const CANVAS_PANEL_MIN_WIDTH = 980;
const IMMERSIVE_CANVAS_PANEL_WIDTH = 1180;
const BROWSER_MODE_PANEL_WIDTH = 1040;
const BROWSER_MODE_TEACH_PANEL_WIDTH = 1260;
const BROWSER_MODE_MIN_PANEL_WIDTH = 820;
const BROWSER_MODE_TEACH_MIN_PANEL_WIDTH = 940;
const IMMERSIVE_CENTER_COL_MIN_WIDTH = 480;
// Canvas modes may be large, but must never reduce the live chat column to a
// sliver. The workspace tree belongs inside Canvas and should consume Canvas
// room before it is allowed to displace the chat surface.
const CANVAS_CHAT_COLUMN_MIN_WIDTH = 400;
const CANVAS_CHAT_COLUMN_HARD_MIN_WIDTH = 380;
const NATIVE_BROWSER_RESIZE_HANDLE_GUTTER = 8;
const CREATIVE_MODE_PANEL_WIDTH = IMMERSIVE_CANVAS_PANEL_WIDTH;
let creativeModeSavedPanelWidth = null;
let canvasPreviewSavedPanelWidth = null;
let browserCanvasPanelWidthMode = '';
let rightPanelCanvasSavedScrollTop = 0;

const CANVAS_PREVIEW_DEVICES = {
  responsive: { label: 'Responsive', width: 0, height: 0, icon: 'solar:monitor-bold-duotone' },
  iphone15: { label: 'iPhone', width: 393, height: 852, icon: 'solar:smartphone-bold-duotone' },
  iphoneSE: { label: 'SE', width: 375, height: 667, icon: 'solar:smartphone-bold-duotone' },
  pixel8: { label: 'Pixel', width: 412, height: 915, icon: 'solar:smartphone-bold-duotone' },
};

const BROWSER_INTERACTION_META = {
  agent: {
    label: 'Agent',
    copy: 'Agent mode leaves the browser fully in Prometheus\' hands while the browser surface follows the active page and tool activity.',
  },
  copilot: {
    label: 'Co-pilot',
    copy: 'Co-pilot mode is the handoff lane. The canvas is ready for browser control state, and we can now hang real page input forwarding on top of it next.',
  },
  teach: {
    label: 'Teach',
    copy: 'Teach mode is where browser learning will live. This surface is now in place for guided DOM capture and reusable browser memory.',
  },
};

function normalizeBrowserTeachPhase(phase) {
  const value = String(phase || '').trim().toLowerCase();
  if (value === 'recording' || value === 'approval_pending' || value === 'verifying' || value === 'verified') return value;
  return 'idle';
}

function normalizeBrowserTeachRisk(risk) {
  return String(risk || '').trim().toLowerCase() === 'high' ? 'high' : 'none';
}

function createEmptyBrowserTeachSession() {
  return {
    active: false,
    phase: 'idle',
    startedAt: 0,
    completedAt: 0,
    approvalRequestedAt: 0,
    reviewRequestedAt: 0,
    startUrl: '',
    startTitle: '',
    steps: [],
    pendingStep: null,
    pendingSelectionIntent: null,
    executingStepId: '',
    verification: null,
  };
}

function snapshotBrowserTeachStep(step) {
  if (!step || typeof step !== 'object') return null;
  const selection = step.selection && typeof step.selection === 'object'
    ? {
        selector: String(step.selection.selector || '').trim(),
        tagName: String(step.selection.tagName || '').trim(),
        id: String(step.selection.id || '').trim(),
        text: String(step.selection.text || '').trim(),
        bounds: step.selection.bounds || null,
      }
    : null;
  const input = step.input && typeof step.input === 'object' ? { ...step.input } : {};
  const args = step.args && typeof step.args === 'object' ? { ...step.args } : {};
  return {
    id: String(step.id || '').trim(),
    kind: String(step.kind || '').trim(),
    toolName: String(step.toolName || '').trim(),
    title: String(step.title || '').trim(),
    summary: String(step.summary || '').trim(),
    toolPreview: String(step.toolPreview || '').trim(),
    targetName: String(step.targetName || '').trim(),
    risk: normalizeBrowserTeachRisk(step.risk),
    status: String(step.status || '').trim() || 'recorded',
    createdAt: Number(step.createdAt || 0) || 0,
    executedAt: Number(step.executedAt || 0) || 0,
    pageUrl: String(step.pageUrl || '').trim(),
    pageTitle: String(step.pageTitle || '').trim(),
    resultSummary: String(step.resultSummary || '').trim(),
    selection,
    input,
    args,
  };
}

function snapshotBrowserTeachSession(session) {
  const teach = session && typeof session === 'object' ? session : createEmptyBrowserTeachSession();
  return {
    active: teach.active === true,
    phase: normalizeBrowserTeachPhase(teach.phase),
    startedAt: Number(teach.startedAt || 0) || 0,
    completedAt: Number(teach.completedAt || 0) || 0,
    approvalRequestedAt: Number(teach.approvalRequestedAt || 0) || 0,
    reviewRequestedAt: Number(teach.reviewRequestedAt || 0) || 0,
    startUrl: String(teach.startUrl || '').trim(),
    startTitle: String(teach.startTitle || '').trim(),
    executingStepId: String(teach.executingStepId || '').trim(),
    steps: Array.isArray(teach.steps)
      ? teach.steps.map((step) => snapshotBrowserTeachStep(step)).filter(Boolean)
      : [],
    pendingStep: snapshotBrowserTeachStep(teach.pendingStep),
    verification: teach.verification && typeof teach.verification === 'object'
      ? {
          status: String(teach.verification.status || '').trim(),
          mode: String(teach.verification.mode || '').trim(),
          boundaryLabel: String(teach.verification.boundaryLabel || '').trim(),
          stopBeforeStep: Number(teach.verification.stopBeforeStep || 0) || 0,
          verifierSessionId: String(teach.verification.verifierSessionId || '').trim(),
          executedCount: Number(teach.verification.executedCount || 0) || 0,
          totalRecordedSteps: Number(teach.verification.totalRecordedSteps || 0) || 0,
          riskyStepIndexes: Array.isArray(teach.verification.riskyStepIndexes)
            ? teach.verification.riskyStepIndexes.map((value) => Number(value || 0) || 0).filter(Boolean)
            : [],
          failedStep: Number(teach.verification.failedStep || 0) || 0,
          failureSummary: String(teach.verification.failureSummary || '').trim(),
          finalUrl: String(teach.verification.finalUrl || '').trim(),
          finalTitle: String(teach.verification.finalTitle || '').trim(),
          startedAt: Number(teach.verification.startedAt || 0) || 0,
          completedAt: Number(teach.verification.completedAt || 0) || 0,
        }
      : null,
  };
}

function restoreBrowserTeachSessionState(saved) {
  const teach = createEmptyBrowserTeachSession();
  const restored = saved && typeof saved === 'object' ? saved : {};
  teach.active = restored.active === true;
  teach.phase = normalizeBrowserTeachPhase(restored.phase);
  teach.startedAt = Number(restored.startedAt || 0) || 0;
  teach.completedAt = Number(restored.completedAt || 0) || 0;
  teach.approvalRequestedAt = Number(restored.approvalRequestedAt || 0) || 0;
  teach.reviewRequestedAt = Number(restored.reviewRequestedAt || 0) || 0;
  teach.startUrl = String(restored.startUrl || '').trim();
  teach.startTitle = String(restored.startTitle || '').trim();
  teach.executingStepId = String(restored.executingStepId || '').trim();
  teach.steps = Array.isArray(restored.steps)
    ? restored.steps.map((step) => snapshotBrowserTeachStep(step)).filter(Boolean)
    : [];
  teach.pendingStep = snapshotBrowserTeachStep(restored.pendingStep);
  teach.verification = restored.verification && typeof restored.verification === 'object'
    ? {
        status: String(restored.verification.status || '').trim(),
        mode: String(restored.verification.mode || '').trim(),
        boundaryLabel: String(restored.verification.boundaryLabel || '').trim(),
        stopBeforeStep: Number(restored.verification.stopBeforeStep || 0) || 0,
        verifierSessionId: String(restored.verification.verifierSessionId || '').trim(),
        executedCount: Number(restored.verification.executedCount || 0) || 0,
        totalRecordedSteps: Number(restored.verification.totalRecordedSteps || 0) || 0,
        riskyStepIndexes: Array.isArray(restored.verification.riskyStepIndexes)
          ? restored.verification.riskyStepIndexes.map((value) => Number(value || 0) || 0).filter(Boolean)
          : [],
        failedStep: Number(restored.verification.failedStep || 0) || 0,
        failureSummary: String(restored.verification.failureSummary || '').trim(),
        finalUrl: String(restored.verification.finalUrl || '').trim(),
        finalTitle: String(restored.verification.finalTitle || '').trim(),
        startedAt: Number(restored.verification.startedAt || 0) || 0,
        completedAt: Number(restored.verification.completedAt || 0) || 0,
      }
    : null;
  teach.pendingSelectionIntent = null;
  if (!teach.active || teach.phase === 'idle') {
    teach.active = false;
    teach.phase = 'idle';
    teach.executingStepId = '';
    teach.pendingStep = null;
  }
  return teach;
}

function syncBrowserTeachSessionToBackend() {
  const sessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
  if (!sessionId) return;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  const teach = snapshotBrowserTeachSession(getBrowserTeachSession());
  wsSend({
    type: 'browser:teach:sync',
    sessionId,
    teachSession: teach.active ? teach : { active: false, phase: 'idle' },
  });
}

function getViewportBoundPanelWidth(desiredWidth, minimumWidth = 760, options = {}) {
  if (typeof window === 'undefined') return Math.max(minimumWidth, desiredWidth);
  const viewportWidth = Math.max(0, Number(window.innerWidth) || 0);
  const reservedWidth = Math.max(0, Number(options.reservedWidth || 0) || 0);
  const maxViewportRatio = Math.max(0.1, Math.min(1, Number(options.maxViewportRatio || 1) || 1));
  const viewportReserveCap = viewportWidth > 0 ? viewportWidth - reservedWidth : desiredWidth;
  const ratioCap = viewportWidth > 0 ? viewportWidth * maxViewportRatio : desiredWidth;
  const rawMaxWidth = Math.min(viewportReserveCap, ratioCap, viewportWidth > 0 ? viewportWidth - 40 : desiredWidth);
  const maxWidth = viewportWidth > 0 ? Math.max(minimumWidth, rawMaxWidth) : desiredWidth;
  return Math.max(minimumWidth, Math.min(desiredWidth, maxWidth));
}

function getCanvasPanelMaximumWidth() {
  const workspace = document.getElementById('workspace');
  const workspaceWidth = workspace?.getBoundingClientRect().width || workspace?.clientWidth || 0;
  if (!workspaceWidth) return Number.POSITIVE_INFINITY;
  // Keep a useful chat column on ordinary desktop sizes, while still allowing
  // Canvas to remain usable on narrower windows.
  const reservedChatWidth = Math.min(
    CANVAS_CHAT_COLUMN_MIN_WIDTH,
    Math.max(CANVAS_CHAT_COLUMN_HARD_MIN_WIDTH, Math.floor(workspaceWidth * 0.46)),
  );
  return Math.max(360, Math.floor(workspaceWidth - reservedChatWidth));
}

function clampCanvasPanelToWorkspace() {
  const rightPanel = document.getElementById('right-panel');
  if (!rightPanel || !rightPanel.classList.contains('canvas-open')) return false;
  const maximumWidth = getCanvasPanelMaximumWidth();
  const currentWidth = rightPanel.getBoundingClientRect().width || rightPanel.offsetWidth || 0;
  if (!Number.isFinite(maximumWidth) || !currentWidth || currentWidth <= maximumWidth) return false;
  setRightPanelWidth(maximumWidth, { minimumWidth: 1, preserveChatColumn: true });
  return true;
}

function setRightPanelWidth(width, options = {}) {
  const rightPanel = document.getElementById('right-panel');
  if (!rightPanel) return;
  let boundedWidth = getViewportBoundPanelWidth(width, options.minimumWidth || 760, options);
  const canvasLikeSurface = rightPanel.classList.contains('canvas-open')
    || !!normalizeCreativeMode(window.currentCreativeMode);
  if (options.preserveChatColumn !== false && canvasLikeSurface) {
    boundedWidth = Math.min(boundedWidth, getCanvasPanelMaximumWidth());
  }
  rightPanel.style.width = `${boundedWidth}px`;
  rightPanel.style.minWidth = `${boundedWidth}px`;
  if (options.lockMax) rightPanel.style.maxWidth = `${boundedWidth}px`;
  else rightPanel.style.removeProperty('max-width');
}

function resetRightPanelWidth() {
  const rightPanel = document.getElementById('right-panel');
  if (!rightPanel) return;
  rightPanel.style.removeProperty('width');
  rightPanel.style.removeProperty('min-width');
  rightPanel.style.removeProperty('max-width');
}

function getBrowserCanvasPanelWidthTarget(mode = getBrowserCanvasState().interactionMode) {
  const normalizedMode = normalizeBrowserInteractionMode(mode);
  const isTeachMode = normalizedMode === 'teach';
  // Browser is a Canvas surface, so it should open at the same useful default
  // width and use the same workspace maximum instead of the old half-window cap.
  // Teach may still grow further by drag when its workflow rail is visible.
  return Math.max(
    CANVAS_PANEL_MIN_WIDTH,
    isTeachMode ? BROWSER_MODE_TEACH_MIN_PANEL_WIDTH : BROWSER_MODE_MIN_PANEL_WIDTH,
  );
}

function applyBrowserCanvasPanelDefault(options = {}) {
  const rightPanel = document.getElementById('right-panel');
  if (!rightPanel || !canvasOpen || !isBrowserCanvasSurfaceActive() || isCreativeModeLocked()) return false;
  const mode = normalizeBrowserInteractionMode(getBrowserCanvasState().interactionMode);
  if (options.force !== true && browserCanvasPanelWidthMode === mode) return false;
  browserCanvasPanelWidthMode = mode;
  setRightPanelWidth(getBrowserCanvasPanelWidthTarget(mode), {
    minimumWidth: CANVAS_PANEL_MIN_WIDTH,
    maxViewportRatio: 1,
    preserveChatColumn: true,
  });
  return true;
}

function restoreCanvasPreviewSavedPanelWidth(rightPanel = document.getElementById('right-panel')) {
  if (!rightPanel || canvasPreviewSavedPanelWidth === null) return false;
  if (canvasPreviewSavedPanelWidth && !/^0px$/i.test(canvasPreviewSavedPanelWidth)) {
    rightPanel.style.width = canvasPreviewSavedPanelWidth;
    rightPanel.style.minWidth = canvasPreviewSavedPanelWidth;
  } else {
    rightPanel.style.removeProperty('width');
    rightPanel.style.removeProperty('min-width');
  }
  rightPanel.style.removeProperty('max-width');
  canvasPreviewSavedPanelWidth = null;
  return true;
}

function normalizeCreativeMode(mode) {
  const key = String(mode || '').trim().toLowerCase();
  if (key === 'canvas') return 'image';
  return Object.prototype.hasOwnProperty.call(CREATIVE_MODE_META, key) ? key : null;
}

function getCreativeModeMeta(mode) {
  const key = normalizeCreativeMode(mode);
  return key ? CREATIVE_MODE_META[key] : null;
}

function getActiveCanvasTab() {
  return canvasTabs.find((tab) => tab.id === activeCanvasTabId) || null;
}

function isPreviewLikeCanvasTab(tab) {
  if (!tab) return false;
  if (tab.isImage || tab.isBinary) return true;
  return String(tab.mode || '').toLowerCase() === 'preview';
}

function getBrowserCanvasState() {
  if (!window.browserCanvasState || typeof window.browserCanvasState !== 'object') {
    window.browserCanvasState = {
      surface: 'files',
      interactionMode: 'agent',
      controlCaptured: false,
      controlOwner: 'agent',
      streamActive: false,
      streamTransport: '',
      streamFocus: 'passive',
      streamStatus: '',
      streamLastFrameAt: 0,
      loading: false,
      lastError: '',
      frameFormat: 'png',
      active: false,
      browserDesignMode: false,
      browserDesignSelectMode: false,
      browserDesignSelections: [],
       profileKind: '',
       inhouseProfile: 'main',
       browserTarget: '',
      profileLabel: '',
      browserSessions: {},
      nativeTabs: [],
      activeNativeTabId: '',
      sessionId: '',
      followSessionId: '',
      url: '',
      title: '',
      lastRestorableUrl: '',
      lastRestorableTitle: '',
      lastTool: '',
      statusLabel: 'Browser idle',
      frameBase64: '',
      frameBlobUrl: '',
      frameWidth: 0,
      frameHeight: 0,
      frameBitmapWidth: 0,
      frameBitmapHeight: 0,
      frameViewportWidth: 0,
      frameViewportHeight: 0,
      frameScrollX: 0,
      frameScrollY: 0,
      frameDevicePixelRatio: 1,
      selectedElement: null,
      hoverElement: null,
      interactableMap: null,
      interactableMapRequestedAt: 0,
      interactableMapRequestId: '',
      namedElements: [],
      itemRoots: [],
      extractionSchemas: [],
      elementNameDraft: '',
      elementNameDraftKey: '',
      transientHighlight: null,
      knowledgeSite: '',
      knowledgeRequestedFor: '',
      selectionPending: false,
      teachSession: createEmptyBrowserTeachSession(),
      updatedAt: 0,
    };
  }
  return window.browserCanvasState;
}

function snapshotBrowserCanvasSessionState(state = getBrowserCanvasState()) {
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  const snapshotSessionId = String(state.sessionId || '').trim();
  const belongsToPrimarySession = !primarySessionId || snapshotSessionId === primarySessionId;
  const browserSessions = {};
  Object.entries(getBrowserSessionRegistry(state)).forEach(([sessionId, record]) => {
    if (!record || typeof record !== 'object') return;
    // Browser records live in a process-wide registry, but the canvas snapshot
    // is persisted per chat. Never copy another chat's agents into this chat's
    // durable browser state.
    if (primarySessionId && String(sessionId || '').trim() !== primarySessionId) return;
    const { frameBase64, ...rest } = record;
    browserSessions[sessionId] = {
      ...rest,
      frameBase64: '',
    };
  });
  return {
    surface: String(state.surface || 'files') === 'browser' ? 'browser' : 'files',
    interactionMode: normalizeBrowserInteractionMode(state.interactionMode),
    active: belongsToPrimarySession && state.active === true,
    browserDesignMode: state.browserDesignMode === true,
    browserDesignSelectMode: state.browserDesignSelectMode === true,
    browserDesignSelections: Array.isArray(state.browserDesignSelections)
      ? state.browserDesignSelections.slice(0, 24).map((selection) => cloneBrowserDesignSelection(selection)).filter(Boolean)
      : [],
    profileKind: String(state.profileKind || '').trim(),
    inhouseProfile: String(state.inhouseProfile || '').trim() || 'main',
    browserTarget: String(state.browserTarget || '').trim(),
     profileLabel: String(state.profileLabel || '').trim(),
     browserSessions,
     nativeTabs: normalizeNativeBrowserTabs(state.nativeTabs),
     activeNativeTabId: String(state.activeNativeTabId || '').trim(),
     sessionId: belongsToPrimarySession ? snapshotSessionId : '',
    followSessionId: String(state.followSessionId || '').trim(),
    url: belongsToPrimarySession ? String(state.url || '').trim() : '',
    title: belongsToPrimarySession ? String(state.title || '').trim() : '',
    lastRestorableUrl: belongsToPrimarySession ? String(state.lastRestorableUrl || '').trim() : '',
    lastRestorableTitle: belongsToPrimarySession ? String(state.lastRestorableTitle || '').trim() : '',
    lastTool: belongsToPrimarySession ? String(state.lastTool || '').trim() : '',
    statusLabel: belongsToPrimarySession ? String(state.statusLabel || '').trim() : '',
    selectedElement: cloneBrowserDesignSelection(state.selectedElement),
    namedElements: Array.isArray(state.namedElements)
      ? state.namedElements.map((entry) => ({
          name: String(entry?.name || '').trim(),
          selector: String(entry?.selector || '').trim(),
          tagName: String(entry?.tagName || '').trim(),
          id: String(entry?.id || '').trim(),
          text: String(entry?.text || '').trim(),
          url: String(entry?.url || '').trim(),
          savedAt: Number(entry?.savedAt || 0) || 0,
        })).filter((entry) => entry.name)
      : [],
    itemRoots: Array.isArray(state.itemRoots)
      ? state.itemRoots.map((entry) => ({
          name: String(entry?.name || '').trim(),
          selector: String(entry?.selector || '').trim(),
          tagName: String(entry?.tagName || '').trim(),
          id: String(entry?.id || '').trim(),
          text: String(entry?.text || '').trim(),
          url: String(entry?.url || '').trim(),
          savedAt: Number(entry?.savedAt || 0) || 0,
        })).filter((entry) => entry.name)
      : [],
    extractionSchemas: Array.isArray(state.extractionSchemas)
      ? state.extractionSchemas.map((entry) => ({
          name: String(entry?.name || '').trim(),
          itemRoot: String(entry?.itemRoot || '').trim(),
          containerSelector: String(entry?.containerSelector || '').trim(),
          dedupeKey: String(entry?.dedupeKey || '').trim(),
          limit: Number(entry?.limit || 0) || 0,
          fields: entry?.fields && typeof entry.fields === 'object' ? { ...entry.fields } : {},
          savedAt: Number(entry?.savedAt || 0) || 0,
        })).filter((entry) => entry.name)
      : [],
    knowledgeSite: String(state.knowledgeSite || '').trim(),
    selectionPending: state.selectionPending === true,
    teachSession: snapshotBrowserTeachSession(state.teachSession),
    updatedAt: Number(state.updatedAt || 0) || 0,
  };
}

function restoreBrowserCanvasSessionState(saved) {
  const state = getBrowserCanvasState();
  const restored = saved && typeof saved === 'object' ? saved : {};
  const primarySessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
  const restoredSessionId = String(restored.sessionId || '').trim();
  const savedRegistry = restored.browserSessions && typeof restored.browserSessions === 'object' && !Array.isArray(restored.browserSessions)
    ? restored.browserSessions
    : {};
  const currentRegistry = Object.fromEntries(Object.entries(savedRegistry).filter(([sessionId]) => (
    !primarySessionId || String(sessionId || '').trim() === primarySessionId
  )));
  const hasCurrentSessionState = !primarySessionId
    || restoredSessionId === primarySessionId
    || Object.prototype.hasOwnProperty.call(currentRegistry, primarySessionId);
  state.surface = String(restored.surface || 'files') === 'browser' ? 'browser' : 'files';
  state.interactionMode = normalizeBrowserInteractionMode(restored.interactionMode);
  state.controlCaptured = false;
  state.controlOwner = 'agent';
  state.streamActive = false;
  state.streamTransport = '';
  state.streamFocus = 'passive';
  state.streamStatus = '';
  state.streamLastFrameAt = 0;
  state.frameFormat = 'png';
  state.active = hasCurrentSessionState && restored.active === true;
  state.browserDesignMode = restored.browserDesignMode === true;
  state.browserDesignSelectMode = restored.browserDesignSelectMode === true;
  state.browserDesignSelections = Array.isArray(restored.browserDesignSelections)
    ? restored.browserDesignSelections.slice(0, 24).map((selection) => cloneBrowserDesignSelection(selection)).filter(Boolean)
    : [];
   state.browserSessions = currentRegistry && typeof currentRegistry === 'object'
    ? Object.fromEntries(Object.entries(currentRegistry).map(([sessionId, record]) => {
        const clean = record && typeof record === 'object' ? { ...record } : {};
        clean.frameBase64 = '';
        return [sessionId, clean];
      }))
     : {};
   state.nativeTabs = normalizeNativeBrowserTabs(restored.nativeTabs);
   state.activeNativeTabId = String(restored.activeNativeTabId || '').trim();
   state.sessionId = hasCurrentSessionState
     ? String(primarySessionId || restoredSessionId || '').trim()
     : '';
  const restoredFollowSessionId = String(restored.followSessionId || '').trim();
  state.followSessionId = hasCurrentSessionState && currentRegistry[restoredFollowSessionId]
    ? restoredFollowSessionId
    : '';
  state.url = hasCurrentSessionState ? String(restored.url || '').trim() : '';
  state.title = hasCurrentSessionState ? String(restored.title || '').trim() : '';
  state.lastRestorableUrl = hasCurrentSessionState ? String(restored.lastRestorableUrl || '').trim() : '';
  state.lastRestorableTitle = hasCurrentSessionState ? String(restored.lastRestorableTitle || '').trim() : '';
  state.lastTool = hasCurrentSessionState ? String(restored.lastTool || '').trim() : '';
  state.statusLabel = hasCurrentSessionState
    ? (String(restored.statusLabel || '').trim() || (state.active ? 'Browser active' : 'Browser idle'))
    : 'Browser idle';
  state.agentCursor = null;
  state.selectedElement = cloneBrowserDesignSelection(restored.selectedElement);
  state.namedElements = Array.isArray(restored.namedElements)
    ? restored.namedElements.map((entry) => ({
        name: String(entry?.name || '').trim(),
        selector: String(entry?.selector || '').trim(),
        tagName: String(entry?.tagName || '').trim(),
        id: String(entry?.id || '').trim(),
        text: String(entry?.text || '').trim(),
        url: String(entry?.url || '').trim(),
        savedAt: Number(entry?.savedAt || 0) || 0,
      })).filter((entry) => entry.name)
    : [];
  state.itemRoots = Array.isArray(restored.itemRoots)
    ? restored.itemRoots.map((entry) => ({
        name: String(entry?.name || '').trim(),
        selector: String(entry?.selector || '').trim(),
        tagName: String(entry?.tagName || '').trim(),
        id: String(entry?.id || '').trim(),
        text: String(entry?.text || '').trim(),
        url: String(entry?.url || '').trim(),
        savedAt: Number(entry?.savedAt || 0) || 0,
      })).filter((entry) => entry.name)
    : [];
  state.extractionSchemas = Array.isArray(restored.extractionSchemas)
    ? restored.extractionSchemas.map((entry) => ({
        name: String(entry?.name || '').trim(),
        itemRoot: String(entry?.itemRoot || '').trim(),
        containerSelector: String(entry?.containerSelector || '').trim(),
        dedupeKey: String(entry?.dedupeKey || '').trim(),
        limit: Number(entry?.limit || 0) || 0,
        fields: entry?.fields && typeof entry.fields === 'object' ? { ...entry.fields } : {},
        savedAt: Number(entry?.savedAt || 0) || 0,
      })).filter((entry) => entry.name)
    : [];
  state.knowledgeSite = String(restored.knowledgeSite || '').trim();
  state.knowledgeRequestedFor = '';
  state.elementNameDraft = '';
  state.elementNameDraftKey = '';
  state.transientHighlight = null;
  state.selectionPending = false;
  state.teachSession = restoreBrowserTeachSessionState(restored.teachSession);
  state.updatedAt = Number(restored.updatedAt || 0) || 0;
  state.frameBase64 = '';
  state.frameWidth = 0;
  state.frameHeight = 0;
  // Blob URLs are only valid for this page lifetime — drop any in-memory ref and
  // revoke whatever the previous run held.
  if (state.frameBlobUrl) { try { URL.revokeObjectURL(state.frameBlobUrl); } catch {} }
  state.frameBlobUrl = '';
  state.frameBitmapWidth = 0;
  state.frameBitmapHeight = 0;
  state.frameViewportWidth = 0;
  state.frameViewportHeight = 0;
  state.frameScrollX = 0;
  state.frameScrollY = 0;
  state.frameDevicePixelRatio = 1;
  state.hoverElement = null;
  state.interactableMap = null;
  state.interactableMapRequestedAt = 0;
  state.interactableMapRequestId = '';
  return state;
}

function normalizeBrowserInteractionMode(mode) {
  const key = String(mode || '').trim().toLowerCase();
  if (key === 'review') return 'agent';
  return Object.prototype.hasOwnProperty.call(BROWSER_INTERACTION_META, key) ? key : 'agent';
}

function getBrowserInteractionMeta(mode) {
  return BROWSER_INTERACTION_META[normalizeBrowserInteractionMode(mode)] || BROWSER_INTERACTION_META.agent;
}

function getBrowserTeachSession(state = getBrowserCanvasState()) {
  if (!state.teachSession || typeof state.teachSession !== 'object') {
    state.teachSession = createEmptyBrowserTeachSession();
  }
  return state.teachSession;
}

function hasActiveBrowserTeachSession(state = getBrowserCanvasState()) {
  const teach = getBrowserTeachSession(state);
  return teach.active === true && normalizeBrowserTeachPhase(teach.phase) !== 'idle';
}

function isBrowserTeachRecording(state = getBrowserCanvasState()) {
  const teach = getBrowserTeachSession(state);
  return teach.active === true && normalizeBrowserTeachPhase(teach.phase) === 'recording';
}

function isBrowserTeachAwaitingApproval(state = getBrowserCanvasState()) {
  const teach = getBrowserTeachSession(state);
  return teach.active === true && normalizeBrowserTeachPhase(teach.phase) === 'approval_pending';
}

function isBrowserTeachVerified(state = getBrowserCanvasState()) {
  const teach = getBrowserTeachSession(state);
  return teach.active === true && normalizeBrowserTeachPhase(teach.phase) === 'verified' && !!teach.verification;
}

function buildBrowserTeachStepId() {
  return `teach_step_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function getBrowserTeachSelectionKey(selection) {
  if (!selection || typeof selection !== 'object') return '';
  return [
    String(selection.selector || '').trim(),
    String(selection.id || '').trim(),
    String(selection.tagName || '').trim(),
    String(selection.text || '').trim().slice(0, 80),
  ].join('|');
}

function cloneBrowserTeachSelection(selection) {
  if (!selection || typeof selection !== 'object') return null;
  return {
    selector: String(selection.selector || '').trim(),
    tagName: String(selection.tagName || '').trim(),
    id: String(selection.id || '').trim(),
    text: String(selection.text || '').trim(),
    bounds: selection.bounds || null,
  };
}

function matchNamedBrowserElementForSelection(selection, state = getBrowserCanvasState()) {
  if (!selection || typeof selection !== 'object') return null;
  const selector = String(selection.selector || '').trim();
  const id = String(selection.id || '').trim();
  const selectionKey = getBrowserTeachSelectionKey(selection);
  const items = Array.isArray(state.namedElements) ? state.namedElements : [];
  return items.find((entry) => {
    const entrySelector = String(entry?.selector || '').trim();
    const entryId = String(entry?.id || '').trim();
    if (selector && entrySelector && selector === entrySelector) return true;
    if (id && entryId && id === entryId) return true;
    return getBrowserTeachSelectionKey(entry) === selectionKey;
  }) || null;
}

function resolveBrowserTeachTargetName(selection, state = getBrowserCanvasState()) {
  const selectedKey = getSelectedBrowserElementKey(selection);
  if (selectedKey && selectedKey === state.elementNameDraftKey) {
    const draft = String(state.elementNameDraft || '').trim();
    if (draft) return draft;
  }
  const matched = matchNamedBrowserElementForSelection(selection, state);
  return String(matched?.name || '').trim();
}

function summarizeBrowserTeachTarget(selection, state = getBrowserCanvasState()) {
  const targetName = resolveBrowserTeachTargetName(selection, state);
  if (targetName) return targetName;
  const text = String(selection?.text || '').replace(/\s+/g, ' ').trim();
  if (text) return text.slice(0, 72);
  const id = String(selection?.id || '').trim();
  if (id) return id;
  const tagName = String(selection?.tagName || '').trim();
  return tagName || 'selected element';
}

function classifyBrowserTeachRisk(text) {
  const source = String(text || '').trim().toLowerCase();
  if (!source) return 'none';
  return /\b(post|tweet|send|publish|submit|delete|remove|archive|buy|purchase|checkout|pay|save(?: changes)?|confirm|place order|apply|update settings)\b/i.test(source)
    ? 'high'
    : 'none';
}

function browserTeachStepToolPreview(step) {
  if (!step || typeof step !== 'object') return '';
  const args = step.args && typeof step.args === 'object' ? step.args : {};
  switch (String(step.toolName || '').trim()) {
    case 'browser_click':
      return `browser_click(${JSON.stringify(args)})`;
    case 'browser_fill':
      return `browser_fill(${JSON.stringify(args)})`;
    case 'browser_type':
      return `browser_type(${JSON.stringify(args)})`;
    case 'browser_press_key':
      return `browser_press_key(${JSON.stringify(args)})`;
    case 'browser_scroll':
      return `browser_scroll(${JSON.stringify(args)})`;
    default:
      return `${String(step.toolName || 'browser_step')}(${JSON.stringify(args)})`;
  }
}

function isEditableBrowserTeachSelection(selection) {
  const tagName = String(selection?.tagName || '').trim().toLowerCase();
  if (tagName === 'input' || tagName === 'textarea' || tagName === 'select') return true;
  const selector = String(selection?.selector || '').trim().toLowerCase();
  return selector.includes('contenteditable');
}

function createBrowserTeachClickStep(selection, point, state = getBrowserCanvasState()) {
  const clonedSelection = cloneBrowserTeachSelection(selection);
  const targetLabel = summarizeBrowserTeachTarget(clonedSelection, state);
  const targetName = resolveBrowserTeachTargetName(clonedSelection, state);
  const args = targetName
    ? { element: targetName }
    : { selector: String(clonedSelection?.selector || '').trim() };
  const summary = `Click ${targetLabel}`;
  return {
    id: buildBrowserTeachStepId(),
    kind: 'click',
    toolName: 'browser_click',
    title: summary,
    summary,
    toolPreview: browserTeachStepToolPreview({ toolName: 'browser_click', args }),
    targetName,
    risk: classifyBrowserTeachRisk(`${targetLabel} ${clonedSelection?.text || ''}`),
    status: 'pending',
    createdAt: Date.now(),
    executedAt: 0,
    pageUrl: String(state.url || '').trim(),
    pageTitle: String(state.title || '').trim(),
    resultSummary: '',
    selection: clonedSelection,
    input: {
      action: 'click',
      x: Number(point?.x || 0),
      y: Number(point?.y || 0),
      button: 'left',
    },
    args,
  };
}

function createBrowserTeachTextStep(text, state = getBrowserCanvasState()) {
  const value = String(text || '');
  const selection = cloneBrowserTeachSelection(state.selectedElement);
  const targetLabel = summarizeBrowserTeachTarget(selection, state);
  const targetName = resolveBrowserTeachTargetName(selection, state);
  const toolName = selection ? 'browser_fill' : 'browser_type';
  const args = toolName === 'browser_fill'
    ? (targetName ? { element: targetName, text: value } : { selector: String(selection?.selector || '').trim(), text: value })
    : { text: value };
  const summary = toolName === 'browser_fill'
    ? `Type into ${targetLabel}`
    : `Type "${value.replace(/\s+/g, ' ').trim().slice(0, 48)}"`;
  return {
    id: buildBrowserTeachStepId(),
    kind: toolName === 'browser_fill' ? 'fill' : 'text',
    toolName,
    title: summary,
    summary,
    toolPreview: browserTeachStepToolPreview({ toolName, args }),
    targetName,
    risk: 'none',
    status: 'pending',
    createdAt: Date.now(),
    executedAt: 0,
    pageUrl: String(state.url || '').trim(),
    pageTitle: String(state.title || '').trim(),
    resultSummary: '',
    selection,
    input: {
      action: 'text',
      text: value,
    },
    args,
  };
}

function createBrowserTeachKeyStep(key, modifiers = {}, state = getBrowserCanvasState()) {
  const comboParts = [
    modifiers.ctrlKey ? 'Control' : '',
    modifiers.altKey ? 'Alt' : '',
    modifiers.metaKey ? 'Meta' : '',
    modifiers.shiftKey ? 'Shift' : '',
    String(key || '').trim(),
  ].filter(Boolean);
  const combo = comboParts.join('+');
  const args = { key: combo };
  const summary = `Press ${combo}`;
  return {
    id: buildBrowserTeachStepId(),
    kind: 'key',
    toolName: 'browser_press_key',
    title: summary,
    summary,
    toolPreview: browserTeachStepToolPreview({ toolName: 'browser_press_key', args }),
    targetName: '',
    risk: classifyBrowserTeachRisk(combo),
    status: 'pending',
    createdAt: Date.now(),
    executedAt: 0,
    pageUrl: String(state.url || '').trim(),
    pageTitle: String(state.title || '').trim(),
    resultSummary: '',
    selection: cloneBrowserTeachSelection(state.selectedElement),
    input: {
      action: 'key',
      key: String(key || '').trim(),
      ctrlKey: modifiers.ctrlKey === true,
      altKey: modifiers.altKey === true,
      metaKey: modifiers.metaKey === true,
      shiftKey: modifiers.shiftKey === true,
    },
    args,
  };
}

function createBrowserTeachScrollStep(point, deltaX, deltaY, state = getBrowserCanvasState()) {
  const verticalMagnitude = Math.abs(Number(deltaY || 0));
  const horizontalMagnitude = Math.abs(Number(deltaX || 0));
  const direction = verticalMagnitude >= horizontalMagnitude
    ? (Number(deltaY || 0) < 0 ? 'up' : 'down')
    : (Number(deltaX || 0) < 0 ? 'left' : 'right');
  const multiplier = Math.max(1, Math.min(6, Math.round(Math.max(verticalMagnitude, horizontalMagnitude) / 560) || 1));
  const args = {
    direction: direction === 'up' ? 'up' : 'down',
    multiplier,
  };
  const summary = direction === 'up' || direction === 'down'
    ? `Scroll ${direction}`
    : `Scroll ${direction === 'left' ? 'left' : 'right'}`;
  return {
    id: buildBrowserTeachStepId(),
    kind: 'scroll',
    toolName: 'browser_scroll',
    title: summary,
    summary,
    toolPreview: browserTeachStepToolPreview({ toolName: 'browser_scroll', args }),
    targetName: '',
    risk: 'none',
    status: 'pending',
    createdAt: Date.now(),
    executedAt: 0,
    pageUrl: String(state.url || '').trim(),
    pageTitle: String(state.title || '').trim(),
    resultSummary: '',
    selection: cloneBrowserTeachSelection(state.selectedElement),
    input: {
      action: 'wheel',
      x: Number(point?.x || 0),
      y: Number(point?.y || 0),
      deltaX: Number(deltaX || 0),
      deltaY: Number(deltaY || 0),
    },
    args,
  };
}

function refreshBrowserTeachStepMetadata(step, state = getBrowserCanvasState()) {
  if (!step || typeof step !== 'object') return step;
  const next = { ...step };
  if (next.selection) {
    next.selection = cloneBrowserTeachSelection(next.selection);
  }
  if (next.kind === 'click' && next.selection) {
    const targetLabel = summarizeBrowserTeachTarget(next.selection, state);
    next.targetName = resolveBrowserTeachTargetName(next.selection, state);
    next.args = next.targetName ? { element: next.targetName } : { selector: String(next.selection.selector || '').trim() };
    next.summary = `Click ${targetLabel}`;
    next.title = next.summary;
    next.risk = classifyBrowserTeachRisk(`${targetLabel} ${next.selection.text || ''}`);
  } else if ((next.kind === 'fill' || next.kind === 'text') && next.input?.text != null) {
    const text = String(next.input.text || '');
    if (next.selection) {
      const targetLabel = summarizeBrowserTeachTarget(next.selection, state);
      next.targetName = resolveBrowserTeachTargetName(next.selection, state);
      next.toolName = 'browser_fill';
      next.args = next.targetName ? { element: next.targetName, text } : { selector: String(next.selection.selector || '').trim(), text };
      next.summary = `Type into ${targetLabel}`;
    } else {
      next.toolName = 'browser_type';
      next.args = { text };
      next.summary = `Type "${text.replace(/\s+/g, ' ').trim().slice(0, 48)}"`;
    }
    next.title = next.summary;
    next.risk = 'none';
  } else if (next.kind === 'scroll') {
    const deltaX = Number(next.input?.deltaX || 0);
    const deltaY = Number(next.input?.deltaY || 0);
    const rebuilt = createBrowserTeachScrollStep({ x: next.input?.x, y: next.input?.y }, deltaX, deltaY, state);
    next.summary = rebuilt.summary;
    next.title = rebuilt.title;
    next.args = rebuilt.args;
  } else if (next.kind === 'key') {
    next.summary = next.title || next.summary || 'Press key';
  }
  next.toolPreview = browserTeachStepToolPreview(next);
  return next;
}

function isBrowserCanvasSurfaceActive() {
  return String(getBrowserCanvasState().surface || 'files') === 'browser';
}

function isBrowserDesignMode(state = getBrowserCanvasState()) {
  return isBrowserCanvasSurfaceActive() && state?.browserDesignMode === true;
}

function cloneBrowserDesignSelection(selection) {
  if (!selection || typeof selection !== 'object') return null;
  return {
    selector: String(selection.selector || '').trim(),
    pack: selection.pack && typeof selection.pack === 'object' ? { ...selection.pack } : (selection.pack || null),
    tagName: String(selection.tagName || '').trim(),
    id: String(selection.id || '').trim(),
    role: String(selection.role || '').trim(),
    classList: Array.isArray(selection.classList) ? selection.classList.map((value) => String(value || '').trim()).filter(Boolean).slice(0, 24) : [],
    text: String(selection.text || '').trim().slice(0, 1200),
    htmlSnippet: String(selection.htmlSnippet || '').trim().slice(0, 4000),
    bounds: selection.bounds && typeof selection.bounds === 'object' ? { ...selection.bounds } : null,
    liveBounds: selection.liveBounds && typeof selection.liveBounds === 'object' ? { ...selection.liveBounds } : null,
    viewport: selection.viewport && typeof selection.viewport === 'object' ? { ...selection.viewport } : null,
    url: String(selection.url || '').trim(),
    title: String(selection.title || '').trim(),
  };
}

function getChatHighlightSessionId(sessionId = '') {
  return String(sessionId || window.activeChatSessionId || window.agentSessionId || 'default').trim() || 'default';
}

function normalizeChatHighlightedTextContext(value, fallback = {}) {
  const source = value && typeof value === 'object' ? value : fallback;
  const text = String(source?.text || value || '').replace(/\s+/g, ' ').trim().slice(0, 2400);
  if (!text) return null;
  return {
    text,
    sourceRole: String(source?.sourceRole || '').trim().toLowerCase(),
    messageIndex: Number.isInteger(source?.messageIndex) ? source.messageIndex : null,
    createdAt: Number(source?.createdAt || Date.now()) || Date.now(),
  };
}

function getActiveChatHighlightedTextContext(sessionId = window.activeChatSessionId) {
  return chatHighlightedTextContexts.get(getChatHighlightSessionId(sessionId)) || null;
}

function setChatHighlightedTextContext(text, metadata = {}) {
  const context = normalizeChatHighlightedTextContext({ text, ...metadata });
  const sessionId = getChatHighlightSessionId(metadata.sessionId);
  if (!context) {
    chatHighlightedTextContexts.delete(sessionId);
  } else {
    chatHighlightedTextContexts.set(sessionId, context);
  }
  updateDesignSelectionChip();
  return context;
}

function clearChatHighlightedTextContext(sessionId = window.activeChatSessionId) {
  chatHighlightedTextContexts.delete(getChatHighlightSessionId(sessionId));
  updateDesignSelectionChip();
}

function clearHighlightedTextAnnotation() {
  clearChatHighlightedTextContext();
  hideChatTextSelectionPopover();
}

function highlightedTextToAttachmentPreview(context = getActiveChatHighlightedTextContext()) {
  if (!context?.text) return null;
  return {
    kind: 'text-selection',
    name: 'Annotation',
    ext: 'text',
    previewText: context.text.slice(0, 240),
    text: context.text,
    sourceRole: context.sourceRole || '',
    messageIndex: Number.isInteger(context.messageIndex) ? context.messageIndex : null,
  };
}

function renderHighlightedTextPillMarkup(context = getActiveChatHighlightedTextContext()) {
  if (!context?.text) return '';
  const preview = context.text.length > 68 ? `${context.text.slice(0, 66)}…` : context.text;
  return `<div class="chat-file-pill chat-annotation-pill" title="${escHtml(`Annotation\n\n${context.text}`)}">
    <span class="pill-icon"><iconify-icon icon="solar:quote-up-square-bold-duotone" width="14" height="14"></iconify-icon></span>
    <span class="pill-copy"><strong class="pill-name">Annotation</strong><em class="pill-ext" title="${escHtml(context.text)}">${escHtml(preview)}</em></span>
    <button class="pill-remove" onclick="clearHighlightedTextAnnotation()" title="Remove annotation" aria-label="Remove annotation">&times;</button>
  </div>`;
}

function renderDesignAnnotationPillMarkup(count = 1) {
  const total = Math.max(1, Number(count) || 1);
  const label = total === 1 ? 'Annotation' : `${total} Annotations`;
  return `<div class="chat-file-pill chat-annotation-pill" title="${escHtml(`${label} attached to the next message`)}">
    <span class="pill-icon"><iconify-icon icon="solar:cursor-square-bold-duotone" width="14" height="14"></iconify-icon></span>
    <span class="pill-copy"><strong class="pill-name">${escHtml(label)}</strong></span>
    <button class="pill-remove" onclick="clearDesignSelectionAttachments()" title="Remove ${escHtml(label.toLowerCase())}" aria-label="Remove ${escHtml(label.toLowerCase())}">&times;</button>
  </div>`;
}

function getBrowserDesignAnnotationSelections(state = getBrowserCanvasState()) {
  const selections = [];
  const seen = new Set();
  const add = (selection) => {
    const next = cloneBrowserDesignSelection(selection);
    if (!next) return;
    const key = getBrowserTeachSelectionKey(next);
    if (!key || seen.has(key)) return;
    seen.add(key);
    selections.push(next);
  };
  (Array.isArray(state?.browserDesignSelections) ? state.browserDesignSelections : []).forEach(add);
  if (state?.selectedElement) add(state.selectedElement);
  return selections.slice(-24);
}

function renderBrowserDesignSelectionPillMarkup(selection, index) {
  if (!selection) return '';
  const label = selection.selector
    || (selection.id ? `#${selection.id}` : '')
    || selection.tagName
    || 'element';
  const truncated = label.length > 40 ? `${label.slice(0, 38)}…` : label;
  return `<div class="chat-file-pill chat-annotation-pill" title="${escHtml(`Annotation ${index + 1}\n\n${label}${selection.text ? `\n\n${selection.text}` : ''}`)}">
    <span class="pill-icon"><iconify-icon icon="solar:cursor-square-bold-duotone" width="14" height="14"></iconify-icon></span>
    <span class="pill-copy"><strong class="pill-name">Annotation ${index + 1}</strong><em class="pill-ext">${escHtml(truncated)}</em></span>
    <button class="pill-remove" onclick="removeBrowserDesignSelectionPill(${index})" title="Remove annotation" aria-label="Remove annotation">&times;</button>
  </div>`;
}

function getCurrentChatModeSessionId() {
  return String(window.activeChatSessionId || window.agentSessionId || '').trim();
}

function getBrowserCanvasPrimarySessionId() {
  return String(window.activeChatSessionId || window.agentSessionId || getBrowserCanvasState().sessionId || '').trim();
}

function getBrowserSessionRegistry(state = getBrowserCanvasState()) {
  if (!state.browserSessions || typeof state.browserSessions !== 'object' || Array.isArray(state.browserSessions)) {
    state.browserSessions = {};
  }
  return state.browserSessions;
}

function getBrowserSessionRecord(sessionId, state = getBrowserCanvasState()) {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  return getBrowserSessionRegistry(state)[sid] || null;
}

function getBrowserSessionLabel(record, index = 0) {
  const ownerType = String(record?.browserOwnerType || record?.ownerType || '').trim().toLowerCase();
  const rawLabel = String(record?.browserLabel || record?.label || '').trim();
  if (ownerType === 'background') return `Browser ${Math.max(2, index + 1)}: ${rawLabel || 'Subagent'}`;
  return rawLabel || 'Main Agent';
}

function upsertBrowserSessionRecord(msg, options = {}) {
  const state = getBrowserCanvasState();
  const sid = String(msg?.sessionId || '').trim();
  if (!sid) return null;
  const registry = getBrowserSessionRegistry(state);
  const previous = registry[sid] || {};
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  const ownerType = String(msg?.browserOwnerType || previous.browserOwnerType || (sid === primarySessionId ? 'main' : '') || '').trim().toLowerCase();
  const next = {
    ...previous,
    sessionId: sid,
    browserOwnerType: ownerType || 'main',
    browserOwnerId: String(msg?.browserOwnerId || previous.browserOwnerId || '').trim(),
    browserLabel: String(msg?.browserLabel || previous.browserLabel || (ownerType === 'background' ? 'Subagent' : 'Main Agent')).trim(),
    browserTaskPrompt: String(msg?.browserTaskPrompt || previous.browserTaskPrompt || '').trim(),
    browserSpawnerSessionId: String(msg?.browserSpawnerSessionId || previous.browserSpawnerSessionId || '').trim(),
     profileKind: String(msg?.profileKind || previous.profileKind || '').trim(),
     inhouseProfile: String(msg?.inhouseProfile || previous.inhouseProfile || 'main').trim() || 'main',
     browserTarget: String(msg?.browserTarget || previous.browserTarget || msg?.profileKind || previous.profileKind || '').trim(),
    profileLabel: String(msg?.profileLabel || previous.profileLabel || '').trim(),
    active: typeof msg?.active === 'boolean' ? msg.active === true : previous.active === true,
    url: String(msg?.url || previous.url || '').trim(),
    title: String(msg?.title || previous.title || '').trim(),
    tool: String(msg?.tool || msg?.lastTool || previous.tool || '').trim(),
    statusLabel: String(msg?.statusLabel || previous.statusLabel || '').trim(),
    streamActive: typeof msg?.streamActive === 'boolean' ? msg.streamActive === true : previous.streamActive === true,
    nativeTabs: Array.isArray(msg?.nativeTabs)
      ? normalizeNativeBrowserTabs(msg.nativeTabs)
      : (Array.isArray(previous.nativeTabs) ? normalizeNativeBrowserTabs(previous.nativeTabs) : []),
    activeNativeTabId: String(msg?.activeNativeTabId || previous.activeNativeTabId || '').trim(),
    frameBase64: typeof msg?.frameBase64 === 'string' && msg.frameBase64.trim() ? msg.frameBase64 : previous.frameBase64,
    frameWidth: Number.isFinite(Number(msg?.frameWidth)) ? Number(msg.frameWidth) : (Number(previous.frameWidth) || 0),
    frameHeight: Number.isFinite(Number(msg?.frameHeight)) ? Number(msg.frameHeight) : (Number(previous.frameHeight) || 0),
    frameFormat: String(msg?.frameFormat || previous.frameFormat || 'png').trim().toLowerCase() === 'jpeg' ? 'jpeg' : 'png',
    updatedAt: Number(msg?.timestamp || Date.now()) || Date.now(),
    registeredAt: Number(previous.registeredAt || Date.now()) || Date.now(),
  };
  registry[sid] = next;
  if (options.copyToCanvas === true) {
    state.sessionId = sid;
    state.active = next.active;
    state.url = next.url || state.url;
    state.title = next.title || state.title;
    state.lastTool = next.tool || state.lastTool;
    state.statusLabel = next.statusLabel || state.statusLabel;
    state.streamActive = next.streamActive;
    state.profileKind = next.profileKind || state.profileKind || '';
    state.inhouseProfile = next.inhouseProfile || state.inhouseProfile || 'main';
    state.browserTarget = next.browserTarget || state.browserTarget || '';
    state.profileLabel = next.profileLabel || state.profileLabel || '';
    if (Array.isArray(msg?.nativeTabs)) state.nativeTabs = normalizeNativeBrowserTabs(msg.nativeTabs);
    if (msg?.activeNativeTabId !== undefined) state.activeNativeTabId = next.activeNativeTabId;
     if (next.frameBase64) {
      state.frameBase64 = next.frameBase64;
      state.frameWidth = next.frameWidth;
      state.frameHeight = next.frameHeight;
      state.frameFormat = next.frameFormat;
    }
    state.updatedAt = next.updatedAt;
  }
  return next;
}

function getBrowserCanvasSessionTabs(state = getBrowserCanvasState()) {
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  const registry = getBrowserSessionRegistry(state);
  if (primarySessionId && !registry[primarySessionId]) {
    upsertBrowserSessionRecord({
      sessionId: primarySessionId,
      browserOwnerType: 'main',
      browserLabel: 'Main Agent',
      active: state.active,
      url: state.url,
      title: state.title,
      tool: state.lastTool,
      statusLabel: state.statusLabel,
      frameBase64: state.frameBase64,
      frameWidth: state.frameWidth,
      frameHeight: state.frameHeight,
      frameFormat: state.frameFormat,
      profileKind: state.profileKind,
      browserTarget: state.browserTarget,
      profileLabel: state.profileLabel,
      timestamp: state.updatedAt || Date.now(),
    });
  }
  const records = Object.values(registry)
    .filter((record) => record && record.sessionId)
    .sort((a, b) => {
      if (a.sessionId === primarySessionId) return -1;
      if (b.sessionId === primarySessionId) return 1;
      return Number(a.registeredAt || a.updatedAt || 0) - Number(b.registeredAt || b.updatedAt || 0);
    });
  return records.length ? records : [];
}

function getBrowserCanvasVisibleSessionId() {
  const state = getBrowserCanvasState();
  const followSessionId = String(state.followSessionId || '').trim();
  if (followSessionId) return followSessionId;
  const visibleSessionId = String(state.sessionId || '').trim();
  return visibleSessionId || getBrowserCanvasPrimarySessionId();
}

function normalizeBrowserProviderKey(value) {
  return String(value || '').trim().toLowerCase().replace(/[-\s]+/g, '_');
}

function isInHouseBrowserProviderValue(value) {
  const key = normalizeBrowserProviderKey(value);
  return key === 'inhouse' || key === 'in_house' || key === 'in_app' || key === 'electron' || key === 'prometheus_inhouse' || key === 'prometheus_in_house';
}

function isBrowserCanvasInHouseProvider(state = getBrowserCanvasState()) {
  const visibleRecord = getBrowserSessionRecord(getBrowserCanvasVisibleSessionId(), state);
  return isInHouseBrowserProviderValue(visibleRecord?.browserTarget)
    || isInHouseBrowserProviderValue(visibleRecord?.profileKind)
    || isInHouseBrowserProviderValue(state.browserTarget)
    || isInHouseBrowserProviderValue(state.profileKind);
}

function isFollowingDetachedBrowserCanvasSession(state = getBrowserCanvasState()) {
  const followSessionId = String(state.followSessionId || '').trim();
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  return !!followSessionId && followSessionId !== primarySessionId;
}

function followBrowserCanvasSession(sessionId, options = {}) {
  const state = getBrowserCanvasState();
  const nextSessionId = String(sessionId || '').trim();
  if (!nextSessionId) return false;
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  if (!primarySessionId || nextSessionId === primarySessionId) {
    return returnBrowserCanvasToPrimarySession(options);
  }
  state.followSessionId = nextSessionId;
  state.sessionId = nextSessionId;
  const record = getBrowserSessionRecord(nextSessionId, state);
  if (record) {
    state.active = record.active === true;
    state.url = record.url || '';
    state.title = record.title || '';
    state.lastTool = record.tool || '';
    state.statusLabel = record.statusLabel || state.statusLabel;
    state.streamActive = record.streamActive === true;
    state.profileKind = record.profileKind || '';
    state.inhouseProfile = record.inhouseProfile || 'main';
    state.browserTarget = record.browserTarget || record.profileKind || '';
    state.profileLabel = record.profileLabel || '';
    if (state.frameBlobUrl) { try { URL.revokeObjectURL(state.frameBlobUrl); } catch {} }
    state.frameBlobUrl = '';
    state.frameBase64 = record.frameBase64 || '';
    if (state.frameBase64) {
      const url = decodeBase64FrameToBlobUrl(state.frameBase64, record.frameFormat);
      if (url) state.frameBlobUrl = url;
    }
    state.frameWidth = Number(record.frameWidth || 0) || 0;
    state.frameHeight = Number(record.frameHeight || 0) || 0;
    state.frameFormat = record.frameFormat || 'png';
    state.updatedAt = Number(record.updatedAt || Date.now()) || Date.now();
  }
  state.hoverElement = null;
  state.interactableMap = null;
  state.controlCaptured = false;
  state.controlOwner = 'agent';
  state.selectionPending = false;
  clearBrowserTransientHighlight();
  clearQueuedBrowserControlInputs();
  if (options.statusLabel) state.statusLabel = String(options.statusLabel || '').trim();
  if (options.render !== false) renderBrowserCanvasSurface();
  if (options.requestData !== false) {
    requestBrowserKnowledge(true);
    syncBrowserCanvasStream({ force: true });
  }
  persistActiveChat();
  return true;
}

function returnBrowserCanvasToPrimarySession(options = {}) {
  const state = getBrowserCanvasState();
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  const wasFollowing = isFollowingDetachedBrowserCanvasSession(state);
  state.followSessionId = '';
  if (primarySessionId) state.sessionId = primarySessionId;
  const record = getBrowserSessionRecord(primarySessionId, state);
  if (record) {
    state.active = record.active === true;
    state.url = record.url || '';
    state.title = record.title || '';
    state.lastTool = record.tool || '';
    state.statusLabel = record.statusLabel || state.statusLabel;
    state.streamActive = record.streamActive === true;
    state.profileKind = record.profileKind || '';
    state.inhouseProfile = record.inhouseProfile || 'main';
    state.browserTarget = record.browserTarget || record.profileKind || '';
    state.profileLabel = record.profileLabel || '';
    if (state.frameBlobUrl) { try { URL.revokeObjectURL(state.frameBlobUrl); } catch {} }
    state.frameBlobUrl = '';
    state.frameBase64 = record.frameBase64 || '';
    if (state.frameBase64) {
      const url = decodeBase64FrameToBlobUrl(state.frameBase64, record.frameFormat);
      if (url) state.frameBlobUrl = url;
    }
    state.frameWidth = Number(record.frameWidth || 0) || 0;
    state.frameHeight = Number(record.frameHeight || 0) || 0;
    state.frameFormat = record.frameFormat || 'png';
    state.updatedAt = Number(record.updatedAt || Date.now()) || Date.now();
  }
  state.hoverElement = null;
  state.interactableMap = null;
  state.controlCaptured = false;
  state.controlOwner = 'agent';
  state.selectionPending = false;
  clearBrowserTransientHighlight();
  clearQueuedBrowserControlInputs();
  if (options.statusLabel) state.statusLabel = String(options.statusLabel || '').trim();
  if (options.render !== false) renderBrowserCanvasSurface();
  if ((wasFollowing || options.force === true) && options.requestData !== false) {
    requestBrowserKnowledge(true);
    syncBrowserCanvasStream({ force: true });
  }
  persistActiveChat();
  return true;
}

function closeBrowserModeForCreativeSwitch(options = {}) {
  const state = getBrowserCanvasState();
  const surfaceActive = isBrowserCanvasSurfaceActive();
  const interactionMode = normalizeBrowserInteractionMode(state.interactionMode);
  const captureActive = state.controlCaptured === true;
  if (!surfaceActive && interactionMode === 'agent' && !captureActive) return false;

  if (captureActive) {
    syncBrowserControlCapture(false, {
      owner: 'agent',
      reason: String(options.reason || 'Creative workspace opened.').trim(),
      statusLabel: String(options.statusLabel || 'Browser control returned to agent.').trim(),
      render: false,
      syncRemote: options.syncRemote !== false,
      flushPending: false,
    });
  }

  if (interactionMode !== 'agent') {
    state.interactionMode = 'agent';
    if (options.syncRemote !== false) {
      const sessionId = getBrowserCanvasPrimarySessionId();
      if (sessionId) wsSend({ type: 'browser:mode:set', sessionId, mode: 'agent' });
    }
  }

  if (surfaceActive) {
    setBrowserCanvasSurface('files', { autoOpen: false });
  } else {
    renderBrowserCanvasSurface();
    syncCanvasSurfaceWidthLock(getActiveCanvasTab());
  }

  if (options.persist !== false) persistActiveChat();
  return true;
}

async function exitCreativeModeForBrowserSwitch(options = {}) {
  const sid = String(options.sessionId || getCurrentChatModeSessionId()).trim();
  const activeMode = normalizeCreativeMode(options.mode === undefined ? window.currentCreativeMode : options.mode);
  if (!sid || !activeMode) return false;
  const savedMode = await persistCreativeMode(sid, null);
  applySessionCreativeMode(sid, savedMode);
  return true;
}

function getBrowserCanvasControlSessionId() {
  return getBrowserCanvasPrimarySessionId();
}

function focusBrowserCanvasFrameWrap() {
  const frameWrap = document.getElementById('browser-canvas-frame-wrap');
  if (!frameWrap || typeof frameWrap.focus !== 'function') return;
  try {
    if (document.activeElement && document.activeElement !== frameWrap && typeof document.activeElement.blur === 'function') {
      document.activeElement.blur();
    }
  } catch {}
  try {
    frameWrap.focus({ preventScroll: true });
  } catch {
    try { frameWrap.focus(); } catch {}
  }
}

function resolveBrowserCanvasViewportPointFromClient(clientX, clientY) {
  const state = getBrowserCanvasState();
  const frame = document.getElementById('browser-canvas-frame');
  const nativeProvider = isBrowserCanvasInHouseProvider(state);
  const targetEl = nativeProvider ? document.getElementById('browser-canvas-frame-stage') : frame;
  if (!targetEl || (!nativeProvider && !String(state.frameBase64 || '').trim() && !state.frameBlobUrl)) return null;
  const rect = targetEl.getBoundingClientRect();
  if (!rect.width || !rect.height) return null;
  const computed = window.getComputedStyle(targetEl);
  const borderLeft = parseFloat(computed.borderLeftWidth) || 0;
  const borderTop = parseFloat(computed.borderTopWidth) || 0;
  const borderRight = parseFloat(computed.borderRightWidth) || 0;
  const borderBottom = parseFloat(computed.borderBottomWidth) || 0;
  const innerWidth = rect.width - borderLeft - borderRight;
  const innerHeight = rect.height - borderTop - borderBottom;
  const localX = Number(clientX || 0) - rect.left - borderLeft;
  const localY = Number(clientY || 0) - rect.top - borderTop;
  if (localX < 0 || localY < 0 || localX > innerWidth || localY > innerHeight) return null;
  const viewportWidth = Number(state.frameViewportWidth || state.frameWidth || innerWidth);
  const viewportHeight = Number(state.frameViewportHeight || state.frameHeight || innerHeight);
  // Subpixel coords — Playwright accepts floats and converts internally.
  return {
    x: (localX / innerWidth) * viewportWidth,
    y: (localY / innerHeight) * viewportHeight,
  };
}

function convertBrowserWheelDelta(event) {
  const deltaMode = Number(event?.deltaMode || 0);
  const factor = deltaMode === 1 ? 16 : (deltaMode === 2 ? 320 : 1);
  return {
    deltaX: Number(event?.deltaX || 0) * factor,
    deltaY: Number(event?.deltaY || 0) * factor,
  };
}

function normalizeBrowserForwardedKey(event) {
  const raw = String(event?.key || '').trim();
  if (!raw || raw === 'Dead' || raw === 'Process') return '';
  if (raw === ' ') return 'Space';
  return raw;
}

function flushQueuedBrowserWheelInput(options = {}) {
  if (browserQueuedWheelFlushTimer) {
    clearTimeout(browserQueuedWheelFlushTimer);
    browserQueuedWheelFlushTimer = 0;
  }
  const pending = browserQueuedWheelInput;
  browserQueuedWheelInput = null;
  if (!pending || options.clearOnly === true) return;
  const state = getBrowserCanvasState();
  if (isBrowserTeachRecording(state)) {
    upsertPendingBrowserTeachStep(
      createBrowserTeachScrollStep(pending, pending.deltaX, pending.deltaY, state),
      { merge: true },
    );
    return;
  }
  const sessionId = getBrowserCanvasControlSessionId();
  if (!sessionId || !(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  wsSend({
    type: 'browser:input',
    sessionId,
    action: 'wheel',
    x: pending.x,
    y: pending.y,
    deltaX: pending.deltaX,
    deltaY: pending.deltaY,
  });
}

function queueBrowserWheelInput(point, deltaX, deltaY) {
  if (!point) return;
  if (!browserQueuedWheelInput) {
    browserQueuedWheelInput = { x: point.x, y: point.y, deltaX: 0, deltaY: 0 };
  }
  browserQueuedWheelInput.x = point.x;
  browserQueuedWheelInput.y = point.y;
  browserQueuedWheelInput.deltaX += Number(deltaX || 0);
  browserQueuedWheelInput.deltaY += Number(deltaY || 0);
  if (browserQueuedWheelFlushTimer) clearTimeout(browserQueuedWheelFlushTimer);
  browserQueuedWheelFlushTimer = window.setTimeout(() => flushQueuedBrowserWheelInput(), 90);
}

function flushQueuedBrowserTextInput(options = {}) {
  if (browserQueuedTextFlushTimer) {
    clearTimeout(browserQueuedTextFlushTimer);
    browserQueuedTextFlushTimer = 0;
  }
  const text = browserQueuedTextInput;
  browserQueuedTextInput = '';
  if (!text || options.clearOnly === true) return;
  const state = getBrowserCanvasState();
  if (isBrowserTeachRecording(state)) {
    upsertPendingBrowserTeachStep(createBrowserTeachTextStep(text, state), { merge: true });
    return;
  }
  const sessionId = getBrowserCanvasControlSessionId();
  if (!sessionId || !(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  wsSend({
    type: 'browser:input',
    sessionId,
    action: 'text',
    text,
  });
}

function queueBrowserTextInput(text) {
  const value = String(text || '');
  if (!value) return;
  browserQueuedTextInput += value;
  if (browserQueuedTextFlushTimer) clearTimeout(browserQueuedTextFlushTimer);
  browserQueuedTextFlushTimer = window.setTimeout(() => flushQueuedBrowserTextInput(), 80);
}

function clearQueuedBrowserControlInputs() {
  flushQueuedBrowserTextInput({ clearOnly: true });
  flushQueuedBrowserWheelInput({ clearOnly: true });
}

function syncBrowserControlCapture(captured, options = {}) {
  const state = getBrowserCanvasState();
  const nextCaptured = captured === true;
  const nextOwner = nextCaptured ? (String(options.owner || '').trim().toLowerCase() === 'agent' ? 'agent' : 'user') : 'agent';
  state.controlCaptured = nextCaptured;
  state.controlOwner = nextOwner;
  if (nextCaptured) {
    state.statusLabel = String(options.statusLabel || state.statusLabel || 'You are controlling the browser.').trim();
    if (options.focusFrame !== false) focusBrowserCanvasFrameWrap();
  } else {
    if (options.flushPending !== false) {
      flushQueuedBrowserTextInput();
      flushQueuedBrowserWheelInput();
    } else {
      clearQueuedBrowserControlInputs();
    }
    if (options.statusLabel) {
      state.statusLabel = String(options.statusLabel || '').trim();
    }
  }
  if (options.render !== false) renderBrowserCanvasSurface();
  if (options.syncRemote === false) return;
  const sessionId = getBrowserCanvasControlSessionId();
  if (!sessionId || !(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  wsSend({
    type: 'browser:control:set',
    sessionId,
    captured: nextCaptured,
    owner: nextOwner,
    reason: String(options.reason || '').trim(),
  });
}

function captureBrowserCanvasControl(reason = 'User clicked into the browser canvas.') {
  const state = getBrowserCanvasState();
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  if (mode !== 'copilot' && mode !== 'teach') return false;
  if (isFollowingDetachedBrowserCanvasSession(state)) {
    showToast('The canvas is following the detached Teach verifier tab. Return to Main Tab to control the live browser again.', 'info');
    return false;
  }
  syncBrowserControlCapture(true, {
    owner: 'user',
    reason,
    statusLabel: (mode === 'teach' && isBrowserTeachRecording(state))
      ? 'Teach mode is recording. Stage the next step, then continue it when you are ready.'
      : 'You are controlling the browser.',
    render: true,
    syncRemote: true,
    focusFrame: true,
  });
  return true;
}

function releaseBrowserCanvasControl(options = {}) {
  const state = getBrowserCanvasState();
  if (!state.controlCaptured && options.force !== true) return false;
  syncBrowserControlCapture(false, {
    owner: 'agent',
    reason: String(options.reason || 'Browser control returned to Prometheus.').trim(),
    statusLabel: String(options.statusLabel || 'Browser control returned to Prometheus.').trim(),
    render: options.render !== false,
    syncRemote: options.syncRemote !== false,
    flushPending: options.flushPending !== false,
  });
  return true;
}

function handleCapturedBrowserKeydown(event) {
  const state = getBrowserCanvasState();
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  if (mode !== 'copilot' && mode !== 'teach') return;
  if (!state.controlCaptured || state.controlOwner !== 'user') return;
  if (event?.isComposing) return;
  const normalizedKey = normalizeBrowserForwardedKey(event);
  if (!normalizedKey) return;
  // Before "Start Teach" is pressed, forward all keys exactly like copilot mode.
  if (mode === 'teach' && !isBrowserTeachRecording(state) && normalizedKey === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    releaseBrowserCanvasControl({
      reason: 'User released browser control with Escape.',
      statusLabel: 'Browser control returned to Prometheus.',
    });
    return;
  }
  if (normalizedKey === 'Escape') {
    event.preventDefault();
    event.stopPropagation();
    releaseBrowserCanvasControl({
      reason: 'User released browser control with Escape.',
      statusLabel: 'Browser control returned to Prometheus.',
    });
    return;
  }
  const noModifiers = !event.ctrlKey && !event.altKey && !event.metaKey;
  const teachPlainText = mode === 'teach'
    && noModifiers
    && (normalizedKey.length === 1 || (normalizedKey === 'Space' && (isEditableBrowserTeachSelection(state.selectedElement) || ((getBrowserTeachSession(state).pendingStep?.kind === 'fill') || (getBrowserTeachSession(state).pendingStep?.kind === 'text')))));
  const isPlainText = normalizedKey.length === 1 && noModifiers;
  event.preventDefault();
  event.stopPropagation();
  if (isPlainText || teachPlainText) {
    queueBrowserTextInput(normalizedKey === 'Space' ? ' ' : event.key);
    return;
  }
  if (['Shift', 'Control', 'Alt', 'Meta'].includes(normalizedKey)) return;
  if (mode === 'teach' && isBrowserTeachRecording(state)) {
    upsertPendingBrowserTeachStep(createBrowserTeachKeyStep(normalizedKey, {
      ctrlKey: event.ctrlKey === true,
      altKey: event.altKey === true,
      metaKey: event.metaKey === true,
      shiftKey: event.shiftKey === true,
    }, state));
    return;
  }
  flushQueuedBrowserTextInput();
  const sessionId = getBrowserCanvasControlSessionId();
  if (!sessionId || !(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  wsSend({
    type: 'browser:input',
    sessionId,
    action: 'key',
    key: normalizedKey,
    ctrlKey: event.ctrlKey === true,
    altKey: event.altKey === true,
    metaKey: event.metaKey === true,
    shiftKey: event.shiftKey === true,
  });
}

function handleCapturedBrowserWheel(event) {
  const state = getBrowserCanvasState();
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  if (mode !== 'copilot' && mode !== 'teach') return;
  // Before recording starts, scrolling works like copilot navigation.
  if (!state.controlCaptured || state.controlOwner !== 'user') return;
  const point = resolveBrowserCanvasViewportPointFromClient(event?.clientX, event?.clientY);
  if (!point) return;
  const { deltaX, deltaY } = convertBrowserWheelDelta(event);
  if (!deltaX && !deltaY) return;
  event.preventDefault();
  event.stopPropagation();
  queueBrowserWheelInput(point, deltaX, deltaY);
}

function ensureBrowserCanvasControlBindings() {
  const frameWrap = document.getElementById('browser-canvas-frame-wrap');
  if (!frameWrap || frameWrap.dataset.browserControlBound === '1') return;
  frameWrap.addEventListener('keydown', handleCapturedBrowserKeydown);
  frameWrap.addEventListener('wheel', handleCapturedBrowserWheel, { passive: false });
  frameWrap.dataset.browserControlBound = '1';
}

function ensureBrowserCanvasGlobalControlBindings() {
  if (window.__promBrowserControlGlobalsBound) return;
  document.addEventListener('pointerdown', (event) => {
    const state = getBrowserCanvasState();
    const mode = normalizeBrowserInteractionMode(state.interactionMode);
    if (mode !== 'copilot' && mode !== 'teach') return;
    if (!state.controlCaptured || state.controlOwner !== 'user') return;
    const target = event?.target instanceof Element ? event.target : null;
    const frameWrap = document.getElementById('browser-canvas-frame-wrap');
    if (target && frameWrap?.contains(target)) return;
    releaseBrowserCanvasControl({
      reason: 'Browser control released when focus moved back to the app.',
      statusLabel: 'Browser control returned to Prometheus.',
    });
  }, true);
  window.__promBrowserControlGlobalsBound = true;
}

function clearBrowserCanvasStreamHeartbeat() {
  if (!browserStreamHeartbeatTimer) return;
  clearInterval(browserStreamHeartbeatTimer);
  browserStreamHeartbeatTimer = 0;
}

function startBrowserCanvasStreamHeartbeat() {
  if (browserStreamHeartbeatTimer) return;
  browserStreamHeartbeatTimer = window.setInterval(() => {
    const desired = window.__promBrowserCanvasStreamDesired;
    if (!desired?.active || !desired?.sessionId) {
      clearBrowserCanvasStreamHeartbeat();
      return;
    }
    if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
    wsSend({
      type: 'browser:stream:set',
      sessionId: desired.sessionId,
      active: true,
      focus: desired.focus,
      preferCdp: true,
      restoreUrl: getBrowserCanvasRestoreHint(getBrowserCanvasState()).restoreUrl,
      restoreTitle: getBrowserCanvasRestoreHint(getBrowserCanvasState()).restoreTitle,
    });
  }, 5000);
}

function syncBrowserCanvasStream(options = {}) {
  const state = getBrowserCanvasState();
  const currentMode = normalizeBrowserInteractionMode(state.interactionMode);
  const sessionId = getBrowserCanvasVisibleSessionId();
  const nativeProvider = isBrowserCanvasInHouseProvider(state);
  const desired = {
    sessionId: String(sessionId || '').trim(),
    active: !!(canvasOpen && isBrowserCanvasSurfaceActive() && state.active && sessionId && !nativeProvider),
    focus: isBrowserCanvasSurfaceActive() ? 'interactive' : ((currentMode === 'copilot' || currentMode === 'teach') ? 'interactive' : 'passive'),
  };
  const previous = window.__promBrowserCanvasStreamDesired || { sessionId: '', active: false, focus: 'passive' };
  window.__promBrowserCanvasStreamDesired = desired;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    clearBrowserCanvasStreamHeartbeat();
    return;
  }
  const shouldStopPrevious = previous.active && previous.sessionId && (
    !desired.active || previous.sessionId !== desired.sessionId
  );
  if (shouldStopPrevious) {
    wsSend({
      type: 'browser:stream:set',
      sessionId: previous.sessionId,
      active: false,
      reason: 'Browser canvas moved away from this session.',
    });
  }
  const shouldStartOrRefresh = desired.active && (
    options.force === true
    || !previous.active
    || previous.sessionId !== desired.sessionId
    || previous.focus !== desired.focus
  );
  if (shouldStartOrRefresh) {
    const { restoreUrl, restoreTitle } = getBrowserCanvasRestoreHint(state);
    wsSend({
      type: 'browser:stream:set',
      sessionId: desired.sessionId,
      active: true,
      focus: desired.focus,
      preferCdp: true,
      restoreUrl,
      restoreTitle,
    });
  }
  if (!desired.active) {
    clearBrowserCanvasStreamHeartbeat();
  } else {
    startBrowserCanvasStreamHeartbeat();
  }
}

function normalizeNativeBrowserTabs(tabs) {
  if (!Array.isArray(tabs)) return [];
  return tabs.map((tab, index) => ({
    id: String(tab?.id || tab?.tabId || `native-tab-${index + 1}`).trim(),
    title: String(tab?.title || '').trim() || 'New Tab',
    url: String(tab?.url || 'about:blank').trim() || 'about:blank',
    loading: tab?.loading === true,
    active: tab?.active === true,
    index: Number.isFinite(Number(tab?.index)) ? Number(tab.index) : index,
    canGoBack: tab?.canGoBack === true,
    canGoForward: tab?.canGoForward === true,
  })).filter((tab) => tab.id);
}

function applyNativeBrowserStateToCanvas(nativeState, state = getBrowserCanvasState()) {
  if (!nativeState || typeof nativeState !== 'object') return state;
  if (nativeState.profile !== undefined) state.inhouseProfile = String(nativeState.profile || '').trim() || 'main';
  if (nativeState.profileLabel !== undefined) state.profileLabel = String(nativeState.profileLabel || '').trim() || state.profileLabel;
  if (Array.isArray(nativeState.tabs)) state.nativeTabs = normalizeNativeBrowserTabs(nativeState.tabs);
  if (nativeState.activeTabId !== undefined) state.activeNativeTabId = String(nativeState.activeTabId || '').trim();
  if (state.activeNativeTabId && state.nativeTabs.length) {
    state.nativeTabs = state.nativeTabs.map((tab) => ({
      ...tab,
      active: tab.id === state.activeNativeTabId,
    }));
  }
  return state;
}

function isSettingsSurfaceVisible() {
  const modal = document.getElementById('settings-modal');
  if (!modal) return false;
  const style = window.getComputedStyle ? window.getComputedStyle(modal) : null;
  return modal.style.display !== 'none'
    && modal.getAttribute('aria-hidden') !== 'true'
    && style?.display !== 'none'
    && style?.visibility !== 'hidden';
}

function getNativeBrowserSurfaceApi() {
  return window.prometheusBrowserSurface && typeof window.prometheusBrowserSurface === 'object'
    ? window.prometheusBrowserSurface
    : null;
}

function getPreferredInHouseProfileId(state = getBrowserCanvasState()) {
  const stored = (() => {
    try { return localStorage.getItem('prometheus.inhouse.profile') || ''; } catch { return ''; }
  })();
  // The settings choice is global to this desktop install. Prefer it over a
  // stale profile copied into a session snapshot so switching profiles while
  // the browser canvas is open takes effect on the next attach.
  return String(stored || state.inhouseProfile || 'main').trim() || 'main';
}

function announceNativeBrowserStateToGateway(nativeState, state = getBrowserCanvasState(), options = {}) {
  const sid = String(nativeState?.sessionId || state.sessionId || getDirectBrowserSessionId(state) || '').trim();
  if (!sid) return;
  const send = () => {
    nativeBrowserGatewaySyncTimers.delete(sid);
    if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
    const browserActive = nativeState?.active !== undefined
      ? nativeState.active !== false
      : nativeState?.attached !== false;
    wsSend({
      type: 'browser:native_state',
      sessionId: sid,
      active: browserActive,
      attached: nativeState?.attached !== false,
      profile: String(nativeState?.profile || state.inhouseProfile || 'main').trim() || 'main',
      profileLabel: String(nativeState?.profileLabel || state.profileLabel || '').trim(),
      url: String(nativeState?.url || state.url || '').trim(),
      title: String(nativeState?.title || state.title || '').trim(),
      activeTabId: String(nativeState?.activeTabId || state.activeNativeTabId || '').trim(),
      tabs: Array.isArray(nativeState?.tabs) ? nativeState.tabs : (Array.isArray(state.nativeTabs) ? state.nativeTabs : []),
      timestamp: Date.now(),
    });
  };
  const previous = nativeBrowserGatewaySyncTimers.get(sid);
  if (previous) clearTimeout(previous);
  if (options.immediate === true) send();
  else nativeBrowserGatewaySyncTimers.set(sid, setTimeout(send, 80));
}

function getNativeBrowserBoundsElement() {
  return document.getElementById('browser-canvas-frame-stage') || document.getElementById('browser-canvas-frame-wrap');
}

function queueNativeBrowserSurfaceSync(options = {}) {
  if (nativeBrowserSyncQueued && options.force !== true) return;
  nativeBrowserSyncQueued = true;
  requestAnimationFrame(() => {
    nativeBrowserSyncQueued = false;
    syncNativeBrowserSurface(options);
  });
}

async function syncNativeBrowserSurface(options = {}) {
  const api = getNativeBrowserSurfaceApi();
  if (!api) return false;
  ensureNativeBrowserSurfaceStateListener();
  ensureNativeBrowserBoundsObserver();
  const state = getBrowserCanvasState();
  const sessionId = getBrowserCanvasVisibleSessionId();
  const shouldShow = !!(
    canvasOpen
    && isBrowserCanvasSurfaceActive()
     && state.active
     && sessionId
     && isBrowserCanvasInHouseProvider(state)
     && !isSettingsSurfaceVisible()
   );
  if (!shouldShow) {
    nativeBrowserLastBoundsKey = '';
    nativeBrowserAttachedSessionId = '';
    if (typeof api.detach === 'function') {
      try { await api.detach(); } catch {}
    } else {
      try { await api.setBounds?.({ x: 0, y: 0, width: 0, height: 0 }); } catch {}
    }
    return false;
  }
  const targetEl = getNativeBrowserBoundsElement();
  const rect = targetEl?.getBoundingClientRect?.();
  if (!rect || rect.width < 8 || rect.height < 8) {
    queueNativeBrowserSurfaceSync({ force: true });
    return false;
  }
  // The native WebContentsView is composited above the renderer, so a DOM
  // z-index cannot keep it from swallowing the panel's left-edge resize grip.
  // Reserve a few physical pixels for that grip in the native bounds.
  const resizeGutter = Math.min(
    NATIVE_BROWSER_RESIZE_HANDLE_GUTTER,
    Math.max(0, Math.floor(rect.width) - 8),
  );
  const bounds = {
    x: Math.round(rect.left + resizeGutter),
    y: Math.round(rect.top),
    width: Math.max(0, Math.round(rect.width - resizeGutter)),
    height: Math.round(rect.height),
  };
  const key = `${sessionId}:${String(state.activeNativeTabId || '').trim()}:${bounds.x}:${bounds.y}:${bounds.width}:${bounds.height}`;
  const profileId = getPreferredInHouseProfileId(state);
  const attachKey = `${sessionId}:${profileId}`;
  try {
    // Attach only when the session or selected profile changes. Re-attaching on
    // every render or resize would re-trigger a native state broadcast and
    // create an attach → state → render → attach echo loop. Bounds updates are
    // cheap and idempotent, so those run whenever the rect changes.
    if (nativeBrowserAttachedSessionId !== attachKey) {
      nativeBrowserAttachedSessionId = attachKey;
      await api.attach?.({
        sessionId,
        url: state.url || getBrowserCanvasRestoreHint(state).restoreUrl || 'about:blank',
        profile: profileId,
      });
    }
    if (key !== nativeBrowserLastBoundsKey || options.force === true) {
      nativeBrowserLastBoundsKey = key;
      await api.setBounds?.(bounds);
    }
    return true;
  } catch (err) {
    // Allow the next render/resize to retry a failed attach instead of leaving
    // a stale key that makes the detached view look permanently connected.
    if (nativeBrowserAttachedSessionId === attachKey) nativeBrowserAttachedSessionId = '';
    console.warn('[Prometheus] Native browser surface sync failed:', err);
    return false;
  }
}

async function fetchChatSessionSummariesWithRetry() {
  const url = '/api/sessions?scope=all&includeAutomated=1&limit=160&offset=0';
  // Electron can paint the renderer before the gateway has completed its
  // warmup. Keep the first-load failure from looking like the user's history
  // disappeared; retry a few times before falling back to the normal refresh
  // timer.
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const timeoutMs = 2500 + attempt * 750;
    const data = await fetchJsonWithTimeout(url, timeoutMs);
    if (data && Array.isArray(data.sessions) && (data.sessions.length > 0 || Number(data.total || 0) === 0)) {
      return data;
    }
    if (attempt < 3) await new Promise((resolve) => setTimeout(resolve, 400 + attempt * 500));
  }
  return null;
}

function normalizeBrowserAddressInput(value) {
  const raw = String(value || '').trim();
  if (!raw) throw new Error('Enter a URL to open.');
  if (raw === 'about:blank') return raw;
  const withScheme = /^[a-z][a-z0-9+.-]*:/i.test(raw) ? raw : `https://${raw}`;
  let parsed;
  try { parsed = new URL(withScheme); } catch {
    throw new Error('Enter a valid HTTP or HTTPS URL.');
  }
  if (!['http:', 'https:'].includes(parsed.protocol)) {
    throw new Error('The in-app browser accepts only HTTP or HTTPS URLs.');
  }
  if (parsed.username || parsed.password) {
    throw new Error('URLs containing embedded credentials are not allowed.');
  }
  return parsed.href;
}

function getDirectBrowserSessionId(state = getBrowserCanvasState()) {
  return String(window.activeChatSessionId || window.agentSessionId || state.sessionId || 'default').trim() || 'default';
}

async function openDirectNativeBrowserSurface(options = {}) {
  const api = getNativeBrowserSurfaceApi();
  if (!api || typeof api.available !== 'function' || typeof api.attach !== 'function') return false;
  if (!(await api.available())) return false;

  const state = getBrowserCanvasState();
  const sessionId = getDirectBrowserSessionId(state);
  const inhouseProfile = getPreferredInHouseProfileId(state);
  const restoreHint = getBrowserCanvasRestoreHint(state);
  const requestedUrl = String(options.url || state.url || restoreHint.restoreUrl || 'about:blank').trim() || 'about:blank';
  if (requestedUrl === 'about:blank' && !String(state.title || '').trim()) state.title = 'New Tab';
  state.sessionId = sessionId;
  state.active = true;
  state.profileKind = 'inhouse';
  state.inhouseProfile = inhouseProfile;
  state.browserTarget = 'inhouse';
  state.profileLabel = 'Prometheus in-house browser';
  state.loading = false;
  state.lastError = '';
  state.statusLabel = requestedUrl === 'about:blank' ? 'New tab ready. Enter a URL to browse.' : 'Browser ready.';
  upsertBrowserSessionRecord({
    sessionId,
    browserOwnerType: 'main',
    browserLabel: 'Main Agent',
    active: true,
    url: requestedUrl,
    title: state.title,
    statusLabel: state.statusLabel,
    profileKind: 'inhouse',
    browserTarget: 'inhouse',
    profileLabel: state.profileLabel,
    inhouseProfile,
    timestamp: Date.now(),
  }, { copyToCanvas: true });
  setBrowserCanvasSurface('browser');
  try {
     const nativeState = await api.attach({ sessionId, url: requestedUrl, profile: inhouseProfile });
    if (nativeState && typeof nativeState === 'object') {
      applyNativeBrowserStateToCanvas(nativeState, state);
      announceNativeBrowserStateToGateway(nativeState, state, { immediate: true });
      state.url = String(nativeState.url || state.url || 'about:blank').trim();
      state.title = String(nativeState.title || state.title || '').trim();
      state.loading = nativeState.loading === true;
      state.lastError = String(nativeState.lastError || '').trim();
      state.statusLabel = state.lastError
        ? `Browser error: ${state.lastError}`
        : (state.loading ? 'In-house browser loading.' : state.statusLabel);
    }
    announceNativeBrowserStateToGateway({
      sessionId,
      attached: true,
      profile: state.inhouseProfile,
      url: state.url,
      title: state.title,
      tabs: state.nativeTabs,
      activeTabId: state.activeNativeTabId,
    }, state, { immediate: true });
    renderBrowserCanvasSurface();
    persistActiveChat();
    window.requestAnimationFrame?.(() => {
      const input = document.getElementById('browser-canvas-address-input');
      if (input && document.activeElement !== input) {
        input.focus({ preventScroll: true });
        input.select?.();
      }
    });
    return true;
  } catch (error) {
    state.lastError = String(error?.message || error || 'Could not open the in-app browser.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    persistActiveChat();
    showToast(state.lastError, 'error');
    return true;
  }
}

function openPrometheusBrowserLink(url, options = {}) {
  const run = nativeBrowserLinkOpenInFlight.catch(() => false).then(async () => {
    const address = normalizeBrowserAddressInput(url);
    const api = getNativeBrowserSurfaceApi();
    if (api && typeof api.available === 'function' && typeof api.attach === 'function' && await api.available()) {
      // Electron always uses the in-house partition for UI links, even when a
      // user-Chrome target is selected for agent tools. This does not touch or
      // close the extension-owned personal tab.
      return openDirectNativeBrowserSurface({ url: address });
    }

    const state = getBrowserCanvasState();
    const sessionId = getBrowserCanvasPrimarySessionId() || getDirectBrowserSessionId(state);
    if (!sessionId) throw new Error('No chat session is available for browser navigation.');
    if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
      showToast('Browser connection is reconnecting. Try again in a second.', 'info');
      return false;
    }
    returnBrowserCanvasToPrimarySession({ render: false, requestData: false });
    state.active = true;
    state.url = address;
    state.loading = true;
    state.lastError = '';
    state.statusLabel = `Opening ${address}`;
    setBrowserCanvasSurface('browser');
    renderBrowserCanvasSurface();
    wsSend({
      type: 'browser:link_open',
      sessionId,
      url: address,
      source: String(options.source || 'desktop-link'),
      lane: String(options.lane || 'prometheus'),
      timestamp: Date.now(),
    });
    return true;
  });
  nativeBrowserLinkOpenInFlight = run.catch(() => false);
  return run;
}

function ensureNativeBrowserBoundsObserver() {
  if (nativeBrowserBoundsObserver || typeof ResizeObserver === 'undefined') return;
  const targetEl = getNativeBrowserBoundsElement();
  if (!targetEl) return;
  nativeBrowserBoundsObserver = new ResizeObserver(() => queueNativeBrowserSurfaceSync());
  [
    targetEl,
    document.getElementById('browser-canvas-frame-wrap'),
    document.getElementById('browser-canvas-live-card'),
    document.getElementById('browser-canvas-layout'),
    document.getElementById('right-panel'),
    document.getElementById('canvas-panel'),
  ].filter(Boolean).forEach((element) => {
    try { nativeBrowserBoundsObserver.observe(element); } catch {}
  });
  window.addEventListener('resize', () => queueNativeBrowserSurfaceSync({ force: true }), { passive: true });
  window.addEventListener('scroll', () => queueNativeBrowserSurfaceSync({ force: true }), { passive: true, capture: true });
  window.visualViewport?.addEventListener('resize', () => queueNativeBrowserSurfaceSync({ force: true }), { passive: true });
}

function ensureNativeBrowserSurfaceStateListener() {
  const api = getNativeBrowserSurfaceApi();
  if (!api || nativeBrowserStateUnsubscribe || typeof api.onState !== 'function') return;
  nativeBrowserStateUnsubscribe = api.onState((nativeState) => {
    if (!nativeState || typeof nativeState !== 'object') return;
    const sid = String(nativeState.sessionId || '').trim();
    if (!sid || sid !== getBrowserCanvasVisibleSessionId()) return;
    const state = getBrowserCanvasState();
    // Hiding the native view should not erase this session's browser context
    // while tabs still exist. Closing the last tab sends an empty tab list and
    // still makes the browser inactive.
    const nativeTabs = Array.isArray(nativeState.tabs) ? nativeState.tabs : [];
    const nextActive = nativeState.attached !== false
      || (state.active === true && nativeTabs.length > 0);
    const nextUrl = String(nativeState.url || state.url || '').trim();
    const nextTitle = String(nativeState.title || state.title || '').trim();
    const nextError = String(nativeState.lastError || '').trim();
    const nextStatus = nextError
      ? `Browser error: ${nextError}`
      : (nextActive
        ? (nativeState.loading ? 'In-house browser loading.' : 'In-house browser active.')
        : 'In-house browser idle.');
     const previousNativeTabsKey = JSON.stringify(state.nativeTabs || []);
     const previousActiveNativeTabId = String(state.activeNativeTabId || '').trim();
     applyNativeBrowserStateToCanvas(nativeState, state);
     const nextTabsKey = JSON.stringify(state.nativeTabs || []);
    announceNativeBrowserStateToGateway({ ...nativeState, active: nextActive }, state);
    // Skip churn when nothing meaningful changed — native state broadcasts fire on
    // every loading toggle, so avoid redundant render + persist cycles.
    const unchanged = state.active === nextActive
      && state.url === nextUrl
      && state.title === nextTitle
      && state.statusLabel === nextStatus
      && state.loading === (nativeState.loading === true)
      && state.lastError === nextError
      && previousActiveNativeTabId === String(nativeState.activeTabId || '').trim()
      && previousNativeTabsKey === nextTabsKey
      && state.profileKind === 'inhouse';
    if (unchanged) return;
     state.active = nextActive;
     state.profileKind = 'inhouse';
     state.browserTarget = 'inhouse';
     state.profileLabel = String(nativeState.profileLabel || state.profileLabel || 'Prometheus in-house browser').trim();
    state.url = nextUrl;
    state.title = nextTitle;
    state.loading = nativeState.loading === true;
    state.lastError = nextError;
    state.statusLabel = nextStatus;
    state.streamActive = false;
    state.streamTransport = 'native';
    state.updatedAt = Date.now();
    rememberBrowserCanvasRestorablePage(state.url, state.title, state);
    upsertBrowserSessionRecord({
      sessionId: sid,
      active: nextActive,
      url: state.url,
      title: state.title,
      statusLabel: state.statusLabel,
       profileKind: 'inhouse',
       browserTarget: 'inhouse',
       profileLabel: state.profileLabel,
       inhouseProfile: state.inhouseProfile,
      streamActive: false,
      nativeTabs: state.nativeTabs,
      activeNativeTabId: state.activeNativeTabId,
      timestamp: state.updatedAt,
    });
    renderBrowserCanvasSurface();
    persistActiveChat();
  });
}

// ─── In-house browser Teach-mode capture ────────────────────────────────────
// The native WebContentsView sits on top of the canvas and eats clicks, so the
// normal renderer click recorder never fires. Instead we toggle a preload-based
// capture inside the native view and stage Teach steps from the clicks it relays.
function ensureNativeBrowserTeachListener() {
  const api = getNativeBrowserSurfaceApi();
  if (!api || nativeBrowserTeachUnsub || typeof api.onTeachClick !== 'function') return;
  nativeBrowserTeachUnsub = api.onTeachClick((payload) => handleNativeBrowserTeachClick(payload));
  if (typeof api.onTeachFill === 'function') api.onTeachFill((payload) => handleNativeBrowserTeachFill(payload));
  if (typeof api.onTeachKey === 'function') api.onTeachKey((payload) => handleNativeBrowserTeachKey(payload));
  if (typeof api.onTeachScroll === 'function') api.onTeachScroll((payload) => handleNativeBrowserTeachScroll(payload));
}

function ensureNativeBrowserDesignListener() {
  const api = getNativeBrowserSurfaceApi();
  if (!api || nativeBrowserDesignUnsubscribers.length || typeof api.onDesignHover !== 'function') return;
  nativeBrowserDesignUnsubscribers = [
    api.onDesignHover((payload) => handleNativeBrowserDesignHover(payload)),
    typeof api.onDesignSelect === 'function' ? api.onDesignSelect((payload) => handleNativeBrowserDesignSelect(payload)) : null,
    typeof api.onDesignChat === 'function' ? api.onDesignChat((payload) => handleNativeBrowserDesignChat(payload)) : null,
  ].filter((unsubscribe) => typeof unsubscribe === 'function');
}

function isNativeBrowserDesignEventForVisibleSession(payload) {
  const sid = String(payload?.sessionId || '').trim();
  return !sid || sid === getBrowserCanvasVisibleSessionId();
}

function nativeBrowserDesignSelectionFromPayload(payload) {
  if (!payload || typeof payload !== 'object') return null;
  return cloneBrowserDesignSelection({
    ...payload,
    ...payload.selection,
    bounds: payload.selection?.bounds || payload.bounds || null,
    liveBounds: payload.selection?.bounds || payload.bounds || null,
    viewport: payload.selection?.viewport || payload.viewport || null,
    url: payload.selection?.url || payload.url || '',
    title: payload.selection?.title || payload.title || '',
  });
}

function handleNativeBrowserDesignHover(payload) {
  if (!isNativeBrowserDesignEventForVisibleSession(payload)) return;
  const state = getBrowserCanvasState();
  if (!isBrowserDesignMode(state)) return;
  state.hoverElement = nativeBrowserDesignSelectionFromPayload(payload);
  renderBrowserCanvasSurface();
}

function handleNativeBrowserDesignSelect(payload) {
  if (!isNativeBrowserDesignEventForVisibleSession(payload)) return;
  const state = getBrowserCanvasState();
  if (!isBrowserDesignMode(state)) return;
  const selection = nativeBrowserDesignSelectionFromPayload(payload);
  if (!selection) return;
  applyBrowserDesignSelection(selection, { showPopover: false });
  addProcessEntry('info', `Design: selected ${selection.selector || selection.tagName || 'element'}.`);
}

function handleNativeBrowserDesignChat(payload) {
  if (!isNativeBrowserDesignEventForVisibleSession(payload)) return;
  const state = getBrowserCanvasState();
  if (!isBrowserDesignMode(state)) return;
  const selection = nativeBrowserDesignSelectionFromPayload(payload);
  if (selection) applyBrowserDesignSelection(selection, { showPopover: false });
  const text = String(payload?.text || '').trim();
  const input = document.getElementById('chat-input');
  if (!text || !input) return;
  input.value = text;
  void sendChat().catch((err) => showToast(`Send failed: ${err.message}`, 'error'));
}

async function syncNativeBrowserDesignMode(state = getBrowserCanvasState()) {
  const api = getNativeBrowserSurfaceApi();
  if (!api || typeof api.setDesignMode !== 'function') return;
  ensureNativeBrowserDesignListener();
  const sessionId = getBrowserCanvasVisibleSessionId();
  const want = !!(
    isBrowserCanvasInHouseProvider(state)
    && isBrowserCanvasSurfaceActive()
    && state.browserDesignMode === true
    && sessionId
  );
  if (!want && !nativeBrowserDesignModeOn) return;
  if (want && nativeBrowserDesignModeOn && nativeBrowserDesignSessionId === sessionId) return;
  try {
    if (nativeBrowserDesignModeOn && nativeBrowserDesignSessionId && nativeBrowserDesignSessionId !== sessionId) {
      await api.setDesignMode({ sessionId: nativeBrowserDesignSessionId, enabled: false });
    }
    await api.setDesignMode({ sessionId, enabled: want });
    nativeBrowserDesignModeOn = want;
    nativeBrowserDesignSessionId = want ? sessionId : '';
  } catch (err) {
    nativeBrowserDesignModeOn = false;
    nativeBrowserDesignSessionId = '';
    console.warn('[Prometheus] Native browser Design mode sync failed:', err);
  }
}

function nativeTeachRecordingState() {
  const state = getBrowserCanvasState();
  if (!isBrowserCanvasInHouseProvider(state)) return null;
  if (normalizeBrowserInteractionMode(state.interactionMode) !== 'teach') return null;
  if (!isBrowserTeachRecording(state)) return null;
  return state;
}

function appendRecordedNativeTeachStep(state, step, label) {
  const teach = getBrowserTeachSession(state);
  const finalized = refreshBrowserTeachStepMetadata(step, state);
  finalized.status = 'recorded';
  finalized.executedAt = Date.now();
  teach.steps = [...(Array.isArray(teach.steps) ? teach.steps : []), finalized];
  teach.pendingStep = null;
  state.statusLabel = `Recorded step ${teach.steps.length}: ${finalized.summary || finalized.title || label}. Remove it below if unwanted.`;
  addProcessEntry('info', `Teach: recorded ${finalized.summary || label}.`);
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
}

function syncNativeBrowserTeachCapture(state = getBrowserCanvasState()) {
  const api = getNativeBrowserSurfaceApi();
  if (!api || typeof api.setTeachCapture !== 'function') return;
  ensureNativeBrowserTeachListener();
  const sessionId = getBrowserCanvasVisibleSessionId();
  const teach = getBrowserTeachSession(state);
  // Capture only while actively recording AND no step is staged. Disabling capture
  // while a step is pending lets the "Continue" execution click pass through to the
  // page (and advance it) instead of being intercepted again.
  const wantCapture = !!(
    isBrowserCanvasInHouseProvider(state)
    && normalizeBrowserInteractionMode(state.interactionMode) === 'teach'
    && isBrowserTeachRecording(state)
    && sessionId
  );
  if (wantCapture === nativeBrowserTeachCaptureOn) return;
  nativeBrowserTeachCaptureOn = wantCapture;
  try { api.setTeachCapture({ sessionId, enabled: wantCapture }); } catch {}
}

function handleNativeBrowserTeachClick(payload) {
  if (!payload || typeof payload !== 'object') return;
  const state = getBrowserCanvasState();
  if (!isBrowserCanvasInHouseProvider(state)) return;
  if (normalizeBrowserInteractionMode(state.interactionMode) !== 'teach') return;
  if (!isBrowserTeachRecording(state)) return;
  const teach = getBrowserTeachSession(state);
  const selection = {
    selector: String(payload.selector || '').trim(),
    pack: null,
    tagName: String(payload.tagName || '').trim(),
    id: String(payload.id || '').trim(),
    role: String(payload.role || '').trim(),
    text: String(payload.text || '').trim(),
    bounds: payload.bounds || null,
    liveBounds: payload.bounds || null,
  };
  if (!selection.selector && !selection.id && !selection.tagName) return;
  state.selectedElement = selection;
  state.elementNameDraftKey = '';
  // Live-macro model: the click already passed through to the page, so record it
  // straight into the steps list (visible + removable) — no pending/Continue.
  const intent = { action: 'click', x: Number(payload.x || 0), y: Number(payload.y || 0), button: 'left' };
  appendRecordedNativeTeachStep(state, createBrowserTeachClickStep(selection, intent, state), 'browser click step');
}

function handleNativeBrowserTeachFill(payload) {
  if (!payload || typeof payload !== 'object') return;
  const state = nativeTeachRecordingState();
  if (!state) return;
  const selector = String(payload.selector || '').trim();
  const text = String(payload.text || '');
  if (!selector || !text) return;
  const teach = getBrowserTeachSession(state);
  // If the last recorded step was a fill on the SAME field, replace it (so we keep
  // the final text rather than stacking partial edits from refocus/blur cycles).
  const selection = {
    selector,
    pack: null,
    tagName: String(payload.tagName || '').trim(),
    id: '',
    role: String(payload.role || '').trim(),
    text: String(payload.label || '').trim(),
    bounds: payload.bounds || null,
    liveBounds: payload.bounds || null,
  };
  state.selectedElement = selection;
  const steps = Array.isArray(teach.steps) ? teach.steps : [];
  const last = steps[steps.length - 1];
  if (last && last.kind === 'fill' && String(last?.selection?.selector || '') === selector) {
    teach.steps = steps.slice(0, -1);
  }
  appendRecordedNativeTeachStep(state, createBrowserTeachTextStep(text, state), 'text input');
}

function handleNativeBrowserTeachKey(payload) {
  if (!payload || typeof payload !== 'object') return;
  const state = nativeTeachRecordingState();
  if (!state) return;
  const key = String(payload.key || '').trim();
  if (!key) return;
  const modifiers = {
    ctrlKey: payload.ctrlKey === true,
    altKey: payload.altKey === true,
    metaKey: payload.metaKey === true,
    shiftKey: payload.shiftKey === true,
  };
  appendRecordedNativeTeachStep(state, createBrowserTeachKeyStep(key, modifiers, state), `press ${key}`);
}

function handleNativeBrowserTeachScroll(payload) {
  if (!payload || typeof payload !== 'object') return;
  const state = nativeTeachRecordingState();
  if (!state) return;
  const deltaX = Number(payload.deltaX || 0);
  const deltaY = Number(payload.deltaY || 0);
  if (Math.abs(deltaX) < 40 && Math.abs(deltaY) < 40) return;
  // The preload already debounces a scroll burst into one event, so record each
  // deliberate burst as its own step (preserves scroll distance on replay).
  const point = { x: 60, y: 200 };
  appendRecordedNativeTeachStep(state, createBrowserTeachScrollStep(point, deltaX, deltaY, state), 'scroll');
}

function truncateBrowserPreview(value, max = 80) {
  const str = String(value ?? '');
  if (str.length <= max) return str;
  const parenIdx = str.indexOf('(');
  if (parenIdx > 0 && parenIdx < max) {
    const head = str.slice(0, parenIdx).trim();
    return `${head}(…)`;
  }
  return `${str.slice(0, max - 1).trim()}…`;
}

function formatBrowserCanvasTimestamp(value) {
  const timestamp = Number(value || 0);
  if (!timestamp) return 'Waiting for browser activity';
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return 'Waiting for browser activity';
  return `Updated ${date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit', second: '2-digit' })}`;
}

function suggestBrowserElementName(element) {
  if (!element || typeof element !== 'object') return '';
  const id = String(element.id || '').trim();
  if (id) return id.replace(/[-_]+/g, ' ').trim();
  const selector = String(element.selector || '').trim();
  const selectorMatch = selector.match(/([a-z0-9_-]+)(?::nth-of-type\(\d+\))?$/i);
  if (selectorMatch?.[1]) return selectorMatch[1].replace(/[-_]+/g, ' ').trim();
  const text = String(element.text || '').replace(/\s+/g, ' ').trim();
  if (text) return text.slice(0, 48);
  return String(element.tagName || 'element').trim();
}

function getSelectedBrowserElementKey(element = getBrowserCanvasState().selectedElement) {
  if (!element || typeof element !== 'object') return '';
  return [
    String(element.selector || '').trim(),
    String(element.id || '').trim(),
    String(element.tagName || '').trim(),
    String(element.text || '').trim().slice(0, 80),
  ].join('|');
}

function getCanvasWidthLockMessage(tab = getActiveCanvasTab()) {
  const creativeMeta = getCreativeModeMeta(window.currentCreativeMode);
  if (creativeMeta) return `Exit ${creativeMeta.title} to resize the canvas.`;
  if (canvasOpen && isPreviewLikeCanvasTab(tab)) {
    return 'Switch the canvas back to code to resize the panel.';
  }
  return '';
}

function isCanvasWidthLocked(tab = getActiveCanvasTab()) {
  return !!getCanvasWidthLockMessage(tab);
}

function syncCanvasSurfaceWidthLock(tab = getActiveCanvasTab()) {
  const rightPanel = document.getElementById('right-panel');
  if (!rightPanel) return;
  clampCanvasPanelToWorkspace();
  if (isCreativeModeLocked()) {
    updateCreativeModeControls();
    if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
    return;
  }
  if (canvasOpen && isBrowserCanvasSurfaceActive()) {
    restoreCanvasPreviewSavedPanelWidth(rightPanel);
    applyBrowserCanvasPanelDefault();
    updateCreativeModeControls();
    if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
    return;
  }
  const shouldLock = !!(canvasOpen && isPreviewLikeCanvasTab(tab));
  if (shouldLock) {
    if (canvasPreviewSavedPanelWidth === null) {
      const measuredWidth = rightPanel.offsetWidth || 0;
      canvasPreviewSavedPanelWidth =
        rightPanel.style.width
        || rightPanel.style.minWidth
        || (measuredWidth ? `${measuredWidth}px` : '');
    }
    setRightPanelWidth(IMMERSIVE_CANVAS_PANEL_WIDTH, { minimumWidth: 960, lockMax: true });
  } else if (canvasPreviewSavedPanelWidth !== null) {
    restoreCanvasPreviewSavedPanelWidth(rightPanel);
  }
  updateCreativeModeControls();
  if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
}

function getCanvasPreviewDevice() {
  return CANVAS_PREVIEW_DEVICES[canvasPreviewDevice] ? canvasPreviewDevice : 'responsive';
}

function setCanvasPreviewDevice(deviceKey) {
  canvasPreviewDevice = CANVAS_PREVIEW_DEVICES[deviceKey] ? deviceKey : 'responsive';
  syncCanvasPreviewDeviceFrame();
  const tab = getActiveCanvasTab();
  if (tab?.mode === 'preview' || tab?.isImage || tab?.isBinary) {
    addProcessEntry('info', `Preview device: ${CANVAS_PREVIEW_DEVICES[canvasPreviewDevice].label}.`);
  }
}

function syncCanvasPreviewDeviceFrame() {
  const shell = document.getElementById('canvas-preview-shell');
  const stage = document.getElementById('canvas-preview-stage');
  const deviceFrame = document.getElementById('canvas-preview-device-frame');
  const iframe = document.getElementById('canvas-preview-frame');
  const sizeLabel = document.getElementById('canvas-preview-size-label');
  if (!shell || !stage || !deviceFrame || !iframe) return;

  const key = getCanvasPreviewDevice();
  const device = CANVAS_PREVIEW_DEVICES[key];
  shell.dataset.device = key;
  document.querySelectorAll('[data-canvas-preview-device]').forEach((button) => {
    button.classList.toggle('active', button.getAttribute('data-canvas-preview-device') === key);
  });

  if (key === 'responsive') {
    stage.style.overflow = 'hidden';
    deviceFrame.style.width = '100%';
    deviceFrame.style.height = '100%';
    deviceFrame.style.padding = '0';
    iframe.style.width = '100%';
    iframe.style.height = '100%';
    iframe.style.transform = '';
    iframe.style.borderRadius = '0';
    iframe.style.boxShadow = '';
    if (sizeLabel) sizeLabel.textContent = 'Fluid viewport';
    return;
  }

  const stageRect = stage.getBoundingClientRect();
  const availableWidth = Math.max(240, stageRect.width - 48);
  const availableHeight = Math.max(320, stageRect.height - 48);
  const scale = Math.min(1, availableWidth / device.width, availableHeight / device.height);
  const scaledWidth = Math.round(device.width * scale);
  const scaledHeight = Math.round(device.height * scale);
  stage.style.overflow = 'auto';
  deviceFrame.style.width = `${scaledWidth}px`;
  deviceFrame.style.height = `${scaledHeight}px`;
  deviceFrame.style.padding = '0';
  iframe.style.width = `${device.width}px`;
  iframe.style.height = `${device.height}px`;
  iframe.style.transform = `scale(${scale})`;
  iframe.style.borderRadius = '28px';
  iframe.style.boxShadow = '0 24px 70px rgba(0,0,0,0.45)';
  if (sizeLabel) sizeLabel.textContent = `${device.width} x ${device.height}`;
}

function getActiveChatSessionRecord() {
  return (window.chatSessions || []).find(s => s.id === window.activeChatSessionId) || null;
}

function isCreativeModeLocked() {
  return !!normalizeCreativeMode(window.currentCreativeMode);
}

function shouldHideCenterColumnForImmersivePanels() {
  if (String(window.currentMode || 'chat') !== 'chat') return false;
  const sidebar = document.getElementById('sidebar');
  const rightPanel = document.getElementById('right-panel');
  const workspace = document.getElementById('workspace');
  if (!sidebar || !rightPanel || !workspace) return false;
  if (sidebar.classList.contains('collapsed')) return false;
  if (!rightPanel.classList.contains('open')) return false;
  // With the primary sidebar open, a Design workspace should be genuinely
  // immersive. Keeping a narrow live-chat strip beside it only produces a
  // clipped, unusable column.
  if (isCreativeModeLocked() && rightPanel.classList.contains('canvas-open')) return true;
  const immersiveRightPanelActive = isCreativeModeLocked() || (canvasOpen && isBrowserCanvasSurfaceActive());
  if (!immersiveRightPanelActive) return false;
  const workspaceWidth = workspace.getBoundingClientRect().width || workspace.clientWidth || 0;
  const rightPanelWidth =
    rightPanel.getBoundingClientRect().width
    || rightPanel.offsetWidth
    || Number.parseFloat(rightPanel.style.width)
    || Number.parseFloat(rightPanel.style.minWidth)
    || 0;
  const minimumCenterWidth = isCreativeModeLocked()
    ? CANVAS_CHAT_COLUMN_HARD_MIN_WIDTH
    : CANVAS_CHAT_COLUMN_MIN_WIDTH;
  return (workspaceWidth - rightPanelWidth) < minimumCenterWidth;
}

function syncCenterColumnVisibility() {
  const body = document.body;
  const centerCol = document.getElementById('centerCol');
  const shouldHide = shouldHideCenterColumnForImmersivePanels();
  const wasHidden = body?.classList.contains('immersive-center-hidden') === true;
  if (body) body.classList.toggle('immersive-center-hidden', shouldHide);
  if (centerCol) {
    if (shouldHide) centerCol.setAttribute('aria-hidden', 'true');
    else centerCol.removeAttribute('aria-hidden');
  }
  const rightPanel = document.getElementById('right-panel');
  const workspace = document.getElementById('workspace');
  if (shouldHide && rightPanel && workspace && isCreativeModeLocked()) {
    const workspaceWidth = workspace.getBoundingClientRect().width || workspace.clientWidth || 0;
    if (workspaceWidth) {
      setRightPanelWidth(workspaceWidth, { minimumWidth: 1, preserveChatColumn: false });
    }
  } else if (wasHidden && rightPanel && canvasOpen && isCreativeModeLocked()) {
    // Returning the Chat column (for example when the sidebar is collapsed)
    // also restores the normal capped creative width.
    setRightPanelWidth(CREATIVE_MODE_PANEL_WIDTH, {
      minimumWidth: 960,
      lockMax: true,
      preserveChatColumn: true,
    });
  }
}

function updateCreativeModeControls() {
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  const meta = getCreativeModeMeta(mode);
  const widthLockMessage = getCanvasWidthLockMessage();
  const browserState = getBrowserCanvasState();
  const browserSurfaceActive = isBrowserCanvasSurfaceActive();
  const badge = document.getElementById('creative-mode-badge');
  const canvasToggleBtn = document.getElementById('canvas-toggle-btn');
  const backBtn = document.getElementById('canvas-context-btn');
  const resizeHandle = document.getElementById('rp-resize');
  const exitButtons = document.querySelectorAll('[data-creative-mode-exit]');
  const modeButtons = document.querySelectorAll('[data-creative-mode-btn]');
  const browserSurfaceButtons = [
    document.getElementById('canvas-browser-surface-btn'),
    document.getElementById('right-panel-browser-surface-btn'),
  ].filter(Boolean);
  const browserModeRail = document.getElementById('canvas-browser-mode-rail');
  const browserLiveDots = [
    document.getElementById('canvas-browser-live-dot'),
    document.getElementById('right-panel-browser-live-dot'),
  ].filter(Boolean);
  const browserModeButtons = document.querySelectorAll('[data-browser-mode-btn]');
  const root = document.documentElement;

  if (root) root.dataset.creativeMode = mode || '';
  if (document.body) document.body.classList.toggle('browser-surface-active', browserSurfaceActive);

  if (badge) {
    if (meta) {
      badge.style.display = 'inline-flex';
      badge.style.borderColor = meta.accent;
      badge.style.background = meta.glow;
      badge.style.color = meta.accent;
      badge.textContent = `${meta.title} active`;
    } else {
      badge.style.display = 'none';
      badge.textContent = '';
    }
  }

  modeButtons.forEach((btn) => {
    const btnMode = normalizeCreativeMode(btn.dataset.creativeModeBtn);
    const browserDesignActive = browserSurfaceActive
      && browserState.browserDesignMode === true
      && btnMode === 'design';
    const active = browserDesignActive || (!!mode && btnMode === mode);
    const activeAccent = browserDesignActive ? '#38bdf8' : (meta?.accent || 'rgba(255,255,255,0.18)');
    const activeGlow = browserDesignActive ? 'rgba(56,189,248,0.2)' : (meta?.glow || 'rgba(255,255,255,0.06)');
    btn.dataset.active = active ? 'true' : 'false';
    btn.style.borderColor = active ? activeAccent : 'rgba(255,255,255,0.12)';
    btn.style.background = active ? activeGlow : 'rgba(255,255,255,0.06)';
    btn.style.color = active ? (browserDesignActive ? '#e0f2fe' : (meta?.accent || '#e8e6e1')) : '#9a9890';
    if (btnMode === 'design' && browserSurfaceActive) {
      btn.title = browserDesignActive ? 'Close Browser Design mode' : 'Enter Browser Design mode';
    }
  });

  exitButtons.forEach((btn) => {
    btn.style.display = meta ? 'inline-flex' : 'none';
  });
  browserSurfaceButtons.forEach((btn) => {
    btn.dataset.active = browserSurfaceActive ? 'true' : 'false';
    btn.title = browserSurfaceActive ? 'Close browser surface' : 'Show browser activity';
  });
  browserModeButtons.forEach((btn) => {
    const btnMode = normalizeBrowserInteractionMode(btn.dataset.browserModeBtn);
    const active = browserSurfaceActive && !browserState.browserDesignMode && btnMode === normalizeBrowserInteractionMode(browserState.interactionMode);
    btn.dataset.active = active ? 'true' : 'false';
  });
  browserLiveDots.forEach((dot) => {
    dot.style.display = browserState.active ? 'inline-flex' : 'none';
  });
  if (browserModeRail) browserModeRail.style.display = browserSurfaceActive ? 'inline-flex' : 'none';

  if (canvasToggleBtn) {
    const browserInHouseActive = browserState.active === true && isBrowserCanvasInHouseProvider(browserState);
    canvasToggleBtn.classList.toggle('browser-live', browserInHouseActive);
    canvasToggleBtn.title = browserInHouseActive
      ? 'Open Canvas — in-app browser active'
      : (meta ? `${meta.title} is active` : 'Open Canvas');
    canvasToggleBtn.setAttribute('aria-label', browserInHouseActive
      ? 'Open Canvas — in-app browser active'
      : (meta ? `${meta.title} is active` : (canvasOpen ? 'Close Canvas' : 'Open Canvas')));
    canvasToggleBtn.setAttribute('aria-pressed', canvasOpen ? 'true' : 'false');
  }
  if (backBtn) {
    backBtn.title = canvasOpen ? 'Close Canvas' : 'Back to Context';
  }
  if (resizeHandle) {
    resizeHandle.style.opacity = widthLockMessage ? '0.45' : '';
    resizeHandle.style.cursor = widthLockMessage ? 'not-allowed' : '';
    resizeHandle.title = widthLockMessage || 'Drag to resize';
  }
}

function renderNativeBrowserTabs(state, nativeProvider) {
  const tabsEl = document.getElementById('browser-canvas-native-tabs');
  if (!tabsEl) return;
  const tabs = normalizeNativeBrowserTabs(state.nativeTabs);
  if (!nativeProvider || !state.active) {
    tabsEl.style.display = 'none';
    tabsEl.innerHTML = '';
    return;
  }
  const activeTabId = String(state.activeNativeTabId || '').trim();
  tabsEl.style.display = 'flex';
  tabsEl.innerHTML = `${tabs.map((tab) => {
    const tabIdArg = JSON.stringify(tab.id).replace(/"/g, '&quot;');
    const active = tab.id === activeTabId || (!activeTabId && tab.active);
    const title = tab.title || (tab.url === 'about:blank' ? 'New Tab' : tab.url);
    return `
      <div class="browser-native-tab${active ? ' active' : ''}" role="tab" aria-selected="${active ? 'true' : 'false'}" tabindex="0" onclick="selectNativeBrowserCanvasTab(${tabIdArg}, event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();selectNativeBrowserCanvasTab(${tabIdArg}, event)}" title="${escHtml(tab.url || title)}">
        <span style="width:7px;height:7px;border-radius:999px;background:${tab.loading ? '#fbbf24' : (active ? '#38bdf8' : '#64748b')};flex:0 0 auto"></span>
        <span class="browser-native-tab-title">${escHtml(title)}</span>
        <button class="browser-native-tab-close" type="button" title="Close tab" aria-label="Close ${escHtml(title)}" onclick="closeNativeBrowserCanvasTab(${tabIdArg}, event)">×</button>
      </div>
    `;
  }).join('')}
  <button class="browser-native-tab-new" type="button" title="New tab" aria-label="New tab" onclick="newNativeBrowserCanvasTab()">+</button>`;
}

let browserSurfaceRendererModule = null;
let browserSurfaceRendererPromise = null;
let browserSurfaceRenderQueued = false;

function shouldLoadBrowserSurfaceRenderer() {
  const state = getBrowserCanvasState();
  const activeTab = getActiveCanvasTab();
  return !!(
    state?.active
    || state?.loading
    || state?.lastError
    || state?.url
    || state?.selectedElement
    || browserCanvasStream?.active
    || nativeBrowserSurface?.active
    || (canvasOpen && activeTab?.mode === 'browser')
  );
}

function loadBrowserSurfaceRenderer() {
  if (browserSurfaceRendererModule) return Promise.resolve(browserSurfaceRendererModule);
  if (!browserSurfaceRendererPromise) {
    browserSurfaceRendererPromise = import('../features/chat/optional/browser-surface-renderer.js')
      .then((module) => {
        browserSurfaceRendererModule = module;
        return module;
      })
      .catch((error) => {
        browserSurfaceRendererPromise = null;
        throw error;
      });
  }
  return browserSurfaceRendererPromise;
}

const browserSurfaceRendererContext = Object.freeze(Object.defineProperties({}, {
  "cloneBrowserDesignSelection": { enumerable: true, get: () => cloneBrowserDesignSelection },
  "ensureBrowserCanvasControlBindings": { enumerable: true, get: () => ensureBrowserCanvasControlBindings },
  "ensureBrowserCanvasFrameMetaResizeObserver": { enumerable: true, get: () => ensureBrowserCanvasFrameMetaResizeObserver },
  "ensureBrowserCanvasGlobalControlBindings": { enumerable: true, get: () => ensureBrowserCanvasGlobalControlBindings },
  "ensureBrowserCanvasHoverBindings": { enumerable: true, get: () => ensureBrowserCanvasHoverBindings },
  "escHtml": { enumerable: true, get: () => escHtml },
  "formatBrowserCanvasTimestamp": { enumerable: true, get: () => formatBrowserCanvasTimestamp },
  "getBrowserCanvasRestoreHint": { enumerable: true, get: () => getBrowserCanvasRestoreHint },
  "getBrowserCanvasState": { enumerable: true, get: () => getBrowserCanvasState },
  "getBrowserCanvasVisibleSessionId": { enumerable: true, get: () => getBrowserCanvasVisibleSessionId },
  "getBrowserDesignAnnotationSelections": { enumerable: true, get: () => getBrowserDesignAnnotationSelections },
  "getBrowserInteractionMeta": { enumerable: true, get: () => getBrowserInteractionMeta },
  "getBrowserSessionRecord": { enumerable: true, get: () => getBrowserSessionRecord },
  "getBrowserTeachSession": { enumerable: true, get: () => getBrowserTeachSession },
  "getSelectedBrowserElementKey": { enumerable: true, get: () => getSelectedBrowserElementKey },
  "hasActiveBrowserTeachSession": { enumerable: true, get: () => hasActiveBrowserTeachSession },
  "isBrowserCanvasInHouseProvider": { enumerable: true, get: () => isBrowserCanvasInHouseProvider },
  "isBrowserDesignMode": { enumerable: true, get: () => isBrowserDesignMode },
  "isBrowserTeachAwaitingApproval": { enumerable: true, get: () => isBrowserTeachAwaitingApproval },
  "isBrowserTeachRecording": { enumerable: true, get: () => isBrowserTeachRecording },
  "isBrowserTeachVerified": { enumerable: true, get: () => isBrowserTeachVerified },
  "isFollowingDetachedBrowserCanvasSession": { enumerable: true, get: () => isFollowingDetachedBrowserCanvasSession },
  "isRestorableBrowserCanvasUrl": { enumerable: true, get: () => isRestorableBrowserCanvasUrl },
  "normalizeBrowserInteractionMode": { enumerable: true, get: () => normalizeBrowserInteractionMode },
  "queueNativeBrowserSurfaceSync": { enumerable: true, get: () => queueNativeBrowserSurfaceSync },
  "renderNativeBrowserTabs": { enumerable: true, get: () => renderNativeBrowserTabs },
  "renderSourcesMinimizedPanel": { enumerable: true, get: () => renderSourcesMinimizedPanel },
  "suggestBrowserElementName": { enumerable: true, get: () => suggestBrowserElementName },
  "summarizeBrowserTeachTarget": { enumerable: true, get: () => summarizeBrowserTeachTarget },
  "syncBrowserCanvasFrameLayout": { enumerable: true, get: () => syncBrowserCanvasFrameLayout },
  "syncBrowserCanvasStream": { enumerable: true, get: () => syncBrowserCanvasStream },
  "syncNativeBrowserDesignMode": { enumerable: true, get: () => syncNativeBrowserDesignMode },
  "syncNativeBrowserTeachCapture": { enumerable: true, get: () => syncNativeBrowserTeachCapture },
  "truncateBrowserPreview": { enumerable: true, get: () => truncateBrowserPreview },
  "updateBrowserAgentCursorOverlay": { enumerable: true, get: () => updateBrowserAgentCursorOverlay },
  "updateBrowserHoverOverlay": { enumerable: true, get: () => updateBrowserHoverOverlay },
  "updateBrowserSelectionOverlay": { enumerable: true, get: () => updateBrowserSelectionOverlay },
  "updateBrowserTransientHighlight": { enumerable: true, get: () => updateBrowserTransientHighlight },
  "updateCreativeModeControls": { enumerable: true, get: () => updateCreativeModeControls },
  "updateDesignSelectionChip": { enumerable: true, get: () => updateDesignSelectionChip },
}));

function renderBrowserCanvasSurface() {
  if (browserSurfaceRendererModule) {
    return browserSurfaceRendererModule.renderBrowserCanvasSurface(browserSurfaceRendererContext);
  }
  if (!shouldLoadBrowserSurfaceRenderer() || browserSurfaceRenderQueued) return undefined;
  browserSurfaceRenderQueued = true;
  void loadBrowserSurfaceRenderer()
    .then((module) => module.renderBrowserCanvasSurface(browserSurfaceRendererContext))
    .catch((error) => console.warn('[Browser Canvas] optional renderer failed to load:', error))
    .finally(() => { browserSurfaceRenderQueued = false; });
  return undefined;
}

function setBrowserCanvasSurface(surface, options = {}) {
  const nextSurface = String(surface || '').trim().toLowerCase() === 'browser' ? 'browser' : 'files';
  const state = getBrowserCanvasState();
  const changed = state.surface !== nextSurface;
  state.surface = nextSurface;
  if (changed && nextSurface !== 'browser') browserCanvasPanelWidthMode = '';
  if (nextSurface === 'browser' && options.autoOpen !== false && !canvasOpen) {
    toggleCanvas(true, { force: true });
  }
  const activeTab = getActiveCanvasTab();
  if (canvasOpen || nextSurface === 'browser') {
    applyCanvasViewMode(activeTab?.mode || 'code', activeTab || null);
    canvasRenderTabs();
  } else if (changed) {
    updateCreativeModeControls();
  }
  renderBrowserCanvasSurface();
  syncCanvasSurfaceWidthLock(activeTab || null);
}

async function openBrowserCanvasSurface() {
  const preserveDesignIntent = normalizeCreativeMode(window.currentCreativeMode) === 'design';
  try {
    await exitCreativeModeForBrowserSwitch();
  } catch (err) {
    showToast(`Could not open Browser mode: ${err.message}`, 'error');
    return;
  }
  const browserState = getBrowserCanvasState();
  const nativeSurfaceAvailable = !!getNativeBrowserSurfaceApi();
  if (nativeSurfaceAvailable || !browserState.active || isBrowserCanvasInHouseProvider(browserState)) {
    try {
      if (await openDirectNativeBrowserSurface()) {
        if (preserveDesignIntent) setBrowserDesignMode(true, { persist: false });
        return;
      }
    } catch (err) {
      showToast(`Could not open Browser mode: ${String(err?.message || err || 'Electron browser unavailable.')}`, 'error');
      return;
    }
  }
  setBrowserCanvasSurface('browser');
  if (preserveDesignIntent) setBrowserDesignMode(true, { persist: false });
  window.requestAnimationFrame?.(() => document.getElementById('browser-canvas-address-input')?.focus?.({ preventScroll: true }));
}

async function toggleBrowserCanvasSurface() {
  if (isBrowserCanvasSurfaceActive()) {
    showCanvasFilesSurface();
    if (canvasOpen) toggleCanvas(false);
    else updateCreativeModeControls();
    return;
  }
  await openBrowserCanvasSurface();
}

function showCanvasFilesSurface() {
  setBrowserCanvasSurface('files', { autoOpen: false });
}

function setBrowserDesignMode(enabled, options = {}) {
  const state = getBrowserCanvasState();
  const next = enabled === true;
  state.browserDesignMode = next;
  if (!next) {
    state.browserDesignSelectMode = false;
    state.browserDesignSelections = [];
    state.hoverElement = null;
    hideBrowserDesignPopovers();
  } else if (options.clearSelection === true) {
    state.selectedElement = null;
    state.browserDesignSelections = [];
  }
  if (next) state.statusLabel = 'Design mode is ready. Hover an element, then click to inspect it.';
  if (options.render !== false) renderBrowserCanvasSurface();
  if (options.persist !== false) persistActiveChat();
  void syncNativeBrowserDesignMode(state);
  return next;
}

async function toggleBrowserDesignMode() {
  if (!isBrowserCanvasSurfaceActive()) {
    await openBrowserCanvasSurface();
    if (!isBrowserCanvasSurfaceActive()) return false;
  }
  const state = getBrowserCanvasState();
  const enabled = !isBrowserDesignMode(state);
  setBrowserDesignMode(enabled);
  showToast(enabled ? 'Browser Design mode enabled' : 'Browser Design mode closed', 'info', 2200);
  return enabled;
}

async function setBrowserInteractionMode(mode) {
  try {
    await exitCreativeModeForBrowserSwitch();
  } catch (err) {
    showToast(`Could not switch Browser mode: ${err.message}`, 'error');
    return;
  }
  const state = getBrowserCanvasState();
  const nextMode = normalizeBrowserInteractionMode(mode);
  if (state.browserDesignMode) setBrowserDesignMode(false, { persist: false, render: false });
  if (state.interactionMode === nextMode && isBrowserCanvasSurfaceActive()) {
    renderBrowserCanvasSurface();
    return;
  }
  state.interactionMode = nextMode;
  if (nextMode !== 'copilot' && nextMode !== 'teach' && state.controlCaptured) {
    syncBrowserControlCapture(false, {
      owner: 'agent',
      reason: `Browser interaction mode changed to ${nextMode}.`,
      statusLabel: `Browser interaction mode is now ${nextMode}.`,
      render: false,
      syncRemote: true,
      flushPending: false,
    });
  }
  renderBrowserCanvasSurface();
  if (!isBrowserCanvasSurfaceActive()) setBrowserCanvasSurface('browser');
  else syncCanvasSurfaceWidthLock(getActiveCanvasTab());
  const sessionId = getBrowserCanvasPrimarySessionId();
  if (sessionId) {
    wsSend({ type: 'browser:mode:set', sessionId, mode: nextMode });
  }
}

function syncBrowserCanvasFrameLayout(frameWrap, frameMeta, frameEl) {
  if (frameWrap) {
    frameWrap.style.flexDirection = 'column';
    frameWrap.style.alignItems = 'stretch';
    frameWrap.style.justifyContent = 'flex-start';
  }
  if (!frameMeta || !frameEl) return;
  const state = getBrowserCanvasState();
  const nativeProvider = isBrowserCanvasInHouseProvider(state);
  const stageEl = frameEl.parentElement;
  const viewportWidth = Math.max(1, Number(state.frameViewportWidth || state.frameWidth || frameEl.naturalWidth || 1280) || 1280);
  const viewportHeight = Math.max(1, Number(state.frameViewportHeight || state.frameHeight || frameEl.naturalHeight || 720) || 720);
  const wrapRectWidth = Number(frameWrap?.clientWidth || frameWrap?.getBoundingClientRect?.().width || 0);
  const surfaceInset = nativeProvider ? 0 : 24;
  const availableWidth = nativeProvider
    ? Math.max(1, Math.floor(wrapRectWidth) - surfaceInset)
    : Math.max(220, Math.floor(wrapRectWidth) - surfaceInset);
  const metaHeight = frameMeta.style.display === 'none' ? 0 : (Number(frameMeta.offsetHeight || 0) + 12);
  const availableHeight = nativeProvider
    ? Math.max(1, Number(frameWrap?.clientHeight || 0) - metaHeight - surfaceInset)
    : Math.max(160, Number(frameWrap?.clientHeight || 0) - metaHeight - surfaceInset);
  const widthFirstHeight = Math.floor(availableWidth * (viewportHeight / viewportWidth));
  const renderWidth = Math.max(220, Math.floor(availableWidth));
  const renderHeight = Math.max(124, Math.min(availableHeight, widthFirstHeight));
  if (stageEl) {
    if (nativeProvider) {
      // The native WebContentsView can render at any size, so let it fill the
      // whole card instead of locking to a screenshot's fixed aspect ratio.
      stageEl.style.width = `${Math.floor(availableWidth)}px`;
      stageEl.style.height = `${Math.floor(availableHeight)}px`;
      stageEl.style.maxWidth = '100%';
      stageEl.style.maxHeight = 'none';
      stageEl.style.margin = '0';
    } else {
      stageEl.style.width = `${renderWidth}px`;
      stageEl.style.height = `${renderHeight}px`;
      stageEl.style.maxWidth = '100%';
    }
  }
  const frameWidth = nativeProvider
    ? (stageEl?.getBoundingClientRect?.().width || stageEl?.clientWidth || 0)
    : (frameEl.getBoundingClientRect().width || frameEl.clientWidth || 0);
  if (frameWidth > 0) {
    frameMeta.style.width = `${frameWidth}px`;
    frameMeta.style.maxWidth = '100%';
  } else {
    frameMeta.style.width = '';
    frameMeta.style.maxWidth = '';
  }
}

// Keep the meta strip + every overlay aligned with the streamed <img> when the panel
// (or the window) is resized, even outside of full re-renders. Previously frameMeta
// only resynced inside renderBrowserCanvasSurface, so it drifted while idle.
let browserCanvasFrameMetaResizeObserver = null;
function ensureBrowserCanvasFrameMetaResizeObserver(frameWrap, frameMeta, frameEl) {
  if (!frameWrap || !frameMeta || !frameEl || typeof ResizeObserver === 'undefined') return;
  if (browserCanvasFrameMetaResizeObserver) return;
  browserCanvasFrameMetaResizeObserver = new ResizeObserver(() => {
    const wrap = document.getElementById('browser-canvas-frame-wrap');
    const meta = document.getElementById('browser-canvas-frame-meta');
    const img = document.getElementById('browser-canvas-frame');
    if (!wrap || !meta || !img) return;
    syncBrowserCanvasFrameLayout(wrap, meta, img);
    syncNativeBrowserSurface();
    const state = getBrowserCanvasState();
    updateBrowserSelectionOverlay(document.getElementById('browser-canvas-selection-box'), img, state);
    updateBrowserTransientHighlight(document.getElementById('browser-canvas-click-highlight'), img, state);
    updateBrowserHoverOverlay();
    updateBrowserAgentCursorOverlay(document.getElementById('browser-canvas-agent-cursor'), img, state);
  });
  try { browserCanvasFrameMetaResizeObserver.observe(frameWrap); } catch {}
  try { browserCanvasFrameMetaResizeObserver.observe(frameEl); } catch {}
}

function positionBrowserOverlayElement(overlayEl, frameEl, bounds, options = {}) {
  if (!overlayEl || !frameEl || !bounds) return false;
  const state = options.state || getBrowserCanvasState();
  // Bounds arrive in CSS-px viewport coordinates from the page's getBoundingClientRect().
  // The streamed bitmap covers that same viewport box, so we map by:
  //   1. CSS-px viewport (state.frameViewportWidth/Height) → bitmap pixels (state.frameBitmapWidth/Height)
  //   2. bitmap pixels → on-screen rendered <img> size (frameRect inner box)
  // No magic nudge required — the prior 10/6 nudge was masking a missing DPR step.
  const viewportWidth = Number(state?.frameViewportWidth || state?.frameWidth || 0);
  const viewportHeight = Number(state?.frameViewportHeight || state?.frameHeight || 0);
  if (!viewportWidth || !viewportHeight) {
    overlayEl.style.display = 'none';
    return false;
  }
  const frameWrap = frameEl.parentElement;
  const frameRect = frameEl.getBoundingClientRect();
  const wrapRect = frameWrap?.getBoundingClientRect?.();
  if (!frameRect.width || !frameRect.height || !wrapRect?.width || !wrapRect?.height) {
    overlayEl.style.display = 'none';
    return false;
  }
  const computed = window.getComputedStyle(frameEl);
  const borderLeft = parseFloat(computed.borderLeftWidth) || 0;
  const borderTop = parseFloat(computed.borderTopWidth) || 0;
  const borderRight = parseFloat(computed.borderRightWidth) || 0;
  const borderBottom = parseFloat(computed.borderBottomWidth) || 0;
  const innerWidth = frameRect.width - borderLeft - borderRight;
  const innerHeight = frameRect.height - borderTop - borderBottom;
  if (innerWidth <= 0 || innerHeight <= 0) {
    overlayEl.style.display = 'none';
    return false;
  }
  // bounds.x/y are already in CSS-px viewport-relative coords. We map directly to the inner <img> box.
  const scaleX = innerWidth / viewportWidth;
  const scaleY = innerHeight / viewportHeight;
  const originLeft = frameRect.left - wrapRect.left + borderLeft;
  const originTop = frameRect.top - wrapRect.top + borderTop;
  const boundX = Number(bounds.x) || 0;
  const boundY = Number(bounds.y) || 0;
  const boundW = Number(bounds.width) || 0;
  const boundH = Number(bounds.height) || 0;
  // Use subpixel CSS — the browser handles rendering crisp lines at fractional positions.
  // No Math.max floor: small elements get small boxes. Optional padding can expand the visible
  // outline if the caller really needs minimum size, but we don't impose it by default.
  const padding = Number(options.padding) || 0;
  overlayEl.style.left = `${originLeft + boundX * scaleX - padding}px`;
  overlayEl.style.top = `${originTop + boundY * scaleY - padding}px`;
  overlayEl.style.width = `${Math.max(0, boundW * scaleX + padding * 2)}px`;
  overlayEl.style.height = `${Math.max(0, boundH * scaleY + padding * 2)}px`;
  return true;
}

function updateBrowserSelectionOverlay(selectionBox, frameEl, state = getBrowserCanvasState()) {
  if (!selectionBox || !frameEl) return;
  const mode = normalizeBrowserInteractionMode(state?.interactionMode);
  if (isFollowingDetachedBrowserCanvasSession(state) || (!isBrowserDesignMode(state) && mode !== 'teach' && mode !== 'copilot')) {
    selectionBox.style.display = 'none';
    return;
  }
  // Prefer the live-tracked bounds (re-resolved by the server every frame) so the box
  // sticks to the element through scroll/layout shifts. Fall back to the snapshot
  // captured at click time.
  const live = state?.selectedElement?.liveBounds;
  const bounds = (live && Number.isFinite(live.width) && live.width > 0) ? live : state?.selectedElement?.bounds;
  if (!bounds || !positionBrowserOverlayElement(selectionBox, frameEl, bounds, { state })) {
    selectionBox.style.display = 'none';
    return;
  }
  selectionBox.style.display = 'block';
}

function updateBrowserTransientHighlight(highlightEl, frameEl, state = getBrowserCanvasState()) {
  if (!highlightEl || !frameEl) return;
  if (isFollowingDetachedBrowserCanvasSession(state)) {
    highlightEl.style.display = 'none';
    return;
  }
  const highlight = state?.transientHighlight;
  if (!highlight?.bounds || Number(highlight?.expiresAt || 0) <= Date.now()) {
    highlightEl.style.display = 'none';
    return;
  }
  if (!positionBrowserOverlayElement(highlightEl, frameEl, highlight.bounds)) {
    highlightEl.style.display = 'none';
    return;
  }
  highlightEl.style.display = 'block';
}

function updateBrowserAgentCursorOverlay(cursorEl, frameEl, state = getBrowserCanvasState()) {
  if (!cursorEl || !frameEl) return;
  const cursor = state?.agentCursor;
  const viewportWidth = Number(cursor?.viewportWidth || state?.frameViewportWidth || state?.frameWidth || 0);
  const viewportHeight = Number(cursor?.viewportHeight || state?.frameViewportHeight || state?.frameHeight || 0);
  const x = Number(cursor?.x);
  const y = Number(cursor?.y);
  if (!cursor || !Number.isFinite(x) || !Number.isFinite(y) || !viewportWidth || !viewportHeight) {
    cursorEl.style.display = 'none';
    return;
  }
  if (Number(cursor.expiresAt || 0) <= Date.now()) {
    cursorEl.style.opacity = '0';
    return;
  }
  const frameWrap = frameEl.parentElement;
  const frameRect = frameEl.getBoundingClientRect();
  const wrapRect = frameWrap?.getBoundingClientRect?.();
  if (!frameRect.width || !frameRect.height || !wrapRect?.width || !wrapRect?.height) {
    cursorEl.style.display = 'none';
    return;
  }
  const computed = window.getComputedStyle(frameEl);
  const borderLeft = parseFloat(computed.borderLeftWidth) || 0;
  const borderTop = parseFloat(computed.borderTopWidth) || 0;
  const borderRight = parseFloat(computed.borderRightWidth) || 0;
  const borderBottom = parseFloat(computed.borderBottomWidth) || 0;
  const innerWidth = frameRect.width - borderLeft - borderRight;
  const innerHeight = frameRect.height - borderTop - borderBottom;
  const originLeft = frameRect.left - wrapRect.left + borderLeft;
  const originTop = frameRect.top - wrapRect.top + borderTop;
  const left = originLeft + (x * (innerWidth / viewportWidth));
  const top = originTop + (y * (innerHeight / viewportHeight));
  cursorEl.style.display = 'block';
  cursorEl.style.left = `${left}px`;
  cursorEl.style.top = `${top}px`;
  cursorEl.style.opacity = '1';
  cursorEl.dataset.kind = String(cursor.kind || 'move');
  cursorEl.dataset.phase = String(cursor.phase || 'active');
  const label = cursorEl.querySelector('[data-browser-agent-cursor-label]');
  if (label) {
    const text = String(cursor.label || '').trim();
    label.textContent = text ? truncateBrowserPreview(text, 42) : 'Prometheus';
  }
}

function receiveBrowserAgentCursor(msg) {
  if (!isBrowserEventForActiveSession(msg, { scope: 'visible' })) return;
  const state = getBrowserCanvasState();
  const now = Date.now();
  state.agentCursor = {
    x: Math.round(Number(msg?.x || 0)),
    y: Math.round(Number(msg?.y || 0)),
    viewportWidth: Number(msg?.viewportWidth || state.frameWidth || 0) || 0,
    viewportHeight: Number(msg?.viewportHeight || state.frameHeight || 0) || 0,
    kind: String(msg?.kind || 'move').trim(),
    phase: String(msg?.phase || 'active').trim(),
    label: String(msg?.label || '').trim(),
    updatedAt: Number(msg?.timestamp || now) || now,
    expiresAt: now + 2200,
  };
  const cursorEl = document.getElementById('browser-canvas-agent-cursor');
  const frameEl = document.getElementById('browser-canvas-frame');
  updateBrowserAgentCursorOverlay(cursorEl, frameEl, state);
  window.clearTimeout(window.__browserAgentCursorFadeTimer || 0);
  window.__browserAgentCursorFadeTimer = window.setTimeout(() => {
    const latest = getBrowserCanvasState().agentCursor;
    if (!latest || latest.updatedAt !== state.agentCursor?.updatedAt) return;
    const el = document.getElementById('browser-canvas-agent-cursor');
    if (el) el.style.opacity = '0';
  }, 1800);
}

function clearBrowserTransientHighlight(options = {}) {
  const state = getBrowserCanvasState();
  if (browserTransientHighlightFadeTimer) {
    clearTimeout(browserTransientHighlightFadeTimer);
    browserTransientHighlightFadeTimer = 0;
  }
  if (browserTransientHighlightCleanupTimer) {
    clearTimeout(browserTransientHighlightCleanupTimer);
    browserTransientHighlightCleanupTimer = 0;
  }
  state.transientHighlight = null;
  const highlightEl = document.getElementById('browser-canvas-click-highlight');
  if (highlightEl) {
    highlightEl.style.opacity = '0';
    highlightEl.style.transform = 'scale(1)';
    highlightEl.style.display = 'none';
  }
  if (options.render === true) renderBrowserCanvasSurface();
}

function triggerBrowserTransientHighlight(selection) {
  if (!selection?.bounds) return;
  const state = getBrowserCanvasState();
  const now = Date.now();
  state.transientHighlight = {
    selector: String(selection.selector || '').trim(),
    tagName: String(selection.tagName || '').trim(),
    id: String(selection.id || '').trim(),
    text: String(selection.text || '').trim(),
    bounds: selection.bounds,
    startedAt: now,
    expiresAt: now + 720,
  };
  const highlightEl = document.getElementById('browser-canvas-click-highlight');
  const frameEl = document.getElementById('browser-canvas-frame');
  if (!highlightEl || !frameEl) {
    renderBrowserCanvasSurface();
    return;
  }
  if (browserTransientHighlightFadeTimer) clearTimeout(browserTransientHighlightFadeTimer);
  if (browserTransientHighlightCleanupTimer) clearTimeout(browserTransientHighlightCleanupTimer);
  updateBrowserTransientHighlight(highlightEl, frameEl, state);
  highlightEl.style.opacity = '0';
  highlightEl.style.transform = 'scale(0.985)';
  requestAnimationFrame(() => {
    updateBrowserTransientHighlight(highlightEl, frameEl, state);
    highlightEl.style.opacity = '1';
    highlightEl.style.transform = 'scale(1)';
  });
  browserTransientHighlightFadeTimer = window.setTimeout(() => {
    highlightEl.style.opacity = '0';
    highlightEl.style.transform = 'scale(1.012)';
  }, 360);
  browserTransientHighlightCleanupTimer = window.setTimeout(() => {
    clearBrowserTransientHighlight();
  }, 760);
}

function handleBrowserCanvasFrameLoad() {
  const selectionBox = document.getElementById('browser-canvas-selection-box');
  const clickHighlight = document.getElementById('browser-canvas-click-highlight');
  const agentCursor = document.getElementById('browser-canvas-agent-cursor');
  const frameEl = document.getElementById('browser-canvas-frame');
  const frameWrap = document.getElementById('browser-canvas-frame-wrap');
  const frameMeta = document.getElementById('browser-canvas-frame-meta');
  syncBrowserCanvasFrameLayout(frameWrap, frameMeta, frameEl);
  updateBrowserSelectionOverlay(selectionBox, frameEl, getBrowserCanvasState());
  updateBrowserTransientHighlight(clickHighlight, frameEl, getBrowserCanvasState());
  updateBrowserAgentCursorOverlay(agentCursor, frameEl, getBrowserCanvasState());
}

function inspectBrowserCanvasPoint(event) {
  const state = getBrowserCanvasState();
  if (event?.button && Number(event.button) !== 0) return;
  if (!isBrowserCanvasSurfaceActive()) return;
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  const designMode = isBrowserDesignMode(state);
  if (!designMode && mode !== 'teach' && mode !== 'copilot') return;
  if (isFollowingDetachedBrowserCanvasSession(state)) {
    showToast('The canvas is currently following the detached Teach verifier tab. Return to Main Tab before controlling or selecting the live browser.', 'info');
    return;
  }
  if (typeof event?.preventDefault === 'function') event.preventDefault();
  if (typeof event?.stopPropagation === 'function') event.stopPropagation();
  const point = resolveBrowserCanvasViewportPointFromClient(event?.clientX, event?.clientY);
  if (!point) return;
  const viewportX = point.x;
  const viewportY = point.y;
  const sessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
  if (!sessionId) return;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    showToast('Browser connection is reconnecting. Try again in a second.', 'info');
    return;
  }
  if (designMode) {
    state.selectionPending = true;
    state.statusLabel = 'Inspecting browser element for Design mode...';
    renderBrowserCanvasSurface();
    wsSend({
      type: 'browser:inspect_point',
      sessionId,
      x: viewportX,
      y: viewportY,
      purpose: 'design_select',
      track: true,
    });
    return;
  }
  const teach = getBrowserTeachSession(state);
  // Copilot mode, or teach mode before "Start Teach" — navigate freely like copilot.
  if (mode === 'copilot' || (mode === 'teach' && !isBrowserTeachRecording(state))) {
    captureBrowserCanvasControl('User clicked into the browser canvas.');
    state.statusLabel = 'Sending click to browser...';
    renderBrowserCanvasSurface();
    wsSend({
      type: 'browser:input',
      sessionId,
      action: 'click',
      x: viewportX,
      y: viewportY,
      button: 'left',
    });
    return;
  }
  if (isBrowserTeachRecording(state) && teach.pendingStep) {
    showToast('Continue or discard the current teach step first.', 'info');
    return;
  }
  if (isBrowserTeachRecording(state)) {
    captureBrowserCanvasControl('Teach mode is capturing the next browser step.');
    teach.pendingSelectionIntent = {
      action: 'click',
      x: viewportX,
      y: viewportY,
      button: 'left',
      createdAt: Date.now(),
    };
    state.statusLabel = 'Inspecting the next teach step...';
  } else {
    teach.pendingSelectionIntent = null;
    state.statusLabel = 'Inspecting browser element...';
  }
  state.selectionPending = true;
  renderBrowserCanvasSurface();
  wsSend({
    type: 'browser:inspect_point',
    sessionId,
    x: viewportX,
    y: viewportY,
    purpose: 'select',
    track: true,
  });
}

// ─── Live hover inspect ───────────────────────────────────────────────────────
// We keep a recent "interactable map" (selector packs + bounds) snapshot client-side
// and hit-test mousemoves locally — no round-trip per move. We still fall back to
// a throttled server inspect_point for elements that aren't in the local map.

const BROWSER_INTERACTABLE_MAP_TTL_MS = 1800;
const BROWSER_HOVER_FALLBACK_MIN_INTERVAL_MS = 140;
let browserHoverRafHandle = 0;
let browserHoverPendingPoint = null;
let browserLastHoverFallbackAt = 0;
let browserLastHoverFingerprint = '';

function maybeRequestBrowserInteractableMap(state = getBrowserCanvasState(), options = {}) {
  if (!state) return;
  const sessionId = String(state.sessionId || '').trim();
  if (!sessionId) return;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  if (!isBrowserDesignMode(state) && mode !== 'teach' && mode !== 'copilot' && options.force !== true) return;
  const now = Date.now();
  if (!options.force && (now - Number(state.interactableMapRequestedAt || 0)) < BROWSER_INTERACTABLE_MAP_TTL_MS) return;
  state.interactableMapRequestedAt = now;
  state.interactableMapRequestId = `imap_${now}`;
  wsSend({
    type: 'browser:inspect_map',
    sessionId,
    requestId: state.interactableMapRequestId,
    limit: 240,
    includeStatic: isBrowserDesignMode(state),
  });
}

function hitTestBrowserInteractableMap(state, viewportX, viewportY) {
  const map = state?.interactableMap;
  if (!map || !Array.isArray(map.items) || !map.items.length) return null;
  if ((Date.now() - Number(map.capturedAt || 0)) > 5000) return null;
  // Prefer the smallest box that contains the point — that's the most specific element.
  let best = null;
  let bestArea = Infinity;
  for (const item of map.items) {
    const b = item?.bounds;
    if (!b) continue;
    const x = Number(b.x) || 0;
    const y = Number(b.y) || 0;
    const w = Number(b.width) || 0;
    const h = Number(b.height) || 0;
    if (viewportX < x || viewportY < y || viewportX > x + w || viewportY > y + h) continue;
    const area = Math.max(1, w * h);
    if (area < bestArea) {
      bestArea = area;
      best = item;
    }
  }
  return best;
}

function applyBrowserHoverFromLocalMap(state, viewportX, viewportY) {
  const hit = hitTestBrowserInteractableMap(state, viewportX, viewportY);
  if (!hit) {
    if (state.hoverElement) {
      state.hoverElement = null;
      updateBrowserHoverOverlay();
    }
    return false;
  }
  const fingerprint = `${hit.bounds?.x}|${hit.bounds?.y}|${hit.bounds?.width}|${hit.bounds?.height}|${hit.selector}`;
  if (fingerprint === browserLastHoverFingerprint && state.hoverElement) return true;
  browserLastHoverFingerprint = fingerprint;
  state.hoverElement = {
    selector: hit.selector,
    pack: hit.pack || null,
    tagName: hit.tagName || '',
    role: hit.role || '',
    text: hit.text || '',
    bounds: hit.bounds,
  };
  updateBrowserHoverOverlay();
  return true;
}

function maybeRequestBrowserHoverFallback(state, viewportX, viewportY) {
  const now = Date.now();
  if (now - browserLastHoverFallbackAt < BROWSER_HOVER_FALLBACK_MIN_INTERVAL_MS) return;
  const sessionId = String(state.sessionId || '').trim();
  if (!sessionId) return;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  browserLastHoverFallbackAt = now;
  wsSend({
    type: 'browser:inspect_point',
    sessionId,
    x: viewportX,
    y: viewportY,
    purpose: 'hover',
    track: false,
    requestId: `hover_${now}`,
  });
}

function handleBrowserCanvasFramePointerMove(event) {
  const state = getBrowserCanvasState();
  if (!isBrowserCanvasSurfaceActive()) return;
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  if (!isBrowserDesignMode(state) && mode !== 'teach' && mode !== 'copilot') return;
  if (isFollowingDetachedBrowserCanvasSession(state)) return;
  // While the user has the browser captured (i.e. typing into the page), don't draw
  // hover overlays — the page itself should look "clicked into," not under inspection.
  if (state.controlCaptured && state.controlOwner === 'user' && mode === 'copilot') return;
  const point = resolveBrowserCanvasViewportPointFromClient(event?.clientX, event?.clientY);
  if (!point) {
    if (state.hoverElement) {
      state.hoverElement = null;
      updateBrowserHoverOverlay();
    }
    return;
  }
  browserHoverPendingPoint = point;
  if (browserHoverRafHandle) return;
  browserHoverRafHandle = requestAnimationFrame(() => {
    browserHoverRafHandle = 0;
    const pending = browserHoverPendingPoint;
    browserHoverPendingPoint = null;
    if (!pending) return;
    const ok = applyBrowserHoverFromLocalMap(state, pending.x, pending.y);
    if (!ok) {
      // Schedule a refreshed interactable map, and ask the server directly while we wait.
      maybeRequestBrowserInteractableMap(state);
      maybeRequestBrowserHoverFallback(state, pending.x, pending.y);
    }
  });
}

function handleBrowserCanvasFramePointerLeave() {
  const state = getBrowserCanvasState();
  if (!state.hoverElement) return;
  state.hoverElement = null;
  browserLastHoverFingerprint = '';
  updateBrowserHoverOverlay();
}

function updateBrowserHoverOverlay() {
  const hoverEl = document.getElementById('browser-canvas-hover-box');
  const frameEl = document.getElementById('browser-canvas-frame');
  if (!hoverEl || !frameEl) return;
  const state = getBrowserCanvasState();
  const mode = normalizeBrowserInteractionMode(state.interactionMode);
  const hover = state.hoverElement;
   if (!hover?.bounds || (!isBrowserDesignMode(state) && mode !== 'teach' && mode !== 'copilot') || isFollowingDetachedBrowserCanvasSession(state)) {
    hoverEl.style.display = 'none';
    return;
  }
  if (!positionBrowserOverlayElement(hoverEl, frameEl, hover.bounds, { state })) {
    hoverEl.style.display = 'none';
    return;
  }
  hoverEl.style.display = 'block';
}

function ensureBrowserCanvasHoverBindings() {
  const frameWrap = document.getElementById('browser-canvas-frame-wrap');
  if (!frameWrap || frameWrap.dataset.browserHoverBound === '1') return;
  frameWrap.addEventListener('pointermove', handleBrowserCanvasFramePointerMove);
  frameWrap.addEventListener('pointerleave', handleBrowserCanvasFramePointerLeave);
  frameWrap.dataset.browserHoverBound = '1';
}

function updateBrowserElementNameDraft(value) {
  const state = getBrowserCanvasState();
  state.elementNameDraft = String(value || '');
  syncPendingBrowserTeachStepFromDraft(state);
  renderBrowserCanvasSurface();
  persistActiveChat();
}

function getBrowserKnowledgeHost(url) {
  try {
    const raw = String(url || '').trim();
    if (!raw) return '';
    const parsed = new URL(raw.startsWith('http://') || raw.startsWith('https://') ? raw : `https://${raw}`);
    return String(parsed.hostname || '').replace(/^www\./i, '').toLowerCase();
  } catch {
    return '';
  }
}

function isRestorableBrowserCanvasUrl(url) {
  const value = String(url || '').trim();
  if (!value) return false;
  if (/^(about|chrome|devtools):/i.test(value)) return false;
  return /^https?:\/\//i.test(value);
}

function rememberBrowserCanvasRestorablePage(url, title = '', state = getBrowserCanvasState()) {
  const nextUrl = String(url || '').trim();
  if (!isRestorableBrowserCanvasUrl(nextUrl)) return false;
  state.lastRestorableUrl = nextUrl;
  const nextTitle = String(title || '').trim();
  if (nextTitle) state.lastRestorableTitle = nextTitle;
  return true;
}

function getBrowserCanvasRestoreHint(state = getBrowserCanvasState()) {
  const currentUrl = String(state.url || '').trim();
  const currentTitle = String(state.title || '').trim();
  const savedUrl = String(state.lastRestorableUrl || '').trim();
  const savedTitle = String(state.lastRestorableTitle || '').trim();
  const restoreUrl = isRestorableBrowserCanvasUrl(currentUrl) ? currentUrl : savedUrl;
  const restoreTitle = isRestorableBrowserCanvasUrl(currentUrl) ? currentTitle : savedTitle;
  return { restoreUrl, restoreTitle };
}

function isBrowserCanvasClosedStreamStatus(status) {
  const value = String(status || '').trim().toLowerCase();
  if (!value) return false;
  return (
    value.includes('page closed')
    || value.includes('chrome session ended')
    || value.includes('browser tab closed')
    || value.includes('last browser tab closed')
  );
}

function requestBrowserKnowledge(force = false) {
  const state = getBrowserCanvasState();
  const sessionId = getBrowserCanvasVisibleSessionId();
  const { restoreUrl, restoreTitle } = getBrowserCanvasRestoreHint(state);
  const host = getBrowserKnowledgeHost(state.url) || getBrowserKnowledgeHost(restoreUrl);
  if (!sessionId || !state.active || !host) return;
  if (!force && state.knowledgeRequestedFor === host) return;
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) return;
  state.knowledgeRequestedFor = host;
  wsSend({
    type: 'browser:knowledge:request',
    sessionId,
    restoreUrl,
    restoreTitle,
  });
}

function reopenBrowserCanvasLastPage() {
  const state = getBrowserCanvasState();
  const sessionId = getBrowserCanvasPrimarySessionId();
  const { restoreUrl, restoreTitle } = getBrowserCanvasRestoreHint(state);
  if (!sessionId) {
    showToast('No chat session is available for browser reopen.', 'error');
    return false;
  }
  if (!isRestorableBrowserCanvasUrl(restoreUrl)) {
    showToast('No last browser page is saved for this chat yet.', 'info');
    return false;
  }
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    showToast('Browser connection is reconnecting. Try again in a second.', 'info');
    return false;
  }
  returnBrowserCanvasToPrimarySession({ render: false, requestData: false });
  state.active = true;
  state.statusLabel = `Reopening ${restoreTitle || restoreUrl}`;
  state.url = restoreUrl;
  if (restoreTitle) state.title = restoreTitle;
  setBrowserCanvasSurface('browser');
  renderBrowserCanvasSurface();
  wsSend({
    type: 'browser:reopen',
    sessionId,
    restoreUrl,
    restoreTitle,
  });
  return true;
}

async function sendNativeBrowserNavigation(action, url = '') {
  const api = getNativeBrowserSurfaceApi();
  const state = getBrowserCanvasState();
  const sessionId = getDirectBrowserSessionId(state);
  if (!api || typeof api.navigate !== 'function') return false;
  const normalizedAction = String(action || '').trim().toLowerCase();
  let address = '';
  try {
    if (normalizedAction === 'open') address = normalizeBrowserAddressInput(url);
  } catch (error) {
    state.lastError = String(error?.message || error || 'Invalid browser URL.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    showToast(state.lastError, 'error');
    return true;
  }
  state.sessionId = sessionId;
  state.active = true;
  state.loading = true;
  state.lastError = '';
  state.statusLabel = normalizedAction === 'open' ? `Opening ${address}` : `${normalizedAction.charAt(0).toUpperCase()}${normalizedAction.slice(1)} requested.`;
  if (normalizedAction === 'open') state.url = address;
  renderBrowserCanvasSurface();
  try {
    const nativeState = await api.navigate({ sessionId, action: normalizedAction, url: address });
    if (nativeState && typeof nativeState === 'object') {
      applyNativeBrowserStateToCanvas(nativeState, state);
      state.url = String(nativeState.url || state.url || '').trim();
      state.title = String(nativeState.title || state.title || '').trim();
      state.loading = nativeState.loading === true;
      state.lastError = String(nativeState.lastError || '').trim();
      state.statusLabel = state.lastError
        ? `Browser error: ${state.lastError}`
        : (state.loading ? 'In-house browser loading.' : 'In-house browser active.');
    }
  } catch (error) {
    state.loading = false;
    state.lastError = String(error?.message || error || 'Browser navigation failed.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    showToast(state.lastError, 'error');
  }
  upsertBrowserSessionRecord({
    sessionId,
    active: true,
    url: state.url,
    title: state.title,
    statusLabel: state.statusLabel,
       profileKind: 'inhouse',
       browserTarget: 'inhouse',
       profileLabel: state.profileLabel || 'Prometheus in-house browser',
       inhouseProfile: state.inhouseProfile || 'main',
    timestamp: Date.now(),
   }, { copyToCanvas: true });
  announceNativeBrowserStateToGateway({
    sessionId,
    attached: true,
    profile: state.inhouseProfile,
    profileLabel: state.profileLabel,
    url: state.url,
    title: state.title,
    tabs: state.nativeTabs,
    activeTabId: state.activeNativeTabId,
  }, state, { immediate: true });
   renderBrowserCanvasSurface();
   persistActiveChat();
   return true;
 }

 function commitNativeBrowserTabState(nativeState, statusLabel = '') {
  const state = getBrowserCanvasState();
  if (nativeState && typeof nativeState === 'object') {
    applyNativeBrowserStateToCanvas(nativeState, state);
    state.active = nativeState.attached !== false;
    state.sessionId = String(nativeState.sessionId || state.sessionId || '').trim();
    state.url = String(nativeState.url || state.url || 'about:blank').trim();
    state.title = String(nativeState.title || state.title || '').trim();
    state.loading = nativeState.loading === true;
    state.lastError = String(nativeState.lastError || '').trim();
    state.statusLabel = state.lastError
      ? `Browser error: ${state.lastError}`
      : (statusLabel || (state.loading ? 'In-house browser loading.' : 'In-house browser active.'));
    upsertBrowserSessionRecord({
      sessionId: state.sessionId,
      active: state.active,
      url: state.url,
      title: state.title,
      statusLabel: state.statusLabel,
      profileKind: 'inhouse',
      browserTarget: 'inhouse',
       profileLabel: state.profileLabel || 'Prometheus in-house browser',
       inhouseProfile: state.inhouseProfile || 'main',
       nativeTabs: state.nativeTabs,
      activeNativeTabId: state.activeNativeTabId,
      timestamp: Date.now(),
     }, { copyToCanvas: true });
    announceNativeBrowserStateToGateway(nativeState, state, { immediate: true });
   }
  renderBrowserCanvasSurface();
  persistActiveChat();
  queueNativeBrowserSurfaceSync({ force: true });
  return nativeState;
}

async function selectNativeBrowserCanvasTab(tabId, event) {
  event?.stopPropagation?.();
  const api = getNativeBrowserSurfaceApi();
  const state = getBrowserCanvasState();
  const sessionId = getDirectBrowserSessionId(state);
  const requestedTabId = String(tabId || '').trim();
  if (!api || typeof api.selectTab !== 'function' || !sessionId || !requestedTabId) return false;
  try {
    const nativeState = await api.selectTab({ sessionId, tabId: requestedTabId });
    commitNativeBrowserTabState(nativeState, 'Switched browser tab.');
    return true;
  } catch (error) {
    state.lastError = String(error?.message || error || 'Could not switch browser tabs.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    showToast(state.lastError, 'error');
    return false;
  }
}

async function newNativeBrowserCanvasTab(url = '') {
  const api = getNativeBrowserSurfaceApi();
  const state = getBrowserCanvasState();
  const sessionId = getDirectBrowserSessionId(state);
  if (!api || typeof api.newTab !== 'function' || !sessionId) return false;
  let targetUrl = '';
  try { targetUrl = String(url || '').trim() ? normalizeBrowserAddressInput(url) : 'about:blank'; }
  catch (error) {
    state.lastError = String(error?.message || error || 'Invalid browser URL.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    showToast(state.lastError, 'error');
    return false;
  }
  try {
    const nativeState = await api.newTab({ sessionId, url: targetUrl });
    commitNativeBrowserTabState(nativeState, targetUrl === 'about:blank' ? 'New tab ready.' : 'Opened new browser tab.');
    if (targetUrl === 'about:blank') {
      requestAnimationFrame(() => {
        const input = document.getElementById('browser-canvas-address-input');
        if (input) { input.focus({ preventScroll: true }); input.select?.(); }
      });
    }
    return true;
  } catch (error) {
    state.lastError = String(error?.message || error || 'Could not open a new browser tab.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    showToast(state.lastError, 'error');
    return false;
  }
}

async function closeNativeBrowserCanvasTab(tabId, event) {
  event?.stopPropagation?.();
  const api = getNativeBrowserSurfaceApi();
  const state = getBrowserCanvasState();
  const sessionId = getDirectBrowserSessionId(state);
  const requestedTabId = String(tabId || '').trim();
  if (!api || typeof api.closeTab !== 'function' || !sessionId || !requestedTabId) return false;
  try {
    const nativeState = await api.closeTab({ sessionId, tabId: requestedTabId });
    commitNativeBrowserTabState(nativeState, 'Closed browser tab.');
    return true;
  } catch (error) {
    state.lastError = String(error?.message || error || 'Could not close browser tab.').trim();
    state.statusLabel = `Browser error: ${state.lastError}`;
    renderBrowserCanvasSurface();
    showToast(state.lastError, 'error');
    return false;
  }
}

function sendBrowserCanvasNavigation(action, url = '') {
  const state = getBrowserCanvasState();
  const sessionId = getBrowserCanvasPrimarySessionId();
  if (!sessionId) {
    showToast('No chat session is available for browser navigation.', 'error');
    return false;
  }
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    showToast('Browser connection is reconnecting. Try again in a second.', 'info');
    return false;
  }
  const normalizedAction = String(action || '').trim().toLowerCase();
  let address = String(url || '').trim();
  if (normalizedAction === 'open') {
    try { address = normalizeBrowserAddressInput(address); }
    catch (error) {
      state.lastError = String(error?.message || error || 'Invalid browser URL.').trim();
      state.statusLabel = `Browser error: ${state.lastError}`;
      renderBrowserCanvasSurface();
      showToast(state.lastError, 'error');
      return false;
    }
  }
  if (isBrowserCanvasInHouseProvider(state)) {
    sendNativeBrowserNavigation(normalizedAction, address);
    return true;
  }
  const wasActive = state.active === true;
  returnBrowserCanvasToPrimarySession({ render: false, requestData: false });
  const hasActiveSession = state.active === true;
  if (normalizedAction !== 'open' || wasActive || hasActiveSession) {
    state.active = true;
  }
  if (normalizedAction === 'open' && state.active) {
    state.url = address;
  }
  state.statusLabel = normalizedAction === 'open'
    ? `Opening ${address}`
    : `${normalizedAction.charAt(0).toUpperCase()}${normalizedAction.slice(1)} requested.`;
  setBrowserCanvasSurface('browser');
  renderBrowserCanvasSurface();
  wsSend({
    type: 'browser:navigation',
    sessionId,
    action: normalizedAction,
    url: address,
  });
  return true;
}

function openBrowserCanvasAddress() {
  const input = document.getElementById('browser-canvas-address-input');
  return sendBrowserCanvasNavigation('open', input?.value || '');
}

function handleBrowserCanvasAddressKeydown(event) {
  if (event?.key !== 'Enter') return;
  if (typeof event.preventDefault === 'function') event.preventDefault();
  openBrowserCanvasAddress();
}

function syncPendingBrowserTeachStepFromDraft(state = getBrowserCanvasState()) {
  const teach = getBrowserTeachSession(state);
  if (!teach.pendingStep || !teach.pendingStep.selection) return;
  const pendingKey = getBrowserTeachSelectionKey(teach.pendingStep.selection);
  const selectedKey = getSelectedBrowserElementKey(state.selectedElement);
  if (!pendingKey || !selectedKey || pendingKey !== selectedKey) return;
  teach.pendingStep = refreshBrowserTeachStepMetadata(teach.pendingStep, state);
}

function upsertPendingBrowserTeachStep(step, options = {}) {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  if (!isBrowserTeachRecording(state)) return false;
  const nextStep = refreshBrowserTeachStepMetadata(step, state);
  const existing = teach.pendingStep && typeof teach.pendingStep === 'object' ? { ...teach.pendingStep } : null;
  if (existing && options.merge !== true) {
    showToast('Continue or discard the current teach step first.', 'info');
    return false;
  }
  if (existing && options.merge === true && existing.kind === nextStep.kind) {
    if ((existing.kind === 'fill' || existing.kind === 'text') && nextStep.input?.text != null) {
      existing.input = { ...existing.input, text: `${String(existing.input?.text || '')}${String(nextStep.input.text || '')}` };
      teach.pendingStep = refreshBrowserTeachStepMetadata(existing, state);
    } else if (existing.kind === 'scroll') {
      existing.input = {
        ...existing.input,
        x: Number(nextStep.input?.x || existing.input?.x || 0),
        y: Number(nextStep.input?.y || existing.input?.y || 0),
        deltaX: Number(existing.input?.deltaX || 0) + Number(nextStep.input?.deltaX || 0),
        deltaY: Number(existing.input?.deltaY || 0) + Number(nextStep.input?.deltaY || 0),
      };
      teach.pendingStep = refreshBrowserTeachStepMetadata(existing, state);
    } else {
      showToast('Continue or discard the current teach step first.', 'info');
      return false;
    }
  } else {
    teach.pendingStep = nextStep;
  }
  state.statusLabel = 'Review the pending teach step, rename anything you want, then continue.';
  renderBrowserCanvasSurface();
  persistActiveChat();
  return true;
}

function discardBrowserTeachPendingStep(options = {}) {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  teach.pendingStep = null;
  teach.pendingSelectionIntent = null;
  state.selectionPending = false;
  if (options.clearSelection === true) {
    state.selectedElement = null;
    state.elementNameDraft = '';
    state.elementNameDraftKey = '';
  }
  state.statusLabel = isBrowserTeachRecording(state)
    ? 'Teach mode is recording. Inspect the next step when you are ready.'
    : (state.statusLabel || 'Browser idle');
  renderBrowserCanvasSurface();
  persistActiveChat();
}

function markBrowserTeachExecutionError(errorText) {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  const executingId = String(teach.executingStepId || '').trim();
  if (!executingId) return;
  teach.steps = Array.isArray(teach.steps)
    ? teach.steps.map((step) => {
        if (String(step?.id || '').trim() !== executingId) return step;
        return {
          ...step,
          status: 'error',
          resultSummary: String(errorText || 'Teach step failed.').trim(),
        };
      })
    : [];
  teach.executingStepId = '';
  state.statusLabel = String(errorText || 'Teach step failed.').trim() || 'Teach step failed.';
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
}

function finalizeBrowserTeachExecution(msg) {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  const executingId = String(teach.executingStepId || '').trim();
  if (!executingId) return;
  const timestamp = Number(msg?.timestamp || Date.now()) || Date.now();
  teach.steps = Array.isArray(teach.steps)
    ? teach.steps.map((step) => {
        if (String(step?.id || '').trim() !== executingId) return step;
        return {
          ...step,
          status: 'recorded',
          executedAt: timestamp,
          resultSummary: String(msg?.userAction?.summary || '').trim(),
          pageUrl: String(msg?.url || step?.pageUrl || '').trim(),
          pageTitle: String(msg?.title || step?.pageTitle || '').trim(),
        };
      })
    : [];
  teach.executingStepId = '';
  state.statusLabel = 'Teach step recorded.';
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
}

function continueBrowserTeachPendingStep() {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  if (!isBrowserTeachRecording(state)) {
    showToast('Start a Teach session first.', 'info');
    return;
  }
  if (teach.executingStepId) {
    showToast('A teach step is still running. Give it a moment.', 'info');
    return;
  }
  if (!teach.pendingStep) {
    showToast('Stage a teach step first.', 'info');
    return;
  }
  const sessionId = getBrowserCanvasControlSessionId();
  if (!sessionId) {
    showToast('No active browser session is linked to this chat yet.', 'info');
    return;
  }
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    showToast('Browser connection is reconnecting. Try again in a second.', 'info');
    return;
  }
  const finalizedStep = refreshBrowserTeachStepMetadata(teach.pendingStep, state);
  const executionPayload = finalizedStep.input && typeof finalizedStep.input === 'object'
    ? { ...finalizedStep.input }
    : null;
  if (!executionPayload?.action) {
    showToast('This teach step is missing its browser action payload.', 'error');
    return;
  }
  teach.executingStepId = String(finalizedStep.id || '').trim();
  teach.steps = [...(Array.isArray(teach.steps) ? teach.steps : []), {
    ...finalizedStep,
    status: 'executing',
  }];
  teach.pendingStep = null;
  teach.pendingSelectionIntent = null;
  state.selectionPending = false;
  state.statusLabel = `Running teach step: ${finalizedStep.summary || finalizedStep.title || finalizedStep.toolName || 'browser step'}`;
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
  addProcessEntry('info', `Teach: executing ${finalizedStep.summary || finalizedStep.toolName || 'browser step'}.`);
  wsSend({
    type: 'browser:input',
    sessionId,
    ...executionPayload,
  });
}

function removeBrowserTeachStep(stepId) {
  const teach = getBrowserTeachSession();
  const targetId = String(stepId || '').trim();
  if (!targetId) return;
  teach.steps = Array.isArray(teach.steps)
    ? teach.steps.filter((step) => String(step?.id || '').trim() !== targetId)
    : [];
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
}

function startBrowserTeachSession(options = {}) {
  const state = getBrowserCanvasState();
  if (!state.active || !String(state.url || '').trim()) {
    showToast('Open a live browser session first, then start Teach mode.', 'info');
    return;
  }
  const teach = getBrowserTeachSession(state);
  const shouldPreserveSteps = options.resume === true || normalizeBrowserTeachPhase(teach.phase) === 'approval_pending';
  const preserveSteps = shouldPreserveSteps && Array.isArray(teach.steps) ? teach.steps.slice() : [];
  state.interactionMode = 'teach';
  Object.assign(teach, createEmptyBrowserTeachSession(), {
    active: true,
    phase: 'recording',
    startedAt: Date.now(),
    startUrl: String(state.url || '').trim(),
    startTitle: String(state.title || '').trim(),
    steps: preserveSteps,
  });
  captureBrowserCanvasControl('Teach mode is recording workflow steps.');
  state.statusLabel = 'Teach mode started. Click the browser to stage the first step.';
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
  addProcessEntry('info', `Teach: recording started from ${teach.startTitle || teach.startUrl || 'the current page'}.`);
}

function cancelBrowserTeachSession() {
  const state = getBrowserCanvasState();
  state.teachSession = createEmptyBrowserTeachSession();
  state.selectionPending = false;
  state.statusLabel = 'Teach mode reset.';
  releaseBrowserCanvasControl({
    reason: 'Teach mode ended.',
    statusLabel: 'Teach mode reset.',
    render: false,
  });
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
  addProcessEntry('info', 'Teach: session cleared.');
}

function buildBrowserTeachReviewPrompt() {
  return 'Teach mode recording complete. Review the captured workflow, summarize what it appears to do, call out any risky steps, and ask whether you should run the full verification or stop before a specific step. Do not run any browser tools yet.';
}

function completeBrowserTeachSession() {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  if (!isBrowserTeachRecording(state)) {
    showToast('Start a Teach session before completing it.', 'info');
    return;
  }
  if (teach.pendingStep) {
    showToast('Continue or discard the pending teach step before completing the workflow.', 'info');
    return;
  }
  if (teach.executingStepId) {
    showToast('A teach step is still running. Give it a moment.', 'info');
    return;
  }
  if (!Array.isArray(teach.steps) || !teach.steps.length) {
    showToast('Record at least one teach step first.', 'info');
    return;
  }
  teach.phase = 'approval_pending';
  teach.completedAt = Date.now();
  teach.approvalRequestedAt = teach.completedAt;
  teach.reviewRequestedAt = teach.completedAt;
  state.statusLabel = 'Teach workflow recorded. Asking Prometheus to review it.';
  releaseBrowserCanvasControl({
    reason: 'Teach recording complete. Waiting for verification approval.',
    statusLabel: 'Teach workflow recorded. Waiting for verification approval.',
    render: false,
  });
  renderBrowserCanvasSurface();
  persistActiveChat();
  syncBrowserTeachSessionToBackend();
  addProcessEntry('info', 'Teach: sent the recorded workflow to Prometheus for review.');
  sendChat(buildBrowserTeachReviewPrompt());
}

function parseBrowserTeachVerificationApproval(message) {
  const source = String(message || '').trim();
  if (!source) return { approved: false, mode: 'full', stopBeforeStep: 0 };
  const text = source.toLowerCase();
  if (/\b(don't run|do not run|hold off|wait on verification|not yet|skip verification)\b/i.test(text)) {
    return { approved: false, mode: 'full', stopBeforeStep: 0 };
  }
  const stopStepMatch = text.match(/\bstop(?:ping)?\s+before\s+step\s+(\d+)\b/i);
  if (stopStepMatch) {
    return {
      approved: true,
      mode: 'step',
      stopBeforeStep: Math.max(1, Number(stopStepMatch[1] || 0) || 0),
    };
  }
  if (/\b(stop(?:ping)?\s+before\s+(?:the\s+)?(?:last|final)\s+(?:risky\s+)?step|stop before final action|safe verification|run safe)\b/i.test(text)) {
    return { approved: true, mode: 'safe', stopBeforeStep: 0 };
  }
  if (/\b(run\s+(?:the\s+)?full(?:\s+test)?|full verification|run it|go ahead|proceed|verify it|test it)\b/i.test(text)) {
    return { approved: true, mode: 'full', stopBeforeStep: 0 };
  }
  return { approved: false, mode: 'full', stopBeforeStep: 0 };
}

function requestBrowserTeachVerification(mode = 'full', stopBeforeStep = 0) {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  if (!isBrowserTeachAwaitingApproval(state)) {
    showToast('Record and complete a Teach workflow first.', 'info');
    return;
  }
  let message = '';
  let statusLabel = '';
  if (mode === 'safe') {
    message = 'Teach mode verification approved. Run the verification now, but stop before the final risky step. Use browser_teach_verify, then explain what you actually replayed, what worked, what needed adjustment, and what you think this workflow is for. Ask me to confirm that understanding before creating anything.';
    statusLabel = 'Teach verification requested: stop before the final risky step.';
  } else if (mode === 'step') {
    const targetStep = Math.max(1, Number(stopBeforeStep || 0) || 0);
    if (!targetStep) {
      showToast('Pick a step number to stop before.', 'info');
      return;
    }
    message = `Teach mode verification approved. Run the verification now, but stop before step ${targetStep}. Use browser_teach_verify with that boundary, then explain what you actually replayed, what worked, what needed adjustment, and what you think this workflow is for. Ask me to confirm that understanding before creating anything.`;
    statusLabel = `Teach verification requested: stop before step ${targetStep}.`;
  } else {
    message = 'Teach mode verification approved. Run the full verification now using browser_teach_verify, then explain what you actually replayed, what worked, what needed adjustment, and what you think this workflow is for. Ask me to confirm that understanding before creating anything.';
    statusLabel = 'Teach verification requested: full replay.';
  }
  state.statusLabel = statusLabel;
  renderBrowserCanvasSurface();
  persistActiveChat();
  addProcessEntry('info', statusLabel);
  sendChat(message);
}

function requestBrowserTeachVerificationFromInput() {
  const input = document.getElementById('browser-canvas-teach-stop-step-input');
  const stepValue = Math.max(1, Number(input?.value || 0) || 0);
  if (input) input.value = stepValue ? String(stepValue) : '';
  requestBrowserTeachVerification('step', stepValue);
}

function saveSelectedBrowserMemory(kind = 'element') {
  const state = getBrowserCanvasState();
  const selected = state.selectedElement;
  const rawName = String(state.elementNameDraft || '').trim();
  const normalizedKind = String(kind || '').trim().toLowerCase() === 'item_root' ? 'item_root' : 'element';
  const label = normalizedKind === 'item_root' ? 'item root' : 'element';
  if (!selected) {
    showToast('Select a browser element first.', 'info');
    return;
  }
  if (!rawName) {
    showToast(`Give the ${label} a name first.`, 'info');
    return;
  }
  const sessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
  if (!sessionId) {
    showToast('No active browser session is linked to this chat yet.', 'info');
    return;
  }
  if (!(window.ws && window.ws.readyState === WebSocket.OPEN)) {
    showToast('Browser memory is reconnecting. Try again in a second.', 'info');
    return;
  }
  state.statusLabel = `Saving "${rawName}" as a browser ${label}...`;
  renderBrowserCanvasSurface();
  wsSend({
    type: 'browser:element:save',
    sessionId,
    kind: normalizedKind,
    name: rawName,
    selection: {
      selector: String(selected.selector || '').trim(),
      tagName: String(selected.tagName || '').trim(),
      id: String(selected.id || '').trim(),
      text: String(selected.text || '').trim(),
      url: String(state.url || '').trim(),
    },
  });
}

function saveNamedBrowserElement() {
  saveSelectedBrowserMemory('element');
}

function saveNamedBrowserItemRoot() {
  saveSelectedBrowserMemory('item_root');
}

function isBrowserEventForActiveSession(msg, options = {}) {
  const incoming = String(msg?.sessionId || '').trim();
  if (!incoming) return true;
  const scope = String(options.scope || 'visible').trim().toLowerCase() === 'primary' ? 'primary' : 'visible';
  const primarySessionId = getBrowserCanvasPrimarySessionId();
  const visibleSessionId = getBrowserCanvasVisibleSessionId();
  if (scope === 'primary') return incoming === primarySessionId;
  return incoming === visibleSessionId || (!visibleSessionId && incoming === primarySessionId);
}

function applyBrowserEventState(msg, options = {}) {
  if (!msg) return;
  upsertBrowserSessionRecord(msg);
  if (!isBrowserEventForActiveSession(msg, { scope: 'visible' })) {
    renderBrowserCanvasSurface();
    persistActiveChat();
    return;
  }
  const state = getBrowserCanvasState();
  const creativeLocked = isCreativeModeLocked();
  const previousHost = getBrowserKnowledgeHost(state.url);
  const incomingSessionId = String(msg.sessionId || state.sessionId || '').trim();
  const allowInteractionSync = !isFollowingDetachedBrowserCanvasSession(state) || incomingSessionId === getBrowserCanvasPrimarySessionId();
  state.sessionId = incomingSessionId;
  state.active = msg.active !== false;
  state.url = String(msg.url || state.url || '').trim();
  state.title = String(msg.title || state.title || '').trim();
  if (msg.profileKind) state.profileKind = String(msg.profileKind || '').trim();
  if (msg.inhouseProfile) state.inhouseProfile = String(msg.inhouseProfile || '').trim() || 'main';
  if (msg.browserTarget) state.browserTarget = String(msg.browserTarget || '').trim();
  if (msg.profileLabel) state.profileLabel = String(msg.profileLabel || '').trim();
  if (Array.isArray(msg.nativeTabs)) state.nativeTabs = normalizeNativeBrowserTabs(msg.nativeTabs);
  if (msg.activeNativeTabId !== undefined) state.activeNativeTabId = String(msg.activeNativeTabId || '').trim();
  rememberBrowserCanvasRestorablePage(state.url, state.title, state);
  state.lastTool = String(msg.tool || msg.lastTool || state.lastTool || '').trim();
  state.statusLabel = String(msg.statusLabel || state.statusLabel || '').trim() || (state.active ? 'Browser active' : 'Browser idle');
  if (allowInteractionSync && typeof msg.captured === 'boolean') state.controlCaptured = msg.captured === true;
  if (allowInteractionSync && msg.controlOwner) state.controlOwner = String(msg.controlOwner || '').trim().toLowerCase() === 'user' ? 'user' : 'agent';
  if (typeof msg.streamActive === 'boolean') state.streamActive = msg.streamActive === true;
  if (typeof msg.streamTransport === 'string') state.streamTransport = String(msg.streamTransport || '').trim().toLowerCase();
  if (typeof msg.streamFocus === 'string') state.streamFocus = String(msg.streamFocus || 'passive').trim().toLowerCase() === 'interactive' ? 'interactive' : 'passive';
  if (typeof msg.streamStatus === 'string') state.streamStatus = String(msg.streamStatus || '').trim();
  if (state.active === false) {
    clearBrowserTransientHighlight();
    clearQueuedBrowserControlInputs();
    clearBrowserCanvasStreamHeartbeat();
    state.frameBase64 = '';
    if (state.frameBlobUrl) { try { URL.revokeObjectURL(state.frameBlobUrl); } catch {} }
    state.frameBlobUrl = '';
    state.frameWidth = 0;
    state.frameHeight = 0;
    state.frameBitmapWidth = 0;
    state.frameBitmapHeight = 0;
    state.frameViewportWidth = 0;
    state.frameViewportHeight = 0;
    state.frameScrollX = 0;
    state.frameScrollY = 0;
    state.frameFormat = 'png';
    state.selectedElement = null;
    state.hoverElement = null;
    state.interactableMap = null;
    state.agentCursor = null;
    state.controlCaptured = false;
    state.controlOwner = 'agent';
    state.streamActive = false;
    state.streamTransport = '';
    state.streamFocus = 'passive';
    state.streamStatus = '';
    state.profileKind = '';
    state.browserTarget = '';
    state.profileLabel = '';
    state.streamLastFrameAt = 0;
    state.elementNameDraft = '';
    state.elementNameDraftKey = '';
    state.knowledgeRequestedFor = '';
    state.selectionPending = false;
  } else if (typeof msg.frameBase64 === 'string' && msg.frameBase64.trim()) {
    state.frameBase64 = msg.frameBase64;
    if (Number.isFinite(Number(msg.frameWidth))) state.frameWidth = Number(msg.frameWidth);
    if (Number.isFinite(Number(msg.frameHeight))) state.frameHeight = Number(msg.frameHeight);
    state.frameFormat = String(msg.frameFormat || 'png').trim().toLowerCase() === 'jpeg' ? 'jpeg' : 'png';
  }
  upsertBrowserSessionRecord(msg, { copyToCanvas: true });
  const nextHost = getBrowserKnowledgeHost(state.url);
  if (state.active && nextHost && nextHost !== previousHost) {
    clearBrowserTransientHighlight();
    state.namedElements = [];
    state.itemRoots = [];
    state.extractionSchemas = [];
    state.knowledgeSite = '';
    state.knowledgeRequestedFor = '';
  }
  state.updatedAt = Number(msg.timestamp || Date.now()) || Date.now();
  if (allowInteractionSync && msg.mode) state.interactionMode = creativeLocked ? 'agent' : normalizeBrowserInteractionMode(msg.mode);
  if (state.interactionMode !== 'copilot' && state.interactionMode !== 'teach' && state.controlCaptured) {
    state.controlCaptured = false;
    state.controlOwner = 'agent';
    clearQueuedBrowserControlInputs();
  }
  persistActiveChat();
  if (state.active && nextHost) requestBrowserKnowledge();
  if (options.autoOpen && state.active && !creativeLocked) {
    setBrowserCanvasSurface('browser');
  } else {
    renderBrowserCanvasSurface();
  }
}

function applyCreativeModeUI(options = {}) {
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  if (!mode) creativeFeatureUiRequestToken += 1;
  if (mode && !creativeFeatureRuntime) {
    const requestToken = ++creativeFeatureUiRequestToken;
    const expectedSessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
    ensureCreativeFeatureRuntime()
      .then(() => {
        const activeSessionId = String(window.activeChatSessionId || window.agentSessionId || '').trim();
        if (requestToken !== creativeFeatureUiRequestToken) return;
        if (expectedSessionId && activeSessionId !== expectedSessionId) return;
        if (normalizeCreativeMode(window.currentCreativeMode) !== mode) return;
        applyCreativeModeUI(options);
      })
      .catch((error) => {
        console.error('[creative] Failed to load feature runtime:', error);
        showToast('Could not load Creative workspace', String(error?.message || error), 'error');
      });
    return;
  }
  const suppressAutoOpen = window.__pmSuppressCreativeAutoOpen === true;
  const shouldAutoOpen = options.autoOpen === true && !suppressAutoOpen;
  const rightPanel = document.getElementById('right-panel');
  const panel = document.getElementById('canvas-panel');
  const topbar = document.getElementById('right-panel-topbar');
  const body = document.body;
  if (mode) {
    if (isStructuredCreativeMode(mode)) ensureCreativeSceneForMode(mode);
    if (shouldAutoOpen && rightPanel && !rightPanel.classList.contains('open')) {
      if (typeof window.toggleRightPanel === 'function') window.toggleRightPanel();
    }
    if (shouldAutoOpen && body) body.classList.remove('right-collapsed');
    if ((shouldAutoOpen || canvasOpen) && rightPanel && !creativeModeSavedPanelWidth) {
      creativeModeSavedPanelWidth = rightPanel.style.width || `${rightPanel.offsetWidth || 0}px`;
    }
    if (shouldAutoOpen || canvasOpen) {
      setRightPanelWidth(CREATIVE_MODE_PANEL_WIDTH, {
        minimumWidth: 960,
        lockMax: true,
        preserveChatColumn: true,
      });
      if (shouldAutoOpen && !canvasOpen) toggleCanvas(true, { force: true });
    }
  } else if (rightPanel) {
    if (creativeModeSavedPanelWidth && !/^0px$/i.test(creativeModeSavedPanelWidth)) {
      rightPanel.style.width = creativeModeSavedPanelWidth;
      rightPanel.style.minWidth = creativeModeSavedPanelWidth;
    } else {
      rightPanel.style.removeProperty('width');
      rightPanel.style.removeProperty('min-width');
    }
    rightPanel.style.removeProperty('max-width');
    creativeModeSavedPanelWidth = null;
  }
  if (!suppressAutoOpen && canvasOpen && rightPanel && panel) {
    rightPanel.classList.add('canvas-open');
    rightPanel.scrollTop = 0;
    panel.style.display = 'flex';
    if (topbar) topbar.style.display = 'none';
  }
  updateCreativeModeControls();
  if (canvasOpen) {
    // Reapply the active view when the creative mode changes. In particular,
    // entering Design Mode must reload the preview so its selection/hover
    // handlers can be attached to a preview that was opened beforehand.
    const activeTab = getActiveCanvasTab();
    applyCanvasViewMode(activeTab?.mode || 'code', activeTab || null);
    canvasRenderTabs();
  }
  renderCanvasPublishControls();
  syncCanvasSurfaceWidthLock();
  if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
  window.prometheusCreativeCompositionBridge = getCreativeCompositionBridge();
  if (creativeFeatureRuntime) {
    creativeFeatureRuntime.syncCreativeEditor({
      mode: normalizeCreativeMode(window.currentCreativeMode),
      shell: document.getElementById('canvas-creative-shell'),
      scene: window.prometheusCreativeScene,
      api: window.prometheusCreativeCore,
      compositionBridge: window.prometheusCreativeCompositionBridge,
    });
  }
}

function revealCreativeCanvasForWorkspaceOutput(mode = window.currentCreativeMode) {
  const normalizedMode = normalizeCreativeMode(mode);
  if (!isStructuredCreativeMode(normalizedMode)) return;
  if (normalizeCreativeMode(window.currentCreativeMode) !== normalizedMode) {
    window.currentCreativeMode = normalizedMode;
  }
  ensureCreativeSceneForMode(normalizedMode);
  applyCreativeModeUI({ autoOpen: true });
}

function createBlankCreativeScene(mode = window.currentCreativeMode) {
  const normalized = normalizeCreativeMode(mode);
  return createSceneDocument({
    width: normalized === 'video' ? 1080 : 1080,
    height: normalized === 'video' ? 1920 : 1080,
    background: normalized === 'video' ? '#050816' : '#ffffff',
    durationMs: normalized === 'video' ? 8000 : 12000,
    frameRate: 60,
  });
}

function applySessionCreativeMode(sessionId, mode, options = {}) {
  const sid = String(sessionId || window.activeChatSessionId || window.agentSessionId || '').trim();
  if (!sid) return;
  const normalizedMode = normalizeCreativeMode(mode);
  const session = (window.chatSessions || []).find((s) => s.id === sid);
  if (session) session.creativeMode = normalizedMode;
  if (sid === window.activeChatSessionId || sid === window.agentSessionId) {
    if (normalizedMode) {
      closeBrowserModeForCreativeSwitch({
        persist: false,
        reason: `${getCreativeModeMeta(normalizedMode)?.title || 'Creative workspace'} opened.`,
        statusLabel: 'Browser mode closed.',
      });
    }
    window.currentCreativeMode = normalizedMode;
    if (options.resetScene === true && isStructuredCreativeMode(normalizedMode)) {
      creativeSceneDoc = createBlankCreativeScene(normalizedMode);
      creativeSelectedId = null;
      creativeTimelineMs = 0;
      creativeHistoryPast = [];
      creativeHistoryFuture = [];
      creativeHtmlMotionClip = null;
      window.prometheusCreativeScene = creativeSceneDoc;
      window.prometheusCreativeSelectionId = null;
      if (session) {
        session.creativeSceneDoc = creativeSceneDoc;
        session.creativeSelectedId = null;
        session.creativeTimelineMs = 0;
        session.creativeHistoryPast = [];
        session.creativeHistoryFuture = [];
        session.creativeHtmlMotionClip = null;
      }
    }
    applyCreativeModeUI({ autoOpen: options.autoOpen === true });
    updateDesignSelectionChip();
    syncHeaderCanvasChrome();
  }
  if (options.persist !== false) saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
}

async function persistCreativeMode(sessionId, mode) {
  const res = await fetch('/api/creative-mode', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId, mode: normalizeCreativeMode(mode) }),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.success === false) {
    throw new Error(data.error || `HTTP ${res.status}`);
  }
  return normalizeCreativeMode(data.creativeMode);
}

async function setCreativeModeFromUI(mode) {
  const sid = getCurrentChatModeSessionId();
  const nextMode = normalizeCreativeMode(mode);
  if (!sid || !nextMode) return;
  if (nextMode === 'design' && isBrowserCanvasSurfaceActive()) {
    await toggleBrowserDesignMode();
    return;
  }
  try {
    await ensureCreativeFeatureRuntime();
    const savedMode = await persistCreativeMode(sid, nextMode);
    applySessionCreativeMode(sid, savedMode, { autoOpen: true });
    const meta = getCreativeModeMeta(savedMode);
    addProcessEntry('info', `${meta?.title || 'Creative workspace'} opened for this chat.`);
    showToast(`${meta?.title || 'Creative workspace'} opened`);
  } catch (err) {
    showToast(`Could not open Creative workspace: ${err.message}`, 'error');
  }
}

async function exitCreativeModeFromUI() {
  const sid = getCurrentChatModeSessionId();
  if (!sid || !isCreativeModeLocked()) return;
  try {
    await persistCreativeMode(sid, null);
    applySessionCreativeMode(sid, null);
    addProcessEntry('info', 'Creative workspace closed for this chat.');
    showToast('Creative workspace closed');
  } catch (err) {
    showToast(`Could not close Creative workspace: ${err.message}`, 'error');
  }
}

function renderQueuedPromptsPanel() {
  const panel = document.getElementById('queued-prompts-panel');
  const list = document.getElementById('queued-prompts-list');
  if (!panel || !list) {
    updateBackgroundSpawnDockOffset();
    return;
  }
  const queue = getActiveQueuedPrompts();
  window.queuedPrompts = queue;
  const count = queue.length;
  if (count === 0) {
    panel.style.display = 'none';
    list.innerHTML = '';
    updateBackgroundSpawnDockOffset();
    return;
  }
  panel.style.display = 'block';
  panel.setAttribute('aria-label', `${count} queued prompt${count === 1 ? '' : 's'}`);
  list.innerHTML = queue.map((q, i) => `
    <div class="queued-item">
      <span class="queued-item-index">${i + 1}.</span>
      <button type="button" class="queued-item-text" onclick="editQueuedPrompt(${i})" title="Edit queued prompt" aria-label="Edit queued prompt">${escHtml(getQueuedTurnMessage(q))}${getQueuedTurnFiles(q).length ? `<span class="queued-item-attachments">+${getQueuedTurnFiles(q).length}</span>` : ''}</button>
      <div class="queued-item-actions">
        <button class="queued-icon-btn queued-steer-btn" onclick="steerQueuedPrompt(${i})" title="Steer into active run" aria-label="Steer into active run">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>
        </button>
        <button class="queued-icon-btn queued-remove-btn" onclick="removeQueuedPrompt(${i})" title="Remove from queue" aria-label="Remove from queue">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/></svg>
        </button>
      </div>
    </div>
  `).join('');
  updateBackgroundSpawnDockOffset();
}

function removeQueuedPrompt(index) {
  const queue = getActiveQueuedPrompts();
  if (!Number.isInteger(index) || index < 0 || index >= queue.length) return;
  queue.splice(index, 1);
  window.queuedPrompts = queue;
  updateQueuedPromptUI();
}

function editQueuedPrompt(index) {
  const queue = getActiveQueuedPrompts();
  if (!Number.isInteger(index) || index < 0 || index >= queue.length) return;
  const turn = normalizeQueuedChatTurn(queue[index]);
  const message = String(turn.message || '').trim();
  queue.splice(index, 1);
  window.queuedPrompts = queue;
  updateQueuedPromptUI();
  const input = document.getElementById('chat-input');
  if (input && message) {
    input.value = message;
    input.dispatchEvent(new Event('input'));
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
  }
}

function _collapseChatSteerWorkflowPresentation(sessionId, workflowGroupId, options = {}) {
  const sid = String(sessionId || '').trim();
  const groupId = String(workflowGroupId || '').trim();
  if (!sid || !/^chat_steer_/i.test(groupId)) return false;
  const sess = getChatSessionById(sid);
  if (!sess || !Array.isArray(sess.history)) return false;

  let changed = false;
  const nextHistory = [];
  for (const message of sess.history) {
    if (String(message?.workflowGroupId || '') !== groupId) {
      nextHistory.push(message);
      continue;
    }
    if (isAssistantLikeMessage(message) && String(message.workflowPart || '') === 'before_interruption') {
      changed = true;
      continue;
    }
    const nextMessage = { ...message };
    delete nextMessage.workflowGroupId;
    delete nextMessage.workflowPart;
    delete nextMessage.workflowLabel;
    if (String(nextMessage.channelLabel || '').toLowerCase() === 'steer') delete nextMessage.channelLabel;
    if (String(nextMessage.messageKind || '') === 'steer_continuation') delete nextMessage.messageKind;
    changed = true;
    nextHistory.push(nextMessage);
  }
  if (!changed) return false;
  // Keep the same array object: the in-flight stream holds a reference to it
  // while its final assistant turn is being appended.
  sess.history.splice(0, sess.history.length, ...nextHistory);
  if (window.activeChatSessionId === sid) window.chatHistory = sess.history;
  if (options.persist !== false) {
    persistSession(sid);
    syncSessionHistoryToServerById(sid, sess.history).catch(() => {});
  }
  return true;
}

function _chatSteerWorkflowGroupIds(streamState) {
  const ids = Array.isArray(streamState?.steerWorkflowGroupIds) ? streamState.steerWorkflowGroupIds : [];
  const pending = String(streamState?.pendingInterruptionWorkflowGroupId || '').trim();
  return [...new Set([...ids, pending].map((id) => String(id || '').trim()).filter((id) => /^chat_steer_/i.test(id)))];
}

function _settlePendingChatSteerPresentation(sessionId, streamState) {
  const groupIds = _chatSteerWorkflowGroupIds(streamState);
  if (!groupIds.length) return false;
  streamState.pendingInterruptionWorkflowPresentationCleared = true;
  const changed = groupIds.reduce((changed, groupId) => (
    _collapseChatSteerWorkflowPresentation(sessionId, groupId) || changed
  ), false);
  // Final-answer rendering owns the timer again after the temporary split is
  // gone, so it appears above the final response rather than below a steer.
  streamState.steerTimerAnchored = false;
  return changed;
}

function appendChatSteerWorkflowSplit(sessionId, steerText, data = {}) {
  const sid = String(sessionId || '').trim();
  const sess = getChatSessionById(sid);
  if (!sess) return false;
  if (!Array.isArray(sess.history)) sess.history = [];
  if (!Array.isArray(sess.processLog)) sess.processLog = [];
  const st = getSessionStreamState(sid);
  const startIndex = Number.isFinite(Number(st?.currentTurnStartIndex)) ? Math.max(0, Number(st.currentTurnStartIndex)) : 0;
  const entries = sess.processLog.slice(startIndex);
  const liveTraceEntries = Array.isArray(st?.liveTraceEntries) ? st.liveTraceEntries.slice() : [];
  const groupId = `chat_steer_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  const text = String(steerText || '').trim();
  const workStartedAt = Number(st?.turnStartedAt || Date.now()) || Date.now();
  const timerAnchor = st?.steerTimerAnchored !== true;

  // Record the steer outside either trace segment, then use the new process
  // boundary for the continuation. This prevents old tool events from being
  // replayed below the steered user message.
  addSessionProcessEntry(sid, 'warn', `Chat steer queued: ${text.slice(0, 180)}`, {
    actor: 'Chat Steer',
    eventId: data?.eventId,
    runtimeId: data?.runtimeId,
  });
  const continuationStartIndex = sess.processLog.length;

  if (st || entries.length || liveTraceEntries.length) {
    sess.history.push({
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      workStartedAt,
      liveTraceEntries,
      processEntries: entries,
      _steerTimerAnchor: timerAnchor,
      suppressWorkTimer: !timerAnchor,
      workflowGroupId: groupId,
      workflowPart: 'before_interruption',
      workflowLabel: 'Tool stream before steer',
    });
  }
  sess.history.push({
    role: 'user',
    content: text,
    attachmentPreviews: Array.isArray(data?.attachmentPreviews) && data.attachmentPreviews.length ? data.attachmentPreviews : undefined,
    timestamp: Date.now(),
    channel: 'web',
    channelLabel: 'steer',
    workflowGroupId: groupId,
    workflowPart: 'interruption',
    workflowLabel: 'Message sent as steer',
  });
  if (st) {
    st.forceAppendAssistantAfterInterruption = true;
    st.pendingInterruptionWorkflowGroupId = groupId;
    st.pendingInterruptionWorkflowLabel = 'Response after steer';
    st.pendingInterruptionWorkflowPresentationCleared = false;
    st.steerWorkflowGroupIds = _chatSteerWorkflowGroupIds(st).concat(groupId).filter((id, index, all) => all.indexOf(id) === index);
    st.steerTimerAnchored = true;
    st.currentTurnStartIndex = continuationStartIndex;
    st.liveTraceEntries = [];
    st.currentPreflightStatus = '';
    st.currentProgressLines = [];
    st.currentProgressThinkingText = '';
  }
  persistSession(sid);
  syncSessionHistoryToServerById(sid, sess.history).catch(() => {});
  if (window.activeChatSessionId === sid) {
    window.chatHistory = sess.history;
    renderChatMessages();
  }
  return true;
}

async function steerQueuedPrompt(index) {
  const queue = getActiveQueuedPrompts();
  if (!Number.isInteger(index) || index < 0 || index >= queue.length) return;
  const turn = normalizeQueuedChatTurn(queue[index]);
  const message = String(turn.message || '').trim();
  if (!message) return;
  const sessionId = String(window.activeChatSessionId || '').trim();
  if (!sessionId || !isSessionThinking(sessionId)) {
    showToast('No active run to steer', 'This prompt can still run normally when the chat is idle.', 'info');
    return;
  }
  try {
    const queuedFiles = getQueuedTurnFiles(turn);
    let steerMessage = message;
    let attachmentPreviews = [];
    if (queuedFiles.length) {
      addSessionProcessEntry(sessionId, 'info', `Uploading ${queuedFiles.length} queued steer file(s).`, { actor: 'Chat Steer' });
      const uploadResults = await uploadStagedFilesToCanvas(queuedFiles);
      const fileContextNote = buildFileContextNote(uploadResults);
      steerMessage = fileContextNote ? message + fileContextNote : message;
      attachmentPreviews = uploadResultsToAttachmentPreviews(uploadResults);
    }
    const data = await api('/api/chat/steer', {
      method: 'POST',
      body: {
        sessionId,
        message: steerMessage,
        attachmentPreviews: attachmentPreviews.length ? attachmentPreviews.map(sanitizeAttachmentPreviewForDurableStorage) : undefined,
        source: 'web_queue_button',
      },
      timeoutMs: 15000,
    });
    queue.splice(index, 1);
    window.queuedPrompts = queue;
    updateQueuedPromptUI();
    appendChatSteerWorkflowSplit(sessionId, steerMessage, { ...data, attachmentPreviews });
    showToast('Steer sent', queuedFiles.length ? 'Files uploaded and folded into the active run.' : 'Prometheus will fold it into the active run.', 'success', 1800);
  } catch (err) {
    addSessionProcessEntry(sessionId, 'error', `Steer failed: ${String(err?.message || err)}`, { actor: 'Chat Steer' });
    showToast('Steer failed', String(err?.message || err), 'error');
  }
}

function isActiveMainGoalRunning(sessionId) {
  const sid = String(sessionId || '').trim();
  const sess = sid ? getChatSessionById(sid) : null;
  return !!(sess?.mainChatGoal && String(sess.mainChatGoal.status || '') === 'active' && isSessionThinking(sid));
}

async function steerActiveGoalRunFromComposer(message) {
  const sessionId = String(window.activeChatSessionId || '').trim();
  const text = String(message || '').trim();
  if (!sessionId || !text) return false;
  try {
    const data = await api('/api/chat/steer', {
      method: 'POST',
      body: {
        sessionId,
        message: text,
        source: 'web_goal_composer',
      },
      timeoutMs: 15000,
    });
    appendChatSteerWorkflowSplit(sessionId, text, data);
    showToast('Steer sent', 'Prometheus will fold it into the active goal run.', 'success', 1800);
    return true;
  } catch (err) {
    addSessionProcessEntry(sessionId, 'error', `Goal steer failed: ${String(err?.message || err)}`, { actor: 'Chat Steer' });
    showToast('Steer failed', String(err?.message || err), 'error');
    return false;
  }
}

function clearQueuedPrompts() {
  const queue = getActiveQueuedPrompts();
  if (!queue.length) return;
  queue.length = 0;
  window.queuedPrompts = queue;
  addProcessEntry('info', 'Cleared queued prompts.');
  updateQueuedPromptUI();
}

function updateQueuedPromptUI() {
  const badge = document.getElementById('queued-prompts-indicator');
  const sendBtn = document.getElementById('send-btn');
  const input = document.getElementById('chat-input');
  const queue = getActiveQueuedPrompts();
  window.queuedPrompts = queue;
  const count = queue.length;
  if (badge) {
    badge.style.display = 'none';
    badge.textContent = '';
  }
  if (sendBtn) {
    sendBtn.disabled = false;
    sendBtn.title = window.isThinking ? `Queue next prompt${count ? ` (${count} queued)` : ''}` : 'Send';
  }
  if (input) {
    input.placeholder = window.isThinking
      ? 'Assistant is responding. Press Enter/Send to queue next prompt.'
      : 'Send Prometheus a message';
  }
  renderQueuedPromptsPanel();
  updateBackgroundSpawnDockOffset();
}

function getVoicePendingTurns() {
  if (!Array.isArray(window._voicePendingTurns)) window._voicePendingTurns = [];
  return window._voicePendingTurns;
}

function getActiveVoicePendingTurns() {
  const sid = String(window.activeChatSessionId || '').trim();
  if (!sid) return [];
  return getVoicePendingTurns().filter((turn) => String(turn?.sessionId || '') === sid);
}

function removeVoicePendingTurnInternal(id) {
  const key = String(id || '');
  if (!key) return null;
  const turns = getVoicePendingTurns();
  const index = turns.findIndex((turn) => String(turn?.id || '') === key);
  if (index < 0) return null;
  return turns.splice(index, 1)[0] || null;
}

function markVoicePendingTurn(id, patch = {}) {
  const key = String(id || '');
  if (!key) return null;
  const turn = getVoicePendingTurns().find((entry) => String(entry?.id || '') === key);
  if (!turn) return null;
  Object.assign(turn, patch);
  return turn;
}

function renderVoicePendingTurns() {
  const turns = getActiveVoicePendingTurns();
  if (!turns.length) return '';
  return turns.map((turn) => {
    const idArg = encodeInlineJsString(turn.id);
    const files = Array.isArray(turn.files) ? turn.files : [];
    const state = String(turn.state || 'queued');
    const isLocked = state !== 'queued';
    const label = state === 'sending' ? 'Sending voice message' : 'Queued voice message';
    return `
      <div class="msg-shell user voice-pending-shell">
        <div class="msg user voice-pending-msg">
          <div class="msg-body voice-pending-body">
            <div class="msg-content">${escHtml(turn.text || '')}</div>
            <div class="voice-pending-meta">
              <span>${escHtml(label)}${files.length ? ` +${files.length} file(s)` : ''}</span>
              <span class="voice-pending-actions">
                <button class="voice-pending-btn" onclick="editVoicePendingTurn(${idArg})" ${isLocked ? 'disabled' : ''}>Edit</button>
                <button class="voice-pending-btn" onclick="removeVoicePendingTurn(${idArg})" ${isLocked ? 'disabled' : ''}>Remove</button>
              </span>
            </div>
          </div>
        </div>
      </div>`;
  }).join('');
}

function enqueueVoicePendingTurn(text, files = [], source = 'voice') {
  const message = String(text || '').trim();
  if (!message) return '';
  ensureActiveChatSessionExists();
  const sessionId = String(window.activeChatSessionId || '');
  if (isSessionThinking(sessionId) && (!Array.isArray(files) || files.length === 0)) {
    submitDesktopVoiceAsLiveSteer(message, { source }).catch((err) => {
      showToast('Voice steer failed', String(err?.message || err), 'error');
    });
    return '';
  }
  const turn = {
    id: `voice_${Date.now()}_${++voicePendingTurnSeq}`,
    sessionId,
    text: message,
    files: Array.isArray(files) ? files.slice() : [],
    source: String(source || 'voice'),
    state: 'queued',
    createdAt: Date.now(),
  };
  getVoicePendingTurns().push(turn);
  renderChatMessages();
  setTimeout(processVoicePendingTurns, 0);
  return turn.id;
}

function removeVoicePendingTurn(id) {
  const turn = getVoicePendingTurns().find((entry) => String(entry?.id || '') === String(id || ''));
  if (!turn) return;
  if (String(turn.state || 'queued') !== 'queued') {
    showToast('Voice message is already sending', 'Wait for it to appear as a chat bubble.', 'info');
    return;
  }
  removeVoicePendingTurnInternal(id);
  renderChatMessages();
}

function editVoicePendingTurn(id) {
  const turn = getVoicePendingTurns().find((entry) => String(entry?.id || '') === String(id || ''));
  if (!turn) return;
  if (String(turn.state || 'queued') !== 'queued') {
    showToast('Voice message is already sending', 'Wait for it to appear as a chat bubble before editing.', 'info');
    return;
  }
  removeVoicePendingTurnInternal(id);
  const input = document.getElementById('chat-input');
  if (input) {
    input.value = String(turn.text || '');
    resizeChatInput(input);
    input.focus();
  }
  const files = Array.isArray(turn.files) ? turn.files : [];
  if (files.length) {
    pendingChatFiles = pendingChatFiles.concat(files);
    renderChatFilePills();
  }
  renderChatMessages();
}

async function processVoicePendingTurns() {
  if (voicePendingProcessing) return;
  const sid = String(window.activeChatSessionId || '').trim();
  if (!sid || isSessionThinking(sid)) return;
  const turn = getVoicePendingTurns().find((entry) => String(entry?.sessionId || '') === sid && String(entry?.state || 'queued') === 'queued');
  if (!turn) return;
  voicePendingProcessing = true;
  markVoicePendingTurn(turn.id, { state: 'sending' });
  renderChatMessages();
  try {
    await sendChat(makeQueuedChatTurn(turn.text, turn.files), {
      voicePendingTurnId: turn.id,
      voiceAgentHandoff: true,
      voiceSource: turn.source || 'desktop_voice',
    });
  } catch (err) {
    markVoicePendingTurn(turn.id, { state: 'queued' });
    showToast('Voice message send failed', String(err?.message || err), 'error');
  } finally {
    voicePendingProcessing = false;
    setTimeout(processVoicePendingTurns, 0);
  }
}

function sanitizeBrowserCanvasStateForStorage(browserCanvasState) {
  if (!browserCanvasState || typeof browserCanvasState !== 'object') return browserCanvasState;
  const clean = { ...browserCanvasState };
  clean.frameBase64 = '';
  const registry = clean.browserSessions && typeof clean.browserSessions === 'object' && !Array.isArray(clean.browserSessions)
    ? clean.browserSessions
    : {};
  clean.browserSessions = Object.fromEntries(Object.entries(registry).map(([sessionId, record]) => {
    const next = record && typeof record === 'object' ? { ...record } : {};
    next.frameBase64 = '';
    return [sessionId, next];
  }));
  return clean;
}

function sanitizeChatSessionForStorage(session) {
  if (!session || typeof session !== 'object') return session;
  const history = Array.isArray(session.history)
    ? session.history
      .filter((msg) => !isInternalChatMessage(msg))
      .slice(-4)
      .map((msg) => {
        const next = sanitizeChatMessageForDurableStorage(msg);
        delete next.toolLog;
        delete next.processEntries;
        delete next.thinking;
        return next;
      })
    : [];
  return {
    ...session,
    history,
    processLog: [],
    creativeHistoryPast: [],
    creativeHistoryFuture: [],
    browserCanvasState: sanitizeBrowserCanvasStateForStorage(session.browserCanvasState),
  };
}

function sanitizeAttachmentPreviewForDurableStorage(attachment) {
  if (!attachment || typeof attachment !== 'object') return attachment;
  const next = { ...attachment };
  const hasDurablePath = !!String(next.workspacePath || next.path || next.filePath || '').trim();
  if (hasDurablePath) {
    delete next.dataUrl;
    delete next.base64;
    delete next.file;
  }
  return next;
}

function sanitizeChatMessageForDurableStorage(msg) {
  if (!msg || typeof msg !== 'object') return msg;
  const next = { ...msg };
  if (Array.isArray(next.attachmentPreviews)) {
    next.attachmentPreviews = next.attachmentPreviews.map(sanitizeAttachmentPreviewForDurableStorage);
  }
  return next;
}

function sanitizeChatSessionsForStorage(sessions) {
  return Array.isArray(sessions)
    ? sessions.filter(hasPersistableChatSessionContent).map((session) => sanitizeChatSessionForStorage(session))
    : [];
}

function saveChatSessions() {
  const sanitized = sanitizeChatSessionsForStorage(window.chatSessions);
  try {
    localStorage.setItem(CHAT_SESSIONS_KEY, JSON.stringify(sanitized));
  } catch (err) {
    if (err && (err.name === 'QuotaExceededError' || /quota/i.test(String(err.message || err)))) {
      console.warn('[ChatPage] localStorage quota exceeded; saving compact session index without browser frames.');
      const compact = sanitized.map((session) => ({
        ...session,
        history: Array.isArray(session.history) ? session.history.slice(-24) : [],
        processLog: Array.isArray(session.processLog) ? session.processLog.slice(-80) : [],
        creativeCheckpoints: Array.isArray(session.creativeCheckpoints) ? session.creativeCheckpoints.slice(-6) : undefined,
      }));
      try {
        localStorage.setItem(CHAT_SESSIONS_KEY, JSON.stringify(compact));
        window.chatSessions = compact;
      } catch (fallbackErr) {
        console.warn('[ChatPage] compact session save also exceeded quota; saving minimal recent session index.', fallbackErr);
        const minimal = compact.slice(-8).map((session) => ({
          id: session.id,
          title: session.title,
          createdAt: session.createdAt,
          updatedAt: session.updatedAt,
          unread: session.unread,
          automated: session.automated,
          history: Array.isArray(session.history) ? session.history.slice(-4) : [],
          processLog: [],
          browserCanvasState: null,
        }));
        try {
          localStorage.setItem(CHAT_SESSIONS_KEY, JSON.stringify(minimal));
          window.chatSessions = minimal;
        } catch (minimalErr) {
          console.error('[ChatPage] unable to persist chat sessions after quota compaction; continuing without local persistence.', minimalErr);
        }
      }
      return;
    }
    throw err;
  }
}

async function deleteSessionFromServer(id) {
  const res = await fetch(`/api/sessions/${encodeURIComponent(id)}`, { method: 'DELETE' });
  if (!res.ok && res.status !== 404) {
    const body = await res.text().catch(() => '');
    throw new Error(body || `Delete failed (${res.status})`);
  }
}

function isSessionTitleCommandMessage(msg) {
  if (!msg || msg.role !== 'user') return false;
  const text = String(msg.content || '').trim();
  return /^\/[a-z][\w-]*(?:@\w+)?(?:\s|$)/i.test(text);
}

function isCommandSessionTitle(value) {
  return /^\/[a-z][\w-]*(?:@\w+)?(?:\s|$)/i.test(String(value || '').trim());
}

function normalizeSessionTitleText(value) {
  return String(value || '')
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`[^`]*`/g, ' ')
    .replace(/https?:\/\/\S+/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[#*_~>[\]()"']/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isGreetingOnlySessionMessage(text) {
  const t = String(text || '').trim().toLowerCase();
  if (!t) return true;
  return /^(?:hey|hi|hello|yo|sup|gm|good\s+(?:morning|afternoon|evening)|howdy|hiya|heya|thanks|thank you|ok|okay|cool|nice|great|test|testing|new chat|greeting)[\s!.,-]*(?:prom|prometheus)?[\s!.,-]*(?:how(?:'|’)s it going\??|what(?:'|’)s up\??)?$/i.test(t);
}

function titleCaseSessionWord(word, index) {
  const lower = String(word || '').toLowerCase();
  const keepLower = new Set(['a', 'an', 'and', 'as', 'at', 'by', 'for', 'from', 'in', 'into', 'of', 'on', 'or', 'the', 'to', 'via', 'with']);
  const upper = new Set(['ai', 'api', 'ci', 'css', 'html', 'ui', 'ux', 'llm', 'mcp', 'pwa', 'qr', 'sms', 'seo']);
  if (upper.has(lower)) return lower.toUpperCase();
  if (index > 0 && keepLower.has(lower)) return lower;
  return lower.charAt(0).toUpperCase() + lower.slice(1);
}

function polishSessionTitle(raw) {
  let text = normalizeSessionTitleText(raw)
    .replace(/^(?:please\s+)?(?:can|could|would)\s+you\s+/i, '')
    .replace(/^(?:please\s+)?(?:can|could|would)\s+we\s+/i, '')
    .replace(/^(?:please\s+)?(?:help\s+me\s+|help\s+us\s+|help\s+)/i, '')
    .replace(/^(?:please\s+)?(?:look\s+into|check\s+out|take\s+a\s+look\s+at|investigate|review|fix|update|add|create|make|build|implement|debug)\s+/i, (match) => {
      const verb = match.replace(/please\s+/i, '').trim();
      return verb.replace(/\s+/g, ' ') + ' ';
    })
    .replace(/\b(?:please|pls|thanks|thank you)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  text = text
    .replace(/\b(?:i think|maybe|kind of|sort of|basically|actually)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const words = text.split(/\s+/).filter(Boolean);
  const stopAt = words.findIndex((word, index) => index >= 3 && /^(?:because|where|while|when|after|before|so|and|but|however)$/i.test(word));
  const kept = (stopAt > 0 ? words.slice(0, stopAt) : words).slice(0, 7);
  const title = kept.map(titleCaseSessionWord).join(' ').replace(/[.,:;!?-]+$/g, '').trim();
  return title.length > 56 ? `${title.slice(0, 53).trim()}...` : title;
}

function makeSessionTitle(history) {
  const earlyUsers = (Array.isArray(history) ? history : [])
    .filter(m => m?.role === 'user' && !isSessionTitleCommandMessage(m) && !isInternalChatMessage(m))
    .slice(0, 3);
  const candidate = earlyUsers
    .map(m => normalizeSessionTitleText(m.content))
    .find(text => text.length >= 8 && !isGreetingOnlySessionMessage(text));
  return candidate ? polishSessionTitle(candidate) || 'New chat' : 'New chat';
}

function shouldAutoRefreshSessionTitle(session, history) {
  if (session?.autoTitleLocked === true) return false;
  const current = String(session?.title || '').trim();
  if (!current || current === 'New chat' || isCommandSessionTitle(current)) return true;
  const firstUser = (Array.isArray(history) ? history : [])
    .find(m => m?.role === 'user' && !isSessionTitleCommandMessage(m) && !isInternalChatMessage(m));
  const firstUserTitle = normalizeSessionTitleText(firstUser?.content).slice(0, 60).trim();
  return !!firstUserTitle && current === firstUserTitle;
}

function applyAutoSessionTitleOnce(session, history) {
  if (!session || !shouldAutoRefreshSessionTitle(session, history)) {
    return false;
  }
  const nextTitle = makeSessionTitle(history);
  if (!nextTitle || nextTitle === 'New chat') return false;
  const changed = session.title !== nextTitle;
  session.title = nextTitle;
  if (changed && String(session.id || '') === String(window.activeChatSessionId || '') && typeof syncChatTopbarTitle === 'function') {
    syncChatTopbarTitle();
  }
  return true;
}

function applyServerSessionTitle(sessionId, title) {
  const sid = String(sessionId || '').trim();
  const nextTitle = String(title || '').replace(/\s+/g, ' ').trim();
  if (!sid || !nextTitle) return false;
  const session = getChatSessionById(sid);
  if (!session) return false;
  session.title = nextTitle;
  session.autoTitleLocked = true;
  if (sid === window.activeChatSessionId) window.chatTitle = nextTitle;
  if (sid === window.activeChatSessionId && typeof syncChatTopbarTitle === 'function') syncChatTopbarTitle();
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (typeof window.renderChannelSessionsList === 'function') window.renderChannelSessionsList();
  return true;
}

function getChatMessageTimestamp(msg) {
  const ts = Number(msg?.timestamp || 0);
  return Number.isFinite(ts) && ts > 0 ? ts : 0;
}

function getSessionLastMessageAt(session) {
  const explicit = Number(session?.lastMessageAt || 0);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const history = Array.isArray(session?.history) ? session.history : [];
  for (let i = history.length - 1; i >= 0; i--) {
    const msg = history[i];
    const role = String(msg?.role || '').toLowerCase();
    if (role !== 'user' && role !== 'assistant' && role !== 'ai') continue;
    const content = String(msg?.content || '').trim();
    if (!content || isInternalChatMessage(msg)) continue;
    const ts = getChatMessageTimestamp(msg);
    if (ts > 0) return ts;
  }
  return Number(session?.createdAt || session?.updatedAt || session?.lastActiveAt || 0) || 0;
}

function createEmptyChatSession(id = generateSessionId()) {
  const now = Date.now();
  return {
    id,
    title: 'New chat',
    autoTitleLocked: false,
    channel: 'web',
    source: 'web',
    voiceRoom: null,
    history: [],
    processLog: [],
    creativeMode: null,
    canvasProjectRoot: null,
    canvasProjectLabel: null,
    canvasProjectLink: null,
    creativeSceneDoc: null,
    creativeSelectedId: null,
    creativeTimelineMs: 0,
    creativeHistoryPast: [],
    creativeHistoryFuture: [],
    creativeHtmlMotionClip: null,
    creativeComposition: null,
    mainChatGoal: null,
    mainChatGoalHistory: [],
    createdAt: now,
    updatedAt: now,
    lastMessageAt: 0,
  };
}

function hasPersistableChatSessionContent(session) {
  if (!session || typeof session !== 'object') return false;
  if (session._needsServerLoad || session.automated) return true;
  if (session.source && session.source !== 'web') return true;
  if (Array.isArray(session.history) && session.history.length > 0) return true;
  if (Array.isArray(session.processLog) && session.processLog.length > 0) return true;
  return false;
}

function ensureActiveChatSessionExists() {
  let id = String(window.activeChatSessionId || '').trim();
  if (!id) {
    id = generateSessionId();
    window.activeChatSessionId = id;
    setAgentSessionId(id);
  }
  let sess = getChatSessionById(id);
  if (!sess) {
    sess = createEmptyChatSession(id);
    window.chatSessions.unshift(sess);
  }
  return sess;
}

function setDraftChatSession(id = generateSessionId()) {
  const nextId = String(id || '').trim() || generateSessionId();
  window.activeChatSessionId = nextId;
  setAgentSessionId(nextId);
  emptyChatBrainCardIconOrder = [];
  // A draft is a new browser scope as well as a new message scope. Clear the
  // previous chat's registry before rendering the empty chat surface.
  restoreBrowserCanvasSessionState(null);
  window.chatHistory = [];
  window.processLogEntries = [];
  window.currentCreativeMode = null;
  window.runtimeProgressState = null;
  if (typeof resetSessionStreamState === 'function') resetSessionStreamState(nextId);
  // A fresh draft must not inherit the previous chat's presentation state.
  // In particular, `window.isThinking` is a compatibility mirror that may
  // still describe a background chat which is streaming.
  const draftIsThinking = syncActiveSessionRunState();
  if (typeof window.setButtonState === 'function') window.setButtonState(draftIsThinking);
  return nextId;
}

function isAssistantLikeMessage(msg) {
  return msg?.role === 'ai' || msg?.role === 'assistant';
}

function formatAssistantWorkDuration(ms) {
  const total = Math.max(0, Math.floor(Number(ms || 0) / 1000));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = total % 60;
  if (hours > 0) return `${hours}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

function assistantWorkStartedAt(msg) {
  const explicit = Number(msg?.workStartedAt || msg?.startedAt || 0);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const ts = Number(msg?.timestamp || 0);
  return Number.isFinite(ts) && ts > 0 ? ts : 0;
}

function renderAssistantWorkTimer(msg, { active = false, startedAt = 0 } = {}) {
  if (msg?.suppressWorkTimer === true) return '';
  const start = Number(startedAt || assistantWorkStartedAt(msg) || 0);
  if (!start) return '';
  const endedAt = Number(msg?.workEndedAt || 0);
  const duration = active
    ? Date.now() - start
    : (Number.isFinite(Number(msg?.workDurationMs)) && Number(msg.workDurationMs) >= 0
      ? Number(msg.workDurationMs)
      : ((Number.isFinite(endedAt) && endedAt > 0 ? endedAt : Number(msg?.timestamp || Date.now())) - start));
  const label = `${active ? 'Working for' : 'Worked for'} ${formatAssistantWorkDuration(duration)}`;
  const traceEntries = active ? [] : desktopWorkflowTraceEntriesForMessage(msg);
  if (!liveTraceHasToolGroup(traceEntries)) return `<div class="assistant-work-timer">${escHtml(label)}</div>`;
  const drawerId = traceDrawerIdForMessage(msg);
  const open = ensureOpenProcessPanelSet().has(drawerId);
  return `<button type="button" class="assistant-work-timer assistant-work-timer--expandable${open ? ' expanded' : ''}" aria-expanded="${open ? 'true' : 'false'}" aria-controls="${escHtml(drawerId)}" onclick="toggleTraceDrawer('${escHtml(drawerId)}')">
    <span>${escHtml(label)}</span>
    <svg class="assistant-work-timer-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
  </button>`;
}

function cloneChatMessageForBranch(msg) {
  if (!msg || typeof msg !== 'object') return null;
  const clone = JSON.parse(JSON.stringify(msg));
  delete clone._promptVariants;
  delete clone._promptVariantActive;
  delete clone._editingDraft;
  return clone;
}

function getMessageCopyText(msg) {
  return String(msg?.content || '').trim();
}

function isVoiceAgentWorkerHandoffMessage(msg) {
  const label = String(msg?.channelLabel || msg?.source || '').toLowerCase();
  return msg?.voiceAgentWorkerHandoff === true
    || label.includes('voice agent handoff')
    || label.includes('realtime agent dispatch');
}

function findAssistantResponseIndex(history, userIndex) {
  const list = Array.isArray(history) ? history : [];
  for (let i = userIndex + 1; i < list.length; i++) {
    const msg = list[i];
    if (!msg) continue;
    if (msg.role === 'user') return -1;
    if (isAssistantLikeMessage(msg)) return i;
  }
  return -1;
}

function getBranchTailStartIndex(history, userIndex) {
  const assistantIndex = findAssistantResponseIndex(history, userIndex);
  return assistantIndex >= 0 ? assistantIndex + 1 : userIndex + 1;
}

function getPromptVariants(userIndex) {
  const msg = (window.chatHistory || [])[userIndex];
  return Array.isArray(msg?._promptVariants) ? msg._promptVariants : [];
}

function getPromptVariantActiveIndex(userIndex) {
  const variants = getPromptVariants(userIndex);
  const raw = Number((window.chatHistory || [])[userIndex]?._promptVariantActive);
  if (!variants.length) return -1;
  return Number.isFinite(raw) ? clamp(Math.floor(raw), 0, variants.length - 1) : 0;
}

function makePromptVariantFromTimeline(userIndex) {
  const history = window.chatHistory || [];
  const user = cloneChatMessageForBranch(history[userIndex]);
  if (!user) return null;
  const assistantIndex = findAssistantResponseIndex(history, userIndex);
  const assistant = assistantIndex >= 0 ? cloneChatMessageForBranch(history[assistantIndex]) : null;
  const tailStart = assistantIndex >= 0 ? assistantIndex + 1 : userIndex + 1;
  const tail = history.slice(tailStart).map(cloneChatMessageForBranch).filter(Boolean);
  return { user, assistant, tail };
}

function attachPromptVariantsToUserMessage(user, variants, activeIndex) {
  const next = cloneChatMessageForBranch(user) || { role: 'user', content: '', timestamp: Date.now() };
  next._promptVariants = variants;
  next._promptVariantActive = activeIndex;
  return next;
}

function saveActivePromptVariant(userIndex) {
  const history = window.chatHistory || [];
  const msg = history[userIndex];
  const variants = Array.isArray(msg?._promptVariants) ? msg._promptVariants : null;
  if (!variants || !variants.length) return variants || [];
  const activeIndex = getPromptVariantActiveIndex(userIndex);
  const current = makePromptVariantFromTimeline(userIndex);
  if (current) variants[activeIndex] = current;
  msg._promptVariants = variants;
  msg._promptVariantActive = activeIndex;
  return variants;
}

function ensurePromptVariantsForEdit(userIndex) {
  const history = window.chatHistory || [];
  const msg = history[userIndex];
  if (!msg || msg.role !== 'user') return null;
  if (Array.isArray(msg._promptVariants) && msg._promptVariants.length) {
    saveActivePromptVariant(userIndex);
    return msg._promptVariants;
  }
  const original = makePromptVariantFromTimeline(userIndex);
  msg._promptVariants = original ? [original] : [];
  msg._promptVariantActive = 0;
  return msg._promptVariants;
}

function historyForServer(history = window.chatHistory || []) {
  return (Array.isArray(history) ? history : [])
    .filter((msg) => msg && (msg.role === 'user' || isAssistantLikeMessage(msg)))
    .map((msg) => ({
      ...sanitizeChatMessageForDurableStorage(cloneChatMessageForBranch(msg)),
      role: msg.role === 'user' ? 'user' : 'assistant',
      content: String(msg.content || ''),
      timestamp: Number(msg.timestamp) || Date.now(),
    }))
    .filter((msg) => msg.content.trim());
}

async function syncActiveSessionHistoryToServer(history = window.chatHistory || [], options = {}) {
  const sid = String(window.activeChatSessionId || '').trim();
  if (!sid) return;
  try {
    const res = await fetch(`/api/sessions/${encodeURIComponent(sid)}/history`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        history: historyForServer(history),
        resetCompaction: options.resetCompaction === true,
      }),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
  } catch (err) {
    console.warn('[ChatPage] failed to sync edited session history:', err);
  }
}

async function markEditRerunResetOnServer(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  try {
    await fetch(`/api/sessions/${encodeURIComponent(sid)}/edit-rerun-reset`, { method: 'POST' });
  } catch {}
}

function waitForSessionIdle(sessionId, timeoutMs = 1800) {
  const sid = String(sessionId || '').trim();
  const start = Date.now();
  return new Promise((resolve) => {
    const tick = () => {
      if (!isSessionThinking(sid) || Date.now() - start >= timeoutMs) {
        resolve();
        return;
      }
      setTimeout(tick, 50);
    };
    tick();
  });
}

function findRecentVoiceWorkflowUserIndex(history, transcript, maxAgeMs = 180000) {
  const text = String(transcript || '').replace(/\s+/g, ' ').trim();
  if (!text || !Array.isArray(history)) return -1;
  const now = Date.now();
  for (let i = history.length - 1; i >= 0; i -= 1) {
    const msg = history[i];
    if (!msg || msg.role !== 'user') continue;
    const content = String(msg.content || '').replace(/\s+/g, ' ').trim();
    if (content !== text) continue;
    const ts = Number(msg.timestamp || 0);
    if (Number.isFinite(ts) && ts > 0 && now - ts > maxAgeMs) continue;
    if (msg.workflowGroupId || msg.voiceInterruptionEventId || /^voice_/i.test(String(msg.channel || ''))) {
      return i;
    }
  }
  return -1;
}

function appendVoiceInterruptionWorkflowSplit(sessionId, transcript, data) {
  const sid = String(sessionId || '').trim();
  const sess = getChatSessionById(sid);
  if (!sess) return false;
  const eventId = String(data?.eventId || data?.steerEventId || '').trim();
  if (eventId && Array.isArray(sess.history) && sess.history.some((msg) => String(msg?.voiceInterruptionEventId || '') === eventId)) {
    return data?.classification?.shouldAbortOriginalRun === true;
  }
  const shouldAbort = data?.classification?.shouldAbortOriginalRun === true;
  if (!shouldAbort && data?.steerApplied === true) {
    return appendChatSteerWorkflowSplit(sid, transcript || '(voice interruption)', {
      ...data,
      eventId: data?.steerEventId || data?.eventId,
      runtimeId: data?.runtimeId || data?.activeRun?.id,
    });
  }
  if (!Array.isArray(sess.history)) sess.history = [];
  if (!Array.isArray(sess.processLog)) sess.processLog = [];
  const st = getSessionStreamState(sid);
  const startIndex = Number.isFinite(Number(st?.currentTurnStartIndex)) ? Math.max(0, Number(st.currentTurnStartIndex)) : 0;
  const entries = sess.processLog.slice(startIndex);
  const groupId = `voice_workflow_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;
  const intent = String(data?.classification?.intent || 'unknown');
  const interruptionText = String(transcript || '').trim() || '(voice interruption)';
  if (entries.length) {
    sess.history.push({
      role: 'assistant',
      content: 'Tool stream continued below.',
      timestamp: Date.now(),
      processEntries: entries,
      workflowGroupId: groupId,
      workflowPart: 'before_interruption',
      workflowLabel: 'Tool stream before interruption',
      voiceInterruptionEventId: eventId || undefined,
    });
  }
  sess.history.push({
    role: 'user',
    content: interruptionText,
    timestamp: Date.now(),
    channel: 'voice',
    channelLabel: 'voice interruption',
    workflowGroupId: groupId,
    workflowPart: 'interruption',
    workflowLabel: `Interruption: ${intent}`,
    voiceInterruptionEventId: eventId || undefined,
  });
  const reply = String(data?.voiceReply || '').trim();
  const responseEntries = Array.isArray(data?.processEntries) && data.processEntries.length
    ? data.processEntries
    : sess.processLog.slice(startIndex);
  if (reply || shouldAbort) {
    sess.history.push({
      role: 'assistant',
      content: [
        reply,
        shouldAbort ? '[Stopped by user]\n\nVoice interruption stopped the active Prometheus worker. Process log preserved.' : '',
      ].filter(Boolean).join('\n\n'),
      timestamp: Date.now(),
      processEntries: responseEntries,
      workflowGroupId: groupId,
      workflowPart: shouldAbort ? 'abort_response' : 'interruption_response',
      workflowLabel: shouldAbort ? 'Abort response' : 'Interruption response',
      voiceInterruptionEventId: eventId || undefined,
    });
  }
  if (!shouldAbort && st) {
    st.forceAppendAssistantAfterInterruption = true;
    st.pendingInterruptionWorkflowGroupId = groupId;
    st.pendingInterruptionWorkflowLabel = asSteer ? 'Response after steer' : 'Interruption response';
    st.pendingInterruptionWorkflowPresentationCleared = false;
  }
  persistSession(sid);
  if (window.activeChatSessionId === sid) {
    window.chatHistory = sess.history;
    renderChatMessages();
  }
  return shouldAbort;
}

const _MSG_ICON_COPY = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="8" width="12" height="12" rx="2.5"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/></svg>`;
const _MSG_ICON_PEN = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22H21"/><path d="M15 2a2.121 2.121 0 0 1 3 3L5 17l-4 1 1-4z"/></svg>`;
const _MSG_ICON_FORK = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="4" r="2"/><circle cx="5" cy="20" r="2"/><circle cx="19" cy="20" r="2"/><path d="M12 6v5l-5.5 7M12 11l5.5 7"/></svg>`;
const _MSG_ICON_SIDE = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M12 5v14"/><path d="M7 9h2"/><path d="M15 9h2"/><path d="M15 13h2"/></svg>`;
const _MSG_ICON_PREV = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M15 18l-6-6 6-6"/></svg>`;
const _MSG_ICON_NEXT = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>`;

function renderMessageActions(msg, originalIndex) {
  const isUser = msg?.role === 'user';
  const copyTitle = isUser ? 'Copy prompt' : 'Copy response';
  const editOrFork = isUser
    ? `<button class="msg-action-btn" type="button" title="Edit prompt" onclick="startEditUserMessage(${originalIndex}, event)">${_MSG_ICON_PEN}</button>`
    : `<button class="msg-action-btn" type="button" title="Fork conversation" onclick="forkConversationFromAssistantMessage(${originalIndex}, event)">${_MSG_ICON_FORK}</button>`;
  return `<div class="msg-actions">
    <button class="msg-action-btn" type="button" title="${copyTitle}" onclick="copyChatMessage(${originalIndex}, event)">${_MSG_ICON_COPY}</button>
    ${editOrFork}
    <button class="msg-action-btn" type="button" title="Open side chat" onclick="sideChatFromMessage(${originalIndex}, event)">${_MSG_ICON_SIDE}</button>
    ${isUser ? renderPromptVariantNav(originalIndex) : ''}
  </div>`;
}

function renderPromptVariantNav(originalIndex) {
  const variants = getPromptVariants(originalIndex);
  if (variants.length < 2) return '';
  const active = getPromptVariantActiveIndex(originalIndex);
  return `<div class="msg-variant-nav" title="Prompt variants">
    <button class="msg-action-btn" type="button" title="Previous variant" ${active <= 0 ? 'disabled' : ''} onclick="switchPromptVariant(${originalIndex}, ${active - 1}, event)">${_MSG_ICON_PREV}</button>
    <span>${active + 1}/${variants.length}</span>
    <button class="msg-action-btn" type="button" title="Next variant" ${active >= variants.length - 1 ? 'disabled' : ''} onclick="switchPromptVariant(${originalIndex}, ${active + 1}, event)">${_MSG_ICON_NEXT}</button>
  </div>`;
}

function renderUserEditComposer(msg, originalIndex) {
  const value = escHtml(String(msg?.content || ''));
  return `<div class="msg-edit-composer" onclick="event.stopPropagation()">
    <textarea id="msg-edit-input-${originalIndex}" class="msg-edit-input" rows="4">${value}</textarea>
    <div class="msg-edit-actions">
      <button type="button" class="msg-edit-btn" onclick="cancelEditUserMessage(event)">Cancel</button>
      <button type="button" class="msg-edit-btn msg-edit-btn-primary" onclick="submitEditedUserMessage(${originalIndex}, event)">Send</button>
    </div>
  </div>`;
}

function isInternalChatSession(session) {
  return /^(brain_thought_|brain_dream_|brain_dream_cleanup_|subagent_chat_|task_recovery_|task_resume_brief_)/i.test(String(session?.id || ''));
}

function isInternalChatMessage(msg) {
  const text = String(msg?.content || '').trim();
  const label = String(msg?.channelLabel || msg?.channel || '').toLowerCase();
  return label === 'internal_watch'
    || /^\[Internal watch\b/i.test(text)
    || /^\[BACKGROUND_TASK_RESULT\b/i.test(text)
    || /^Restart Context Packet\b/i.test(text);
}

let visualArtifactStateSyncTimer = null;

function persistDesktopVisualArtifactState(visualId, state) {
  const id = String(visualId || '').trim();
  if (!id || !state || typeof state !== 'object') return;
  const history = Array.isArray(window.chatHistory) ? window.chatHistory : [];
  let artifact = null;
  for (const message of history) {
    artifact = Array.isArray(message?.richArtifacts)
      ? message.richArtifacts.find((item) => item?.type === 'visual' && String(item.id || '') === id)
      : null;
    if (artifact) break;
  }
  if (!artifact) return;
  const nextState = JSON.parse(JSON.stringify(state));
  if (JSON.stringify(artifact.state || {}) === JSON.stringify(nextState)) return;
  artifact.state = nextState;
  artifact.stateUpdatedAt = Date.now();
  saveChatSessions();
  if (visualArtifactStateSyncTimer) clearTimeout(visualArtifactStateSyncTimer);
  visualArtifactStateSyncTimer = setTimeout(() => {
    visualArtifactStateSyncTimer = null;
    syncActiveSessionHistoryToServer(window.chatHistory || []).catch(() => {});
  }, 450);
}

if (typeof window !== 'undefined' && !window.__PROM_DESKTOP_VISUAL_STATE_LISTENER__) {
  window.__PROM_DESKTOP_VISUAL_STATE_LISTENER__ = true;
  window.addEventListener('prometheus:visual-state-change', (event) => {
    persistDesktopVisualArtifactState(event?.detail?.visualId, event?.detail?.state);
  });
}

function setChatSessions(next) {
  const sessions = (Array.isArray(next) ? next : [])
    .filter((session) => !isInternalChatSession(session))
    .filter(hasPersistableChatSessionContent);
  if (typeof window.setChatSessionsRef === 'function') {
    return window.setChatSessionsRef(sessions);
  }
  window.chatSessions = sessions;
  return window.chatSessions;
}

function normalizeExternalImportSummary(value) {
  if (!value || typeof value !== 'object') return null;
  const source = value.source && typeof value.source === 'object' ? value.source : {};
  const provider = String(source.provider || '').trim().slice(0, 80);
  const adapter = String(source.adapter || '').trim().slice(0, 120);
  if (!provider && !adapter) return null;
  return {
    version: Number(value.version || 1) || 1,
    source: {
      provider,
      adapter,
      sourceLabel: String(source.sourceLabel || '').trim().slice(0, 120),
      sourceAccountId: String(source.sourceAccountId || '').trim().slice(0, 160) || undefined,
    },
    continuation: 'prometheus',
    sourceResume: 'unsupported',
    importedAt: Number(value.importedAt || 0) || 0,
  };
}

function normalizeStoredSession(session) {
  const history = reconcileChatHistoryAfterMerge(
    collapseDuplicateAssistantMessages(
      normalizeChatHistoryTimestamps(Array.isArray(session?.history) ? session.history.filter((msg) => !isInternalChatMessage(msg)) : [])
    )
  );
  const normalizedTitleSession = {
    title: session?.title,
    autoTitleLocked: session?.autoTitleLocked === true,
  };
  applyAutoSessionTitleOnce(normalizedTitleSession, history);
  const title = normalizedTitleSession.title || 'New chat';
  // If processLog was cleared by a localStorage quota fallback but history messages still carry
  // their processEntries, rebuild the flat processLog from those entries so the process log
  // panel is not empty on the next page load.
  const existingProcessLog = Array.isArray(session?.processLog) ? session.processLog : [];
  const processLog = existingProcessLog.length > 0
    ? existingProcessLog
    : history.flatMap((m) => processEntriesForMessage(m));
  return {
    ...session,
    title,
    autoTitleLocked: normalizedTitleSession.autoTitleLocked === true,
    history,
    processLog,
    creativeMode: normalizeCreativeMode(session?.creativeMode),
    canvasProjectRoot: normalizeCanvasPath(session?.canvasProjectRoot) || null,
    canvasProjectLabel: session?.canvasProjectLabel || null,
    canvasProjectLink: normalizeCanvasProjectLink(session?.canvasProjectLink),
    creativeSceneDoc: session?.creativeSceneDoc || null,
    creativeSelectedId: session?.creativeSelectedId || null,
    creativeTimelineMs: Number.isFinite(Number(session?.creativeTimelineMs)) ? Number(session.creativeTimelineMs) : 0,
    creativeHistoryPast: Array.isArray(session?.creativeHistoryPast) ? session.creativeHistoryPast : [],
    creativeHistoryFuture: Array.isArray(session?.creativeHistoryFuture) ? session.creativeHistoryFuture : [],
    creativeHtmlMotionClip: session?.creativeHtmlMotionClip || null,
    mainChatGoal: session?.mainChatGoal || null,
    mainChatGoalHistory: Array.isArray(session?.mainChatGoalHistory) ? session.mainChatGoalHistory : [],
    sideChat: session?.sideChat === true,
    parentSessionId: session?.parentSessionId || null,
    voiceRoom: session?.voiceRoom && typeof session.voiceRoom === 'object' ? session.voiceRoom : null,
    externalImport: normalizeExternalImportSummary(session?.externalImport),
    sidebarOrder: Number.isFinite(Number(session?.sidebarOrder)) ? Number(session.sidebarOrder) : null,
  };
}

function normalizeStoredSessionStub(session) {
  const normalized = normalizeStoredSession(session);
  return {
    ...normalized,
    history: [],
    processLog: [],
    _needsServerLoad: true,
  };
}

function loadStoredSessionStubsForStartup() {
  try {
    const raw = localStorage.getItem(CHAT_SESSIONS_KEY) || '[]';
    if (raw.length > 250000) {
      console.warn('[ChatPage] Skipping large local session cache during startup; using server summaries instead.');
      return [];
    }
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map(normalizeStoredSessionStub) : [];
  } catch {
    return [];
  }
}

function sessionStubFromServer(s) {
  const channel = String(s.channel || 'web');
  const projectId = String(s.projectId || '').trim();
  const preview = String(s.lastMessagePreview || s.preview || '').replace(/\s+/g, ' ').trim();
  return normalizeStoredSession({
    id: s.id,
    title: s.title || preview || s.id,
    preview,
    lastMessage: preview,
    lastMessagePreview: preview,
    history: [],
    processLog: [],
    creativeMode: s.creativeMode,
    canvasProjectRoot: s.canvasProjectRoot,
    canvasProjectLabel: s.canvasProjectLabel,
    canvasProjectLink: s.canvasProjectLink,
    creativeSceneDoc: s.creativeSceneDoc,
    creativeSelectedId: s.creativeSelectedId,
    creativeTimelineMs: s.creativeTimelineMs,
    creativeHistoryPast: Array.isArray(s.creativeHistoryPast) ? s.creativeHistoryPast : [],
    creativeHistoryFuture: Array.isArray(s.creativeHistoryFuture) ? s.creativeHistoryFuture : [],
    creativeHtmlMotionClip: s.creativeHtmlMotionClip || null,
    mainChatGoal: s.mainChatGoal || null,
    pinnedAt: Number(s.pinnedAt || 0) || null,
    sidebarOrder: Number.isFinite(Number(s.sidebarOrder)) ? Number(s.sidebarOrder) : null,
    settledAt: Number(s.settledAt || 0) || null,
    settled: s.settled === true || Number(s.settledAt || 0) > 0,
    activeRun: s.activeRun === true,
    createdAt: s.createdAt || Date.now(),
    updatedAt: s.lastActiveAt || s.createdAt || Date.now(),
    lastMessageAt: s.lastMessageAt || s.lastActiveAt || s.createdAt || Date.now(),
    messageCount: Number.isFinite(Number(s.messageCount)) ? Math.max(0, Math.floor(Number(s.messageCount))) : 0,
    chatModelRoute: s.chatModelRoute && typeof s.chatModelRoute === 'object' ? s.chatModelRoute : null,
    channel,
    voiceRoom: s.voiceRoom && typeof s.voiceRoom === 'object' ? s.voiceRoom : null,
    lastOrigin: s.lastOrigin && typeof s.lastOrigin === 'object' ? s.lastOrigin : undefined,
    externalImport: normalizeExternalImportSummary(s.externalImport),
    projectId: projectId || null,
    projectName: projectId ? (String(s.projectName || '').trim() || null) : null,
    source: projectId ? 'project' : (channel !== 'web' ? channel : undefined),
    automated: channel !== 'web',
    _needsServerLoad: true,
  });
}

function mergeServerSessionSummaries(summaries) {
  if (!Array.isArray(summaries) || summaries.length === 0) return;
  window.chatSessions = Array.isArray(window.chatSessions) ? window.chatSessions : [];
  const byId = new Map(window.chatSessions.map(s => [String(s.id), s]));
  let pinsChanged = false;
  for (const serverSession of summaries) {
    if (!serverSession?.id) continue;
    if (isInternalChatSession(serverSession)) continue;
    if (Array.isArray(_pinnedChats)) {
      const pinIndex = _pinnedChats.indexOf(String(serverSession.id));
      const serverPinned = Number(serverSession.pinnedAt || 0) > 0;
      if (serverPinned && pinIndex === -1) {
        _pinnedChats.push(String(serverSession.id));
        pinsChanged = true;
      } else if (!serverPinned && pinIndex !== -1) {
        _pinnedChats.splice(pinIndex, 1);
        pinsChanged = true;
      }
    }
    const serverStub = sessionStubFromServer(serverSession);
    const sessionId = String(serverSession.id);
    const existing = byId.get(sessionId);
    const activeRun = hasSessionThinkingState(sessionId)
      ? window._sessionThinking[sessionId] === true
      : serverStub.activeRun === true;
    if (existing) {
      const serverUpdatedAt = Number(serverStub.updatedAt || 0);
      const localUpdatedAt = Number(existing.updatedAt || existing.createdAt || 0);
      const serverLastMessageAt = Number(serverStub.lastMessageAt || 0);
      const localLastMessageAt = Number(existing.lastMessageAt || getSessionLastMessageAt(existing) || 0);
      Object.assign(existing, {
        title: existing.autoTitleLocked === true ? existing.title : (serverStub.title || existing.title),
        autoTitleLocked: existing.autoTitleLocked === true || serverStub.autoTitleLocked === true,
        createdAt: existing.createdAt || serverStub.createdAt,
        updatedAt: Math.max(localUpdatedAt, serverUpdatedAt) || serverStub.updatedAt,
        lastMessageAt: Math.max(localLastMessageAt, serverLastMessageAt) || existing.lastMessageAt || serverStub.lastMessageAt || 0,
        preview: String(serverStub.preview || existing.preview || '').trim(),
        lastMessage: String(serverStub.lastMessage || existing.lastMessage || '').trim(),
        lastMessagePreview: String(serverStub.lastMessagePreview || existing.lastMessagePreview || '').trim(),
        messageCount: Math.max(Number(existing.messageCount || 0), Number(serverStub.messageCount || 0), Array.isArray(existing.history) ? existing.history.length : 0),
        chatModelRoute: serverStub.chatModelRoute || existing.chatModelRoute || null,
        channel: serverStub.channel || existing.channel,
        voiceRoom: serverStub.voiceRoom || existing.voiceRoom || null,
        lastOrigin: serverStub.lastOrigin || existing.lastOrigin,
        externalImport: serverStub.externalImport || existing.externalImport || null,
        source: serverStub.source || existing.source,
        projectId: serverStub.projectId || existing.projectId || null,
        projectName: serverStub.projectName || existing.projectName || null,
        automated: existing.automated || serverStub.automated,
        creativeMode: existing.creativeMode ?? serverStub.creativeMode,
        canvasProjectRoot: existing.canvasProjectRoot || serverStub.canvasProjectRoot,
        canvasProjectLabel: existing.canvasProjectLabel || serverStub.canvasProjectLabel,
        canvasProjectLink: existing.canvasProjectLink || serverStub.canvasProjectLink,
        mainChatGoal: serverStub.mainChatGoal || existing.mainChatGoal || null,
        pinnedAt: serverStub.pinnedAt || null,
        sidebarOrder: serverStub.sidebarOrder ?? existing.sidebarOrder ?? null,
        settledAt: serverStub.settledAt || null,
        settled: serverStub.settled === true,
        activeRun,
      });
      const hasHistoryButNoProcessLog = Array.isArray(existing.history) && existing.history.length > 0
        && (!Array.isArray(existing.processLog) || existing.processLog.length === 0);
      if (serverUpdatedAt > localUpdatedAt + 250 || !Array.isArray(existing.history) || existing.history.length === 0 || hasHistoryButNoProcessLog) {
        existing._needsServerLoad = true;
      }
    } else {
      const newSession = { ...serverStub, activeRun };
      window.chatSessions.push(newSession);
      byId.set(sessionId, newSession);
    }
  }
  if (pinsChanged) localStorage.setItem('prometheus_pinned_chats', JSON.stringify(_pinnedChats));
  window.chatSessions.sort((a, b) => getSessionSortTime(b) - getSessionSortTime(a));
}

// Fetch a single session's full history from the server and populate the stub.
async function _loadSessionFromServer(id, options = {}) {
  if (/^(brain_thought_|brain_dream_|brain_dream_cleanup_|subagent_chat_|task_recovery_|task_resume_brief_)/i.test(String(id || ''))) return;
  const sess = window.chatSessions.find(s => s.id === id);
  const force = options.force === true;
  if (!sess || (!force && !sess._needsServerLoad)) return;
  try {
    const params = new URLSearchParams();
    if (options.full === true) {
      params.set('full', '1');
    } else {
      params.set('historyLimit', String(Math.max(20, Math.min(300, Number(options.historyLimit || 80)))));
      params.set('processLimit', String(Math.max(40, Math.min(500, Number(options.processLimit || 240)))));
      params.set('includeToolLog', '0');
      if (options.fullProcess === true || options.recovery === true) params.set('fullProcess', '1');
    }
    const query = params.toString();
    const data = await fetchJsonWithTimeout(`/api/sessions/${encodeURIComponent(id)}${query ? `?${query}` : ''}`, 3000);
    const s = data.session;
    if (!s) return;
    const localHistory = Array.isArray(sess.history) ? sess.history.slice() : [];
    const localProcessLog = Array.isArray(sess.processLog) ? sess.processLog.slice() : [];
    const serverHistory = (s.history || [])
      .filter((m) => !isInternalChatMessage(m))
      .map(m => ({
        ...m,
        role: m.role,
        content: m.content || '',
        timestamp: m.timestamp,
      }));
    sess.history = mergeServerAndLocalHistory(localHistory, serverHistory);
    applyDesktopInitialHistoryPage(sess, s);
    const serverProcessLog = Array.isArray(s.processLog) ? s.processLog : [];
    const messageProcessLog = (sess.history || []).flatMap((m) => processEntriesForMessage(m));
    sess.processLog = mergeProcessEntryLists(localProcessLog, serverProcessLog, messageProcessLog);
    sess.creativeMode = normalizeCreativeMode(s.creativeMode);
    sess.projectId = String(s.projectId || sess.projectId || '').trim() || null;
    sess.projectName = String(s.projectName || sess.projectName || '').trim() || null;
    sess.canvasProjectRoot = normalizeCanvasPath(s.canvasProjectRoot) || null;
    sess.canvasProjectLabel = s.canvasProjectLabel || null;
    sess.canvasProjectLink = normalizeCanvasProjectLink(s.canvasProjectLink);
    sess.creativeSceneDoc = s.creativeSceneDoc || null;
    sess.creativeSelectedId = s.creativeSelectedId || null;
    sess.creativeTimelineMs = Number.isFinite(Number(s.creativeTimelineMs)) ? Number(s.creativeTimelineMs) : 0;
    sess.creativeHtmlMotionClip = s.creativeHtmlMotionClip || null;
    sess.mainChatGoal = s.mainChatGoal || null;
    sess.chatModelRoute = s.chatModelRoute && typeof s.chatModelRoute === 'object' ? s.chatModelRoute : (sess.chatModelRoute || null);
    sess.pinnedAt = Number(s.pinnedAt || 0) || null;
    sess.settledAt = Number(s.settledAt || 0) || null;
    sess.settled = s.settled === true || Number(s.settledAt || 0) > 0;
    sess.mainChatGoalHistory = Array.isArray(s.mainChatGoalHistory) ? s.mainChatGoalHistory : [];
    if (s.autoTitleLocked === true && String(s.title || '').trim()) {
      sess.title = String(s.title || '').trim();
      sess.autoTitleLocked = true;
    }
    const channel = String(s.channel || sess.source || '').trim();
    if (channel && channel !== 'web') {
      sess.source = channel;
      sess.automated = true;
    }
    sess.channel = channel || sess.channel || 'web';
    sess.voiceRoom = s.voiceRoom && typeof s.voiceRoom === 'object'
      ? s.voiceRoom
      : (sess.voiceRoom || null);
    sess.externalImport = normalizeExternalImportSummary(s.externalImport) || normalizeExternalImportSummary(sess.externalImport);
    applyAutoSessionTitleOnce(sess, sess.history);
    sess.createdAt = s.createdAt || sess.createdAt;
    sess.updatedAt = s.lastActiveAt || sess.updatedAt;
    sess.lastMessageAt = s.lastMessageAt || getSessionLastMessageAt(sess);
    const lastMessage = [...(sess.history || [])].reverse().find((message) => {
      const role = String(message?.role || '').toLowerCase();
      return ['user', 'assistant', 'ai'].includes(role) && String(message?.content || '').trim();
    });
    const preview = String(lastMessage?.content || '').replace(/\s+/g, ' ').trim();
    if (preview) {
      sess.preview = preview.slice(0, 220);
      sess.lastMessage = sess.preview;
      sess.lastMessagePreview = sess.preview;
    }
    delete sess._needsServerLoad;
    syncDesktopChatRuntime(sess, { source: 'desktop-initial-page', pageInfo: sess.historyPage });
    saveChatSessions();
    if (window.activeChatSessionId === id) {
      scheduleChatContextWindowRefresh(250);
      window.refreshActiveChatModelRoute?.();
    }
  } catch {}
}

async function loadChatSessions() {
  setChatSessions(loadStoredSessionStubsForStartup());
  let serverSessions = [];
  try {
    const data = await fetchChatSessionSummariesWithRetry();
    if (data) {
      serverSessions = Array.isArray(data.sessions) ? data.sessions : [];
    }
  } catch {}

  if (serverSessions.length > 0) {
    mergeServerSessionSummaries(serverSessions);
    if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  }

  const rememberedSessionId = recallActiveChatSessionId();
  const rememberedSession = rememberedSessionId ? getChatSessionById(rememberedSessionId) : null;
  const rememberedRun = rememberedSessionId ? readDesktopActiveChatRun(rememberedSessionId) : null;
  const shouldRestoreRememberedSession = !!rememberedSessionId && !!rememberedSession && (
    !!rememberedRun
    || rememberedSession.activeRun === true
    || (String(rememberedSession.title || '').trim() && String(rememberedSession.title || '').trim() !== 'New chat')
  );
  const startupSessionId = shouldRestoreRememberedSession ? rememberedSessionId : generateSessionId();
  if (shouldRestoreRememberedSession) {
    window.activeChatSessionId = startupSessionId;
    setAgentSessionId(startupSessionId);
    await _loadSessionFromServer(startupSessionId, {
      force: true,
      historyLimit: 80,
      processLimit: 240,
      recovery: !!rememberedRun || rememberedSession.activeRun === true,
    });
  } else {
    setDraftChatSession(startupSessionId);
  }
  if (!window.agentSessionId || window.agentSessionId !== window.activeChatSessionId) setAgentSessionId(window.activeChatSessionId);
  saveChatSessions();
  syncActiveChat();
  if (isDesktopVoiceRoomSession(window.activeChatSessionId)) {
    syncDesktopVoiceRoomForSession(window.activeChatSessionId, getChatSessionById(window.activeChatSessionId));
  } else {
    resetDesktopVoiceRoomState();
  }

  // Periodically refresh one unified timeline to surface activity from every
  // connected transport if a websocket frame was missed.
  if (window._sessionListRefreshTimer) clearInterval(window._sessionListRefreshTimer);
  window._sessionListRefreshTimer = setInterval(async () => {
    try {
      const data = await fetchJsonWithTimeout('/api/sessions?scope=all&includeAutomated=1&limit=160&offset=0', 2500);
      if (data) {
        const svr = Array.isArray(data.sessions) ? data.sessions : [];
        if (svr.length > 0) {
          mergeServerSessionSummaries(svr);
          if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
        }
      }
    } catch {}
  }, 45000);
}

function getActiveMainChatGoal() {
  const sess = window.chatSessions.find(s => s.id === window.activeChatSessionId);
  return sess?.mainChatGoal || null;
}

let mainGoalElapsedTimer = null;
let mainGoalDetailsOpen = false;

function mainGoalTimestampMs(value) {
  if (value === null || value === undefined || value === '') return 0;
  const numeric = Number(value);
  if (Number.isFinite(numeric) && numeric > 0) return numeric;
  const parsed = Date.parse(String(value));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
}

function mainGoalStartedAtMs(goal) {
  return mainGoalTimestampMs(goal?.createdAt || goal?.created_at || goal?.startedAt);
}

function mainGoalPauseStartedAtMs(goal) {
  return mainGoalTimestampMs(goal?.pauseStartedAt || goal?.pause_started_at);
}

function mainGoalPausedMs(goal) {
  const value = Number(goal?.pausedMs || goal?.paused_ms);
  return Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0;
}

function mainGoalFinishedAtMs(goal) {
  return mainGoalTimestampMs(goal?.completedAt || goal?.failedAt || goal?.blockedAt || goal?.updatedAt);
}

function mainGoalElapsedMs(goal) {
  const startedAt = mainGoalStartedAtMs(goal);
  if (!startedAt) return 0;
  const status = String(goal?.status || 'active');
  if (status === 'paused' || status === 'restarting') {
    const pausedMs = mainGoalPausedMs(goal);
    const pauseStartedAt = mainGoalPauseStartedAtMs(goal);
    const totalPausedMs = pauseStartedAt ? pausedMs + Math.max(0, Date.now() - pauseStartedAt) : pausedMs;
    const endAt = (mainGoalFinishedAtMs(goal) || Date.now()) - totalPausedMs;
    return Math.max(0, endAt - startedAt);
  }
  if (['completed', 'done', 'failed', 'blocked', 'cleared'].includes(status)) {
    const endedAt = mainGoalFinishedAtMs(goal) || Date.now();
    return Math.max(0, endedAt - startedAt - mainGoalPausedMs(goal));
  }
  return Math.max(0, Date.now() - startedAt - mainGoalPausedMs(goal));
}

function formatGoalElapsed(ms) {
  const total = Math.max(0, Math.floor(Number(ms || 0) / 1000));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = total % 60;
  if (hours > 0) return `${hours}h ${minutes}m ${seconds}s`;
  if (minutes > 0) return `${minutes}m ${seconds}s`;
  return `${seconds}s`;
}

function mainGoalStatusLabel(status) {
  const value = String(status || 'active').toLowerCase();
  if (value === 'done' || value === 'completed') return 'Completed goal';
  if (value === 'paused') return 'Paused goal';
  if (value === 'restarting') return 'Applying changes';
  if (value === 'blocked') return 'Blocked goal';
  if (value === 'failed') return 'Failed goal';
  return 'Pursuing goal';
}

function mainGoalTurnPlans(goal) {
  return Array.isArray(goal?.turnPlans) ? goal.turnPlans : [];
}

function renderMainGoalDiagnostics(goal) {
  const rows = [
    ['Quality', goal?.lastQualityGrade || ''],
    ['Open issues', Array.isArray(goal?.lastUnresolvedIssues) ? goal.lastUnresolvedIssues.join(' | ') : ''],
    ['Missing criteria', Array.isArray(goal?.lastMissingAcceptanceCriteria) ? goal.lastMissingAcceptanceCriteria.join(' | ') : ''],
    ['Verification gaps', Array.isArray(goal?.lastVerificationGaps) ? goal.lastVerificationGaps.join(' | ') : ''],
  ].filter(([, value]) => String(value || '').trim());
  if (!rows.length) return '';
  return `<div class="main-goal-diagnostics">
    ${rows.map(([label, value]) => `<div><strong>${escHtml(label)}</strong><span>${escHtml(String(value).slice(0, 700))}</span></div>`).join('')}
  </div>`;
}

function renderMainGoalTurnPlans(goal) {
  const plans = mainGoalTurnPlans(goal);
  if (!plans.length) {
    return '<div class="main-goal-plan-empty">No turn plan has been declared yet.</div>';
  }
  const total = plans.length;
  return `<div class="main-goal-turn-plans">
    ${plans.map((plan, index) => {
      const steps = Array.isArray(plan?.steps) ? plan.steps : [];
      const complete = steps.filter((step) => ['done', 'skipped'].includes(normalizeProgressStatus(step?.status))).length;
      const title = `Turn ${index + 1}/${total}`;
      const status = String(plan?.status || 'planned');
      const judge = String(plan?.judgeReason || '').trim();
      return `<section class="main-goal-turn-plan" data-plan-status="${escHtml(status)}">
        <div class="main-goal-turn-head">
          <strong>${escHtml(title)}</strong>
          <span>${escHtml(status)} · ${escHtml(String(complete))}/${escHtml(String(steps.length))}</span>
        </div>
        <div class="main-goal-turn-steps">
          ${steps.length ? renderChecklistItemsHTML(steps, { maxText: 170 }) : '<div class="main-goal-plan-empty">This turn has no tracked steps.</div>'}
        </div>
        ${judge ? `<div class="main-goal-turn-judge">${escHtml(judge.slice(0, 700))}</div>` : ''}
      </section>`;
    }).join('')}
  </div>`;
}

function updateMainGoalElapsedLabel() {
  const goal = getActiveMainChatGoal();
  const label = document.querySelector('[data-main-goal-elapsed]');
  if (!label || !goal || goal.status === 'cleared') return;
  label.textContent = formatGoalElapsed(mainGoalElapsedMs(goal));
}

function syncMainGoalElapsedTimer() {
  const goal = getActiveMainChatGoal();
  const shouldTick = !!goal && String(goal.status || '') === 'active' && mainGoalStartedAtMs(goal) > 0;
  if (!shouldTick) {
    if (mainGoalElapsedTimer) clearInterval(mainGoalElapsedTimer);
    mainGoalElapsedTimer = null;
    return;
  }
  updateMainGoalElapsedLabel();
  if (!mainGoalElapsedTimer) mainGoalElapsedTimer = setInterval(updateMainGoalElapsedLabel, 1000);
}

function toggleMainGoalDetails() {
  mainGoalDetailsOpen = !mainGoalDetailsOpen;
  renderMainGoalStrip();
}

function renderMainGoalStrip() {
  const strip = document.getElementById('main-goal-strip');
  if (!strip) return;
  const chatView = document.getElementById('chat-view');
  const goal = getActiveMainChatGoal();
  if (!goal || ['cleared', 'done', 'completed'].includes(String(goal.status || '').toLowerCase())) {
    strip.style.display = 'none';
    strip.innerHTML = '';
    chatView?.classList.remove('has-main-goal');
    syncMainGoalElapsedTimer();
    return;
  }
  const status = String(goal.status || 'active');
  const isActive = status === 'active';
  const canResume = ['paused', 'blocked', 'failed'].includes(status);
  const reason = goal.blockedReason || goal.pausedReason || goal.failureReason || goal.lastReason || '';
  const deniedActions = Array.isArray(goal.deniedActions) ? goal.deniedActions : [];
  const latestDenial = deniedActions[deniedActions.length - 1] || null;
  const plans = mainGoalTurnPlans(goal);
  const latestPlan = plans[plans.length - 1] || null;
  const policyMeta = [
    mainGoalStatusLabel(status),
    `${Number(goal.turnsUsed || 0)} turns`,
    latestPlan ? `turn plans ${plans.length}` : '',
    'Autonomous',
    'Hard policy active',
    deniedActions.length ? `${deniedActions.length} denied` : '',
    reason,
  ].filter(Boolean).join(' · ');
  const judgeReprompt = String(goal.nextStepDirective || goal.lastJudgeDirective || goal.lastReason || '').trim();
  const expanded = mainGoalDetailsOpen === true;
  strip.style.display = 'flex';
  strip.setAttribute('data-status', status);
  chatView?.classList.add('has-main-goal');
  strip.innerHTML = `
    <button type="button" class="main-goal-main" onclick="toggleMainGoalDetails()" aria-expanded="${expanded ? 'true' : 'false'}" title="Show goal details">
      <div class="main-goal-kicker"><span>${escHtml(mainGoalStatusLabel(status))}</span><span class="main-goal-elapsed" data-main-goal-elapsed>${escHtml(formatGoalElapsed(mainGoalElapsedMs(goal)))}</span></div>
      <div class="main-goal-title" title="${escHtml(goal.goal || '')}">${escHtml(goal.goal || 'Untitled goal')}</div>
      <div class="main-goal-meta">${escHtml(policyMeta)}</div>
      ${latestDenial ? `<div class="main-goal-denial">${escHtml(`Latest denied: ${latestDenial.category || 'policy'} - ${latestDenial.reason || 'Blocked by hard policy.'}`)}</div>` : ''}
      ${expanded ? `
        <div class="main-goal-details">
          <div><strong>Turns</strong><span>${escHtml(String(Number(goal.turnsUsed || 0)))}</span></div>
          <div><strong>Original goal</strong><span>${escHtml(goal.goal || 'Untitled goal')}</span></div>
          <div><strong>Last judge reprompt</strong><span>${escHtml(judgeReprompt || 'No judge reprompt yet.')}</span></div>
          ${renderMainGoalDiagnostics(goal)}
          ${renderMainGoalTurnPlans(goal)}
        </div>
      ` : ''}
    </button>
    <div class="main-goal-actions">
      ${isActive ? `<button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('pause')" title="Pause goal">Pause</button>` : ''}
      ${canResume ? `<button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('resume')" title="Resume goal">Resume</button>` : ''}
      <button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('status')" title="Refresh goal">Status</button>
      <button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('revise')" title="Revise goal">Revise</button>
      ${status !== 'done' ? `<button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('done')" title="Mark goal done">Done</button>` : ''}
      <button class="main-goal-action" type="button" onclick="event.stopPropagation(); mainGoalAction('clear')" title="Clear goal">Clear</button>
    </div>
  `;
  syncMainGoalElapsedTimer();
}

async function mainGoalAction(action) {
  const sid = String(window.activeChatSessionId || '').trim();
  if (!sid) return;
  try {
    const body = {};
    if (action === 'pause') {
      const reason = window.prompt?.('Pause reason (optional)', '') || '';
      if (reason.trim()) body.text = reason.trim();
    } else if (action === 'done') {
      const note = window.prompt?.('Completion note (optional)', '') || '';
      if (note.trim()) body.text = note.trim();
    } else if (action === 'clear') {
      const ok = window.confirm?.('Clear and archive this goal?') ?? true;
      if (!ok) return;
      const note = window.prompt?.('Archive note (optional)', '') || '';
      if (note.trim()) body.text = note.trim();
    } else if (action === 'revise') {
      const current = getActiveMainChatGoal();
      const goal = window.prompt?.('Revise goal', current?.goal || '') || '';
      if (!goal.trim()) return;
      body.goal = goal.trim();
    }
    const result = await api(`/api/sessions/${encodeURIComponent(sid)}/main-goal/${encodeURIComponent(action)}`, { method: 'POST', body });
    const sess = window.chatSessions.find(s => s.id === sid);
    if (sess) sess.mainChatGoal = result?.goal || null;
    renderMainGoalStrip();
    if (action === 'status' && result?.message) showToast('Goal status', result.message.slice(0, 240), 'info');
    if (action !== 'status') showToast('Goal updated', result?.message || action, 'success');
  } catch (err) {
    showToast('Goal action failed', err?.message || String(err), 'error');
  }
}

function syncActiveChat() {
  const sess = window.chatSessions.find(s => s.id === window.activeChatSessionId);
  activateDesktopChatRuntime(sess);
  const visibleSideLink = window.sideChatSplitOpen ? getActiveSideChatLink() : null;
  if (!visibleSideLink) {
    const staleSideSessionId = String(window.activeSideChatId || '').trim();
    setDesktopSecondaryChatRuntime('');
    if (window.sideChatSplitOpen) {
      window.sideChatSplitOpen = false;
      window.activeSideChatId = '';
      dispatchDesktopChatLifecycle('side-chat-state', { open: false, sessionId: staleSideSessionId });
    }
  } else {
    setDesktopSecondaryChatRuntime(visibleSideLink.id);
    const visibleSideSession = getChatSessionById(visibleSideLink.id);
    if (visibleSideSession) syncDesktopChatRuntime(visibleSideSession, { source: 'desktop-secondary-session-switch' });
  }
  syncChatTopbarTitle();
  // Model/reasoning is per chat. Refresh it on every session switch instead of
  // letting the global provider-health poll overwrite the composer label.
  if (sess?.id && typeof window.refreshActiveChatModelRoute === 'function') {
    window.refreshActiveChatModelRoute().catch(() => {});
  }
  window.chatHistory = sess ? (sess.history || []) : [];
  window.processLogEntries = sess ? (sess.processLog || []) : [];
  window.currentCreativeMode = normalizeCreativeMode(sess?.creativeMode);
  canvasProjectRoot = normalizeCanvasPath(sess?.canvasProjectRoot) || null;
  canvasProjectLabel = sess?.canvasProjectLabel || null;
  canvasProjectLink = normalizeCanvasProjectLink(sess?.canvasProjectLink);
  const incomingCreativeSceneDoc = sess?.creativeSceneDoc ? createSceneDocument(sess.creativeSceneDoc) : createSceneDocument();
  const currentElements = Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [];
  const incomingElements = Array.isArray(incomingCreativeSceneDoc?.elements) ? incomingCreativeSceneDoc.elements : [];
  const currentHasHyperframesSource = currentElements.some((element) => (
    element?.type === 'hyperframes'
    && (
      String(element?.meta?.html || '').trim()
      || String(element?.meta?.projectPath || '').trim()
    )
  ));
  const incomingLooksLikeDefaultBlankVideoScene = incomingElements.length === 0
    && normalizeCreativeMode(sess?.creativeMode || window.currentCreativeMode) === 'video'
    && Math.round(Number(incomingCreativeSceneDoc?.durationMs) || 0) === 12000;
  const sameCreativeSceneSession = String(window._lastCreativeSceneSessionId || '') === String(sess?.id || '');
  if (sameCreativeSceneSession && currentHasHyperframesSource && incomingLooksLikeDefaultBlankVideoScene) {
    console.warn('Refused stale blank Creative scene rehydration while HyperFrames source is active.', { incomingCreativeSceneDoc });
    if (sess) sess.creativeSceneDoc = creativeSceneDoc;
  } else {
    creativeSceneDoc = incomingCreativeSceneDoc;
  }
  window._lastCreativeSceneSessionId = sess?.id || '';
  creativeSelectedId = sess?.creativeSelectedId || null;
  creativeTimelineMs = Number.isFinite(Number(sess?.creativeTimelineMs)) ? Number(sess.creativeTimelineMs) : 0;
  creativeHistoryPast = Array.isArray(sess?.creativeHistoryPast) ? sess.creativeHistoryPast.slice() : [];
  creativeHistoryFuture = Array.isArray(sess?.creativeHistoryFuture) ? sess.creativeHistoryFuture.slice() : [];
  creativeHtmlMotionClip = sess?.creativeHtmlMotionClip || null;
  creativeComposition = sess?.creativeComposition || null;
  restoreBrowserCanvasSessionState(sess?.browserCanvasState);
  if (window.currentCreativeMode) {
    closeBrowserModeForCreativeSwitch({ persist: false, syncRemote: false });
  }
  window.prometheusCreativeScene = creativeSceneDoc;
  window.prometheusCreativeSelectionId = creativeSelectedId;
  canvasWorkspaceTree = [];
  canvasWorkspaceRootPath = '';
  canvasFolderExpanded.clear();
  window.runtimeProgressState = normalizeDeclaredRuntimeProgressState(sess?.progressState);
  if (sess?.activeRun === true && !hasSessionThinkingState(sess.id)) {
    window._sessionThinking[sess.id] = true;
    const st = getSessionStreamState(sess.id) || resetSessionStreamState(sess.id);
    st.currentTurnStartIndex = inferCurrentTurnProcessStartIndex(sess);
    st.turnStartedAt = Number(st.turnStartedAt || getSessionLastMessageAt(sess) || Date.now());
    recoverDesktopMainChatSession(sess.id, { recovery: true, fullRefresh: false }).catch(() => {});
  }
  if (sess) {
    if (window._sessionThinking && window._sessionThinking[sess.id]) {
      applyStreamStateToWindow(sess.id);
    } else {
      window.streamingAIText = '';
      window.streamingThinkingText = '';
      window.currentPreflightStatus = '';
      window.currentProgressLines = [];
      window.currentProgressThinkingActive = false;
      window.currentProgressThinkingText = '';
      window.currentTurnStartIndex = -1;
      window.activeModelBadge = null;
    }
  }
  renderMainGoalStrip();
  renderChatMessages();
  renderProcessLog();
  renderProgressPanel();
  // Reset session list pagination when loading fresh sessions
  if (typeof window._sessionShowCount !== 'undefined') window._sessionShowCount = 20;
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (typeof window.updateStats === 'function') window.updateStats([]);
  // Restore canvas tabs for this session (re-fetch content from disk)
  canvasTabs = [];
  activeCanvasTabId = null;
  if (canvasEditor) setCanvasEditorValue('');
  canvasRenderTabs();
  applyCanvasViewMode('code', null);
  const savedPaths = sess && Array.isArray(sess.canvasFiles) ? sess.canvasFiles : [];
  if (savedPaths.length > 0) {
    // Show notify dot so user knows canvas has files for this session
    const dot = document.getElementById('canvas-notify-dot');
    if (dot && !canvasOpen) dot.style.display = 'block';
    // Silently load tabs in background (don't auto-open canvas)
    savedPaths.forEach(f => {
      canvasPresentFile(f.diskPath, f.name, { autoOpen: false }).catch(() => {});
    });
  } else {
    const dot = document.getElementById('canvas-notify-dot');
    if (dot) dot.style.display = 'none';
  }
  if (canvasProjectRoot) {
    canvasLoadWorkspaceFiles(canvasProjectRoot).catch(() => {});
    loadCanvasPublishState().catch(() => {});
  } else {
    updateCanvasWorkspaceChrome();
    renderCanvasPublishControls();
  }
  applyCreativeModeUI();
  renderBrowserCanvasSurface();
  // Instantly refresh pending actions for the new session
  if (typeof window.loadSessionApprovals === 'function') window.loadSessionApprovals();
  if (sess && !window._sessionThinking?.[sess.id]) {
    restorePendingInlineApprovalsForSession(sess.id).catch(() => {});
    restorePendingInlineQuestionsForSession(sess.id).catch(() => {});
  }
  // Sync button/input state for the newly active session
  const activeSessThinking = syncActiveSessionRunState();
  if (typeof window.setButtonState === 'function') window.setButtonState(activeSessThinking);
  updateQueuedPromptUI();
  scheduleChatContextWindowRefresh(250);
  dispatchDesktopChatLifecycle('chat-session-activated', {
    sessionId: String(sess?.id || ''),
    sideSessionId: window.sideChatSplitOpen ? String(window.activeSideChatId || '') : '',
  });
}

function refreshVisibleChannelsList() {
  const channelPanel = document.getElementById('sidebar-channels');
  if (!channelPanel || channelPanel.style.display === 'none') return;
  if (typeof window.renderChannelsList === 'function') window.renderChannelsList();
}

function persistActiveChat() {
  const idx = window.chatSessions.findIndex(s => s.id === window.activeChatSessionId);
  if (idx === -1) return;
  window.chatSessions[idx].history = window.chatHistory;
  window.chatSessions[idx].processLog = window.processLogEntries;
  window.chatSessions[idx].progressState = window.runtimeProgressState;
  applyAutoSessionTitleOnce(window.chatSessions[idx], window.chatHistory);
  window.chatSessions[idx].updatedAt = Date.now();
  window.chatSessions[idx].creativeMode = normalizeCreativeMode(window.currentCreativeMode);
  window.chatSessions[idx].canvasProjectRoot = canvasProjectRoot || null;
  window.chatSessions[idx].canvasProjectLabel = canvasProjectLabel || null;
  window.chatSessions[idx].canvasProjectLink = normalizeCanvasProjectLink(canvasProjectLink);
  window.chatSessions[idx].creativeSceneDoc = creativeSceneDoc || null;
  window.chatSessions[idx].creativeSelectedId = creativeSelectedId || null;
  window.chatSessions[idx].creativeTimelineMs = Number.isFinite(Number(creativeTimelineMs)) ? Number(creativeTimelineMs) : 0;
  window.chatSessions[idx].creativeHistoryPast = creativeHistoryPast.slice();
  window.chatSessions[idx].creativeHistoryFuture = creativeHistoryFuture.slice();
  window.chatSessions[idx].creativeHtmlMotionClip = creativeHtmlMotionClip || null;
  window.chatSessions[idx].browserCanvasState = snapshotBrowserCanvasSessionState();
  // Save canvas files for this session (diskPath + name only, content re-fetched from disk)
  window.chatSessions[idx].canvasFiles = canvasTabs
    .filter(t => t.diskPath)
    .map(t => ({ diskPath: t.diskPath, name: t.name }));
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (typeof window.updateStats === 'function') window.updateStats([]);
}

// Load terminal sessions from the server
async function loadTerminalSessions() {
  try {
    const res = await fetch('/api/sessions?scope=all&includeAutomated=1&limit=200&offset=0');
    const data = await res.json();
    const sessions = Array.isArray(data.sessions) ? data.sessions : [];
    window.channelSessionsByChannel = {};
    window.terminalSessions = [];
    window.mobileSessions = [];
    window.telegramSessions = [];
    window.discordSessions = [];
    window.whatsappSessions = [];
    mergeServerSessionSummaries(sessions);
    saveChatSessions();
  } catch {
    window.terminalSessions = [];
    window.mobileSessions = [];
    window.telegramSessions = [];
    window.discordSessions = [];
    window.whatsappSessions = [];
    window.channelSessionsByChannel = {};
  }
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
}

// Open a terminal session by loading it from the server and adding to chat sessions
async function openTerminalSession(id, source = 'terminal') {
  try {
    const res = await fetch(`/api/sessions/${id}`);
    const data = await res.json();
    if (!data.session) return;
    const s = data.session;
    source = String(s.channel || source || 'terminal').trim();

    // Check if already in chatSessions
    let existing = window.chatSessions.find(c => c.id === id);
    if (!existing) {
      existing = {
        id: s.id,
        title: s.title || s.id,
        history: (s.history || []).map(m => ({
          role: m.role === 'user' ? 'user' : 'assistant',
          content: m.content,
          timestamp: m.timestamp,
          channel: m.channel || source,
          channelLabel: m.channelLabel || source,
          origin: m.origin && typeof m.origin === 'object' ? m.origin : undefined,
          source: m.source,
          voiceSpeaker: m.voiceSpeaker,
          voiceTargetKey: m.voiceTargetKey,
        })),
        processLog: [],
        creativeMode: normalizeCreativeMode(s.creativeMode),
        canvasProjectRoot: normalizeCanvasPath(s.canvasProjectRoot) || null,
        canvasProjectLabel: s.canvasProjectLabel || null,
        canvasProjectLink: normalizeCanvasProjectLink(s.canvasProjectLink),
        creativeSceneDoc: s.creativeSceneDoc || null,
        creativeSelectedId: s.creativeSelectedId || null,
        creativeTimelineMs: Number.isFinite(Number(s.creativeTimelineMs)) ? Number(s.creativeTimelineMs) : 0,
        creativeHistoryPast: Array.isArray(s.creativeHistoryPast) ? s.creativeHistoryPast : [],
        creativeHistoryFuture: Array.isArray(s.creativeHistoryFuture) ? s.creativeHistoryFuture : [],
        creativeHtmlMotionClip: s.creativeHtmlMotionClip || null,
        createdAt: s.createdAt,
        updatedAt: s.lastActiveAt,
        lastMessageAt: s.lastMessageAt || getSessionLastMessageAt({ history: (s.history || []), createdAt: s.createdAt, updatedAt: s.lastActiveAt }),
        automated: source !== 'web',
        source,
        voiceRoom: s.voiceRoom || null,
      };
      window.chatSessions.unshift(existing);
      saveChatSessions();
    } else {
      existing.source = source !== 'web' ? source : existing.source;
      existing.channel = source || existing.channel || 'web';
      existing.automated = source !== 'web' ? true : existing.automated;
      existing.voiceRoom = s.voiceRoom && typeof s.voiceRoom === 'object' ? s.voiceRoom : (existing.voiceRoom || null);
      existing._needsServerLoad = true;
      await _loadSessionFromServer(id, { force: true });
    }

    if (window.currentMode !== 'chat') {
      if (typeof window.setMode === 'function') window.setMode('chat');
      else setMode('chat');
    }

    window.activeChatSessionId = id;
    setAgentSessionId(id);
    markSessionRead(id);
    syncActiveChat();
    refreshVisibleChannelsList();
    if (source === 'voice_room') {
      restoreDesktopVoiceRoomSession(id).catch((error) => showDesktopVoiceStatus('Voice Room needs microphone access', error?.message || 'Enable microphone access to join this room.', 'error'));
    } else {
      resetDesktopVoiceRoomState();
    }
  } catch (e) {
    addProcessEntry('error', `Could not load terminal session: ${e.message}`);
  }
}

function newChatSession() {
  const id = generateSessionId();
  if (realtimeVoiceRepliesEnabled || realtimeVoiceStarting || voiceAgentRealtimeConnection || voiceAgentRealtimeConnecting) {
    disableRealtimeVoiceMode();
  }
  resetDesktopVoiceRoomState({ resetTarget: true });
  if (window.currentMode !== 'chat') {
    if (typeof window.setMode === 'function') window.setMode('chat');
    else setMode('chat');
  }
  if (typeof window.setSidebarSegTab === 'function') window.setSidebarSegTab('chats');
  resetDesktopNewChatContext();
  setDraftChatSession(id);
  // New regular chat always exits project mode before the empty-state render;
  // otherwise a stale project dataset can suppress the desktop context dock
  // for the first frame of the new-chat screen.
  if (typeof window._maybeClearProjectState === 'function') {
    window._maybeClearProjectState(id);
  }
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (typeof window.renderChannelSessionsList === 'function') window.renderChannelSessionsList();
  renderChatMessages();
  if (chatResourcesState.open) loadChatResources({ sessionId: id });
}

function toggleSessionsEditMode() {
  window.sessionsEditMode = !window.sessionsEditMode;
  const btn = document.getElementById('sessions-edit-btn');
  if (btn) btn.textContent = window.sessionsEditMode ? 'Done' : 'Edit';
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
}

async function deleteChatSession(id, ev) {
  if (ev) ev.stopPropagation();
  const idx = window.chatSessions.findIndex(s => s.id === id);
  try {
    await deleteSessionFromServer(id);
  } catch (err) {
    showToast(`Delete failed: ${err.message}`, 'error');
    return;
  }

  if (idx !== -1) window.chatSessions.splice(idx, 1);
  if (Array.isArray(window.terminalSessions)) {
    window.terminalSessions = window.terminalSessions.filter(s => s.id !== id);
  }
  if (Array.isArray(window.mobileSessions)) {
    window.mobileSessions = window.mobileSessions.filter(s => s.id !== id);
  }
  ['telegramSessions', 'discordSessions', 'whatsappSessions'].forEach((key) => {
    if (Array.isArray(window[key])) window[key] = window[key].filter(s => s.id !== id);
  });
  if (window.channelSessionsByChannel && typeof window.channelSessionsByChannel === 'object') {
    Object.keys(window.channelSessionsByChannel).forEach((channel) => {
      if (Array.isArray(window.channelSessionsByChannel[channel])) {
        window.channelSessionsByChannel[channel] = window.channelSessionsByChannel[channel].filter(s => s.id !== id);
      }
    });
  }
  if (window.chatSessions.length === 0) {
    const newId = generateSessionId();
    window.activeChatSessionId = newId;
    setAgentSessionId(newId);
  } else if (window.activeChatSessionId === id) {
    window.activeChatSessionId = window.chatSessions[0].id;
    setAgentSessionId(window.activeChatSessionId);
  }

  saveChatSessions();
  syncActiveChat();
  if (typeof window.loadProjects === 'function') window.loadProjects();
  if (typeof window.renderChannelsList === 'function') window.renderChannelsList();
}

async function openSession(id) {
  if (window.currentMode !== 'chat') {
    if (typeof window.setMode === 'function') window.setMode('chat');
    else setMode('chat');
  }
  resetDesktopNewChatContext();
  window.activeChatSessionId = id;
  setAgentSessionId(id);
  const sess = window.chatSessions.find(s => s.id === id);
  if (sess) {
    await _loadSessionFromServer(id, {
      force: true,
      recovery: sess.activeRun === true || !!readDesktopActiveChatRun(id),
    });
  }
  // A session is read when its conversation is actually opened. Clear this
  // after the server refresh so stale local/server merge state cannot put it
  // straight back into Unread (or keep it in the Priority attention group).
  markSessionRead(id);
  // Establish project/non-project chrome before rendering the active chat so
  // the empty composer dock reflects the session's real context immediately.
  if (typeof window._maybeClearProjectState === 'function') {
    window._maybeClearProjectState(id);
  }
  syncActiveChat();
  if (chatResourcesState.open) loadChatResources({ sessionId: id });
  if (isDesktopVoiceRoomSession(id)) {
    restoreDesktopVoiceRoomSession(id).catch((error) => showDesktopVoiceStatus('Voice Room needs microphone access', error?.message || 'Enable microphone access to join this room.', 'error'));
  } else {
    resetDesktopVoiceRoomState();
    if (voiceAgentRealtimeConnection?.sessionId && voiceAgentRealtimeConnection.sessionId !== id) disableRealtimeVoiceMode();
  }
  recoverDesktopMainChatSession(id, { recovery: true, fullRefresh: false }).catch(() => {});
  refreshVisibleChannelsList();
}

function markSessionUnread(sessionId) {
  const sess = window.chatSessions.find(s => s.id === sessionId);
  if (sess && sessionId !== window.activeChatSessionId) {
    const becameUnread = !sess.unread;
    sess.unread = true;
    if (becameUnread) window.scheduleSessionListRefresh?.();
  }
}

function upsertAutomatedSession(as, opts = {}) {
  if (!as || !as.id) return false;
  if (isInternalChatSession(as) || /^brain_/i.test(String(as.jobId || ''))) return false;
  const markUnread = opts.markUnread !== false;
  const mappedHistory = Array.isArray(as.history)
    ? as.history.map((m) => ({
        role: m.role === 'ai' ? 'assistant' : (m.role === 'assistant' ? 'assistant' : 'user'),
        content: String(m.content || ''),
        timestamp: Number(m.timestamp) || Date.now(),
        channel: String(m.channel || ''),
        channelLabel: String(m.channelLabel || ''),
      }))
    : [];
  const nextSession = {
    id: as.id,
    title: as.title || 'Automated Session',
    history: mappedHistory,
    processLog: [],
    creativeMode: normalizeCreativeMode(as.creativeMode),
    canvasProjectRoot: normalizeCanvasPath(as.canvasProjectRoot) || null,
    canvasProjectLabel: as.canvasProjectLabel || null,
    canvasProjectLink: normalizeCanvasProjectLink(as.canvasProjectLink),
    creativeSceneDoc: as.creativeSceneDoc || null,
    creativeSelectedId: as.creativeSelectedId || null,
    creativeTimelineMs: Number.isFinite(Number(as.creativeTimelineMs)) ? Number(as.creativeTimelineMs) : 0,
    creativeHistoryPast: Array.isArray(as.creativeHistoryPast) ? as.creativeHistoryPast : [],
    creativeHistoryFuture: Array.isArray(as.creativeHistoryFuture) ? as.creativeHistoryFuture : [],
    creativeHtmlMotionClip: as.creativeHtmlMotionClip || null,
    createdAt: Number(as.createdAt) || Date.now(),
    updatedAt: Date.now(),
    automated: true,
    jobName: as.jobName || '',
    source: String(as.source || ''),
    unread: markUnread,
  };
  const existingIdx = window.chatSessions.findIndex(s => s.id === as.id);
  if (existingIdx === -1) window.chatSessions.push(nextSession);
	  else window.chatSessions[existingIdx] = { ...window.chatSessions[existingIdx], ...nextSession };
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (window.activeChatSessionId === as.id) renderChatMessages();
  return true;
}

const DEFAULT_CHAT_TOPBAR_SUBTITLE = 'Prometheus operator workspace';

function syncChatTopbarTitle() {
  const titleEl = document.getElementById('page-title-text');
  const subEl = document.getElementById('page-title-sub');
  const contextTitleEl = document.getElementById('chat-context-title');
  const contextProjectEl = document.getElementById('chat-context-project');
  const contextProjectNameEl = document.getElementById('chat-context-project-name');
  if (!titleEl && !subEl && !contextTitleEl && !contextProjectEl && !contextProjectNameEl) return;

  const sessions = Array.isArray(window.chatSessions) ? window.chatSessions : [];
  const session = sessions.find((candidate) => String(candidate?.id || '') === String(window.activeChatSessionId || '')) || null;
  const titleOverride = window.__PROM_CHAT_TITLE_OVERRIDE;
  const hasTitleOverride = Boolean(
    String(titleOverride?.sessionId || '').trim()
      && String(titleOverride.sessionId) === String(window.activeChatSessionId || '')
  );
  const sessionTitle = hasTitleOverride
    ? String(titleOverride?.title || '').trim() || 'Chat'
    : String(session?.title || '').trim() || 'New chat';
  const titleOverrideSubtitle = hasTitleOverride ? String(titleOverride?.subtitle || '').trim() : '';
  const projectName = String(
    session?.projectName
      || session?.canvasProjectLabel
      || document.body?.dataset?.projectName
      || ''
  ).trim();
  const isProjectSession = Boolean(
    session?.projectId
      || document.body?.classList?.contains('in-project-session')
      || projectName
  );

  if (titleEl) titleEl.textContent = sessionTitle;
  if (subEl) subEl.textContent = titleOverrideSubtitle || (isProjectSession && projectName
    ? `Project · ${projectName}`
    : DEFAULT_CHAT_TOPBAR_SUBTITLE);
  if (contextTitleEl) contextTitleEl.textContent = sessionTitle;
  if (contextProjectNameEl) contextProjectNameEl.textContent = projectName;
  if (contextProjectEl) {
    const showProject = isProjectSession && Boolean(projectName);
    contextProjectEl.hidden = !showProject;
    contextProjectEl.setAttribute('aria-hidden', String(!showProject));
  }
}

function markSessionRead(sessionId) {
  const sess = window.chatSessions.find(s => s.id === sessionId);
  if (!sess || sess.unread !== true) return false;
  sess.unread = false;
  saveChatSessions();
  window.scheduleSessionListRefresh?.();
  return true;
}

// ---- Mode switching ----
function setMode(mode) {
  const validModes = ['chat', 'bgtasks', 'schedule', 'teams', 'proposals', 'audit', 'memory'];
  if (!validModes.includes(mode)) mode = 'chat';
  window.currentMode = mode;

  // Activate v2 sidebar nav items
  validModes.forEach((m) => {
    const el = document.getElementById(`nav-${m}`);
    if (el) el.classList.toggle('active', m === mode);
  });
  // More popover items
  ['audit', 'memory'].forEach(m => {
    const el = document.getElementById(`nav-${m}`);
    if (el) el.classList.toggle('active', m === mode);
  });
  const moreBtn = document.getElementById('moreNavBtn');
  if (moreBtn) moreBtn.classList.toggle('active', mode === 'audit' || mode === 'memory');
  if (typeof window.closeMorePopover === 'function') window.closeMorePopover();

  // Update page title in topbar
  const pageTitles = {
    chat: ['Chat', 'Prometheus operator workspace'],
    bgtasks: ['Tasks', 'Background task queue'],
    schedule: ['Schedule', 'Recurring + one-off jobs'],
    teams: ['Teams', 'Managed agent teams'],
    proposals: ['Proposals', 'Awaiting approval'],
    audit: ['Audit Log', 'Non-main agent runs'],
    memory: ['Memory Graph', 'Knowledge web'],
  };
  const parts = pageTitles[mode] || ['Chat', ''];
  const titleEl = document.getElementById('page-title-text');
  const subEl = document.getElementById('page-title-sub');
  if (titleEl) titleEl.textContent = parts[0];
  if (subEl) subEl.textContent = parts[1];
  if (mode === 'chat') syncChatTopbarTitle();

  // Toggle view panels
  const viewMap = {
    chat: 'chat-view',
    bgtasks: 'bgtasks-view',
    schedule: 'schedule-view',
    teams: 'teams-view',
    proposals: 'proposals-view',
    audit: 'audit-view',
    memory: 'memory-view',
  };
  Object.entries(viewMap).forEach(([m, viewId]) => {
    const el = document.getElementById(viewId);
    if (el) el.style.display = m === mode ? 'flex' : 'none';
  });

  // In v2 layout: sidebar is always visible; main-shell hidden for non-chat modes
  const mainEl = document.querySelector('main.main-shell');
  if (mainEl) mainEl.style.display = mode === 'chat' ? '' : 'none';
  // Right panel: close when switching away from chat; hide toggle on non-chat pages
  const rightPanel = document.getElementById('right-panel');
  const toggleBtn = document.getElementById('drawerToggle');
  if (mode !== 'chat') {
    if (rightPanel) {
      rightPanel.classList.remove('open');
      rightPanel.style.removeProperty('width');
      rightPanel.style.removeProperty('min-width');
      rightPanel.style.removeProperty('max-width');
    }
    document.body.classList.add('right-collapsed');
    if (toggleBtn) { toggleBtn.classList.remove('active'); toggleBtn.style.display = 'none'; }
  } else {
    document.body.classList.toggle('right-collapsed', !(rightPanel?.classList.contains('open')));
    if (toggleBtn) toggleBtn.style.display = '';
  }
  if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();

  // Load data for selected page
  if (mode === 'bgtasks' && typeof window.refreshBgTasks === 'function') window.refreshBgTasks();
  if (mode === 'schedule' && typeof window.refreshSchedules === 'function') window.refreshSchedules();
  if (mode === 'teams') {
    const badge = document.getElementById('teams-badge');
    if (badge) badge.style.display = 'none';
    if (typeof window.teamsPageActivate === 'function') window.teamsPageActivate();
    else if (typeof window.refreshTeams === 'function') window.refreshTeams();
  }
  if (mode === 'proposals') {
    if (typeof window.loadProposals === 'function') window.loadProposals();
    const badge = document.getElementById('proposals-badge');
    if (badge) badge.style.display = 'none';
  }
  if (mode === 'audit' && typeof window.loadAuditLog === 'function') window.loadAuditLog();
  if (mode === 'memory' && typeof window.memoryPageActivate === 'function') window.memoryPageActivate();
}

// ---- Proposals — EXTRACTED to src/pages/ProposalsPage.js (F3b) ----
// Functions: loadProposals, renderProposals, updateProposalBadge,
//            jumpToProposalSession, approveProposal, denyProposal

// ---- Sidebar tabs ----
function setSidebarTab(tab) {
  // Map old tab names to new seg tab names
  const tabMap = { jobs: 'chats', skills: 'skills', projects: 'projects' };
  const newTab = tabMap[tab] || tab;
  if (typeof window.setSidebarSegTab === 'function') {
    window.setSidebarSegTab(newTab);
  }
  if (tab === 'skills' || newTab === 'skills') window.loadInstalledSkills?.();
}

// ---- Agent mode toggle ----
function updateAgentMode() {
  window.useAgentMode = document.getElementById('agent-mode-toggle').checked;
  document.getElementById('agent-mode-label').textContent = window.useAgentMode ? 'Agent' : 'Chat';
  document.getElementById('agent-mode-badge').classList.toggle('visible', window.useAgentMode);
  refreshActiveSlashCommandChrome();
}

// ---- Chat ----
function renderReactSteps(steps) {
  if (!steps || steps.length === 0) return '';
  const toolSteps = steps.filter(s => s.action);
  if (toolSteps.length === 0) return '';

  const getSearchDiagnostics = (s) => s?.toolData?.search_diagnostics || s?.diagnostics || null;
  const extractUrls = (s, resultText) => {
    const fromToolData = Array.isArray(s?.toolData?.results)
      ? s.toolData.results.map(r => String(r?.url || '').trim()).filter(u => /^https?:\/\//i.test(u))
      : [];
    const fromText = String(resultText || '').match(/https?:\/\/[^\s)]+/g) || [];
    const merged = [...fromToolData, ...fromText.map(u => String(u).trim())];
    const out = [];
    const seen = new Set();
    for (const u of merged) {
      if (!u || seen.has(u)) continue;
      seen.add(u);
      out.push(u);
      if (out.length >= 5) break;
    }
    return out;
  };
  const providerSummary = (diag) => {
    if (!diag || !Array.isArray(diag.attempted) || !diag.attempted.length) return '';
    return diag.attempted.map(a => {
      const p = String(a.provider || '').toLowerCase();
      const status = String(a.status || '').toLowerCase();
      if (status === 'success') {
        const count = Number.isFinite(a.result_count) ? `, ${a.result_count} result${a.result_count === 1 ? '' : 's'}` : '';
        return `${p}=success${count}`;
      }
      if (status === 'skipped') return `${p}=skipped${a.reason ? ` (${a.reason})` : ''}`;
      return `${p}=failed${a.reason ? ` (${a.reason})` : ''}`;
    }).join(' | ');
  };

  const id = 'steps_' + Math.random().toString(36).slice(2);
  const items = toolSteps.map(s => {
    const resultText = typeof s.toolResult === 'string' ? s.toolResult : JSON.stringify(s.toolResult || '');
    const diag = String(s.action || '') === 'web_search' ? getSearchDiagnostics(s) : null;
    const query = String(diag?.query || s?.params?.query || '').trim();
    const selectedProvider = String(diag?.selected_provider || s?.toolData?.provider || '').toLowerCase();
    const providers = diag ? providerSummary(diag) : '';
    const urls = String(s.action || '') === 'web_search' ? extractUrls(s, resultText) : [];
    return `
      <div class="react-step">
        ${s.thought ? `<div class="react-step-thought">${escHtml(s.thought.slice(0, 120))}</div>` : ''}
        <div class="react-step-action">${escHtml(s.action)}</div>
        ${resultText ? `<div class="react-step-result${resultText.startsWith('ERROR') ? ' error' : ''}">${escHtml(resultText.slice(0, 160))}${resultText.length > 160 ? '…' : ''}</div>` : ''}
        ${diag ? `
          <div style="margin-top:6px;font-size:10px;color:var(--muted);line-height:1.5">
            ${query ? `<div><b>query</b>: ${escHtml(query)}</div>` : ''}
            ${selectedProvider ? `<div><b>provider hit</b>: ${escHtml(selectedProvider)}</div>` : ''}
            ${providers ? `<div><b>providers</b>: ${escHtml(providers)}</div>` : ''}
          </div>
        ` : ''}
        ${String(s.action || '') === 'web_search' && !diag ? `
          <div style="margin-top:6px;font-size:10px;color:var(--muted);line-height:1.5">
            ${selectedProvider ? `<div><b>provider hit</b>: ${escHtml(selectedProvider)}</div>` : ''}
          </div>
        ` : ''}
        ${urls.length ? `
          <div style="margin-top:6px;font-size:10px;line-height:1.6">
            <div style="color:var(--muted);margin-bottom:2px"><b>sources</b>:</div>
            ${urls.slice(0, 3).map((u, i) => `<div>${i + 1}. <a href="${escHtml(u)}" target="_blank" rel="noopener noreferrer">${escHtml(u)}</a></div>`).join('')}
          </div>
        ` : ''}
      </div>
    `;
  }).join('');

  return `
    <div class="react-steps-toggle" onclick="toggleSteps('${id}')">
      ? ${toolSteps.length} tool step${toolSteps.length !== 1 ? 's' : ''} used
    </div>
    <div class="react-steps" id="${id}" style="display:none">${items}</div>
  `;
}

function toggleSteps(id) {
  const el = document.getElementById(id);
  if (!el) return;
  const visible = el.style.display !== 'none';
  el.style.display = visible ? 'none' : 'block';
  el.previousElementSibling.textContent = `${visible ? '?' : '?'} ${el.querySelectorAll('.react-step').length} tool step${el.querySelectorAll('.react-step').length !== 1 ? 's' : ''} used`;
}

function renderAssistantContent(content, message = null) {
  const text = String(content || '');
  const markdownOptions = { visualArtifacts: Array.isArray(message?.richArtifacts) ? message.richArtifacts : [] };
  const bgHeaderMatch = text.match(/\nBackground agent response:\s*\n?/i) || text.match(/^Background agent response:\s*\n?/i);
  if (bgHeaderMatch && typeof bgHeaderMatch.index === 'number') {
    const splitAt = bgHeaderMatch.index;
    const head = text.slice(0, splitAt).trim();
    const bgBody = text.slice(splitAt + bgHeaderMatch[0].length).trim();
    return `
      <div class="msg-staged">
        ${head ? `<div class="msg-content markdown-body">${renderMd(head, markdownOptions)}</div>` : ''}
        <div class="msg-stage">
          <div class="msg-stage-title">Background agent response</div>
          <div class="msg-content markdown-body">${renderMd(bgBody || 'No background details provided.', markdownOptions)}</div>
        </div>
      </div>
    `;
  }
  const hasStaged = /(^|\n)(Initial chat|Execution result|Final chat):\s*/i.test(text);
  if (!hasStaged) return `<div class="msg-content markdown-body">${renderMd(text, markdownOptions)}</div>`;
  const chunks = text
    .split(/\n\s*---\s*\n/g)
    .map(s => String(s || '').trim())
    .filter(Boolean);
  const html = chunks.map((chunk, idx) => {
    const m = chunk.match(/^(Initial chat|Execution result|Final chat):\s*\n?/i);
    const title = m ? m[1] : `Section ${idx + 1}`;
    const body = m ? chunk.slice(m[0].length).trim() : chunk;
    return `
      <div class="msg-stage">
        <div class="msg-stage-title">${escHtml(title)}</div>
        <div class="msg-content markdown-body">${renderMd(body, markdownOptions)}</div>
      </div>
    `;
  }).join('');
  return `<div class="msg-staged">${html}</div>`;
}

