  if (kind === 'arrow') return 'solar:arrow-right-up-bold-duotone';
  if (kind === 'sparkles') return 'solar:stars-bold-duotone';
  if (kind === 'bolt') return 'solar:bolt-bold-duotone';
  if (kind === 'lock') return 'solar:lock-keyhole-bold-duotone';
  if (kind === 'camera') return 'solar:camera-bold-duotone';
  if (kind === 'globe') return 'solar:global-bold-duotone';
  if (kind === 'palette') return 'solar:palette-round-bold-duotone';
