function renderCreativeQuickExportCardStudioV3() {
  const isVideo = normalizeCreativeMode(window.currentCreativeMode) === 'video';
  const mp4Config = isVideo ? getCreativeVideoExportConfig('mp4') : null;
  const gifConfig = isVideo ? getCreativeGifExportConfig() : null;
  const isGifExporting = isCreativeExportActive('gif');
  const isWebmExporting = isCreativeExportActive('webm');
  const isMp4Exporting = isCreativeExportActive('mp4');
  const isExporting = isCreativeExportActive();
  const exportPercent = getCreativeActiveExportPercent();
  const exportStatus = String(creativeActiveExport?.status || '').trim().toLowerCase();
  const exportSubtitle = isExporting
    ? `${creativeActiveExport?.audioEnabled ? 'Audio + video' : 'Video'} export ${exportStatus === 'finalizing' ? 'is finalizing' : exportStatus === 'canceling' ? 'is stopping' : 'is recording'} at ${exportPercent}%`
    : (isVideo ? 'Export the current frame or record the full video draft without leaving the studio.' : 'Export the current frame without leaving the studio.');
  return `
    <section class="creative-inspector-card">
      <div class="creative-section-heading">
        <div class="creative-card-title">Quick export</div>
        <div class="creative-card-subtitle">${escHtml(exportSubtitle)}</div>
      </div>
      ${isExporting ? `
        <div class="creative-inspector-summary" style="margin-bottom:12px">
          <span class="creative-summary-pill">${exportPercent}%</span>
          <span class="creative-summary-pill">${escHtml(creativeActiveExport?.format?.toUpperCase?.() || 'VIDEO')}</span>
          <span class="creative-summary-pill">${escHtml(creativeActiveExport?.audioEnabled ? 'audio armed' : (creativeActiveExport?.audioRequested ? 'audio unavailable' : 'video only'))}</span>
        </div>
      ` : ''}
      <details class="creative-export-menu creative-export-menu--inline">
        <summary class="creative-chip-btn creative-chip-btn--accent" ${isExporting ? 'aria-disabled="true"' : ''}><iconify-icon icon="solar:gallery-export-bold-duotone" width="14" height="14"></iconify-icon>${escHtml(isExporting ? `Exporting ${exportPercent}%` : 'Export')}<iconify-icon icon="solar:alt-arrow-down-bold-duotone" width="12" height="12"></iconify-icon></summary>
        <div class="creative-export-menu-panel" role="menu">
          <button onclick="canvasExportCreative('png'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:gallery-bold-duotone" width="16" height="16"></iconify-icon><span>PNG</span><span class="creative-export-menu-hint">Image</span></button>
          <button onclick="canvasExportCreative('jpeg'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:gallery-round-bold-duotone" width="16" height="16"></iconify-icon><span>JPG</span><span class="creative-export-menu-hint">Image</span></button>
          ${!isVideo ? `<button onclick="canvasSaveCreativeLayerAssets(); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:layers-bold-duotone" width="16" height="16"></iconify-icon><span>Layer PNGs</span><span class="creative-export-menu-hint">Assets</span></button>` : ''}
          <button onclick="canvasExportCreative('svg'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:code-square-bold-duotone" width="16" height="16"></iconify-icon><span>SVG</span><span class="creative-export-menu-hint">Vector</span></button>
          <button onclick="canvasExportCreative('pdf'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:document-bold-duotone" width="16" height="16"></iconify-icon><span>PDF</span><span class="creative-export-menu-hint">Document</span></button>
          ${isVideo && gifConfig ? `<button onclick="canvasExportCreative('gif'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:gallery-favourite-bold-duotone" width="16" height="16"></iconify-icon><span>${escHtml(isGifExporting ? `GIF ${exportPercent}%` : 'GIF')}</span><span class="creative-export-menu-hint">Animation</span></button>` : ''}
          ${isVideo && mp4Config ? `<button onclick="canvasExportCreative('mp4'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:videocamera-record-bold-duotone" width="16" height="16"></iconify-icon><span>${escHtml(isMp4Exporting ? `MP4 ${exportPercent}%` : 'MP4')}</span><span class="creative-export-menu-hint">Video</span></button>` : ''}
          ${isVideo ? `<button onclick="canvasExportCreative('webm'); this.closest('details').removeAttribute('open')" class="creative-export-menu-item" ${isExporting ? 'disabled' : ''}><iconify-icon icon="solar:clapperboard-play-bold-duotone" width="16" height="16"></iconify-icon><span>${escHtml(isWebmExporting ? `WEBM ${exportPercent}%` : 'WEBM')}</span><span class="creative-export-menu-hint">Video</span></button>` : ''}
          ${isExporting ? `<button onclick="canvasCancelCreativeExport()" class="creative-export-menu-item creative-export-menu-item--danger" ${creativeActiveExport?.cancelRequested ? 'disabled' : ''}><iconify-icon icon="solar:close-circle-bold-duotone" width="16" height="16"></iconify-icon><span>${escHtml(creativeActiveExport?.cancelRequested ? 'Stopping...' : 'Cancel export')}</span></button>` : ''}
        </div>
      </details>
    </section>
  `;
}

function renderCreativeAssetEntryStudioV3(entry, kind = 'scene') {
  const safePath = escHtml(normalizeCanvasPath(entry?.path || '')).replace(/'/g, '&#39;');
  const safeName = escHtml(String(entry?.name || (kind === 'scene' ? 'scene.json' : 'asset'))).replace(/'/g, '&#39;');
  const isVideoExport = kind === 'export' && isCreativeVideoMediaPath(entry?.path || entry?.name || '');
  const isPlaceableImage = (kind === 'asset' || kind === 'export') && isCreativeImageMediaPath(entry?.path || entry?.name || '');
  const timestamp = formatCreativeAssetTimestamp(entry?.savedAt || entry?.modifiedAt);
  const summary = kind === 'scene'
    ? describeCreativeSceneAssetSummary(entry)
    : `${String(entry?.ext || '').replace(/^\./, '').toUpperCase() || 'ASSET'} | ${formatCreativeAssetBytes(entry?.size)}`;
  const modeBadge = kind === 'scene' && isStructuredCreativeMode(entry?.creativeMode)
    ? `<span class="creative-summary-pill">${escHtml(entry.creativeMode === 'video' ? 'Video scene' : 'Image scene')}</span>`
    : '';
  return `
    <div class="creative-asset-item">
      <div class="creative-asset-item-head">
        <div>
          <div class="creative-asset-item-title">${escHtml(entry?.name || '')}</div>
          <div class="creative-asset-item-subtitle">${escHtml(summary)}</div>
        </div>
        <div class="creative-asset-item-meta">
          <span class="creative-summary-pill">${escHtml(timestamp)}</span>
          ${modeBadge}
        </div>
      </div>
      ${entry?.parseError ? `<div class="creative-asset-empty" style="margin-top:10px">${escHtml(entry.parseError)}</div>` : ''}
      <div class="creative-asset-actions">
        ${kind === 'scene' ? `<button onclick="canvasLoadCreativeSceneAsset('${safePath}')" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="solar:play-bold-duotone" width="14" height="14"></iconify-icon>Load</button>` : ''}
        ${(isVideoExport || isPlaceableImage) ? `<button onclick="canvasPlaceCreativeExportOnCanvas('${safePath}', '${safeName}')" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="${isVideoExport ? 'solar:play-circle-bold-duotone' : 'solar:gallery-add-bold-duotone'}" width="14" height="14"></iconify-icon>Place</button>` : ''}
        <button onclick="canvasDownloadFile('${safePath}', '${safeName}')" class="creative-chip-btn"><iconify-icon icon="solar:download-minimalistic-bold-duotone" width="14" height="14"></iconify-icon>Download</button>
        <button onclick="openInFileLocation('${safePath}')" class="creative-chip-btn"><iconify-icon icon="solar:folder-open-bold-duotone" width="14" height="14"></iconify-icon>Reveal</button>
      </div>
    </div>
  `;
}

function renderCreativeRenderJobEntryStudioV3(entry) {
  const safeOutputPath = escHtml(normalizeCanvasPath(entry?.outputPath || '')).replace(/'/g, '&#39;');
  const safeOutputName = escHtml(String(entry?.outputFilename || `${String(entry?.format || 'render').toLowerCase() || 'render'}.bin`)).replace(/'/g, '&#39;');
  const isVideoOutput = !!safeOutputPath && isCreativeVideoMediaPath(entry?.outputPath || entry?.outputFilename || '');
  const safeJobId = escHtml(String(entry?.id || '')).replace(/'/g, '&#39;');
  const manifest = entry?.manifest && typeof entry.manifest === 'object'
    ? entry.manifest
    : (entry?.workerInput?.manifest && typeof entry.workerInput.manifest === 'object' ? entry.workerInput.manifest : null);
  const timestamp = formatCreativeAssetTimestamp(entry?.updatedAt || entry?.createdAt || entry?.requestedAt);
  const progress = Math.round(clamp(Number(entry?.progress) || 0, 0, 1) * 100);
  const normalizedStatus = normalizeCreativeRenderJobStatus(entry?.status);
  const isTerminal = isCreativeRenderJobTerminalStatus(entry?.status);
  const isRetryable = !isTerminal && entry?.retryable === true;
  const statusLabel = normalizedStatus.replace(/_/g, ' ');
  // Status badge color by state
  const statusColorMap = {
    queued: 'creative-job-badge--queued',
    running: 'creative-job-badge--running',
    retrying: 'creative-job-badge--retrying',
    uploading: 'creative-job-badge--uploading',
    completed: 'creative-job-badge--completed',
    cancel_requested: 'creative-job-badge--canceling',
    canceled: 'creative-job-badge--canceled',
    failed: 'creative-job-badge--failed',
  };
  const badgeClass = statusColorMap[normalizedStatus] || 'creative-job-badge--queued';
  const subtitle = entry?.outputFilename
    ? `${entry.outputFilename}${entry?.outputSize ? ` | ${formatCreativeAssetBytes(entry.outputSize)}` : ''}`
    : (entry?.error || 'No output file written yet.');
  const modeBadge = isStructuredCreativeMode(entry?.creativeMode)
    ? `<span class="creative-summary-pill">${escHtml(entry.creativeMode === 'video' ? 'Video job' : 'Image job')}</span>`
    : '';
  const progressLabel = entry?.progressLabel || '';
  const attemptInfo = (Number(entry?.attemptCount) > 1)
    ? `Attempt ${entry.attemptCount}${entry?.maxAttempts ? `/${entry.maxAttempts}` : ''}` : '';
  const hasError = !isTerminal && entry?.lastError;
  const safeError = hasError ? escHtml(String(entry.lastError).slice(0, 200)) : '';
  const pipelineLabel = manifest?.pipeline
    ? String(manifest.pipeline).replace(/-/g, ' ')
    : (entry?.renderer ? String(entry.renderer).replace(/-/g, ' ') : '');
  const captureFormat = String(manifest?.captureFormat || entry?.captureFormat || '').trim().toUpperCase();
  const deliveredFormat = String(manifest?.deliveredFormat || entry?.deliveredFormat || '').trim().toUpperCase();
  const formatFlow = captureFormat && deliveredFormat
    ? `${captureFormat} -> ${deliveredFormat}`
    : (deliveredFormat || captureFormat || '');
  const audioPlan = manifest?.audio && typeof manifest.audio === 'object' ? manifest.audio : null;
  const audioLabel = audioPlan?.requested
    ? (audioPlan.includeInCapture ? 'audio captured' : (audioPlan.requiresServerMix ? 'audio needs server mix' : `audio ${audioPlan.outcome || 'pending'}`))
    : '';
  const serverFinish = manifest?.serverFinish && typeof manifest.serverFinish === 'object' ? manifest.serverFinish : null;
  const serverFinishLabel = serverFinish?.requested
    ? `finish ${serverFinish.status || (serverFinish.available === false ? 'waiting for ffmpeg' : 'pending')}`
    : '';
  const manifestChips = [pipelineLabel, formatFlow, audioLabel, serverFinishLabel]
    .filter(Boolean)
    .map((label) => `<span class="creative-summary-pill">${escHtml(label)}</span>`)
    .join('');
  return `
    <div class="creative-asset-item creative-render-job-item">
      <div class="creative-asset-item-head">
        <div style="min-width:0">
          <div class="creative-asset-item-title">${escHtml(String(entry?.name || entry?.outputFilename || 'Render job'))}</div>
          <div class="creative-asset-item-subtitle" style="margin-top:3px">${escHtml([String(entry?.format || 'render').toUpperCase(), progressLabel, attemptInfo].filter(Boolean).join(' · '))}</div>
        </div>
        <div class="creative-asset-item-meta" style="flex-shrink:0">
          <span class="creative-job-badge ${badgeClass}">${escHtml(statusLabel)}</span>
          ${modeBadge}
          <span class="creative-summary-pill">${escHtml(timestamp)}</span>
        </div>
      </div>
      ${!isTerminal ? `
        <div class="creative-job-progress-wrap" style="margin-top:10px">
          <div class="creative-job-progress-bar">
            <div class="creative-job-progress-fill creative-job-progress-fill--${normalizedStatus}" style="width:${progress}%"></div>
          </div>
          <div class="creative-job-progress-label">${progress}%</div>
        </div>
      ` : ''}
      ${hasError ? `<div class="creative-job-error-note"><iconify-icon icon="solar:danger-triangle-bold-duotone" width="13" height="13"></iconify-icon> ${safeError}</div>` : ''}
      ${manifestChips ? `<div class="creative-inspector-summary" style="margin-top:8px">${manifestChips}</div>` : ''}
      <div class="creative-asset-item-subtitle" style="margin-top:8px">${escHtml(subtitle)}</div>
      <div class="creative-asset-actions" style="margin-top:10px">
        ${!isTerminal ? `<button onclick="canvasCancelCreativeRenderJob('${safeJobId}')" class="creative-chip-btn creative-chip-btn--danger"><iconify-icon icon="solar:stop-bold-duotone" width="14" height="14"></iconify-icon>Cancel</button>` : ''}
        ${isRetryable ? `<button onclick="canvasRetryCreativeRenderJob('${safeJobId}')" class="creative-chip-btn"><iconify-icon icon="solar:refresh-bold-duotone" width="14" height="14"></iconify-icon>Retry</button>` : ''}
        ${isVideoOutput ? `<button onclick="canvasPlaceCreativeExportOnCanvas('${safeOutputPath}', '${safeOutputName}')" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="solar:play-circle-bold-duotone" width="14" height="14"></iconify-icon>Place</button>` : ''}
        ${safeOutputPath ? `<button onclick="canvasDownloadFile('${safeOutputPath}', '${safeOutputName}')" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="solar:download-minimalistic-bold-duotone" width="14" height="14"></iconify-icon>Download</button>` : ''}
        ${safeOutputPath ? `<button onclick="openInFileLocation('${safeOutputPath}')" class="creative-chip-btn"><iconify-icon icon="solar:folder-open-bold-duotone" width="14" height="14"></iconify-icon>Reveal</button>` : ''}
      </div>
    </div>
  `;
}

function renderCreativeSavedAssetsCardStudioV3() {
  const sceneEntries = Array.isArray(creativeAssetsState.scenes) ? creativeAssetsState.scenes.slice(0, 5) : [];
  const renderJobEntries = Array.isArray(creativeAssetsState.renderJobs) ? creativeAssetsState.renderJobs.slice(0, 5) : [];
  const exportEntries = Array.isArray(creativeAssetsState.exports) ? creativeAssetsState.exports.slice(0, 5) : [];
  const layerAssetEntries = (Array.isArray(creativeAssetsState.indexedAssets) ? creativeAssetsState.indexedAssets : [])
    .filter((asset) => Array.isArray(asset?.tags) && asset.tags.includes('layer-asset'))
    .slice(0, 8);
  const storageLabel = normalizeCanvasPath(creativeAssetsState.storageRootRelative || creativeAssetsState.storageRoot || canvasProjectRoot || '');
  const totalItems = Math.max(0, Number(creativeAssetsState.counts?.scenes) || sceneEntries.length)
    + Math.max(0, Number(creativeAssetsState.counts?.jobs) || renderJobEntries.length)
    + Math.max(0, Number(creativeAssetsState.counts?.exports) || exportEntries.length)
    + layerAssetEntries.length;
  const emptyCopy = creativeAssetsState.loading
    ? 'Loading saved scenes and exports from the workspace backend...'
    : (creativeAssetsState.error || 'Save a scene or export an asset and it will appear here.');
  return `
    <section class="creative-inspector-card">
      <div class="creative-inspector-card-header">
        <div>
          <div class="creative-card-title">Saved assets</div>
          <div class="creative-card-subtitle">Scene snapshots and rendered exports stored in the creative backend workspace.</div>
        </div>
        <div class="creative-inspector-badge">${totalItems} items</div>
      </div>
      <div class="creative-info-note">
        ${escHtml(storageLabel ? `${creativeAssetsState.usesProjectRoot ? 'Project root' : 'Creative workspace'}: ${storageLabel}` : 'The creative backend will create a workspace folder as soon as you save a scene or export an asset.')}
      </div>
      <div class="creative-pill-row" style="margin-top:12px">
        <button onclick="canvasSaveCreativeSceneSnapshot()" class="creative-chip-btn creative-chip-btn--accent" ${creativeSceneSavePending ? 'disabled' : ''}>
          <iconify-icon icon="solar:diskette-bold-duotone" width="14" height="14"></iconify-icon>${escHtml(creativeSceneSavePending ? 'Saving...' : 'Save scene')}
        </button>
        <button onclick="canvasRefreshCreativeAssets()" class="creative-chip-btn" ${creativeAssetsState.loading ? 'disabled' : ''}>
          <iconify-icon icon="solar:refresh-bold-duotone" width="14" height="14"></iconify-icon>${escHtml(creativeAssetsState.loading ? 'Refreshing...' : 'Refresh')}
        </button>
        ${storageLabel ? `<button onclick="canvasRevealCreativeStorageRoot()" class="creative-chip-btn"><iconify-icon icon="solar:folder-with-files-bold-duotone" width="14" height="14"></iconify-icon>Reveal root</button>` : ''}
      </div>
      <div class="creative-assets-stack">
        <div class="creative-assets-section">
          <div class="creative-assets-section-label">Scenes</div>
          ${sceneEntries.length
            ? `<div class="creative-asset-list">${sceneEntries.map((entry) => renderCreativeAssetEntryStudioV3(entry, 'scene')).join('')}</div>`
            : `<div class="creative-asset-empty">${escHtml(emptyCopy)}</div>`}
        </div>
        <div class="creative-assets-section">
          <div class="creative-assets-section-label">Render jobs</div>
          ${renderJobEntries.length
            ? `<div class="creative-asset-list">${renderJobEntries.map((entry) => renderCreativeRenderJobEntryStudioV3(entry)).join('')}</div>`
            : `<div class="creative-asset-empty">Server-backed render jobs will show up here while video exports are running and after they complete.</div>`}
        </div>
        <div class="creative-assets-section">
          <div class="creative-assets-section-label">Exports</div>
          ${exportEntries.length
            ? `<div class="creative-asset-list">${exportEntries.map((entry) => renderCreativeAssetEntryStudioV3(entry, 'export')).join('')}</div>`
            : `<div class="creative-asset-empty">Rendered exports like PNG, PDF, MP4, or WEBM will show up here after each export.</div>`}
        </div>
        <div class="creative-assets-section">
          <div class="creative-assets-section-label">Layer assets</div>
          ${layerAssetEntries.length
            ? `<div class="creative-asset-list">${layerAssetEntries.map((entry) => renderCreativeAssetEntryStudioV3(entry, 'asset')).join('')}</div>`
            : `<div class="creative-asset-empty">Saved layer PNGs will show up here after you extract or export layer assets.</div>`}
        </div>
      </div>
    </section>
  `;
}

const CREATIVE_NUMERIC_PRESETS = {
  x: [0, 40, 80, 120, 160, 240, 320, 480, 640],
  y: [0, 40, 80, 120, 160, 240, 320, 480, 640],
  width: [40, 80, 120, 160, 240, 320, 480, 640, 800, 1080],
  height: [40, 80, 120, 160, 240, 320, 480, 640, 800, 1080],
  rotation: [-180, -90, -45, -30, -15, 0, 15, 30, 45, 90, 180],
  opacity: [0, 0.1, 0.25, 0.5, 0.75, 0.9, 1],
  zIndex: [0, 1, 2, 3, 4, 5, 10, 20, 50, 100],
  'meta.fontSize': [10, 12, 14, 16, 18, 20, 24, 28, 32, 40, 48, 56, 64, 72, 96, 120, 160],
  'meta.fontWeight': [100, 200, 300, 400, 500, 600, 700, 800, 900],
  'meta.lineHeight': [1, 1.1, 1.2, 1.3, 1.4, 1.5, 1.6, 1.75, 2],
  'meta.letterSpacing': [-2, -1, -0.5, 0, 0.5, 1, 2, 4, 6, 8],
  'meta.radius': [0, 2, 4, 6, 8, 12, 16, 20, 24, 32, 48, 64, 999],
  'meta.strokeWidth': [0, 1, 2, 3, 4, 6, 8, 12, 16],
  'meta.sides': [5, 6, 7, 8],
  'meta.speed': [0.25, 0.5, 0.75, 1, 1.25, 1.5, 2, 3],
  width_doc: [480, 720, 1080, 1200, 1440, 1920, 2160, 3840],
  height_doc: [480, 720, 1080, 1200, 1440, 1920, 2160, 3840],
  durationMs: [3000, 5000, 8000, 10000, 12000, 15000, 20000, 30000, 60000],
  frameRate: [24, 25, 30, 48, 50, 60],
  'audioTrack.startMs': [0, 500, 1000, 2000, 5000, 10000],
  'audioTrack.durationMs': [0, 2000, 5000, 8000, 12000, 20000, 30000],
  'audioTrack.volume': [0, 0.25, 0.5, 0.75, 1],
  'audioTrack.trimStartMs': [0, 500, 1000, 2000, 5000],
  'audioTrack.trimEndMs': [0, 500, 1000, 2000, 5000],
  'audioTrack.fadeInMs': [0, 250, 500, 1000, 2000],
  'audioTrack.fadeOutMs': [0, 250, 500, 1000, 2000],
};
function renderCreativePropertyFieldStudioV3(label, key, value, type = 'number', extra = {}) {
  const step = extra.step !== undefined ? `step="${escHtml(extra.step)}"` : '';
  const min = extra.min !== undefined ? `min="${escHtml(extra.min)}"` : '';
  const max = extra.max !== undefined ? `max="${escHtml(extra.max)}"` : '';
  const handler = extra.handler || 'canvasUpdateCreativeProperty';
  const inputValue = type === 'color'
    ? (/^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(value ?? '').trim()) ? String(value).trim() : '#111827')
    : type === 'text'
    ? String(value ?? '')
    : Number.isFinite(Number(value)) ? String(value) : '0';
  if (type === 'number') {
    const presets = CREATIVE_NUMERIC_PRESETS[key] || [];
    const listId = `crv-preset-${String(key).replace(/[^a-z0-9]/gi, '-')}`;
    const listAttr = presets.length ? `list="${listId}"` : '';
    const datalist = presets.length ? `<datalist id="${listId}">${presets.map((p) => `<option value="${p}"></option>`).join('')}</datalist>` : '';
    return `
      <label class="creative-form-field">
        <span class="creative-form-label">${escHtml(label)}</span>
        <input class="creative-form-input creative-form-input--numeric" type="number" value="${escHtml(inputValue)}" ${step} ${min} ${max} ${listAttr} inputmode="decimal" oninput="${handler}('${escHtml(key)}', this.value, 'number')">
        ${datalist}
      </label>
    `;
  }
  return `
    <label class="creative-form-field">
      <span class="creative-form-label">${escHtml(label)}</span>
      <input class="creative-form-input" type="${type}" value="${escHtml(inputValue)}" ${step} ${min} ${max} oninput="${handler}('${escHtml(key)}', this.value, '${type}')">
    </label>
  `;
}

function renderCreativePropertyToggleStudioV3(label, key, value, extra = {}) {
  const handler = extra.handler || 'canvasUpdateCreativeProperty';
  return `
    <label class="creative-form-field">
      <span class="creative-form-label">${escHtml(label)}</span>
      <label class="creative-form-toggle">
        <input type="checkbox" ${value ? 'checked' : ''} onchange="${handler}('${escHtml(key)}', this.checked, 'boolean')">
        <span>${value ? 'On' : 'Off'}</span>
      </label>
    </label>
  `;
}

function renderCreativePropertyTextareaStudioV3(label, key, value, extra = {}) {
  const handler = extra.handler || 'canvasUpdateCreativeProperty';
  return `
    <label class="creative-form-field">
      <span class="creative-form-label">${escHtml(label)}</span>
      <textarea class="creative-form-textarea" oninput="${handler}('${escHtml(key)}', this.value, 'text')">${escHtml(String(value || ''))}</textarea>
    </label>
  `;
}

function renderCreativeKeyframeSectionStudioV3(selected) {
  const keyframes = Array.isArray(selected?.meta?.keyframes) ? selected.meta.keyframes.slice().sort((a, b) => (a.atMs || 0) - (b.atMs || 0)) : [];
  const currentEase = keyframes.find((keyframe) => Number(keyframe.atMs) === Number(creativeTimelineMs))?.ease || '';
  const packMap = getCreativeLibraryPackMap();
  const presetBrowser = getFilteredCreativePresetCatalog(selected?.type || '');
  const presetFilterOptions = getActiveCreativeAnimationPresetCatalog(selected?.type || '')
    .reduce((acc, preset) => {
      const libraryId = String(preset?.libraryId || '').trim().toLowerCase();
      if (!libraryId || acc.some((entry) => entry.id === libraryId)) return acc;
      const pack = packMap.get(libraryId);
      acc.push({
        id: libraryId,
        label: pack?.label || preset?.libraryId || libraryId,
        source: pack?.source || 'builtin',
      });
      return acc;
    }, []);
  return `
    <section class="creative-inspector-card">
      <div class="creative-inspector-card-header">
        <div>
          <div class="creative-card-title">Animation</div>
          <div class="creative-card-subtitle">Capture the current frame state, add presets, and tune easing at the playhead.</div>
        </div>
        <button onclick="canvasAddCreativeKeyframe()" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="solar:add-circle-bold-duotone" width="14" height="14"></iconify-icon>Add @ ${escHtml(formatCreativeTimelineTime(creativeTimelineMs))}</button>
      </div>
      <section class="creative-inspector-card creative-inspector-card--subtle" style="margin-top:12px">
        <div class="creative-section-heading">
          <div class="creative-card-title">Preset browser</div>
          <div class="creative-card-subtitle">Search installed motion packs and apply reusable animation recipes without digging through every library by hand.</div>
        </div>
        <div class="creative-field-grid creative-field-grid--browser">
          <label class="creative-form-field">
            <span class="creative-form-label">Search presets</span>
            <input class="creative-form-input" type="search" placeholder="Fade, blur, typewriter..." value="${escHtml(creativePresetBrowserState.query || '')}" oninput="canvasSetCreativePresetBrowserField('query', this.value)">
          </label>
          <label class="creative-form-field">
            <span class="creative-form-label">Pack</span>
            <select class="creative-form-select" onchange="canvasSetCreativePresetBrowserField('libraryId', this.value)">
              <option value="__all__" ${String(creativePresetBrowserState.libraryId || '__all__') === '__all__' ? 'selected' : ''}>All motion packs</option>
              <option value="__builtin__" ${String(creativePresetBrowserState.libraryId || '') === '__builtin__' ? 'selected' : ''}>Built-in packs</option>
              <option value="__custom__" ${String(creativePresetBrowserState.libraryId || '') === '__custom__' ? 'selected' : ''}>Imported packs</option>
              ${presetFilterOptions.map((pack) => `<option value="${escHtml(pack.id)}" ${String(creativePresetBrowserState.libraryId || '') === String(pack.id) ? 'selected' : ''}>${escHtml(pack.label)}${pack.source === 'custom' ? ' · imported' : ''}</option>`).join('')}
            </select>
          </label>
        </div>
        <div class="creative-inspector-summary" style="margin-top:12px">
          <span class="creative-summary-pill">${presetBrowser.presets.length} presets</span>
          <span class="creative-summary-pill">${presetBrowser.groups.length} packs</span>
          <span class="creative-summary-pill">${escHtml(selected?.type || 'element')}</span>
        </div>
        ${presetBrowser.groups.length ? `
          <div class="creative-preset-groups">
            ${presetBrowser.groups.map((group) => `
              <div class="creative-preset-group">
                <div class="creative-preset-group-title">${escHtml(group.pack?.label || group.libraryId || 'Motion pack')}</div>
                <div class="creative-preset-group-meta">${escHtml(`${group.pack?.source === 'custom' ? 'Imported' : 'Built-in'} · ${group.presets.length} preset${group.presets.length === 1 ? '' : 's'}`)}</div>
                <div class="creative-pill-row" style="margin-top:10px">
                  ${group.presets.map((preset) => `<button onclick="canvasApplyCreativeAnimationPreset('${escHtml(preset.id)}')" class="creative-chip-btn">${escHtml(preset.label)}</button>`).join('')}
                </div>
              </div>
            `).join('')}
          </div>
        ` : `<div class="creative-asset-empty" style="margin-top:12px">No installed motion presets match that search for this element type yet. Try another query or switch the pack filter back to all motion libraries.</div>`}
      </section>
      <label class="creative-form-field" style="margin-top:12px">
        <span class="creative-form-label">Ease at playhead</span>
        <select class="creative-form-select" onchange="canvasSetCreativeKeyframeEase(this.value)">
          <option value="">Choose ease...</option>
          ${['linear', 'power2.out', 'power2.inOut', 'power3.out', 'power3.inOut', 'back.out(1.7)', 'back.inOut(1.4)'].map((ease) => `
            <option value="${escHtml(ease)}" ${currentEase === ease ? 'selected' : ''}>${escHtml(ease)}</option>
          `).join('')}
        </select>
      </label>
      ${keyframes.length ? `
        <div style="display:flex;flex-direction:column;gap:8px;margin-top:12px">
          ${keyframes.map((keyframe) => `
            <div style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:10px 12px;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.03);border-radius:14px">
              <div>
                <div style="font-size:11px;font-weight:700;color:#fafaf9">${escHtml(formatCreativeTimelineTime(keyframe.atMs))}</div>
                <div style="font-size:10px;color:#a8a29e;margin-top:3px">${escHtml(`x ${Math.round(Number(keyframe.x ?? selected.x) || 0)} | y ${Math.round(Number(keyframe.y ?? selected.y) || 0)} | opacity ${Number(keyframe.opacity ?? selected.opacity ?? 1).toFixed(2)}${keyframe.ease ? ` | ${keyframe.ease}` : ''}`)}</div>
              </div>
              <button onclick="canvasDeleteCreativeKeyframe('${escHtml(keyframe.id)}')" class="creative-chip-btn creative-chip-btn--danger"><iconify-icon icon="solar:trash-bin-trash-bold-duotone" width="13" height="13"></iconify-icon></button>
            </div>
          `).join('')}
        </div>
      ` : `
        <div class="creative-info-note">No keyframes yet. Scrub the playhead, stage the element where you want it, and add a keyframe from the live frame.</div>
      `}
    </section>
  `;
}

function renderCreativeStageElementStudioV3(baseElement, mode) {
  const element = getRenderedCreativeElement(baseElement, mode);
  const visualState = getCreativeElementVisualStateStudioV3(baseElement, mode);
  const isSelected = baseElement.id === creativeSelectedId;
  const selectedClass = isSelected ? '2px solid rgba(249,115,22,0.95)' : '1px solid transparent';
  const shadowParts = [];
  if (baseElement.locked) shadowParts.push('inset 0 0 0 1px rgba(250,204,21,0.85)');
  if (isSelected) shadowParts.push('0 0 0 1px rgba(251,146,60,0.78)', '0 16px 30px rgba(15,15,16,0.18)');
  const selectionShadow = shadowParts.length ? shadowParts.join(',') : 'none';
  const canResize = isSelected && baseElement.locked !== true && baseElement.visible !== false;
  const resizeHandle = canResize
    ? `<div data-creative-resize-handle="true" title="Drag to resize" style="position:absolute;right:7px;bottom:7px;width:13px;height:13px;border-radius:5px;background:linear-gradient(180deg,#fb923c,#f97316);border:2px solid rgba(255,255,255,0.92);box-shadow:0 0 0 1px rgba(0,0,0,0.28),0 10px 20px rgba(249,115,22,0.28);cursor:nwse-resize;z-index:3"></div>`
    : '';
  const compositingCss = buildCreativeLayerCompositingCssStudioV3(baseElement, visualState);
  const sharedStyle = [
    'position:absolute',
    `left:${Number(element.x) || 0}px`,
    `top:${Number(element.y) || 0}px`,
    `width:${Math.max(8, Number(element.width) || 0)}px`,
    `height:${Math.max(8, Number(element.height) || 0)}px`,
    `opacity:${Number.isFinite(Number(element.opacity)) ? Number(element.opacity) : 1}`,
    `transform:rotate(${Number(element.rotation) || 0}deg)`,
    `z-index:${Number(baseElement.zIndex) || 0}`,
    `outline:${selectedClass}`,
    `box-shadow:${selectionShadow}`,
    ...compositingCss,
    `visibility:${baseElement.visible === false ? 'hidden' : 'visible'}`,
    `pointer-events:${baseElement.visible === false ? 'none' : 'auto'}`,
    'outline-offset:0',
    `cursor:${baseElement.locked ? 'not-allowed' : (isSelected ? 'grab' : 'pointer')}`,
    'touch-action:none',
  ].join(';');
  const clickAttr = `onclick="canvasSelectCreativeElement('${baseElement.id}')"`;
  const selectionAttr = isSelected ? ' data-creative-selection="true"' : '';
  const baseAttrs = `${clickAttr} data-creative-element-id="${escHtml(baseElement.id)}"${selectionAttr}`;
  if (baseElement.type === 'text') {
    return `<div ${baseAttrs} style="${sharedStyle}"><div style="width:100%;height:100%;padding:4px 6px;box-sizing:border-box;color:${escHtml(baseElement.meta?.color || '#111827')};font-size:${Number(baseElement.meta?.fontSize) || 24}px;font-weight:${Number(baseElement.meta?.fontWeight) || 700};font-family:${escHtml(baseElement.meta?.fontFamily || 'Manrope')};font-style:${escHtml(baseElement.meta?.fontStyle || 'normal')};line-height:${Number(baseElement.meta?.lineHeight) || 1.2};letter-spacing:${Number(baseElement.meta?.letterSpacing) || 0}px;text-align:${escHtml(baseElement.meta?.textAlign || 'left')};white-space:pre-wrap;overflow:hidden">${escHtml(visualState.textContent || baseElement.meta?.content || 'Text')}</div>${resizeHandle}</div>`;
  }
  if (baseElement.type === 'icon') {
    const size = Math.max(24, Math.min(Number(element.width) || 64, Number(element.height) || 64));
    return `<div ${baseAttrs} style="${sharedStyle}"><div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:${escHtml(baseElement.meta?.color || '#111827')}"><iconify-icon icon="${escHtml(baseElement.meta?.iconName || 'solar:stars-bold-duotone')}" width="${size}" height="${size}"></iconify-icon></div>${resizeHandle}</div>`;
  }
  if (baseElement.type === 'image') {
    const bg = baseElement.meta?.source
      ? `background-image:url('${escHtml(creativeMediaSourceUrl(baseElement.meta.source)).replace(/'/g, '&#39;')}');background-size:${escHtml(baseElement.meta?.fit || 'cover')};background-position:center center;`
      : 'background:linear-gradient(135deg,#2c2b2a,#474543);';
    return `<div ${baseAttrs} style="${sharedStyle}"><div style="width:100%;height:100%;border-radius:${Number(baseElement.meta?.radius) || 18}px;border:1px dashed rgba(255,255,255,0.16);${bg}"></div>${resizeHandle}</div>`;
  }
  if (baseElement.type === 'video') {
    const source = escHtml(creativeMediaSourceUrl(baseElement.meta?.source || ''));
    const fit = escHtml(String(baseElement.meta?.fit || 'cover'));
    const radius = Number(baseElement.meta?.radius) || 18;
    const poster = baseElement.meta?.poster ? ` poster="${escHtml(creativeMediaSourceUrl(baseElement.meta.poster))}"` : '';
    const body = source
      ? `<video data-creative-video-element="${escHtml(baseElement.id)}" src="${source}"${poster} muted playsinline preload="auto" style="width:100%;height:100%;object-fit:${fit};border-radius:${radius}px;display:block;background:#111827;border:1px solid rgba(255,255,255,0.12)"></video>`
      : `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;border-radius:${radius}px;border:1px dashed rgba(249,115,22,0.3);background:linear-gradient(135deg,#1f2937,#3f3f46);color:#fed7aa;font-size:12px;font-weight:800"><iconify-icon icon="solar:film-roll-bold-duotone" width="30" height="30"></iconify-icon></div>`;
    return `<div ${baseAttrs} style="${sharedStyle}">${body}${resizeHandle}</div>`;
  }
  if (baseElement.type === 'hyperframes') {
    const label = escHtml(baseElement.meta?.compositionId || 'HyperFrames clip');
    const radius = Math.max(0, Number(baseElement.meta?.radius) || 0);
    return `<div ${baseAttrs} style="${sharedStyle};overflow:hidden;background:#020617;border-radius:${radius}px"><div data-hyperframes-mount="${escHtml(baseElement.id)}" style="position:absolute;inset:0;width:100%;height:100%;overflow:hidden;background:#020617"><div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;color:#93c5fd;font-size:12px;font-weight:800;letter-spacing:0.02em">${label}</div></div>${resizeHandle}</div>`;
  }
  if (baseElement.type === 'lottie') {
    const lottieSrc = escHtml(String(baseElement.meta?.source || ''));
    const lottieLoop = baseElement.meta?.loop !== false ? 'loop' : '';
    const lottieAutoplay = baseElement.meta?.autoplay !== false ? 'autoplay' : '';
    const lottieSpeed = Number(baseElement.meta?.speed) || 1;
    const lottiePlaceholder = !lottieSrc ? `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,0.04);border-radius:12px;border:1px dashed rgba(249,115,22,0.3)"><iconify-icon icon="solar:film-roll-bold-duotone" width="32" height="32" style="color:#fb923c;opacity:0.6"></iconify-icon></div>` : '';
    return `<div ${baseAttrs} style="${sharedStyle}">${lottieSrc ? `<lottie-player src="${lottieSrc}" ${lottieLoop} ${lottieAutoplay} speed="${lottieSpeed}" style="width:100%;height:100%"></lottie-player>` : lottiePlaceholder}${resizeHandle}</div>`;
  }
  if (baseElement.type === 'group') {
    return `<div ${baseAttrs} style="${sharedStyle}">${renderCreativeComponentBodyStudioV3(baseElement)}${resizeHandle}</div>`;
  }
  const shape = String(baseElement.meta?.shape || 'rect');
  const fill = baseElement.meta?.fill || '#111827';
  const stroke = baseElement.meta?.stroke || 'transparent';
  const strokeWidth = Math.max(0, Number(baseElement.meta?.strokeWidth) || 0);
  const radius = shape === 'circle' ? 999 : Math.max(0, Number(baseElement.meta?.radius) || 0);
  if (shape === 'line' || shape === 'arrow') {
    const arrowHead = shape === 'arrow'
      ? `<div style="position:absolute;right:-1px;top:50%;transform:translateY(-50%);width:0;height:0;border-top:${Math.max(6, strokeWidth * 2)}px solid transparent;border-bottom:${Math.max(6, strokeWidth * 2)}px solid transparent;border-left:${Math.max(10, strokeWidth * 3)}px solid ${escHtml(stroke || fill)}"></div>`
      : '';
    return `<div ${baseAttrs} style="${sharedStyle};background:${escHtml(stroke || fill)};border-radius:999px">${arrowHead}${resizeHandle}</div>`;
  }
  if (shape === 'triangle') {
    return `<div ${baseAttrs} style="${sharedStyle}"><div style="width:100%;height:100%;clip-path:polygon(50% 0%, 0% 100%, 100% 100%);background:${escHtml(fill)};border:${strokeWidth}px solid ${escHtml(stroke)};box-sizing:border-box"></div>${resizeHandle}</div>`;
  }
  if (shape === 'polygon') {
    const sides = Math.max(5, Math.min(8, Number(baseElement.meta?.sides) || 6));
    const clipPath = sides >= 7
      ? 'polygon(50% 0%, 78% 10%, 100% 36%, 92% 68%, 68% 92%, 32% 92%, 8% 68%, 0% 36%, 22% 10%)'
      : sides === 5
      ? 'polygon(50% 0%, 100% 38%, 82% 100%, 18% 100%, 0% 38%)'
      : 'polygon(25% 6%, 75% 6%, 100% 50%, 75% 94%, 25% 94%, 0% 50%)';
    return `<div ${baseAttrs} style="${sharedStyle}"><div style="width:100%;height:100%;clip-path:${clipPath};background:${escHtml(fill)};border:${strokeWidth}px solid ${escHtml(stroke)};box-sizing:border-box"></div>${resizeHandle}</div>`;
  }
  return `<div ${baseAttrs} style="${sharedStyle};background:${escHtml(fill)};border:${strokeWidth}px solid ${escHtml(stroke)};border-radius:${radius}px">${resizeHandle}</div>`;
}

function drawCreativeWaveformCanvas(audioTrack) {
  const canvasEl = document.querySelector('.creative-timeline-audio-wave-canvas');
  if (!canvasEl) return;
  const peaks = audioTrack?.analysis?.waveformPeaks;
  if (!Array.isArray(peaks) || peaks.length === 0) return;
  const lane = canvasEl.closest('.creative-timeline-track-lane--audio');
  if (!lane) return;
  const laneRect = lane.getBoundingClientRect();
  if (!laneRect.width) return;
  const audioLeft = parseFloat(canvasEl.dataset.audioLeft) || 0;
  const audioWidth = parseFloat(canvasEl.dataset.audioWidth) || 0;
  const leftPx = (audioLeft / 100) * laneRect.width;
  const widthPx = Math.max(1, (audioWidth / 100) * laneRect.width);
  canvasEl.style.position = 'absolute';
  canvasEl.style.left = `${leftPx}px`;
  canvasEl.style.top = '6px';
  canvasEl.style.bottom = '6px';
  canvasEl.style.width = `${widthPx}px`;
  canvasEl.style.height = `${laneRect.height - 12}px`;
  canvasEl.style.pointerEvents = 'none';
  canvasEl.style.borderRadius = '999px';
  canvasEl.style.overflow = 'hidden';
  canvasEl.width = Math.round(widthPx * window.devicePixelRatio);
  canvasEl.height = Math.round((laneRect.height - 12) * window.devicePixelRatio);
  const ctx = canvasEl.getContext('2d');
  if (!ctx) return;
  ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
  const W = widthPx;
  const H = laneRect.height - 12;
  ctx.clearRect(0, 0, W, H);
  const buckets = peaks.length;
  const barW = Math.max(1, W / buckets);
  const midY = H / 2;
  // Sky-blue gradient matching the audio lane accent
  const grad = ctx.createLinearGradient(0, 0, 0, H);
  grad.addColorStop(0, 'rgba(125,211,252,0.82)');
  grad.addColorStop(0.5, 'rgba(56,189,248,0.72)');
  grad.addColorStop(1, 'rgba(125,211,252,0.82)');
  ctx.fillStyle = grad;
  for (let i = 0; i < buckets; i++) {
    const peak = Math.max(0, Math.min(1, Number(peaks[i]) || 0));
    const barH = Math.max(2, peak * midY * 1.8);
    const x = i * barW;
    ctx.fillRect(x, midY - barH / 2, Math.max(1, barW - 1), barH);
  }
}

function getCreativeHtmlMotionBlockIcon(block = {}) {
  const category = String(block.category || '').toLowerCase();
  if (category === 'caption') return 'solar:text-bold-duotone';
  if (category === 'product') return 'solar:monitor-smartphone-bold-duotone';
  if (category === 'chart') return 'solar:chart-2-bold-duotone';
  if (category === 'transition') return 'solar:rewind-forward-circle-bold-duotone';
  if (category === 'cta') return 'solar:cursor-square-bold-duotone';
  return 'solar:widget-add-bold-duotone';
}

function renderCreativeHtmlMotionBlocksPanelStudioV3() {
  const state = creativeHtmlMotionBlocksState;
  const query = escHtml(state.query || '');
  const blocks = Array.isArray(state.blocks) ? state.blocks : [];
  const grouped = blocks.reduce((acc, block) => {
    const key = String(block.packId || 'prometheus-core');
    if (!acc[key]) acc[key] = [];
    acc[key].push(block);
    return acc;
  }, {});
  const groups = Object.entries(grouped);
  return `
    <div class="creative-lib-panel-header">
      <div class="creative-lib-panel-title">Motion Blocks</div>
      <div class="creative-lib-panel-sub">Insert registry blocks into the active HTML motion clip.</div>
    </div>
    <div style="padding:10px 10px 0">
      <input
        class="creative-form-input"
        type="search"
        placeholder="captions, charts, CTA..."
        value="${query}"
        oninput="canvasSearchHtmlMotionBlocks(this.value)"
      />
    </div>
    ${state.loading ? `<div class="creative-asset-empty" style="padding:16px">Loading blocks...</div>` : ''}
    ${state.error ? `<div class="creative-asset-empty" style="padding:16px;color:#fca5a5">${escHtml(state.error)}</div>` : ''}
    ${!state.loading && !state.error && !blocks.length ? `<div class="creative-asset-empty" style="padding:16px">No matching HTML motion blocks.</div>` : ''}
    ${groups.map(([packId, packBlocks]) => `
      <div style="padding:12px 10px 0">
        <div style="font-size:10px;font-weight:800;letter-spacing:0.07em;text-transform:uppercase;color:#6b7280;margin-bottom:8px">${escHtml(packId.replace(/^prometheus-/, ''))}</div>
        <div class="creative-lib-cat-items" style="grid-template-columns:1fr">
          ${packBlocks.map((block) => `
            <button onclick="canvasInsertHtmlMotionBlock('${escHtml(block.id)}')" class="creative-lib-tile" style="grid-template-columns:34px 1fr;min-height:78px;text-align:left">
              <span class="creative-lib-tile-icon"><iconify-icon icon="${escHtml(getCreativeHtmlMotionBlockIcon(block))}" width="22" height="22"></iconify-icon></span>
              <span style="min-width:0">
                <span class="creative-lib-tile-label" style="display:block">${escHtml(block.name || block.id)}</span>
                <span style="display:block;font-size:10px;line-height:1.25;color:#9ca3af;margin-top:3px">${escHtml(block.description || block.bestFor || '')}</span>
                <span style="display:block;font-size:10px;line-height:1.25;color:#6b7280;margin-top:5px">${escHtml(block.category || 'block')}</span>
              </span>
            </button>
          `).join('')}
        </div>
      </div>
    `).join('')}
  `;
}

function renderCreativeHtmlMotionKnobsCardStudioV3(clip) {
  const parameters = Array.isArray(clip?.parameters) ? clip.parameters : [];
  if (!parameters.length) return '';
  const controls = parameters.map((parameter) => {
    const id = String(parameter?.id || '').trim();
    if (!id) return '';
    const type = String(parameter?.type || 'text').toLowerCase();
    const label = escHtml(parameter.label || id);
    const description = parameter.description ? `<div class="creative-info-note" style="margin-top:6px">${escHtml(parameter.description)}</div>` : '';
    const current = getHtmlMotionParameterCurrentValue(parameter, clip);
    const safeId = escHtml(id).replace(/'/g, '&#39;');
    if (type === 'range') {
      const min = Number.isFinite(Number(parameter.min)) ? Number(parameter.min) : 0;
      const max = Number.isFinite(Number(parameter.max)) ? Number(parameter.max) : 1;
      const step = Number.isFinite(Number(parameter.step)) ? Number(parameter.step) : 0.05;
      const value = Number.isFinite(Number(current)) ? Number(current) : Number(parameter.defaultValue) || min;
      return `
        <label class="creative-form-label" style="margin-top:10px">${label} <span style="float:right;color:#9ca3af">${escHtml(String(value))}</span></label>
        <input class="creative-form-input" type="range" min="${min}" max="${max}" step="${step}" value="${value}" onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.value)" />
        ${description}
      `;
    }
    if (type === 'color') {
      return `
        <label class="creative-form-label" style="margin-top:10px">${label}</label>
        <div style="display:flex;gap:8px;align-items:center">
          <input type="color" value="${escHtml(String(current || parameter.defaultValue || '#ffffff'))}" onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.value)" style="width:42px;height:34px;border:0;background:transparent;padding:0" />
          <input class="creative-form-input" type="text" value="${escHtml(String(current || parameter.defaultValue || ''))}" onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.value)" />
        </div>
        ${description}
      `;
    }
    if (type === 'boolean') {
      const checked = current === true || current === 'true' || current === '1';
      return `
        <label class="creative-form-label" style="margin-top:10px;display:flex;align-items:center;gap:8px">
          <input type="checkbox" ${checked ? 'checked' : ''} onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.checked ? 'true' : 'false')" />
          ${label}
        </label>
        ${description}
      `;
    }
    if (type === 'select' && Array.isArray(parameter.options) && parameter.options.length) {
      return `
        <label class="creative-form-label" style="margin-top:10px">${label}</label>
        <select class="creative-form-input" onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.value)">
          ${parameter.options.map((option) => {
            const selected = String(option) === String(current) ? 'selected' : '';
            return `<option value="${escHtml(String(option))}" ${selected}>${escHtml(String(option))}</option>`;
          }).join('')}
        </select>
        ${description}
      `;
    }
    return `
      <label class="creative-form-label" style="margin-top:10px">${label}</label>
      <input class="creative-form-input" type="${type === 'number' ? 'number' : 'text'}" value="${escHtml(String(current || ''))}" onchange="canvasUpdateHtmlMotionParameter('${safeId}', this.value)" />
      ${description}
    `;
  }).join('');
  return `
    <section class="creative-inspector-card">
      <div class="creative-section-heading">
        <div class="creative-card-title">Knobs</div>
        <div class="creative-card-subtitle">Template parameters mapped to HTML motion variables.</div>
      </div>
      ${controls}
      <div class="creative-pill-row" style="margin-top:12px">
        <button onclick="canvasRunHtmlMotionFrameQA()" class="creative-chip-btn"><iconify-icon icon="solar:camera-bold-duotone" width="14" height="14"></iconify-icon>Check frames</button>
      </div>
    </section>
  `;
}

function renderCreativeHtmlMotionLintCardStudioV3() {
  const clip = normalizeCreativeHtmlMotionClip(creativeHtmlMotionClip);
  const lint = creativeHtmlMotionLintState.lint || clip?.lint || null;
  const composition = creativeHtmlMotionLintState.composition || clip?.composition || null;
  const issues = Array.isArray(lint?.issues) ? lint.issues : [];
  const errors = Array.isArray(lint?.errors) && lint.errors.length
    ? lint.errors
    : issues.filter((issue) => String(issue?.severity || '').toLowerCase() === 'error');
  const warnings = Array.isArray(lint?.warnings) && lint.warnings.length
    ? lint.warnings
    : issues.filter((issue) => String(issue?.severity || '').toLowerCase() === 'warning');
  const errorCount = errors.length || Math.max(0, Number(lint?.errorCount) || 0);
  const warningCount = warnings.length || Math.max(0, Number(lint?.warningCount) || 0);
  const ok = lint ? lint.ok !== false && errorCount === 0 : false;
  const statusLabel = creativeHtmlMotionLintState.loading
    ? 'Checking'
    : lint
      ? (ok ? 'Export ready' : `${errorCount} issue${errorCount === 1 ? '' : 's'}`)
      : 'Not checked';
  if (!clip) {
    return `
      <section class="creative-inspector-card">
        <div class="creative-section-heading">
          <div class="creative-card-title">HTML motion</div>
          <div class="creative-card-subtitle">Start a registry-backed composition, then add blocks from the Blocks rail.</div>
        </div>
        <div class="creative-pill-row">
          <button onclick="canvasCreateBlankHtmlMotionComposition().catch((err)=>showToast(String(err && err.message ? err.message : err), 'error'))" class="creative-chip-btn creative-chip-btn--accent">
            <iconify-icon icon="solar:add-circle-bold-duotone" width="14" height="14"></iconify-icon>New HTML motion
          </button>
        </div>
      </section>
    `;
  }
  return `
    ${renderCreativeHtmlMotionKnobsCardStudioV3(clip)}
    <section class="creative-inspector-card">
      <div class="creative-section-heading">
        <div class="creative-card-title">HTML motion lint</div>
        <div class="creative-card-subtitle">${escHtml(clip.title || clip.path)}</div>
      </div>
      <div class="creative-inspector-summary">
        <span class="creative-summary-pill">${escHtml(statusLabel)}</span>
        <span class="creative-summary-pill">${errorCount} errors</span>
        <span class="creative-summary-pill">${warningCount} warnings</span>
        ${composition ? `<span class="creative-summary-pill">${Math.round(Number(composition.width) || clip.width)} x ${Math.round(Number(composition.height) || clip.height)}</span>` : ''}
        ${composition?.durationMs ? `<span class="creative-summary-pill">${escHtml(formatCreativeTimelineTime(composition.durationMs))}</span>` : ''}
      </div>
      ${creativeHtmlMotionLintState.error ? `<div class="creative-info-note" style="margin-top:10px;color:#fca5a5">${escHtml(creativeHtmlMotionLintState.error)}</div>` : ''}
      ${errors.length ? `<div class="creative-info-note" style="margin-top:10px;color:#fca5a5">${errors.slice(0, 3).map((entry) => escHtml(entry.message || entry)).join('<br>')}</div>` : ''}
      ${!errors.length && warnings.length ? `<div class="creative-info-note" style="margin-top:10px">${warnings.slice(0, 3).map((entry) => escHtml(entry.message || entry)).join('<br>')}</div>` : ''}
      <div class="creative-pill-row" style="margin-top:12px">
        <button onclick="canvasRefreshHtmlMotionLint()" class="creative-chip-btn"><iconify-icon icon="solar:checklist-minimalistic-bold-duotone" width="14" height="14"></iconify-icon>Lint</button>
        <button onclick="canvasRunHtmlMotionFrameQA()" class="creative-chip-btn"><iconify-icon icon="solar:camera-bold-duotone" width="14" height="14"></iconify-icon>Frame QA</button>
        <button onclick="canvasExportHtmlMotionClip(false)" class="creative-chip-btn creative-chip-btn--accent"><iconify-icon icon="solar:videocamera-record-bold-duotone" width="14" height="14"></iconify-icon>Export MP4</button>
      </div>
      ${errors.length ? `<div class="creative-pill-row" style="margin-top:8px"><button onclick="canvasExportHtmlMotionClip(true)" class="creative-chip-btn creative-chip-btn--danger">Force export</button></div>` : ''}
    </section>
  `;
}

