function renderCreativeWorkspaceStudioV3(options) {
  if (creativeWorkspaceRuntimeModule) {
    return creativeWorkspaceRuntimeModule.renderCreativeWorkspaceStudioV3(creativeWorkspaceRuntimeContext, options);
  }
  void loadCreativeWorkspaceRuntime()
    .then((module) => module.renderCreativeWorkspaceStudioV3(creativeWorkspaceRuntimeContext, options))
    .catch((error) => console.warn('[Creative] optional workspace failed to load:', error));
  return undefined;
}

function canvasAddCreativeLibraryItem(section, kind) {
  const items = getActiveCreativeElementLibrary()[String(section || '').toLowerCase()] || [];
  const found = items.find((item) => item.kind === kind);
  if (!found) return;
  ensureCreativeSceneForMode(window.currentCreativeMode);
  const nextZ = creativeSceneDoc.elements.length;
  const baseX = 96 + (creativeSceneDoc.elements.length % 4) * 56;
  const baseY = 120 + (creativeSceneDoc.elements.length % 5) * 44;
  const defaultWidth = Number.isFinite(Number(found.defaultWidth))
    ? Math.max(12, Number(found.defaultWidth))
    : found.type === 'text'
    ? 420
    : found.type === 'icon'
      ? 84
      : found.type === 'group'
        ? (['button', 'badge', 'divider'].includes(found.kind) ? 240 : 300)
        : (['triangle', 'polygon'].includes(found.kind) ? 180 : 220);
  const defaultHeight = Number.isFinite(Number(found.defaultHeight))
    ? Math.max(12, Number(found.defaultHeight))
    : found.type === 'text'
    ? 96
    : found.type === 'icon'
      ? 84
      : found.type === 'group'
        ? (found.kind === 'button' ? 64 : found.kind === 'badge' ? 52 : found.kind === 'divider' ? 54 : 180)
        : (found.kind === 'line' || found.kind === 'arrow' ? 12 : 140);
  const patch = {
    op: 'add',
    type: found.type,
    x: baseX,
    y: baseY,
    width: defaultWidth,
    height: defaultHeight,
    zIndex: nextZ,
    meta: JSON.parse(JSON.stringify(found.meta || {})),
  };
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [patch]);
  const added = nextDoc.elements[nextDoc.elements.length - 1];
  setCreativeSceneDoc(nextDoc, { render: false, recordHistory: true });
  setCreativeSelection(added?.id || null, { render: false });
  renderCreativeWorkspace();
}

function canvasAddCreativePreset() {
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [
    {
      op: 'add',
      type: 'shape',
      x: 120,
      y: mode === 'video' ? 420 : 360,
      width: 320,
      height: 180,
      zIndex: creativeSceneDoc.elements.length,
      meta: { shape: 'rect', fill: mode === 'video' ? '#1d4ed8' : '#fdba74', radius: 24 },
    },
    {
      op: 'add',
      type: 'text',
      x: 156,
      y: mode === 'video' ? 464 : 404,
      width: 260,
      height: 72,
      zIndex: creativeSceneDoc.elements.length + 1,
      meta: { content: mode === 'video' ? 'Motion Block' : 'Feature Card', fontSize: 32, fontWeight: 800, color: '#ffffff', lineHeight: 1.2 },
    },
  ]);
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasApplyCreativeAnimationPreset(preset) {
  const selected = getSelectedCreativeElement();
  if (!selected) return;
  const presetCatalog = getActiveCreativeAnimationPresetCatalog(selected?.type || '');
  const normalizedPresetId = String(preset || '').trim().toLowerCase().replace(/-/g, '_');
  const presetMeta = presetCatalog.find((entry) => String(entry?.id || '').trim().toLowerCase().replace(/-/g, '_') === normalizedPresetId);
  const defaultDurationMs = Math.max(100, Number(presetMeta?.defaultDurationMs) || 500);
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'add-animation-preset',
    id: selected.id,
    patch: {
      preset,
      startMs: creativeTimelineMs,
      durationMs: defaultDurationMs,
    },
  }]);
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasClearCreativeScene() {
  const ok = typeof confirm === 'function' ? confirm('Clear the current creative scene?') : true;
  if (!ok) return;
  commitCreativeHistorySnapshot(captureCreativeSnapshot());
  creativeHistoryFuture = [];
  creativeSceneDoc = getDefaultCreativeScene(window.currentCreativeMode);
  creativeSelectedId = creativeSceneDoc.elements[creativeSceneDoc.elements.length - 1]?.id || null;
  creativeTimelineMs = 0;
  creativeHtmlMotionClip = null;
  stopCreativeAudioPreview({ reset: true, dispose: true });
  persistActiveChat();
  renderCreativeWorkspace();
}

function canvasSelectCreativeInspectorTab(tab) {
  setCreativeInspectorTab(tab);
}

function canvasSelectCreativeElement(id) {
  setCreativeSelection(id);
}

function canvasToggleCreativeLayerVisibility(elementId) {
  const element = findCreativeElementInDoc(creativeSceneDoc, elementId);
  if (!element) return;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'set',
    id: elementId,
    patch: { visible: element.visible === false },
  }]);
  setCreativeSelection(elementId, { render: false, persist: false });
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasToggleCreativeLayerLock(elementId) {
  const element = findCreativeElementInDoc(creativeSceneDoc, elementId);
  if (!element) return;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'set',
    id: elementId,
    patch: { locked: element.locked !== true },
  }]);
  setCreativeSelection(elementId, { render: false, persist: false });
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasMoveCreativeLayer(elementId, direction) {
  if (!elementId) return;
  setCreativeSelection(elementId, { render: false, persist: false });
  canvasNudgeCreativeZ(direction);
}

function canvasClearCreativeAudioTrack() {
  if (normalizeCreativeMode(window.currentCreativeMode) !== 'video') return;
  creativeAudioAnalysisRequestToken += 1;
  commitCreativeHistorySnapshot(captureCreativeSnapshot());
  const nextDoc = createSceneDocument({
    ...creativeSceneDoc,
    audioTrack: {
      source: '',
      label: '',
      startMs: 0,
      durationMs: 0,
      trimStartMs: 0,
      trimEndMs: 0,
      volume: 1,
      muted: false,
      fadeInMs: 0,
      fadeOutMs: 0,
      analysis: null,
    },
  });
  stopCreativeAudioPreview({ reset: true, dispose: true });
  setCreativeSceneDoc(nextDoc, { render: false, persist: false });
  renderCreativeWorkspace();
  persistActiveChat();
}

function coerceCreativeValue(raw, type) {
  if (type === 'color' || type === 'text') return String(raw ?? '');
  if (type === 'boolean') return raw === true || raw === 'true' || raw === '1' || raw === 'on';
  const n = Number(raw);
  return Number.isFinite(n) ? n : 0;
}

function canvasUpdateCreativeProperty(key, rawValue, type = 'number') {
  const selected = getSelectedCreativeElement();
  if (!selected) return;
  const normalizedKey = String(key || '').trim();
  const value = coerceCreativeValue(rawValue, type);
  const extraPatch = normalizedKey === 'meta.content' && selected.meta?.motionEffects?.typewriter
    ? { 'meta.motionEffects.typewriter.sourceContent': String(value ?? '') }
    : null;
  let nextDoc = null;
  if (normalizeCreativeMode(window.currentCreativeMode) === 'video' && CREATIVE_VIDEO_TIMELINE_KEYS.has(normalizedKey)) {
    if (normalizedKey === 'x' || normalizedKey === 'y' || normalizedKey === 'width' || normalizedKey === 'height') {
      const rendered = getRenderedCreativeElement(selected, 'video') || selected;
      const rawPatch = {
        x: normalizedKey === 'x' ? value : rendered.x,
        y: normalizedKey === 'y' ? value : rendered.y,
        width: normalizedKey === 'width' ? value : rendered.width,
        height: normalizedKey === 'height' ? value : rendered.height,
      };
      const aspectPatch = normalizedKey === 'width' || normalizedKey === 'height'
        ? applyCreativeAspectLockToRect(selected, rendered, rawPatch, {
            prefer: normalizedKey === 'height' ? 'height' : 'width',
          })
        : rawPatch;
      nextDoc = applyCreativeGeometryPatch(selected.id, aspectPatch, {
        mode: 'video',
        atMs: creativeTimelineMs,
        aspectLock: normalizedKey === 'width' || normalizedKey === 'height',
        prefer: normalizedKey === 'height' ? 'height' : 'width',
      });
    } else {
      const nextValue = normalizedKey === 'opacity'
        ? Math.max(0, Math.min(1, Number(value) || 0))
        : Number(value) || 0;
      nextDoc = applyCreativeTimelineScalarPatch(selected.id, normalizedKey, nextValue, { mode: 'video', atMs: creativeTimelineMs });
    }
  } else {
    if (normalizedKey === 'width' || normalizedKey === 'height' || normalizedKey === 'x' || normalizedKey === 'y') {
      const rawPatch = {
        x: normalizedKey === 'x' ? value : selected.x,
        y: normalizedKey === 'y' ? value : selected.y,
        width: normalizedKey === 'width' ? value : selected.width,
        height: normalizedKey === 'height' ? value : selected.height,
      };
      const aspectPatch = normalizedKey === 'width' || normalizedKey === 'height'
        ? applyCreativeAspectLockToRect(selected, selected, rawPatch, {
            prefer: normalizedKey === 'height' ? 'height' : 'width',
          })
        : rawPatch;
      nextDoc = applyCreativeGeometryPatch(selected.id, aspectPatch, {
        mode: window.currentCreativeMode,
        aspectLock: normalizedKey === 'width' || normalizedKey === 'height',
        prefer: normalizedKey === 'height' ? 'height' : 'width',
      });
    } else {
      nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
        op: 'set',
        id: selected.id,
        patch: extraPatch ? { [key]: value, ...extraPatch } : { [key]: value },
      }]);
    }
  }
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasUpdateCreativeDocumentProperty(key, rawValue, type = 'number') {
  const value = coerceCreativeValue(rawValue, type);
  commitCreativeHistorySnapshot(captureCreativeSnapshot());
  const nextDoc = (() => {
    const clone = JSON.parse(JSON.stringify(creativeSceneDoc || createSceneDocument()));
    if (String(key || '').includes('.')) setCreativeNestedValue(clone, key, value);
    else clone[key] = value;
    return createSceneDocument(clone);
  })();
  setCreativeSceneDoc(nextDoc, { render: false, persist: false });
  creativeTimelineMs = Math.max(0, Math.min(Math.max(1000, Number(nextDoc.durationMs) || 12000), creativeTimelineMs));
  const session = getActiveChatSessionRecord();
  if (session) session.creativeTimelineMs = creativeTimelineMs;
  renderCreativeWorkspace();
  persistActiveChat();
  const normalizedKey = String(key || '').trim();
  if (normalizedKey.startsWith('audioTrack.')) {
    const track = getCreativeAudioTrackConfig(nextDoc);
    creativeAudioAnalysisRequestToken += 1;
    if (track.source) {
      void syncCreativeAudioTrackAnalysis(nextDoc, {
        force: normalizedKey === 'audioTrack.source',
        silent: true,
      });
    }
  }
}

function canvasSetCreativeTimeline(rawValue) {
  if (isCreativePlaybackActive()) pauseCreativePlayback();
  setCreativeTimelinePosition(rawValue, { render: false, forceSeek: true });
}

function canvasAddCreativeKeyframe() {
  const selected = getSelectedCreativeElement();
  if (!selected) return;
  const rendered = getRenderedCreativeElement(selected, window.currentCreativeMode) || selected;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'add-keyframe',
    id: selected.id,
    patch: {
      atMs: creativeTimelineMs,
      x: rendered.x,
      y: rendered.y,
      width: rendered.width,
      height: rendered.height,
      opacity: rendered.opacity,
      rotation: rendered.rotation,
    },
  }]);
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasDeleteCreativeKeyframe(keyframeId) {
  const selected = getSelectedCreativeElement();
  if (!selected || !keyframeId) return;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'delete-keyframe',
    id: selected.id,
    keyframeId,
  }]);
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasSetCreativeKeyframeEase(ease) {
  const selected = getSelectedCreativeElement();
  if (!selected || !ease) return;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'set-ease',
    id: selected.id,
    patch: {
      atMs: creativeTimelineMs,
      ease,
    },
  }]);
  setCreativeSceneDoc(nextDoc, { recordHistory: true });
}

function canvasDeleteCreativeSelection() {
  const selected = getSelectedCreativeElement();
  if (!selected) return;
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{ op: 'delete', id: selected.id }]);
  setCreativeSceneDoc(nextDoc, { render: false, recordHistory: true });
  const fallback = nextDoc.elements[nextDoc.elements.length - 1]?.id || null;
  setCreativeSelection(fallback, { render: false });
  renderCreativeWorkspace();
}

function canvasNudgeCreativeZ(direction) {
  const selected = getSelectedCreativeElement();
  if (!selected) return;
  const sorted = creativeSceneDoc.elements.slice().sort((a, b) => (a.zIndex || 0) - (b.zIndex || 0));
  const index = sorted.findIndex((element) => element.id === selected.id);
  if (index === -1) return;
  const swapIndex = index + (direction > 0 ? 1 : -1);
  if (swapIndex < 0 || swapIndex >= sorted.length) return;
  const next = sorted.slice();
  const tmp = next[index];
  next[index] = next[swapIndex];
  next[swapIndex] = tmp;
  const normalized = next.map((element, idx) => ({ ...element, zIndex: idx }));
  setCreativeSceneDoc({ ...creativeSceneDoc, elements: normalized }, { recordHistory: true });
}

function buildCreativeSceneCallerContext() {
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  if (isBrowserDesignMode()) {
    const state = getBrowserCanvasState();
    const selected = cloneBrowserDesignSelection(state.selectedElement);
    const selections = Array.isArray(state.browserDesignSelections) ? state.browserDesignSelections.map(cloneBrowserDesignSelection).filter(Boolean) : [];
    return [
      '[BROWSER_DESIGN_SURFACE]',
      `browser_url: ${state.url || 'unknown'}`,
      `browser_title: ${state.title || 'unknown'}`,
      `browser_profile: ${state.profileLabel || state.browserTarget || state.profileKind || 'browser gateway'}`,
      selected ? `[BROWSER_DESIGN_SELECTION]\n${JSON.stringify(selected).slice(0, 4200)}` : '',
      selections.length ? `[BROWSER_DESIGN_MULTI_SELECTION]\n${JSON.stringify(selections).slice(0, 12000)}` : '',
      selected ? 'Use the selected live browser element as the primary focus. Explain the change or edit the source if this is a local project; for external pages, describe the limitation and provide the exact DOM/CSS guidance.' : '',
    ].filter(Boolean).join('\n');
  }
  if (mode === 'design') {
    const tab = canvasTabs.find((candidate) => candidate.id === activeCanvasTabId) || null;
    const projectFiles = flattenCanvasWorkspaceFiles(canvasWorkspaceTree).slice(0, 24);
    return [
      `[DESIGN_SURFACE]`,
      tab ? `active_file: ${tab.diskPath || tab.name}` : '',
      tab?.diskPath ? `workspace_path: ${tab.diskPath}` : '',
      tab ? `preview_mode: ${tab.mode || 'preview'}` : '',
      projectFiles.length ? `project_files:\n${projectFiles.map((filePath) => `- ${filePath}`).join('\n')}` : '',
      designSelectedElementContext ? `[DESIGN_SELECTION]\n${JSON.stringify(designSelectedElementContext).slice(0, 2600)}` : '',
      designSelectedElementContext?.sourceAnchor?.file
        ? `Source anchor: ${designSelectedElementContext.sourceAnchor.file}${designSelectedElementContext.sourceAnchor.line ? `:${designSelectedElementContext.sourceAnchor.line}:${designSelectedElementContext.sourceAnchor.column || 1}` : ''}. Start there, then verify the surrounding source before editing.`
        : '',
      designSelectedElementContext?.sourceCandidates?.length
        ? `Verified source candidates:\n${designSelectedElementContext.sourceCandidates.slice(0, 6).map((candidate) => `- ${candidate.file}:${candidate.line}:${candidate.column} (${candidate.matchedBy}, ${candidate.confidence})${candidate.preview ? ` — ${candidate.preview}` : ''}`).join('\n')}`
        : '',
      designSelectedElementContext ? 'Use the selected preview element as the primary focus. Read and edit the live project files already open in the canvas; do not only describe code changes.' : '',
      designMultiSelectedElements.length ? `[DESIGN_MULTI_SELECTION]\n${JSON.stringify(designMultiSelectedElements.map((entry) => entry.context)).slice(0, 12000)}` : '',
      designMultiSelectedElements.length ? `The user has attached ${designMultiSelectedElements.length} preview element${designMultiSelectedElements.length === 1 ? '' : 's'} for multi-edit. Apply the requested change across ALL of them by editing the corresponding source files.` : '',
      getDesignPatchInstruction(),
    ].filter(Boolean).join('\n');
  }
  if (!isStructuredCreativeMode(mode)) return '';
  ensureCreativeSceneForMode(mode);
  const selected = getSelectedCreativeElement();
  const selectionCtx = selected ? buildSceneSelectionContext(creativeSceneDoc, selected.id) : null;
  const enabledLibraryLabels = (Array.isArray(creativeLibrariesState.libraries) ? creativeLibrariesState.libraries : [])
    .filter((pack) => pack?.enabled === true)
    .map((pack) => pack?.label || pack?.id)
    .filter(Boolean)
    .join(', ');
  const elementSummary = creativeSceneDoc.elements.slice(0, 12).map((element) => {
    const label = element.type === 'hyperframes'
      ? (element.meta?.compositionId || element.meta?.catalogId || 'HyperFrames composition')
      : element.meta?.content || element.meta?.iconName || element.meta?.shape || element.type;
    const keyframeCount = Array.isArray(element.meta?.keyframes) ? element.meta.keyframes.length : 0;
    const hfMeta = element.type === 'hyperframes'
      ? ` · HyperFrames ${element.meta?.advancedBlock ? 'advanced' : 'editable'} · ${Math.max(0, Number(element.meta?.durationMs) || 0)}ms`
      : '';
    return `- [${element.id}] ${element.type} @ (${element.x}, ${element.y}) ${element.width}x${element.height}${hfMeta}${keyframeCount ? ` · keyframes ${keyframeCount}` : ''} :: ${String(label).slice(0, 80)}`;
  }).join('\n');
  return [
    `[CREATIVE_SCENE]`,
    `mode: ${mode}`,
    creativeSceneDoc.elements.some((element) => element.type === 'hyperframes') ? 'HyperFrames clip mode is active: prefer hyperframes_* tools for source-backed edits, lint, QA, and export. Use HTML Motion tools only for legacy clips or explicit fallback.' : '',
    creativeHtmlMotionClip ? `activeHtmlMotionClip: ${creativeHtmlMotionClip.path || creativeHtmlMotionClip.title || 'yes'}` : '',
    creativeHtmlMotionClip ? 'Legacy HTML Motion clip mode is active: for edits, first call creative_read_html_motion_clip, then creative_patch_html_motion_clip with the smallest safe ops. Only recreate with creative_create_html_motion_clip when the user asks for a rebuild. QA/export with creative_render_html_motion_snapshot and creative_export_html_motion_clip.' : '',
    `canvas: ${creativeSceneDoc.width}x${creativeSceneDoc.height}`,
    `background: ${creativeSceneDoc.background || '#ffffff'}`,
    `durationMs: ${Math.max(1000, Number(creativeSceneDoc.durationMs) || 12000)}`,
    `frameRate: ${Math.max(1, Number(creativeSceneDoc.frameRate) || 60)}`,
    `playheadMs: ${creativeTimelineMs}`,
    `elements: ${creativeSceneDoc.elements.length}`,
    `enabledLibraries: ${getActiveCreativeLibraryIds().join(', ')}`,
    enabledLibraryLabels ? `enabledLibraryLabels: ${enabledLibraryLabels}` : '',
    elementSummary ? `scene_elements:\n${elementSummary}` : '',
    selectionCtx ? `[CREATIVE_SELECTION]\n${JSON.stringify(selectionCtx).slice(0, 2400)}` : '',
    creativeHtmlMotionSelectedElementContext ? `[HTML_MOTION_SELECTION]\n${JSON.stringify(creativeHtmlMotionSelectedElementContext).slice(0, 5200)}` : '',
    creativeHtmlMotionSelectedElementContext ? 'Use the selected HTML motion element as the primary focus. Prefer creative_read_html_motion_clip followed by focused creative_patch_html_motion_clip operations targeting the selector, role, nearby HTML snippet, timing attributes, or stable region markers. Do not rebuild the whole clip unless the user explicitly asks for a full rebuild.' : '',
    getCreativePatchInstruction(mode),
  ].filter(Boolean).join('\n');
}

function summarizeCreativeSceneForCommand() {
  const doc = creativeSceneDoc || createSceneDocument();
  const elements = Array.isArray(doc.elements) ? doc.elements : [];
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  const validation = validateCreativeSceneLayout(doc, { mode });
  return {
    mode,
    width: Number(doc.width) || 0,
    height: Number(doc.height) || 0,
    background: doc.background || '',
    durationMs: Math.max(1000, Number(doc.durationMs) || 12000),
    frameRate: Math.max(1, Number(doc.frameRate) || 60),
    playheadMs: creativeTimelineMs || 0,
    selectedId: creativeSelectedId || null,
    elementCount: elements.length,
    htmlMotionClip: normalizeCreativeHtmlMotionClip(creativeHtmlMotionClip),
    elements: elements.slice(0, 24).map((element) => ({
      id: element.id,
      type: element.type,
      x: element.x,
      y: element.y,
      width: element.width,
      height: element.height,
      rotation: element.rotation,
      opacity: element.opacity,
      zIndex: element.zIndex,
      label: element.type === 'hyperframes'
        ? (element.meta?.compositionId || element.meta?.catalogId || 'HyperFrames composition')
        : element.meta?.content || element.meta?.iconName || element.meta?.shape || element.meta?.src || element.type,
      keyframes: Array.isArray(element.meta?.keyframes) ? element.meta.keyframes.length : 0,
    })),
    validation,
  };
}

function hashCreativeObject(value) {
  const text = JSON.stringify(value || {});
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function getCreativeElementTiming(element = {}) {
  const keyframes = Array.isArray(element.meta?.keyframes) ? element.meta.keyframes : [];
  const keyTimes = keyframes
    .map((keyframe) => Number(keyframe?.atMs))
    .filter((value) => Number.isFinite(value));
  const timelineStartMs = Number.isFinite(Number(element.meta?.timelineStartMs)) ? Number(element.meta.timelineStartMs) : null;
  const timelineDurationMs = Number.isFinite(Number(element.meta?.timelineDurationMs)) ? Number(element.meta.timelineDurationMs) : null;
  const startMs = timelineStartMs ?? (keyTimes.length ? Math.min(...keyTimes) : 0);
  const endMs = timelineDurationMs !== null
    ? startMs + timelineDurationMs
    : (keyTimes.length ? Math.max(...keyTimes) : Math.max(1000, Number(creativeSceneDoc?.durationMs) || 12000));
  return {
    startMs,
    endMs,
    durationMs: Math.max(0, endMs - startMs),
    keyframeCount: keyframes.length,
    keyframeTimes: keyTimes.slice(0, 24),
    timelineStartMs,
    timelineDurationMs,
  };
}

function getCreativeElementInventory(options = {}) {
  const includeHidden = options.includeHidden !== false;
  const doc = creativeSceneDoc || createSceneDocument();
  const elements = Array.isArray(doc.elements) ? doc.elements : [];
  return elements
    .filter((element) => includeHidden || (element.visible !== false && Number(element.opacity) !== 0))
    .map((element, index) => {
      const timing = getCreativeElementTiming(element);
      return {
        index,
        id: element.id,
        type: element.type,
        label: element.meta?.content || element.meta?.iconName || element.meta?.source || element.meta?.shape || element.type,
        text: element.type === 'text' ? String(element.meta?.content || '') : '',
        source: element.meta?.source || element.meta?.src || '',
        iconName: element.meta?.iconName || '',
        parentId: element.parentId || element.groupId || element.meta?.parentId || null,
        templateId: element.meta?.templateId || element.meta?.motionTemplateId || element.templateId || null,
        templateInstanceId: element.meta?.templateInstanceId || element.meta?.motionTemplateInstanceId || null,
        visible: element.visible !== false,
        locked: element.locked === true,
        x: element.x,
        y: element.y,
        width: element.width,
        height: element.height,
        rotation: element.rotation,
        opacity: element.opacity,
        zIndex: element.zIndex,
        timing,
        animationIds: Array.isArray(element.meta?.animations) ? element.meta.animations.map((entry) => entry?.preset || entry?.id).filter(Boolean) : [],
        keyframes: Array.isArray(element.meta?.keyframes) ? element.meta.keyframes.slice(0, 12) : [],
      };
    });
}

function getCreativeFrameTraceAt(atMs) {
  const doc = creativeSceneDoc || createSceneDocument();
  const width = Math.max(1, Number(doc.width) || 1080);
  const height = Math.max(1, Number(doc.height) || 1080);
  const currentMs = Math.max(0, Number(atMs) || 0);
  const elements = (Array.isArray(doc.elements) ? doc.elements : [])
    .map((element, index) => {
      const rendered = resolveElementAtTime(element, currentMs) || element;
      const timing = getCreativeElementTiming(element);
      const bounds = {
        left: Number(rendered.x) || 0,
        top: Number(rendered.y) || 0,
        right: (Number(rendered.x) || 0) + (Number(rendered.width) || 0),
        bottom: (Number(rendered.y) || 0) + (Number(rendered.height) || 0),
      };
      const intersectsCanvas = bounds.right > 0 && bounds.bottom > 0 && bounds.left < width && bounds.top < height;
      const visible = rendered.visible !== false && Number(rendered.opacity ?? 1) > 0.001;
      const withinTiming = currentMs >= timing.startMs && currentMs <= Math.max(timing.startMs, timing.endMs);
      return {
        index,
        id: element.id,
        type: element.type,
        label: element.meta?.content || element.meta?.iconName || element.meta?.source || element.meta?.shape || element.type,
        active: visible && intersectsCanvas && withinTiming,
        visible,
        intersectsCanvas,
        withinTiming,
        zIndex: Number(rendered.zIndex) || 0,
        opacity: rendered.opacity,
        x: rendered.x,
        y: rendered.y,
        width: rendered.width,
        height: rendered.height,
        rotation: rendered.rotation,
        timing,
        sourceTemplate: element.meta?.templateId || element.meta?.motionTemplateId || element.meta?.templateInstanceId || null,
      };
    })
    .sort((a, b) => (a.zIndex - b.zIndex) || (a.index - b.index));
  return {
    atMs: currentMs,
    canvas: { width, height, durationMs: doc.durationMs, frameRate: doc.frameRate },
    activeCount: elements.filter((element) => element.active).length,
    elements,
  };
}

function diffCreativeFrameTraces(leftTrace, rightTrace) {
  const leftById = new Map((leftTrace?.elements || []).map((element) => [element.id, element]));
  const rightById = new Map((rightTrace?.elements || []).map((element) => [element.id, element]));
  const ids = new Set([...leftById.keys(), ...rightById.keys()]);
  const changed = [];
  ids.forEach((id) => {
    const left = leftById.get(id);
    const right = rightById.get(id);
    if (!left || !right) {
      changed.push({ id, change: left ? 'removed' : 'added', left: left || null, right: right || null });
      return;
    }
    const keys = ['active', 'visible', 'intersectsCanvas', 'withinTiming', 'x', 'y', 'width', 'height', 'rotation', 'opacity', 'zIndex'];
    const deltas = {};
    keys.forEach((key) => {
      if (JSON.stringify(left[key]) !== JSON.stringify(right[key])) deltas[key] = { from: left[key], to: right[key] };
    });
    if (Object.keys(deltas).length) changed.push({ id, type: right.type, label: right.label, change: 'changed', deltas });
  });
  return changed;
}

function getCreativeElementBounds(element = {}) {
  const left = Number(element.x) || 0;
  const top = Number(element.y) || 0;
  const width = Math.max(0, Number(element.width) || 0);
  const height = Math.max(0, Number(element.height) || 0);
  return { left, top, right: left + width, bottom: top + height, width, height, area: width * height };
}

function getCreativeOverlapDetails(options = {}) {
  const threshold = Math.max(0, Number(options.threshold ?? 0.02) || 0.02);
  const atMs = Number.isFinite(Number(options.atMs)) ? Number(options.atMs) : creativeTimelineMs;
  const elements = (Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [])
    .map((element) => (normalizeCreativeMode(window.currentCreativeMode) === 'video' ? (resolveElementAtTime(element, atMs) || element) : element))
    .filter((element) => element && element.visible !== false && Number(element.opacity ?? 1) > 0.001);
  const overlaps = [];
  for (let i = 0; i < elements.length; i += 1) {
    for (let j = i + 1; j < elements.length; j += 1) {
      const a = elements[i];
      const b = elements[j];
      const ab = getCreativeElementBounds(a);
      const bb = getCreativeElementBounds(b);
      const width = Math.max(0, Math.min(ab.right, bb.right) - Math.max(ab.left, bb.left));
      const height = Math.max(0, Math.min(ab.bottom, bb.bottom) - Math.max(ab.top, bb.top));
      const area = width * height;
      if (!area) continue;
      const smallerArea = Math.max(1, Math.min(ab.area || 0, bb.area || 0));
      const ratio = area / smallerArea;
      if (ratio < threshold) continue;
      overlaps.push({
        ids: [a.id, b.id],
        types: [a.type, b.type],
        labels: [
          a.meta?.content || a.meta?.iconName || a.meta?.source || a.type,
          b.meta?.content || b.meta?.iconName || b.meta?.source || b.type,
        ],
        area: Math.round(area),
        overlapRatio: Number(ratio.toFixed(3)),
        bounds: {
          left: Math.round(Math.max(ab.left, bb.left)),
          top: Math.round(Math.max(ab.top, bb.top)),
          right: Math.round(Math.min(ab.right, bb.right)),
          bottom: Math.round(Math.min(ab.bottom, bb.bottom)),
          width: Math.round(width),
          height: Math.round(height),
        },
        severity: (a.type === 'text' || b.type === 'text') && ratio >= 0.08 ? 'error' : (ratio >= 0.22 ? 'warn' : 'info'),
      });
    }
  }
  return overlaps.sort((a, b) => b.overlapRatio - a.overlapRatio);
}

function getCreativeTextOverflowDetails() {
  const elements = Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [];
  return elements
    .filter((element) => element?.type === 'text' && element.visible !== false && Number(element.opacity ?? 1) > 0.001)
    .map((element) => {
      const content = String(element.meta?.content || '');
      const measurement = measureTextBlock(content, buildTextFontSpec(element.meta), element.width, element.meta?.lineHeight || 1.2, {
        fontSize: element.meta?.fontSize,
        fontWeight: element.meta?.fontWeight,
        fontFamily: element.meta?.fontFamily,
        fontStyle: element.meta?.fontStyle,
      });
      const measuredHeight = Math.round(Number(measurement.height) || 0);
      const measuredWidth = Math.round(Number(measurement.width) || Math.min(Number(element.width) || 0, Math.max(0, content.length * Number(element.meta?.fontSize || 24) * 0.55)));
      const boxWidth = Math.max(0, Number(element.width) || 0);
      const boxHeight = Math.max(0, Number(element.height) || 0);
      const verticalOverflow = measuredHeight > boxHeight + Math.max(4, Number(element.meta?.fontSize || 24) * 0.25);
      const longestWord = content.split(/\s+/).reduce((longest, word) => Math.max(longest, word.length), 0);
      const longWordRisk = longestWord > 16 && boxWidth < Number(element.meta?.fontSize || 24) * 9;
      const brokenLineRisk = content.split('\n').some((line) => line.length <= 2 && content.length > 18)
        || /\b[A-Za-z]{3,}\s*\n\s*[A-Za-z]{1,2}\b|\b[A-Za-z]{1,2}\s*\n\s*[A-Za-z]{3,}\b/.test(content);
      return {
        id: element.id,
        text: content,
        box: { width: boxWidth, height: boxHeight },
        measured: { width: measuredWidth, height: measuredHeight, lineCount: measurement.lineCount || null },
        overflow: verticalOverflow || longWordRisk || brokenLineRisk,
        verticalOverflow,
        longWordRisk,
        brokenLineRisk,
      };
    });
}

function parseCreativeHexColor(value) {
  const raw = String(value || '').trim();
  const hex = raw.match(/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i)?.[1];
  if (!hex) return null;
  const full = hex.length === 3 ? hex.split('').map((part) => `${part}${part}`).join('') : hex;
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
    raw: `#${full.toUpperCase()}`,
  };
}

function getCreativeRelativeLuminance(color) {
  const channel = (value) => {
    const normalized = Math.max(0, Math.min(255, Number(value) || 0)) / 255;
    return normalized <= 0.03928 ? normalized / 12.92 : ((normalized + 0.055) / 1.055) ** 2.4;
  };
  return (0.2126 * channel(color.r)) + (0.7152 * channel(color.g)) + (0.0722 * channel(color.b));
}

function getCreativeContrastRatio(a, b) {
  const l1 = getCreativeRelativeLuminance(a);
  const l2 = getCreativeRelativeLuminance(b);
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

function inferCreativeElementBackgroundColor(element) {
  const doc = creativeSceneDoc || createSceneDocument();
  const target = getCreativeElementBounds(element);
  const centerX = target.left + (target.width / 2);
  const centerY = target.top + (target.height / 2);
  const below = (Array.isArray(doc.elements) ? doc.elements : [])
    .filter((candidate) => candidate && candidate.id !== element.id && candidate.visible !== false && Number(candidate.opacity ?? 1) > 0.001)
    .filter((candidate) => Number(candidate.zIndex || 0) < Number(element.zIndex || 0))
    .sort((a, b) => Number(b.zIndex || 0) - Number(a.zIndex || 0));
  for (const candidate of below) {
    const bounds = getCreativeElementBounds(candidate);
    if (centerX < bounds.left || centerX > bounds.right || centerY < bounds.top || centerY > bounds.bottom) continue;
    const color = parseCreativeHexColor(candidate.meta?.fill || candidate.meta?.color || candidate.meta?.background || candidate.meta?.backgroundColor);
    if (color) return color;
  }
  return parseCreativeHexColor(doc.background) || parseCreativeHexColor('#ffffff');
}

function getCreativeContrastDetails() {
  const elements = Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [];
  return elements
    .filter((element) => element?.type === 'text' && element.visible !== false && Number(element.opacity ?? 1) > 0.001)
    .map((element) => {
      const foreground = parseCreativeHexColor(element.meta?.color || element.meta?.fill || '#000000');
      const background = inferCreativeElementBackgroundColor(element);
      if (!foreground || !background) {
        return {
          id: element.id,
          text: String(element.meta?.content || ''),
          foreground: foreground?.raw || String(element.meta?.color || element.meta?.fill || ''),
          background: background?.raw || '',
          ratio: null,
          passesAA: null,
          warning: 'Could not determine simple solid foreground/background contrast.',
        };
      }
      const ratio = getCreativeContrastRatio(foreground, background);
      const fontSize = Number(element.meta?.fontSize) || 24;
      const fontWeight = Number(element.meta?.fontWeight) || 400;
      const largeText = fontSize >= 24 || (fontSize >= 18.66 && fontWeight >= 700);
      const threshold = largeText ? 3 : 4.5;
      return {
        id: element.id,
        text: String(element.meta?.content || ''),
        foreground: foreground.raw,
        background: background.raw,
        ratio: Number(ratio.toFixed(2)),
        threshold,
        passesAA: ratio >= threshold,
        largeText,
      };
    });
}

function detectCreativeEmptyRegions(options = {}) {
  const doc = creativeSceneDoc || createSceneDocument();
  const width = Math.max(1, Number(doc.width) || 1080);
  const height = Math.max(1, Number(doc.height) || 1080);
  const cols = Math.max(4, Math.min(16, Number(options.cols) || 6));
  const rows = Math.max(4, Math.min(16, Number(options.rows) || 8));
  const minAreaRatio = Math.max(0, Math.min(1, Number(options.minAreaRatio) || 0.06));
  const elements = (Array.isArray(doc.elements) ? doc.elements : [])
    .filter((element) => element && element.visible !== false && Number(element.opacity ?? 1) > 0.02)
    .filter((element) => !['background'].includes(String(element.meta?.role || '').toLowerCase()));
  const emptyCells = [];
  for (let row = 0; row < rows; row += 1) {
    for (let col = 0; col < cols; col += 1) {
      const bounds = {
        left: (col / cols) * width,
        top: (row / rows) * height,
        right: ((col + 1) / cols) * width,
        bottom: ((row + 1) / rows) * height,
      };
      const occupied = elements.some((element) => {
        const eb = getCreativeElementBounds(element);
        const overlap = Math.max(0, Math.min(bounds.right, eb.right) - Math.max(bounds.left, eb.left))
          * Math.max(0, Math.min(bounds.bottom, eb.bottom) - Math.max(bounds.top, eb.top));
        return overlap > ((bounds.right - bounds.left) * (bounds.bottom - bounds.top) * 0.08);
      });
      if (!occupied) emptyCells.push({ row, col, bounds });
    }
  }
  const regions = emptyCells
    .map((cell) => ({
      grid: { row: cell.row, col: cell.col },
      bounds: {
        left: Math.round(cell.bounds.left),
        top: Math.round(cell.bounds.top),
        right: Math.round(cell.bounds.right),
        bottom: Math.round(cell.bounds.bottom),
        width: Math.round(cell.bounds.right - cell.bounds.left),
        height: Math.round(cell.bounds.bottom - cell.bounds.top),
      },
      areaRatio: Number((((cell.bounds.right - cell.bounds.left) * (cell.bounds.bottom - cell.bounds.top)) / (width * height)).toFixed(3)),
    }))
    .filter((region) => region.areaRatio >= minAreaRatio);
  return {
    grid: { rows, cols },
    emptyCellCount: emptyCells.length,
    emptyRatio: Number((emptyCells.length / Math.max(1, rows * cols)).toFixed(3)),
    regions: regions.slice(0, 40),
  };
}

function checkCreativeKeyframes() {
  const durationMs = Math.max(1000, Number(creativeSceneDoc?.durationMs) || 12000);
  const elements = Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [];
  const details = elements.map((element) => {
    const keyframes = Array.isArray(element.meta?.keyframes) ? element.meta.keyframes : [];
    const sorted = keyframes.slice().sort((a, b) => (Number(a?.atMs) || 0) - (Number(b?.atMs) || 0));
    const warnings = [];
    const times = sorted.map((keyframe) => Number(keyframe?.atMs)).filter((value) => Number.isFinite(value));
    if (times.some((time) => time < 0 || time > durationMs)) warnings.push('keyframe_outside_scene_duration');
    if (new Set(times).size !== times.length) warnings.push('duplicate_keyframe_times');
    if (keyframes.length === 1) warnings.push('single_keyframe_has_no_motion');
    if (keyframes.length >= 2) {
      const first = sorted[0] || {};
      const last = sorted[sorted.length - 1] || {};
      const motionKeys = ['x', 'y', 'width', 'height', 'rotation', 'opacity'];
      const changed = motionKeys.some((key) => JSON.stringify(first[key]) !== JSON.stringify(last[key]));
      if (!changed) warnings.push('keyframes_do_not_change_visible_properties');
    }
    return {
      id: element.id,
      type: element.type,
      label: element.meta?.content || element.meta?.iconName || element.meta?.source || element.type,
      keyframeCount: keyframes.length,
      keyframeTimes: times,
      warnings,
    };
  });
  return {
    durationMs,
    animatedCount: details.filter((entry) => entry.keyframeCount >= 2).length,
    issueCount: details.reduce((sum, entry) => sum + entry.warnings.length, 0),
    elements: details,
  };
}

function checkCreativeCaptionTiming() {
  const durationMs = Math.max(1000, Number(creativeSceneDoc?.durationMs) || 12000);
  const captionElements = getCreativeElementInventory({ includeHidden: false })
    .filter((element) => element.type === 'text')
    .map((element) => ({
      id: element.id,
      text: element.text,
      startMs: Math.max(0, Number(element.timing?.startMs) || 0),
      endMs: Math.min(durationMs, Math.max(Number(element.timing?.endMs) || durationMs, Number(element.timing?.startMs) || 0)),
      durationMs: Math.max(0, Number(element.timing?.durationMs) || durationMs),
    }))
    .sort((a, b) => a.startMs - b.startMs);
  const issues = [];
  captionElements.forEach((caption, index) => {
    if (caption.durationMs < 700) issues.push({ code: 'caption_too_short', id: caption.id, durationMs: caption.durationMs });
    if (caption.text.length > 90 && caption.durationMs < 1800) issues.push({ code: 'dense_caption_timing', id: caption.id, chars: caption.text.length, durationMs: caption.durationMs });
    const next = captionElements[index + 1];
    if (next && caption.endMs > next.startMs) issues.push({ code: 'caption_overlap', ids: [caption.id, next.id], overlapMs: caption.endMs - next.startMs });
  });
  return {
    durationMs,
    captionCount: captionElements.length,
    captions: captionElements,
    issues,
    ok: issues.length === 0,
  };
}

function checkCreativeAudioSync() {
  const durationMs = Math.max(1000, Number(creativeSceneDoc?.durationMs) || 12000);
  const audioTrack = getCreativeAudioTrackConfig();
  const hasAudio = hasCreativeAudioTrack();
  const issues = [];
  if (!hasAudio) issues.push({ code: 'no_audio_track', severity: 'info', message: 'No audio track is attached.' });
  const audioStart = Math.max(0, Number(audioTrack.startMs) || 0);
  const audioDuration = Math.max(0, Number(audioTrack.durationMs) || 0);
  const audioEnd = audioDuration ? audioStart + audioDuration : 0;
  if (hasAudio && audioEnd && audioEnd < durationMs - 300) issues.push({ code: 'audio_ends_before_scene', severity: 'warn', audioEndMs: audioEnd, durationMs });
  if (hasAudio && audioStart > 300) issues.push({ code: 'audio_starts_late', severity: 'warn', audioStartMs: audioStart });
  if (hasAudio && audioTrack.muted) issues.push({ code: 'audio_muted', severity: 'warn' });
  const captionTiming = checkCreativeCaptionTiming();
  if (hasAudio && captionTiming.captionCount && !audioDuration) issues.push({ code: 'caption_audio_duration_unknown', severity: 'info' });
  return {
    ok: !issues.some((issue) => issue.severity === 'warn' || issue.severity === 'error'),
    durationMs,
    hasAudio,
    audioTrack,
    audioWindow: hasAudio ? { startMs: audioStart, endMs: audioEnd || null, durationMs: audioDuration || null } : null,
    captionSummary: { captionCount: captionTiming.captionCount, issueCount: captionTiming.issues.length },
    issues,
  };
}

function buildCreativeQualityReport(options = {}) {
  const mode = normalizeCreativeMode(window.currentCreativeMode);
  const doc = creativeSceneDoc || createSceneDocument();
  const durationMs = Math.max(1000, Number(doc.durationMs) || 12000);
  const sampleTimes = mode === 'video'
    ? (Array.isArray(options.sampleTimesMs) && options.sampleTimesMs.length
        ? options.sampleTimesMs
        : [0, Math.round(durationMs / 2), Math.max(0, durationMs - 250)])
        .map((value) => Math.max(0, Math.min(durationMs, Number(value) || 0)))
        .slice(0, 12)
    : [0];
  const validation = validateCreativeSceneLayout(doc, { mode });
  const inventory = getCreativeElementInventory({ includeHidden: options.includeHidden !== false });
  const keyframes = mode === 'video' ? checkCreativeKeyframes() : null;
  const captions = mode === 'video' ? checkCreativeCaptionTiming() : null;
  const audioSync = mode === 'video' ? checkCreativeAudioSync() : null;
  const traces = sampleTimes.map((atMs) => getCreativeFrameTraceAt(atMs));
  const diffs = traces.slice(1).map((trace, index) => ({
    leftAtMs: traces[index].atMs,
    rightAtMs: trace.atMs,
    changed: diffCreativeFrameTraces(traces[index], trace),
  }));
  const issues = [];
  (validation.issues || []).forEach((issue) => {
    issues.push({
      severity: issue.severity || 'warn',
      code: issue.code || 'layout_issue',
      message: issue.message || issue.code || 'Layout issue',
      elementIds: issue.elementIds || [],
      source: 'layout',
    });
  });
  if (mode === 'video' && keyframes) {
    if (keyframes.animatedCount < Math.min(3, Math.max(1, inventory.length))) {
      issues.push({ severity: 'warn', code: 'weak_motion_progression', message: 'Few layers have meaningful keyframed motion.', source: 'timeline' });
    }
    keyframes.elements.forEach((entry) => {
      entry.warnings.forEach((warning) => {
        issues.push({ severity: 'warn', code: warning, message: `${entry.label} has ${warning.replace(/_/g, ' ')}.`, elementIds: [entry.id], source: 'keyframes' });
      });
    });
  }
  if (mode === 'video' && captions) {
    captions.issues.forEach((issue) => {
      issues.push({ severity: 'warn', code: issue.code, message: `Caption timing issue: ${issue.code.replace(/_/g, ' ')}.`, elementIds: issue.id ? [issue.id] : (issue.ids || []), source: 'captions' });
    });
  }
  if (mode === 'video' && audioSync) {
    audioSync.issues.forEach((issue) => {
      if (issue.severity === 'info' && issue.code === 'no_audio_track') return;
      issues.push({ severity: issue.severity || 'warn', code: issue.code, message: issue.message || `Audio issue: ${issue.code.replace(/_/g, ' ')}.`, source: 'audio' });
    });
  }
  if (mode === 'video') {
    traces.forEach((trace) => {
      if (trace.activeCount === 0) {
        issues.push({ severity: 'error', code: 'blank_frame', message: `No active layers at ${formatCreativeTimelineTime(trace.atMs)}.`, source: 'frames' });
      }
    });
    diffs.forEach((diff) => {
      if (!diff.changed.length) {
        issues.push({ severity: 'warn', code: 'static_frame_span', message: `No scene graph changes between ${formatCreativeTimelineTime(diff.leftAtMs)} and ${formatCreativeTimelineTime(diff.rightAtMs)}.`, source: 'frames' });
      }
    });
  }
  const assetUsage = {
    imageCount: inventory.filter((entry) => entry.type === 'image').length,
    videoCount: inventory.filter((entry) => entry.type === 'video').length,
    iconCount: inventory.filter((entry) => entry.type === 'icon').length,
    lottieCount: inventory.filter((entry) => entry.type === 'lottie').length,
    motionTemplateCount: Array.isArray(doc.motionTemplates) ? doc.motionTemplates.length : 0,
    indexedAssets: Array.isArray(creativeAssetsState?.indexedAssets) ? creativeAssetsState.indexedAssets.length : 0,
  };
  if (mode === 'video' && assetUsage.imageCount + assetUsage.videoCount + assetUsage.iconCount + assetUsage.lottieCount + assetUsage.motionTemplateCount < 2) {
    issues.push({ severity: 'warn', code: 'thin_visual_system', message: 'Video has too few media/icon/template anchors to feel designed.', source: 'assets' });
  }
  const errorCount = issues.filter((issue) => issue.severity === 'error').length;
  const warnCount = issues.filter((issue) => issue.severity === 'warn').length;
  const score = Math.max(0, Math.min(100, 100 - (errorCount * 30) - (warnCount * 8)));
  return {
    ok: errorCount === 0,
    ship: errorCount === 0 && warnCount <= 2,
    score,
    mode,
    sceneHash: hashCreativeObject(doc),
    scene: summarizeCreativeSceneForCommand(),
    sampleTimesMs: sampleTimes,
    issueSummary: { errors: errorCount, warnings: warnCount, info: issues.filter((issue) => issue.severity === 'info').length },
    issues,
    assetUsage,
    validation,
    keyframes,
    captions,
    audioSync,
    traces,
    diffs,
    recommendation: errorCount
      ? 'Fix error-level frame/layout issues before export.'
      : (warnCount > 2 ? 'Improve warnings before final export for a more polished video.' : 'Ready for export after visual snapshot review.'),
  };
}

function getCreativeCommandSelectedElement() {
  const selected = getSelectedCreativeElement();
  return selected ? JSON.parse(JSON.stringify(selected)) : null;
}

function sendCreativeCommandResult(sourceMessage, payload = {}) {
  wsSend({
    type: 'creative_command_result',
    commandId: String(sourceMessage?.commandId || ''),
    sessionId: String(sourceMessage?.sessionId || window.activeChatSessionId || window.agentSessionId || ''),
    success: payload.success === true,
    error: payload.error || '',
    data: payload.data || null,
    sceneSummary: payload.sceneSummary || summarizeCreativeSceneForCommand(),
    selectedElement: payload.selectedElement === undefined ? getCreativeCommandSelectedElement() : payload.selectedElement,
    snapshot: payload.snapshot || null,
    snapshots: Array.isArray(payload.snapshots) ? payload.snapshots : [],
    timestamp: Date.now(),
  });
}

function isCreativeCommandForActiveSession(message, activeSessionId = window.activeChatSessionId || window.agentSessionId || '') {
  const sid = String(message?.sessionId || '').trim();
  const activeSid = String(activeSessionId || '').trim();
  return !!sid && !!activeSid && sid === activeSid;
}

async function ensureCreativeCommandSessionActive(message, options = {}) {
  const sid = String(message?.sessionId || '').trim();
  if (!sid) return false;
  const previousActiveSessionId = String(options.previousActiveSessionId || window.activeChatSessionId || '').trim();
  if (isCreativeCommandForActiveSession(message)) {
    const activeMode = normalizeCreativeMode(message?.creativeMode);
    if (activeMode && normalizeCreativeMode(window.currentCreativeMode) !== activeMode) {
      applySessionCreativeMode(sid, activeMode, { resetScene: message?.resetScene === true });
    }
    return true;
  }

  let sess = window.chatSessions.find((session) => session.id === sid);
  if (!sess) {
    sess = {
      id: sid,
      title: 'Telegram creative session',
      history: [],
      processLog: [],
      creativeMode: normalizeCreativeMode(message?.creativeMode),
      canvasProjectRoot: null,
      canvasProjectLabel: null,
      canvasProjectLink: null,
      creativeSceneDoc: null,
      creativeSelectedId: null,
      creativeTimelineMs: 0,
      creativeHistoryPast: [],
      creativeHistoryFuture: [],
      creativeHtmlMotionClip: null,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      source: 'telegram',
      automated: true,
      unread: true,
      _needsServerLoad: true,
    };
    window.chatSessions.push(sess);
  }

  const background = previousActiveSessionId && previousActiveSessionId !== sid;
  const previousSuppress = window.__pmSuppressCreativeAutoOpen;
  if (background) window.__pmSuppressCreativeAutoOpen = true;
  window.activeChatSessionId = sid;
  setAgentSessionId(sid);
  if (sess._needsServerLoad) await _loadSessionFromServer(sid);
  const mode = normalizeCreativeMode(message?.creativeMode || sess.creativeMode);
  if (mode) applySessionCreativeMode(sid, mode, { resetScene: message?.resetScene === true, persist: true });
  if (background) {
    window.activeChatSessionId = previousActiveSessionId;
    setAgentSessionId(previousActiveSessionId);
    window.__pmSuppressCreativeAutoOpen = previousSuppress;
    return true;
  }
  window.__pmSuppressCreativeAutoOpen = previousSuppress;
  syncActiveChat();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (typeof window.renderChatMessages === 'function') window.renderChatMessages();
  if (typeof window.setMode === 'function') window.setMode('chat');
  return isCreativeCommandForActiveSession(message);
}

function getCreativeCommandTargetIds(payload = {}) {
  const ids = Array.isArray(payload.ids)
    ? payload.ids.map((id) => String(id || '').trim()).filter(Boolean)
    : [];
  if (!ids.length && payload.id) ids.push(String(payload.id || '').trim());
  if (!ids.length && creativeSelectedId) ids.push(creativeSelectedId);
  const known = new Set((creativeSceneDoc?.elements || []).map((element) => element.id));
  return [...new Set(ids)].filter((id) => known.has(id));
}

function getCreativeElementsBounds(elements = []) {
  const valid = elements.filter(Boolean);
  if (!valid.length) return null;
  const left = Math.min(...valid.map((element) => Number(element.x) || 0));
  const top = Math.min(...valid.map((element) => Number(element.y) || 0));
  const right = Math.max(...valid.map((element) => (Number(element.x) || 0) + (Number(element.width) || 0)));
  const bottom = Math.max(...valid.map((element) => (Number(element.y) || 0) + (Number(element.height) || 0)));
  return { left, top, right, bottom, width: right - left, height: bottom - top, centerX: left + ((right - left) / 2), centerY: top + ((bottom - top) / 2) };
}

function commitCreativeCommandDoc(nextDoc, options = {}) {
  setCreativeSceneDoc(createSceneDocument(nextDoc), { render: false, recordHistory: true });
  if (options.selectedId !== undefined) setCreativeSelection(options.selectedId, { render: false });
  renderCreativeWorkspace();
  persistActiveChat();
}

function isProbablyDarkColor(value) {
  const raw = String(value || '').trim();
  const hex = raw.match(/^#?([0-9a-f]{6})$/i)?.[1];
  if (!hex) return false;
  const r = parseInt(hex.slice(0, 2), 16);
  const g = parseInt(hex.slice(2, 4), 16);
  const b = parseInt(hex.slice(4, 6), 16);
  return ((0.2126 * r) + (0.7152 * g) + (0.0722 * b)) < 115;
}

function normalizeCreativeCommandPatch(payload = {}) {
  const patch = payload.patch && typeof payload.patch === 'object' ? { ...payload.patch } : {};
  const props = payload.props && typeof payload.props === 'object' ? payload.props : {};
  const style = payload.style && typeof payload.style === 'object' ? payload.style : {};
  const meta = payload.meta && typeof payload.meta === 'object' ? payload.meta : {};
  const directTopLevelKeys = new Set(['x', 'y', 'width', 'height', 'rotation', 'opacity', 'zIndex', 'locked', 'visible']);
  const metaAliasKeys = new Set([
    'text', 'content', 'fontSize', 'fontWeight', 'fontFamily', 'fontStyle', 'lineHeight', 'letterSpacing',
    'textAlign', 'align', 'fill', 'color', 'stroke', 'strokeWidth', 'radius', 'shadow', 'blendMode',
    'source', 'fit', 'position', 'iconName', 'background', 'backgroundColor',
  ]);
  Object.assign(patch, props);
  const applyMetaValue = (key, value) => {
    const normalizedKey = key === 'text' ? 'content'
      : key === 'align' ? 'textAlign'
      : key;
    patch[`meta.${normalizedKey}`] = value;
  };
  Object.entries(style).forEach(([key, value]) => {
    if (directTopLevelKeys.has(key)) patch[key] = value;
    else applyMetaValue(key, value);
  });
  Object.entries(meta).forEach(([key, value]) => {
    applyMetaValue(key, value);
  });
  Object.entries(payload || {}).forEach(([key, value]) => {
    if (['id', 'patch', 'props', 'style', 'meta'].includes(key)) return;
    if (directTopLevelKeys.has(key)) patch[key] = value;
    else if (metaAliasKeys.has(key)) applyMetaValue(key, value);
  });
  return patch;
}

function normalizeCreativeCommandOps(payload = {}) {
  const rawOps = Array.isArray(payload.ops)
    ? payload.ops
    : (Array.isArray(payload.operations) ? payload.operations : []);
  const canvasPatch = {};
  const ops = [];
  rawOps.forEach((rawOp) => {
    if (!rawOp || typeof rawOp !== 'object') return;
    const rawKind = String(rawOp.op || rawOp.action || rawOp.type || '').trim();
    const kind = rawKind.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`).replace(/[\s-]+/g, '_').toLowerCase();
    if (kind === 'set_canvas' || kind === 'setcanvas' || kind === 'canvas') {
      ['width', 'height', 'durationMs', 'frameRate'].forEach((key) => {
        if (Number.isFinite(Number(rawOp[key]))) canvasPatch[key] = Number(rawOp[key]);
      });
      if (typeof rawOp.background === 'string' && rawOp.background.trim()) canvasPatch.background = rawOp.background.trim();
      return;
    }
    if (kind === 'update_element' || kind === 'updateelement' || kind === 'set') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      const patch = normalizeCreativeCommandPatch(rawOp);
      ops.push({ op: 'set', id, patch });
      return;
    }
    if (kind === 'add_element' || kind === 'addelement' || kind === 'add') {
      const nestedElement = rawOp.element && typeof rawOp.element === 'object' && !Array.isArray(rawOp.element)
        ? rawOp.element
        : null;
      const source = nestedElement
        ? { ...rawOp, ...nestedElement, element: undefined }
        : rawOp;
      const elementType = String(source.elementType || source.kind || source.nodeType || source.layerType || '').trim()
        || String(nestedElement?.type || '').trim()
        || (kind === 'add' ? String(rawOp.type || '').trim() : '');
      ops.push({ ...source, op: 'add', type: elementType || String(source.type || '').trim() || 'shape' });
      return;
    }
    if (kind === 'delete_element' || kind === 'deleteelement' || kind === 'delete' || kind === 'remove') {
      ops.push({ op: 'delete', id: rawOp.id || rawOp.elementId });
      return;
    }
    if (kind === 'move_element' || kind === 'moveelement' || kind === 'move') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({ op: 'move', id, patch: { x: rawOp.x ?? rawOp.patch?.x, y: rawOp.y ?? rawOp.patch?.y } });
      return;
    }
    if (kind === 'resize_element' || kind === 'resizeelement' || kind === 'resize') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({ op: 'resize', id, patch: { width: rawOp.width ?? rawOp.patch?.width, height: rawOp.height ?? rawOp.patch?.height } });
      return;
    }
    if (kind === 'set_keyframes' || kind === 'setkeyframes') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({ op: 'set-keyframes', id, patch: { keyframes: rawOp.keyframes || rawOp.patch?.keyframes || [] } });
      return;
    }
    if (kind === 'add_keyframe' || kind === 'addkeyframe') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({ op: 'add-keyframe', id, patch: rawOp.patch || rawOp.keyframe || rawOp });
      return;
    }
    if (kind === 'delete_keyframe' || kind === 'deletekeyframe') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({ op: 'delete-keyframe', id, keyframeId: rawOp.keyframeId || rawOp.idKeyframe || rawOp.patch?.id });
      return;
    }
    if (kind === 'add_animation_preset' || kind === 'addanimationpreset' || kind === 'apply_animation') {
      const id = String(rawOp.id || rawOp.elementId || '').trim();
      if (!id) return;
      ops.push({
        op: 'add-animation-preset',
        id,
        preset: rawOp.preset || rawOp.presetId || rawOp.animation,
        startMs: rawOp.startMs ?? rawOp.atMs ?? rawOp.patch?.startMs,
        durationMs: rawOp.durationMs ?? rawOp.patch?.durationMs,
      });
      return;
    }
    ops.push(rawOp);
  });
  return { ops, canvasPatch };
}

function applyCreativeArrangeCommand(payload = {}) {
  const action = String(payload.action || '').trim().toLowerCase();
  const ids = getCreativeCommandTargetIds(payload);
  if (!action) throw new Error('arrange requires action.');
  if (!ids.length) throw new Error('arrange needs at least one target element or a selected element.');
  const idSet = new Set(ids);
  const elements = creativeSceneDoc.elements || [];
  const selectedElements = elements.filter((element) => idSet.has(element.id));
  const selectedBounds = getCreativeElementsBounds(selectedElements);
  const docBounds = { left: 0, top: 0, right: creativeSceneDoc.width, bottom: creativeSceneDoc.height, width: creativeSceneDoc.width, height: creativeSceneDoc.height, centerX: creativeSceneDoc.width / 2, centerY: creativeSceneDoc.height / 2 };
  const targetBounds = String(payload.target || 'canvas').toLowerCase() === 'selection' && selectedBounds ? selectedBounds : docBounds;
  let nextElements = elements.map((element) => ({ ...element, meta: JSON.parse(JSON.stringify(element.meta || {})) }));
  let selectedId = creativeSelectedId;

  if (action === 'delete') {
    nextElements = nextElements.filter((element) => !idSet.has(element.id));
    selectedId = nextElements[nextElements.length - 1]?.id || null;
  } else if (action === 'lock' || action === 'unlock' || action === 'show' || action === 'hide') {
    nextElements = nextElements.map((element) => idSet.has(element.id)
      ? { ...element, locked: action === 'lock' ? true : action === 'unlock' ? false : element.locked, visible: action === 'show' ? true : action === 'hide' ? false : element.visible }
      : element);
  } else if (action === 'duplicate') {
    const offsetX = Number.isFinite(Number(payload.offsetX)) ? Number(payload.offsetX) : 24;
    const offsetY = Number.isFinite(Number(payload.offsetY)) ? Number(payload.offsetY) : 24;
    const maxZ = nextElements.reduce((max, element) => Math.max(max, Number(element.zIndex) || 0), 0);
    const clones = selectedElements.map((element, index) => ({
      ...JSON.parse(JSON.stringify(element)),
      id: createCreativeLocalId(element.type || 'el'),
      x: (Number(element.x) || 0) + offsetX,
      y: (Number(element.y) || 0) + offsetY,
      zIndex: maxZ + index + 1,
    }));
    nextElements = [...nextElements, ...clones];
    selectedId = clones[clones.length - 1]?.id || selectedId;
  } else if (action === 'layer') {
    const layer = String(payload.layer || '').trim().toLowerCase();
    if (!['front', 'back', 'forward', 'backward'].includes(layer)) throw new Error('layer action requires layer front, back, forward, or backward.');
    const sorted = nextElements.slice().sort((a, b) => (Number(a.zIndex) || 0) - (Number(b.zIndex) || 0));
    const moveById = (id, direction) => {
      const index = sorted.findIndex((element) => element.id === id);
      const swapIndex = index + direction;
      if (index < 0 || swapIndex < 0 || swapIndex >= sorted.length) return;
      const tmp = sorted[index];
      sorted[index] = sorted[swapIndex];
      sorted[swapIndex] = tmp;
    };
    if (layer === 'front') {
      ids.forEach((id) => {
        const index = sorted.findIndex((element) => element.id === id);
        if (index >= 0) sorted.push(sorted.splice(index, 1)[0]);
      });
    } else if (layer === 'back') {
      [...ids].reverse().forEach((id) => {
        const index = sorted.findIndex((element) => element.id === id);
        if (index >= 0) sorted.unshift(sorted.splice(index, 1)[0]);
      });
    } else {
      ids.forEach((id) => moveById(id, layer === 'forward' ? 1 : -1));
    }
    nextElements = sorted.map((element, index) => ({ ...element, zIndex: index }));
  } else if (action === 'align' || action === 'center') {
    const align = action === 'center'
      ? (String(payload.axis || 'both').toLowerCase() === 'x' ? 'center' : String(payload.axis || 'both').toLowerCase() === 'y' ? 'middle' : 'both')
      : String(payload.align || '').trim().toLowerCase();
    nextElements = nextElements.map((element) => {
      if (!idSet.has(element.id)) return element;
      const patch = {};
      if (align === 'left') patch.x = targetBounds.left;
      if (align === 'right') patch.x = targetBounds.right - element.width;
      if (align === 'center' || align === 'both') patch.x = targetBounds.centerX - (element.width / 2);
      if (align === 'top') patch.y = targetBounds.top;
      if (align === 'bottom') patch.y = targetBounds.bottom - element.height;
      if (align === 'middle' || align === 'both') patch.y = targetBounds.centerY - (element.height / 2);
      return { ...element, ...patch };
    });
  } else if (action === 'distribute') {
    const axis = String(payload.axis || 'x').toLowerCase() === 'y' ? 'y' : 'x';
    const ordered = selectedElements.slice().sort((a, b) => (axis === 'x' ? a.x - b.x : a.y - b.y));
    if (ordered.length < 3) throw new Error('distribute requires at least three target elements.');
    const first = ordered[0];
    const last = ordered[ordered.length - 1];
    const start = axis === 'x' ? first.x : first.y;
    const end = axis === 'x' ? last.x : last.y;
    const step = (end - start) / Math.max(1, ordered.length - 1);
    const patches = new Map(ordered.map((element, index) => [element.id, start + (step * index)]));
    nextElements = nextElements.map((element) => idSet.has(element.id)
      ? { ...element, [axis]: patches.get(element.id) ?? element[axis] }
      : element);
  } else {
    throw new Error(`Unknown arrange action: ${action}`);
  }

  commitCreativeCommandDoc({ ...creativeSceneDoc, elements: nextElements }, { selectedId });
  return { action, ids, selectedId };
}

function applyCreativeStyleCommand(payload = {}) {
  const ids = getCreativeCommandTargetIds(payload);
  if (!ids.length) throw new Error('apply_style needs at least one target element or a selected element.');
  const style = payload.style && typeof payload.style === 'object' ? payload.style : {};
  const meta = payload.meta && typeof payload.meta === 'object' ? payload.meta : {};
  const directStyleKeys = new Set(['opacity', 'rotation', 'width', 'height', 'x', 'y', 'zIndex', 'locked', 'visible']);
  const directMetaKeys = new Set([
    'color', 'fill', 'fontSize', 'fontWeight', 'fontFamily', 'fontStyle', 'lineHeight', 'letterSpacing',
    'textAlign', 'align', 'stroke', 'strokeWidth', 'radius', 'shadow', 'blendMode', 'background', 'backgroundColor',
  ]);
  Object.entries(payload || {}).forEach(([key, value]) => {
    if (['ids', 'id', 'style', 'meta'].includes(key)) return;
    if (directStyleKeys.has(key)) style[key] = value;
    else if (directMetaKeys.has(key)) meta[key === 'align' ? 'textAlign' : key] = value;
  });
  if (!Object.keys(style).length && !Object.keys(meta).length) throw new Error('apply_style requires style or meta.');
  const ops = ids.map((id) => ({
    op: 'set',
    id,
    patch: {
      ...style,
      ...Object.fromEntries(Object.entries(meta).map(([key, value]) => [`meta.${key}`, value])),
    },
  }));
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, ops);
  commitCreativeCommandDoc(nextDoc, { selectedId: ids[ids.length - 1] || creativeSelectedId });
  return { styledIds: ids, styleKeys: Object.keys(style), metaKeys: Object.keys(meta) };
}

function applyCreativeFitAssetCommand(payload = {}) {
  const id = String(payload.id || creativeSelectedId || '').trim();
  if (!id) throw new Error('fit_asset requires id or selected element.');
  const element = findCreativeElementInDoc(creativeSceneDoc, id);
  if (!element) throw new Error(`Element not found: ${id}`);
  const metaPatch = {};
  if (typeof payload.source === 'string' && payload.source.trim()) metaPatch.source = payload.source.trim();
  if (typeof payload.fit === 'string' && payload.fit.trim()) metaPatch.fit = payload.fit.trim();
  if (typeof payload.position === 'string' && payload.position.trim()) metaPatch.position = payload.position.trim();
  if (Number.isFinite(Number(payload.radius))) metaPatch.radius = Number(payload.radius);
  if (!Object.keys(metaPatch).length) throw new Error('fit_asset requires source, fit, position, or radius.');
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'set',
    id,
    patch: Object.fromEntries(Object.entries(metaPatch).map(([key, value]) => [`meta.${key}`, value])),
  }]);
  commitCreativeCommandDoc(nextDoc, { selectedId: id });
  return { id, meta: metaPatch };
}

function inferCreativeAssetType(source = '', explicitType = '') {
  const requested = String(explicitType || '').trim().toLowerCase();
  if (requested === 'image' || requested === 'video' || requested === 'audio') return requested;
  const ext = String(source || '').split('?')[0].split('#')[0].split('.').pop().toLowerCase();
  if (VIDEO_EXTENSIONS.has(ext)) return 'video';
  if (['mp3', 'wav', 'm4a', 'aac', 'ogg', 'flac'].includes(ext)) return 'audio';
  return 'image';
}

function applyCreativeAddAssetCommand(payload = {}) {
  const source = String(payload.source || payload.path || payload.url || '').trim();
  if (!source) throw new Error('add_asset requires source.');
  const type = inferCreativeAssetType(source, payload.assetType || payload.type);
  if (normalizeCreativeMode(window.currentCreativeMode) === 'video' && creativeHtmlMotionClip) {
    clearCreativeHtmlMotionClip({ render: false, persist: false });
  }
  const meta = payload.meta && typeof payload.meta === 'object' ? { ...payload.meta } : {};
  meta.source = source;
  meta.fit = String(payload.fit || meta.fit || 'cover').trim();
  if (Number.isFinite(Number(payload.radius))) meta.radius = Number(payload.radius);
  if (type === 'video') {
    meta.muted = payload.muted !== false;
    meta.volume = Number.isFinite(Number(payload.volume)) ? Math.max(0, Math.min(1, Number(payload.volume))) : (meta.muted ? 0 : 1);
    meta.trimStartMs = Math.max(0, Number(payload.trimStartMs ?? meta.trimStartMs) || 0);
    if (Number.isFinite(Number(payload.trimEndMs))) meta.trimEndMs = Math.max(0, Number(payload.trimEndMs));
    const explicitStart = payload.startMs ?? payload.timelineStartMs ?? meta.timelineStartMs;
    meta.timelineStartMs = Number.isFinite(Number(explicitStart))
      ? Math.max(0, Number(explicitStart))
      : getCreativeTimelineAppendStartMs();
    if (Number.isFinite(Number(payload.durationMs ?? payload.timelineDurationMs))) {
      meta.timelineDurationMs = Math.max(100, Number(payload.durationMs ?? payload.timelineDurationMs));
    } else if (Number.isFinite(Number(creativeSceneDoc?.durationMs))) {
      meta.timelineDurationMs = Math.max(100, Number(creativeSceneDoc.durationMs));
    }
  } else if (type === 'audio') {
    const explicitStart = payload.startMs ?? payload.timelineStartMs ?? meta.timelineStartMs;
    meta.timelineStartMs = Number.isFinite(Number(explicitStart))
      ? Math.max(0, Number(explicitStart))
      : getCreativeTimelineAppendStartMs();
    if (Number.isFinite(Number(payload.durationMs ?? payload.timelineDurationMs))) {
      meta.timelineDurationMs = Math.max(100, Number(payload.durationMs ?? payload.timelineDurationMs));
    }
    meta.volume = Number.isFinite(Number(payload.volume)) ? Math.max(0, Math.min(1, Number(payload.volume))) : 1;
  }
  const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
    op: 'add',
    type,
    x: Number.isFinite(Number(payload.x)) ? Number(payload.x) : (type === 'video' ? 0 : Math.round(creativeSceneDoc.width * 0.12)),
    y: Number.isFinite(Number(payload.y)) ? Number(payload.y) : (type === 'video' ? 0 : Math.round(creativeSceneDoc.height * 0.12)),
    width: Number.isFinite(Number(payload.width)) ? Number(payload.width) : (type === 'video' ? Math.round(creativeSceneDoc.width) : Math.round(creativeSceneDoc.width * 0.46)),
    height: Number.isFinite(Number(payload.height)) ? Number(payload.height) : (type === 'video' ? Math.round(creativeSceneDoc.height) : Math.round(creativeSceneDoc.height * 0.46)),
    rotation: Number.isFinite(Number(payload.rotation)) ? Number(payload.rotation) : 0,
    opacity: Number.isFinite(Number(payload.opacity)) ? Number(payload.opacity) : 1,
    zIndex: Number.isFinite(Number(payload.zIndex)) ? Number(payload.zIndex) : (creativeSceneDoc.elements || []).length,
    meta,
  }]);
  const added = nextDoc.elements[nextDoc.elements.length - 1] || null;
  commitCreativeCommandDoc(nextDoc, { selectedId: added?.id || creativeSelectedId });
  return { addedId: added?.id || null, type, source };
}

function getCreativeTimelineAppendStartMs() {
  const elements = Array.isArray(creativeSceneDoc?.elements) ? creativeSceneDoc.elements : [];
  const ends = elements
    .filter((element) => ['video', 'audio'].includes(String(element?.type || '').toLowerCase()))
    .map((element) => {
      const meta = element?.meta || {};
      const start = Math.max(0, Number(meta.timelineStartMs ?? meta.startMs ?? element.startMs) || 0);
      const duration = Math.max(0, Number(meta.timelineDurationMs ?? meta.durationMs ?? element.durationMs) || 0);
      return start + duration;
    })
    .filter((value) => Number.isFinite(value) && value > 0);
  return ends.length ? Math.max(...ends) : 0;
}

function buildCreativeTemplateElements(template, payload = {}, mode = normalizeCreativeMode(window.currentCreativeMode)) {
  const isVideo = mode === 'video';
  const fallbackWidth = isVideo ? 1280 : (template === 'thumbnail' ? 1280 : 1080);
  const fallbackHeight = isVideo ? 720 : (template === 'thumbnail' ? 720 : 1080);
  const width = Number.isFinite(Number(payload.width))
    ? Number(payload.width)
    : (Number.isFinite(Number(creativeSceneDoc?.width)) ? Number(creativeSceneDoc.width) : fallbackWidth);
  const height = Number.isFinite(Number(payload.height))
    ? Number(payload.height)
    : (Number.isFinite(Number(creativeSceneDoc?.height)) ? Number(creativeSceneDoc.height) : fallbackHeight);
  const isPortrait = height > width * 1.12;
  const templateDefaults = {
    quote_card: { title: 'A stronger idea starts here.', subtitle: 'Make the message impossible to miss.', cta: 'Read more', accent: '#f97316' },
    thumbnail: { title: 'Big Result, Simple Move', subtitle: 'A polished starter layout ready for editing.', cta: 'Watch now', accent: '#f97316' },
    video_promo: { title: 'Launch Better Work', subtitle: 'Fast visuals, sharp motion, ready to export.', cta: 'Learn more', accent: '#f97316' },
    app_launch: { title: 'Launch your app with motion', subtitle: 'Show the product, the promise, and the CTA in one clean frame.', cta: 'Try it now', accent: '#2563EB' },
    event_flyer: { title: 'The event starts here', subtitle: 'Date, venue, headline, and reason to show up.', cta: 'Reserve your spot', accent: '#E11D48' },
    testimonial: { title: '“This changed the workflow.”', subtitle: 'Real proof, clean hierarchy, and a strong trust moment.', cta: 'See the story', accent: '#38BDF8' },
    carousel: { title: 'Three reasons this works', subtitle: 'Use slides, cards, and progress markers for a swipeable idea.', cta: 'Swipe through', accent: '#7C3AED' },
    tiktok_caption_reel: { title: 'Hook them in one second', subtitle: 'Bold captions, punchy beats, progress, and CTA.', cta: 'Build faster', accent: '#FF4D2D' },
    audiogram: { title: 'Turn audio into attention', subtitle: 'Waveform, cover art, captions, and progress motion.', cta: 'Listen now', accent: '#16D9FF' },
    product_ad: { title: 'Prometheus Creative', subtitle: 'A polished starter layout ready for editing.', cta: 'Shop now', accent: '#16a34a' },
  };
  const defaults = templateDefaults[template] || { title: 'Prometheus Creative', subtitle: 'A polished starter layout ready for editing.', cta: 'Learn more', accent: '#f97316' };
  const background = String(payload.background || (isVideo ? '#101828' : '#f8fafc')).trim();
  const accent = String(payload.accent || defaults.accent).trim();
  const title = String(payload.title || defaults.title).trim();
  const subtitle = String(payload.subtitle || defaults.subtitle).trim();
  const cta = String(payload.cta || defaults.cta).trim();
  const templateDurationMs = isVideo ? Math.max(6000, Number(payload.durationMs) || 9000) : 12000;
  const cardRadius = isVideo ? 28 : 36;
  const z = (index) => index;
  const foreground = isProbablyDarkColor(background) ? '#f8fafc' : '#111827';
  const muted = isProbablyDarkColor(background) ? '#d0d5dd' : '#475467';
  const deco = isPortrait
    ? { x: Math.round(width * 0.62), y: Math.round(height * 0.02), width: Math.round(width * 0.34), height: Math.round(height * 0.34), rotation: 8 }
    : { x: Math.round(width * 0.58), y: -80, width: Math.round(width * 0.42), height: Math.round(height * 0.72), rotation: 8 };
  const titleX = Math.round(width * (isPortrait ? 0.08 : 0.08));
  const titleY = Math.round(height * (isPortrait ? 0.18 : 0.27));
  const titleW = Math.round(width * (isPortrait ? 0.72 : 0.58));
  const subtitleY = Math.round(height * (isPortrait ? 0.39 : 0.53));
  const buttonX = Math.round(width * 0.085);
  const buttonY = Math.round(height * (isPortrait ? 0.62 : 0.72));
  const buttonW = Math.round(width * (isPortrait ? 0.44 : 0.28));
  const buttonH = isVideo ? 58 : 68;
  const baseText = { fontFamily: 'Manrope', color: foreground, lineHeight: 1.05 };
  const elements = [
    { op: 'add', type: 'shape', x: 0, y: 0, width, height, zIndex: z(0), meta: { shape: 'rect', fill: background, radius: 0 } },
    { op: 'add', type: 'shape', ...deco, zIndex: z(1), meta: { shape: 'rect', fill: accent, radius: cardRadius } },
    { op: 'add', type: 'shape', x: Math.round(width * 0.08), y: Math.round(height * 0.12), width: Math.round(width * 0.08), height: Math.round(width * 0.08), zIndex: z(2), meta: { shape: 'circle', fill: accent } },
    { op: 'add', type: 'text', x: titleX, y: titleY, width: titleW, height: isVideo ? 220 : 160, zIndex: z(3), meta: { ...baseText, content: isVideo ? splitCreativeMotionCaptionLines(title, isPortrait ? 22 : 28, 3) : title, fontSize: isVideo ? (isPortrait ? 82 : 66) : 76, fontWeight: 900, lineHeight: isVideo ? 0.96 : 1.05 } },
    { op: 'add', type: 'text', x: Math.round(width * 0.085), y: subtitleY, width: Math.round(width * (isPortrait ? 0.68 : 0.48)), height: isVideo ? 130 : 90, zIndex: z(4), meta: { ...baseText, content: isVideo ? splitCreativeMotionCaptionLines(subtitle, isPortrait ? 34 : 44, 3) : subtitle, fontSize: isVideo ? (isPortrait ? 32 : 25) : 30, fontWeight: 700, lineHeight: 1.16, color: muted } },
    { op: 'add', type: 'shape', x: buttonX, y: buttonY, width: buttonW, height: buttonH, zIndex: z(5), meta: { shape: 'rect', fill: accent, radius: 999 } },
    { op: 'add', type: 'text', x: buttonX + 26, y: buttonY + Math.round(buttonH * 0.24), width: Math.max(120, buttonW - 52), height: 40, zIndex: z(6), meta: { ...baseText, content: cta, fontSize: isVideo ? 20 : 24, fontWeight: 850, color: '#ffffff', textAlign: 'center' } },
  ];
  if (template === 'quote_card') {
    elements.push({ op: 'add', type: 'text', x: Math.round(width * 0.08), y: Math.round(height * 0.08), width: 90, height: 90, zIndex: z(7), meta: { ...baseText, content: '"', fontSize: 120, fontWeight: 900, color: accent } });
  }
  if (template === 'video_promo') {
    const progressY = Math.round(height * 0.92);
    const chipY = Math.round(height * (isPortrait ? 0.52 : 0.64));
    const chipW = Math.round(width * (isPortrait ? 0.24 : 0.17));
    ['MOTION', 'PRESETS', 'EXPORT'].forEach((label, index) => {
      const x = Math.round(width * 0.085) + index * Math.round(chipW * 1.12);
      elements.push({ op: 'add', type: 'shape', x, y: chipY, width: chipW, height: isPortrait ? 58 : 46, zIndex: z(7 + index), meta: { shape: 'rect', fill: index === 1 ? '#111827' : accent, radius: 999, stroke: 'rgba(255,255,255,0.18)', strokeWidth: 1 } });
      elements.push({ op: 'add', type: 'text', x: x + 18, y: chipY + (isPortrait ? 16 : 12), width: chipW - 36, height: 28, zIndex: z(10 + index), meta: { ...baseText, content: label, fontSize: isPortrait ? 20 : 16, fontWeight: 900, color: index === 1 ? foreground : '#ffffff', textAlign: 'center', lineHeight: 1 } });
    });
    elements.push({ op: 'add', type: 'icon', x: Math.round(width * (isPortrait ? 0.78 : 0.77)), y: Math.round(height * (isPortrait ? 0.34 : 0.36)), width: isPortrait ? 118 : 96, height: isPortrait ? 118 : 96, zIndex: z(14), meta: { iconName: 'solar:play-circle-bold-duotone', color: '#ffffff', shadow: '0 18px 52px rgba(0,0,0,0.34)' } });
    elements.push({ op: 'add', type: 'shape', x: Math.round(width * 0.085), y: progressY, width: Math.round(width * 0.82), height: isPortrait ? 14 : 10, opacity: 0.26, zIndex: z(15), meta: { shape: 'rect', fill: '#ffffff', radius: 999 } });
    elements.push({ op: 'add', type: 'shape', x: Math.round(width * 0.085), y: progressY, width: Math.round(width * 0.18), height: isPortrait ? 14 : 10, zIndex: z(16), meta: { shape: 'rect', fill: '#38BDF8', radius: 999, keyframes: [{ id: createCreativeLocalId('kf'), atMs: 0, x: Math.round(width * 0.085), y: progressY, width: Math.round(width * 0.12), height: isPortrait ? 14 : 10, opacity: 1, rotation: 0, ease: 'linear' }, { id: createCreativeLocalId('kf'), atMs: templateDurationMs, x: Math.round(width * 0.085), y: progressY, width: Math.round(width * 0.82), height: isPortrait ? 14 : 10, opacity: 1, rotation: 0, ease: 'linear' }] } });
  }
  if (['app_launch', 'product_ad', 'event_flyer', 'testimonial', 'carousel', 'tiktok_caption_reel', 'audiogram'].includes(template)) {
    const panelX = Math.round(width * (isPortrait ? 0.06 : 0.62));
    const panelY = Math.round(height * (isPortrait ? 0.67 : 0.14));
    const panelW = Math.round(width * (isPortrait ? 0.88 : 0.32));
    const panelH = Math.round(height * (isPortrait ? 0.18 : 0.52));
    const visualX = Math.round(width * (isPortrait ? 0.12 : 0.58));
    const visualY = Math.round(height * (isPortrait ? 0.46 : 0.3));
    const iconName = template === 'audiogram'
      ? 'solar:volume-loud-bold-duotone'
      : template === 'event_flyer'
        ? 'solar:calendar-bold-duotone'
        : template === 'testimonial'
          ? 'solar:chat-round-like-bold-duotone'
          : template === 'app_launch'
            ? 'solar:rocket-2-bold-duotone'
            : 'solar:stars-bold-duotone';
    elements.push(
      { op: 'add', type: 'shape', x: panelX, y: panelY, width: panelW, height: panelH, zIndex: z(18), meta: { shape: 'rect', fill: isProbablyDarkColor(background) ? 'rgba(255,255,255,.08)' : '#ffffff', radius: 30, stroke: 'rgba(255,255,255,.18)', strokeWidth: 1, shadow: '0 26px 80px rgba(0,0,0,.24)' } },
      { op: 'add', type: 'text', x: panelX + 34, y: panelY + 32, width: panelW - 68, height: 90, zIndex: z(19), meta: { ...baseText, content: splitCreativeMotionCaptionLines(subtitle, isPortrait ? 34 : 30, 3), fontSize: isPortrait ? 30 : 22, fontWeight: 800, color: foreground, lineHeight: 1.1 } },
      { op: 'add', type: 'shape', x: panelX + 34, y: panelY + panelH - 78, width: Math.min(panelW - 68, Math.round(width * 0.48)), height: 58, zIndex: z(20), meta: { shape: 'rect', fill: accent, radius: 999 } },
      { op: 'add', type: 'text', x: panelX + 58, y: panelY + panelH - 62, width: Math.min(panelW - 116, Math.round(width * 0.4)), height: 32, zIndex: z(21), meta: { ...baseText, content: cta, fontSize: isPortrait ? 22 : 18, fontWeight: 900, color: '#ffffff', textAlign: 'center', lineHeight: 1 } },
      { op: 'add', type: 'icon', x: visualX, y: visualY, width: isPortrait ? 112 : 96, height: isPortrait ? 112 : 96, zIndex: z(22), meta: { iconName, color: accent, shadow: '0 18px 52px rgba(0,0,0,.32)' } },
    );
    if (template === 'audiogram') {
      const waveY = Math.round(height * (isPortrait ? 0.56 : 0.68));
      for (let i = 0; i < 18; i += 1) {
        const barH = 18 + ((i * 17) % 68);
        elements.push({ op: 'add', type: 'shape', x: Math.round(width * 0.12) + i * Math.round(width * 0.035), y: waveY - Math.round(barH / 2), width: Math.max(6, Math.round(width * 0.012)), height: barH, zIndex: z(30 + i), meta: { shape: 'rect', fill: i % 3 === 0 ? accent : '#ffffff', radius: 999, keyframes: isVideo ? [{ id: createCreativeLocalId('kf'), atMs: 0, x: Math.round(width * 0.12) + i * Math.round(width * 0.035), y: waveY - Math.round(barH / 2), width: Math.max(6, Math.round(width * 0.012)), height: barH * 0.58, opacity: 0.75, rotation: 0, ease: 'sine.inOut' }, { id: createCreativeLocalId('kf'), atMs: Math.round(templateDurationMs / 2), x: Math.round(width * 0.12) + i * Math.round(width * 0.035), y: waveY - Math.round(barH / 2), width: Math.max(6, Math.round(width * 0.012)), height: barH, opacity: 1, rotation: 0, ease: 'sine.inOut' }, { id: createCreativeLocalId('kf'), atMs: templateDurationMs, x: Math.round(width * 0.12) + i * Math.round(width * 0.035), y: waveY - Math.round(barH / 2), width: Math.max(6, Math.round(width * 0.012)), height: barH * 0.68, opacity: 0.82, rotation: 0, ease: 'sine.inOut' }] : [] } });
      }
    }
  }
  return { width, height, background, durationMs: templateDurationMs, elements };
}

function splitCreativeMotionCaptionLines(text = '', maxChars = 24, maxLines = 3) {
  const words = String(text || '').split(/\s+/).filter(Boolean);
  const lines = [];
  let current = '';
  words.forEach((word) => {
    const next = current ? `${current} ${word}` : word;
    if (current && next.length > maxChars) {
      lines.push(current);
      current = word;
    } else {
      current = next;
    }
  });
  if (current) lines.push(current);
  if (lines.length <= maxLines) return lines.join('\n');
  return [...lines.slice(0, maxLines - 1), lines.slice(maxLines - 1).join(' ')].join('\n');
}

function buildMotionVisibilityKeyframes(element, startMs, endMs, durationMs, fromY = 36) {
  const base = { x: element.x, y: element.y, width: element.width, height: element.height, rotation: element.rotation || 0 };
  const safeStart = Math.max(0, Number(startMs) || 0);
  const safeEnd = Math.max(safeStart + 180, Number(endMs) || safeStart + 1200);
  const fade = Math.min(220, Math.max(80, Math.round((safeEnd - safeStart) / 7)));
  return [
    { id: createCreativeLocalId('kf'), atMs: 0, ...base, y: base.y + fromY, opacity: 0, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: safeStart, ...base, y: base.y + fromY, opacity: 0, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: Math.min(safeEnd, safeStart + fade), ...base, opacity: element.opacity ?? 1, ease: 'power2.out' },
    { id: createCreativeLocalId('kf'), atMs: Math.max(safeStart, safeEnd - fade), ...base, opacity: element.opacity ?? 1, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: safeEnd, ...base, y: base.y - Math.round(fromY / 2), opacity: 0, ease: 'power2.in' },
    { id: createCreativeLocalId('kf'), atMs: Math.max(safeEnd, durationMs), ...base, y: base.y - Math.round(fromY / 2), opacity: 0, ease: 'linear' },
  ];
}

function buildCaptionReelV2SceneElementsFromMotionInstance(instance = {}) {
  const input = instance.input || {};
  const width = Math.max(320, Number(input.width) || Number(creativeSceneDoc?.width) || 1080);
  const height = Math.max(320, Number(input.height) || Number(creativeSceneDoc?.height) || 1920);
  const durationMs = Math.max(4000, Number(input.durationMs || instance.durationMs) || 9000);
  const brand = input.brand || {};
  const colors = brand.colors || {};
  const fonts = brand.fonts || {};
  const presetKey = String(instance.presetId || input.presetId || input.style?.preset || '').toLowerCase();
  const isBoldTikTok = presetKey.includes('bold') || presetKey.includes('tiktok');
  const background = isBoldTikTok ? '#050608' : (colors.background || '#07111F');
  const panel = isBoldTikTok ? '#111827' : '#0F172A';
  const textColor = colors.text || '#F8FAFC';
  const accent = isBoldTikTok ? '#FF4D2D' : (colors.accent || '#F7C948');
  const accent2 = isBoldTikTok ? '#16D9FF' : (colors.secondary || '#38BDF8');
  const accent3 = isBoldTikTok ? '#FFE45E' : '#8B5CF6';
  const headingFont = isBoldTikTok ? 'Bebas Neue' : (fonts.heading && fonts.heading !== 'Inter' ? fonts.heading : 'Sora');
  const bodyFont = isBoldTikTok ? 'Manrope' : (fonts.body && fonts.body !== 'Inter' ? fonts.body : 'Inter');
  const safeX = Math.round(width * 0.06);
  const prefix = `motion_${String(instance.id || createCreativeLocalId('motion')).replace(/[^a-z0-9_-]/gi, '_')}`;
  const segments = Array.isArray(input.captions?.segments) && input.captions.segments.length
    ? input.captions.segments
    : [{ startMs: 900, endMs: durationMs - 1800, text: input.text?.subtitle || input.text?.body || 'Reusable motion templates powered by Remotion.' }];
  const supportCopy = input.text?.body || input.text?.subtitle || 'Templates, captions, presets, and direct frame review become one reusable motion workflow.';
  const cta = input.text?.cta || 'Build faster with Prometheus';
  const ops = [];
  const add = (element) => {
    ops.push({
      op: 'add',
      ...element,
      id: element.id || createCreativeLocalId('motionel'),
      meta: {
        ...(element.meta || {}),
        motionTemplateId: instance.id || null,
        generatedBy: 'caption-reel-v2',
      },
    });
  };
  const vis = (element, start, end, fromY = 36) => buildMotionVisibilityKeyframes(element, start, end, durationMs, fromY);
  add({ id: `${prefix}_bg`, type: 'shape', x: 0, y: 0, width, height, zIndex: 0, meta: { shape: 'rect', fill: background, radius: 0 } });
  add({
    id: `${prefix}_grain_overlay`,
    type: 'shape',
    x: Math.round(width * -0.04),
    y: Math.round(height * 0.02),
    width: Math.round(width * 1.1),
    height: Math.round(height * 0.96),
    opacity: 0.12,
    zIndex: 1,
    meta: { shape: 'rect', fill: 'rgba(255,255,255,0.045)', radius: 48 },
  });
  add({
    id: `${prefix}_accent_slab`,
    type: 'shape',
    x: Math.round(width * 0.68),
    y: Math.round(height * 0.065),
    width: Math.round(width * 0.25),
    height: Math.round(height * 0.28),
    rotation: 9,
    opacity: 0.78,
    zIndex: 2,
    meta: {
      shape: 'rect',
      fill: accent,
      radius: 36,
      shadow: '0 26px 80px rgba(255,77,45,0.34)',
      keyframes: [
        { id: createCreativeLocalId('kf'), atMs: 0, x: Math.round(width * 0.78), y: Math.round(height * 0.03), width: Math.round(width * 0.2), height: Math.round(height * 0.23), rotation: 18, opacity: 0, ease: 'linear' },
        { id: createCreativeLocalId('kf'), atMs: 360, x: Math.round(width * 0.68), y: Math.round(height * 0.065), width: Math.round(width * 0.25), height: Math.round(height * 0.28), rotation: 9, opacity: 0.78, ease: 'back.out(2)' },
        { id: createCreativeLocalId('kf'), atMs: durationMs, x: Math.round(width * 0.62), y: Math.round(height * 0.1), width: Math.round(width * 0.28), height: Math.round(height * 0.3), rotation: 0, opacity: 0.44, ease: 'linear' },
      ],
    },
  });
  const eyebrow = { x: safeX, y: Math.round(height * 0.07), width: Math.round(width * 0.66), height: 46, opacity: 1, rotation: 0 };
  add({ id: `${prefix}_eyebrow`, type: 'text', ...eyebrow, zIndex: 5, meta: { content: 'PROMETHEUS // MOTION SYSTEM', fontSize: 28, fontWeight: 950, fontFamily: bodyFont, color: accent3, lineHeight: 1.05, letterSpacing: 0, keyframes: vis(eyebrow, 0, durationMs - 350, 24) } });
  const title = { x: safeX, y: Math.round(height * 0.135), width: Math.round(width * 0.68), height: Math.round(height * 0.17), opacity: 1, rotation: 0 };
  add({ id: `${prefix}_title`, type: 'text', ...title, zIndex: 6, meta: { content: splitCreativeMotionCaptionLines(input.text?.title || 'Prometheus is getting motion templates', 23, 3), fontSize: 92, fontWeight: 950, fontFamily: headingFont, color: textColor, lineHeight: 0.95, letterSpacing: 0, textAlign: 'left', shadow: '0 22px 80px rgba(0,0,0,0.5)', keyframes: vis(title, 90, Math.min(durationMs, 4700), 48) } });

  const chipLabels = ['TEMPLATES', 'CAPTIONS', 'QA GATES'];
  chipLabels.forEach((label, index) => {
    const chip = {
      x: safeX + Math.round(index * width * 0.255),
      y: Math.round(height * 0.335),
      width: Math.round(width * (index === 2 ? 0.22 : 0.2)),
      height: 58,
      opacity: 1,
      rotation: index === 1 ? -1 : 0,
    };
    add({ id: `${prefix}_chip_${index + 1}_bg`, type: 'shape', ...chip, zIndex: 4, meta: { shape: 'rect', fill: index === 1 ? accent2 : panel, radius: 999, stroke: 'rgba(255,255,255,0.18)', strokeWidth: 1, keyframes: vis(chip, 480 + index * 110, durationMs - 650, 22) } });
    add({ id: `${prefix}_chip_${index + 1}_text`, type: 'text', x: chip.x + 20, y: chip.y + 14, width: chip.width - 40, height: 32, opacity: 1, rotation: chip.rotation, zIndex: 7, meta: { content: label, fontSize: 22, fontWeight: 950, fontFamily: bodyFont, color: index === 1 ? '#031018' : textColor, textAlign: 'center', lineHeight: 1, keyframes: vis({ ...chip, x: chip.x + 20, y: chip.y + 14, width: chip.width - 40, height: 32 }, 540 + index * 110, durationMs - 650, 18) } });
  });

  const captionY = Math.round(height * 0.44);
  const firstSegment = segments[0] || {};
  const secondSegment = segments[1] || {};
  const splitAt = Math.round(durationMs * 0.52);
  const captionWindows = [
    { segment: firstSegment, start: 650, end: Math.min(splitAt - 220, durationMs - 1500), color: textColor, mark: accent },
    { segment: secondSegment, start: Math.max(splitAt, 1700), end: durationMs - 1250, color: textColor, mark: accent2 },
  ].filter((item) => String(item.segment?.text || '').trim());
  captionWindows.forEach((item, index) => {
    const caption = { x: safeX, y: captionY, width: Math.round(width * 0.84), height: Math.round(height * 0.18), opacity: 1, rotation: 0 };
    add({ id: `${prefix}_caption_${index + 1}`, type: 'text', ...caption, zIndex: 7, meta: { content: splitCreativeMotionCaptionLines(item.segment.text, 26, 3), fontSize: index === 0 ? 64 : 58, fontWeight: 950, fontFamily: bodyFont, color: item.color, lineHeight: 1.04, letterSpacing: 0, textAlign: 'left', shadow: '0 20px 70px rgba(0,0,0,0.46)', keyframes: vis(caption, item.start, item.end, 52) } });
    const mark = { x: safeX, y: captionY + Math.round(height * 0.175) + (index * 28), width: Math.round(width * (index === 0 ? 0.54 : 0.46)), height: 18, opacity: 1, rotation: -1 };
    add({ id: `${prefix}_highlight_${index + 1}`, type: 'shape', ...mark, zIndex: 5, meta: { shape: 'rect', fill: item.mark, radius: 999, shadow: `0 14px 38px ${index === 0 ? 'rgba(255,77,45,0.35)' : 'rgba(22,217,255,0.32)'}`, keyframes: vis(mark, item.start + 120, item.end, 18) } });
  });

  const cardY = Math.round(height * 0.705);
  const card = { x: safeX, y: cardY, width: Math.round(width * 0.88), height: Math.round(height * 0.15), opacity: 0.96, rotation: 0 };
  add({ id: `${prefix}_card`, type: 'shape', ...card, zIndex: 3, meta: { shape: 'rect', fill: panel, radius: 34, stroke: 'rgba(255,255,255,0.18)', strokeWidth: 1, shadow: '0 28px 90px rgba(0,0,0,0.38)', keyframes: vis(card, Math.max(1200, durationMs - 3900), durationMs, 58) } });
  const support = { x: safeX + 42, y: cardY + 38, width: Math.round(width * 0.66), height: 104, opacity: 1, rotation: 0 };
  add({ id: `${prefix}_support`, type: 'text', ...support, zIndex: 8, meta: { content: splitCreativeMotionCaptionLines(supportCopy, 32, 3), fontSize: 34, fontWeight: 850, fontFamily: bodyFont, color: textColor, lineHeight: 1.08, keyframes: vis(support, Math.max(1350, durationMs - 3650), durationMs, 34) } });
  const ctaBg = { x: safeX + 42, y: cardY + 178, width: Math.round(width * 0.66), height: 82, opacity: 1, rotation: -1 };
  add({ id: `${prefix}_cta_bg`, type: 'shape', ...ctaBg, zIndex: 8, meta: { shape: 'rect', fill: accent3, radius: 999, shadow: '0 18px 48px rgba(255,228,94,0.26)', keyframes: vis(ctaBg, Math.max(1650, durationMs - 3150), durationMs, 24) } });
  const ctaText = { x: safeX + 70, y: cardY + 199, width: Math.round(width * 0.61), height: 44, opacity: 1, rotation: -1 };
  add({ id: `${prefix}_cta_text`, type: 'text', ...ctaText, zIndex: 9, meta: { content: cta, fontSize: 32, fontWeight: 950, fontFamily: bodyFont, color: '#07111F', textAlign: 'center', lineHeight: 1, keyframes: vis(ctaText, Math.max(1700, durationMs - 3070), durationMs, 18) } });
  add({ id: `${prefix}_progress_track`, type: 'shape', x: safeX, y: Math.round(height * 0.952), width: Math.round(width * 0.88), height: 16, opacity: 0.28, zIndex: 2, meta: { shape: 'rect', fill: '#FFFFFF', radius: 999 } });
  add({ id: `${prefix}_progress_fill`, type: 'shape', x: safeX, y: Math.round(height * 0.952), width: Math.round(width * 0.14), height: 16, zIndex: 4, meta: { shape: 'rect', fill: accent2, radius: 999, shadow: '0 0 34px rgba(22,217,255,0.42)', keyframes: [{ id: createCreativeLocalId('kf'), atMs: 0, x: safeX, y: Math.round(height * 0.952), width: Math.round(width * 0.08), height: 16, opacity: 1, rotation: 0, ease: 'linear' }, { id: createCreativeLocalId('kf'), atMs: durationMs, x: safeX, y: Math.round(height * 0.952), width: Math.round(width * 0.88), height: 16, opacity: 1, rotation: 0, ease: 'linear' }] } });
  return { elements: ops, width, height, durationMs, background };
}

function buildCreativeMotionTemplateSceneElements(instance = {}) {
  const templateId = String(instance.templateId || instance.input?.templateId || '').trim().toLowerCase();
  if (templateId === 'caption-reel-v2' || templateId === 'caption-reel') return buildCaptionReelV2SceneElementsFromMotionInstance(instance);
  if (templateId === 'product-promo') {
    const text = instance.input?.text && typeof instance.input.text === 'object' ? instance.input.text : {};
    return {
      elements: buildCreativeTemplateElements('product_ad', {
        title: text.title || 'Prometheus',
      subtitle: text.subtitle || text.body || 'A polished product promo built in the Creative workspace.',
        cta: text.cta || 'Learn more',
        background: instance.input?.brand?.colors?.background || '#0f172a',
        accent: instance.input?.brand?.colors?.primary || '#ff4d2d',
        durationMs: Number(instance.durationMs || instance.input?.durationMs) || 9000,
      }, 'video'),
      width: Number(instance.input?.width) || creativeSceneDoc.width,
      height: Number(instance.input?.height) || creativeSceneDoc.height,
      durationMs: Number(instance.durationMs || instance.input?.durationMs) || creativeSceneDoc.durationMs,
      background: instance.input?.brand?.colors?.background || creativeSceneDoc.background,
    };
  }
  if (templateId === 'audio-visualizer') {
    const text = instance.input?.text && typeof instance.input.text === 'object' ? instance.input.text : {};
    return {
      elements: buildCreativeTemplateElements('audiogram', {
        title: text.title || 'Audio highlight',
        subtitle: text.subtitle || text.body || 'Waveform, captions, cover art, and progress motion.',
        cta: text.cta || 'Listen now',
        background: instance.input?.brand?.colors?.background || '#07111f',
        accent: instance.input?.brand?.colors?.accent || '#16D9FF',
        durationMs: Number(instance.durationMs || instance.input?.durationMs) || 9000,
      }, 'video'),
      width: Number(instance.input?.width) || creativeSceneDoc.width,
      height: Number(instance.input?.height) || creativeSceneDoc.height,
      durationMs: Number(instance.durationMs || instance.input?.durationMs) || creativeSceneDoc.durationMs,
      background: instance.input?.brand?.colors?.background || creativeSceneDoc.background,
    };
  }
  return { elements: [], width: Number(instance.input?.width) || creativeSceneDoc.width, height: Number(instance.input?.height) || creativeSceneDoc.height, durationMs: Number(instance.durationMs || instance.input?.durationMs) || creativeSceneDoc.durationMs, background: creativeSceneDoc.background };
}

function applyCreativeTemplateCommand(payload = {}) {
  const template = String(payload.template || '').trim().toLowerCase();
  if (!template) throw new Error('apply_template requires template.');
  const mode = normalizeCreativeMode(window.currentCreativeMode);
    const built = buildCreativeTemplateElements(template, payload, mode);
    const replace = payload.replace !== false;
    const base = replace
      ? createSceneDocument({ width: built.width, height: built.height, background: built.background, durationMs: built.durationMs, frameRate: mode === 'video' ? 60 : creativeSceneDoc.frameRate })
      : creativeSceneDoc;
  const nextDoc = executeSceneGraphOps(base, built.elements);
  commitCreativeCommandDoc(nextDoc, { selectedId: nextDoc.elements[nextDoc.elements.length - 1]?.id || null });
  if (mode === 'video') setCreativeTimelinePosition(0, { render: false, persist: false });
  return { template, replace, width: nextDoc.width, height: nextDoc.height, elements: nextDoc.elements.length };
}

function buildVisibilityKeyframes(element, startMs, endMs, durationMs) {
  const base = { x: element.x, y: element.y, width: element.width, height: element.height, rotation: element.rotation };
  const safeStart = Math.max(0, Number(startMs) || 0);
  const safeEnd = Math.max(safeStart + 100, Number(endMs) || safeStart + 1000);
  const fade = Math.min(160, Math.max(40, Math.round((safeEnd - safeStart) / 8)));
  return [
    { id: createCreativeLocalId('kf'), atMs: 0, ...base, opacity: 0, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: safeStart, ...base, opacity: 0, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: Math.min(safeEnd, safeStart + fade), ...base, opacity: element.opacity ?? 1, ease: 'power2.out' },
    { id: createCreativeLocalId('kf'), atMs: Math.max(safeStart, safeEnd - fade), ...base, opacity: element.opacity ?? 1, ease: 'linear' },
    { id: createCreativeLocalId('kf'), atMs: safeEnd, ...base, opacity: 0, ease: 'power2.in' },
    { id: createCreativeLocalId('kf'), atMs: Math.max(safeEnd, durationMs), ...base, opacity: 0, ease: 'linear' },
  ];
}

function applyCreativeTimelineCommand(payload = {}) {
  if (normalizeCreativeMode(window.currentCreativeMode) !== 'video') throw new Error('creative_timeline is only available in Video mode.');
  const action = String(payload.action || '').trim().toLowerCase();
  const durationMs = getCreativeTimelineDurationMs();
  if (action === 'set_duration') {
    const nextDuration = Math.max(1000, Number(payload.durationMs) || durationMs);
    const nextDoc = createSceneDocument({ ...creativeSceneDoc, durationMs: nextDuration });
    commitCreativeCommandDoc(nextDoc, { selectedId: creativeSelectedId });
    setCreativeTimelinePosition(Math.min(creativeTimelineMs, nextDuration), { render: false, persist: false });
    return { action, durationMs: nextDuration };
  }
  if (action === 'set_playhead') {
    const atMs = snapCreativeTimelineMs(Number(payload.atMs) || 0, durationMs);
    setCreativeTimelinePosition(atMs, { render: true, persist: true, forceSeek: true });
    return { action, atMs };
  }
  if (action === 'caption') {
    const text = String(payload.text || '').trim();
    if (!text) throw new Error('caption requires text.');
    const startMs = Math.max(0, Number(payload.startMs ?? payload.atMs) || creativeTimelineMs || 0);
    const clipDurationMs = Math.max(500, Number(payload.clipDurationMs || payload.durationMs) || 2200);
    const endMs = Math.min(Math.max(durationMs, startMs + clipDurationMs), startMs + clipDurationMs);
    const nextDoc = executeSceneGraphOps(creativeSceneDoc, [{
      op: 'add',
      type: 'text',
      x: Math.round(creativeSceneDoc.width * 0.16),
      y: Math.round(creativeSceneDoc.height * 0.78),
      width: Math.round(creativeSceneDoc.width * 0.68),
      height: 80,
      zIndex: (creativeSceneDoc.elements || []).length + 1,
      meta: { content: text, fontSize: 34, fontWeight: 850, color: '#ffffff', textAlign: 'center', lineHeight: 1.15, shadow: '0 6px 24px rgba(0,0,0,.42)' },
    }]);
    const added = nextDoc.elements[nextDoc.elements.length - 1];
    added.meta.keyframes = buildVisibilityKeyframes(added, startMs, endMs, Math.max(durationMs, endMs));
    commitCreativeCommandDoc({ ...nextDoc, durationMs: Math.max(durationMs, endMs) }, { selectedId: added.id });
    return { action, captionId: added.id, startMs, endMs };
  }
  const ids = getCreativeCommandTargetIds(payload);
  if (!ids.length) throw new Error(`${action || 'timeline'} needs target ids or a selected element.`);
  if (action === 'trim_visibility' || action === 'sequence') {
    const startMs = Math.max(0, Number(payload.startMs ?? payload.atMs) || 0);
    const clipDurationMs = Math.max(300, Number(payload.clipDurationMs || payload.durationMs) || 1800);
    const gapMs = Math.max(0, Number(payload.gapMs) || 160);
    let nextDuration = durationMs;
    const nextElements = creativeSceneDoc.elements.map((element) => {
      if (!ids.includes(element.id)) return element;
      const index = action === 'sequence' ? ids.indexOf(element.id) : 0;
      const clipStart = startMs + (index * (clipDurationMs + gapMs));
      const clipEnd = clipStart + clipDurationMs;
      nextDuration = Math.max(nextDuration, clipEnd + 400);
      return {
        ...element,
        meta: {
          ...(element.meta || {}),
          keyframes: buildVisibilityKeyframes(element, clipStart, clipEnd, nextDuration),
          timelineStartMs: clipStart,
          timelineDurationMs: clipDurationMs,
        },
      };
    });
    commitCreativeCommandDoc({ ...creativeSceneDoc, durationMs: nextDuration, elements: nextElements }, { selectedId: ids[ids.length - 1] });
    return { action, ids, startMs, clipDurationMs, gapMs, durationMs: nextDuration };
  }
  if (action === 'stagger_animations') {
    const preset = String(payload.preset || 'fade_slide_up').trim();
    const startMs = Math.max(0, Number(payload.startMs ?? payload.atMs) || creativeTimelineMs || 0);
    const gapMs = Math.max(0, Number(payload.gapMs) || 180);
    const clipDurationMs = Math.max(100, Number(payload.clipDurationMs || payload.durationMs) || 520);
    const ops = ids.map((id, index) => ({ op: 'add-animation-preset', id, preset, startMs: startMs + (index * gapMs), durationMs: clipDurationMs }));
    const nextDoc = executeSceneGraphOps(creativeSceneDoc, ops);
    commitCreativeCommandDoc(nextDoc, { selectedId: ids[ids.length - 1] });
    return { action, ids, preset, startMs, gapMs, animationDurationMs: clipDurationMs };
  }
  throw new Error(`Unknown timeline action: ${action}`);
}

// ── Composition (multi-clip timeline) ────────────────────────────────────────
function compositionId(prefix = 'comp') {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function defaultCompositionTracks() {
  return [
    { id: compositionId('track'), kind: 'video', label: 'V1', index: 0, height: 56, muted: false, locked: false, hidden: false },
    { id: compositionId('track'), kind: 'audio', label: 'A1', index: 1, height: 44, muted: false, locked: false, hidden: false },
    { id: compositionId('track'), kind: 'caption', label: 'C1', index: 2, height: 36, muted: false, locked: false, hidden: false },
  ];
}

function createVideoCompositionFromActiveClip(seed = {}) {
  const doc = seed.scene || creativeSceneDoc || {};
  const tracks = defaultCompositionTracks();
  const htmlClip = seed.htmlMotionClip || creativeHtmlMotionClip || null;
  const hyperframesClip = seed.hyperframesClip || (Array.isArray(doc.elements) ? doc.elements.find((el) => el?.type === 'hyperframes') : null);
  const videoTrack = tracks[0];
  const activeDurationMs = Number(hyperframesClip?.meta?.durationMs || hyperframesClip?.timing?.durationMs || htmlClip?.durationMs || doc.durationMs);
  const durationMs = Math.max(1000, activeDurationMs || 12000);
  const clips = [];
  if (hyperframesClip && (hyperframesClip?.meta?.html || hyperframesClip?.meta?.projectPath)) {
    clips.push({
      id: `clip_${hyperframesClip.id || 'hyperframes'}`,
      trackId: videoTrack.id,
      label: hyperframesClip.meta?.compositionId || hyperframesClip.title || 'HyperFrames',
      inMs: 0,
      outMs: durationMs,
      trimStartMs: 0,
      trimEndMs: 0,
      lane: 'hyperframes',
      source: {
        kind: 'hyperframes',
        html: hyperframesClip.meta?.html || '',
        projectPath: hyperframesClip.meta?.projectPath || null,
        entryFile: hyperframesClip.meta?.entryFile || null,
        elementId: hyperframesClip.id,
        compositionId: hyperframesClip.meta?.compositionId || null,
        variables: hyperframesClip.meta?.variables || {},
      },
      transitionIn: null,
      transitionOut: null,
      locked: false,
      meta: { sourceFormat: 'hyperframes' },
    });
  } else if (htmlClip?.path) {
    clips.push({
      id: `clip_${htmlClip.id || 'html_motion'}`,
      trackId: videoTrack.id,
      label: htmlClip.title || 'HTML Motion',
      inMs: 0,
      outMs: durationMs,
      trimStartMs: 0,
      trimEndMs: 0,
      lane: 'html-motion',
      source: { kind: 'html-motion', clipPath: htmlClip.path, compositionId: htmlClip.composition?.id || null },
      transitionIn: null,
      transitionOut: null,
      locked: false,
      meta: {},
    });
  }
  return {
    id: `comp_${hyperframesClip?.id || htmlClip?.id || doc.id || 'video'}`,
    version: 1,
    width: Number(hyperframesClip?.width || htmlClip?.width || doc.width) || 1920,
    height: Number(hyperframesClip?.height || htmlClip?.height || doc.height) || 1080,
    frameRate: Math.max(1, Number(htmlClip?.frameRate || doc.frameRate) || 60),
    durationMs,
    background: doc.background || '#000000',
    tracks,
    clips,
    audioTracks: doc.audioTrack && doc.audioTrack.source ? [doc.audioTrack] : [],
    captions: Array.isArray(doc.captions) ? doc.captions : [],
    brandKit: doc.brandKit || null,
    selectedClipId: clips[0]?.id || null,
    meta: { videoClipLanes: ['hyperframes', 'html-motion', 'remotion'] },
  };
}

function ensureCreativeComposition() {
  if (!creativeComposition) creativeComposition = createVideoCompositionFromActiveClip();
  return creativeComposition;
}

function getCreativeCompositionBridge() {
  return {
    getComposition: () => creativeComposition,
    getSequenceState: () => ({ ...creativeSequenceState }),
    ensureComposition: () => ensureCreativeComposition(),
    openSequence: () => window.canvasSequenceOpen?.(),
    saveSequence: () => window.canvasSequenceSave?.(),
    render: () => window.canvasCompositionRender?.(),
    splitAtPlayhead: () => window.canvasCompositionSplitAtPlayhead?.(),
    deleteSelected: () => window.canvasCompositionDeleteSelected?.(),
    selectClip: (clipId) => {
      const comp = ensureCreativeComposition();
      if (!comp) return;
      comp.selectedClipId = clipId || null;
      persistCompositionState();
      renderCreativeWorkspace?.();
    },
    getPlayheadMs: () => Number(creativeTimelineMs) || 0,
  };
}

window.prometheusCreativeCompositionBridge = getCreativeCompositionBridge();

function recomputeCompositionDuration(comp) {
  const computed = comp.clips.reduce((max, c) => Math.max(max, c.outMs || 0), 0);
  comp.durationMs = Math.max(1000, computed || comp.durationMs || 1000);
}

function persistCompositionState() {
  const sid = window.currentChatSessionId;
  if (!sid) return;
  const idx = (window.chatSessions || []).findIndex((s) => s.id === sid);
  if (idx >= 0) {
    window.chatSessions[idx].creativeComposition = creativeComposition;
    window.chatSessions[idx].updatedAt = Date.now();
  }
  try { persistActiveChat?.(); } catch {}
}

function summarizeComposition(comp) {
  const videoTrackIds = new Set(comp.tracks.filter((t) => t.kind === 'video').map((t) => t.id));
  return {
    width: comp.width,
    height: comp.height,
    durationMs: comp.durationMs,
    frameRate: comp.frameRate,
    trackCount: comp.tracks.length,
    clipCount: comp.clips.length,
    videoClipCount: comp.clips.filter((c) => videoTrackIds.has(c.trackId)).length,
    audioTrackCount: (comp.audioTracks || []).length,
    captionTrackCount: (comp.captions || []).length,
  };
}

function compositionAddTrack(comp, kind, label) {
  const sameKindCount = comp.tracks.filter((t) => t.kind === kind).length;
  const track = {
    id: compositionId('track'),
    kind,
    label: label || (kind === 'video' ? `V${sameKindCount + 1}` : kind === 'audio' ? `A${sameKindCount + 1}` : `C${sameKindCount + 1}`),
    index: comp.tracks.length,
    height: kind === 'video' ? 56 : kind === 'audio' ? 44 : 36,
    muted: false, locked: false, hidden: false,
  };
  comp.tracks.push(track);
  return track;
}

function compositionAddClip(comp, input) {
  let trackId = input.trackId || '';
  if (!trackId) {
    const firstVideo = comp.tracks.find((t) => t.kind === 'video');
    if (!firstVideo) throw new Error('Composition has no video track to host the clip.');
    trackId = firstVideo.id;
  }
  const track = comp.tracks.find((t) => t.id === trackId);
  if (!track) throw new Error(`Unknown trackId: ${trackId}`);
  if (track.locked) throw new Error(`Track ${track.label} is locked.`);
  const inMs = Number.isFinite(Number(input.inMs)) ? Math.max(0, Number(input.inMs)) : Math.max(0, Number(input.atMs) || 0);
  const outMs = Number.isFinite(Number(input.outMs))
    ? Math.max(inMs + 1, Number(input.outMs))
    : inMs + Math.max(1, Number(input.durationMs) || 4000);
  const lane = ['hyperframes', 'html-motion', 'remotion'].includes(input.lane) ? input.lane : '';
  if (!lane) throw new Error('Video timeline clips must use hyperframes, html-motion, or remotion.');
  const clip = {
    id: compositionId('clip'),
    trackId,
    label: input.label || 'Clip',
    inMs,
    outMs,
    trimStartMs: Math.max(0, Number(input.trimStartMs) || 0),
    trimEndMs: Math.max(0, Number(input.trimEndMs) || 0),
    lane,
    source: input.source || (lane === 'hyperframes'
      ? { kind: 'hyperframes', html: '', elementId: '', compositionId: null, variables: {} }
      : lane === 'html-motion'
        ? { kind: 'html-motion', clipPath: '' }
        : { kind: 'remotion', templateId: '', input: {} }),
    transitionIn: null,
    transitionOut: null,
    locked: false,
    meta: {},
  };
  if (input.ripple === true) {
    const dur = clip.outMs - clip.inMs;
    for (const existing of comp.clips) {
      if (existing.trackId === trackId && existing.inMs >= clip.inMs) {
        existing.inMs += dur;
        existing.outMs += dur;
      }
    }
  }
  comp.clips.push(clip);
  recomputeCompositionDuration(comp);
  return clip;
}

function compositionMoveClip(comp, clipId, options) {
  const clip = comp.clips.find((c) => c.id === clipId);
  if (!clip) throw new Error(`Unknown clipId: ${clipId}`);
  if (clip.locked) throw new Error('Clip is locked.');
  if (options.trackId && options.trackId !== clip.trackId) {
    const target = comp.tracks.find((t) => t.id === options.trackId);
    if (!target) throw new Error(`Unknown trackId: ${options.trackId}`);
    if (target.locked) throw new Error(`Track ${target.label} is locked.`);
    clip.trackId = options.trackId;
  }
  const dur = clip.outMs - clip.inMs;
  let newIn = clip.inMs;
  if (Number.isFinite(Number(options.atMs))) newIn = Math.max(0, Number(options.atMs));
  else if (Number.isFinite(Number(options.deltaMs))) newIn = Math.max(0, clip.inMs + Number(options.deltaMs));
  clip.inMs = newIn;
  clip.outMs = newIn + dur;
  recomputeCompositionDuration(comp);
  return clip;
}

function compositionTrimClip(comp, clipId, edge, toMs) {
  const clip = comp.clips.find((c) => c.id === clipId);
  if (!clip) throw new Error(`Unknown clipId: ${clipId}`);
  if (clip.locked) throw new Error('Clip is locked.');
  const target = Math.max(0, Number(toMs) || 0);
  if (edge === 'head') {
    if (target >= clip.outMs) throw new Error('Head trim would zero out the clip.');
    const delta = target - clip.inMs;
    clip.inMs = target;
    clip.trimStartMs = Math.max(0, clip.trimStartMs + delta);
  } else {
    if (target <= clip.inMs) throw new Error('Tail trim would zero out the clip.');
    const delta = clip.outMs - target;
    clip.outMs = target;
    clip.trimEndMs = Math.max(0, clip.trimEndMs + delta);
  }
  recomputeCompositionDuration(comp);
  return clip;
}

function compositionSplitClip(comp, clipId, atMs) {
  const idx = comp.clips.findIndex((c) => c.id === clipId);
  if (idx < 0) throw new Error(`Unknown clipId: ${clipId}`);
  const clip = comp.clips[idx];
  if (clip.locked) throw new Error('Clip is locked.');
  if (atMs <= clip.inMs || atMs >= clip.outMs) throw new Error('Split point must be strictly inside the clip.');
  const originalOutMs = clip.outMs;
  const originalTrimEndMs = clip.trimEndMs;
  const localOffsetMs = atMs - clip.inMs;
  const rightDuration = originalOutMs - atMs;
  const right = JSON.parse(JSON.stringify(clip));
  right.id = compositionId('clip');
  right.inMs = atMs;
  right.outMs = originalOutMs;
  right.trimStartMs = clip.trimStartMs + localOffsetMs;
  right.trimEndMs = originalTrimEndMs;
  right.transitionIn = null;
  clip.outMs = atMs;
  clip.trimEndMs = originalTrimEndMs + rightDuration;
  clip.transitionOut = null;
  comp.clips.splice(idx + 1, 0, right);
  recomputeCompositionDuration(comp);
  return { left: clip, right };
}

function compositionDeleteClip(comp, clipId, options = {}) {
  const idx = comp.clips.findIndex((c) => c.id === clipId);
  if (idx < 0) return false;
  const clip = comp.clips[idx];
  const removedDuration = clip.outMs - clip.inMs;
  comp.clips.splice(idx, 1);
  if (options.ripple === true) {
    for (const other of comp.clips) {
      if (other.trackId === clip.trackId && other.inMs >= clip.outMs) {
        other.inMs = Math.max(0, other.inMs - removedDuration);
        other.outMs = Math.max(0, other.outMs - removedDuration);
      }
    }
  }
  if (comp.selectedClipId === clipId) comp.selectedClipId = null;
  recomputeCompositionDuration(comp);
  return true;
}

function compositionSetTransition(comp, clipId, edge, spec) {
  const clip = comp.clips.find((c) => c.id === clipId);
  if (!clip) throw new Error(`Unknown clipId: ${clipId}`);
  if (edge === 'in') clip.transitionIn = spec || null;
  else clip.transitionOut = spec || null;
  return clip;
}

function compositionLint(comp) {
  const issues = [];
  for (const track of comp.tracks) {
    const items = comp.clips.filter((c) => c.trackId === track.id).sort((a, b) => a.inMs - b.inMs);
    for (let i = 0; i < items.length; i++) {
      const a = items[i];
      if (a.outMs <= a.inMs) issues.push({ severity: 'error', code: 'clip_zero_duration', message: 'Clip has non-positive duration.', clipId: a.id, trackId: track.id });
      for (let j = i + 1; j < items.length; j++) {
        const b = items[j];
        if (a.inMs < b.outMs && b.inMs < a.outMs) issues.push({ severity: track.kind === 'video' ? 'warning' : 'info', code: 'clip_overlap', message: `Clips overlap on ${track.label}.`, clipId: a.id, trackId: track.id });
      }
    }
  }
  if (comp.tracks.filter((t) => t.kind === 'video').length === 0) issues.push({ severity: 'error', code: 'no_video_track', message: 'Composition has no video track.' });
  return { ok: issues.filter((i) => i.severity === 'error').length === 0, issues };
}

async function handleCreativeCommandMessage(message) {
  await ensureCreativeFeatureRuntime();
  const module = creativeWorkspaceRuntimeModule || await loadCreativeWorkspaceRuntime();
  return module.handleCreativeCommandMessage(creativeWorkspaceRuntimeContext, message);
}

function buildBrowserTeachCallerContext(latestMessage = '') {
  const state = getBrowserCanvasState();
  const teach = getBrowserTeachSession(state);
  if (!teach.active || normalizeBrowserTeachPhase(teach.phase) === 'idle') return '';
  const steps = Array.isArray(teach.steps) ? teach.steps : [];
  const pending = teach.pendingStep && typeof teach.pendingStep === 'object' ? teach.pendingStep : null;
  const verification = teach.verification && typeof teach.verification === 'object' ? teach.verification : null;
  const verificationApproval = parseBrowserTeachVerificationApproval(latestMessage);
  const riskySteps = steps
    .map((step, idx) => ({ step, index: idx + 1 }))
    .filter(({ step }) => normalizeBrowserTeachRisk(step?.risk) === 'high');
  return [
    '[TEACH_SESSION]',
    'Teach mode is active. Your job is to help the user capture, verify, and package a reusable browser workflow.',
    `phase: ${normalizeBrowserTeachPhase(teach.phase)}`,
    `start_url: ${teach.startUrl || state.url || '(unknown)'}`,
    teach.startTitle ? `start_title: ${teach.startTitle}` : '',
    `recorded_steps: ${steps.length}`,
    riskySteps.length ? `risky_steps: ${riskySteps.map(({ index }) => index).join(', ')}` : 'risky_steps: none',
    pending ? `pending_step: ${pending.toolPreview || pending.summary || pending.toolName}` : '',
    normalizeBrowserTeachPhase(teach.phase) === 'approval_pending'
      ? (verificationApproval.approved
          ? 'The user has now approved Teach verification. Call browser_teach_verify with the approved boundary before you summarize the results.'
          : 'The user has completed recording. Do NOT execute browser tools yet. First summarize the workflow, explain the risky steps, and ask whether to run the full verification or stop before a specific step.')
      : 'While recording, stay focused on cleaning up the workflow, naming elements, and making the final replay reliable.',
    verificationApproval.approved ? `verification_approval: ${verificationApproval.mode}` : '',
    verificationApproval.approved && verificationApproval.stopBeforeStep > 0 ? `verification_stop_before_step: ${verificationApproval.stopBeforeStep}` : '',
    'If the user explicitly approves verification in their latest message, use browser_teach_verify to replay the workflow from the recorded start_url and then explain what happened step by step.',
    verification
      ? [
          '[TEACH_VERIFICATION_RESULT]',
          `status: ${verification.status || 'unknown'}`,
          `boundary: ${verification.boundaryLabel || 'unknown'}`,
          `executed_steps: ${Number(verification.executedCount || 0)} / ${Number(verification.totalRecordedSteps || 0)}`,
          verification.stopBeforeStep > 0 ? `stopped_before_step: ${verification.stopBeforeStep}` : '',
          verification.failedStep > 0 ? `failed_step: ${verification.failedStep}` : '',
          verification.failureSummary ? `failure_summary: ${verification.failureSummary}` : '',
          verification.finalTitle ? `final_title: ${verification.finalTitle}` : '',
          verification.finalUrl ? `final_url: ${verification.finalUrl}` : '',
          Array.isArray(verification.riskyStepIndexes) && verification.riskyStepIndexes.length
            ? `recorded_risky_steps: ${verification.riskyStepIndexes.join(', ')}`
            : 'recorded_risky_steps: none',
        ].filter(Boolean).join('\n')
      : '',
    verification
      ? 'After verification, summarize what actually happened, infer the likely workflow goal, ask the user whether that understanding is correct, and recommend composite, skill, both, or neither. Do not create anything unless the user explicitly asks you to.'
      : 'After verification, explain what worked, what needed adjustment, and recommend the next packaging option, but do not create anything unless the user explicitly asks you to.',
    verification
      ? 'Write the post-verification reply from the verifier evidence, not from a canned template. Reference the actual steps, failures, recoveries, and final page when you explain what you learned.'
      : '',
    steps.length
      ? `steps:\n${steps.map((step, idx) => {
          const status = String(step?.status || 'recorded').trim().toLowerCase();
          const risk = normalizeBrowserTeachRisk(step?.risk);
          const statusSuffix = status && status !== 'recorded' ? ` [status=${status}]` : '';
          const riskSuffix = risk === 'high' ? ' [risk=high]' : '';
          return `${idx + 1}. ${String(step?.toolPreview || step?.summary || step?.toolName || 'browser step').trim()}${statusSuffix}${riskSuffix}`;
        }).join('\n')}`
      : '',
  ].filter(Boolean).join('\n');
}

function buildCombinedCallerContext(latestMessage = '') {
  return [
    buildCreativeSceneCallerContext(),
    buildBrowserTeachCallerContext(latestMessage),
    (() => {
      const highlighted = getActiveChatHighlightedTextContext();
      if (!highlighted?.text) return '';
      return [
        '[CHAT_HIGHLIGHTED_TEXT]',
        'The user attached highlighted chat text as an annotation. Treat it as the primary quoted context for this turn.',
        `source_role: ${highlighted.sourceRole || 'chat'}`,
        Number.isInteger(highlighted.messageIndex) ? `message_index: ${highlighted.messageIndex}` : '',
        `text:\n${highlighted.text}`,
        '[/CHAT_HIGHLIGHTED_TEXT]',
      ].filter(Boolean).join('\n');
    })(),
  ].filter(Boolean).join('\n\n');
}

function getCanvasLang(filename) {
  const ext = String(filename || '').split('.').pop().toLowerCase();
  return CANVAS_LANG_MAP[ext] || 'null';
}

function isHtmlFile(filename) {
  const ext = String(filename || '').split('.').pop().toLowerCase();
  return ext === 'html' || ext === 'htm';
}

function extractJsonCandidatesFromText(text) {
  const source = String(text || '');
  const candidates = [];
  const fenceRegex = /```(?:json)?\s*([\s\S]*?)```/gi;
  let fence;
  while ((fence = fenceRegex.exec(source)) !== null) {
    const chunk = String(fence[1] || '').trim();
    if (chunk) candidates.push(chunk);
  }
  const stack = [];
  let start = -1;
  for (let i = 0; i < source.length; i += 1) {
    const ch = source[i];
    if (ch === '{') {
      if (!stack.length) start = i;
      stack.push(ch);
    } else if (ch === '}' && stack.length) {
      stack.pop();
      if (!stack.length && start >= 0) {
        const chunk = source.slice(start, i + 1).trim();
        if (chunk) candidates.push(chunk);
        start = -1;
      }
    }
  }
  return candidates;
}

function parseDesignOpsFromText(text) {
  const supportedOps = new Set([
    'patch-css-rule',
    'patch-html-attributes',
    'replace-inner-text',
    'replace-in-file',
    'insert-in-file',
  ]);
  const candidates = extractJsonCandidatesFromText(text);
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (!parsed || !Array.isArray(parsed.ops)) continue;
      const ops = parsed.ops.filter((op) => supportedOps.has(String(op?.op || '').trim()));
      if (!ops.length) continue;
      return {
        matched: true,
        ops,
        payload: parsed,
        source: candidate,
      };
    } catch {
      // keep scanning
    }
  }
  return { matched: false, ops: [], payload: null, source: '' };
}

function getDesignPatchInstruction() {
  return [
    '[DESIGN_PATCH_PROTOCOL]',
    'For Design Mode edit requests, the goal is to change the live project files backing the current canvas, not merely explain a patch.',
    'If file editing tools are available, use them to read and edit the exact canvas files first.',
    'If file tools are not available in this turn, return a JSON object with an "ops" array inside a ```json fenced block so the Design client can apply it.',
    'Supported design ops: patch-css-rule, patch-html-attributes, replace-inner-text, replace-in-file, insert-in-file.',
    'Use patch-css-rule for visual style changes to selected elements and components.',
    'Use patch-html-attributes or replace-inner-text for HTML structure/content changes.',
    'Use replace-in-file or insert-in-file when CSS/JS source files need direct targeted edits.',
    'Always include a target file when you know it. Prefer CSS first for style changes, HTML second for structure/content, and JS only when behavior or generated markup must change.',
  ].join('\n');
}

function flattenCanvasWorkspaceFiles(nodes, prefix = '') {
  if (!Array.isArray(nodes)) return [];
  const results = [];
  for (const node of nodes) {
    if (!node || typeof node !== 'object') continue;
    const nodePath = normalizeCanvasPath(node.path || (prefix ? `${prefix}/${node.name || ''}` : (node.name || '')));
    if (node.type === 'file' && nodePath) {
      results.push(nodePath);
      continue;
    }
    if (node.type === 'dir' && Array.isArray(node.children)) {
      results.push(...flattenCanvasWorkspaceFiles(node.children, nodePath));
    }
  }
  return results;
}

function getCanvasPathExt(filePath) {
  return String(filePath || '').split('.').pop().toLowerCase();
}

function escapeRegex(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildProjectAbsolutePath(relativePath) {
  const rel = normalizeCanvasPath(relativePath);
  if (!rel) return '';
  if (/^[a-z]:\//i.test(rel) || rel.startsWith('/')) return rel;
  if (!canvasProjectRoot) return rel;
  return normalizeCanvasPath(`${canvasProjectRoot}/${rel}`);
}

function encodeCanvasPreviewPath(relativePath) {
  return String(relativePath || '')
    .split('/')
    .filter(Boolean)
    .map((segment) => encodeURIComponent(segment))
    .join('/');
}

function getProjectRelativeCanvasPath(targetPath, rootPath = canvasProjectRoot) {
  const normalizedTarget = normalizeCanvasPath(targetPath || '');
  const normalizedRoot = normalizeCanvasPath(rootPath || '');
  if (!normalizedTarget || !normalizedRoot) return '';
  if (normalizedTarget === normalizedRoot) return '';
  const rootPrefix = `${normalizedRoot}/`;
  return normalizedTarget.startsWith(rootPrefix) ? normalizedTarget.slice(rootPrefix.length) : '';
}

function getDesignPreviewEntryPath(tab) {
  const normalizedRoot = normalizeCanvasPath(canvasProjectRoot || '');
  if (!normalizedRoot) return '';
  const preferredTabPath = getProjectRelativeCanvasPath(tab?.diskPath || '', normalizedRoot);
  if (preferredTabPath && isHtmlFile(tab?.name || preferredTabPath)) return preferredTabPath;
  const htmlTab = canvasTabs.find((candidate) => {
    const relativePath = getProjectRelativeCanvasPath(candidate?.diskPath || '', normalizedRoot);
    return relativePath && isHtmlFile(candidate?.name || relativePath);
  });
  if (htmlTab) return getProjectRelativeCanvasPath(htmlTab.diskPath, normalizedRoot);
  return 'index.html';
}

function escapeCanvasPreviewAttribute(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Code previews are an editor surface, not a second browser. Keep links,
// forms, and popup APIs inside the preview so an accidental click cannot
// navigate the Electron renderer or open Prometheus Browser.
function protectCanvasPreviewDocument(source) {
  const guard = `<script data-prometheus-preview-guard>(function(){
    try {
      var noopOpen = function(){ return null; };
      window.open = noopOpen;
      document.addEventListener('click', function(event){
        var anchor = event.target && event.target.closest ? event.target.closest('a[href]') : null;
        if (anchor) event.preventDefault();
      }, true);
      document.addEventListener('auxclick', function(event){
        var anchor = event.target && event.target.closest ? event.target.closest('a[href]') : null;
        if (anchor) event.preventDefault();
      }, true);
      document.addEventListener('submit', function(event){ event.preventDefault(); }, true);
    } catch (_) {}
  })();<\/script>`;
  const value = String(source || '');
  if (/<script[^>]+data-prometheus-preview-guard/i.test(value)) return value;
  if (/<\/body\s*>/i.test(value)) return value.replace(/<\/body\s*>/i, `${guard}</body>`);
  if (/<\/html\s*>/i.test(value)) return value.replace(/<\/html\s*>/i, `${guard}</html>`);
  return `${value}${guard}`;
}

// Keep Design previews independent from the save request.  Loading the page through
// the project-preview route meant a Code → Preview transition could show a stale or
// blank document while its write was still in flight.  srcdoc renders the editor's
// current contents immediately; this base URL preserves normal relative assets.
function buildDesignPreviewDocument(content, previewPath) {
  const parts = String(previewPath || '').split('/').filter(Boolean);
  parts.pop();
  const sessionId = encodeURIComponent(String(window.agentSessionId || 'default'));
  const directory = parts.length ? `${encodeCanvasPreviewPath(parts.join('/'))}/` : '';
  const baseHref = `/api/canvas/project-preview/${sessionId}/${directory}`;
  const baseTag = `<base href="${escapeCanvasPreviewAttribute(baseHref)}">`;
  const source = String(content || '');

  let documentSource = '';
  if (/<head\b[^>]*>/i.test(source)) {
    documentSource = source.replace(/<head\b[^>]*>/i, (match) => `${match}${baseTag}`);
  } else if (/<html\b[^>]*>/i.test(source)) {
    documentSource = source.replace(/<html\b[^>]*>/i, (match) => `${match}<head>${baseTag}</head>`);
  } else {
    documentSource = `<!doctype html><html><head>${baseTag}</head><body>${source}</body></html>`;
  }
  return protectCanvasPreviewDocument(documentSource);
}

async function syncDirtyDesignTabsToDisk() {
  const normalizedRoot = normalizeCanvasPath(canvasProjectRoot || '');
  if (!normalizedRoot) return 0;
  const activeTab = canvasTabs.find((candidate) => candidate.id === activeCanvasTabId) || null;
  if (activeTab && canvasEditor && activeTab.mode !== 'preview' && !activeTab.isImage && !activeTab.isBinary) {
    activeTab.content = canvasEditor.getValue();
  }

  let synced = 0;
  for (const tab of canvasTabs) {
    const relativePath = getProjectRelativeCanvasPath(tab?.diskPath || '', normalizedRoot);
    if (!tab?.dirty || !tab?.diskPath || !relativePath || tab.isImage || tab.isBinary) continue;
    await writeCanvasFileSnapshot(tab.diskPath, String(tab.content || ''), { name: tab.name || relativePath.split('/').pop() || relativePath });
    tab.savedContent = String(tab.content || '');
    tab.dirty = false;
    synced += 1;
  }
  if (synced) canvasRenderTabs();
  return synced;
}

function resolveDesignFilePath(fileHint, allowedExts = []) {
  const normalizedHint = normalizeCanvasPath(fileHint);
  const allowed = Array.isArray(allowedExts) && allowedExts.length
    ? new Set(allowedExts.map((ext) => String(ext || '').toLowerCase()))
    : null;
  const acceptExt = (filePath) => !allowed || allowed.has(getCanvasPathExt(filePath));
  const allProjectFiles = flattenCanvasWorkspaceFiles(canvasWorkspaceTree).map((relativePath) => buildProjectAbsolutePath(relativePath));
  const candidates = [
    ...canvasTabs.map((tab) => normalizeCanvasPath(tab.diskPath || '')).filter(Boolean),
    ...allProjectFiles,
  ].filter((value, index, array) => array.indexOf(value) === index);
  const activeTab = canvasTabs.find((tab) => tab.id === activeCanvasTabId) || null;

  if (normalizedHint) {
    const exact = candidates.find((candidate) => normalizeCanvasPath(candidate) === normalizedHint && acceptExt(candidate));
    if (exact) return exact;
    const directAbsolute = buildProjectAbsolutePath(normalizedHint);
    const directMatch = candidates.find((candidate) => normalizeCanvasPath(candidate) === directAbsolute && acceptExt(candidate));
    if (directMatch) return directMatch;
    const suffix = normalizedHint.startsWith('/') ? normalizedHint : `/${normalizedHint}`;
    const suffixMatch = candidates.find((candidate) => normalizeCanvasPath(candidate).endsWith(suffix) && acceptExt(candidate));
    if (suffixMatch) return suffixMatch;
    const nameMatch = candidates.find((candidate) => String(candidate).split('/').pop() === normalizedHint.split('/').pop() && acceptExt(candidate));
    if (nameMatch) return nameMatch;
    if (acceptExt(directAbsolute)) return directAbsolute;
  }

  if (activeTab?.diskPath && acceptExt(activeTab.diskPath)) return normalizeCanvasPath(activeTab.diskPath);

  const preferredExtOrder = allowed ? Array.from(allowed) : [];
  for (const preferredExt of preferredExtOrder) {
    const match = candidates.find((candidate) => getCanvasPathExt(candidate) === preferredExt);
    if (match) return match;
  }

  const fallback = candidates.find((candidate) => acceptExt(candidate));
  return fallback || '';
}

async function loadCanvasFileSnapshot(diskPath) {
  const normalizedPath = normalizeCanvasPath(diskPath);
  if (!normalizedPath) throw new Error('No target file was resolved.');
  const existingTab = canvasTabs.find((tab) => normalizeCanvasPath(tab.diskPath || '') === normalizedPath);
  if (existingTab && !existingTab.isImage && !existingTab.isBinary) {
    if (canvasEditor && activeCanvasTabId === existingTab.id && existingTab.mode !== 'preview') {
      existingTab.content = canvasEditor.getValue();
    }
    return {
      diskPath: normalizedPath,
      name: existingTab.name || normalizedPath.split('/').pop() || normalizedPath,
      content: String(existingTab.content || ''),
      tab: existingTab,
    };
  }
  const response = await fetch(`/api/canvas/file?path=${encodeURIComponent(normalizedPath)}`);
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.success) {
    throw new Error(data.error || `Could not load ${normalizedPath}`);
  }
  if (data.isImage || data.isBinary) {
    throw new Error(`Unsupported Design patch target: ${normalizedPath}`);
  }
  return {
    diskPath: normalizedPath,
    name: normalizedPath.split('/').pop() || normalizedPath,
    content: String(data.content || ''),
    tab: existingTab || null,
  };
}

async function writeCanvasFileSnapshot(diskPath, content, options = {}) {
  const normalizedPath = normalizeCanvasPath(diskPath);
  const response = await fetch('/api/canvas/file', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ path: normalizedPath, content }),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.success) {
    throw new Error(data.error || `Could not save ${normalizedPath}`);
  }

  let tab = canvasTabs.find((candidate) => normalizeCanvasPath(candidate.diskPath || '') === normalizedPath) || null;
  const fileName = options.name || normalizedPath.split('/').pop() || normalizedPath;
  if (!tab) {
    tab = {
      id: `ctab_${Math.random().toString(36).slice(2)}`,
      name: fileName,
      content,
      savedContent: content,
      diskPath: normalizedPath,
      dirty: false,
      mode: isHtmlFile(fileName) ? 'preview' : 'code',
      language: getCanvasLang(fileName),
    };
    canvasTabs.push(tab);
  } else {
    tab.name = fileName;
    tab.content = content;
    tab.savedContent = content;
    tab.dirty = false;
    tab.isImage = false;
    tab.isBinary = false;
  }

  if (activeCanvasTabId === tab.id) {
    if (canvasEditor && tab.mode !== 'preview') setCanvasEditorValue(content);
    if (tab.mode === 'preview') canvasUpdatePreview();
  }
  canvasRenderTabs();
  persistActiveChat();
  return tab;
}

function serializeHtmlDocument(doc) {
  const doctype = doc?.doctype ? '<!DOCTYPE html>\n' : '<!DOCTYPE html>\n';
  return `${doctype}${doc.documentElement.outerHTML}`;
}

function queryDesignHtmlTarget(doc, selector) {
  const primarySelector = String(selector || '').trim();
  if (primarySelector) {
    try {
      const found = doc.querySelector(primarySelector);
      if (found) return found;
    } catch {
      // ignore invalid selector and fall through
    }
  }
  const selectedId = String(designSelectedElementContext?.id || '').trim();
  if (selectedId) {
    try {
      const found = doc.getElementById(selectedId);
      if (found) return found;
    } catch {}
  }
  const selectedSelector = String(designSelectedElementContext?.selector || '').trim();
  if (selectedSelector) {
    try {
      const found = doc.querySelector(selectedSelector);
      if (found) return found;
    } catch {}
  }
  return null;
}

function normalizeCssPropertyName(name) {
  return String(name || '')
    .replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`)
    .trim()
    .toLowerCase();
}

function upsertCssRuleContent(content, selector, declarations = {}) {
  const nextDeclarations = {};
  Object.entries(declarations || {}).forEach(([key, value]) => {
    const prop = normalizeCssPropertyName(key);
    if (!prop) return;
    nextDeclarations[prop] = String(value);
  });
  if (!selector || !Object.keys(nextDeclarations).length) return String(content || '');

  const selectorRegex = new RegExp(`(^|\\n)\\s*${escapeRegex(selector)}\\s*\\{([\\s\\S]*?)\\}`, 'm');
  const source = String(content || '');
  const match = source.match(selectorRegex);
  if (match) {
    const originalBlock = String(match[2] || '');
    const parsedDeclarations = {};
    originalBlock.replace(/([a-zA-Z-]+)\s*:\s*([^;]+);?/g, (_full, prop, value) => {
      parsedDeclarations[normalizeCssPropertyName(prop)] = String(value).trim();
      return _full;
    });
    const merged = { ...parsedDeclarations, ...nextDeclarations };
    const ruleBody = Object.entries(merged)
      .map(([prop, value]) => `  ${prop}: ${value};`)
      .join('\n');
    return source.replace(selectorRegex, `${match[1] || '\n'}${selector} {\n${ruleBody}\n}`);
  }

  const newRule = `${selector} {\n${Object.entries(nextDeclarations).map(([prop, value]) => `  ${prop}: ${value};`).join('\n')}\n}`;
  return `${source.replace(/\s*$/, '')}\n\n${newRule}\n`;
}

function patchHtmlAttributesContent(content, selector, patch = {}) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(String(content || ''), 'text/html');
  const target = queryDesignHtmlTarget(doc, selector);
  if (!target) throw new Error(`Could not find HTML selector ${selector || '(selected element)'}.`);

  const attributes = patch.attributes && typeof patch.attributes === 'object' ? patch.attributes : {};
  const styles = patch.styles && typeof patch.styles === 'object' ? patch.styles : {};
  const removeAttributes = Array.isArray(patch.removeAttributes) ? patch.removeAttributes : [];

  Object.entries(attributes).forEach(([name, value]) => {
    if (value === null || value === undefined || value === false) target.removeAttribute(name);
    else target.setAttribute(name, String(value));
  });
  removeAttributes.forEach((name) => {
    if (name) target.removeAttribute(String(name));
  });
  Object.entries(styles).forEach(([name, value]) => {
    const prop = normalizeCssPropertyName(name);
    if (!prop) return;
    if (value === null || value === undefined || value === false) target.style.removeProperty(prop);
    else target.style.setProperty(prop, String(value));
  });

  return serializeHtmlDocument(doc);
}

function replaceInnerTextContent(content, selector, text) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(String(content || ''), 'text/html');
  const target = queryDesignHtmlTarget(doc, selector);
  if (!target) throw new Error(`Could not find HTML selector ${selector || '(selected element)'}.`);
  target.textContent = String(text ?? '');
  return serializeHtmlDocument(doc);
}

function replaceInFileContent(content, op = {}) {
  const source = String(content || '');
  const find = op.find;
  const replace = String(op.replace ?? '');
  if (find === undefined || find === null || find === '') {
    throw new Error('replace-in-file requires a non-empty "find" value.');
  }
  if (op.regex) {
    const flags = String(op.flags || (op.all ? 'g' : '')).trim();
    const pattern = new RegExp(String(find), flags);
    if (!pattern.test(source)) throw new Error(`Pattern not found: ${find}`);
    return source.replace(pattern, replace);
  }
  const needle = String(find);
  if (!source.includes(needle)) throw new Error(`Text not found: ${needle}`);
  if (op.all) return source.split(needle).join(replace);
  return source.replace(needle, replace);
}

function insertInFileContent(content, op = {}) {
  const source = String(content || '');
  const text = String(op.text ?? '');
  if (!text) throw new Error('insert-in-file requires "text".');
  if (op.before) {
    const marker = String(op.before);
    const index = source.indexOf(marker);
    if (index < 0) throw new Error(`Marker not found: ${marker}`);
    return `${source.slice(0, index)}${text}${source.slice(index)}`;
  }
  if (op.after) {
    const marker = String(op.after);
    const index = source.indexOf(marker);
    if (index < 0) throw new Error(`Marker not found: ${marker}`);
    return `${source.slice(0, index + marker.length)}${text}${source.slice(index + marker.length)}`;
  }
  return `${source}${source.endsWith('\n') ? '' : '\n'}${text}`;
}

function buildDesignElementSelector(element) {
  if (!element || !element.tagName) return '';
  if (element.id) return `#${element.id}`;
  const segments = [];
  let cursor = element;
  while (cursor && cursor.nodeType === 1 && segments.length < 5) {
    const tag = String(cursor.tagName || '').toLowerCase();
    if (!tag) break;
    let segment = tag;
    if (cursor.classList?.length) {
      segment += '.' + Array.from(cursor.classList).slice(0, 3).join('.');
    }
    const parent = cursor.parentElement;
    if (parent) {
      const siblings = Array.from(parent.children).filter((candidate) => candidate.tagName === cursor.tagName);
      if (siblings.length > 1) {
        const index = siblings.indexOf(cursor);
        if (index >= 0) segment += `:nth-of-type(${index + 1})`;
      }
    }
    segments.unshift(segment);
    cursor = cursor.parentElement;
    if (cursor?.id) {
      segments.unshift(`#${cursor.id}`);
      break;
    }
  }
  return segments.join(' > ');
}

function extractDesignElementContext(element, frame) {
  if (!element || !frame) return null;
  const rect = element.getBoundingClientRect();
  const frameRect = frame.getBoundingClientRect();
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  const sourceAnchor = getDesignSelectionSourceAnchor(element);
  return {
    tagName: String(element.tagName || '').toLowerCase(),
    id: element.id || '',
    classList: Array.from(element.classList || []),
    selector: buildDesignElementSelector(element),
    sourceAnchor,
    sourceCandidates: [],
    text: String(element.innerText || element.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 240),
    htmlSnippet: String(element.outerHTML || '').slice(0, 600),
    bounds: {
      x: Math.round(rect.left - frameRect.left),
      y: Math.round(rect.top - frameRect.top),
      width: Math.round(rect.width),
      height: Math.round(rect.height),
    },
    computed: computed ? {
      display: computed.display,
      position: computed.position,
      color: computed.color,
      backgroundColor: computed.backgroundColor,
      font: computed.font,
      fontSize: computed.fontSize,
      fontWeight: computed.fontWeight,
      lineHeight: computed.lineHeight,
      border: computed.border,
      borderRadius: computed.borderRadius,
      padding: computed.padding,
      margin: computed.margin,
    } : {},
  };
}

function getDesignSelectionSourceAnchor(element) {
  const tab = canvasTabs.find((candidate) => candidate.id === activeCanvasTabId);
  const source = String(tab?.content || '');
  const file = String(tab?.diskPath || '');
  if (!source || !file || !element) return file ? { file } : null;

  const countMatches = (needle) => {
    if (!needle) return { index: -1, count: 0 };
    let index = source.indexOf(needle);
    let count = 0;
    let first = index;
    while (index >= 0) {
      count += 1;
      if (count > 1) break;
      index = source.indexOf(needle, index + Math.max(1, needle.length));
    }
    return { index: first, count };
  };
  const id = String(element.id || '').trim();
  const text = String(element.innerText || element.textContent || '').replace(/\s+/g, ' ').trim();
  const candidates = [
    id ? `id="${id}"` : '',
    id ? `id='${id}'` : '',
    text.length >= 2 && text.length <= 160 ? text : '',
  ].filter(Boolean);
  for (const needle of candidates) {
    const match = countMatches(needle);
    if (match.count !== 1 || match.index < 0) continue;
    const before = source.slice(0, match.index);
    return {
      file,
      line: before.split(/\r?\n/).length,
      column: match.index - Math.max(0, before.lastIndexOf('\n') + 1) + 1,
      matchedBy: id && needle.includes(id) ? 'id' : 'text',
    };
  }
  return { file };
}

function getDesignSourceResolverRevision(tab) {
  const source = String(tab?.content || '');
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `${source.length}:${(hash >>> 0).toString(36)}`;
}

async function resolveDesignSelectionSourceCandidates(context) {
  const tab = canvasTabs.find((candidate) => candidate.id === activeCanvasTabId);
  if (!context || !tab?.diskPath) return;
  const selection = {
    selector: String(context.selector || ''),
    id: String(context.id || ''),
    classList: Array.isArray(context.classList) ? context.classList.slice(0, 6) : [],
    text: String(context.text || '').slice(0, 220),
    tagName: String(context.tagName || ''),
  };
  try {
    const response = await fetch('/api/canvas/design-source-resolve', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        sessionId: String(window.activeChatSessionId || window.agentSessionId || 'default'),
        sourcePath: tab.diskPath,
        revision: getDesignSourceResolverRevision(tab),
        sourceContent: String(tab.content || '').slice(0, 768 * 1024),
        selection,
      }),
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || data?.success === false || context !== designSelectedElementContext) return;
    const candidates = Array.isArray(data?.candidates) ? data.candidates.slice(0, 12) : [];
    context.sourceCandidates = candidates;
    if ((!context.sourceAnchor || !context.sourceAnchor.line) && candidates[0]) {
      const first = candidates[0];
      context.sourceAnchor = {
        file: first.file,
        line: first.line,
        column: first.column,
        matchedBy: first.matchedBy,
      };
    }
  } catch {
    // The local active-file anchor remains available if source resolution is
    // temporarily unavailable; selection must never block the chat surface.
  }
}

function getCreativeHtmlMotionElementSelector(element) {
  if (!element || !element.tagName) return '';
  if (element.id) return `#${element.id}`;
  const prometheusId = element.getAttribute?.('data-prometheus-id') || element.getAttribute?.('data-block-id');
  if (prometheusId) return `[data-prometheus-id="${String(prometheusId).replace(/"/g, '\\"')}"]`;
  const role = element.getAttribute?.('data-role');
  if (role) {
    const selector = `[data-role="${String(role).replace(/"/g, '\\"')}"]`;
    try {
      if (element.ownerDocument?.querySelectorAll?.(selector)?.length === 1) return selector;
    } catch {}
  }
  return buildDesignElementSelector(element);
}

function extractCreativeHtmlMotionElementContext(element, frame) {
  if (!element || !frame) return null;
  const tagName = String(element.tagName || '').toLowerCase();
  if (!tagName || ['html', 'head', 'style', 'script', 'meta', 'link'].includes(tagName)) return null;
  const rect = element.getBoundingClientRect();
  if (!rect.width || !rect.height) return null;
  const frameRect = frame.getBoundingClientRect();
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  const clip = normalizeCreativeHtmlMotionClip(creativeHtmlMotionClip);
  const selector = getCreativeHtmlMotionElementSelector(element);
  const pretext = measureCreativeHtmlMotionTextElement(element, frame);
  const dataAttrs = {};
  try {
    Array.from(element.attributes || []).forEach((attr) => {
      if (String(attr.name || '').startsWith('data-')) dataAttrs[attr.name] = String(attr.value || '');
    });
  } catch {}
  return {
    kind: 'html_motion_element',
    clipPath: clip?.path || '',
    clipTitle: clip?.title || '',
    atMs: Number.isFinite(Number(creativeTimelineMs)) ? Number(creativeTimelineMs) : 0,
    tagName,
    id: element.id || '',
    classList: Array.from(element.classList || []),
    selector,
    role: element.getAttribute?.('data-role') || '',
    data: dataAttrs,
    text: String(element.innerText || element.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 360),
    htmlSnippet: String(element.outerHTML || '').slice(0, 1800),
    bounds: {
      x: Math.round(rect.left - frameRect.left),
      y: Math.round(rect.top - frameRect.top),
      width: Math.round(rect.width),
      height: Math.round(rect.height),
    },
    timing: {
      startMs: element.getAttribute?.('data-start') || '',
      durationMs: element.getAttribute?.('data-duration') || '',
      endMs: element.getAttribute?.('data-end') || '',
      trimStartMs: element.getAttribute?.('data-trim-start') || '',
      offsetMs: element.getAttribute?.('data-offset') || '',
    },
    computed: computed ? {
      display: computed.display,
      position: computed.position,
      color: computed.color,
      backgroundColor: computed.backgroundColor,
      font: computed.font,
      fontSize: computed.fontSize,
      fontWeight: computed.fontWeight,
      lineHeight: computed.lineHeight,
      opacity: computed.opacity,
      transform: computed.transform,
      zIndex: computed.zIndex,
      border: computed.border,
      borderRadius: computed.borderRadius,
      padding: computed.padding,
      margin: computed.margin,
    } : {},
    pretext,
  };
}

function parseCreativeHtmlMotionPx(value, fallback = 0) {
  const source = String(value || '').trim();
  const parsed = Number.parseFloat(source);
  return Number.isFinite(parsed) ? parsed : fallback;
}

const CREATIVE_HTML_MOTION_FLUID_LAYOUT_ENABLED = true;
const CREATIVE_HTML_MOTION_LAYOUT_HALO_PX = 18;
const CREATIVE_HTML_MOTION_FLOW_MARGIN_PX = 18;
const CREATIVE_HTML_MOTION_FLOW_EXCLUSION_SELECTOR = '[data-flow-exclusion],[data-layout-exclusion],[data-role="flow-exclusion"],[data-role="exclusion"],[data-role="orb"],.flow-exclusion,.orb';
const CREATIVE_HTML_MOTION_FLOW_TEXT_SELECTOR = '[data-flow-text],[data-role="flow-text"],[data-role="article-text"],[data-role="body-copy"],.flow-text,.article-copy';

function getCreativeHtmlMotionOffsetParent(element, frame) {
  if (!element || !frame) return null;
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  if (computed?.position === 'fixed') return null;
  return element.offsetParent || element.parentElement || frame.contentDocument?.body || null;
}

function getCreativeHtmlMotionLayoutContainer(frame, element = null) {
  const doc = frame?.contentDocument;
  if (!doc) return null;
  return element?.closest?.('[data-role="scene"]') || doc.querySelector('[data-role="scene"]') || doc.getElementById('stage') || doc.body;
}

function getCreativeHtmlMotionPositionInOffsetParent(element, frame, rectOverride = null) {
  const rect = rectOverride || element?.getBoundingClientRect?.();
  if (!element || !frame || !rect) return { position: 'absolute', parent: null, left: 0, top: 0, parentRect: { left: 0, top: 0 } };
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  if (computed?.position === 'fixed') {
    return { position: 'fixed', parent: null, left: rect.left, top: rect.top, parentRect: { left: 0, top: 0 } };
  }
  const parent = getCreativeHtmlMotionOffsetParent(element, frame);
  const parentRect = parent?.getBoundingClientRect?.() || frame.contentDocument?.body?.getBoundingClientRect?.() || { left: 0, top: 0 };
  return {
    position: 'absolute',
    parent,
    left: rect.left - parentRect.left,
    top: rect.top - parentRect.top,
    parentRect,
  };
}

function prepareCreativeHtmlMotionElementForLayoutEdit(element, frame, rectOverride = null) {
  if (!element || !frame) return null;
  const rect = rectOverride || element.getBoundingClientRect();
  const coords = getCreativeHtmlMotionPositionInOffsetParent(element, frame, rect);
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  element.style.position = coords.position || (computed?.position === 'fixed' ? 'fixed' : 'absolute');
  element.style.left = `${Math.round(coords.left)}px`;
  element.style.top = `${Math.round(coords.top)}px`;
  element.style.width = `${Math.max(24, Math.round(rect.width))}px`;
  element.style.minWidth = '24px';
  element.style.boxSizing = 'border-box';
  return coords;
}

function getCreativeHtmlMotionLayoutPriority(element) {
  const explicit = Number(element?.getAttribute?.('data-layout-priority'));
  if (Number.isFinite(explicit)) return explicit;
  const role = String(element?.getAttribute?.('data-role') || '').toLowerCase();
  if (role === 'cta') return 95;
  if (role === 'headline') return 86;
  if (role === 'lower-third') return 78;
  if (role === 'chart') return 64;
  if (element?.classList?.contains?.('kicker')) return 58;
  if (element?.classList?.contains?.('bubble')) return 48;
  return 50;
}

function isCreativeHtmlMotionFluidLayoutBody(element, frame, activeElement = null) {
  if (!element || !frame?.contentWindow || element === frame.contentDocument?.body) return false;
  if (element.id === 'prometheus-html-motion-transform-overlay') return false;
  if (element.closest?.('#prometheus-html-motion-transform-overlay')) return false;
  if (activeElement && element.contains?.(activeElement) && element !== activeElement) return false;
  const rect = element.getBoundingClientRect?.();
  if (!rect || rect.width < 18 || rect.height < 18) return false;
  const computed = frame.contentWindow.getComputedStyle(element);
  if (!computed || computed.display === 'none' || computed.visibility === 'hidden' || Number(computed.opacity) === 0) return false;
  if (element.hasAttribute?.('data-layout-body')) return true;
  const role = String(element.getAttribute?.('data-role') || '').toLowerCase();
  if (['cta', 'lower-third', 'chart', 'headline'].includes(role)) return true;
  if (element.classList?.contains?.('bubble') || element.classList?.contains?.('kicker') || element.classList?.contains?.('stat-card')) return true;
  return false;
}

function isCreativeHtmlMotionFlowExclusion(element) {
  if (!element || element.nodeType !== 1) return false;
  if (element.hasAttribute?.('data-flow-exclusion')) return true;
  if (element.hasAttribute?.('data-layout-exclusion')) return true;
  const role = String(element.getAttribute?.('data-role') || '').toLowerCase();
  if (['flow-exclusion', 'exclusion', 'orb', 'object'].includes(role)) return true;
  return element.classList?.contains?.('orb') || element.classList?.contains?.('flow-exclusion');
}

function isCreativeHtmlMotionFlowTextTarget(element) {
  if (!element || element.nodeType !== 1) return false;
  if (element.hasAttribute?.('data-flow-text')) return true;
  const role = String(element.getAttribute?.('data-role') || '').toLowerCase();
  if (['flow-text', 'article-text', 'body-copy'].includes(role)) return true;
  return element.classList?.contains?.('flow-text') || element.classList?.contains?.('article-copy');
}

function ensureCreativeHtmlMotionFlowStyle(frame) {
  const doc = frame?.contentDocument;
  if (!doc?.head) return;
  let style = doc.getElementById('prometheus-html-motion-flow-style');
  if (style) return;
  style = doc.createElement('style');
  style.id = 'prometheus-html-motion-flow-style';
  style.textContent = `
    .prometheus-html-motion-flow-spacer {
      display:block !important;
      pointer-events:none !important;
      user-select:none !important;
      color:transparent !important;
      overflow:hidden !important;
    }
    [data-prometheus-html-motion-flow-active="true"] {
      text-wrap:pretty;
    }
    [data-prometheus-html-motion-flow-detached="true"] {
      float:none !important;
      shape-outside:none !important;
      margin:0 !important;
    }
  `;
  doc.head.appendChild(style);
}

function removeCreativeHtmlMotionFlowSpacers(frame) {
  const doc = frame?.contentDocument;
  if (!doc) return;
  doc.querySelectorAll('.prometheus-html-motion-flow-spacer').forEach((node) => node.remove());
  doc.querySelectorAll('[data-prometheus-html-motion-flow-active="true"]').forEach((node) => {
    node.removeAttribute('data-prometheus-html-motion-flow-active');
  });
}

function getCreativeHtmlMotionFlowShape(element) {
  const explicit = String(element?.getAttribute?.('data-flow-shape') || element?.getAttribute?.('data-layout-shape') || '').toLowerCase();
  if (explicit) return explicit;
  const computedRadius = String(element?.style?.borderRadius || '').toLowerCase();
  if (element?.classList?.contains?.('orb') || computedRadius.includes('50%') || computedRadius.includes('999')) return 'circle';
  return 'rect';
}

function getCreativeHtmlMotionClosestFlowTextTarget(element) {
  return element?.closest?.(CREATIVE_HTML_MOTION_FLOW_TEXT_SELECTOR) || null;
}

function getCreativeHtmlMotionClosestFlowExclusion(element) {
  return element?.closest?.(CREATIVE_HTML_MOTION_FLOW_EXCLUSION_SELECTOR) || null;
}

function detachCreativeHtmlMotionNestedFlowExclusions(frame) {
  const doc = frame?.contentDocument;
  const win = frame?.contentWindow;
  if (!doc || !win) return;
  Array.from(doc.querySelectorAll(CREATIVE_HTML_MOTION_FLOW_EXCLUSION_SELECTOR)).forEach((element) => {
    if (!isCreativeHtmlMotionFlowExclusion(element)) return;
    if (element.getAttribute('data-prometheus-html-motion-flow-detached') === 'true') return;
    const textElement = getCreativeHtmlMotionClosestFlowTextTarget(element);
    if (!textElement || !textElement.contains(element)) return;
    const rect = element.getBoundingClientRect?.();
    const textRect = textElement.getBoundingClientRect?.();
    if (!rect?.width || !rect?.height || !textRect?.width || !textRect?.height) return;
    const textStyle = win.getComputedStyle(textElement);
    if (textStyle?.position === 'static') textElement.style.position = 'relative';
    element.style.position = 'absolute';
    element.style.left = `${Math.round(rect.left - textRect.left)}px`;
    element.style.top = `${Math.round(rect.top - textRect.top)}px`;
    element.style.width = `${Math.round(rect.width)}px`;
    element.style.height = `${Math.round(rect.height)}px`;
    element.style.float = 'none';
    element.style.margin = '0';
    element.style.shapeOutside = 'none';
    element.style.zIndex = element.style.zIndex || '8';
    element.setAttribute('data-prometheus-html-motion-flow-detached', 'true');
  });
}

function collectCreativeHtmlMotionFlowExclusions(frame) {
  const doc = frame?.contentDocument;
  if (!doc) return [];
  const candidates = Array.from(doc.querySelectorAll(CREATIVE_HTML_MOTION_FLOW_EXCLUSION_SELECTOR));
  return candidates
    .filter((element) => isCreativeHtmlMotionFlowExclusion(element))
    .filter((element) => {
      const rect = element.getBoundingClientRect?.();
      return rect && rect.width >= 8 && rect.height >= 8;
    });
}

function collectCreativeHtmlMotionFlowTextTargets(frame) {
  const doc = frame?.contentDocument;
  if (!doc) return [];
  return Array.from(doc.querySelectorAll(CREATIVE_HTML_MOTION_FLOW_TEXT_SELECTOR))
    .filter((element) => isCreativeHtmlMotionFlowTextTarget(element));
}

function chooseCreativeHtmlMotionFlowExclusionForText(textRect, exclusions) {
  const matches = [];
  exclusions.forEach((element) => {
    const rect = element.getBoundingClientRect();
    const expanded = getCreativeHtmlMotionInflatedRect(rect, CREATIVE_HTML_MOTION_FLOW_MARGIN_PX);
    const overlap = getCreativeHtmlMotionRectOverlap(textRect, expanded);
    if (!overlap) return;
    const area = overlap.overlapX * overlap.overlapY;
    matches.push({ element, rect, expanded, overlap, area });
  });
  return matches.sort((a, b) => {
    const topDelta = a.expanded.top - b.expanded.top;
    if (Math.abs(topDelta) > 8) return topDelta;
    return b.area - a.area;
  }).slice(0, 4);
}

function applyCreativeHtmlMotionFlowSpacer(textElement, exclusion) {
  if (!textElement || !exclusion?.element) return false;
  const textRect = textElement.getBoundingClientRect();
  const exRect = exclusion.rect;
  const side = (exRect.left + exRect.width / 2) < (textRect.left + textRect.width / 2) ? 'left' : 'right';
  const overlapTop = Math.max(0, Math.round(exclusion.expanded.top - textRect.top));
  const overlapHeight = Math.max(16, Math.round(Math.min(textRect.bottom, exclusion.expanded.bottom) - Math.max(textRect.top, exclusion.expanded.top)));
  const intrusion = side === 'left'
    ? Math.max(0, Math.round(exclusion.expanded.right - textRect.left))
    : Math.max(0, Math.round(textRect.right - exclusion.expanded.left));
  const spacerWidth = Math.min(Math.max(24, intrusion), Math.max(24, Math.round(textRect.width * 0.82)));
  const shape = getCreativeHtmlMotionFlowShape(exclusion.element);
  const spacer = textElement.ownerDocument.createElement('span');
  spacer.className = 'prometheus-html-motion-flow-spacer';
  spacer.setAttribute('aria-hidden', 'true');
  spacer.dataset.prometheusFlowSource = getCreativeHtmlMotionElementSelector(exclusion.element);
  spacer.style.cssText = [
    `float:${side}`,
    `width:${spacerWidth}px`,
    `height:${overlapHeight}px`,
    `margin-${side === 'left' ? 'right' : 'left'}:${CREATIVE_HTML_MOTION_FLOW_MARGIN_PX}px`,
    `margin-top:${overlapTop}px`,
    shape === 'circle' ? 'shape-outside:circle(50%)' : 'shape-outside:inset(0 round 12px)',
    shape === 'circle' ? 'clip-path:circle(50%)' : '',
  ].filter(Boolean).join(';');
  textElement.insertBefore(spacer, textElement.firstChild);
  textElement.setAttribute('data-prometheus-html-motion-flow-active', 'true');
  return true;
}

function applyCreativeHtmlMotionFlowAroundExclusions(frame) {
  if (!frame?.contentDocument) return 0;
  try {
    ensureCreativeHtmlMotionFlowStyle(frame);
    removeCreativeHtmlMotionFlowSpacers(frame);
    detachCreativeHtmlMotionNestedFlowExclusions(frame);
    const exclusions = collectCreativeHtmlMotionFlowExclusions(frame);
    const textTargets = collectCreativeHtmlMotionFlowTextTargets(frame);
    let applied = 0;
    textTargets.forEach((textElement) => {
      const textRect = textElement.getBoundingClientRect();
      if (!textRect.width || !textRect.height) return;
      const matches = chooseCreativeHtmlMotionFlowExclusionForText(textRect, exclusions);
      matches.forEach((exclusion) => {
        if (applyCreativeHtmlMotionFlowSpacer(textElement, exclusion)) applied += 1;
      });
    });
    updateCreativeHtmlMotionSpatialDebugOverlay(frame);
    return applied;
  } catch (err) {
    console.warn('[HTML Motion] Flow reflow skipped:', err);
    return 0;
  }
}

function scheduleCreativeHtmlMotionFlowAroundExclusions(frame) {
  if (!frame?.contentDocument) return;
  if (frame._htmlMotionFlowRefreshPending) return;
  frame._htmlMotionFlowRefreshPending = true;
  const raf = frame.contentWindow?.requestAnimationFrame?.bind(frame.contentWindow) || window.requestAnimationFrame || ((callback) => setTimeout(callback, 16));
  raf(() => {
    frame._htmlMotionFlowRefreshPending = false;
    applyCreativeHtmlMotionFlowAroundExclusions(frame);
  });
}

function installCreativeHtmlMotionFlowWatchers(frame) {
  const doc = frame?.contentDocument;
  if (!doc?.documentElement || frame._htmlMotionFlowWatchersReady) return;
  frame._htmlMotionFlowWatchersReady = true;
  try {
    const observer = new frame.contentWindow.MutationObserver((records) => {
      if (records.some((record) => getCreativeHtmlMotionClosestFlowExclusion(record.target) || getCreativeHtmlMotionClosestFlowTextTarget(record.target))) {
        scheduleCreativeHtmlMotionFlowAroundExclusions(frame);
      }
    });
    observer.observe(doc.documentElement, {
      subtree: true,
      attributes: true,
      attributeFilter: ['style', 'class', 'data-drag-x', 'data-drag-y', 'data-dragX', 'data-dragY', 'data-flow-shape', 'data-layout-shape'],
    });
    frame._htmlMotionFlowObserver = observer;
  } catch {}
}

function ensureCreativeHtmlMotionSpatialDebugStyle(frame) {
  const doc = frame?.contentDocument;
  if (!doc?.head) return;
  let style = doc.getElementById('prometheus-html-motion-spatial-debug-style');
  if (style) return;
  style = doc.createElement('style');
  style.id = 'prometheus-html-motion-spatial-debug-style';
  style.textContent = `
    #prometheus-html-motion-spatial-debug-overlay {
      position:absolute; inset:0; z-index:2147483645; pointer-events:none;
    }
    .prometheus-html-motion-debug-box {
      position:absolute; border:2px solid rgba(56,189,248,.95); background:rgba(56,189,248,.08);
      box-shadow:0 0 0 6px rgba(56,189,248,.08); box-sizing:border-box;
    }
    .prometheus-html-motion-debug-box[data-kind="flow-text"] { border-color:rgba(34,197,94,.95); background:rgba(34,197,94,.09); }
    .prometheus-html-motion-debug-box[data-kind="flow-exclusion"] { border-color:rgba(163,255,18,.95); background:rgba(163,255,18,.10); border-radius:999px; }
    .prometheus-html-motion-debug-box[data-kind="halo"] { border:1px dashed rgba(251,191,36,.95); background:rgba(251,191,36,.06); box-shadow:none; }
    .prometheus-html-motion-debug-label {
      position:absolute; left:0; top:-20px; padding:3px 6px; border-radius:6px; background:rgba(2,6,23,.86);
      color:#e0f2fe; font:800 10px/1 Inter,system-ui,sans-serif; white-space:nowrap;
    }
  `;
  doc.head.appendChild(style);
}

function updateCreativeHtmlMotionSpatialDebugOverlay(frame = creativeHtmlMotionLastClickedFrame) {
  const doc = frame?.contentDocument;
  if (!doc?.body) return;
  let overlay = doc.getElementById('prometheus-html-motion-spatial-debug-overlay');
  if (!creativeHtmlMotionSpatialDebugEnabled) {
    if (overlay) overlay.remove();
    return;
  }
  ensureCreativeHtmlMotionSpatialDebugStyle(frame);
  if (!overlay) {
    overlay = doc.createElement('div');
    overlay.id = 'prometheus-html-motion-spatial-debug-overlay';
    doc.body.appendChild(overlay);
  }
  const bodyRect = doc.body.getBoundingClientRect();
  const bodies = collectCreativeHtmlMotionFluidLayoutBodies(frame, null);
  const flows = [...collectCreativeHtmlMotionFlowExclusions(frame), ...collectCreativeHtmlMotionFlowTextTargets(frame)];
  const seen = new Set();
  const rows = [];
  [...bodies, ...flows].forEach((element) => {
    if (!element || seen.has(element)) return;
    seen.add(element);
    const rect = element.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const isFlowText = isCreativeHtmlMotionFlowTextTarget(element);
    const isFlowEx = isCreativeHtmlMotionFlowExclusion(element);
    const kind = isFlowEx ? 'flow-exclusion' : (isFlowText ? 'flow-text' : 'body');
    const label = isFlowEx ? 'flow exclusion' : (isFlowText ? 'flow text' : (element.getAttribute('data-role') || 'layout body'));
    rows.push(`<div class="prometheus-html-motion-debug-box" data-kind="${kind}" style="left:${Math.round(rect.left - bodyRect.left)}px;top:${Math.round(rect.top - bodyRect.top)}px;width:${Math.round(rect.width)}px;height:${Math.round(rect.height)}px"><span class="prometheus-html-motion-debug-label">${label}</span></div>`);
    const halo = getCreativeHtmlMotionInflatedRect(rect, isFlowEx ? CREATIVE_HTML_MOTION_FLOW_MARGIN_PX : CREATIVE_HTML_MOTION_LAYOUT_HALO_PX);
    rows.push(`<div class="prometheus-html-motion-debug-box" data-kind="halo" style="left:${Math.round(halo.left - bodyRect.left)}px;top:${Math.round(halo.top - bodyRect.top)}px;width:${Math.round(halo.width)}px;height:${Math.round(halo.height)}px"></div>`);
  });
  overlay.innerHTML = rows.join('');
}

function collectCreativeHtmlMotionFluidLayoutBodies(frame, activeElement = null) {
  const doc = frame?.contentDocument;
  if (!doc) return [];
  const selector = [
    '[data-layout-body]',
    '[data-role="cta"]',
    '[data-role="lower-third"]',
    '[data-role="chart"]',
    '[data-role="headline"]',
    '.bubble',
    '.kicker',
    '.stat-card',
  ].join(',');
  const elements = new Set(Array.from(doc.querySelectorAll(selector)));
  if (activeElement) elements.add(activeElement);
  return Array.from(elements).filter((element) => isCreativeHtmlMotionFluidLayoutBody(element, frame, activeElement));
}

function getCreativeHtmlMotionInflatedRect(rect, halo = CREATIVE_HTML_MOTION_LAYOUT_HALO_PX) {
  return {
    left: rect.left - halo,
    top: rect.top - halo,
    right: rect.right + halo,
    bottom: rect.bottom + halo,
    width: rect.width + halo * 2,
    height: rect.height + halo * 2,
  };
}

function getCreativeHtmlMotionRectOverlap(a, b) {
  const overlapX = Math.min(a.right, b.right) - Math.max(a.left, b.left);
  const overlapY = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
  if (overlapX <= 0 || overlapY <= 0) return null;
  return { overlapX, overlapY };
}

function rememberCreativeHtmlMotionFluidElement(state, element) {
  if (!state?.fluidPreviousStyles || !element) return;
  if (!state.fluidPreviousStyles.has(element)) {
    state.fluidPreviousStyles.set(element, element.getAttribute('style') || '');
  }
}

function markCreativeHtmlMotionFluidElementChanged(state, element) {
  if (!state?.fluidChangedElements || !element || element === state.element) return;
  state.fluidChangedElements.add(element);
}

function moveCreativeHtmlMotionFluidElement(state, element, dx, dy) {
  if (!state?.frame || !element || (!dx && !dy)) return false;
  rememberCreativeHtmlMotionFluidElement(state, element);
  const rect = element.getBoundingClientRect();
  const container = getCreativeHtmlMotionLayoutContainer(state.frame, element);
  const containerRect = container?.getBoundingClientRect?.();
  prepareCreativeHtmlMotionElementForLayoutEdit(element, state.frame, rect);
  const left = parseCreativeHtmlMotionPx(element.style.left, 0);
  const top = parseCreativeHtmlMotionPx(element.style.top, 0);
  let nextLeft = left + dx;
  let nextTop = top + dy;
  if (containerRect) {
    const coords = getCreativeHtmlMotionPositionInOffsetParent(element, state.frame, rect);
    const viewportLeft = coords.parentRect.left + nextLeft;
    const viewportTop = coords.parentRect.top + nextTop;
    if (viewportLeft < containerRect.left) nextLeft += containerRect.left - viewportLeft;
    if (viewportTop < containerRect.top) nextTop += containerRect.top - viewportTop;
    if (viewportLeft + rect.width > containerRect.right) nextLeft -= (viewportLeft + rect.width) - containerRect.right;
    if (viewportTop + rect.height > containerRect.bottom) nextTop -= (viewportTop + rect.height) - containerRect.bottom;
  }
  element.style.left = `${Math.round(nextLeft)}px`;
  element.style.top = `${Math.round(nextTop)}px`;
  element.style.transition = 'left 120ms cubic-bezier(.16,1,.3,1), top 120ms cubic-bezier(.16,1,.3,1), width 120ms cubic-bezier(.16,1,.3,1), height 120ms cubic-bezier(.16,1,.3,1)';
  const changed = Math.abs(nextLeft - left) >= 1 || Math.abs(nextTop - top) >= 1;
  if (changed) markCreativeHtmlMotionFluidElementChanged(state, element);
  if (isCreativeHtmlMotionElementTextEditable(element)) {
    applyCreativeHtmlMotionPretextInlineFeedback(element, state.frame, String(element.textContent || ''));
  }
  return changed;
}

function resizeCreativeHtmlMotionFluidElement(state, element, axis, amount) {
  if (!state?.frame || !element || !amount) return false;
  rememberCreativeHtmlMotionFluidElement(state, element);
  const rect = element.getBoundingClientRect();
  prepareCreativeHtmlMotionElementForLayoutEdit(element, state.frame, rect);
  const minWidth = Math.max(120, Number(element.getAttribute?.('data-layout-min-width')) || 120);
  const minHeight = Math.max(56, Number(element.getAttribute?.('data-layout-min-height')) || 56);
  let nextWidth = rect.width;
  let nextHeight = rect.height;
  if (axis === 'x') nextWidth = Math.max(minWidth, rect.width - Math.abs(amount));
  else nextHeight = Math.max(minHeight, rect.height - Math.abs(amount));
  const changed = Math.abs(nextWidth - rect.width) >= 1 || Math.abs(nextHeight - rect.height) >= 1;
  if (!changed) return false;
  element.style.width = `${Math.round(nextWidth)}px`;
  element.style.height = `${Math.round(nextHeight)}px`;
  element.style.minWidth = `${Math.round(minWidth)}px`;
  element.style.boxSizing = 'border-box';
  element.style.transition = 'left 120ms cubic-bezier(.16,1,.3,1), top 120ms cubic-bezier(.16,1,.3,1), width 120ms cubic-bezier(.16,1,.3,1), height 120ms cubic-bezier(.16,1,.3,1)';
  markCreativeHtmlMotionFluidElementChanged(state, element);
  if (isCreativeHtmlMotionElementTextEditable(element)) {
    applyCreativeHtmlMotionPretextInlineFeedback(element, state.frame, String(element.textContent || ''));
  }
  return true;
}

function runCreativeHtmlMotionFluidLayoutPass(state) {
  const bodies = collectCreativeHtmlMotionFluidLayoutBodies(state.frame, state.element).map((element) => ({
    element,
    priority: element === state.element ? 1000 : getCreativeHtmlMotionLayoutPriority(element),
    rect: element.getBoundingClientRect(),
  }));
  let moved = false;
  for (let i = 0; i < bodies.length; i += 1) {
    for (let j = i + 1; j < bodies.length; j += 1) {
      const a = bodies[i];
      const b = bodies[j];
      if (!a?.element || !b?.element) continue;
      const overlap = getCreativeHtmlMotionRectOverlap(getCreativeHtmlMotionInflatedRect(a.rect), getCreativeHtmlMotionInflatedRect(b.rect));
      if (!overlap) continue;
      const moveA = a.element !== state.element && (b.element === state.element || a.priority <= b.priority);
      const mover = moveA ? a : b;
      const anchor = moveA ? b : a;
      if (mover.element === state.element) continue;
      const moverCenterX = mover.rect.left + mover.rect.width / 2;
      const moverCenterY = mover.rect.top + mover.rect.height / 2;
      const anchorCenterX = anchor.rect.left + anchor.rect.width / 2;
      const anchorCenterY = anchor.rect.top + anchor.rect.height / 2;
      let dx = 0;
      let dy = 0;
      if (overlap.overlapX < overlap.overlapY) {
        dx = (moverCenterX < anchorCenterX ? -1 : 1) * Math.ceil(overlap.overlapX + 4);
      } else {
        dy = (moverCenterY < anchorCenterY ? -1 : 1) * Math.ceil(overlap.overlapY + 4);
      }
      if (moveCreativeHtmlMotionFluidElement(state, mover.element, dx, dy)) {
        moved = true;
      } else if (resizeCreativeHtmlMotionFluidElement(state, mover.element, overlap.overlapX < overlap.overlapY ? 'x' : 'y', overlap.overlapX < overlap.overlapY ? overlap.overlapX + 4 : overlap.overlapY + 4)) {
        moved = true;
      }
    }
  }
  return moved;
}

function runCreativeHtmlMotionFluidLayout(state) {
  if (state?.frame) applyCreativeHtmlMotionFlowAroundExclusions(state.frame);
  if (!CREATIVE_HTML_MOTION_FLUID_LAYOUT_ENABLED || !state?.frame || !state?.element) return;
  for (let pass = 0; pass < 6; pass += 1) {
    if (!runCreativeHtmlMotionFluidLayoutPass(state)) break;
  }
  applyCreativeHtmlMotionFlowAroundExclusions(state.frame);
}

function getCreativeHtmlMotionStylePatchFromElement(element) {
  if (!element) return null;
  const patch = {
    position: element.style.position || 'absolute',
    left: element.style.left,
    top: element.style.top,
    width: element.style.width,
    height: element.style.height,
    minWidth: element.style.minWidth,
    boxSizing: element.style.boxSizing,
  };
  Object.keys(patch).forEach((key) => {
    if (!String(patch[key] ?? '').trim()) delete patch[key];
  });
  return patch;
}

function captureCreativeHtmlMotionTemporaryMotionStyle(element) {
  if (!element?.style) return null;
  return {
    animation: element.style.getPropertyValue('animation') || '',
    transition: element.style.getPropertyValue('transition') || '',
    transform: element.style.getPropertyValue('transform') || '',
  };
}

function restoreCreativeHtmlMotionTemporaryMotionStyle(element, captured) {
  if (!element?.style || !captured) return;
  ['animation', 'transition', 'transform'].forEach((property) => {
    const value = String(captured[property] || '').trim();
    if (value) element.style.setProperty(property, value);
    else element.style.removeProperty(property);
  });
}

function restoreCreativeHtmlMotionFluidPreviousStyles(state) {
  state?.fluidPreviousStyles?.forEach((style, element) => {
    try { element.setAttribute('style', style || ''); } catch {}
  });
}

function buildCreativeHtmlMotionFlowOrbHtml(frame, textElement) {
  const rect = textElement?.getBoundingClientRect?.();
  const coords = textElement && frame && rect ? getCreativeHtmlMotionPositionInOffsetParent(textElement, frame, rect) : null;
  const size = Math.max(150, Math.min(340, Math.round(Math.min(rect?.width || 320, rect?.height || 320) * 0.42)));
  const left = Math.round((coords?.left || 80) + Math.max(24, (rect?.width || 640) * 0.08));
  const top = Math.round((coords?.top || 120) + Math.max(24, (rect?.height || 420) * 0.38));
  const id = `prom-flow-orb-${Date.now().toString(36)}`;
  return `<div id="${id}" class="prom-flow-orb flow-exclusion" data-role="orb" data-layout-body="flow-object" data-flow-exclusion data-flow-shape="circle" data-layout-priority="72" style="position:absolute;left:${left}px;top:${top}px;width:${size}px;height:${size}px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 36% 31%,#f7ffb0 0%,#a3ff12 32%,rgba(80,180,20,.64) 58%,rgba(80,180,20,.12) 72%,transparent 74%);box-shadow:0 0 64px rgba(163,255,18,.62),0 0 0 2px rgba(163,255,18,.38);z-index:2;box-sizing:border-box;"><span style="font:950 11px/1 Inter,system-ui,sans-serif;letter-spacing:.2em;color:#1a2508;text-transform:uppercase;pointer-events:none;">FLOW OBJECT</span></div>`;
}

function getCreativeHtmlMotionLineHeightPx(computed, fontSize) {
  const raw = String(computed?.lineHeight || '').trim();
  const parsed = Number.parseFloat(raw);
  if (Number.isFinite(parsed)) {
    if (raw.endsWith('px')) return Math.max(fontSize, parsed);
    if (!raw || raw === 'normal') return Math.max(fontSize, fontSize * 1.2);
    return parsed <= 4 ? Math.max(fontSize, fontSize * parsed) : parsed;
  }
  return Math.max(fontSize, fontSize * 1.2);
}

function measureCreativeHtmlMotionTextElement(element, frame, textOverride = null) {
  if (!element || !frame) return null;
  const text = textOverride == null
    ? String(element.innerText || element.textContent || '')
    : String(textOverride || '');
  if (!text.trim()) return null;
  const rect = element.getBoundingClientRect();
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  if (!computed || !rect.width) return null;
  const fontSize = Math.max(8, parseCreativeHtmlMotionPx(computed.fontSize, 16));
  const lineHeightPx = getCreativeHtmlMotionLineHeightPx(computed, fontSize);
  const width = Math.max(8, Math.floor(rect.width));
  const availableHeight = Math.max(0, Math.floor(rect.height));
  const fontSpec = computed.font && computed.font !== ''
    ? computed.font
    : `${computed.fontStyle || 'normal'} ${computed.fontWeight || 400} ${fontSize}px ${computed.fontFamily || 'Inter'}`;
  const measurement = measureTextBlock(text, fontSpec, width, lineHeightPx, {
    fontSize,
    fontWeight: computed.fontWeight,
    fontFamily: computed.fontFamily,
    fontStyle: computed.fontStyle,
  });
  const measuredHeight = Math.ceil(Number(measurement?.height) || 0);
  return {
    engine: measurement?.kind || 'fallback',
    fontSpec: measurement?.fontSpec || fontSpec,
    lineCount: Math.max(1, Number(measurement?.lineCount) || 1),
    lineHeightPx: Math.round(Number(measurement?.lineHeightPx) || lineHeightPx),
    measuredHeight,
    availableWidth: Math.round(width),
    availableHeight,
    overflowY: availableHeight > 0 && measuredHeight > availableHeight + 2,
  };
}

function applyCreativeHtmlMotionPretextInlineFeedback(element, frame, textOverride = null) {
  const measurement = measureCreativeHtmlMotionTextElement(element, frame, textOverride);
  if (!measurement) return null;
  const message = `PreText: ${measurement.lineCount} line${measurement.lineCount === 1 ? '' : 's'}, ${measurement.measuredHeight}px measured / ${measurement.availableHeight}px box`;
  element.dataset.prometheusHtmlMotionPretext = message;
  element.title = message;
  if (measurement.overflowY) {
    element.style.outline = '2px solid #fb7185';
    element.style.boxShadow = '0 0 0 5px rgba(251,113,133,0.20), inset 0 0 0 9999px rgba(251,113,133,0.08)';
  } else {
    element.style.outline = '2px solid #22c55e';
    element.style.boxShadow = '0 0 0 5px rgba(34,197,94,0.18), inset 0 0 0 9999px rgba(34,197,94,0.06)';
  }
  return measurement;
}

function getCreativeHtmlMotionPointerMode(event, element) {
  const rect = element?.getBoundingClientRect?.();
  if (!rect) return 'move';
  const edge = 18;
  const nearRight = Number(event.clientX) >= rect.right - edge;
  const nearBottom = Number(event.clientY) >= rect.bottom - edge;
  if (nearRight || nearBottom) return 'resize';
  return 'move';
}

function maybeStartCreativeHtmlMotionDirectManipulation(event, frame) {
  if (!frame || event.button !== 0) return;
  const handle = event.target?.closest?.('[data-prometheus-html-motion-handle]');
  const target = handle ? creativeHtmlMotionLastClickedElement : getCreativeHtmlMotionSelectableTarget(event.target, frame);
  if (!target || target !== creativeHtmlMotionLastClickedElement) return;
  if (!target.hasAttribute('data-prometheus-html-motion-selected')) return;
  if (target.getAttribute('contenteditable') === 'true') return;
  const mode = handle
    ? (String(handle.getAttribute('data-prometheus-html-motion-handle') || '') === 'move' ? 'move' : 'resize')
    : getCreativeHtmlMotionPointerMode(event, target);
  const rect = target.getBoundingClientRect();
  const computed = frame.contentWindow?.getComputedStyle?.(target);
  if (!computed) return;
  event.preventDefault();
  event.stopPropagation();
  const doc = frame.contentDocument;
  const previousInlineStyle = target.getAttribute('style') || '';
  const previousMotionStyle = captureCreativeHtmlMotionTemporaryMotionStyle(target);
  target.style.animation = 'none';
  target.style.transition = 'none';
  target.style.transform = 'none';
  const coords = prepareCreativeHtmlMotionElementForLayoutEdit(target, frame, rect);
  const baseLeft = parseCreativeHtmlMotionPx(target.style.left, coords?.left || 0);
  const baseTop = parseCreativeHtmlMotionPx(target.style.top, coords?.top || 0);
  creativeHtmlMotionDragState = {
    frame,
    element: target,
    mode,
    pointerId: event.pointerId,
    startClientX: event.clientX,
    startClientY: event.clientY,
    baseLeft,
    baseTop,
    baseWidth: Math.max(24, rect.width),
    baseHeight: Math.max(24, rect.height),
    previousInlineStyle,
    previousMotionStyle,
    fluidPreviousStyles: new Map(),
    fluidChangedElements: new Set(),
    moved: false,
    textAware: isCreativeHtmlMotionElementTextEditable(target),
  };
  target.setPointerCapture?.(event.pointerId);
  hideCreativeHtmlMotionPopovers();
  target.style.cursor = mode === 'resize' ? 'nwse-resize' : 'move';
  doc.addEventListener('pointermove', handleCreativeHtmlMotionDirectManipulationMove, true);
  doc.addEventListener('pointerup', handleCreativeHtmlMotionDirectManipulationEnd, true);
  doc.addEventListener('pointercancel', handleCreativeHtmlMotionDirectManipulationCancel, true);
}

function handleCreativeHtmlMotionDirectManipulationMove(event) {
  const state = creativeHtmlMotionDragState;
  if (!state?.element || event.pointerId !== state.pointerId) return;
  event.preventDefault();
  event.stopPropagation();
  const dx = event.clientX - state.startClientX;
  const dy = event.clientY - state.startClientY;
  if (Math.abs(dx) > 2 || Math.abs(dy) > 2) state.moved = true;
  if (state.mode === 'resize') {
    const width = Math.max(36, Math.round(state.baseWidth + dx));
    const height = Math.max(24, Math.round(state.baseHeight + dy));
    state.element.style.width = `${width}px`;
    state.element.style.height = `${height}px`;
    runCreativeHtmlMotionFluidLayout(state);
  } else {
    state.element.style.left = `${Math.round(state.baseLeft + dx)}px`;
    state.element.style.top = `${Math.round(state.baseTop + dy)}px`;
    runCreativeHtmlMotionFluidLayout(state);
  }
  if (state.textAware) applyCreativeHtmlMotionPretextInlineFeedback(state.element, state.frame, String(state.element.textContent || ''));
  updateCreativeHtmlMotionTransformOverlay(state.frame, state.element);
}

async function handleCreativeHtmlMotionDirectManipulationEnd(event) {
  const state = creativeHtmlMotionDragState;
  if (!state?.element || event.pointerId !== state.pointerId) return;
  cleanupCreativeHtmlMotionDirectManipulationListeners(state);
  event.preventDefault();
  event.stopPropagation();
  state.frame._htmlMotionSuppressClick = true;
  state.element.style.cursor = '';
  const measurement = state.textAware ? measureCreativeHtmlMotionTextElement(state.element, state.frame) : null;
  try {
    if (state.moved) {
      const stylePatches = [{
        selector: getCreativeHtmlMotionElementSelector(state.element),
        stylePatch: getCreativeHtmlMotionStylePatchFromElement(state.element),
      }];
      state.fluidChangedElements?.forEach((element) => {
        stylePatches.push({
          selector: getCreativeHtmlMotionElementSelector(element),
          stylePatch: getCreativeHtmlMotionStylePatchFromElement(element),
        });
      });
      await patchCreativeHtmlMotionElementStylesBySelectors(
        stylePatches,
        `${state.mode === 'resize' ? 'Resize' : 'Move'} selected HTML motion element${state.textAware ? ' with PreText fit feedback' : ''}${state.fluidChangedElements?.size ? ' and fluid panel negotiation' : ''}.`
      );
      showToast(
        measurement?.overflowY ? 'HTML Motion: layout updated, but text may overflow.' : 'HTML Motion: layout updated.',
        measurement
          ? (measurement.overflowY ? 'PreText measured the text taller than the resized box.' : `PreText fit check passed${state.fluidChangedElements?.size ? `; ${state.fluidChangedElements.size} nearby panel${state.fluidChangedElements.size === 1 ? '' : 's'} negotiated.` : '.'}`)
          : `Element position/size patched${state.fluidChangedElements?.size ? `; ${state.fluidChangedElements.size} nearby panel${state.fluidChangedElements.size === 1 ? '' : 's'} negotiated.` : '.'}`,
        measurement?.overflowY ? 'warn' : 'success'
      );
      restoreCreativeHtmlMotionTemporaryMotionStyle(state.element, state.previousMotionStyle);
      syncCreativeHtmlMotionTimelinePosition(creativeTimelineMs, { playing: isCreativePlaybackActive(), forceSeek: true });
    }
  } catch (err) {
    state.element.setAttribute('style', state.previousInlineStyle);
    restoreCreativeHtmlMotionFluidPreviousStyles(state);
    showToast(`HTML motion layout edit failed: ${err.message || err}`, 'error');
  } finally {
    creativeHtmlMotionDragState = null;
    if (state.textAware) {
      state.element.style.outline = '';
      state.element.style.boxShadow = '';
      state.element.removeAttribute('title');
      delete state.element.dataset.prometheusHtmlMotionPretext;
    }
    restoreCreativeHtmlMotionTemporaryMotionStyle(state.element, state.previousMotionStyle);
    applyCreativeHtmlMotionPreviewSelection(state.element, state.frame);
    setTimeout(() => { state.frame._htmlMotionSuppressClick = false; }, 80);
  }
}

function handleCreativeHtmlMotionDirectManipulationCancel(event) {
  const state = creativeHtmlMotionDragState;
  if (!state?.element || event.pointerId !== state.pointerId) return;
  cleanupCreativeHtmlMotionDirectManipulationListeners(state);
  state.element.setAttribute('style', state.previousInlineStyle);
  restoreCreativeHtmlMotionFluidPreviousStyles(state);
  creativeHtmlMotionDragState = null;
}

function cleanupCreativeHtmlMotionDirectManipulationListeners(state) {
  const doc = state?.frame?.contentDocument;
  if (!doc) return;
  doc.removeEventListener('pointermove', handleCreativeHtmlMotionDirectManipulationMove, true);
  doc.removeEventListener('pointerup', handleCreativeHtmlMotionDirectManipulationEnd, true);
  doc.removeEventListener('pointercancel', handleCreativeHtmlMotionDirectManipulationCancel, true);
}

async function patchCreativeHtmlMotionElementStyleBySelection(stylePatch = {}, reason = 'Patch selected HTML motion element style.') {
  const selector = String(creativeHtmlMotionSelectedElementContext?.selector || '').trim();
  if (!selector) throw new Error('No selected HTML motion selector is available.');
  return patchCreativeHtmlMotionElementStylesBySelectors([{ selector, stylePatch }], reason);
}

async function patchCreativeHtmlMotionElementStylesBySelectors(stylePatches = [], reason = 'Patch HTML motion element styles.') {
  const normalized = (Array.isArray(stylePatches) ? stylePatches : [])
    .map((entry) => ({
      selector: String(entry?.selector || '').trim(),
      stylePatch: entry?.stylePatch || {},
    }))
    .filter((entry) => entry.selector && entry.stylePatch && Object.keys(entry.stylePatch).length);
  if (!normalized.length) throw new Error('No HTML motion style patches were provided.');
  const read = await readCreativeHtmlMotionClip({ includeHtml: true });
  const html = String(read?.clip?.html || read?.html || '');
  if (!html) throw new Error('Could not read active HTML motion clip HTML.');
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  const ops = [];
  normalized.forEach(({ selector, stylePatch }) => {
    const target = doc.querySelector(selector);
    if (!target) throw new Error(`Could not find selected element in clip HTML: ${selector}`);
    const beforeOuter = String(target.outerHTML || '');
    Object.entries(stylePatch || {}).forEach(([key, value]) => {
      const val = String(value ?? '').trim();
      if (!val) return;
      target.style[key] = val;
    });
    const afterOuter = String(target.outerHTML || '');
    if (!beforeOuter || !afterOuter || beforeOuter === afterOuter) return;
    ops.push({ op: 'replace_text', find: beforeOuter, replace: afterOuter, occurrence: 1 });
  });
  if (!ops.length) {
    throw new Error('Selected element style did not change.');
  }
  return patchCreativeHtmlMotionClip({
    reason,
    ops,
  });
}

async function handleCreativeHtmlMotionSeparateFlowObject() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  const element = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!element || !frame) return;
  try {
    const selector = getCreativeHtmlMotionElementSelector(element);
    if (!selector) throw new Error('No selected HTML motion selector is available.');
    const read = await readCreativeHtmlMotionClip({ includeHtml: true });
    const html = String(read?.clip?.html || read?.html || '');
    if (!html) throw new Error('Could not read active HTML motion clip HTML.');
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const target = doc.querySelector(selector);
    if (!target) throw new Error(`Could not find selected element in clip HTML: ${selector}`);
    const beforeOuter = String(target.outerHTML || '');
    target.setAttribute('data-flow-text', '');
    target.setAttribute('data-layout-body', target.getAttribute('data-layout-body') || 'flow-text');
    if (!target.getAttribute('data-role')) target.setAttribute('data-role', 'flow-text');
    const style = String(target.getAttribute('style') || '');
    const rect = element.getBoundingClientRect();
    const coords = getCreativeHtmlMotionPositionInOffsetParent(element, frame, rect);
    if (!/position\s*:/i.test(style)) target.style.position = coords.position || 'absolute';
    if (!/left\s*:/i.test(style)) target.style.left = `${Math.round(coords.left)}px`;
    if (!/top\s*:/i.test(style)) target.style.top = `${Math.round(coords.top)}px`;
    if (!/width\s*:/i.test(style)) target.style.width = `${Math.max(24, Math.round(rect.width))}px`;
    if (!/min-width\s*:/i.test(style)) target.style.minWidth = '24px';
    if (!/box-sizing\s*:/i.test(style)) target.style.boxSizing = 'border-box';
    const orbHtml = buildCreativeHtmlMotionFlowOrbHtml(frame, element);
    const afterOuter = `${orbHtml}${String(target.outerHTML || '')}`;
    if (!beforeOuter || beforeOuter === afterOuter) throw new Error('Selected flow text did not change.');
    await patchCreativeHtmlMotionClip({
      reason: 'Separate selected HTML motion text into flow text plus a draggable flow-exclusion object.',
      ops: [{ op: 'replace_text', find: beforeOuter, replace: afterOuter, occurrence: 1 }],
    });
    showToast('HTML Motion: flow object separated.', 'A draggable orb was added and the selected copy now participates in flow wrapping.', 'success');
  } catch (err) {
    showToast(`HTML motion separate flow object failed: ${err.message || err}`, 'error');
  }
}

function buildCreativeHtmlMotionPretextFontSpec(computed, fontSize) {
  return `${computed?.fontStyle || 'normal'} ${computed?.fontWeight || 400} ${fontSize}px ${computed?.fontFamily || 'Inter'}`;
}

function measureCreativeHtmlMotionTextForSize(element, frame, fontSize, width = null, height = null) {
  if (!element || !frame) return null;
  const computed = frame.contentWindow?.getComputedStyle?.(element);
  if (!computed) return null;
  const rect = element.getBoundingClientRect();
  const targetWidth = Math.max(8, Math.floor(Number(width) || rect.width || 0));
  const targetHeight = Math.max(0, Math.floor(Number(height) || rect.height || 0));
  const currentFontSize = Math.max(8, parseCreativeHtmlMotionPx(computed.fontSize, 16));
  const currentLineHeightPx = getCreativeHtmlMotionLineHeightPx(computed, currentFontSize);
  const lineHeightRatio = Math.max(0.8, Math.min(2.2, currentLineHeightPx / Math.max(1, currentFontSize)));
  const lineHeightPx = Math.max(fontSize, fontSize * lineHeightRatio);
  const text = String(element.innerText || element.textContent || '');
  const measurement = measureTextBlock(text, buildCreativeHtmlMotionPretextFontSpec(computed, fontSize), targetWidth, lineHeightPx, {
    fontSize,
    fontWeight: computed.fontWeight,
    fontFamily: computed.fontFamily,
    fontStyle: computed.fontStyle,
  });
  const measuredHeight = Math.ceil(Number(measurement?.height) || 0);
  return {
    fontSize,
    lineHeightRatio,
    lineHeightPx,
    measuredHeight,
    lineCount: Math.max(1, Number(measurement?.lineCount) || 1),
    availableWidth: targetWidth,
    availableHeight: targetHeight,
    overflowY: targetHeight > 0 && measuredHeight > targetHeight + 2,
  };
}

async function patchSelectedCreativeHtmlMotionTextStyle(stylePatch, reason, successTitle = 'HTML Motion: text layout updated.') {
  const element = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!element || !frame || !isCreativeHtmlMotionElementTextEditable(element)) return null;
  Object.entries(stylePatch || {}).forEach(([key, value]) => {
    const val = String(value ?? '').trim();
    if (val) element.style[key] = val;
  });
  const measurement = applyCreativeHtmlMotionPretextInlineFeedback(element, frame, String(element.textContent || ''));
  updateCreativeHtmlMotionTransformOverlay(frame, element);
  const result = await patchCreativeHtmlMotionElementStyleBySelection(stylePatch, reason);
  showToast(
    measurement?.overflowY ? `${successTitle} It may overflow.` : successTitle,
    measurement?.overflowY ? 'PreText measured the text taller than the selected box.' : 'PreText fit check passed.',
    measurement?.overflowY ? 'warn' : 'success'
  );
  applyCreativeHtmlMotionPreviewSelection(element, frame);
  creativeHtmlMotionSelectedElementContext = extractCreativeHtmlMotionElementContext(element, frame);
  updateDesignSelectionChip();
  return result;
}

function getCreativeHtmlMotionSelectableTarget(target, frame) {
  if (!target || !frame?.contentWindow) return null;
  const HTMLElementCtor = frame.contentWindow.HTMLElement;
  if (!(target instanceof HTMLElementCtor)) return null;
  let cursor = target;
  let firstVisible = null;
  const skipTags = new Set(['html', 'body', 'main', 'style', 'script', 'meta', 'link']);
  while (cursor && cursor instanceof HTMLElementCtor) {
    const tag = String(cursor.tagName || '').toLowerCase();
    if (cursor.classList?.contains?.('prometheus-html-motion-flow-spacer')) {
      cursor = cursor.parentElement;
      continue;
    }
    const rect = cursor.getBoundingClientRect?.();
    if (!skipTags.has(tag) && rect && rect.width >= 4 && rect.height >= 4) {
      if (!firstVisible) firstVisible = cursor;
      const role = String(cursor.getAttribute?.('data-role') || '').toLowerCase();
      const isComponentRoot = cursor.hasAttribute?.('data-prometheus-edit-root')
        || cursor.hasAttribute?.('data-layout-body')
        || cursor.hasAttribute?.('data-track-index')
        || (cursor.hasAttribute?.('data-start') && cursor.hasAttribute?.('data-duration'))
        || (role && !['stage', 'texture', 'glow'].includes(role));
      if (isComponentRoot) return cursor;
    }
    cursor = cursor.parentElement;
  }
  return firstVisible;
}

function applyCreativeHtmlMotionPreviewSelection(element, frame) {
  const doc = frame?.contentDocument;
  if (!doc) return;
  doc.querySelectorAll('[data-prometheus-html-motion-selected="true"]').forEach((node) => {
    node.removeAttribute('data-prometheus-html-motion-selected');
  });
  if (element && element instanceof frame.contentWindow.HTMLElement) {
    element.setAttribute('data-prometheus-html-motion-selected', 'true');
    creativeHtmlMotionSelectedElementContext = extractCreativeHtmlMotionElementContext(element, frame);
    creativeHtmlMotionLastClickedElement = element;
    creativeHtmlMotionLastClickedFrame = frame;
    ensureCreativeHtmlMotionTransformOverlay(frame);
    updateCreativeHtmlMotionTransformOverlay(frame, element);
    updateDesignSelectionChip();
    addProcessEntry('info', `HTML Motion: selected ${creativeHtmlMotionSelectedElementContext?.selector || creativeHtmlMotionSelectedElementContext?.tagName || 'element'} in video preview.`);
  } else {
    clearCreativeHtmlMotionSelectionContext();
  }
}

function ensureCreativeHtmlMotionTransformOverlay(frame) {
  const doc = frame?.contentDocument;
  if (!doc?.body) return null;
  let overlay = doc.getElementById('prometheus-html-motion-transform-overlay');
  if (overlay) return overlay;
  overlay = doc.createElement('div');
  overlay.id = 'prometheus-html-motion-transform-overlay';
  overlay.innerHTML = `
    <div data-prometheus-html-motion-handle="move" title="Drag to move"></div>
    <div data-prometheus-html-motion-handle="nw" title="Resize"></div>
    <div data-prometheus-html-motion-handle="ne" title="Resize"></div>
    <div data-prometheus-html-motion-handle="sw" title="Resize"></div>
    <div data-prometheus-html-motion-handle="se" title="Resize"></div>
  `;
  overlay.style.cssText = 'position:absolute;display:none;z-index:2147483646;pointer-events:none;border:2px solid #38bdf8;border-radius:6px;box-shadow:0 0 0 5px rgba(56,189,248,.14);box-sizing:border-box';
  doc.body.appendChild(overlay);
  const move = overlay.querySelector('[data-prometheus-html-motion-handle="move"]');
  if (move) {
    move.style.cssText = 'position:absolute;inset:0;pointer-events:auto;background:rgba(56,189,248,.02)';
    move.style.setProperty('cursor', 'move', 'important');
  }
  ['nw','ne','sw','se'].forEach((id) => {
    const handle = overlay.querySelector(`[data-prometheus-html-motion-handle="${id}"]`);
    if (!handle) return;
    const x = id.includes('e') ? 'right:-8px' : 'left:-8px';
    const y = id.includes('s') ? 'bottom:-8px' : 'top:-8px';
    handle.style.cssText = `position:absolute;${x};${y};width:14px;height:14px;border-radius:4px;background:#38bdf8;border:2px solid rgba(2,6,23,.95);box-shadow:0 8px 18px rgba(2,6,23,.35);pointer-events:auto;box-sizing:border-box`;
    handle.style.setProperty('cursor', 'nwse-resize', 'important');
  });
  return overlay;
}

function updateCreativeHtmlMotionTransformOverlay(frame, element) {
  const overlay = ensureCreativeHtmlMotionTransformOverlay(frame);
  const doc = frame?.contentDocument;
  if (!overlay || !doc?.body || !element) return;
  const rect = element.getBoundingClientRect();
  const bodyRect = doc.body.getBoundingClientRect();
  overlay.style.display = 'block';
  overlay.style.left = `${Math.round(rect.left - bodyRect.left)}px`;
  overlay.style.top = `${Math.round(rect.top - bodyRect.top)}px`;
  overlay.style.width = `${Math.max(1, Math.round(rect.width))}px`;
  overlay.style.height = `${Math.max(1, Math.round(rect.height))}px`;
}

function hideCreativeHtmlMotionTransformOverlay(frame = creativeHtmlMotionLastClickedFrame) {
  try {
    const overlay = frame?.contentDocument?.getElementById?.('prometheus-html-motion-transform-overlay');
    if (overlay) overlay.style.display = 'none';
  } catch {}
}

function setupCreativeHtmlMotionPreviewSelection(frame) {
  const doc = frame?.contentDocument;
  if (!doc || !doc.documentElement) return;
  let styleEl = doc.getElementById('prometheus-html-motion-selection-style');
  if (!styleEl) {
    styleEl = doc.createElement('style');
    styleEl.id = 'prometheus-html-motion-selection-style';
    styleEl.textContent = `
      [data-prometheus-html-motion-selected="true"] {
        outline: 2px solid #38bdf8 !important;
        outline-offset: 3px !important;
        box-shadow: 0 0 0 5px rgba(56,189,248,0.18), inset 0 0 0 9999px rgba(56,189,248,0.07) !important;
      }
      [data-prometheus-html-motion-hover="true"] {
        outline: 1px dashed rgba(251,191,36,0.95) !important;
        outline-offset: 3px !important;
        box-shadow: inset 0 0 0 9999px rgba(251,191,36,0.08) !important;
      }
      body[data-prometheus-html-motion-selectable="true"] *:not(#prometheus-html-motion-transform-overlay):not(#prometheus-html-motion-transform-overlay *) {
        cursor: crosshair !important;
      }
    `;
    doc.head.appendChild(styleEl);
  }
  if (doc.body) doc.body.dataset.prometheusHtmlMotionSelectable = 'true';
  if (frame._htmlMotionSelectionReady) return;
  frame._htmlMotionSelectionReady = true;
  doc.addEventListener('mouseover', (event) => {
    const target = getCreativeHtmlMotionSelectableTarget(event.target, frame);
    doc.querySelectorAll('[data-prometheus-html-motion-hover="true"]').forEach((node) => node.removeAttribute('data-prometheus-html-motion-hover'));
    if (target) target.setAttribute('data-prometheus-html-motion-hover', 'true');
  }, true);
  doc.addEventListener('mouseout', () => {
    doc.querySelectorAll('[data-prometheus-html-motion-hover="true"]').forEach((node) => node.removeAttribute('data-prometheus-html-motion-hover'));
  }, true);
  doc.addEventListener('mousedown', () => {
    if (creativeHtmlMotionChatPopoverEl && creativeHtmlMotionChatPopoverEl.style.display !== 'none') hideCreativeHtmlMotionChatPopover();
  }, true);
  doc.addEventListener('pointerdown', (event) => {
    maybeStartCreativeHtmlMotionDirectManipulation(event, frame);
  }, true);
  doc.addEventListener('click', (event) => {
    if (frame._htmlMotionSuppressClick) {
      event.preventDefault();
      event.stopPropagation();
      frame._htmlMotionSuppressClick = false;
      return;
    }
    const target = getCreativeHtmlMotionSelectableTarget(event.target, frame);
    if (!target) return;
    event.preventDefault();
    event.stopPropagation();
    applyCreativeHtmlMotionPreviewSelection(target, frame);
    showCreativeHtmlMotionActionPopover(target, frame);
  }, true);
  frame.contentWindow?.addEventListener?.('scroll', () => repositionCreativeHtmlMotionPopovers(), true);
  applyCreativeHtmlMotionFlowAroundExclusions(frame);
  installCreativeHtmlMotionFlowWatchers(frame);
  if (creativeHtmlMotionSelectedElementContext?.selector) {
    try {
      const existing = doc.querySelector(creativeHtmlMotionSelectedElementContext.selector);
      if (existing) applyCreativeHtmlMotionPreviewSelection(existing, frame);
    } catch {}
  }
}

function positionCreativeHtmlMotionPopover(popover, element, frame, offset = 8) {
  if (!popover || !element || !frame) return;
  const frameRect = frame.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = getDesignFrameScale(frame);
  const pw = popover.offsetWidth || 220;
  const ph = popover.offsetHeight || 44;
  let left = frameRect.left + (rect.left * scale);
  let top = frameRect.top + (rect.top * scale) - ph - offset;
  if (top < 8) top = frameRect.top + ((rect.top + rect.height) * scale) + offset;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  if (left < 8) left = 8;
  if (top + ph > window.innerHeight - 8) top = Math.max(8, window.innerHeight - ph - 8);
  popover.style.left = `${left}px`;
  popover.style.top = `${top}px`;
}

function showCreativeHtmlMotionActionPopover(element, frame) {
  if (!creativeHtmlMotionActionPopoverEl) {
    creativeHtmlMotionActionPopoverEl = document.createElement('div');
    creativeHtmlMotionActionPopoverEl.id = 'creative-html-motion-action-popover';
    creativeHtmlMotionActionPopoverEl.style.cssText = 'position:fixed;z-index:10000;display:none;gap:4px;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,0.14);background:rgba(12,16,24,0.96);box-shadow:0 8px 24px rgba(0,0,0,0.45);backdrop-filter:blur(12px);font-family:Manrope,sans-serif';
    document.body.appendChild(creativeHtmlMotionActionPopoverEl);
  }
  const showEdit = isCreativeHtmlMotionElementTextEditable(element);
  const canSeparateFlow = showEdit && !isCreativeHtmlMotionFlowTextTarget(element);
  creativeHtmlMotionActionPopoverEl.innerHTML = `
    <button type="button" onclick="handleCreativeHtmlMotionChat()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(56,189,248,0.16);color:#bae6fd;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:chat-round-line-bold-duotone" width="14" height="14"></iconify-icon>Chat</button>
    ${showEdit ? `<button type="button" onclick="handleCreativeHtmlMotionEdit()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(249,115,22,0.16);color:#fdba74;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:pen-2-bold-duotone" width="14" height="14"></iconify-icon>Edit</button>` : ''}
    ${canSeparateFlow ? `<button type="button" onclick="handleCreativeHtmlMotionSeparateFlowObject()" title="Create a separate draggable flow object and mark this copy as flow text" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(163,255,18,0.16);color:#d9ff99;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:scissors-bold-duotone" width="14" height="14"></iconify-icon>Separate Flow</button>` : ''}
    <button type="button" onclick="toggleCreativeHtmlMotionSpatialDebug()" title="Show or hide layout bodies, collision halos, and flow shapes" style="display:inline-flex;align-items:center;gap:6px;border:none;background:${creativeHtmlMotionSpatialDebugEnabled ? 'rgba(34,197,94,0.22)' : 'rgba(255,255,255,0.06)'};color:${creativeHtmlMotionSpatialDebugEnabled ? '#bbf7d0' : '#d6d3d1'};border-radius:6px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:radar-2-bold-duotone" width="14" height="14"></iconify-icon>Debug</button>
    <button type="button" onclick="clearCreativeHtmlMotionSelectionContext()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(255,255,255,0.06);color:#d6d3d1;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:close-circle-bold-duotone" width="14" height="14"></iconify-icon>Clear</button>
  `;
  creativeHtmlMotionActionPopoverEl.style.display = 'flex';
  positionCreativeHtmlMotionPopover(creativeHtmlMotionActionPopoverEl, element, frame);
}

function toggleCreativeHtmlMotionSpatialDebug() {
  creativeHtmlMotionSpatialDebugEnabled = !creativeHtmlMotionSpatialDebugEnabled;
  updateCreativeHtmlMotionSpatialDebugOverlay(creativeHtmlMotionLastClickedFrame);
  if (creativeHtmlMotionLastClickedElement && creativeHtmlMotionLastClickedFrame) {
    showCreativeHtmlMotionActionPopover(creativeHtmlMotionLastClickedElement, creativeHtmlMotionLastClickedFrame);
  }
  showToast(
    creativeHtmlMotionSpatialDebugEnabled ? 'HTML Motion: spatial debug on.' : 'HTML Motion: spatial debug off.',
    creativeHtmlMotionSpatialDebugEnabled ? 'Showing layout bodies, collision halos, and flow exclusions.' : 'Spatial debug overlay hidden.',
    'info'
  );
}

function repositionCreativeHtmlMotionPopovers() {
  if (creativeHtmlMotionActionPopoverEl && creativeHtmlMotionActionPopoverEl.style.display !== 'none' && creativeHtmlMotionLastClickedElement && creativeHtmlMotionLastClickedFrame) {
    showCreativeHtmlMotionActionPopover(creativeHtmlMotionLastClickedElement, creativeHtmlMotionLastClickedFrame);
  }
  if (creativeHtmlMotionChatPopoverEl && creativeHtmlMotionChatPopoverEl.style.display !== 'none' && creativeHtmlMotionLastClickedElement && creativeHtmlMotionLastClickedFrame) {
    positionCreativeHtmlMotionPopover(creativeHtmlMotionChatPopoverEl, creativeHtmlMotionLastClickedElement, creativeHtmlMotionLastClickedFrame);
  }
}

function hideCreativeHtmlMotionPopovers() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  if (creativeHtmlMotionChatPopoverEl) creativeHtmlMotionChatPopoverEl.style.display = 'none';
}

function hideCreativeHtmlMotionChatPopover() {
  if (creativeHtmlMotionChatPopoverEl) creativeHtmlMotionChatPopoverEl.style.display = 'none';
}

function handleCreativeHtmlMotionChat() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  if (!creativeHtmlMotionLastClickedElement || !creativeHtmlMotionLastClickedFrame) return;
  showCreativeHtmlMotionChatPopover(creativeHtmlMotionLastClickedElement, creativeHtmlMotionLastClickedFrame);
}

function handleCreativeHtmlMotionEdit() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  const el = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!el || !frame || !isCreativeHtmlMotionElementTextEditable(el)) return;
  showCreativeHtmlMotionInlineEditor(el, frame);
}

async function handleCreativeHtmlMotionAutoHeight() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  const el = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!el || !frame || !isCreativeHtmlMotionElementTextEditable(el)) return;
  try {
    const measurement = measureCreativeHtmlMotionTextElement(el, frame, String(el.textContent || ''));
    if (!measurement) throw new Error('Could not measure selected text.');
    const nextHeight = Math.max(24, Math.ceil(measurement.measuredHeight + 8));
    await patchSelectedCreativeHtmlMotionTextStyle({
      height: `${nextHeight}px`,
      minHeight: `${nextHeight}px`,
      boxSizing: 'border-box',
    }, 'Auto-fit selected HTML motion text height with PreText.', 'HTML Motion: text height fit.');
  } catch (err) {
    showToast(`HTML motion auto-height failed: ${err.message || err}`, 'error');
  }
}

async function handleCreativeHtmlMotionShrinkToFit() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  const el = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!el || !frame || !isCreativeHtmlMotionElementTextEditable(el)) return;
  try {
    const computed = frame.contentWindow?.getComputedStyle?.(el);
    const rect = el.getBoundingClientRect();
    if (!computed || !rect.width || !rect.height) throw new Error('Could not inspect selected text bounds.');
    const startSize = Math.max(8, parseCreativeHtmlMotionPx(computed.fontSize, 16));
    const minSize = Math.max(10, Math.floor(startSize * 0.55));
    let chosen = measureCreativeHtmlMotionTextForSize(el, frame, startSize, rect.width, rect.height);
    for (let size = Math.floor(startSize); size >= minSize; size -= 1) {
      const measured = measureCreativeHtmlMotionTextForSize(el, frame, size, rect.width, rect.height);
      if (!measured) continue;
      chosen = measured;
      if (!measured.overflowY) break;
    }
    if (!chosen) throw new Error('Could not calculate a fitting font size.');
    await patchSelectedCreativeHtmlMotionTextStyle({
      fontSize: `${Math.round(chosen.fontSize)}px`,
      lineHeight: Number(chosen.lineHeightRatio || 1.15).toFixed(2),
      boxSizing: 'border-box',
    }, 'Shrink selected HTML motion text to fit with PreText.', 'HTML Motion: text shrunk to fit.');
  } catch (err) {
    showToast(`HTML motion shrink-to-fit failed: ${err.message || err}`, 'error');
  }
}

async function handleCreativeHtmlMotionBalanceText() {
  if (creativeHtmlMotionActionPopoverEl) creativeHtmlMotionActionPopoverEl.style.display = 'none';
  const el = creativeHtmlMotionLastClickedElement;
  const frame = creativeHtmlMotionLastClickedFrame;
  if (!el || !frame || !isCreativeHtmlMotionElementTextEditable(el)) return;
  try {
    const rect = el.getBoundingClientRect();
    if (!rect.width || !rect.height) throw new Error('Could not inspect selected text bounds.');
    const currentWidth = Math.max(24, Math.round(rect.width));
    const minWidth = Math.max(80, Math.round(currentWidth * 0.72));
    const maxWidth = Math.round(currentWidth * 1.28);
    let best = null;
    for (let width = minWidth; width <= maxWidth; width += 8) {
      const measured = measureCreativeHtmlMotionTextForSize(
        el,
        frame,
        Math.max(8, parseCreativeHtmlMotionPx(frame.contentWindow?.getComputedStyle?.(el)?.fontSize, 16)),
        width,
        rect.height
      );
      if (!measured) continue;
      const linePenalty = Math.abs(measured.lineCount - 2.5) * 28;
      const overflowPenalty = measured.overflowY ? 10000 + Math.max(0, measured.measuredHeight - rect.height) * 20 : 0;
      const driftPenalty = Math.abs(width - currentWidth) * 0.18;
      const ragPenalty = Math.abs((measured.measuredHeight / Math.max(1, measured.lineHeightPx)) - measured.lineCount) * 6;
      const score = linePenalty + overflowPenalty + driftPenalty + ragPenalty;
      if (!best || score < best.score) best = { score, width, measured };
    }
    if (!best) throw new Error('Could not calculate a balanced text width.');
    await patchSelectedCreativeHtmlMotionTextStyle({
      width: `${Math.round(best.width)}px`,
      boxSizing: 'border-box',
    }, 'Balance selected HTML motion text width with PreText.', 'HTML Motion: text balanced.');
  } catch (err) {
    showToast(`HTML motion text balance failed: ${err.message || err}`, 'error');
  }
}

function isCreativeHtmlMotionElementTextEditable(element) {
  if (!element || element.nodeType !== 1) return false;
  const tag = String(element.tagName || '').toLowerCase();
  if (['input','textarea','select','script','style','img','svg','video','audio','iframe','canvas','picture','source','hr','br','meta','link'].includes(tag)) return false;
  const text = String(element.innerText || element.textContent || '').trim();
  if (!text) return false;
  const children = Array.from(element.children || []);
  if (!children.length) return true;
  const inlineTags = new Set(['b','i','em','strong','span','br','u','small','sup','sub','mark']);
  return children.every((child) => inlineTags.has(String(child.tagName || '').toLowerCase()) && !child.children.length);
}

function showCreativeHtmlMotionInlineEditor(element, frame) {
  if (!element || !frame) return;
  if (element.dataset.prometheusHtmlMotionInlineEditing === '1') return;
  const originalText = String(element.textContent || '');
  element.dataset.prometheusHtmlMotionInlineEditing = '1';
  element.dataset.prometheusHtmlMotionOriginalText = originalText;
  element.setAttribute('contenteditable', 'true');
  element.spellcheck = false;
  try { element.focus({ preventScroll: false }); } catch { element.focus(); }
  applyCreativeHtmlMotionPretextInlineFeedback(element, frame, originalText);
  try {
    const doc = frame.contentDocument;
    const range = doc.createRange();
    range.selectNodeContents(element);
    const sel = frame.contentWindow.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  } catch {}
  let canceled = false;
  const cleanup = () => {
    element.removeEventListener('blur', onBlur);
    element.removeEventListener('keydown', onKey);
    element.removeEventListener('input', onInput);
    element.removeAttribute('contenteditable');
    element.style.outline = '';
    element.style.boxShadow = '';
    element.removeAttribute('title');
    delete element.dataset.prometheusHtmlMotionPretext;
    delete element.dataset.prometheusHtmlMotionInlineEditing;
  };
  const onKey = (e) => {
    if (e.key === 'Escape') { e.preventDefault(); canceled = true; element.blur(); }
    else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); element.blur(); }
  };
  const onInput = () => {
    applyCreativeHtmlMotionPretextInlineFeedback(element, frame, String(element.textContent || ''));
  };
  const onBlur = () => {
    cleanup();
    if (canceled) {
      element.textContent = originalText;
      delete element.dataset.prometheusHtmlMotionOriginalText;
      return;
    }
    commitCreativeHtmlMotionInlineEdit(element, originalText);
  };
  element.addEventListener('blur', onBlur);
  element.addEventListener('keydown', onKey);
  element.addEventListener('input', onInput);
}

async function commitCreativeHtmlMotionInlineEdit(element, originalText) {
  const newText = String(element.textContent || '');
  delete element.dataset.prometheusHtmlMotionOriginalText;
  if (newText === originalText) return;
  if (!creativeHtmlMotionClip) {
    element.textContent = originalText;
    showToast('No active HTML motion clip to patch.', 'error');
    return;
  }
  const measurement = measureCreativeHtmlMotionTextElement(element, creativeHtmlMotionLastClickedFrame, newText);
  try {
    const result = await patchCreativeHtmlMotionInlineTextBySelection(element, originalText, newText);
    const appliedCount = (Array.isArray(result?.appliedOps) ? result.appliedOps : Array.isArray(result?.applied) ? result.applied : [])
      .reduce((sum, op) => sum + Math.max(0, Number(op?.count) || 0), 0);
    if (!appliedCount) throw new Error('Could not uniquely locate that text in the clip HTML.');
    showToast(
      measurement?.overflowY ? 'HTML Motion: text updated, but may overflow.' : 'HTML Motion: text updated.',
      measurement?.overflowY ? 'PreText measured the edited copy taller than its selected box.' : 'PreText fit check passed.',
      measurement?.overflowY ? 'warn' : 'success'
    );
    if (creativeHtmlMotionLastClickedElement && creativeHtmlMotionLastClickedFrame) {
      creativeHtmlMotionSelectedElementContext = extractCreativeHtmlMotionElementContext(creativeHtmlMotionLastClickedElement, creativeHtmlMotionLastClickedFrame);
      updateDesignSelectionChip();
    }
  } catch (err) {
    element.textContent = originalText;
    showToast(`HTML motion edit failed: ${err.message || err}`, 'error');
  }
}

async function patchCreativeHtmlMotionInlineTextBySelection(element, originalText, newText) {
  const selector = String(creativeHtmlMotionSelectedElementContext?.selector || '').trim();
  if (selector) {
    try {
      const read = await readCreativeHtmlMotionClip({ includeHtml: true });
      const html = String(read?.clip?.html || read?.html || '');
      if (html) {
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');
        const target = doc.querySelector(selector);
        if (target) {
          const beforeOuter = String(target.outerHTML || '');
          target.textContent = String(newText || '');
          const afterOuter = String(target.outerHTML || '');
          if (beforeOuter && afterOuter && beforeOuter !== afterOuter) {
            return patchCreativeHtmlMotionClip({
              reason: `Direct inline text edit for selected HTML motion element ${selector}.`,
              ops: [{ op: 'replace_text', find: beforeOuter, replace: afterOuter, occurrence: 1 }],
            });
          }
        }
      }
    } catch {}
  }
  const originalEscaped = _designHtmlEscape(originalText);
  const newEscaped = _designHtmlEscape(newText);
  return patchCreativeHtmlMotionClip({
    reason: 'Direct inline text edit from the HTML motion preview.',
    ops: [
      { op: 'replace_text', find: originalText, replace: newText, occurrence: 1, required: false },
      originalEscaped !== originalText
        ? { op: 'replace_text', find: originalEscaped, replace: newEscaped, occurrence: 1, required: false }
        : null,
    ].filter(Boolean),
  });
}

function showCreativeHtmlMotionChatPopover(element, frame) {
  if (!creativeHtmlMotionChatPopoverEl) {
    creativeHtmlMotionChatPopoverEl = document.createElement('div');
    creativeHtmlMotionChatPopoverEl.id = 'creative-html-motion-chat-popover';
    creativeHtmlMotionChatPopoverEl.style.cssText = 'position:fixed;z-index:10000;display:none;width:320px;padding:10px;border-radius:12px;border:1px solid rgba(255,255,255,0.14);background:rgba(12,16,24,0.98);box-shadow:0 14px 36px rgba(0,0,0,0.5);backdrop-filter:blur(14px);font-family:Manrope,sans-serif;flex-direction:column;gap:8px';
    creativeHtmlMotionChatPopoverEl.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
        <div style="font-size:10px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;color:#a8a29e">Chat about selected clip element</div>
        <button type="button" onclick="hideCreativeHtmlMotionChatPopover()" style="border:none;background:transparent;color:#a8a29e;font-size:16px;cursor:pointer;padding:0;line-height:1;font-family:inherit">x</button>
      </div>
      <textarea id="creative-html-motion-chat-input" rows="3" placeholder="Ask to move, restyle, replace, retime, or explain this element..." style="width:100%;box-sizing:border-box;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.04);color:#fafaf9;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;resize:vertical;outline:none"></textarea>
      <div style="display:flex;align-items:center;gap:6px">
        <div style="flex:1"></div>
        <button type="button" onclick="submitCreativeHtmlMotionChatPopover()" style="display:inline-flex;align-items:center;gap:5px;border:1px solid rgba(56,189,248,0.28);background:rgba(56,189,248,0.16);color:#bae6fd;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:plain-bold-duotone" width="14" height="14"></iconify-icon>Send</button>
      </div>
    `;
    document.body.appendChild(creativeHtmlMotionChatPopoverEl);
    const ta = creativeHtmlMotionChatPopoverEl.querySelector('#creative-html-motion-chat-input');
    ta?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submitCreativeHtmlMotionChatPopover(); }
      if (e.key === 'Escape') { e.preventDefault(); hideCreativeHtmlMotionChatPopover(); }
    });
  }
  const ta = document.getElementById('creative-html-motion-chat-input');
  if (ta) ta.value = '';
  creativeHtmlMotionChatPopoverEl.style.display = 'flex';
  positionCreativeHtmlMotionPopover(creativeHtmlMotionChatPopoverEl, element, frame);
  setTimeout(() => document.getElementById('creative-html-motion-chat-input')?.focus(), 30);
}

async function submitCreativeHtmlMotionChatPopover() {
  const textarea = document.getElementById('creative-html-motion-chat-input');
  const text = String(textarea?.value || '').trim();
  if (!text) return;
  const mainInput = document.getElementById('chat-input');
  if (!mainInput) { showToast('Main chat input not found.', 'error'); return; }
  mainInput.value = text;
  hideCreativeHtmlMotionChatPopover();
  try { await sendChat(); } catch (err) { showToast(`Send failed: ${err.message}`, 'error'); }
}

// === Design-mode click-to-edit popover system ===
let designActionPopoverEl = null;
let designChatPopoverEl = null;
let designFilesPopoverEl = null;
let designLastClickedFrame = null;
let designLastClickedElement = null;
let designSelectMode = false;
let designMultiSelectedElements = [];
let designSelectModeOutsideHandler = null;
let browserDesignActionPopoverEl = null;
let browserDesignChatPopoverEl = null;

function hideBrowserDesignPopovers() {
  if (browserDesignActionPopoverEl) browserDesignActionPopoverEl.style.display = 'none';
  if (browserDesignChatPopoverEl) browserDesignChatPopoverEl.style.display = 'none';
}

function getBrowserDesignSelectionRect(selection) {
  const frame = document.getElementById('browser-canvas-frame');
  if (!frame || !selection?.bounds) return null;
  const frameRect = frame.getBoundingClientRect();
  const state = getBrowserCanvasState();
  const viewportWidth = Number(state.frameViewportWidth || state.frameWidth || selection.viewport?.width || 0);
  const viewportHeight = Number(state.frameViewportHeight || state.frameHeight || selection.viewport?.height || 0);
  if (!viewportWidth || !viewportHeight || !frameRect.width || !frameRect.height) return null;
  const computed = window.getComputedStyle(frame);
  const borderLeft = parseFloat(computed.borderLeftWidth) || 0;
  const borderTop = parseFloat(computed.borderTopWidth) || 0;
  const innerWidth = Math.max(1, frameRect.width - borderLeft - (parseFloat(computed.borderRightWidth) || 0));
  const innerHeight = Math.max(1, frameRect.height - borderTop - (parseFloat(computed.borderBottomWidth) || 0));
  const bounds = selection.liveBounds || selection.bounds;
  return {
    left: frameRect.left + borderLeft + (Number(bounds.x) || 0) * (innerWidth / viewportWidth),
    top: frameRect.top + borderTop + (Number(bounds.y) || 0) * (innerHeight / viewportHeight),
    width: Math.max(1, (Number(bounds.width) || 0) * (innerWidth / viewportWidth)),
    height: Math.max(1, (Number(bounds.height) || 0) * (innerHeight / viewportHeight)),
  };
}

function positionBrowserDesignPopover(popover, selection) {
  const rect = getBrowserDesignSelectionRect(selection);
  if (!popover || !rect) return false;
  const pw = popover.offsetWidth || 240;
  const ph = popover.offsetHeight || 40;
  let left = rect.left;
  let top = rect.top - ph - 8;
  if (top < 10) top = rect.top + rect.height + 8;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  if (left < 8) left = 8;
  popover.style.left = `${left}px`;
  popover.style.top = `${Math.max(8, top)}px`;
  return true;
}

function showBrowserDesignActionPopover(selection = getBrowserCanvasState().selectedElement) {
  if (!selection || isBrowserCanvasInHouseProvider()) return;
  if (!browserDesignActionPopoverEl) {
    browserDesignActionPopoverEl = document.createElement('div');
    browserDesignActionPopoverEl.id = 'browser-design-action-popover';
    browserDesignActionPopoverEl.style.cssText = 'position:fixed;z-index:10002;display:none;gap:4px;padding:5px;border-radius:10px;border:1px solid rgba(56,189,248,0.28);background:rgba(8,15,28,0.97);box-shadow:0 12px 30px rgba(2,6,23,0.5);backdrop-filter:blur(12px);font-family:Manrope,sans-serif';
    browserDesignActionPopoverEl.innerHTML = `
      <button type="button" onclick="handleBrowserDesignEdit()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(249,115,22,0.16);color:#fdba74;border-radius:7px;padding:7px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:pen-2-bold-duotone" width="14" height="14"></iconify-icon>Edit</button>
      <button type="button" onclick="handleBrowserDesignChat()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(56,189,248,0.16);color:#bae6fd;border-radius:7px;padding:7px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:chat-round-line-bold-duotone" width="14" height="14"></iconify-icon>Chat</button>
      <button type="button" onclick="handleBrowserDesignSelect()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(168,85,247,0.18);color:#d8b4fe;border-radius:7px;padding:7px 10px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:cursor-square-bold-duotone" width="14" height="14"></iconify-icon>Select</button>
    `;
    document.body.appendChild(browserDesignActionPopoverEl);
  }
  browserDesignActionPopoverEl.style.display = 'flex';
  positionBrowserDesignPopover(browserDesignActionPopoverEl, selection);
}

function showBrowserDesignChatPopover(options = {}) {
  const state = getBrowserCanvasState();
  const selection = options.selection || state.selectedElement;
  if (!selection || isBrowserCanvasInHouseProvider()) return;
  if (!browserDesignChatPopoverEl) {
    browserDesignChatPopoverEl = document.createElement('div');
    browserDesignChatPopoverEl.id = 'browser-design-chat-popover';
    browserDesignChatPopoverEl.style.cssText = 'position:fixed;z-index:10003;display:none;width:min(360px,calc(100vw - 24px));padding:12px;border-radius:12px;border:1px solid rgba(56,189,248,0.28);background:rgba(8,15,28,0.98);box-shadow:0 16px 40px rgba(2,6,23,0.55);backdrop-filter:blur(14px);font-family:Manrope,sans-serif';
    browserDesignChatPopoverEl.innerHTML = `
      <div style="font-size:11px;font-weight:800;color:#e0f2fe">Chat about this browser element</div>
      <div id="browser-design-chat-selection" style="margin-top:5px;font-size:10px;color:#94a3b8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"></div>
      <textarea id="browser-design-chat-input" rows="3" placeholder="What should Prometheus change or explain?" style="width:100%;box-sizing:border-box;margin-top:9px;resize:vertical;border:1px solid rgba(148,163,184,0.2);border-radius:8px;background:rgba(15,23,42,0.75);color:#f8fafc;padding:8px;font:11px/1.45 Manrope,sans-serif"></textarea>
      <div style="display:flex;justify-content:flex-end;gap:7px;margin-top:8px"><button type="button" onclick="hideBrowserDesignPopovers()" style="border:1px solid rgba(148,163,184,0.18);background:transparent;color:#cbd5e1;border-radius:7px;padding:6px 9px;font:700 10px Manrope,sans-serif;cursor:pointer">Close</button><button type="button" onclick="submitBrowserDesignChatPopover()" style="border:1px solid rgba(56,189,248,0.3);background:rgba(56,189,248,0.16);color:#e0f2fe;border-radius:7px;padding:6px 10px;font:800 10px Manrope,sans-serif;cursor:pointer">Send to chat</button></div>
    `;
    document.body.appendChild(browserDesignChatPopoverEl);
  }
  const label = selection.selector || (selection.id ? `#${selection.id}` : selection.tagName || 'element');
  const labelEl = browserDesignChatPopoverEl.querySelector('#browser-design-chat-selection');
  const input = browserDesignChatPopoverEl.querySelector('#browser-design-chat-input');
  if (labelEl) labelEl.textContent = label;
  if (input) {
    input.value = String(options.prompt || '');
    window.setTimeout(() => input.focus(), 0);
  }
  browserDesignChatPopoverEl.style.display = 'block';
  positionBrowserDesignPopover(browserDesignChatPopoverEl, selection);
}

async function submitBrowserDesignChatPopover() {
  const input = document.getElementById('browser-design-chat-input');
  const text = String(input?.value || '').trim();
  if (!text) return;
  const mainInput = document.getElementById('chat-input');
  if (!mainInput) return showToast('Main chat input not found.', 'error');
  mainInput.value = text;
  hideBrowserDesignPopovers();
  try { await sendChat(); } catch (err) { showToast(`Send failed: ${err.message}`, 'error'); }
}

function handleBrowserDesignEdit() {
  if (browserDesignActionPopoverEl) browserDesignActionPopoverEl.style.display = 'none';
  const selection = getBrowserCanvasState().selectedElement;
  if (selection) showBrowserDesignChatPopover({ selection, prompt: 'Edit this browser element so that ' });
}

function handleBrowserDesignChat() {
  if (browserDesignActionPopoverEl) browserDesignActionPopoverEl.style.display = 'none';
  showBrowserDesignChatPopover();
}

function handleBrowserDesignSelect() {
  const state = getBrowserCanvasState();
  if (browserDesignActionPopoverEl) browserDesignActionPopoverEl.style.display = 'none';
  state.browserDesignSelectMode = true;
  if (state.selectedElement) {
    const key = getBrowserTeachSelectionKey(state.selectedElement);
    if (!state.browserDesignSelections.some((entry) => getBrowserTeachSelectionKey(entry) === key)) {
      state.browserDesignSelections.push(cloneBrowserDesignSelection(state.selectedElement));
      state.browserDesignSelections = state.browserDesignSelections.filter(Boolean).slice(-24);
    }
  }
  showToast('Design Select mode is on. Click more elements to attach them.', 'info', 2800);
  renderBrowserCanvasSurface();
  persistActiveChat();
}

function removeBrowserDesignSelectionPill(index) {
  const state = getBrowserCanvasState();
  const annotations = getBrowserDesignAnnotationSelections(state);
  const removed = annotations[Number(index)];
  if (!removed) return;
  const removedKey = getBrowserTeachSelectionKey(removed);
  state.browserDesignSelections = (Array.isArray(state.browserDesignSelections) ? state.browserDesignSelections : [])
    .filter((entry) => getBrowserTeachSelectionKey(entry) !== removedKey);
  if (getBrowserTeachSelectionKey(state.selectedElement) === removedKey) {
    state.selectedElement = state.browserDesignSelections[state.browserDesignSelections.length - 1] || null;
  }
  if (!state.selectedElement) {
    const sessionId = String(state.sessionId || getBrowserCanvasPrimarySessionId() || '').trim();
    if (sessionId && window.ws && window.ws.readyState === WebSocket.OPEN) {
      wsSend({ type: 'browser:clear_selection', sessionId });
    }
  }
  state.updatedAt = Date.now();
  updateDesignSelectionChip();
  renderBrowserCanvasSurface();
  persistActiveChat();
}

function applyBrowserDesignSelection(selection, options = {}) {
  const state = getBrowserCanvasState();
  const next = cloneBrowserDesignSelection(selection);
  if (!next) return;
  state.selectedElement = next;
  state.selectionPending = false;
  state.updatedAt = Date.now();
  if (state.browserDesignSelectMode) {
    const key = getBrowserTeachSelectionKey(next);
    if (!state.browserDesignSelections.some((entry) => getBrowserTeachSelectionKey(entry) === key)) {
      state.browserDesignSelections.push(next);
      state.browserDesignSelections = state.browserDesignSelections.slice(-24);
    }
  } else if (options.showPopover !== false && !isBrowserCanvasInHouseProvider(state)) {
    showBrowserDesignActionPopover(next);
  }
  updateDesignSelectionChip();
  renderBrowserCanvasSurface();
  persistActiveChat();
}

function getDesignPreviewTabPath() {
  const tab = canvasTabs.find((t) => t.id === activeCanvasTabId);
  return tab?.diskPath || '';
}

function repositionDesignPopovers() {
  if (designActionPopoverEl && designActionPopoverEl.style.display !== 'none' && designLastClickedElement && designLastClickedFrame) {
    showDesignActionPopover(designLastClickedElement, designLastClickedFrame);
  }
  if (designChatPopoverEl && designChatPopoverEl.style.display !== 'none' && designLastClickedElement && designLastClickedFrame) {
    positionDesignChatPopover(designLastClickedElement, designLastClickedFrame);
  }
}

function hideAllDesignPopovers() {
  if (designActionPopoverEl) designActionPopoverEl.style.display = 'none';
  if (designChatPopoverEl) designChatPopoverEl.style.display = 'none';
  if (designFilesPopoverEl) designFilesPopoverEl.style.display = 'none';
}

function getDesignFrameScale(frame) {
  const rect = frame?.getBoundingClientRect?.();
  const width = Number(frame?.offsetWidth || 0);
  return rect?.width && width ? rect.width / width : 1;
}

function showDesignActionPopover(element, frame) {
  if (!designActionPopoverEl) {
    designActionPopoverEl = document.createElement('div');
    designActionPopoverEl.id = 'design-action-popover';
    designActionPopoverEl.style.cssText = 'position:fixed;z-index:10000;display:none;gap:4px;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,0.14);background:rgba(17,15,14,0.96);box-shadow:0 8px 24px rgba(0,0,0,0.45);backdrop-filter:blur(12px);font-family:Manrope,sans-serif';
    designActionPopoverEl.innerHTML = `
      <button type="button" onclick="handleDesignEdit()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(249,115,22,0.16);color:#fdba74;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:pen-2-bold-duotone" width="14" height="14"></iconify-icon>Edit</button>
      <button type="button" onclick="handleDesignChat()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(56,189,248,0.16);color:#bae6fd;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:chat-round-line-bold-duotone" width="14" height="14"></iconify-icon>Chat</button>
      <button type="button" onclick="handleDesignSelect()" style="display:inline-flex;align-items:center;gap:6px;border:none;background:rgba(168,85,247,0.18);color:#d8b4fe;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:cursor-square-bold-duotone" width="14" height="14"></iconify-icon>Select</button>
    `;
    document.body.appendChild(designActionPopoverEl);
  }
  designActionPopoverEl.style.display = 'flex';
  const frameRect = frame.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = getDesignFrameScale(frame);
  const pw = designActionPopoverEl.offsetWidth || 160;
  const ph = designActionPopoverEl.offsetHeight || 34;
  const absLeft = frameRect.left + (rect.left * scale);
  const absTop = frameRect.top + (rect.top * scale);
  const scaledHeight = rect.height * scale;
  let top = absTop - ph - 8;
  if (top < 12) top = absTop + scaledHeight + 8;
  let left = absLeft;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  if (left < 8) left = 8;
  designActionPopoverEl.style.left = `${left}px`;
  designActionPopoverEl.style.top = `${top}px`;
}

function isDesignElementTextEditable(element) {
  if (!element || element.nodeType !== 1) return false;
  const tag = String(element.tagName || '').toLowerCase();
  if (['input','textarea','select','script','style','img','svg','video','audio','iframe','canvas','picture','source','hr','br','meta','link'].includes(tag)) return false;
  if (!element.childNodes.length) return false;
  const inlineTags = new Set(['b','i','em','strong','span','br','u','small','sup','sub']);
  for (const child of element.childNodes) {
    if (child.nodeType === 3) continue;
    if (child.nodeType === 1 && inlineTags.has(String(child.tagName || '').toLowerCase()) && !child.children.length) continue;
    return false;
  }
  return String(element.textContent || '').trim().length > 0;
}

async function handleDesignEdit() {
  const el = designLastClickedElement;
  const frame = designLastClickedFrame;
  if (designActionPopoverEl) designActionPopoverEl.style.display = 'none';
  if (!el || !frame) return;
  if (isDesignElementTextEditable(el)) {
    showDesignInlineEditor(el, frame);
    return;
  }
  const matches = await findDesignElementInSources(el).catch(() => []);
  if (!matches.length) {
    showToast('No matching source files found for that element.', 'warn');
    return;
  }
  if (matches.length === 1) {
    await openDesignCodeHighlight(matches[0].diskPath, matches[0].matches);
    return;
  }
  showDesignFilesPopover(el, frame, matches);
}

function handleDesignChat() {
  if (designActionPopoverEl) designActionPopoverEl.style.display = 'none';
  if (!designLastClickedElement || !designLastClickedFrame) return;
  showDesignChatPopover(designLastClickedElement, designLastClickedFrame);
}

function showDesignInlineEditor(element, frame) {
  if (!element || !frame) return;
  if (element.dataset.prometheusInlineEditing === '1') return;
  const originalText = String(element.textContent || '');
  element.dataset.prometheusInlineEditing = '1';
  element.dataset.prometheusOriginalText = originalText;
  element.setAttribute('contenteditable', 'true');
  element.spellcheck = false;
  try { element.focus({ preventScroll: false }); } catch { element.focus(); }
  try {
    const doc = frame.contentDocument;
    const range = doc.createRange();
    range.selectNodeContents(element);
    const sel = frame.contentWindow.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  } catch {}
  let canceled = false;
  const cleanup = () => {
    element.removeEventListener('blur', onBlur);
    element.removeEventListener('keydown', onKey);
    element.removeAttribute('contenteditable');
    delete element.dataset.prometheusInlineEditing;
  };
  const onKey = (e) => {
    if (e.key === 'Escape') { e.preventDefault(); canceled = true; element.blur(); }
    else if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); element.blur(); }
  };
  const onBlur = () => {
    cleanup();
    if (canceled) {
      element.textContent = originalText;
      delete element.dataset.prometheusOriginalText;
      return;
    }
    commitDesignInlineEdit(element, originalText);
  };
  element.addEventListener('blur', onBlur);
  element.addEventListener('keydown', onKey);
}

function _designHtmlEscape(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]);
}
function _designEscapeRe(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

async function commitDesignInlineEdit(el, originalText) {
  const newText = String(el.textContent || '');
  delete el.dataset.prometheusOriginalText;
  if (newText === originalText) return;
  const path = getDesignPreviewTabPath();
  if (!path) {
    el.textContent = originalText;
    showToast('No source file is active for this preview.', 'error');
    return;
  }
  try {
    const res = await fetch(`/api/canvas/file?path=${encodeURIComponent(path)}`);
    const data = await res.json();
    if (!data.success) throw new Error(data.error || 'Load failed');
    const source = String(data.content || '');
    const origEscaped = _designHtmlEscape(originalText);
    const newEscaped = _designHtmlEscape(newText);
    let updatedSource = null;
    const currentOuter = String(el.outerHTML || '');
    const originalOuter = currentOuter.replace(newEscaped, origEscaped);
    if (originalOuter && originalOuter !== currentOuter && source.includes(originalOuter)) {
      updatedSource = source.replace(originalOuter, currentOuter);
    }
    if (!updatedSource) {
      const re = new RegExp(_designEscapeRe(origEscaped), 'g');
      const count = (source.match(re) || []).length;
      if (count === 1) updatedSource = source.replace(origEscaped, newEscaped);
    }
    if (!updatedSource) {
      el.textContent = originalText;
      showToast('Could not uniquely locate the text in the source file. Use Chat for this edit.', 'warn');
      return;
    }
    const saveRes = await fetch('/api/canvas/file', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ path, content: updatedSource }),
    });
    const saveData = await saveRes.json();
    if (!saveData.success) throw new Error(saveData.error || 'Save failed');
    const tab = canvasTabs.find((t) => t.diskPath === path);
    if (tab) {
      tab.content = updatedSource;
      tab.savedContent = updatedSource;
      if (canvasEditor && activeCanvasTabId === tab.id) setCanvasEditorValue(updatedSource);
    }
    showToast('Design: text updated and saved.', 'info');
    addProcessEntry('info', `Design: updated text in ${path}`);
  } catch (err) {
    el.textContent = originalText;
    showToast(`Design edit failed: ${err.message}`, 'error');
  }
}

function handleDesignSelect() {
  if (designActionPopoverEl) designActionPopoverEl.style.display = 'none';
  if (!designLastClickedElement || !designLastClickedFrame) return;
  designSelectMode = true;
  addDesignMultiSelection(designLastClickedElement, designLastClickedFrame);
  installDesignSelectModeOutsideClick();
  showToast('Select mode: click elements to attach. Click outside the canvas to finish.', 'info');
}

function addDesignMultiSelection(element, frame) {
  const ctx = extractDesignElementContext(element, frame);
  if (!ctx) return;
  const key = `${ctx.selector}|${(ctx.htmlSnippet || '').slice(0, 96)}`;
  if (designMultiSelectedElements.some((e) => e._key === key)) return;
  try { element.setAttribute('data-prometheus-design-multi-selected', 'true'); } catch {}
  designMultiSelectedElements.push({ _key: key, context: ctx, element, frame });
  renderDesignSelectionPills();
}

function removeDesignSelectionPill(idx) {
  const entry = designMultiSelectedElements[idx];
  if (entry?.element) {
    try { entry.element.removeAttribute('data-prometheus-design-multi-selected'); } catch {}
  }
  designMultiSelectedElements.splice(idx, 1);
  if (!designMultiSelectedElements.length) {
    clearDesignSelectionContext();
    return;
  }
  renderDesignSelectionPills();
}

function clearDesignMultiSelectionHighlights() {
  for (const entry of designMultiSelectedElements) {
    if (entry?.element) {
      try { entry.element.removeAttribute('data-prometheus-design-multi-selected'); } catch {}
    }
    if (entry?.frame?.contentDocument) {
      try {
        entry.frame.contentDocument.querySelectorAll('[data-prometheus-design-multi-selected="true"]').forEach((node) => node.removeAttribute('data-prometheus-design-multi-selected'));
      } catch {}
    }
  }
}

function clearDesignMultiSelection() {
  clearDesignMultiSelectionHighlights();
  designMultiSelectedElements = [];
  renderDesignSelectionPills();
}

function clearDesignSelectionAttachments() {
  clearDesignMultiSelection();
  clearDesignSelectionContext();
  exitDesignSelectMode();
}

function renderDesignSelectionPills() {
  const cont = document.getElementById('chat-design-selection-pills');
  if (!cont) return;
  const highlightedPill = renderHighlightedTextPillMarkup();
  const designModeActive = normalizeCreativeMode(window.currentCreativeMode) === 'design';
  if ((!designModeActive || !designMultiSelectedElements.length) && !highlightedPill) {
    cont.style.display = 'none';
    cont.innerHTML = '';
    syncChatAttachmentStackVisibility();
    return;
  }
  cont.style.display = 'flex';
  const designPill = designModeActive && designMultiSelectedElements.length
    ? renderDesignAnnotationPillMarkup(designMultiSelectedElements.length)
    : '';
  cont.innerHTML = [highlightedPill, designPill].filter(Boolean).join('');
  syncChatAttachmentStackVisibility();
}

function installDesignSelectModeOutsideClick() {
  if (designSelectModeOutsideHandler) return;
  designSelectModeOutsideHandler = (e) => {
    if (!designSelectMode) return;
    const canvasPanel = document.getElementById('canvas-panel');
    if (canvasPanel && canvasPanel.contains(e.target)) return;
    exitDesignSelectMode();
  };
  document.addEventListener('mousedown', designSelectModeOutsideHandler, true);
}

function exitDesignSelectMode() {
  designSelectMode = false;
  clearDesignMultiSelectionHighlights();
  if (designSelectModeOutsideHandler) {
    document.removeEventListener('mousedown', designSelectModeOutsideHandler, true);
    designSelectModeOutsideHandler = null;
  }
}

function buildDesignSearchNeedles(element) {
  const out = [];
  if (element.id) out.push(`id="${element.id}"`);
  const classes = Array.from(element.classList || []);
  if (classes.length) out.push(`class="${classes.join(' ')}"`);
  const text = String(element.innerText || element.textContent || '').replace(/\s+/g, ' ').trim();
  if (text && text.length >= 8 && text.length <= 160) out.push(text);
  return out;
}

async function findDesignElementInSources(element) {
  const previewPath = getDesignPreviewTabPath();
  if (!previewPath) return [];
  const files = new Set([previewPath]);
  try {
    const res = await fetch(`/api/canvas/file?path=${encodeURIComponent(previewPath)}`);
    const data = await res.json();
    if (data.success) {
      const hrefs = String(data.content || '').matchAll(/<(?:link|script)[^>]*?(?:href|src)=["']([^"']+)["']/g);
      const sep = previewPath.includes('\\') ? '\\' : '/';
      const dir = previewPath.replace(/[\\/][^\\/]+$/, '');
      for (const m of hrefs) {
        const raw = m[1];
        if (/^https?:/i.test(raw) || raw.startsWith('//') || raw.startsWith('data:') || raw.startsWith('#')) continue;
        const absPath = raw.startsWith('/') ? raw : `${dir}${sep}${raw}`;
        files.add(normalizeCanvasPath(absPath));
      }
    }
  } catch {}
  const needles = buildDesignSearchNeedles(element);
  if (!needles.length) return [];
  const results = [];
  for (const path of files) {
    try {
      const res = await fetch(`/api/canvas/file?path=${encodeURIComponent(path)}`);
      const data = await res.json();
      if (!data.success || data.isBinary || data.isImage) continue;
      const content = String(data.content || '');
      const matches = [];
      for (const needle of needles) {
        let idx = 0;
        while ((idx = content.indexOf(needle, idx)) !== -1) {
          matches.push({ index: idx, length: needle.length });
          idx += Math.max(1, needle.length);
        }
      }
      if (matches.length) results.push({ diskPath: path, name: path.split(/[\\/]/).pop(), matches });
    } catch {}
  }
  results.sort((a, b) => b.matches.length - a.matches.length);
  return results;
}

async function openDesignCodeHighlight(diskPath, matches) {
  await canvasPresentFile(diskPath, diskPath.split(/[\\/]/).pop());
  setCanvasMode('code');
  setTimeout(() => {
    if (!canvasEditor) return;
    canvasEditor.getAllMarks().forEach((m) => { if (m.__designHighlight) m.clear(); });
    const doc = canvasEditor.getDoc();
    matches.forEach((m) => {
      const from = doc.posFromIndex(m.index);
      const to = doc.posFromIndex(m.index + m.length);
      const mark = doc.markText(from, to, { className: 'cm-design-highlight' });
      mark.__designHighlight = true;
    });
    if (matches.length) {
      const first = matches[0];
      const fromPos = doc.posFromIndex(first.index);
      canvasEditor.scrollIntoView(fromPos, 80);
      canvasEditor.setCursor(fromPos);
    }
    canvasEditor.refresh();
    canvasEditor.focus();
  }, 150);
}

function showDesignFilesPopover(element, frame, results) {
  if (!designFilesPopoverEl) {
    designFilesPopoverEl = document.createElement('div');
    designFilesPopoverEl.id = 'design-files-popover';
    designFilesPopoverEl.style.cssText = 'position:fixed;z-index:10000;display:none;min-width:240px;max-width:340px;padding:6px;border-radius:10px;border:1px solid rgba(255,255,255,0.14);background:rgba(17,15,14,0.98);box-shadow:0 12px 32px rgba(0,0,0,0.45);backdrop-filter:blur(14px);font-family:Manrope,sans-serif';
    document.body.appendChild(designFilesPopoverEl);
  }
  designFilesPopoverEl.innerHTML = `
    <div style="padding:6px 8px;font-size:10px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;color:#a8a29e">Open in code</div>
    ${results.map((r) => `
      <button type="button" onclick="openDesignFilePick('${escHtml(r.diskPath).replace(/'/g, '&#39;')}')" style="width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 10px;border:none;background:transparent;color:#e7e5e4;border-radius:6px;font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;text-align:left" onmouseover="this.style.background='rgba(249,115,22,0.12)';this.style.color='#fdba74'" onmouseout="this.style.background='transparent';this.style.color='#e7e5e4'">
        <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${escHtml(r.name)}</span>
        <span style="font-size:10px;color:#78716c;font-weight:700">${r.matches.length} match${r.matches.length === 1 ? '' : 'es'}</span>
      </button>
    `).join('')}
  `;
  designFilesPopoverEl._results = results;
  const frameRect = frame.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = getDesignFrameScale(frame);
  designFilesPopoverEl.style.display = 'block';
  const pw = designFilesPopoverEl.offsetWidth || 260;
  const absLeft = frameRect.left + (rect.left * scale);
  const absTop = frameRect.top + ((rect.top + rect.height) * scale) + 8;
  let left = absLeft;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  if (left < 8) left = 8;
  designFilesPopoverEl.style.left = `${left}px`;
  designFilesPopoverEl.style.top = `${absTop}px`;
}

async function openDesignFilePick(diskPath) {
  const results = designFilesPopoverEl?._results || [];
  if (designFilesPopoverEl) designFilesPopoverEl.style.display = 'none';
  const hit = results.find((r) => r.diskPath === diskPath);
  if (hit) await openDesignCodeHighlight(diskPath, hit.matches);
  else { await canvasPresentFile(diskPath, diskPath.split(/[\\/]/).pop()); setCanvasMode('code'); }
}

function positionDesignChatPopover(element, frame) {
  if (!designChatPopoverEl) return;
  const frameRect = frame.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const scale = getDesignFrameScale(frame);
  const pw = 320;
  const ph = designChatPopoverEl.offsetHeight || 180;
  let left = frameRect.left + (rect.left * scale);
  let top = frameRect.top + ((rect.top + rect.height) * scale) + 8;
  if (left + pw > window.innerWidth - 8) left = window.innerWidth - pw - 8;
  if (left < 8) left = 8;
  if (top + ph > window.innerHeight - 8) top = Math.max(8, frameRect.top + (rect.top * scale) - ph - 8);
  designChatPopoverEl.style.left = `${left}px`;
  designChatPopoverEl.style.top = `${top}px`;
}

function showDesignChatPopover(element, frame) {
  if (!designChatPopoverEl) {
    designChatPopoverEl = document.createElement('div');
    designChatPopoverEl.id = 'design-chat-popover';
    designChatPopoverEl.style.cssText = 'position:fixed;z-index:10000;display:none;width:320px;padding:10px;border-radius:12px;border:1px solid rgba(255,255,255,0.14);background:rgba(17,15,14,0.98);box-shadow:0 14px 36px rgba(0,0,0,0.5);backdrop-filter:blur(14px);font-family:Manrope,sans-serif;flex-direction:column;gap:8px';
    designChatPopoverEl.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
        <div style="font-size:10px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;color:#a8a29e">Chat about this element</div>
        <button type="button" onclick="hideDesignChatPopover()" style="border:none;background:transparent;color:#a8a29e;font-size:16px;cursor:pointer;padding:0;line-height:1;font-family:inherit">×</button>
      </div>
      <textarea id="design-chat-input" rows="3" placeholder="Ask to change, restyle, or explain this element…" style="width:100%;box-sizing:border-box;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.04);color:#fafaf9;border-radius:8px;padding:8px 10px;font-size:12px;font-family:inherit;resize:vertical;outline:none"></textarea>
      <div id="design-chat-attachments" style="display:none;flex-wrap:wrap;gap:6px"></div>
      <div style="display:flex;align-items:center;gap:6px">
        <button type="button" onclick="document.getElementById('design-chat-file-input').click()" style="display:inline-flex;align-items:center;gap:5px;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.05);color:#e7e5e4;border-radius:8px;padding:6px 10px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:paperclip-bold-duotone" width="14" height="14"></iconify-icon>Attach</button>
        <input id="design-chat-file-input" type="file" multiple style="display:none" onchange="onDesignChatFilesChosen(this.files)" />
        <div style="flex:1"></div>
        <button type="button" onclick="submitDesignChatPopover()" style="display:inline-flex;align-items:center;gap:5px;border:1px solid rgba(56,189,248,0.28);background:rgba(56,189,248,0.16);color:#bae6fd;border-radius:8px;padding:6px 12px;font-size:11px;font-weight:800;cursor:pointer;font-family:inherit"><iconify-icon icon="solar:plain-bold-duotone" width="14" height="14"></iconify-icon>Send</button>
      </div>
    `;
    document.body.appendChild(designChatPopoverEl);
    const ta = designChatPopoverEl.querySelector('#design-chat-input');
    ta?.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submitDesignChatPopover(); }
      if (e.key === 'Escape') { e.preventDefault(); hideDesignChatPopover(); }
    });
  }
  designChatPopoverEl._attachments = [];
  const attachList = document.getElementById('design-chat-attachments');
  if (attachList) { attachList.innerHTML = ''; attachList.style.display = 'none'; }
  const ta = document.getElementById('design-chat-input');
  if (ta) ta.value = '';
  designChatPopoverEl.style.display = 'flex';
  positionDesignChatPopover(element, frame);
  setTimeout(() => document.getElementById('design-chat-input')?.focus(), 30);
  installDesignChatOutsideClick();
}

let designChatOutsideHandler = null;
function installDesignChatOutsideClick() {
  if (designChatOutsideHandler) return;
  designChatOutsideHandler = (e) => {
    if (!designChatPopoverEl || designChatPopoverEl.style.display === 'none') return;
    if (designChatPopoverEl.contains(e.target)) return;
    hideDesignChatPopover();
  };
  document.addEventListener('mousedown', designChatOutsideHandler, true);
}

function hideDesignChatPopover() {
  if (designChatPopoverEl) designChatPopoverEl.style.display = 'none';
  if (designChatOutsideHandler) {
    document.removeEventListener('mousedown', designChatOutsideHandler, true);
    designChatOutsideHandler = null;
  }
}

function onDesignChatFilesChosen(files) {
  if (!designChatPopoverEl) return;
  const arr = Array.from(files || []);
  designChatPopoverEl._attachments = (designChatPopoverEl._attachments || []).concat(arr);
  const list = document.getElementById('design-chat-attachments');
  if (list) {
    list.style.display = designChatPopoverEl._attachments.length ? 'flex' : 'none';
    list.innerHTML = designChatPopoverEl._attachments.map((f, i) => `
      <span style="display:inline-flex;align-items:center;gap:4px;padding:3px 7px;border-radius:999px;background:rgba(255,255,255,0.06);color:#e7e5e4;font-size:10px;font-weight:700">
        <iconify-icon icon="solar:file-bold-duotone" width="12" height="12"></iconify-icon>${escHtml(f.name)}
        <button type="button" onclick="removeDesignChatAttachment(${i})" style="border:none;background:transparent;color:#a8a29e;cursor:pointer;padding:0 2px;font-size:12px;font-family:inherit;line-height:1">×</button>
      </span>
    `).join('');
  }
  const input = document.getElementById('design-chat-file-input');
  if (input) input.value = '';
}

function removeDesignChatAttachment(idx) {
  if (!designChatPopoverEl?._attachments) return;
  designChatPopoverEl._attachments.splice(idx, 1);
  onDesignChatFilesChosen([]);
}

async function submitDesignChatPopover() {
  const textarea = document.getElementById('design-chat-input');
  const text = String(textarea?.value || '').trim();
  if (!text) return;
  const attachments = designChatPopoverEl?._attachments || [];
  const mainInput = document.getElementById('chat-input');
  if (!mainInput) { showToast('Main chat input not found.', 'error'); return; }
  if (attachments.length && typeof window.stageFiles === 'function') {
    try { await window.stageFiles(attachments); } catch {}
  }
  const context = designSelectedElementContext || (designLastClickedElement && designLastClickedFrame ? extractDesignElementContext(designLastClickedElement, designLastClickedFrame) : null);
  if (context && !designSelectedElementContext) designSelectedElementContext = context;
  // The full selection context travels in the private Design caller context.
  // Keep the visible user turn concise and readable.
  mainInput.value = context
    ? `${text}\n\n[Annotation attached]`
    : text;
  hideDesignChatPopover();
  try { await sendChat(); } catch (err) { showToast(`Send failed: ${err.message}`, 'error'); }
}

function applyDesignPreviewSelection(element, frame) {
  const doc = frame?.contentDocument;
  if (!doc) return;
  doc.querySelectorAll('[data-prometheus-design-selected="true"]').forEach((node) => {
    node.removeAttribute('data-prometheus-design-selected');
  });
  if (element && element instanceof frame.contentWindow.HTMLElement) {
    element.setAttribute('data-prometheus-design-selected', 'true');
    designSelectedElementContext = extractDesignElementContext(element, frame);
    void resolveDesignSelectionSourceCandidates(designSelectedElementContext);
    updateDesignSelectionChip();
    addProcessEntry('info', `Design: selected ${designSelectedElementContext?.selector || designSelectedElementContext?.tagName || 'element'} in preview.`);
  } else {
    clearDesignSelectionContext();
  }
}

function setupDesignPreviewSelection(frame, tab) {
  const doc = frame?.contentDocument;
  if (!doc || !doc.documentElement) return;
  let styleEl = doc.getElementById('prometheus-design-selection-style');
  if (!styleEl) {
    styleEl = doc.createElement('style');
    styleEl.id = 'prometheus-design-selection-style';
    styleEl.textContent = `
      [data-prometheus-design-selected="true"] {
        outline: 2px solid #f97316 !important;
        outline-offset: 2px !important;
        box-shadow: 0 0 0 4px rgba(249,115,22,0.18), inset 0 0 0 9999px rgba(249,115,22,0.08) !important;
      }
      [data-prometheus-design-multi-selected="true"] {
        outline: 2px solid #a855f7 !important;
        outline-offset: 2px !important;
        box-shadow: 0 0 0 4px rgba(168,85,247,0.22), inset 0 0 0 9999px rgba(168,85,247,0.10) !important;
      }
      [data-prometheus-design-hover="true"] {
        outline: 1px dashed rgba(56,189,248,0.9) !important;
        outline-offset: 2px !important;
        box-shadow: inset 0 0 0 9999px rgba(56,189,248,0.10) !important;
      }
      body[data-prometheus-design-mode="true"] * {
        cursor: crosshair !important;
      }
    `;
    doc.head.appendChild(styleEl);
  }
  if (doc.body) doc.body.dataset.prometheusDesignMode = 'true';
  doc.addEventListener('mouseover', (event) => {
    const target = event.target;
    if (!(target instanceof frame.contentWindow.HTMLElement)) return;
    doc.querySelectorAll('[data-prometheus-design-hover="true"]').forEach((node) => node.removeAttribute('data-prometheus-design-hover'));
    target.setAttribute('data-prometheus-design-hover', 'true');
  }, true);
  doc.addEventListener('mouseout', () => {
    doc.querySelectorAll('[data-prometheus-design-hover="true"]').forEach((node) => node.removeAttribute('data-prometheus-design-hover'));
  }, true);
  doc.addEventListener('mousedown', () => {
    if (designChatPopoverEl && designChatPopoverEl.style.display !== 'none') hideDesignChatPopover();
  }, true);
  let designClickTimeout = null;
  doc.addEventListener('click', (event) => {
    const target = event.target;
    if (!(target instanceof frame.contentWindow.HTMLElement)) return;
    if (target.closest('[data-prometheus-inline-editing="1"]')) return;
    if (frame._designBypassClick) return;
    event.preventDefault();
    event.stopPropagation();
    if (designSelectMode) {
      addDesignMultiSelection(target, frame);
      return;
    }
    if (designClickTimeout) clearTimeout(designClickTimeout);
    designClickTimeout = setTimeout(() => {
      designClickTimeout = null;
      applyDesignPreviewSelection(target, frame);
      designLastClickedElement = target;
      designLastClickedFrame = frame;
      showDesignActionPopover(target, frame);
    }, 240);
  }, true);
  doc.addEventListener('dblclick', (event) => {
    const target = event.target;
    if (!(target instanceof frame.contentWindow.HTMLElement)) return;
    if (designSelectMode) return;
    if (designClickTimeout) { clearTimeout(designClickTimeout); designClickTimeout = null; }
    if (designActionPopoverEl) designActionPopoverEl.style.display = 'none';
    event.preventDefault();
    event.stopImmediatePropagation();
    // A synthetic click here used to activate links/file previews, which could
    // unexpectedly hand the user off to Browser mode. Double-click remains a
    // local Design selection/action gesture and never forwards the page click.
    applyDesignPreviewSelection(target, frame);
    designLastClickedElement = target;
    designLastClickedFrame = frame;
    showDesignActionPopover(target, frame);
  }, true);
  frame.contentWindow.addEventListener('scroll', () => repositionDesignPopovers(), true);
  if (designSelectedElementContext?.selector) {
    try {
      const existing = doc.querySelector(designSelectedElementContext.selector);
      if (existing) applyDesignPreviewSelection(existing, frame);
    } catch {}
  } else {
    clearDesignSelectionContext();
  }
  if (tab) tab.mode = 'preview';
}

async function applySingleDesignOp(op) {
  const opName = String(op?.op || '').trim();
  if (!opName) throw new Error('Invalid Design op.');
  let diskPath = '';
  let snapshot = null;
  let nextContent = '';
  let summary = '';

  if (opName === 'patch-css-rule') {
    diskPath = resolveDesignFilePath(op.file, ['css', 'scss', 'less']);
    snapshot = await loadCanvasFileSnapshot(diskPath);
    const selector = String(op.selector || designSelectedElementContext?.selector || '').trim();
    if (!selector) throw new Error('patch-css-rule requires a selector.');
    const declarations = op.declarations && typeof op.declarations === 'object'
      ? op.declarations
      : (op.patch && typeof op.patch === 'object' ? op.patch : {});
    nextContent = upsertCssRuleContent(snapshot.content, selector, declarations);
    summary = `patched CSS rule ${selector} in ${snapshot.name}`;
  } else if (opName === 'patch-html-attributes') {
    diskPath = resolveDesignFilePath(op.file, ['html', 'htm']);
    snapshot = await loadCanvasFileSnapshot(diskPath);
    nextContent = patchHtmlAttributesContent(snapshot.content, op.selector, {
      attributes: op.attributes || op.patch || {},
      styles: op.styles || {},
      removeAttributes: op.removeAttributes || [],
    });
    summary = `patched HTML attributes in ${snapshot.name}`;
  } else if (opName === 'replace-inner-text') {
    diskPath = resolveDesignFilePath(op.file, ['html', 'htm']);
    snapshot = await loadCanvasFileSnapshot(diskPath);
    nextContent = replaceInnerTextContent(snapshot.content, op.selector, op.text ?? op.value ?? '');
    summary = `updated inner text in ${snapshot.name}`;
  } else if (opName === 'replace-in-file') {
    diskPath = resolveDesignFilePath(op.file);
    snapshot = await loadCanvasFileSnapshot(diskPath);
    nextContent = replaceInFileContent(snapshot.content, op);
    summary = `replaced source in ${snapshot.name}`;
  } else if (opName === 'insert-in-file') {
    diskPath = resolveDesignFilePath(op.file);
    snapshot = await loadCanvasFileSnapshot(diskPath);
    nextContent = insertInFileContent(snapshot.content, op);
    summary = `inserted source into ${snapshot.name}`;
  } else {
    throw new Error(`Unsupported Design op: ${opName}`);
  }

  if (nextContent === snapshot.content) {
    return { changed: false, summary: `${summary} (no content change)` };
  }
  await writeCanvasFileSnapshot(snapshot.diskPath, nextContent, { name: snapshot.name });
  return { changed: true, summary, diskPath: snapshot.diskPath };
}

async function applyDesignAssistantOps(replyText) {
  if (normalizeCreativeMode(window.currentCreativeMode) !== 'design') {
    return { matched: false, applied: 0, errors: [] };
  }
  const parsed = parseDesignOpsFromText(replyText);
  if (!parsed.matched) return { matched: false, applied: 0, errors: [] };

  const results = [];
  const errors = [];
  for (const op of parsed.ops) {
    try {
      const result = await applySingleDesignOp(op);
      results.push(result);
    } catch (err) {
      errors.push(`${String(op?.op || 'op')}: ${String(err?.message || err || 'Unknown error')}`);
    }
  }

  const applied = results.filter((result) => result?.changed).length;
  if (applied > 0) {
    addProcessEntry('result', `Design: applied ${applied} file op${applied === 1 ? '' : 's'}.`);
    results.filter((result) => result?.summary).forEach((result) => addProcessEntry('info', `Design: ${result.summary}`));
    if (errors.length) addProcessEntry('warn', `Design: ${errors.join(' | ')}`);
    const activeTab = canvasTabs.find((tab) => tab.id === activeCanvasTabId) || null;
    if (activeTab?.mode === 'preview') canvasUpdatePreview();
    showToast(`Design applied ${applied} edit${applied === 1 ? '' : 's'}`);
  } else if (errors.length) {
    addProcessEntry('warn', `Design patch parsing matched, but nothing was applied. ${errors.join(' | ')}`);
  }

  return { matched: true, applied, errors };
}

function toggleLeftPanel() {
  leftPanelCollapsed = !leftPanelCollapsed;
  document.body.classList.toggle('left-collapsed', leftPanelCollapsed);
  const btn = document.getElementById('sidebar-collapse-btn');
  if (btn) btn.title = leftPanelCollapsed ? 'Expand sidebar' : 'Collapse sidebar';
}

function syncHeaderCanvasChrome() {
  const rightPanel = document.getElementById('right-panel');
  const browserState = getBrowserCanvasState();
  const canvasButton = document.getElementById('canvas-toggle-btn');
  const isRightCanvasOpen = Boolean(
    canvasOpen &&
    rightPanel &&
    rightPanel.classList.contains('open') &&
    rightPanel.classList.contains('canvas-open')
  );
  document.body.classList.toggle('right-canvas-open', isRightCanvasOpen);
  document.body.classList.toggle('right-creative-canvas-open', isRightCanvasOpen && isStructuredCreativeMode(window.currentCreativeMode));
  const browserInHouseActive = browserState.active === true && isBrowserCanvasInHouseProvider(browserState);
  if (canvasButton) {
    canvasButton.classList.toggle('browser-live', browserInHouseActive);
    if (browserInHouseActive) {
      canvasButton.title = 'Open Canvas — in-app browser active';
      canvasButton.setAttribute('aria-label', 'Open Canvas — in-app browser active');
    }
  }
}

function toggleRightPanel() {
  const panel = document.getElementById('right-panel');
  const toggleBtn = document.getElementById('drawerToggle');
  if (!panel) return;
  const wasOpen = panel.classList.contains('open');
  const isOpen = panel.classList.toggle('open');
  document.body.classList.toggle('right-collapsed', !isOpen);
  if (toggleBtn) toggleBtn.classList.toggle('active', isOpen);
  // When closing: clear inline resize styles so CSS width:0 takes effect
  if (!isOpen && wasOpen) {
    if (canvasOpen) toggleCanvas(false, { force: true });
    panel.style.removeProperty('width');
    panel.style.removeProperty('min-width');
    panel.style.removeProperty('max-width');
  } else if (isOpen && !wasOpen) {
    const sidebar = document.getElementById('sidebar');
    if (sidebar && !sidebar.classList.contains('collapsed')) {
      if (typeof window.toggleSidebar === 'function') window.toggleSidebar();
    }
    hideSourcesMinimizedPanel({ resetFilter: false });
    ensureSourcePanelContext(window.activeChatSessionId || window.agentSessionId);
    if (chatResourcesState.sessionId) loadChatResources({ sessionId: chatResourcesState.sessionId, background: true }).catch(() => {});
    refreshSourcePanel();
  }
  if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
  syncHeaderCanvasChrome();
  queueNativeBrowserSurfaceSync({ force: true });
}

function toggleCanvas(nextOpen = null, options = {}) {
  const targetOpen = typeof nextOpen === 'boolean' ? nextOpen : !canvasOpen;
  canvasOpen = targetOpen;
  const panel = document.getElementById('canvas-panel');
  const btn = document.getElementById('canvas-toggle-btn');
  const topbar = document.getElementById('right-panel-topbar');
  const dot = document.getElementById('canvas-notify-dot');
  if (!panel) return;
  if (canvasOpen) {
    // Ensure right panel is open
    const rightPanel = document.getElementById('right-panel');
    if (rightPanel && !rightPanel.classList.contains('open')) {
      if (typeof window.toggleRightPanel === 'function') window.toggleRightPanel();
    }
    if (rightPanel) {
      rightPanelCanvasSavedScrollTop = rightPanel.scrollTop || 0;
      rightPanel.classList.add('canvas-open');
      rightPanel.scrollTop = 0;
    }
    document.body.classList.remove('right-collapsed');
    // Auto-collapse sidebar for more canvas space
    const sidebar = document.getElementById('sidebar');
    if (sidebar && !sidebar.classList.contains('collapsed')) {
      if (typeof window.toggleSidebar === 'function') window.toggleSidebar();
    }
    panel.style.display = 'flex';
    if (isCreativeModeLocked()) {
      // Closing the right drawer clears its inline width. Reopening Canvas
      // must restore the creative workspace width instead of inheriting the
      // ordinary narrow context-drawer width.
      setRightPanelWidth(CREATIVE_MODE_PANEL_WIDTH, {
        minimumWidth: 960,
        lockMax: true,
        preserveChatColumn: true,
      });
    } else {
      const rightPanel = document.getElementById('right-panel');
      const currentWidth = rightPanel?.offsetWidth || 0;
      if (currentWidth < CANVAS_PANEL_MIN_WIDTH) {
        setRightPanelWidth(CANVAS_PANEL_MIN_WIDTH, { minimumWidth: 860 });
      }
    }
    if (topbar) topbar.style.display = 'none';
    if (btn) { btn.style.background='rgba(249,115,22,0.15)'; btn.style.borderColor='rgba(249,115,22,0.45)'; btn.style.color='#f97316'; }
    if (dot) dot.style.display = 'none';
    try {
      if (!canvasEditorInitialized) initCanvasEditor();
    } catch (err) {
      addProcessEntry('error', `Canvas editor init failed: ${String(err?.message || err)}`);
    }
    const activeTab = canvasTabs.find((tab) => tab.id === activeCanvasTabId) || null;
    try {
      applyCanvasViewMode(activeTab?.mode || 'code', activeTab);
      canvasRenderTabs();
    } catch (err) {
      addProcessEntry('error', `Canvas view restore failed: ${String(err?.message || err)}`);
      const creativeShell = document.getElementById('canvas-creative-shell');
      const editorWrap = document.getElementById('canvas-editor-wrap');
      const previewShell = document.getElementById('canvas-preview-shell');
      const previewFrame = document.getElementById('canvas-preview-frame');
      const emptyState = document.getElementById('canvas-empty-state');
      if (creativeShell) creativeShell.style.display = 'none';
      if (editorWrap) editorWrap.style.display = 'none';
      if (previewShell) previewShell.style.display = 'none';
      if (previewFrame) previewFrame.style.display = 'none';
      if (emptyState) emptyState.style.display = 'flex';
    }
	    updateCanvasWorkspaceChrome();
	  } else {
    const rightPanel = document.getElementById('right-panel');
    if (rightPanel) {
      rightPanel.classList.remove('canvas-open');
      rightPanel.scrollTop = rightPanelCanvasSavedScrollTop || 0;
      resetRightPanelWidth();
    }
    browserCanvasPanelWidthMode = '';
	    // Reset fullscreen if active
	    if (canvasFullscreenMode) {
	      canvasFullscreenMode = false;
      panel.style.position = 'absolute';
      panel.style.inset = '0';
      panel.style.zIndex = '20';
      panel.style.background = '';
      syncCanvasFullscreenButton();
    }
	    panel.style.display = 'none';
	    if (topbar) topbar.style.display = 'flex';
	    if (btn) { btn.style.background=''; btn.style.borderColor=''; btn.style.color=''; }
	  }
    syncHeaderCanvasChrome();
    if (typeof window._syncPageViewPositions === 'function') window._syncPageViewPositions();
     syncCanvasSurfaceWidthLock();
    syncBrowserCanvasStream({ force: true });
    queueNativeBrowserSurfaceSync({ force: true });
	}

function toggleCanvasFullscreen() {
  const panel = document.getElementById('canvas-panel');
  if (!panel || !canvasOpen) return;
  canvasFullscreenMode = !canvasFullscreenMode;
  if (canvasFullscreenMode) {
    panel.style.position = 'fixed';
    panel.style.inset = '0';
    panel.style.zIndex = '1000';
    panel.style.background = '#2a2a2a';
  } else {
    panel.style.position = 'absolute';
    panel.style.inset = '0';
    panel.style.zIndex = '20';
    panel.style.background = '';
  }
  syncCanvasFullscreenButton();
  if (isStructuredCreativeMode(normalizeCreativeMode(window.currentCreativeMode))) {
    scheduleCreativeStageViewportSync({ force: true, center: creativeStageZoomMode !== 'manual' });
  }
}

function setCanvasEditorValue(value) {
  if (!canvasEditor) return;
  canvasEditorProgrammaticUpdate = true;
  try {
    canvasEditor.setValue(String(value ?? ''));
  } finally {
    canvasEditorProgrammaticUpdate = false;
  }
}

function syncCanvasFullscreenButton() {
  const btn = document.getElementById('canvas-fullscreen-btn');
  if (!btn) return;
  const active = !!canvasFullscreenMode;
  const expandIcon = btn.querySelector('[data-canvas-fullscreen-icon="expand"]');
  const exitIcon = btn.querySelector('[data-canvas-fullscreen-icon="exit"]');
  if (expandIcon) expandIcon.style.display = active ? 'none' : 'block';
  if (exitIcon) exitIcon.style.display = active ? 'block' : 'none';
  btn.title = active ? 'Exit fullscreen' : 'Fullscreen';
  btn.setAttribute('aria-label', active ? 'Exit fullscreen' : 'Fullscreen');
  btn.setAttribute('aria-pressed', active ? 'true' : 'false');
}

function initCanvasEditor() {
  canvasEditorInitialized = true;
  const wrap = document.getElementById('canvas-editor-wrap');
  if (!wrap) return;
  if (typeof window.__PROM_LOAD_CODEMIRROR === 'function' && typeof CodeMirror === 'undefined') {
    window.__PROM_LOAD_CODEMIRROR()
      .then(() => {
        if (typeof CodeMirror === 'undefined') {
          console.warn('[chat] CodeMirror load returned without defining CodeMirror');
          return;
        }
        initCanvasEditor();
      })
      .catch((err) => {
        console.warn('[chat] CodeMirror load failed:', err);
      });
    return;
  }
  if (typeof CodeMirror === 'undefined') return;
  canvasEditor = CodeMirror(wrap, {
    value: '',
    mode: 'htmlmixed',
    lineNumbers: true,
    lineWrapping: true,
    tabSize: 2,
    indentWithTabs: false,
    theme: 'material-darker',
    extraKeys: { 'Ctrl-S': () => canvasSave(), 'Cmd-S': () => canvasSave() },
  });
  canvasEditor.on('change', () => {
    const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
    if (!tab) return;
    const newVal = canvasEditor.getValue();
    if (canvasEditorProgrammaticUpdate) {
      tab.content = newVal;
      return;
    }
    if (tab.diskPath && newVal !== tab.savedContent) {
      tab.dirty = true;
    } else if (tab.diskPath) {
      tab.dirty = false;
    }
    tab.content = newVal;
    if (tab.mode === 'preview') canvasUpdatePreview();
    canvasRenderTabs();
  });
}

function canvasNewFile() {
  const name = prompt('File name:', 'untitled.html');
  if (!name || !name.trim()) return;
  const id = 'ctab_' + Math.random().toString(36).slice(2);
  canvasTabs.push({ id, name: name.trim(), content: '', mode: 'code', language: getCanvasLang(name) });
  canvasOpenTab(id);
}

// Open generated or API-provided text in the existing code canvas without
// pretending it is a writable workspace file. Project CONTEXT.md uses this
// bridge so the sidebar can show the full living document safely.
function canvasOpenContent(content, name = 'untitled.txt') {
  const tabName = String(name || 'untitled.txt');
  const tabContent = String(content || '');
  let tab = canvasTabs.find((candidate) => candidate.virtualKey === `content:${tabName}`);
  if (!tab) {
    tab = {
      id: 'ctab_' + Math.random().toString(36).slice(2),
      virtualKey: `content:${tabName}`,
      name: tabName,
      content: tabContent,
      savedContent: tabContent,
      dirty: false,
      mode: 'code',
      language: getCanvasLang(tabName),
    };
    canvasTabs.push(tab);
  } else {
    tab.content = tabContent;
    tab.savedContent = tabContent;
    tab.dirty = false;
    tab.mode = 'code';
    tab.language = getCanvasLang(tabName);
  }
  if (!canvasOpen) toggleCanvas(true);
  canvasOpenTab(tab.id);
}

function canvasOpenTab(id) {
  activeCanvasTabId = id;
  const tab = canvasTabs.find(t => t.id === id);
  if (!tab) return;
  // Apply view mode FIRST so the change event fires with the correct mode already set
  applyCanvasViewMode(tab.mode || 'code', tab);
  if (canvasEditor) {
    // Temporarily disconnect change handler to avoid double-render during setValue
    const silentSet = () => {
      setCanvasEditorValue(tab.content || '');
      canvasEditor.setOption('mode', tab.language || 'null');
      setTimeout(() => canvasEditor.refresh(), 10);
    };
    silentSet();
  }
  canvasRenderTabs();
}

function canvasCloseTab(id, ev) {
  if (ev) ev.stopPropagation();
  const idx = canvasTabs.findIndex(t => t.id === id);
  if (idx === -1) return;
  // Tell server this file is no longer on the canvas
  const closingTab = canvasTabs[idx];
  if (closingTab && closingTab.diskPath) canvasNotifyClose(closingTab.diskPath);
  canvasTabs.splice(idx, 1);
  if (activeCanvasTabId === id) {
    if (canvasTabs.length > 0) {
      canvasOpenTab(canvasTabs[Math.min(idx, canvasTabs.length - 1)].id);
    } else {
      activeCanvasTabId = null;
      if (canvasEditor) setCanvasEditorValue('');
      applyCanvasViewMode('code', null);
      canvasRenderTabs();
    }
  } else {
    canvasRenderTabs();
  }
  const tree = document.getElementById('canvas-project-tree');
  if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
}

function setCanvasMode(mode) {
  const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
  if (!tab) return;
  if (mode === 'diff') {
    tab.openMode = 'diff';
    tab.diffAvailable = true;
    tab.diffView = tab.diffView || 'turn';
    tab.mode = 'code';
    applyCanvasViewMode('code', tab);
    canvasRenderTabs();
    return;
  }
  // Code and Preview are the normal editable/preview views. Leaving the diff
  // view should return to the same Canvas tab rather than creating another
  // surface or losing the file that was just reviewed.
  if (tab.openMode === 'diff') delete tab.openMode;
  // sync editor -> tab before switching
  if (canvasEditor && tab.mode !== 'preview') tab.content = canvasEditor.getValue();
  tab.mode = mode;
  applyCanvasViewMode(mode, tab);
  canvasRenderTabs();
}

function canvasDiffRoot(tab) {
  return String(
    tab?.diffRoot
    || sourcePanelState?.codingContext?.root
    || sourcePanelState?.gitRoot
    || '',
  ).trim();
}

function canvasDiffFilePath(tab) {
  return String(tab?.diskPath || tab?.workspacePath || tab?.originalPath || '').trim();
}

async function renderCanvasDiffInto(host, tab) {
  if (!host || !tab) return;
  const filePath = canvasDiffFilePath(tab);
  if (!filePath) {
    host.innerHTML = '<div class="canvas-diff-loading">This file has no workspace path to compare.</div>';
    return;
  }
  const requestVersion = ++canvasDiffRequestVersion;
  host.innerHTML = '<div class="canvas-diff-loading">Loading diff…</div>';
  try {
    const params = new URLSearchParams({
      file: filePath,
      view: String(tab.diffView || 'turn'),
      sessionId: String(window.activeChatSessionId || window.agentSessionId || ''),
    });
    const root = canvasDiffRoot(tab);
    if (root) params.set('root', root);
    const data = await api(`/api/coding/diff?${params.toString()}`, { timeoutMs: 12000, dedupe: false });
    if (requestVersion !== canvasDiffRequestVersion || activeCanvasTabId !== tab.id || tab.openMode !== 'diff') return;
    const { renderUnifiedDiffMarkup } = await loadCodingDiffRenderer();
    if (requestVersion !== canvasDiffRequestVersion || activeCanvasTabId !== tab.id || tab.openMode !== 'diff') return;
    const baseline = data?.baselineKind === 'none'
      ? 'No baseline'
      : data?.baselineKind === 'turn-snapshot' || data?.baselineKind === 'session-snapshot'
        ? 'Snapshot'
        : data?.baselineKind === 'git-index'
          ? 'Staged'
          : 'Git working tree';
    const additions = Number(data?.insertions) || 0;
    const deletions = Number(data?.deletions) || 0;
    host.innerHTML = `
      <div class="canvas-diff-toolbar">
        <span class="canvas-diff-title">Turn diff · ${escHtml(tab.name || filePath)}</span>
        <span class="canvas-diff-meta">${escHtml(baseline)} · +${additions} · -${deletions}</span>
      </div>
      ${renderUnifiedDiffMarkup(data?.diff, { emptyText: data?.baselineKind === 'none' ? 'No comparison baseline is available for this file.' : undefined })}`;
  } catch (error) {
    if (requestVersion !== canvasDiffRequestVersion) return;
    host.innerHTML = `<div class="canvas-diff-loading">${escHtml(error?.message || 'Unable to load diff.')}</div>`;
  }
}

function applyCanvasViewMode(mode, tab) {
  const creativeShell = document.getElementById('canvas-creative-shell');
  const browserShell = document.getElementById('canvas-browser-shell');
  const editorWrap = document.getElementById('canvas-editor-wrap');
  const diffWrap = document.getElementById('canvas-diff-wrap');
  const previewShell = document.getElementById('canvas-preview-shell');
  const previewFrame = document.getElementById('canvas-preview-frame');
  const emptyState = document.getElementById('canvas-empty-state');
  const noFilesHint = document.getElementById('canvas-no-files-hint');
  const fileBrowser = document.getElementById('canvas-file-browser');
  const codeModeBtn = document.getElementById('canvas-code-btn');
  const diffModeBtn = document.getElementById('canvas-diff-btn');
  const previewModeBtn = document.getElementById('canvas-preview-btn');
  updateCanvasWorkspaceChrome();
  if (isStructuredCreativeMode()) {
    if (creativeShell) creativeShell.style.display = 'flex';
    if (browserShell) browserShell.style.display = 'none';
    if (editorWrap) editorWrap.style.display = 'none';
    if (diffWrap) diffWrap.style.display = 'none';
    if (previewShell) previewShell.style.display = 'none';
    if (previewFrame) previewFrame.style.display = 'none';
    if (emptyState) emptyState.style.display = 'none';
    if (noFilesHint) noFilesHint.style.display = 'none';
    if (fileBrowser) fileBrowser.style.display = 'none';
    if (codeModeBtn) codeModeBtn.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    if (previewModeBtn) previewModeBtn.style.display = 'none';
    renderCreativeWorkspace();
    syncCanvasSurfaceWidthLock(tab);
    return;
  }
  if (creativeShell) creativeShell.style.display = 'none';
  if (isBrowserCanvasSurfaceActive()) {
    if (browserShell) browserShell.style.display = 'flex';
    if (editorWrap) editorWrap.style.display = 'none';
    if (diffWrap) diffWrap.style.display = 'none';
    if (previewShell) previewShell.style.display = 'none';
    if (previewFrame) previewFrame.style.display = 'none';
    if (emptyState) emptyState.style.display = 'none';
    if (noFilesHint) noFilesHint.style.display = 'none';
    if (fileBrowser) fileBrowser.style.display = 'none';
    if (codeModeBtn) codeModeBtn.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    if (previewModeBtn) previewModeBtn.style.display = 'none';
    renderBrowserCanvasSurface();
    syncCanvasSurfaceWidthLock(tab);
    return;
  }
  if (browserShell) browserShell.style.display = 'none';
  if (!tab) {
    if (normalizeCreativeMode(window.currentCreativeMode) !== 'design') clearDesignSelectionContext();
    if (editorWrap) editorWrap.style.display = 'none';
    if (diffWrap) diffWrap.style.display = 'none';
    if (previewShell) previewShell.style.display = 'none';
    if (previewFrame) previewFrame.style.display = 'none';
    if (emptyState) emptyState.style.display = 'flex';
    if (noFilesHint) noFilesHint.style.display = 'flex';
    if (fileBrowser) fileBrowser.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    syncCanvasSurfaceWidthLock(tab);
    return;
  }
  if (emptyState) emptyState.style.display = 'none';
  if (noFilesHint) noFilesHint.style.display = 'none';
  if (fileBrowser) fileBrowser.style.display = 'none';
  if (diffWrap) diffWrap.style.display = 'none';
  if (normalizeCreativeMode(window.currentCreativeMode) !== 'design' || mode !== 'preview') {
    clearDesignSelectionContext();
  }
  // Image tabs always show in preview mode — hide code/preview toggle buttons
  if (tab.isImage || tab.isBinary) {
    if (editorWrap) editorWrap.style.display = 'none';
    if (diffWrap) diffWrap.style.display = 'none';
    if (previewShell) { previewShell.style.display = 'flex'; previewShell.style.flex = '1'; }
    if (previewFrame) { previewFrame.style.display = 'block'; previewFrame.style.flex = 'none'; }
    if (codeModeBtn) codeModeBtn.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    if (previewModeBtn) previewModeBtn.style.display = 'none';
    canvasUpdatePreview();
    syncCanvasPreviewDeviceFrame();
    syncCanvasSurfaceWidthLock(tab);
    return;
  }
  // Restore buttons for non-image tabs
  if (codeModeBtn) codeModeBtn.style.display = '';
  if (diffModeBtn) diffModeBtn.style.display = tab.diffAvailable || tab.openMode === 'diff' ? '' : 'none';
  if (previewModeBtn) previewModeBtn.style.display = '';
  if (tab.openMode === 'diff') {
    if (editorWrap) editorWrap.style.display = 'none';
    if (diffWrap) diffWrap.style.display = 'flex';
    if (previewShell) previewShell.style.display = 'none';
    if (previewFrame) previewFrame.style.display = 'none';
    if (codeModeBtn) codeModeBtn.classList.remove('active');
    if (diffModeBtn) diffModeBtn.classList.add('active');
    if (previewModeBtn) previewModeBtn.classList.remove('active');
    renderCanvasDiffInto(diffWrap, tab).catch(() => {});
    syncCanvasSurfaceWidthLock(tab);
    return;
  }
  if (diffModeBtn) diffModeBtn.classList.remove('active');
  if (mode === 'preview') {
    if (editorWrap) editorWrap.style.display = 'none';
    if (previewShell) { previewShell.style.display = 'flex'; previewShell.style.flex = '1'; }
    if (previewFrame) { previewFrame.style.display = 'block'; previewFrame.style.flex = 'none'; }
    if (codeModeBtn) codeModeBtn.classList.remove('active');
    if (previewModeBtn) previewModeBtn.classList.add('active');
    canvasUpdatePreview();
    syncCanvasPreviewDeviceFrame();
  } else {
    if (editorWrap) { editorWrap.style.display = 'flex'; editorWrap.style.flex = '1'; }
    if (previewShell) previewShell.style.display = 'none';
    if (previewFrame) previewFrame.style.display = 'none';
    if (codeModeBtn) codeModeBtn.classList.add('active');
    if (previewModeBtn) previewModeBtn.classList.remove('active');
    if (canvasEditor) {
      setTimeout(() => {
        canvasEditor.setSize('100%', '100%');
        canvasEditor.refresh();
        canvasEditor.focus();
      }, 10);
    }
  }
  syncCanvasSurfaceWidthLock(tab);
}

function canvasRenderTabs() {
  const tabsEl = document.getElementById('canvas-tabs');
  if (!tabsEl) return;
  if (isStructuredCreativeMode()) {
    const label = getStructuredCreativeModeLabel(window.currentCreativeMode);
    tabsEl.innerHTML = `<div class="canvas-tab active" style="cursor:default"><span>${escHtml(label)}</span></div>`;
    const codeModeBtn = document.getElementById('canvas-code-btn');
    const diffModeBtn = document.getElementById('canvas-diff-btn');
    const previewModeBtn = document.getElementById('canvas-preview-btn');
    const saveBtn = document.getElementById('canvas-save-btn');
    const saveControls = document.getElementById('canvas-save-controls');
    if (codeModeBtn) codeModeBtn.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    if (previewModeBtn) previewModeBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    if (saveControls) saveControls.style.display = 'none';
    renderCreativeWorkspace();
    return;
  }
  if (isBrowserCanvasSurfaceActive()) {
    tabsEl.innerHTML = '<div class="canvas-tab active" style="cursor:default"><span>Live Browser</span></div>';
    const codeModeBtn = document.getElementById('canvas-code-btn');
    const diffModeBtn = document.getElementById('canvas-diff-btn');
    const previewModeBtn = document.getElementById('canvas-preview-btn');
    const saveBtn = document.getElementById('canvas-save-btn');
    const saveControls = document.getElementById('canvas-save-controls');
    if (codeModeBtn) codeModeBtn.style.display = 'none';
    if (diffModeBtn) diffModeBtn.style.display = 'none';
    if (previewModeBtn) previewModeBtn.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    if (saveControls) saveControls.style.display = 'none';
    renderBrowserCanvasSurface();
    return;
  }
  tabsEl.innerHTML = canvasTabs.map(t => `
    <div class="canvas-tab ${t.id === activeCanvasTabId ? 'active' : ''} ${t.dirty ? 'canvas-tab-dirty' : ''} ${t.externalChanged ? 'canvas-tab-external' : ''}" onclick="canvasOpenTab('${t.id}')" title="${escHtml(t.externalChanged ? 'Changed outside Canvas · ' : '')}${escHtml(t.diskPath || t.name)}">
      <span>${escHtml(t.name)}</span>
      <button class="canvas-tab-close" onclick="canvasCloseTab('${t.id}', event)" title="Close">×</button>
    </div>
  `).join('') + `<button class="canvas-new-tab" onclick="canvasNewFile()" title="New file">+</button>`;
  const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
  const codeModeBtn = document.getElementById('canvas-code-btn');
  const diffModeBtn = document.getElementById('canvas-diff-btn');
  const previewModeBtn = document.getElementById('canvas-preview-btn');
  const saveBtn = document.getElementById('canvas-save-btn');
  if (codeModeBtn) codeModeBtn.classList.toggle('active', !tab || (tab.mode !== 'preview' && tab.openMode !== 'diff'));
  if (diffModeBtn) {
    diffModeBtn.style.display = tab?.diffAvailable || tab?.openMode === 'diff' ? '' : 'none';
    diffModeBtn.classList.toggle('active', tab?.openMode === 'diff');
  }
  if (previewModeBtn) previewModeBtn.classList.toggle('active', !!(tab && tab.mode === 'preview' && tab.openMode !== 'diff'));
  // Show save controls only for non-image files with a disk path. Keep the
  // original target disabled unless this tab came from an external file.
  const saveControls = document.getElementById('canvas-save-controls');
  if (saveControls) saveControls.style.display = (tab && tab.diskPath && !tab.isImage && !tab.isBinary) ? 'flex' : 'none';
  else if (saveBtn) saveBtn.style.display = (tab && tab.diskPath && !tab.isImage && !tab.isBinary) ? 'flex' : 'none';
  const originalBtn = document.getElementById('canvas-save-original-btn');
  const originalPath = String(tab?.originalPath || '').trim();
  if (originalBtn) {
    originalBtn.disabled = !originalPath;
    originalBtn.title = originalPath ? `Save to ${originalPath}` : 'No external original for this file';
  }
}

async function canvasUpdatePreview() {
  const frame = document.getElementById('canvas-preview-frame');
  const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
  if (!frame || !tab) return;
  const updateVersion = ++canvasPreviewUpdateVersion;
  const content = tab.content || '';
  const ext = (tab.name || '').split('.').pop().toLowerCase();
  const isDesignMode = normalizeCreativeMode(window.currentCreativeMode) === 'design';

  frame.onload = null;
  const useProjectPreview = !!canvasProjectRoot && !tab.isImage && !tab.isBinary;
  const isScriptedPreview = useProjectPreview || isHtmlFile(tab.name) || content.trim().startsWith('<');
  // Design Mode adds editing behavior directly to the preview document. A
  // sandbox without allow-same-origin gives that document an opaque origin,
  // which prevents the parent from attaching the hover/selection handlers.
  // Project previews also need the parent DOM bridge for their editable
  // preview path. Keep the rest of the sandbox restrictions in place (no
  // forms, popups, or top-level navigation), and never grant this bridge to
  // image/binary previews.
  const sandboxPermissions = [isScriptedPreview ? 'allow-scripts' : '', 'allow-downloads'];
  if (useProjectPreview || (isDesignMode && !tab.isImage && !tab.isBinary)) {
    sandboxPermissions.push('allow-same-origin');
  }
  frame.setAttribute('sandbox', sandboxPermissions.filter(Boolean).join(' '));
  if (useProjectPreview) {
    const previewPath = getDesignPreviewEntryPath(tab);
    if (previewPath) {
      // Persist in the background, but never make the visible preview wait for it.
      // Waiting here caused intermittent blank previews until the whole page reloaded.
      void syncDirtyDesignTabsToDisk().catch((err) => {
        addProcessEntry('warn', `Design preview sync failed: ${String(err?.message || err || 'Unknown error')}`);
      });
      if (updateVersion !== canvasPreviewUpdateVersion || activeCanvasTabId !== tab.id) return;
      frame.removeAttribute('src');
      frame.onload = () => {
        try {
          const doc = frame.contentDocument;
          if (!doc || !doc.body) return;
           if (isDesignMode) {
             doc.body.contentEditable = 'false';
             doc.body.spellcheck = false;
             setupDesignPreviewSelection(frame, tab);
           } else {
             doc.body.contentEditable = 'true';
             doc.body.spellcheck = false;
             doc.body.addEventListener('input', () => {
               const html = '<!DOCTYPE html>\n' + doc.documentElement.outerHTML;
               tab.content = html;
             });
           }
        } catch {}
      };
      frame.srcdoc = buildDesignPreviewDocument(content, previewPath);
      return;
    }
  }

  if (tab.isImage) {
    frame.removeAttribute('src');
    const bg = document.documentElement.getAttribute('data-theme') === 'dark' ? '#1f242d' : '#f4f6fb';
    frame.srcdoc = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>
      * { margin: 0; padding: 0; box-sizing: border-box; }
      body { background: ${bg}; display: flex; align-items: center; justify-content: center;
             min-height: 100vh; padding: 16px; }
      img { max-width: 100%; max-height: 100vh; object-fit: contain;
            border-radius: 6px; box-shadow: 0 4px 24px rgba(0,0,0,0.18); }
      .info { position: fixed; bottom: 10px; right: 12px; font-family: monospace;
              font-size: 10px; color: #888; background: rgba(0,0,0,0.45);
              padding: 3px 8px; border-radius: 4px; }
    </style></head><body>
      <img src="${escHtml(content)}" alt="${escHtml(tab.name)}">
      <div class="info">Image preview</div>
    </body></html>`;
    return;
  }

  if (tab.isBinary) {
    if (tab.diskPath) {
      frame.removeAttribute('srcdoc');
      frame.src = `/api/canvas/preview-document?path=${encodeURIComponent(String(tab.diskPath || ''))}&v=${Date.now()}`;
      return;
    }
    frame.removeAttribute('src');
    const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    const bg = isDark ? '#12161d' : '#f5f7fb';
    const panel = isDark ? '#1b2230' : '#ffffff';
    const border = isDark ? '#2f3b51' : '#d7deeb';
    const textColor = isDark ? '#e6edf7' : '#17243b';
    const muted = isDark ? '#97a6ba' : '#5f6f86';
    const fileSize = Number(tab.size || 0);
    const sizeLabel = fileSize > 1024 * 1024
      ? `${(fileSize / (1024 * 1024)).toFixed(2)} MB`
      : fileSize > 1024
        ? `${(fileSize / 1024).toFixed(1)} KB`
        : `${fileSize} bytes`;
    frame.srcdoc = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>
      *{box-sizing:border-box}
      body{margin:0;min-height:100vh;padding:28px;background:${bg};color:${textColor};font-family:Segoe UI,system-ui,sans-serif;display:flex;align-items:center;justify-content:center}
      .card{width:min(720px,92vw);background:${panel};border:1px solid ${border};border-radius:18px;padding:24px;box-shadow:0 16px 44px rgba(0,0,0,.12)}
      .eyebrow{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:${muted};margin-bottom:10px}
      h1{margin:0 0 8px;font-size:24px;line-height:1.2}
      p{margin:0 0 14px;color:${muted};line-height:1.6}
      .meta{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin:18px 0}
      .meta div{padding:10px 12px;border:1px solid ${border};border-radius:12px;background:rgba(127,127,127,.04)}
      .label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:${muted};margin-bottom:4px}
      .value{display:block;font-size:13px;word-break:break-word}
      code{font-family:Cascadia Code,Consolas,monospace;font-size:12px}
    </style></head><body><div class="card">
      <div class="eyebrow">Binary File In Canvas</div>
      <h1>${escHtml(tab.name || 'Document')}</h1>
      <p>This upload is now pinned to the canvas and available to the assistant by exact workspace path, without trying to decode the raw binary as plain text.</p>
      <div class="meta">
        <div><span class="label">Type</span><span class="value">${escHtml(String(tab.mimeType || tab.ext || 'binary'))}</span></div>
        <div><span class="label">Size</span><span class="value">${escHtml(sizeLabel)}</span></div>
        <div><span class="label">Workspace Path</span><span class="value"><code>${escHtml(String(tab.diskPath || ''))}</code></span></div>
      </div>
      <p>For Word files, the assistant should use the <code>docx-reader</code> skill. PDFs and spreadsheets can also be processed from this same workspace path.</p>
    </div></body></html>`;
    return;
  }

  if (ext === 'md') {
    frame.removeAttribute('src');
    const rendered = renderMd(content);
    frame.srcdoc = protectCanvasPreviewDocument(`<!DOCTYPE html><html><head><meta charset="utf-8"><style>
      body{font-family:system-ui,sans-serif;line-height:1.7;padding:24px 32px;max-width:800px;margin:0 auto;color:#17243b}
      h1,h2,h3{font-weight:700;margin:16px 0 8px} code{background:#f0f4fb;padding:2px 6px;border-radius:4px;font-size:0.88em}
      pre{background:#f0f4fb;padding:14px;border-radius:8px;overflow-x:auto} pre code{background:none;padding:0}
      blockquote{border-left:3px solid #3b82f6;padding-left:14px;color:#64748b;margin:10px 0}
      table{border-collapse:collapse;width:100%} th,td{border:1px solid #dbe3ee;padding:6px 10px}
      a{color:#1668e3} hr{border:none;border-top:1px solid #dbe3ee;margin:16px 0}
    </style></head><body>${rendered}</body></html>`);
    return;
  }

  if (ext === 'json') {
    frame.removeAttribute('src');
    try {
      const pretty = JSON.stringify(JSON.parse(content), null, 2);
      frame.srcdoc = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{font-family:monospace;font-size:13px;padding:16px;white-space:pre-wrap;word-break:break-word;color:#17243b}</style></head><body>${pretty.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</body></html>`;
    } catch {
      frame.srcdoc = `<pre style="font-family:monospace;padding:16px;white-space:pre-wrap">${content.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>`;
    }
    return;
  }

  if (!isHtmlFile(tab.name) && !content.trim().startsWith('<')) {
    frame.removeAttribute('src');
    frame.srcdoc = `<pre style="font-family:monospace;padding:16px;white-space:pre-wrap;word-break:break-word">${content.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</pre>`;
    return;
  }
  frame.removeAttribute('src');
  frame.srcdoc = protectCanvasPreviewDocument(content);
  frame.onload = () => {
    try {
      const doc = frame.contentDocument;
      if (!doc || !doc.body) return;
      if (isDesignMode) {
        doc.body.contentEditable = 'false';
        doc.body.spellcheck = false;
        setupDesignPreviewSelection(frame, tab);
      } else {
        doc.body.contentEditable = 'true';
        doc.body.spellcheck = false;
        doc.body.addEventListener('input', () => {
          const html = '<!DOCTYPE html>\n' + doc.documentElement.outerHTML;
          tab.content = html;
          if (canvasEditor && tab.mode !== 'preview') setCanvasEditorValue(html);
        });
      }
    } catch {}
  };
}

function closeCanvasSaveMenu() {
  const menu = document.getElementById('canvas-save-menu');
  const toggle = document.getElementById('canvas-save-menu-btn');
  if (menu) menu.hidden = true;
  if (toggle) toggle.setAttribute('aria-expanded', 'false');
}

function positionCanvasSaveMenu() {
  const menu = document.getElementById('canvas-save-menu');
  const toggle = document.getElementById('canvas-save-menu-btn');
  if (!menu || !toggle || menu.hidden) return;
  const rect = toggle.getBoundingClientRect();
  const width = Math.max(150, menu.offsetWidth || 150);
  const left = Math.max(8, Math.min(window.innerWidth - width - 8, rect.right - width));
  menu.style.position = 'fixed';
  menu.style.left = `${left}px`;
  menu.style.right = 'auto';
  menu.style.top = `${Math.min(window.innerHeight - 8, rect.bottom + 6)}px`;
  menu.style.zIndex = '100000';
}

function toggleCanvasSaveMenu(event) {
  event?.stopPropagation?.();
  const menu = document.getElementById('canvas-save-menu');
  const toggle = document.getElementById('canvas-save-menu-btn');
  if (!menu) return;
  const nextOpen = menu.hidden;
  menu.hidden = !nextOpen;
  if (toggle) toggle.setAttribute('aria-expanded', nextOpen ? 'true' : 'false');
  if (nextOpen) requestAnimationFrame(positionCanvasSaveMenu);
}

if (typeof document !== 'undefined' && !window.__promCanvasSaveMenuInstalled) {
  window.__promCanvasSaveMenuInstalled = true;
  document.addEventListener('pointerdown', (event) => {
    if (!event.target?.closest?.('#canvas-save-controls, #canvas-save-menu')) closeCanvasSaveMenu();
  }, true);
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeCanvasSaveMenu();
  });
  window.addEventListener('resize', positionCanvasSaveMenu, { passive: true });
  window.addEventListener('scroll', positionCanvasSaveMenu, { passive: true, capture: true });
}

async function canvasSave(target = 'workspace') {
  const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
  if (!tab) { addProcessEntry('warn', 'Canvas: no file open to save.'); return; }
  if (canvasEditor && tab.mode !== 'preview') tab.content = canvasEditor.getValue();
  closeCanvasSaveMenu();

  const saveTarget = String(target || 'workspace').toLowerCase() === 'original' ? 'original' : 'workspace';
  const originalPath = String(tab.originalPath || '').trim();
  const previousPath = String(tab.diskPath || '').trim();
  let writePath = saveTarget === 'original' ? originalPath : String(tab.workspacePath || '').trim();
  if (saveTarget === 'original' && !writePath) {
    addProcessEntry('warn', 'Canvas: this file has no external original to save.');
    return;
  }

  const btn = document.getElementById('canvas-save-btn');
  if (btn) { btn.textContent = 'Saving…'; btn.disabled = true; }
  try {
    let data = null;
    if (saveTarget === 'workspace' && !writePath && previousPath && tab.inWorkspace === false) {
      const response = await fetch('/api/canvas/workspace-copy', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sourcePath: previousPath, filename: tab.name, content: tab.content }),
      });
      data = await response.json();
      if (!response.ok || !data.success) throw new Error(data.error || 'Could not create workspace copy');
      writePath = String(data.absPath || data.path || '').trim();
      if (previousPath && previousPath !== writePath) canvasNotifyClose(previousPath);
      tab.workspacePath = writePath;
      tab.diskPath = writePath;
      tab.inWorkspace = true;
      canvasNotifyOpen(writePath);
    } else {
      writePath = writePath || previousPath;
      if (!writePath) {
        const blob = new Blob([tab.content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url; anchor.download = tab.name; anchor.click();
        URL.revokeObjectURL(url);
        addProcessEntry('info', `Canvas: downloaded ${tab.name}`);
        return;
      }
      const response = await fetch('/api/canvas/file', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path: writePath, content: tab.content }),
      });
      data = await response.json();
      if (!response.ok || !data.success) throw new Error(data.error || 'Save failed');
    }
    tab.dirty = false;
    tab.externalChanged = false;
    tab.savedContent = tab.content;
    canvasRenderTabs();
    persistActiveChat();
    addProcessEntry('info', `Canvas: saved ${saveTarget} → ${writePath}`);
  } catch (error) {
    addProcessEntry('error', `Canvas: save error — ${error?.message || error}`);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = '<iconify-icon icon="solar:diskette-bold-duotone" width="14" height="14"></iconify-icon> Save';
    }
  }
}

function canvasSaveOriginal() {
  return canvasSave('original');
}

function canvasAddToContext() {
  const tab = canvasTabs.find(t => t.id === activeCanvasTabId);
  if (!tab) { addProcessEntry('warn', 'Canvas: no file open.'); return; }
  if (canvasEditor && tab.mode !== 'preview') tab.content = canvasEditor.getValue();
  const ext = tab.name.split('.').pop() || 'txt';
  const block = '```' + ext + '\n' + tab.content + '\n```';
  // Send as a message to the LLM so it enters context
  const prompt = `Here is the contents of my file "${tab.name}" for reference:\n\n${block}\n\nI've loaded this file into context. What would you like me to do with it?`;
  const chatInput = document.getElementById('chat-input');
  if (chatInput) {
    chatInput.value = prompt;
    chatInput.style.height = 'auto';
    chatInput.style.height = Math.min(chatInput.scrollHeight, 140) + 'px';
  }
  sendChat();
  addProcessEntry('info', `Canvas: sent ${tab.name} to LLM as context.`);
}

// ──────────────────────────────────────────────────────────────────────────
// CHAT FILE UPLOAD
// Staged files live in pendingChatFiles[] until the user hits Send.
// On send they are uploaded to workspace/uploads/ and loaded into canvas.
// ──────────────────────────────────────────────────────────────────────────

// Each entry: { file: File, name: string, ext: string, text: string|null }
let pendingChatFiles = [];
let pendingChatFileStagingPromises = [];

const TEXT_EXTENSIONS = new Set([
  'txt','md','csv','json','js','ts','jsx','tsx','html','htm','css','scss','less',
  'py','rb','php','java','c','cpp','h','go','rs','sh','bash','yaml','yml',
  'toml','ini','cfg','conf','xml','svg','sql','graphql','vue','svelte','log'
]);

// Images — read as DataURL, uploaded as binary, sent to AI as vision attachment
const IMAGE_EXTENSIONS = new Set(['png','jpg','jpeg','webp','gif','bmp','ico']);
const VIDEO_EXTENSIONS = new Set(['mp4','mov','m4v','webm','avi','mkv','mpeg','mpg','3gp']);
// Other binary types — uploaded as binary, AI reads by path/shell tools
const BINARY_EXTENSIONS = new Set(['pdf','docx','doc','xls','xlsx','pptx','ppt','zip','rar','7z']);

function getCanvasFileIcon(ext) {
  const e = (ext || '').toLowerCase();
  if (['jpg','jpeg','png','gif','webp','bmp','ico','svg'].includes(e)) return '🖼️';
  if (['mp4','mov','avi','mkv','webm'].includes(e)) return '🎥';
  if (['mp3','wav','ogg','flac','m4a'].includes(e)) return '🎵';
  if (['pdf'].includes(e)) return '📄';
  if (['zip','rar','7z','tar','gz'].includes(e)) return '📦';
  if (['doc','docx'].includes(e)) return '📃';
  if (['xls','xlsx','csv'].includes(e)) return '📈';
  if (['ppt','pptx'].includes(e)) return '📊';
  if (['js','ts','jsx','tsx','py','rb','java','c','cpp','go','rs'].includes(e)) return '💻';
  if (['html','htm','css','scss'].includes(e)) return '🌐';
  if (['json','yaml','yml','toml','xml'].includes(e)) return '⚙️';
  if (['md','txt'].includes(e)) return '📝';
  if (['sh','bash'].includes(e)) return '🖥️';
  return '📎';
}

function chatPendingFileKey(fileLike) {
  const file = fileLike?.file || fileLike || {};
  const path = String(file?.path || fileLike?.path || '').trim().toLowerCase();
  if (path) return `path:${path}`;
  const size = Number(file?.size || fileLike?.size || 0);
  const type = String(file?.type || fileLike?.type || '').toLowerCase();
  const name = String(file?.name || fileLike?.name || '').trim().toLowerCase();
  // Pasted screenshots often get unique generated names a few ms apart; size+type
  // is the stable identity for clipboard blobs.
  if (size > 0 && (/^image\//.test(type) || /^video\//.test(type) || /^pasted-/.test(name))) {
    return `blob:${size}:${type || 'application/octet-stream'}`;
  }
  return `file:${name}:${size}:${type}`;
}

function syncChatAttachmentStackVisibility() {
  const stack = document.getElementById('chat-composer-attachment-stack');
  if (!stack) return;
  const hasVisibleContent = Array.from(stack.children).some((child) => {
    if (child.hidden || child.style.display === 'none') return false;
    return window.getComputedStyle(child).display !== 'none';
  });
  stack.style.display = hasVisibleContent ? 'flex' : 'none';
}

function renderChatFilePills() {
  desktopChatRuntime(window.activeChatSessionId)?.replaceAttachments(pendingChatFiles);
  const staging = document.getElementById('chat-file-staging');
  if (!staging) return;
  if (!pendingChatFiles.length) {
    staging.style.display = 'none';
    staging.innerHTML = '';
    syncChatAttachmentStackVisibility();
    updateDesktopComposerSendButton();
    return;
  }
  staging.style.display = 'flex';
  staging.innerHTML = pendingChatFiles.map((f, idx) => {
    const isImg = IMAGE_EXTENSIONS.has(f.ext);
    const preview = isImg && f.dataUrl
      ? `<img class="pill-thumb" src="${f.dataUrl}" alt="">`
      : `<span class="pill-icon" aria-hidden="true">${getCanvasFileIcon(f.ext)}</span>`;
    const kind = f.ext ? f.ext.toUpperCase() : 'FILE';
    return `<div class="chat-file-pill" title="${escHtml(f.name)}">
      ${preview}
      <span class="pill-copy">
        <strong class="pill-name">${escHtml(f.name)}</strong>
        <em class="pill-ext">${escHtml(kind)}</em>
      </span>
      <button class="pill-remove" onclick="removeChatFile(${idx})" title="Remove attachment" aria-label="Remove ${escHtml(f.name)}">&times;</button>
    </div>`;
  }).join('');
  syncChatAttachmentStackVisibility();
  updateDesktopComposerSendButton();
}

function openImgPreview(src, name) {
  if (document.getElementById('img-preview-overlay')) return;
  const overlay = document.createElement('div');
  overlay.id = 'img-preview-overlay';
  overlay.className = 'img-preview-overlay';
  overlay.innerHTML = `
    <div class="img-preview-box" onclick="event.stopPropagation()">
      <button class="img-preview-close" onclick="closeImgPreview()" title="Close">&times;</button>
      <img src="${src}" alt="${name || ''}">
      ${name ? `<div class="img-preview-name">${name}</div>` : ''}
    </div>`;
  overlay.addEventListener('click', closeImgPreview);
  document.body.appendChild(overlay);
  document.addEventListener('keydown', _imgPreviewKeyHandler);
}
function closeImgPreview() {
  const el = document.getElementById('img-preview-overlay');
  if (el) el.remove();
  document.removeEventListener('keydown', _imgPreviewKeyHandler);
}
function _imgPreviewKeyHandler(e) {
  if (e.key === 'Escape') closeImgPreview();
}
window.openImgPreview = openImgPreview;
window.closeImgPreview = closeImgPreview;

function removeChatFile(idx) {
  pendingChatFiles.splice(idx, 1);
  renderChatFilePills();
}

async function stageFiles(fileList) {
  const queuedKeys = new Set(pendingChatFiles.map(chatPendingFileKey));
  const incomingKeys = new Set();
  const uniqueFiles = Array.from(fileList).filter((file) => {
    const key = chatPendingFileKey(file);
    if (queuedKeys.has(key) || incomingKeys.has(key)) return false;
    incomingKeys.add(key);
    return true;
  });
  if (!uniqueFiles.length) return Promise.resolve([]);
  const promises = uniqueFiles.map(file => new Promise(resolve => {
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    if (TEXT_EXTENSIONS.has(ext)) {
      const reader = new FileReader();
      reader.onload = e => resolve({ file, name: file.name, ext, text: e.target.result, dataUrl: null, binary: false });
      reader.onerror = () => resolve({ file, name: file.name, ext, text: null, dataUrl: null, binary: false });
      reader.readAsText(file);
    } else if (IMAGE_EXTENSIONS.has(ext)) {
      // Read as DataURL — enables thumbnail preview and vision attachment
      const reader = new FileReader();
      reader.onload = e => resolve({ file, name: file.name, ext, text: null, dataUrl: e.target.result, binary: false, isImage: true });
      reader.onerror = () => resolve({ file, name: file.name, ext, text: null, dataUrl: null, binary: true, isImage: true });
      reader.readAsDataURL(file);
    } else if (VIDEO_EXTENSIONS.has(ext) || BINARY_EXTENSIONS.has(ext)) {
      // Binary — upload to server as base64, AI reads by path
      resolve({ file, name: file.name, ext, text: null, dataUrl: null, binary: true, base64: null, isVideo: VIDEO_EXTENSIONS.has(ext) });
    } else {
      resolve({ file, name: file.name, ext, text: null, dataUrl: null, binary: true });
    }
  }));
  const stagingPromise = Promise.all(promises).then((staged) => {
    const currentKeys = new Set(pendingChatFiles.map(chatPendingFileKey));
    const newEntries = staged.filter((entry) => {
      const key = chatPendingFileKey(entry);
      if (currentKeys.has(key)) return false;
      currentKeys.add(key);
      return true;
    });
    pendingChatFiles.push(...newEntries);
    renderChatFilePills();
    return newEntries;
  }).finally(() => {
    pendingChatFileStagingPromises = pendingChatFileStagingPromises.filter((p) => p !== stagingPromise);
  });
  pendingChatFileStagingPromises.push(stagingPromise);
  return stagingPromise;
}

async function waitForChatFileStaging() {
  while (pendingChatFileStagingPromises.length) {
    await Promise.allSettled(pendingChatFileStagingPromises.slice());
  }
}

function onChatFileInputChange(event) {
  const files = event.target.files;
  if (!files || !files.length) return;
  stageFiles(files);
  // Reset input so same file can be re-added after removal
  event.target.value = '';
}

function getClipboardFileExtension(mimeType = '', fallbackName = '') {
  const fallbackExt = String(fallbackName || '').split('.').pop().toLowerCase();
  if (fallbackExt && fallbackExt !== fallbackName.toLowerCase()) return fallbackExt;
  const type = String(mimeType || '').toLowerCase();
  if (type.includes('pdf')) return 'pdf';
  if (type.includes('wordprocessingml')) return 'docx';
  if (type.includes('msword')) return 'doc';
  if (type.includes('spreadsheetml')) return 'xlsx';
  if (type.includes('ms-excel')) return 'xls';
  if (type.includes('presentationml')) return 'pptx';
  if (type.includes('ms-powerpoint')) return 'ppt';
  if (type.includes('zip')) return 'zip';
  if (type.includes('json')) return 'json';
  if (type.startsWith('text/')) return 'txt';
  if (type.includes('jpeg') || type.includes('jpg')) return 'jpg';
  if (type.includes('webp')) return 'webp';
  if (type.includes('gif')) return 'gif';
  if (type.includes('bmp')) return 'bmp';
  if (type.includes('svg')) return 'svg';
  if (type.includes('mp4')) return 'mp4';
  if (type.includes('quicktime')) return 'mov';
  if (type.includes('x-m4v')) return 'm4v';
  if (type.includes('webm')) return 'webm';
  if (type.includes('x-msvideo')) return 'avi';
  if (type.includes('x-matroska')) return 'mkv';
  if (type.includes('mpeg')) return 'mpeg';
  if (type.includes('3gpp')) return '3gp';
  return '';
}

function getClipboardImageExtension(mimeType = '') {
  return getClipboardFileExtension(mimeType) || 'png';
}

function getClipboardFileKind(file) {
  const type = String(file?.type || '').toLowerCase();
  const ext = getClipboardFileExtension(type, file?.name);
  if (type.startsWith('image/') || IMAGE_EXTENSIONS.has(ext)) return 'image';
  if (type.startsWith('video/') || VIDEO_EXTENSIONS.has(ext)) return 'video';
  return 'file';
}

function makePastedAttachmentName(file, index = 0) {
  const rawName = String(file?.name || '').trim();
  if (rawName && rawName !== 'image.png' && rawName !== 'video.mp4' && /\.[a-z0-9]+$/i.test(rawName)) return rawName;
  const kind = getClipboardFileKind(file);
  const ext = getClipboardFileExtension(file?.type, rawName) || (kind === 'image' ? 'png' : kind === 'video' ? 'mp4' : 'bin');
  const stamp = new Date().toISOString()
    .replace(/\.\d+Z$/, '')
    .replace(/[^\dT]/g, '')
    .replace('T', '-');
  const suffix = index > 0 ? `-${index + 1}` : '';
  const prefix = kind === 'image' ? 'pasted-screenshot' : kind === 'video' ? 'pasted-video' : 'pasted-file';
  return `${prefix}-${stamp}${suffix}.${ext}`;
}

function makePastedImageName(file, index = 0) {
  return makePastedAttachmentName(file, index);
}

function normalizePastedAttachmentFile(file, index = 0) {
  if (!file) return null;
  const type = String(file.type || '').toLowerCase();
  const kind = getClipboardFileKind(file);
  if (kind === 'file' && !String(file.name || '').trim()) return null;
  const name = makePastedAttachmentName(file, index);
  const ext = getClipboardFileExtension(type, name);
  const mimeType = file.type || (kind === 'image' ? `image/${ext}` : kind === 'video' ? getMimeType(ext) : '');
  try {
    return new File([file], name, {
      type: mimeType,
      lastModified: file.lastModified || Date.now(),
    });
  } catch {
    file.name = file.name || name;
    return file;
  }
}

function normalizePastedImageFile(file, index = 0) {
  const normalized = normalizePastedAttachmentFile(file, index);
  return getClipboardFileKind(normalized) === 'image' ? normalized : null;
}

function getClipboardAttachmentFiles(clipboardData) {
  if (!clipboardData) return [];
  const files = [];
  const seen = new Set();
  // Prefer size+type for clipboard images: Chromium often exposes the same
  // screenshot via both .files and .items, and generated names differ by ms.
  const clipboardKey = (file) => {
    const size = Number(file?.size || 0);
    const type = String(file?.type || '').toLowerCase();
    const name = String(file?.name || '').trim().toLowerCase();
    if (size > 0) return `blob:${size}:${type || 'application/octet-stream'}`;
    return `name:${name}:${type}`;
  };
  const addFile = (file) => {
    if (!file) return;
    const key = clipboardKey(file);
    if (seen.has(key)) return;
    const normalized = normalizePastedAttachmentFile(file, files.length);
    if (!normalized) return;
    seen.add(key);
    // Also mark the normalized name key so stageFiles can't re-add a twin.
    seen.add(clipboardKey(normalized));
    files.push(normalized);
  };

  const fileList = Array.from(clipboardData.files || []).filter(Boolean);
  if (fileList.length) {
    // When FileList is populated it is authoritative. Reading items too is what
    // double-staged the same screenshot on desktop paste.
    fileList.forEach(addFile);
    return files;
  }

  Array.from(clipboardData.items || []).forEach((item) => {
    if (!item || item.kind !== 'file') return;
    try { addFile(item.getAsFile()); } catch {}
  });

  return files;
}

function getClipboardImageFiles(clipboardData) {
  return getClipboardAttachmentFiles(clipboardData)
    .filter((file) => getClipboardFileKind(file) === 'image');
}

async function getBrowserClipboardImageFiles() {
  // Chromium occasionally omits an image from ClipboardEvent.clipboardData
  // while still exposing it through the async Clipboard API (notably copied
  // macOS screenshots in a normal browser tab).
  if (!navigator.clipboard?.read) return [];
  const files = [];
  const seen = new Set();
  const addFile = (file) => {
    const normalized = normalizePastedAttachmentFile(file, files.length);
    if (!normalized || getClipboardFileKind(normalized) !== 'image') return;
    const key = `${normalized.name}:${normalized.size}:${normalized.type}`;
    if (seen.has(key)) return;
    seen.add(key);
    files.push(normalized);
  };
  try {
    const items = await navigator.clipboard.read();
    for (const item of items || []) {
      const imageType = Array.from(item?.types || []).find((type) => /^image\//i.test(String(type)));
      if (!imageType) continue;
      const blob = await item.getType(imageType);
      if (blob) addFile(blob);
    }
  } catch (err) {
    console.debug('[ChatPage] async clipboard image read unavailable:', err);
  }
  return files;
}

function isChatPasteTarget(target) {
  const input = document.getElementById('chat-input');
  const chatView = document.getElementById('chat-view');
  const inputArea = document.querySelector('.chat-input-area');
  if (target === input || inputArea?.contains(target) || chatView?.contains(target)) return true;
  const active = document.activeElement;
  if (active === document.body || active === document.documentElement) return !!chatView;
  return false;
}

function isNonChatEditableTarget(target) {
  if (!target || target === document.getElementById('chat-input')) return false;
  const editable = target.closest?.('input, textarea, select, [contenteditable="true"]');
  return !!editable && editable.id !== 'chat-input';
}

function handleChatPaste(event) {
  if (!isChatPasteTarget(event.target) || isNonChatEditableTarget(event.target)) return;
  // Guard against duplicate capture/bubble listeners or Electron double-dispatch.
  if (event.__promChatPasteHandled) return;
  const files = getClipboardAttachmentFiles(event.clipboardData);
  const pastedText = event.clipboardData?.getData?.('text/plain') || '';
  const stageClipboardFiles = (incoming) => {
    if (!incoming?.length) return;
    stageFiles(incoming).catch((err) => {
      showToast('Could not stage attachment', String(err?.message || err || 'Unknown clipboard error.'), 'error');
    });
    const videoCount = incoming.filter((file) => getClipboardFileKind(file) === 'video').length;
    const imageCount = incoming.filter((file) => getClipboardFileKind(file) === 'image').length;
    const title = incoming.length === 1
      ? (videoCount ? 'Video staged' : imageCount ? 'Screenshot staged' : 'Attachment staged')
      : `${incoming.length} attachments staged`;
    showToast(title, 'Press Send when you are ready.', 'success');
  };

  if (files.length) {
    // Once a file is present, it is the user's attachment intent even if a
    // browser also supplies a text/html representation of that screenshot.
    event.__promChatPasteHandled = true;
    event.preventDefault();
    event.stopImmediatePropagation();
    stageClipboardFiles(files);
    return;
  }

  // Browser screenshots can arrive without clipboardData.files. When there is
  // no text to paste, claim the paste and ask the secure async Clipboard API
  // for an image before the browser silently discards it.
  if (pastedText.trim()) return;
  event.__promChatPasteHandled = true;
  event.preventDefault();
  event.stopImmediatePropagation();
  getBrowserClipboardImageFiles().then((fallbackFiles) => {
    if (fallbackFiles.length) stageClipboardFiles(fallbackFiles);
  });
}

function ensureChatPasteListener() {
  if (window.__prometheusChatPasteInit) return;
  window.__prometheusChatPasteInit = true;
  // Capture phase makes file/image clipboard handling win before editor or
  // browser listeners can consume the event. Register at module load rather
  // than waiting for the delayed composer setup in browser builds.
  document.addEventListener('paste', handleChatPaste, true);
}

function getChatSelectionElement(node) {
  if (!node) return null;
  const element = node.nodeType === Node.ELEMENT_NODE ? node : node.parentElement;
  return element instanceof Element ? element : null;
}

function getChatSelectionDetails() {
  const selection = window.getSelection?.();
  if (!selection || selection.rangeCount < 1 || selection.isCollapsed) return null;
  const text = String(selection.toString() || '').replace(/\s+/g, ' ').trim().slice(0, 2400);
  if (!text) return null;
  const range = selection.getRangeAt(0);
  const chatView = document.getElementById('chat-view');
  const startElement = getChatSelectionElement(range.startContainer);
  const endElement = getChatSelectionElement(range.endContainer);
  if (!chatView || !startElement || !endElement || !chatView.contains(startElement) || !chatView.contains(endElement)) return null;
  if (startElement.closest('.chat-input-area, #chat-text-selection-popover, input, textarea, select, [contenteditable="true"]')
    || endElement.closest('.chat-input-area, #chat-text-selection-popover, input, textarea, select, [contenteditable="true"]')) return null;
  const messageElement = startElement.closest('.msg-shell[data-chat-message-index]');
  const messageIndex = messageElement ? Number(messageElement.getAttribute('data-chat-message-index')) : null;
  const sourceRole = messageElement?.classList.contains('user') ? 'user' : 'assistant';
  const rect = range.getBoundingClientRect?.();
  return {
    text,
    rect: rect && Number.isFinite(rect.left) ? rect : null,
    messageIndex: Number.isInteger(messageIndex) ? messageIndex : null,
    sourceRole,
  };
}

function hideChatTextSelectionPopover() {
  if (chatTextSelectionHideTimer) {
    clearTimeout(chatTextSelectionHideTimer);
    chatTextSelectionHideTimer = null;
  }
  if (!chatTextSelectionPopoverEl) return;
  chatTextSelectionPopoverEl.hidden = true;
  chatTextSelectionPopoverEl.style.display = 'none';
}

function clearChatTextSelectionRange() {
  try {
    const selection = window.getSelection?.();
    if (selection && !selection.isCollapsed) selection.removeAllRanges();
  } catch {}
}

function positionChatTextSelectionPopover(rect, event = null) {
  const popover = chatTextSelectionPopoverEl;
  if (!popover) return;
  const measured = popover.getBoundingClientRect();
  const viewportWidth = Math.max(0, window.innerWidth || document.documentElement.clientWidth || 0);
  const viewportHeight = Math.max(0, window.innerHeight || document.documentElement.clientHeight || 0);
  const sourceRect = rect && rect.width >= 0
    ? rect
    : { left: Number(event?.clientX || 0), right: Number(event?.clientX || 0), top: Number(event?.clientY || 0), bottom: Number(event?.clientY || 0), width: 0, height: 0 };
  const preferredLeft = Number(sourceRect.left || event?.clientX || 0);
  const centeredLeft = sourceRect.width > 0
    ? (Number(sourceRect.left || 0) + Math.max(0, (Number(sourceRect.width) - measured.width) / 2))
    : preferredLeft;
  const left = Math.max(10, Math.min(viewportWidth - measured.width - 10, centeredLeft));
  const below = Number(sourceRect.bottom || event?.clientY || 0) + 8;
  const above = Number(sourceRect.top || event?.clientY || 0) - measured.height - 8;
  const top = below + measured.height <= viewportHeight - 10 || above < 10
    ? Math.max(10, Math.min(viewportHeight - measured.height - 10, below))
    : above;
  popover.style.left = `${Math.round(left)}px`;
  popover.style.top = `${Math.round(top)}px`;
}

async function copyChatHighlightedText(text) {
  const value = String(text || '').trim();
  if (!value) return;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
    } else {
      const helper = document.createElement('textarea');
      helper.value = value;
      helper.style.position = 'fixed';
      helper.style.opacity = '0';
      document.body.appendChild(helper);
      helper.select();
      document.execCommand('copy');
      helper.remove();
    }
    showToast('Copied', 'Highlighted text is on the clipboard.', 'success', 1800);
  } catch (error) {
    showToast('Copy failed', String(error?.message || 'The highlighted text could not be copied.'), 'error');
  }
}

async function openHighlightedTextDetails(details) {
  const text = String(details?.text || '').trim();
  if (!text) return;
  const prompt = [
    'Tell me more about this highlighted text.',
    '',
    `"${text}"`,
    '',
    'Explain what it means, what it is or does, and any surrounding context that would help me understand it. If it is code, explain the behavior and important details plainly.',
  ].join('\n');
  await createSideChat({
    title: 'More details',
    initialText: prompt,
    anchorIndex: details.messageIndex,
    anchorPreview: text,
  });
}

async function runChatTextSelectionAction(action) {
  // Clicking a fixed toolbar can collapse the browser selection in some
  // Electron/Chromium builds even though the toolbar prevents mousedown's
  // default behavior. Keep the exact selection captured when the popover was
  // shown so the action remains reliable.
  const details = getChatSelectionDetails() || chatTextSelectionDetails;
  if (!details) {
    hideChatTextSelectionPopover();
    return;
  }
  hideChatTextSelectionPopover();
  chatTextSelectionDetails = null;
  clearChatTextSelectionRange();
  if (action === 'copy') {
    await copyChatHighlightedText(details.text);
    return;
  }
  if (action === 'add') {
    setChatHighlightedTextContext(details.text, details);
    document.getElementById('chat-input')?.focus?.();
    showToast('Annotation added', 'The highlighted text will be included with your next message.', 'success', 2400);
    return;
  }
  if (action === 'details') {
    try {
      await openHighlightedTextDetails(details);
    } catch (error) {
      showToast('Side chat failed', String(error?.message || error), 'error');
    }
  }
}

function showChatTextSelectionPopover(details, event = null) {
  if (!chatTextSelectionPopoverEl || !details?.text) return;
  chatTextSelectionDetails = { ...details };
  chatTextSelectionPopoverEl.innerHTML = `
    <button type="button" class="chat-text-selection-action chat-text-selection-copy" data-chat-selection-action="copy" title="Copy highlighted text"><iconify-icon icon="solar:copy-bold-duotone" width="14" height="14"></iconify-icon><span>Copy</span></button>
    <span class="chat-text-selection-divider" aria-hidden="true"></span>
    <button type="button" class="chat-text-selection-action" data-chat-selection-action="add"><iconify-icon icon="solar:add-square-bold-duotone" width="14" height="14"></iconify-icon><span>Add to chat</span></button>
    <button type="button" class="chat-text-selection-action" data-chat-selection-action="details"><iconify-icon icon="solar:chat-round-dots-bold-duotone" width="14" height="14"></iconify-icon><span>More details</span></button>`;
  chatTextSelectionPopoverEl.hidden = false;
  chatTextSelectionPopoverEl.style.display = 'inline-flex';
  positionChatTextSelectionPopover(details.rect, event);
}

function initChatTextSelectionPopover() {
  if (chatTextSelectionPopoverBound) return;
  const popover = document.getElementById('chat-text-selection-popover');
  if (!popover) return;
  chatTextSelectionPopoverEl = popover;
  chatTextSelectionPopoverBound = true;
  popover.addEventListener('mousedown', (event) => event.preventDefault());
  popover.addEventListener('click', (event) => {
    const button = event.target.closest?.('[data-chat-selection-action]');
    if (!button) return;
    event.preventDefault();
    event.stopPropagation();
    void runChatTextSelectionAction(button.getAttribute('data-chat-selection-action') || '');
  });
  document.addEventListener('mouseup', (event) => {
    if (popover.contains(event.target)) return;
    setTimeout(() => {
      const details = getChatSelectionDetails();
      if (details) showChatTextSelectionPopover(details, event);
      else hideChatTextSelectionPopover();
    }, 0);
  });
  document.addEventListener('contextmenu', (event) => {
    if (popover.contains(event.target)) return;
    const details = getChatSelectionDetails();
    if (!details) return;
    event.preventDefault();
    event.stopPropagation();
    showChatTextSelectionPopover(details, event);
  }, true);
  document.addEventListener('pointerdown', (event) => {
    if (!popover.contains(event.target)) hideChatTextSelectionPopover();
  }, true);
  document.addEventListener('selectionchange', () => {
    if (chatTextSelectionHideTimer) clearTimeout(chatTextSelectionHideTimer);
    chatTextSelectionHideTimer = setTimeout(() => {
      chatTextSelectionHideTimer = null;
      const details = getChatSelectionDetails();
      if (details) showChatTextSelectionPopover(details);
      else hideChatTextSelectionPopover();
    }, 80);
  });
  window.addEventListener('resize', hideChatTextSelectionPopover, { passive: true });
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    if (!file) {
      reject(new Error('No file bytes available'));
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = String(event.target?.result || '');
      const base64 = dataUrl.replace(/^data:[^;]+;base64,/, '');
      if (!base64) reject(new Error('Could not read file bytes'));
      else resolve(base64);
    };
    reader.onerror = () => reject(new Error('Could not read file bytes'));
    reader.readAsDataURL(file);
  });
}

// Upload staged files to workspace/uploads/ and open them in canvas.
// Returns an array of { name, workspacePath, isImage, base64, mimeType } for context injection.
async function uploadStagedFilesToCanvas(stagedFiles = pendingChatFiles, { signal } = {}) {
  if (!stagedFiles.length) return [];
  const results = [];
  const throwIfAborted = () => {
    if (!signal?.aborted) return;
    const error = new Error('Request stopped');
    error.name = 'AbortError';
    throw error;
  };
  for (const sf of stagedFiles) {
    throwIfAborted();
    if (sf.text !== null) {
      try {
        const r = await fetch('/api/canvas/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: sf.name, content: sf.text }),
          signal,
        });
        const d = await r.json();
        if (d.success) {
          throwIfAborted();
          await canvasPresentFile(d.absPath, d.filename, { autoOpen: false });
          results.push({ name: sf.name, ext: sf.ext, workspacePath: d.absPath, relPath: d.relPath });
        } else {
          results.push({ name: sf.name, ext: sf.ext, workspacePath: null, error: d.error });
        }
      } catch (e) {
        if (signal?.aborted) throw e;
        results.push({ name: sf.name, ext: sf.ext, workspacePath: null, error: e.message });
      }
    } else if (sf.isImage && sf.dataUrl) {
      const mimeType = sf.dataUrl.split(';')[0].replace('data:', '') || `image/${sf.ext}`;
      const pureBase64 = sf.dataUrl.replace(/^data:[^;]+;base64,/, '');
      try {
        const r = await fetch('/api/canvas/upload-binary', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: sf.name, base64: pureBase64, mimeType }),
          signal,
        });
        const d = await r.json();
        if (d.success) {
          throwIfAborted();
          await canvasPresentFile(d.absPath, d.filename, { autoOpen: false });
          results.push({ name: sf.name, ext: sf.ext, workspacePath: d.absPath, relPath: d.relPath, isImage: true, base64: pureBase64, mimeType });
        } else {
          results.push({ name: sf.name, ext: sf.ext, workspacePath: null, isImage: true, base64: pureBase64, mimeType, error: d.error });
        }
      } catch (e) {
        if (signal?.aborted) throw e;
        results.push({ name: sf.name, ext: sf.ext, workspacePath: null, isImage: true, base64: pureBase64, mimeType, error: e.message });
      }
    } else if (sf.base64 || sf.binary) {
      const mimeType = getMimeType(sf.ext);
      let base64 = sf.base64;
      try {
        if (!base64) base64 = await readFileAsBase64(sf.file);
        const r = await fetch('/api/canvas/upload-binary', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: sf.name, base64, mimeType }),
          signal,
        });
        const d = await r.json();
        if (d.success) {
          throwIfAborted();
          await canvasPresentFile(d.absPath, d.filename, { autoOpen: false });
          results.push({ name: sf.name, ext: sf.ext, workspacePath: d.absPath, relPath: d.relPath, binary: true, isVideo: !!sf.isVideo, mimeType });
        } else {
          results.push({ name: sf.name, ext: sf.ext, workspacePath: null, binary: true, isVideo: !!sf.isVideo, mimeType, error: d.error });
        }
      } catch (e) {
        if (signal?.aborted) throw e;
        results.push({ name: sf.name, ext: sf.ext, workspacePath: null, binary: true, isVideo: !!sf.isVideo, mimeType, error: e.message });
      }
    } else {
      results.push({ name: sf.name, ext: sf.ext, workspacePath: null, binary: true });
    }
  }
  return results;
}

function stagedFilesToAttachmentPreviews(stagedFiles) {
  if (!Array.isArray(stagedFiles) || !stagedFiles.length) return [];
  return stagedFiles.map((sf) => {
    if (sf.isImage && sf.dataUrl) {
      return {
        kind: 'image',
        name: sf.name,
        ext: sf.ext || '',
        workspacePath: '',
        dataUrl: sf.dataUrl,
      };
    }
    return {
      kind: sf.isVideo ? 'video' : 'file',
      name: sf.name,
      ext: sf.ext || '',
      workspacePath: '',
      mimeType: sf.binary || sf.isVideo ? getMimeType(sf.ext) : '',
      binary: !!sf.binary,
    };
  });
}

function uploadResultsToAttachmentPreviews(uploadResults) {
  if (!Array.isArray(uploadResults) || !uploadResults.length) return [];
  return uploadResults.map((r) => {
    if (r.isImage && r.base64 && r.mimeType) {
      return {
        kind: 'image',
        name: r.name,
        ext: r.ext || '',
        workspacePath: r.workspacePath || '',
        relPath: r.relPath || '',
        mimeType: r.mimeType || '',
        dataUrl: `data:${r.mimeType};base64,${r.base64}`,
      };
    }
    return {
      kind: r.isVideo ? 'video' : 'file',
      name: r.name,
      ext: r.ext || '',
      workspacePath: r.workspacePath || '',
      mimeType: r.mimeType || '',
      binary: !!r.binary,
    };
  });
}

function designSelectionToAttachmentPreview(context = (isBrowserDesignMode() ? getBrowserCanvasState().selectedElement : designSelectedElementContext)) {
  if (!context || typeof context !== 'object') return null;
  const selector = String(context.selector || '').trim();
  const tagName = String(context.tagName || '').trim();
  const text = String(context.text || '').trim().replace(/\s+/g, ' ');
  const snippet = String(context.htmlSnippet || context.snippet || '').trim().replace(/\s+/g, ' ');
  const label = selector || (context.id ? `#${context.id}` : '') || tagName || 'selected element';
  return {
    kind: 'design-selection',
    name: `Selected: ${label}`,
    ext: tagName || 'element',
    workspacePath: String(context.file || ''),
    previewText: (text || snippet || label).slice(0, 180),
    selector,
  };
}
function getMimeType(ext) {
  const map = {
    pdf: 'application/pdf', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    doc: 'application/msword', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    xls: 'application/vnd.ms-excel', pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    ppt: 'application/vnd.ms-powerpoint', zip: 'application/zip',
    png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', gif: 'image/gif',
    mp4: 'video/mp4', m4v: 'video/x-m4v', mov: 'video/quicktime', webm: 'video/webm',
    avi: 'video/x-msvideo', mkv: 'video/x-matroska', mpeg: 'video/mpeg', mpg: 'video/mpeg', '3gp': 'video/3gpp',
  };
  return map[(ext || '').toLowerCase()] || 'application/octet-stream';
}

// Build the context snippet appended to the user message describing uploaded files.
function buildFileContextNote(uploadResults) {
  if (!uploadResults.length) return '';
  const lines = uploadResults.map(r => {
    if (r.isVideo && r.workspacePath) return `  - "${r.name}" (video) -> saved to: ${r.workspacePath}`;
    if (r.isVideo && !r.workspacePath) return `  - "${r.name}" (video) - upload failed or unavailable`;
    if (r.isImage && r.workspacePath) return `  • "${r.name}" (image) → saved to: ${r.workspacePath}`;
    if (r.isImage && !r.workspacePath) return `  • "${r.name}" (image) — attached for vision analysis`;
    if (r.workspacePath) return `  • "${r.name}" → copied to workspace at: ${r.workspacePath}`;
    if (r.binary) return `  • "${r.name}" — binary file (not copied; view your original)`;
    return `  • "${r.name}" — upload failed: ${r.error || 'unknown error'}`;
  });
  const hasImages = uploadResults.some(r => r.isImage && r.base64);
  const hasVideos = uploadResults.some(r => r.isVideo && r.workspacePath);
  const imageNote = hasImages ? '\nImages above are attached directly — you can see them.' : '';
  const videoNote = hasVideos ? '\nVideos above are saved in the workspace. Use analyze_video when the visual/audio content matters, and in Creative Video mode place them as editable video layers with creative_add_asset or creative_add_element type="video".' : '';
  return `\n\n[UPLOADED FILES]\n${lines.join('\n')}${imageNote}${videoNote}\nUse the exact workspace paths above to read, edit, place, or process files. In Creative Image/Video mode, uploaded images and videos can become editable asset layers with normal x/y/width/height/rotation/opacity/style/animation controls.`;
}

function chatFileUploadInit() {
  // The selection toolbar is independent of file upload, so initialize it
  // before checking for the composer. This also keeps it available on a
  // chat-only/rendered surface that does not expose the upload controls.
  initChatTextSelectionPopover();
  const inputArea = document.querySelector('.chat-input-area');
  if (!inputArea) return;

  // Expand drag target to the full chat column (#chat-view covers messages + input)
  const chatView = document.getElementById('chat-view') || inputArea;

  // Drag-over visual feedback on the full chat column
  chatView.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.stopPropagation();
    chatView.classList.add('drag-over');
  });
  chatView.addEventListener('dragleave', (e) => {
    if (!chatView.contains(e.relatedTarget)) chatView.classList.remove('drag-over');
  });
  chatView.addEventListener('drop', (e) => {
    e.preventDefault();
    e.stopPropagation();
    chatView.classList.remove('drag-over');
    const files = e.dataTransfer?.files;
    if (files && files.length) stageFiles(files);
  });

  ensureChatPasteListener();
}

ensureChatPasteListener();

function setupChatMessageScrollbarFade() {
  const messages = document.getElementById('chat-messages');
  if (!messages || messages.dataset.scrollbarFadeBound === '1') return;
  messages.dataset.scrollbarFadeBound = '1';
  let fadeTimer = null;

  const hideSoon = (delay = 560) => {
    if (fadeTimer) clearTimeout(fadeTimer);
    fadeTimer = setTimeout(() => {
      messages.classList.remove('chat-scroller-active');
      fadeTimer = null;
    }, delay);
  };

  const reveal = () => {
    messages.classList.add('chat-scroller-active');
    hideSoon();
  };

  messages.addEventListener('scroll', reveal, { passive: true });
  messages.addEventListener('wheel', reveal, { passive: true });
  messages.addEventListener('touchmove', reveal, { passive: true });
  messages.addEventListener('pointerdown', reveal);

  wireDesktopTimelineScroller(messages, () => `desktop:main:${window.activeChatSessionId}`, { trackPrimary: true });
  messages.addEventListener('scroll', () => updateChatMessageNavigatorActive(messages), { passive: true });
}

function canvasInitDrop() {
  const panel = document.getElementById('canvas-panel');
  if (!panel) return;
  panel.addEventListener('dragover', (e) => { e.preventDefault(); panel.classList.add('canvas-drag-over'); });
  panel.addEventListener('dragleave', (e) => { if (!panel.contains(e.relatedTarget)) panel.classList.remove('canvas-drag-over'); });
  panel.addEventListener('drop', async (e) => {
    e.preventDefault();
    panel.classList.remove('canvas-drag-over');
    const files = Array.from(e.dataTransfer.files || []);
    if (!files.length) return;
    if (files.some((file) => file.webkitRelativePath)) {
      await canvasImportDirectory(files);
    } else {
      await canvasImportLooseFiles(files);
    }
  });
}

function sanitizeCanvasImportSegment(value) {
  return String(value || '').replace(/[^a-zA-Z0-9._\-() ]/g, '_');
}

function getCanvasNativeFilePath(file) {
  const legacyPath = file?.path || file?.webkitRelativePathNative || '';
  if (legacyPath) return normalizeCanvasPath(legacyPath);
  // In the desktop app Electron's preload resolves the OS path for a File.
  // Browsers deliberately cannot reveal that path, so they fall through to
  // the existing workspace upload flow below.
  try {
    return normalizeCanvasPath(window.prometheusFiles?.getCanvasFilePath?.(file) || '');
  } catch {
    return '';
  }
}

function inferCanvasNativeFolderPath(files) {
  const file = Array.from(files || []).find((candidate) => getCanvasNativeFilePath(candidate) && candidate.webkitRelativePath);
  if (!file) return '';
  const nativePath = getCanvasNativeFilePath(file);
  const relPath = normalizeCanvasPath(file.webkitRelativePath || '');
  const relSegments = relPath.split('/').filter(Boolean);
  if (!nativePath || relSegments.length < 2) return '';
  const nestedPath = relSegments.slice(1).join('/');
  if (!nativePath.endsWith(nestedPath)) return '';
  return normalizeCanvasPath(nativePath.slice(0, nativePath.length - nestedPath.length).replace(/\/+$/, ''));
}

async function readCanvasImportFile(file) {
  const fullName = file.name || 'file';
  const ext = String(fullName).split('.').pop().toLowerCase();
  const textExts = new Set(['txt', 'md', 'json', 'js', 'ts', 'jsx', 'tsx', 'css', 'html', 'htm', 'xml', 'svg', 'py', 'sh', 'yml', 'yaml', 'toml', 'ini', 'env', 'csv']);
  if (textExts.has(ext)) {
    return await new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (event) => resolve({ name: fullName, ext, text: event.target.result, base64: null });
      reader.onerror = () => resolve({ name: fullName, ext, text: null, base64: null });
      reader.readAsText(file);
    });
  }
  return await new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const bytes = new Uint8Array(event.target.result);
      let binary = '';
      for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
      resolve({ name: fullName, ext, text: null, base64: btoa(binary) });
    };
    reader.onerror = () => resolve({ name: fullName, ext, text: null, base64: null });
    reader.readAsArrayBuffer(file);
  });
}

async function uploadCanvasImportFiles(files, options = {}) {
  const imported = [];
  for (const file of files) {
    const parsed = await readCanvasImportFile(file);
    const relativePath = normalizeCanvasPath(options.relativePathForFile ? options.relativePathForFile(file) : '');
    try {
      let response;
      if (parsed.text !== null) {
        response = await fetch('/api/canvas/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: parsed.name, content: parsed.text, relativePath }),
        });
      } else if (parsed.base64) {
        response = await fetch('/api/canvas/upload-binary', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename: parsed.name, base64: parsed.base64, mimeType: getMimeType(parsed.ext), relativePath }),
        });
      } else {
        imported.push({ success: false, name: parsed.name, error: 'Unsupported file type' });
        continue;
      }
      const data = await response.json();
      if (!response.ok || !data.success) {
        imported.push({ success: false, name: parsed.name, error: data.error || `HTTP ${response.status}` });
        continue;
      }
      imported.push({ success: true, name: parsed.name, absPath: data.absPath, relPath: normalizeCanvasPath(data.relPath) });
    } catch (err) {
      imported.push({ success: false, name: parsed.name, error: err.message });
    }
  }
  return imported;
}

async function canvasImportLooseFiles(files) {
  if (!files.length) return;
  const nativePaths = files.map(getCanvasNativeFilePath).filter(Boolean);
  if (nativePaths.length === files.length) {
    for (let i = 0; i < nativePaths.length; i += 1) {
      await canvasPresentFile(nativePaths[i], files[i]?.name || getCanvasProjectDisplayName(nativePaths[i]));
    }
    addProcessEntry('info', `Canvas: connected ${nativePaths.length} file${nativePaths.length === 1 ? '' : 's'} without copying.`);
    return;
  }
  const uploads = await uploadCanvasImportFiles(files);
  const successful = uploads.filter((item) => item.success);
  for (const item of successful) {
    await canvasPresentFile(item.absPath, item.name);
  }
  if (successful.length > 0) {
    await canvasLoadWorkspaceFiles();
    addProcessEntry('info', `Canvas: imported ${successful.length} file${successful.length === 1 ? '' : 's'} into workspace/uploads.`);
  }
}

async function canvasImportDirectory(files) {
  if (!files.length) return;
  const firstRelPath = normalizeCanvasPath(files.find((file) => file.webkitRelativePath)?.webkitRelativePath || '');
  const rootNameRaw = firstRelPath.split('/').filter(Boolean)[0] || 'project';
  const nativeFolderPath = inferCanvasNativeFolderPath(files);
  if (nativeFolderPath) {
    await canvasConnectFolderPath(nativeFolderPath, rootNameRaw);
    return;
  }
  const rootSlug = `${sanitizeCanvasImportSegment(rootNameRaw) || 'project'}_${Date.now()}`;
  const basePrefix = normalizeCanvasPath(`projects/${rootSlug}`);
  const uploads = await uploadCanvasImportFiles(files, {
    relativePathForFile: (file) => {
      const rel = normalizeCanvasPath(file.webkitRelativePath || file.name);
      const segments = rel.split('/').filter(Boolean);
      const nested = segments.length > 1
        ? segments.slice(1).map(sanitizeCanvasImportSegment).join('/')
        : sanitizeCanvasImportSegment(file.name);
      return `${basePrefix}/${nested}`;
    },
  });
  const successful = uploads.filter((item) => item.success);
  if (successful.length === 0) {
    showToast('Folder import failed.', 'error');
    return;
  }
  const firstFile = successful[0];
  const absNorm = normalizeCanvasPath(firstFile.absPath);
  const relNorm = normalizeCanvasPath(firstFile.relPath);
  const workspacePrefix = relNorm && absNorm.endsWith(relNorm)
    ? absNorm.slice(0, absNorm.length - relNorm.length).replace(/\/+$/, '')
    : '';
  const projectRootRel = normalizeCanvasPath(`uploads/${basePrefix}`);
  const projectRootAbs = workspacePrefix ? `${workspacePrefix}/${projectRootRel}` : '';
  try {
    const saved = await persistCanvasProjectRoot(projectRootAbs, rootNameRaw);
    setCanvasProjectState(saved?.projectRoot, saved?.projectLabel);
  } catch (err) {
    showToast(`Canvas project root error: ${err.message}`, 'error');
  }
  await canvasLoadWorkspaceFiles(projectRootAbs);
  await canvasPresentFile(firstFile.absPath, firstFile.name, { skipTreeFocus: true });
  addProcessEntry('info', `Canvas: imported folder "${rootNameRaw}" (${successful.length} files).`);
}

function canvasHasNativePathPicker() {
  return !!(
    window.prometheusFiles
    && typeof window.prometheusFiles.selectCanvasFiles === 'function'
    && typeof window.prometheusFiles.selectCanvasFolder === 'function'
  );
}

async function canvasPickFiles() {
  if (!canvasHasNativePathPicker()) {
    document.getElementById('canvas-file-input')?.click();
    return;
  }
  const paths = await window.prometheusFiles.selectCanvasFiles().catch((err) => {
    showToast(`Could not open file picker: ${err.message || err}`, 'error');
    return [];
  });
  const selectedPaths = Array.isArray(paths) ? paths.filter(Boolean) : [];
  for (const filePath of selectedPaths) {
    await canvasPresentFile(filePath, getCanvasProjectDisplayName(filePath));
  }
  if (selectedPaths.length > 0) {
    addProcessEntry('info', `Canvas: connected ${selectedPaths.length} file${selectedPaths.length === 1 ? '' : 's'} without copying.`);
  }
}

async function canvasConnectFolderPath(folderPath, label = '') {
  const normalizedFolderPath = normalizeCanvasPath(folderPath);
  if (!normalizedFolderPath) return;
  try {
    const saved = await persistCanvasProjectRoot(normalizedFolderPath, label || getCanvasProjectDisplayName(normalizedFolderPath));
    setCanvasProjectState(saved?.projectRoot, saved?.projectLabel);
    canvasFolderExpanded.clear();
    await canvasLoadWorkspaceFiles(saved?.projectRoot || normalizedFolderPath);
    addProcessEntry('info', `Canvas: connected folder ${saved?.projectLabel || label || normalizedFolderPath} without copying.`);
  } catch (err) {
    if (/outside workspace|allowed|invalid project root/i.test(String(err?.message || ''))) {
      const added = await addCanvasAllowedDirectory(
        normalizedFolderPath,
        `Prometheus can't browse this folder yet because it is outside the workspace.\n\nAllow directory:\n${normalizedFolderPath}\n\nThis will add it to Settings > Security > Allowed Paths.`
      );
      if (added) {
        await canvasConnectFolderPath(normalizedFolderPath, label);
        return;
      }
    }
    showToast(`Could not connect folder: ${err.message || err}`, 'error');
  }
}

async function canvasPickFolder() {
  if (!canvasHasNativePathPicker()) {
    document.getElementById('canvas-folder-input')?.click();
    return;
  }
  const paths = await window.prometheusFiles.selectCanvasFolder().catch((err) => {
    showToast(`Could not open folder picker: ${err.message || err}`, 'error');
    return [];
  });
  const folderPath = Array.isArray(paths) ? paths.find(Boolean) : '';
  if (folderPath) await canvasConnectFolderPath(folderPath);
}

// Handle files selected via the "Add File" button (OS file picker)
async function canvasHandleFileInput(input) {
  const files = Array.from(input.files || []);
  if (!files.length) return;
  await canvasImportLooseFiles(files);
  input.value = '';
}

async function canvasHandleFolderInput(input) {
  const files = Array.from(input.files || []);
  if (!files.length) return;
  await canvasImportDirectory(files);
  input.value = '';
}

// ---- Canvas Workspace Integration ----

// Present a workspace file in the canvas (called from SSE handler or "Open in Canvas" button).
// Fetches content from the server and opens/updates a tab.
// Notify the server which files are open in the canvas so the AI always
// knows exact paths without guessing.
function canvasNotifyOpen(diskPath) {
  if (!diskPath || !window.agentSessionId) return;
  fetch('/api/canvas/open', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId: window.agentSessionId, path: diskPath }),
  }).catch(() => {});
}
function canvasNotifyClose(diskPath) {
  if (!diskPath || !window.agentSessionId) return;
  fetch('/api/canvas/close', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ sessionId: window.agentSessionId, path: diskPath }),
  }).catch(() => {});
}

function normalizeCanvasChangePath(value) {
  return String(value || '').trim().replace(/\\/g, '/').replace(/\/+/g, '/').replace(/\/$/, '').toLowerCase();
}

function canvasChangePathMatches(tabPath, changePath) {
  const tabValue = normalizeCanvasChangePath(tabPath);
  const changeValue = normalizeCanvasChangePath(changePath);
  if (!tabValue || !changeValue) return false;
  return tabValue === changeValue
    || tabValue.endsWith(`/${changeValue}`)
    || changeValue.endsWith(`/${tabValue}`);
}

function canvasChangesFromPayload(payload = {}) {
  const candidates = [
    ...(Array.isArray(payload?.files) ? payload.files : []),
    ...(Array.isArray(payload?.workspaceChanges) ? payload.workspaceChanges : []),
    ...(Array.isArray(payload?.workspace_changes) ? payload.workspace_changes : []),
    ...(Array.isArray(payload?.run?.workspaceChanges) ? payload.run.workspaceChanges : []),
  ];
  return Array.from(new Map(candidates
    .filter((file) => file && typeof file === 'object')
    .map((file) => [normalizeCanvasChangePath(file.path || file.displayPath || file.file), file])
    .filter(([key]) => key)).values());
}

async function refreshOpenCanvasFiles(payload = {}, options = {}) {
  const changes = canvasChangesFromPayload(payload);
  if (!changes.length) return 0;
  const affected = canvasTabs.filter((tab) => changes.some((change) => (
    canvasChangePathMatches(tab.diskPath, change.path || change.displayPath)
    || canvasChangePathMatches(tab.workspacePath, change.path || change.displayPath)
    || canvasChangePathMatches(tab.originalPath, change.path || change.displayPath)
    || canvasChangePathMatches(tab.diskPath, change.oldPath || change.old_path)
  )));
  if (!affected.length) return 0;
  let refreshed = 0;
  await Promise.all(affected.map(async (tab) => {
    const change = changes.find((candidate) => (
      canvasChangePathMatches(tab.diskPath, candidate.path || candidate.displayPath)
      || canvasChangePathMatches(tab.workspacePath, candidate.path || candidate.displayPath)
      || canvasChangePathMatches(tab.originalPath, candidate.path || candidate.displayPath)
      || canvasChangePathMatches(tab.diskPath, candidate.oldPath || candidate.old_path)
    ));
    if (!change) return;
    if (tab.dirty && options.force !== true) {
      if (!tab.externalChanged) showToast('Canvas file changed', `${tab.name} has newer workspace content. Save or reload it to review.`, 'info', 4500);
      tab.externalChanged = true;
      return;
    }
    const oldPath = String(tab.diskPath || '').trim();
    const renamedPath = String(change.status || '').toLowerCase() === 'renamed'
      ? String(change.path || '').trim()
      : '';
    const targetPath = renamedPath || String(tab.workspacePath || tab.diskPath || '').trim();
    if (!targetPath || String(change.status || '').toLowerCase() === 'deleted') {
      tab.externalChanged = true;
      return;
    }
    try {
      const response = await fetch(`/api/canvas/file?path=${encodeURIComponent(targetPath)}`);
      const data = await response.json();
      if (!response.ok || !data.success) throw new Error(data.error || 'File is no longer available');
      const fileName = targetPath.split(/[\\/]/).filter(Boolean).pop() || tab.name;
      if (data.isImage) {
        tab.content = `data:${data.mimeType};base64,${data.base64}`;
        tab.savedContent = tab.content;
        tab.isImage = true;
        tab.isBinary = false;
        tab.mimeType = data.mimeType;
      } else if (data.isBinary) {
        tab.content = '';
        tab.savedContent = '';
        tab.isImage = false;
        tab.isBinary = true;
        tab.mimeType = data.mimeType;
        tab.ext = data.ext || (fileName.split('.').pop() || '').toLowerCase();
        tab.size = data.size || 0;
        tab.mode = 'preview';
      } else {
        tab.content = String(data.content || '');
        tab.savedContent = tab.content;
        tab.isImage = false;
        tab.isBinary = false;
      }
      if (renamedPath && oldPath && oldPath !== renamedPath) {
        canvasNotifyClose(oldPath);
        tab.diskPath = renamedPath;
        tab.name = fileName;
        tab.workspacePath = renamedPath;
        tab.inWorkspace = true;
        canvasNotifyOpen(renamedPath);
      }
      tab.dirty = false;
      tab.externalChanged = false;
      if (canvasEditor && activeCanvasTabId === tab.id && !tab.isBinary && !tab.isImage) {
        setCanvasEditorValue(tab.content);
        canvasEditor.setOption('mode', tab.language || getCanvasLang(tab.name));
      }
      if (activeCanvasTabId === tab.id && tab.openMode === 'diff') {
        const diffWrap = document.getElementById('canvas-diff-wrap');
        if (diffWrap) renderCanvasDiffInto(diffWrap, tab).catch(() => {});
      }
      refreshed += 1;
    } catch {
      tab.externalChanged = true;
    }
  }));
  if (refreshed) {
    canvasRenderTabs();
    const activeTab = canvasTabs.find((tab) => tab.id === activeCanvasTabId);
    if (activeTab && activeTab.mode === 'preview') canvasUpdatePreview();
    const tree = document.getElementById('canvas-project-tree');
    if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
  } else if (affected.some((tab) => tab.externalChanged)) {
    canvasRenderTabs();
  }
  return refreshed;
}

async function canvasPresentFileLegacy(diskPath, label) {
  if (!diskPath) return;
  const name = label || diskPath.split('/').pop() || diskPath;
  let tab = canvasTabs.find(t => t.diskPath === diskPath);
  if (tab) {
    try {
      const r = await fetch(`/api/canvas/file?path=${encodeURIComponent(diskPath)}`);
      const d = await r.json();
      if (d.success) {
        if (d.isImage) {
          const dataUrl = `data:${d.mimeType};base64,${d.base64}`;
          tab.content = dataUrl;
          tab.savedContent = dataUrl;
          tab.isImage = true;
          tab.isBinary = false;
          tab.mimeType = d.mimeType;
        } else if (d.isBinary) {
          tab.content = '';
          tab.savedContent = '';
          tab.isImage = false;
          tab.isBinary = true;
          tab.mimeType = d.mimeType;
          tab.ext = d.ext || (name.split('.').pop() || '').toLowerCase();
          tab.size = d.size || 0;
          tab.mode = 'preview';
        } else {
          tab.content = d.content;
          tab.savedContent = d.content;
          tab.isImage = false;
          tab.isBinary = false;
          tab.mode = (name.endsWith('.html') || name.endsWith('.htm') || name.endsWith('.md')) ? 'preview' : 'code';
          if (canvasEditor && activeCanvasTabId === tab.id) {
            setCanvasEditorValue(d.content);
            canvasEditor.setOption('mode', getCanvasLang(name));
          }
        }
        tab.dirty = false;
      }
	    } catch {}
	    if (!canvasOpen) toggleCanvas();
	    canvasOpenTab(tab.id);
	    await ensureCanvasTreeFocusedForFile(diskPath);
	    const tree = document.getElementById('canvas-project-tree');
	    if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
	    return;
	  }
  try {
    const r = await fetch(`/api/canvas/file?path=${encodeURIComponent(diskPath)}`);
    const d = await r.json();
    if (!d.success) { addProcessEntry('error', `Canvas: could not load ${diskPath} â€” ${d.error}`); return; }
    const id = 'ctab_' + Math.random().toString(36).slice(2);
    const ext = name.split('.').pop().toLowerCase();
    if (d.isImage) {
      const dataUrl = `data:${d.mimeType};base64,${d.base64}`;
      canvasTabs.push({
        id, name, content: dataUrl, savedContent: dataUrl,
        diskPath, dirty: false,
        mode: 'preview',
        language: 'null',
        isImage: true,
        mimeType: d.mimeType,
      });
    } else if (d.isBinary) {
      canvasTabs.push({
        id, name, content: '', savedContent: '',
        diskPath, dirty: false,
        mode: 'preview',
        language: 'null',
        isBinary: true,
        mimeType: d.mimeType,
        ext: d.ext || ext,
        size: d.size || 0,
      });
    } else {
      const autoPreview = ext === 'html' || ext === 'htm' || ext === 'md';
      canvasTabs.push({
        id, name, content: d.content, savedContent: d.content,
        diskPath, dirty: false,
        mode: autoPreview ? 'preview' : 'code',
        language: getCanvasLang(name),
      });
    }
    if (!canvasOpen) toggleCanvas();
    canvasOpenTab(id);
    canvasNotifyOpen(diskPath);
    addProcessEntry('info', `Canvas: opened ${diskPath}`);
    const tree = document.getElementById('canvas-project-tree');
    if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
    persistActiveChat();
  } catch (e) {
    addProcessEntry('error', `Canvas: fetch error â€” ${e.message}`);
  }
}

async function canvasPresentFile(diskPath, label, options = {}) {
  if (!diskPath) return;
  const shouldAutoOpen = options.autoOpen !== false;
  const notifyWhenClosed = options.notifyWhenClosed !== false;
  const markCanvasHasHiddenFile = () => {
    if (canvasOpen || !notifyWhenClosed) return;
    const dot = document.getElementById('canvas-notify-dot');
    if (dot) dot.style.display = 'block';
  };
  const name = label || diskPath.split('/').pop() || diskPath;
  const requestedDiff = String(options.openMode || '').toLowerCase() === 'diff';
  const requestedDiffRoot = String(options.diffRoot || '').trim();
  const applyRequestedOpenMode = (candidate) => {
    if (!candidate || !requestedDiff) return;
    candidate.openMode = 'diff';
    candidate.diffAvailable = true;
    candidate.diffView = String(options.diffView || candidate.diffView || 'turn');
    if (requestedDiffRoot) candidate.diffRoot = requestedDiffRoot;
  };
  const requestedOpenMode = requestedDiff
    ? { openMode: 'diff', diffAvailable: true, diffView: String(options.diffView || 'turn'), ...(requestedDiffRoot ? { diffRoot: requestedDiffRoot } : {}) }
    : {};
  let tab = canvasTabs.find((candidate) => candidate.diskPath === diskPath);
  if (tab) {
    try {
      const response = await fetch(`/api/canvas/file?path=${encodeURIComponent(diskPath)}`);
      const data = await response.json();
      if (data.success) {
        tab.inWorkspace = data.inWorkspace !== false;
        if (tab.inWorkspace) tab.workspacePath = diskPath;
        else if (!tab.originalPath) tab.originalPath = diskPath;
        if (data.isImage) {
          const dataUrl = `data:${data.mimeType};base64,${data.base64}`;
          tab.content = dataUrl;
          tab.savedContent = dataUrl;
          tab.isImage = true;
          tab.isBinary = false;
          tab.mimeType = data.mimeType;
        } else if (data.isBinary) {
          tab.content = '';
          tab.savedContent = '';
          tab.isImage = false;
          tab.isBinary = true;
          tab.mimeType = data.mimeType;
          tab.ext = data.ext || (name.split('.').pop() || '').toLowerCase();
          tab.size = data.size || 0;
          tab.mode = 'preview';
        } else {
          tab.content = data.content;
          tab.savedContent = data.content;
          tab.isImage = false;
          tab.isBinary = false;
          tab.mode = (name.endsWith('.html') || name.endsWith('.htm') || name.endsWith('.md')) ? 'preview' : 'code';
          if (canvasEditor && activeCanvasTabId === tab.id) {
            setCanvasEditorValue(data.content);
            canvasEditor.setOption('mode', getCanvasLang(name));
          }
        }
        tab.dirty = false;
      }
    } catch {}
    applyRequestedOpenMode(tab);
    if (!canvasOpen && shouldAutoOpen) toggleCanvas();
    else markCanvasHasHiddenFile();
    canvasOpenTab(tab.id);
    if (!options.skipTreeFocus) await ensureCanvasTreeFocusedForFile(diskPath);
    const tree = document.getElementById('canvas-project-tree');
    if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
    return;
  }
  try {
    const response = await fetch(`/api/canvas/file?path=${encodeURIComponent(diskPath)}`);
    const data = await response.json();
    if (!data.success) {
      if (response.status === 403 && /allowed directories/i.test(String(data.error || ''))) {
        try {
          const added = await promptAllowCanvasDirectory(diskPath);
          if (added) {
            await canvasPresentFile(diskPath, label, options);
            return;
          }
        } catch (err) {
          showToast(`Could not add allowed directory`, err.message || 'Unknown error', 'error');
        }
      }
      addProcessEntry('error', `Canvas: could not load ${diskPath} - ${data.error}`);
      return;
    }
    const id = 'ctab_' + Math.random().toString(36).slice(2);
    const ext = name.split('.').pop().toLowerCase();
    const inWorkspace = data.inWorkspace !== false;
    const canvasPathMeta = {
      inWorkspace,
      workspacePath: inWorkspace ? diskPath : '',
      originalPath: inWorkspace ? '' : diskPath,
    };
    if (data.isImage) {
      const dataUrl = `data:${data.mimeType};base64,${data.base64}`;
      canvasTabs.push({
        id, name, content: dataUrl, savedContent: dataUrl,
        diskPath, dirty: false,
        ...canvasPathMeta,
        ...requestedOpenMode,
        mode: 'preview',
        language: 'null',
        isImage: true,
        mimeType: data.mimeType,
      });
    } else if (data.isBinary) {
      canvasTabs.push({
        id, name, content: '', savedContent: '',
        diskPath, dirty: false,
        ...canvasPathMeta,
        ...requestedOpenMode,
        mode: 'preview',
        language: 'null',
        isBinary: true,
        mimeType: data.mimeType,
        ext: data.ext || ext,
        size: data.size || 0,
      });
    } else {
      const autoPreview = ext === 'html' || ext === 'htm' || ext === 'md';
      canvasTabs.push({
        id, name, content: data.content, savedContent: data.content,
        diskPath, dirty: false,
        ...canvasPathMeta,
        ...requestedOpenMode,
        mode: autoPreview ? 'preview' : 'code',
        language: getCanvasLang(name),
      });
    }
    if (!canvasOpen && shouldAutoOpen) toggleCanvas();
    else markCanvasHasHiddenFile();
    canvasOpenTab(id);
    if (!options.skipTreeFocus) await ensureCanvasTreeFocusedForFile(diskPath);
    canvasNotifyOpen(diskPath);
    addProcessEntry('info', `Canvas: opened ${diskPath}`);
    const tree = document.getElementById('canvas-project-tree');
    if (tree && canvasWorkspaceTree.length) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
    persistActiveChat();
  } catch (err) {
    addProcessEntry('error', `Canvas: fetch error - ${err.message}`);
  }
}

async function canvasClearProjectRoot() {
  try {
    const saved = await persistCanvasProjectRoot('', '');
    setCanvasProjectState(saved?.projectRoot, saved?.projectLabel);
    canvasWorkspaceTree = [];
    canvasWorkspaceRootPath = '';
    canvasFolderExpanded.clear();
    await canvasLoadWorkspaceFiles();
    const activeTab = canvasTabs.find((tab) => tab.id === activeCanvasTabId) || null;
    applyCanvasViewMode(activeTab?.mode || 'code', activeTab);
    canvasRenderTabs();
    addProcessEntry('info', 'Canvas: returned to the full workspace browser.');
  } catch (err) {
    showToast(`Could not clear project root: ${err.message}`, 'error');
  }
}

function toggleCanvasWorkspaceSidebar() {
  canvasBrowserCollapsed = !canvasBrowserCollapsed;
  updateCanvasWorkspaceChrome();
}

function toggleCanvasFolder(folderPath) {
  const nextPath = normalizeCanvasPath(folderPath);
  if (!nextPath) return;
  if (canvasFolderExpanded.has(nextPath)) canvasFolderExpanded.delete(nextPath);
  else canvasFolderExpanded.add(nextPath);
  const tree = document.getElementById('canvas-project-tree');
  if (tree) tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
}

async function canvasUseFolderAsProject(folderPath, folderName, ev) {
  if (ev) ev.stopPropagation();
  try {
    const saved = await persistCanvasProjectRoot(folderPath, folderName || getCanvasProjectDisplayName(folderPath));
    setCanvasProjectState(saved?.projectRoot, saved?.projectLabel);
    canvasFolderExpanded.clear();
    await canvasLoadWorkspaceFiles(saved?.projectRoot);
    addProcessEntry('info', `Canvas: project root set to ${saved?.projectLabel || folderName || folderPath}.`);
  } catch (err) {
    showToast(`Could not set project root: ${err.message}`, 'error');
  }
}

// Load workspace file list. Callers can opt into expanding the browser panel.
async function canvasLoadWorkspaceFiles(rootOverride = null, options = {}) {
  const tree = document.getElementById('canvas-project-tree');
  if (!tree) return;
  tree.innerHTML = '<div style="padding:12px;color:var(--muted);font-size:11px">Loading…</div>';
  try {
    const sid = String(window.activeChatSessionId || window.agentSessionId || '').trim();
    const qs = new URLSearchParams();
    if (sid) qs.set('sessionId', sid);
    if (rootOverride) qs.set('root', normalizeCanvasPath(rootOverride));
    const r = await fetch(`/api/canvas/files?${qs.toString()}`);
    const d = await r.json();
    if (!d.success) { tree.innerHTML = `<div style="padding:12px;color:var(--err)">${escHtml(d.error)}</div>`; return; }
    const nextRoot = normalizeCanvasPath(d.rootAbsPath || d.rootPath || '');
    if (canvasWorkspaceRootPath !== nextRoot) canvasFolderExpanded.clear();
    canvasWorkspaceRootPath = nextRoot;
    canvasWorkspaceTree = Array.isArray(d.files) ? d.files : [];
    if (d.projectRoot || canvasProjectRoot) {
      setCanvasProjectState(d.projectRoot || canvasProjectRoot, d.projectLabel || canvasProjectLabel, {
        persist: false,
        expandBrowser: options.expandBrowser === true,
      });
    } else {
      updateCanvasWorkspaceChrome();
    }
    tree.innerHTML = canvasRenderWorkspaceTree(canvasWorkspaceTree, 0);
    updateCanvasWorkspaceChrome();
  } catch (e) {
    tree.innerHTML = `<div style="padding:12px;color:var(--err)">${escHtml(e.message)}</div>`;
  }
}

function canvasHideFileBrowser() {
  canvasBrowserCollapsed = true;
  updateCanvasWorkspaceChrome();
}

function canvasRenderFileTree(nodes, depth) {
  if (!Array.isArray(nodes) || !nodes.length) return '';
  const icons = { html:'\uD83D\uDCC4', htm:'\uD83D\uDCC4', md:'\uD83D\uDCDD', ts:'\uD83D\uDCBB', js:'\uD83D\uDCBB', json:'{ }', css:'\uD83C\uDFA8', py:'\uD83D\uDC0D', txt:'\uD83D\uDCCB', sh:'\u25BA' };
  let html = '';
  const sorted = [...nodes].sort((a, b) => {
    if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
  for (const node of sorted) {
    const pad = depth * 12;
    if (node.type === 'dir') {
      html += `<div class="canvas-file-tree-dir" style="padding-left:${pad + 12}px">📁 ${escHtml(node.name)}</div>`;
      if (node.children && node.children.length) html += canvasRenderFileTree(node.children, depth + 1);
    } else {
      const ext = node.name.split('.').pop().toLowerCase();
      const icon = icons[ext] || '\uD83D\uDCC4';
      html += `<div class="canvas-file-tree-item" style="padding-left:${pad + 12}px" onclick="canvasPresentFile('${escHtml(node.path).replace(/'/g, '\\&apos;')}', '${escHtml(node.name).replace(/'/g, '\\&apos;')}')">${icon} ${escHtml(node.name)}</div>`;
    }
  }
  return html;
}

function canvasRenderWorkspaceTree(nodes, depth) {
  if (!Array.isArray(nodes) || !nodes.length) return '';
  const icons = { html:'\uD83D\uDCC4', htm:'\uD83D\uDCC4', md:'\uD83D\uDCDD', ts:'\uD83D\uDCBB', js:'\uD83D\uDCBB', json:'{ }', css:'\uD83C\uDFA8', py:'\uD83D\uDC0D', txt:'\uD83D\uDCCB', sh:'\u25BA' };
  const sorted = [...nodes].sort((a, b) => {
    if (a.type !== b.type) return a.type === 'dir' ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
  return sorted.map((node) => {
    const pad = depth * 12;
    if (node.type === 'dir') {
      const folderPath = normalizeCanvasPath(node.path);
      const isOpen = canvasFolderExpanded.has(folderPath);
      const isProjectRoot = !!canvasProjectRoot && normalizeCanvasPath(canvasProjectRoot) === folderPath;
      return `
        <div>
          <div class="canvas-file-tree-dir" style="display:flex;align-items:center;gap:6px;padding:7px 8px;padding-left:${pad + 12}px;border-radius:8px;cursor:pointer;background:${isProjectRoot ? 'rgba(249,115,22,0.14)' : 'transparent'}" onclick="toggleCanvasFolder('${escHtml(folderPath).replace(/'/g, '\\&apos;')}')">
            <span style="color:var(--muted);font-size:10px;width:10px;flex-shrink:0">${isOpen ? '▼' : '▶'}</span>
            <span>📁</span>
            <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:${isProjectRoot ? '800' : '700'}">${escHtml(node.name)}</span>
            ${isProjectRoot ? `<span style="font-size:10px;color:#fb923c;font-weight:800">ROOT</span>` : `<button onclick="canvasUseFolderAsProject('${escHtml(folderPath).replace(/'/g, '\\&apos;')}', '${escHtml(node.name).replace(/'/g, '\\&apos;')}', event)" style="border:1px solid var(--line);background:var(--panel);color:var(--muted);border-radius:6px;padding:1px 6px;font-size:10px;cursor:pointer">Use</button>`}
          </div>
          ${isOpen && node.children && node.children.length ? `<div style="margin-left:${pad + 18}px;border-left:1px solid rgba(255,255,255,0.08)">${canvasRenderWorkspaceTree(node.children, depth + 1)}</div>` : ''}
        </div>`;
    }
    const ext = node.name.split('.').pop().toLowerCase();
    const icon = icons[ext] || '\uD83D\uDCC4';
    const filePath = normalizeCanvasPath(node.path);
    const isActive = canvasTabs.some((tab) => normalizeCanvasPath(tab.diskPath) === filePath);
    return `<div class="canvas-file-tree-item" style="padding:7px 8px;padding-left:${pad + 12}px;border-radius:8px;cursor:pointer;background:${isActive ? 'rgba(249,115,22,0.14)' : 'transparent'}" onclick="canvasPresentFile('${escHtml(filePath).replace(/'/g, '\\&apos;')}', '${escHtml(node.name).replace(/'/g, '\\&apos;')}')">${icon} ${escHtml(node.name)}</div>`;
  }).join('');
}

const SESSION_APPROVAL_RISK_COLORS = {
  low: { bg: '#eefbf3', border: '#a7e3be', badge: '#dbf4e5', text: '#1f7a47', strongText: '#14532d' },
  medium: { bg: '#eff5ff', border: '#bfd3f4', badge: '#dce9ff', text: '#335d99', strongText: '#1e3a5f' },
  high: { bg: '#fff4ec', border: '#fdc9a8', badge: '#ffe3d0', text: '#b35d14', strongText: '#7c2d12' },
};

function getApprovalRiskLevel(score) {
  if (score >= 7) return 'high';
  if (score >= 4) return 'medium';
  return 'low';
}

function getApprovalToolLabel(toolName = '') {
  const tool = String(toolName || '').trim();
  if (!tool) return 'action';
  if (tool === 'desktop_click') return 'desktop click';
  if (tool === 'desktop_press_key') return 'desktop keypress';
  if (tool === 'browser_click') return 'browser click';
  if (tool === 'browser_press_key' || tool === 'browser_key') return 'browser keypress';
  if (tool === 'run_command') return 'command';
  return tool.replace(/_/g, ' ');
}

function summarizeApprovalForHumans(record = {}, fallback = {}) {
  const toolName = String(record.toolName || fallback.toolName || '').trim();
  const approvalKind = String(record.approvalKind || fallback.approvalKind || '').trim();
  const status = String(record.status || fallback.status || 'pending').trim().toLowerCase();
  const args = record.toolArgs && typeof record.toolArgs === 'object' ? record.toolArgs : {};
  const finalAction = record.finalAction || fallback.finalAction || null;
  const devSourceEdit = record.devSourceEdit || fallback.devSourceEdit || null;
  const isFinalAction = approvalKind === 'final_action' || toolName === 'request_final_action_approval';
  const isDevSource = approvalKind === 'dev_source_edit' || toolName === 'request_dev_source_edit';

  if (approvalKind === 'elevated_command') {
    const command = String(args.command || record.command || '').trim();
    return {
      title: 'Administrator command',
      summary: 'Run this exact command with Windows administrator privileges after your one-shot approval.',
      detail: command,
    };
  }

  if (isFinalAction) {
    const target = String(finalAction?.targetLabel || args.target_label || 'final action').trim();
    const summary = String(finalAction?.summary || record.reason || fallback.summary || '').trim();
    return {
      title: status === 'pending' ? `Ready to ${String(finalAction?.actionKind || args.action_kind || 'continue')}` : 'Final action',
      summary: summary || `Approve ${target}.`,
      detail: target,
    };
  }

  if (isDevSource) {
    const files = Array.isArray(devSourceEdit?.allowedFiles) ? devSourceEdit.allowedFiles : [];
    return {
      title: 'Dev source edit',
      summary: String(record.reason || fallback.summary || 'Approve a scoped source edit.').trim(),
      detail: files.length ? `${files.length} file${files.length === 1 ? '' : 's'} requested` : '',
    };
  }

  if (toolName === 'run_command') {
    const command = String(args.command || record.command || '').trim();
    const boundary = record.commandBoundary || fallback.commandBoundary || null;
    const boundaryScope = String(boundary?.scope || '').trim();
    return {
      title: boundaryScope && boundaryScope !== 'workspace' ? 'Outside-workspace command' : 'Command approval',
      summary: boundaryScope && boundaryScope !== 'workspace'
        ? `Run a command that may change ${boundaryScope.replace(/_/g, ' ')} state.`
        : (command ? `Run command${args.cwd ? ` in ${args.cwd}` : ''}` : 'Run a command.'),
      detail: command,
    };
  }

  if (toolName.startsWith('desktop_')) {
    const windowLabel = String(args.window_name || args.app || '').trim();
    const target = args.element != null
      ? `element ${args.element}`
      : Number.isFinite(Number(args.x)) && Number.isFinite(Number(args.y))
        ? `point ${Number(args.x)}, ${Number(args.y)}`
        : '';
    return {
      title: status === 'pending' ? 'Desktop action' : 'Desktop action',
      summary: `${status === 'pending' ? 'Approve' : 'Review'} ${getApprovalToolLabel(toolName)}${windowLabel ? ` in ${windowLabel}` : ''}.`,
      detail: target,
    };
  }

  if (toolName.startsWith('browser_')) {
    const target = args.element || args.selector || (args.ref != null ? `ref ${args.ref}` : '');
    return {
      title: status === 'pending' ? 'Browser action' : 'Browser action',
      summary: `${status === 'pending' ? 'Approve' : 'Review'} ${getApprovalToolLabel(toolName)}.`,
      detail: String(target || '').trim(),
    };
  }

  return {
    title: toolName ? `${getApprovalToolLabel(toolName)} approval` : 'Approval required',
    summary: String(record.reason || fallback.reason || record.summary || fallback.summary || record.action || '').trim(),
    detail: '',
  };
}

function renderSessionApprovalCard(item) {
  const risk = getApprovalRiskLevel(item.riskScore ?? 0);
  const palette = SESSION_APPROVAL_RISK_COLORS[risk] || SESSION_APPROVAL_RISK_COLORS.medium;
  const systems = Array.isArray(item.affectedSystems) ? item.affectedSystems : [];
  const status = String(item.status || 'pending').toLowerCase();
  const isProposal = item.approvalType === 'proposal';
  const isDevSource = item.approvalKind === 'dev_source_edit' || item.toolName === 'request_dev_source_edit';
  const isFinalAction = item.approvalKind === 'final_action' || item.toolName === 'request_final_action_approval';
  const isOneShot = item.oneShot === true || item.approvalKind === 'elevated_command' || isDevSource || isFinalAction;
  const pathAccessPaths = Array.from(new Set([
    item.pathAccess?.requestedPath,
    ...(Array.isArray(item.pathAccess?.requestedPaths) ? item.pathAccess.requestedPaths : []),
  ].map((value) => String(value || '').trim()).filter(Boolean)));
  const approveEndpoint = isProposal ? `/api/proposals/${item.id}/approve` : `/api/approvals/${item.id}/approve`;
  const denyEndpoint = isProposal ? `/api/proposals/${item.id}/deny` : `/api/approvals/${item.id}/deny`;
  return `<div class="approval-card" style="background:${palette.bg};border-color:${palette.border};padding:10px 12px">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:6px">
      <div style="font-size:12px;font-weight:700;color:${palette.strongText || palette.text};flex:1;line-height:1.3">${escHtml(item.title || 'Action requires review')}</div>
      <div style="display:flex;gap:4px;flex-shrink:0">
        <span style="font-size:9px;font-weight:800;padding:2px 6px;border-radius:999px;background:${palette.badge};color:${palette.text};text-transform:uppercase;letter-spacing:0.05em">${escHtml(status)}</span>
        <span style="font-size:9px;font-weight:800;padding:2px 6px;border-radius:999px;background:${palette.badge};color:${palette.text};text-transform:uppercase;letter-spacing:0.05em">risk ${item.riskScore ?? '?'}</span>
      </div>
    </div>
    ${item.summary ? `<div style="font-size:11px;color:${palette.text};margin-bottom:6px;line-height:1.4;opacity:0.9">${escHtml(String(item.summary).slice(0, 180))}</div>` : ''}
    ${pathAccessPaths.length ? `<div style="font-size:10px;color:${palette.text};margin:-2px 0 7px;line-height:1.35"><strong>Path access:</strong><br>${pathAccessPaths.slice(0, 8).map((value) => escHtml(value)).join('<br>')}</div>` : ''}
    ${item.command ? `<pre style="margin:0 0 8px;background:rgba(255,255,255,0.82);border:1px solid ${palette.border};border-radius:8px;padding:8px;font-size:10px;color:${palette.strongText || palette.text};white-space:pre-wrap;word-break:break-word;font-family:'IBM Plex Mono',monospace">${escHtml(String(item.command).slice(0, 300))}</pre>` : ''}
    ${item.scopedTarget ? `<div style="font-size:10px;color:${palette.text};margin:-3px 0 7px;line-height:1.3">Scope: ${escHtml(String(item.scopedTarget).slice(0, 140))}</div>` : ''}
    ${Array.isArray(item.devSourceEdit?.allowedFiles) && item.devSourceEdit.allowedFiles.length ? `<div style="font-size:10px;color:${palette.text};margin:-3px 0 7px;line-height:1.35">Files: ${item.devSourceEdit.allowedFiles.map((file) => escHtml(String(file))).join('<br>')}</div>` : ''}
    ${systems.length ? `<div style="display:flex;flex-wrap:wrap;gap:3px;margin-bottom:7px">${systems.map((s) => `<span style="font-size:9px;background:rgba(255,255,255,0.74);color:${palette.strongText || palette.text};border:1px solid ${palette.border};border-radius:4px;padding:1px 5px;font-family:monospace">${escHtml(s)}</span>`).join('')}</div>` : ''}
    ${isProposal
      ? `<div style="display:flex;gap:6px">
          <button onclick="resolveSessionApproval('${item.id}','approve','${approveEndpoint}')" style="flex:1;border:none;background:#16a34a;color:#fff;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Approve</button>
          <button onclick="resolveSessionApproval('${item.id}','deny','${denyEndpoint}')" style="flex:1;border:1px solid ${palette.border};background:transparent;color:${palette.text};border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Deny</button>
        </div>`
      : isOneShot
        ? `<div style="display:flex;gap:6px">
          <button onclick="resolveSessionApproval('${item.id}','approve','${approveEndpoint}')" style="flex:1;border:none;background:#16a34a;color:#fff;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Approve</button>
          <button onclick="resolveSessionApproval('${item.id}','deny','${denyEndpoint}')" style="flex:1;border:1px solid ${palette.border};background:transparent;color:${palette.text};border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Reject</button>
        </div>`
        : `<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
          <button onclick="resolveSessionApproval('${item.id}','approve','${approveEndpoint}')" style="border:none;background:#16a34a;color:#fff;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Approve Once</button>
          <button onclick="resolveSessionApproval('${item.id}','approve_session','${approveEndpoint}','session')" style="border:none;background:#0f766e;color:#fff;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">This Session</button>
          <button onclick="resolveSessionApproval('${item.id}','approve_always','${approveEndpoint}','always')" style="border:none;background:#2563eb;color:#fff;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">${pathAccessPaths.length ? 'Always allow path' : 'Always Allow'}</button>
          <button onclick="resolveSessionApproval('${item.id}','deny','${denyEndpoint}')" style="border:1px solid ${palette.border};background:transparent;color:${palette.text};border-radius:6px;padding:5px 8px;font-size:11px;font-weight:700;cursor:pointer">Deny</button>
        </div>`}
  </div>`;
}

function normalizeChatApprovalRecord(record = {}, fallback = {}) {
  const id = String(record.id || record.approvalId || fallback.id || fallback.approvalId || '').trim();
  const toolName = String(record.toolName || fallback.toolName || '').trim();
  const approvalKind = String(record.approvalKind || fallback.approvalKind || '').trim();
  const action = String(record.action || fallback.action || fallback.summary || record.summary || '').trim();
  const command = String(record.command || record.toolArgs?.command || fallback.command || '').trim();
  const status = String(record.status || fallback.status || 'pending').trim().toLowerCase();
  const sessionId = String(record.sourceSessionId || record.sessionId || fallback.sourceSessionId || fallback.sessionId || '').trim();
  const isDevSource = approvalKind === 'dev_source_edit' || toolName === 'request_dev_source_edit';
  const isFinalAction = approvalKind === 'final_action' || toolName === 'request_final_action_approval';
  const human = summarizeApprovalForHumans(record, fallback);
  const pathAccess = record.pathAccess || fallback.pathAccess || null;
  return {
    id,
    sessionId,
    toolName,
    approvalKind,
    title: isDevSource ? 'Dev source edit approval' : (isFinalAction ? 'Final action approval' : human.title),
    action,
    command,
    reason: String(record.reason || fallback.reason || record.summary || fallback.summary || '').trim(),
    summary: human.summary || String(record.summary || fallback.summary || action || '').trim(),
    humanDetail: human.detail || '',
    riskScore: Number.isFinite(Number(record.riskScore)) ? Number(record.riskScore) : Number(fallback.riskScore || 0),
    affectedSystems: Array.isArray(record.affectedSystems) ? record.affectedSystems : (Array.isArray(fallback.affectedSystems) ? fallback.affectedSystems : []),
    scopedAction: String(record.scopedAction || fallback.scopedAction || '').trim(),
    scopedTarget: String(record.scopedTarget || fallback.scopedTarget || '').trim(),
    commandBoundary: record.commandBoundary || fallback.commandBoundary || null,
    pathAccess,
    devSourceEdit: record.devSourceEdit || fallback.devSourceEdit || null,
    finalAction: record.finalAction || fallback.finalAction || null,
    oneShot: record.oneShot === true || fallback.oneShot === true || approvalKind === 'elevated_command' || isDevSource || isFinalAction,
    status: status || 'pending',
  };
}

function renderInlineApprovalRequest(item) {
  if (!item || !item.id) return '';
  const approval = normalizeChatApprovalRecord(item);
  const risk = getApprovalRiskLevel(approval.riskScore || 0);
  const systems = Array.isArray(approval.affectedSystems) ? approval.affectedSystems.filter(Boolean) : [];
  const pending = approval.status === 'pending';
  const statusLabel = approval.status === 'approved' ? 'approved' : approval.status === 'rejected' ? 'denied' : approval.status;
  const idArg = encodeInlineJsString(approval.id);
  const approveEndpoint = encodeInlineJsString(`/api/approvals/${approval.id}/approve`);
  const denyEndpoint = encodeInlineJsString(`/api/approvals/${approval.id}/deny`);
  const technicalText = approval.command || approval.scopedAction || approval.action;
  const isDevSource = approval.approvalKind === 'dev_source_edit' || approval.toolName === 'request_dev_source_edit';
  const isFinalAction = approval.approvalKind === 'final_action' || approval.toolName === 'request_final_action_approval';
  const isOneShot = approval.oneShot === true || approval.approvalKind === 'elevated_command' || isDevSource || isFinalAction;
  const isCommandApproval = approval.toolName === 'run_command' && approval.approvalKind !== 'elevated_command';
  const sourceFiles = Array.isArray(approval.devSourceEdit?.allowedFiles) ? approval.devSourceEdit.allowedFiles : [];
  const sourceDirs = Array.isArray(approval.devSourceEdit?.allowedDirs) ? approval.devSourceEdit.allowedDirs : [];
  const verificationCommand = approval.devSourceEdit?.verificationCommand || '';
  const commandBoundary = approval.commandBoundary || null;
  const boundaryScope = String(commandBoundary?.scope || '').trim();
  const boundaryPaths = Array.isArray(commandBoundary?.externalPaths) ? commandBoundary.externalPaths.filter(Boolean) : [];
  const pathAccessPaths = Array.from(new Set([
    approval.pathAccess?.requestedPath,
    ...(Array.isArray(approval.pathAccess?.requestedPaths) ? approval.pathAccess.requestedPaths : []),
  ].map((value) => String(value || '').trim()).filter(Boolean)));
  const boundaryEnv = Array.isArray(commandBoundary?.environmentChanges) ? commandBoundary.environmentChanges.filter(Boolean) : [];
  const devPlan = approval.devSourceEdit?.plan || null;
  const devEvidence = Array.isArray(devPlan?.evidence) ? devPlan.evidence : [];
  const devSteps = Array.isArray(devPlan?.steps) ? devPlan.steps : [];
  const devExpectedWorkflow = Array.isArray(devPlan?.expectedWorkflow)
    ? devPlan.expectedWorkflow
    : (Array.isArray(devPlan?.expected_workflow) ? devPlan.expected_workflow : []);
  const showTechnicalDetails = Boolean(technicalText || approval.reason || systems.length || approval.scopedTarget);
  return `<div class="chat-approval-card chat-approval-card-${risk} chat-approval-card-${escHtml(statusLabel)} ${pending ? 'chat-approval-card-pending' : 'chat-approval-card-resolved'}" data-approval-id="${escHtml(approval.id)}">
    <div class="chat-approval-head">
      <div>
        <div class="chat-approval-kicker">${pending ? 'Approval needed' : 'Approval result'}</div>
        <div class="chat-approval-title">${escHtml(approval.title || 'Approval required')}</div>
      </div>
      <div class="chat-approval-badges">
        <span class="chat-approval-status chat-approval-status-${escHtml(statusLabel)}">${escHtml(statusLabel)}</span>
        ${pending ? `<span class="chat-approval-risk">risk ${escHtml(String(approval.riskScore ?? 0))}</span>` : ''}
      </div>
    </div>
    ${approval.summary ? `<div class="chat-approval-detail">${escHtml(approval.summary)}</div>` : ''}
    ${approval.humanDetail ? `<div class="chat-approval-subdetail">${escHtml(approval.humanDetail)}</div>` : ''}
    ${pending && devPlan?.reasoning ? `<div class="chat-approval-scope"><span>Reasoning</span>${escHtml(String(devPlan.reasoning))}</div>` : ''}
    ${pending && (devPlan?.currentState || devPlan?.fix) ? `<div class="chat-approval-scope"><span>Fix</span>${[
      devPlan.currentState ? `Current: ${String(devPlan.currentState)}` : '',
      devPlan.fix ? `Fix: ${String(devPlan.fix)}` : '',
    ].filter(Boolean).map(escHtml).join('<br>')}</div>` : ''}
    ${pending && devEvidence.length ? `<details class="chat-approval-technical" open>
      <summary>Evidence</summary>
      ${devEvidence.slice(0, 5).map((item) => `<div class="chat-approval-reason"><span>${escHtml(String(item.file || 'file'))}${item.lines ? `:${escHtml(String(item.lines))}` : ''}</span>${escHtml(String(item.finding || ''))}</div>`).join('')}
    </details>` : ''}
    ${pending && devSteps.length ? `<details class="chat-approval-technical">
      <summary>Plan</summary>
      <ol class="chat-approval-plan">${devSteps.slice(0, 8).map((step) => `<li>${escHtml(String(step))}</li>`).join('')}</ol>
    </details>` : ''}
    ${pending && devExpectedWorkflow.length ? `<details class="chat-approval-technical" open>
      <summary>Expected workflow after edits</summary>
      <ol class="chat-approval-plan">${devExpectedWorkflow.slice(0, 8).map((step) => `<li>${escHtml(String(step))}</li>`).join('')}</ol>
    </details>` : ''}
    ${pending && boundaryScope && boundaryScope !== 'workspace' ? `<div class="chat-approval-scope"><span>Boundary</span>${escHtml(boundaryScope.replace(/_/g, ' '))}${commandBoundary?.reason ? `<br>${escHtml(String(commandBoundary.reason))}` : ''}</div>` : ''}
    ${pending && pathAccessPaths.length ? `<div class="chat-approval-scope"><span>Path access requested</span>${pathAccessPaths.slice(0, 8).map((item) => escHtml(String(item))).join('<br>')}</div>` : ''}
    ${pending && boundaryPaths.length ? `<div class="chat-approval-scope"><span>External paths</span>${boundaryPaths.slice(0, 8).map((item) => escHtml(String(item))).join('<br>')}</div>` : ''}
    ${pending && boundaryEnv.length ? `<div class="chat-approval-scope"><span>Environment</span>${boundaryEnv.slice(0, 8).map((item) => escHtml(String(item))).join('<br>')}</div>` : ''}
    ${pending && sourceFiles.length ? `<div class="chat-approval-scope"><span>Files</span>${sourceFiles.map((file) => escHtml(String(file))).join('<br>')}</div>` : ''}
    ${pending && sourceDirs.length ? `<div class="chat-approval-scope"><span>Workspace docs</span>${sourceDirs.map((dir) => escHtml(String(dir))).join('<br>')}</div>` : ''}
    ${pending && verificationCommand ? `<div class="chat-approval-scope"><span>Verify</span>${escHtml(verificationCommand)}</div>` : ''}
    ${pending && showTechnicalDetails ? `<details class="chat-approval-technical">
      <summary>Technical details</summary>
      ${approval.reason ? `<div class="chat-approval-reason"><span>Reason</span>${escHtml(approval.reason)}</div>` : ''}
      ${technicalText ? `<pre class="chat-approval-command">${escHtml(technicalText)}</pre>` : ''}
      ${approval.scopedTarget ? `<div class="chat-approval-scope"><span>Scope</span>${escHtml(approval.scopedTarget)}</div>` : ''}
      ${systems.length ? `<div class="chat-approval-systems">${systems.map((system) => `<span>${escHtml(String(system))}</span>`).join('')}</div>` : ''}
    </details>` : ''}
    ${pending && isCommandApproval ? `<div class="chat-approval-process" data-approval-process="${escHtml(approval.id)}">
      <button class="chat-approval-process-toggle" type="button" onclick="loadApprovalProcessRun(${idArg})">Open terminal</button>
      <div class="chat-approval-process-body" id="approval-process-${escHtml(approval.id)}"></div>
    </div>` : ''}
    ${pending
      ? `<div class="chat-approval-actions">
          <button class="chat-approval-btn chat-approval-approve" type="button" onclick="resolveInlineApproval(${idArg}, 'approve', ${approveEndpoint})">Approve</button>
          <button class="chat-approval-btn chat-approval-deny" type="button" onclick="resolveInlineApproval(${idArg}, 'deny', ${denyEndpoint})">Reject</button>
          ${isOneShot ? '' : `<button class="chat-approval-link" type="button" onclick="resolveInlineApproval(${idArg}, 'approve_session', ${approveEndpoint}, 'session')">Trust this session</button>
          <button class="chat-approval-link" type="button" onclick="resolveInlineApproval(${idArg}, 'approve_always', ${approveEndpoint}, 'always')">Always allow</button>`}
        </div>`
      : `<div class="chat-approval-resolved">This request was ${escHtml(statusLabel)}.</div>`}
  </div>`;
}

function cssEscapeValue(value) {
  const raw = String(value || '');
  if (window.CSS && typeof window.CSS.escape === 'function') return window.CSS.escape(raw);
  return raw.replace(/["\\\]\[]/g, '\\$&');
}

function renderInlinePrometheusQuestion(item) {
  if (!item || !item.id) return '';
  const question = normalizeQuestionRecord(item);
  if (!question.id) return '';
  const pending = question.status === 'pending';
  const idAttr = escHtml(question.id);
  const idArg = encodeInlineJsString(question.id);
  const statusLabel = question.status === 'answered' ? 'answered' : question.status;
  const answerMap = new Map((question.answers || []).map((answer) => [String(answer?.id || ''), answer || {}]));
  const questionBlocks = question.questions.map((q, index) => {
    const answer = answerMap.get(q.id) || {};
    const qName = `${question.id}__${q.id}`;
    const qIdArg = encodeInlineJsString(q.id);
    const selected = Array.isArray(answer.selected) ? answer.selected : [];
    const other = String(answer.other || '').trim();
    const text = String(answer.text || '').trim();
    if (!pending) {
      const selectedText = selected.length ? selected.join(', ') : '';
      const answerText = [selectedText, text, other ? `Other: ${other}` : ''].filter(Boolean).join('\n') || 'No answer';
      return `<div class="chat-approval-scope"><span>${escHtml(q.label)}</span>${escHtml(answerText).replace(/\n/g, '<br>')}</div>`;
    }
    const options = (q.options || []).map((option, optIndex) => {
      const inputId = `${qName}__${optIndex}`;
      const type = q.mode === 'multi_select' ? 'checkbox' : 'radio';
      // For single_select radios, allow re-clicking a checked option to deselect it.
      const deselect = type === 'radio' ? ` onmousedown="toggleQuestionRadio(${encodeInlineJsString(inputId)})"` : '';
      return `<label for="${escHtml(inputId)}" class="pq-option">
        <input id="${escHtml(inputId)}" type="${type}" name="${escHtml(qName)}" value="${escHtml(option)}" data-question-id="${escHtml(q.id)}"${deselect} />
        <span class="pq-option-check" aria-hidden="true"></span>
        <span class="pq-option-label">${escHtml(option)}</span>
      </label>`;
    }).join('');
    const otherInput = q.allowOther && q.mode !== 'text'
      ? `<div class="pq-other-row"><button type="button" class="pq-other-toggle" onclick="toggleQuestionOther(${idArg}, ${qIdArg})"><span class="pq-option-check" aria-hidden="true"></span><span>Other…</span></button></div>`
      : '';
    return `<div class="pq-block" data-question-compose-id="${escHtml(q.id)}" data-question-compose-mode="${escHtml(q.mode)}" data-question-compose-other="${q.allowOther ? 'true' : 'false'}" style="margin-top:${index ? 10 : 0}px">
      <div class="pq-q-label">${escHtml(q.label)}</div>
      ${options ? `<div class="pq-options">${options}</div>` : ''}
      ${otherInput}
    </div>`;
  }).join('');
  return `<div class="chat-approval-card chat-approval-card-low chat-question-card chat-question-card-${escHtml(statusLabel)}" data-question-id="${idAttr}">
    ${questionBlocks}
    ${pending
      ? `<div class="chat-approval-actions">
          <button class="chat-approval-btn chat-approval-deny" type="button" onclick="cancelInlinePrometheusQuestion(${idArg})">Cancel</button>
        </div>`
      : ''}
  </div>`;
}

function toggleQuestionOther(questionId, itemId) {
  const card = document.querySelector(`[data-question-id="${cssEscapeValue(questionId)}"]`);
  const block = card?.querySelector?.(`[data-question-compose-id="${cssEscapeValue(itemId)}"]`);
  if (!card || !block) return;
  card.setAttribute('data-question-compose-target', `${String(itemId)}::other`);
  document.getElementById('chat-input')?.focus?.();
}

// Single_select radios can't be deselected natively. On mousedown, if the radio
// is already checked, cancel the event and uncheck it so the user can clear it.
function toggleQuestionRadio(inputId) {
  try {
    const el = document.getElementById(inputId);
    if (!el || el.type !== 'radio') return;
    if (el.checked) {
      // Defer until after the native click would have re-checked it.
      setTimeout(() => { el.checked = false; el.dispatchEvent(new Event('change', { bubbles: true })); }, 0);
    }
  } catch {}
}

function collectPrometheusQuestionAnswers(question) {
  const card = document.querySelector(`[data-question-id="${cssEscapeValue(question.id)}"]`);
  if (!card) return { answers: [], generalOther: '' };
  const answers = question.questions.map((q) => {
    const checked = Array.from(card.querySelectorAll(`[data-question-id="${cssEscapeValue(q.id)}"]:checked`))
      .map((input) => String(input.value || '').trim())
      .filter(Boolean);
    const text = String(card.querySelector(`[data-question-text="${cssEscapeValue(q.id)}"]`)?.value || '').trim();
    const other = String(card.querySelector(`[data-question-other="${cssEscapeValue(q.id)}"]`)?.value || '').trim();
    return { id: q.id, label: q.label, mode: q.mode, selected: q.mode === 'single_select' ? checked.slice(0, 1) : checked, text, other };
  });
  const generalOther = String(card.querySelector('[data-question-general-other="1"]')?.value || '').trim();
  return { answers, generalOther };
}

function focusPrometheusQuestionComposer() {
  const input = document.getElementById('chat-input');
  if (!input) return;
  try { input.focus({ preventScroll: true }); } catch { try { input.focus(); } catch {} }
}

function upsertInlinePrometheusQuestion(questionInput, options = {}) {
  return desktopQuestionController.upsert(questionInput, options).accepted;
}

function updateInlinePrometheusQuestionStatus(event = {}, status = '') {
  return desktopQuestionController.transition(event, status);
}

async function submitInlinePrometheusQuestion(id, options = {}) {
  const result = await desktopQuestionController.submit(id, {
    ...options,
    readAnswers: (question) => collectPrometheusQuestionAnswers(question),
    getComposerTarget: (question) => {
      const card = document.querySelector(`[data-question-id="${cssEscapeValue(question.id)}"]`);
      return String(card?.getAttribute('data-question-compose-target') || '').trim();
    },
    // Desktop keeps the existing actionable card visible while the request is
    // in flight; the runtime still records the submitting transition.
    projectSubmitting: false,
  });
  if (result.reason === 'missing' || result.reason === 'missing_id') {
    showToast('Question missing', 'Could not load the pending question.', 'error');
    return false;
  }
  return result.ok === true;
}

async function cancelInlinePrometheusQuestion(id) {
  const result = await desktopQuestionController.cancel(id);
  return result.ok === true;
}

async function loadApprovalProcessRun(id, options = {}) {
  const approvalId = String(id || '').trim();
  const body = document.getElementById(`approval-process-${approvalId}`);
  if (!approvalId || !body) return;
  const processWrap = body.closest('.chat-approval-process');
  const toggle = processWrap?.querySelector?.('.chat-approval-process-toggle');
  const forceOpen = options?.forceOpen === true || Number(options?.attempts || 1) > 1;
  if (!forceOpen && body.dataset.terminalOpen === '1') {
    body.innerHTML = '';
    body.dataset.terminalOpen = '0';
    if (toggle) toggle.textContent = 'Open terminal';
    return;
  }
  body.dataset.terminalOpen = '1';
  if (toggle) toggle.textContent = 'Close terminal';
  const attempts = Math.max(1, Math.min(8, Number(options?.attempts || 1)));
  const delayMs = Math.max(150, Math.min(2500, Number(options?.delayMs || 500)));
  body.innerHTML = '<div class="chat-approval-subdetail">Loading command run...</div>';
  try {
    let run = null;
    for (let attempt = 0; attempt < attempts; attempt += 1) {
      const data = await api('/api/processes?limit=100');
      const runs = Array.isArray(data?.runs) ? data.runs : [];
      run = runs.find((item) => String(item?.approvalId || '') === approvalId);
      if (run) break;
      if (attempt < attempts - 1) await new Promise((resolve) => setTimeout(resolve, delayMs));
    }
    const processRunCards = run ? await loadProcessRunCards() : null;
    if (processRunCards) processRunCards.installProcessRunCardHandlers(document);
    body.innerHTML = run
      ? processRunCards.renderProcessRunCard(run)
      : '<div class="chat-approval-subdetail">No linked command run yet. It will appear here after execution starts.</div>';
  } catch (err) {
    body.innerHTML = `<div class="chat-approval-subdetail">Could not load command run: ${escHtml(err?.message || err)}</div>`;
  }
}

async function fetchApprovalDetailsById(id) {
  const approvalId = String(id || '').trim();
  if (!approvalId) return null;
  try {
    const data = await api('/api/approvals?status=all');
    const approval = (data.approvals || []).find((item) => String(item.id || '') === approvalId);
    return approval || null;
  } catch (err) {
    console.warn('[ChatPage] could not fetch approval details:', err);
    return null;
  }
}

function upsertInlineApprovalMessage(approvalInput, options = {}) {
  const approval = normalizeChatApprovalRecord(approvalInput);
  if (!approval.id) return false;
  const sessionId = approval.sessionId || String(window.activeChatSessionId || '').trim();
  if (!sessionId) return false;
  const sess = getChatSessionById(sessionId);
  if (!sess) return false;
  if (!Array.isArray(sess.history)) sess.history = [];
  const existing = sess.history.find((msg) => String(msg?.approvalRequest?.id || '') === approval.id);
  if (existing) {
    existing.approvalRequest = { ...(existing.approvalRequest || {}), ...approval };
    existing.timestamp = Number(existing.timestamp) || Date.now();
  } else if (options.create !== false) {
    sess.history.push({
      role: 'assistant',
      content: '',
      approvalRequest: approval,
      timestamp: Date.now(),
    });
  }
  if (window.activeChatSessionId === sessionId) {
    window.chatHistory = sess.history;
    renderChatMessages();
  } else {
    sess.unread = true;
  }
  persistSession(sessionId);
  return true;
}

function approvalFromEventPayload(event = {}, status = '') {
  const id = String(event.approvalId || event.id || event.approval?.id || '').trim();
  const base = event.approval && typeof event.approval === 'object' ? event.approval : {};
  const approval = normalizeChatApprovalRecord(base, {
    ...event,
    id,
    status: status || base.status || event.status || 'pending',
  });
  if (!approval.sessionId) approval.sessionId = String(event.sessionId || window.activeChatSessionId || '').trim();
  if (status) approval.status = status;
  return approval;
}

function upsertStreamingApproval(sessionId, approvalInput) {
  const approval = normalizeChatApprovalRecord(approvalInput);
  if (!sessionId || !approval.id) return false;
  const st = getSessionStreamState(sessionId);
  if (!st) return false;
  const list = Array.isArray(st.pendingApprovals) ? st.pendingApprovals : [];
  const idx = list.findIndex((item) => String(item?.id || '') === approval.id);
  if (idx >= 0) list[idx] = { ...list[idx], ...approval };
  else list.push(approval);
  st.pendingApprovals = list.slice(-6);
  try { desktopChatRuntime(sessionId)?.upsertApproval(approval); } catch {}
  if (window.activeChatSessionId === sessionId) {
    applyStreamStateToWindow(sessionId);
    renderChatMessages();
  }
  return true;
}

function updateStreamingApprovalStatus(sessionId, id, status = '', event = {}) {
  if (!id) return false;
  const st = getSessionStreamState(sessionId);
  if (!st || !Array.isArray(st.pendingApprovals)) return false;
  const idx = st.pendingApprovals.findIndex((item) => String(item?.id || '') === id);
  if (idx < 0) return false;
  st.pendingApprovals[idx] = normalizeChatApprovalRecord(st.pendingApprovals[idx], {
    ...event,
    id,
    status: status || st.pendingApprovals[idx].status || 'pending',
  });
  st.pendingApprovals[idx].status = status || st.pendingApprovals[idx].status || 'pending';
  try { desktopChatRuntime(sessionId)?.resolveApproval(id, st.pendingApprovals[idx].status, st.pendingApprovals[idx]); } catch {}
  if (window.activeChatSessionId === sessionId) {
    applyStreamStateToWindow(sessionId);
    renderChatMessages();
  }
  return true;
}

function renderStreamingApprovals(items = []) {
  const visible = (Array.isArray(items) ? items : []).filter((item) => item && item.id);
  if (!visible.length) return '';
  return `<div class="chat-live-approvals">${visible.map((item) => renderInlineApprovalRequest(item)).join('')}</div>`;
}

async function showInlineApprovalFromEvent(event = {}) {
  const id = String(event.approvalId || event.id || '').trim();
  const details = event.approval ? null : (id ? await fetchApprovalDetailsById(id) : null);
  const approval = event.approval
    ? approvalFromEventPayload(event, 'pending')
    : normalizeChatApprovalRecord(details || {}, {
      ...event,
      id,
      status: 'pending',
    });
  if (!approval.sessionId) approval.sessionId = String(event.sessionId || window.activeChatSessionId || '').trim();
  if (isSessionThinking(approval.sessionId)) {
    upsertStreamingApproval(approval.sessionId, approval);
    return;
  }
  upsertInlineApprovalMessage(approval);
}

function updateInlineApprovalStatusFromEvent(event = {}, status = '') {
  const id = String(event.approvalId || event.id || event.approval?.id || '').trim();
  if (!id) return;
  const sessionId = String(event.sessionId || event.approval?.sessionId || event.approval?.sourceSessionId || window.activeChatSessionId || '').trim();
  updateStreamingApprovalStatus(sessionId, id, status, event.approval || event);
  const targetSessions = sessionId ? [getChatSessionById(sessionId)].filter(Boolean) : (window.chatSessions || []);
  targetSessions.forEach((sess) => {
    const msg = (sess.history || []).find((entry) => String(entry?.approvalRequest?.id || '') === id);
    if (!msg) return;
    msg.approvalRequest = normalizeChatApprovalRecord(msg.approvalRequest, {
      ...event,
      id,
      status,
      summary: event.summary,
    });
    msg.approvalRequest.status = status || msg.approvalRequest.status || 'pending';
    persistSession(sess.id);
  });
}

async function resolveInlineApproval(id, action, endpoint, grantScope = '') {
  const result = await resolveSessionApproval(id, action, endpoint, grantScope);
  if (result?.ok) {
    const approved = action !== 'deny';
    updateInlineApprovalStatusFromEvent({ approvalId: id, sessionId: window.activeChatSessionId }, approved ? 'approved' : 'rejected');
    if (approved) setTimeout(() => loadApprovalProcessRun(id, { attempts: 6, delayMs: 500, forceOpen: true }), 100);
  }
}

async function restorePendingInlineApprovalsForSession(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  try {
    const data = await api('/api/approvals?status=pending');
    const approvals = (Array.isArray(data?.approvals) ? data.approvals : [])
      .filter((approval) => String(approval.sourceSessionId || approval.sessionId || '').trim() === sid);
    for (const approval of approvals) {
      upsertInlineApprovalMessage(approval, { create: true });
    }
  } catch (err) {
    console.warn('[ChatPage] could not restore pending approvals:', err);
  }
}

async function restorePendingInlineQuestionsForSession(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  try {
    const data = await api(`/api/questions?status=pending&sessionId=${encodeURIComponent(sid)}`);
    const questions = Array.isArray(data?.questions) ? data.questions : [];
    for (const question of questions) {
      upsertInlinePrometheusQuestion(question, { create: true });
    }
  } catch (err) {
    console.warn('[ChatPage] could not restore pending questions:', err);
  }
}

async function loadSessionApprovals() {
  const list = document.getElementById('session-approvals-list');
  const badge = document.getElementById('session-approvals-badge');
  const section = document.getElementById('session-approvals-section');
  if (!list || !badge) return;
  if (section) section.style.display = 'none';
  const currentSessionId = String(window.activeChatSessionId || '').trim();
  try {
    const [approvalData, proposalData, questionData] = await Promise.all([
      api('/api/approvals?status=pending').catch(() => ({ approvals: [] })),
      api(`/api/proposals?status=pending&sessionId=${encodeURIComponent(currentSessionId)}`).catch(() => ({ proposals: [] })),
      api(`/api/questions?status=pending&sessionId=${encodeURIComponent(currentSessionId)}`).catch(() => ({ questions: [] })),
    ]);
    const approvalItems = (approvalData.approvals || [])
      .filter((a) => String(a.sourceSessionId || a.sessionId || '').trim() === currentSessionId)
      .map((a) => ({
        id: a.id,
        title: a.approvalKind === 'dev_source_edit' || a.toolName === 'request_dev_source_edit' ? 'Dev source edit approval' : (a.approvalKind === 'final_action' || a.toolName === 'request_final_action_approval' ? 'Final action approval' : (a.toolName === 'run_command' ? 'Command approval' : 'Tool approval')),
        summary: a.reason || a.summary || '',
        riskScore: a.riskScore ?? 0,
        affectedSystems: a.affectedSystems || [],
        command: a.command || a.scopedAction || '',
        scopedTarget: a.scopedTarget || '',
        commandBoundary: a.commandBoundary || null,
        pathAccess: a.pathAccess || null,
        oneShot: a.oneShot === true,
        status: a.status || 'pending',
        toolName: a.toolName || '',
        approvalKind: a.approvalKind || '',
        devSourceEdit: a.devSourceEdit || null,
        finalAction: a.finalAction || null,
        approvalType: 'command',
      }));
    const proposalItems = (proposalData.proposals || [])
      .filter((p) => String(p.sourceSessionId || p.sessionId || '').trim() === currentSessionId)
      .map((p) => ({
      id: p.id,
      title: p.title,
      summary: p.summary,
      riskScore: p.priority === 'critical' ? 10 : p.priority === 'high' ? 7 : p.priority === 'medium' ? 4 : 2,
      affectedSystems: (p.affectedFiles || []).map((f) => f.path?.split(/[\\/]/).pop() || f.path || '').filter(Boolean),
      status: p.status || 'pending',
      approvalType: 'proposal',
    }));
    const questionItems = (questionData.questions || [])
      .filter((q) => String(q.sourceSessionId || q.sessionId || '').trim() === currentSessionId)
      .map((q) => ({ ...normalizeQuestionRecord(q), approvalType: 'question' }));
    const all = [...questionItems, ...approvalItems, ...proposalItems];
    const runtime = desktopChatRuntime(currentSessionId);
    approvalItems.forEach((item) => { try { runtime?.upsertApproval(item); } catch {} });
    questionItems.forEach((item) => {
      try { desktopQuestionController.upsert(item, { projectLegacy: false }); } catch {}
    });
    const inlineStreamOwnsApprovals = Boolean(
      currentSessionId
      && window._sessionThinking?.[currentSessionId]
      && approvalItems.length
    );
    if (inlineStreamOwnsApprovals) {
      if (section) section.style.display = 'none';
      list.innerHTML = '';
      badge.style.display = 'inline-block';
      badge.textContent = String(all.length);
      return;
    }
    if (!all.length) {
      list.innerHTML = '<div style="font-size:11px;color:var(--muted);text-align:center;padding:12px 0;opacity:0.6">No pending actions</div>';
      badge.style.display = 'none';
      return;
    }
    list.innerHTML = all.map((item) => item.approvalType === 'question' ? renderInlinePrometheusQuestion(item) : renderSessionApprovalCard(item)).join('');
    badge.style.display = 'inline-block';
    badge.textContent = String(all.length);
  } catch (err) {
    list.innerHTML = `<div style="font-size:11px;color:var(--err);padding:8px 0">${escHtml(err.message || 'Load failed')}</div>`;
  }
}

async function resolveSessionApproval(id, action, endpoint, grantScope = '') {
  try {
    const method = 'POST';
    const body = JSON.stringify(grantScope ? { grantScope } : {});
    const result = await api(endpoint, { method, body });
    await loadSessionApprovals();
    if (window.currentMode === 'proposals' && typeof window.loadProposals === 'function') window.loadProposals();
    if (window.currentMode === 'approvals' && typeof window.loadApprovals === 'function') window.loadApprovals();
    if (typeof window.checkPendingProposalsBadge === 'function') window.checkPendingProposalsBadge();
    const label = action === 'deny' ? 'Denied' : grantScope === 'always' ? 'Always allowed' : grantScope === 'session' ? 'Allowed this session' : 'Approved';
    addProcessEntry('info', `${label}: ${id}`);
    const resumePrompt = String(result?.resumePrompt || '').trim();
    if (resumePrompt && action !== 'deny') {
      const approvalSessionId = String(result?.approval?.sessionId || result?.approval?.sourceSessionId || window.activeChatSessionId || '').trim();
      if (approvalSessionId && approvalSessionId !== window.activeChatSessionId) {
        window.activeChatSessionId = approvalSessionId;
        setAgentSessionId(approvalSessionId);
        syncActiveChat();
      }
      setTimeout(() => {
        try {
          sendChat(resumePrompt, { clientRequestId: newChatClientRequestId(approvalSessionId || window.activeChatSessionId) });
        } catch (err) {
          showToast('Approval resume failed', String(err?.message || err), 'error');
        }
      }, 100);
    }
    return { ok: true, data: result, resumePrompt };
  } catch (err) {
    showToast('Error', err.message || 'Could not resolve action', 'error');
    return { ok: false, error: err };
  }
}

if (typeof window.loadSessionApprovals !== 'function') window.loadSessionApprovals = loadSessionApprovals;
if (typeof window.resolveSessionApproval !== 'function') window.resolveSessionApproval = resolveSessionApproval;
if (typeof window.resolveInlineApproval !== 'function') window.resolveInlineApproval = resolveInlineApproval;
if (typeof window.submitInlinePrometheusQuestion !== 'function') window.submitInlinePrometheusQuestion = submitInlinePrometheusQuestion;
if (typeof window.cancelInlinePrometheusQuestion !== 'function') window.cancelInlinePrometheusQuestion = cancelInlinePrometheusQuestion;
if (typeof window.toggleQuestionOther !== 'function') window.toggleQuestionOther = toggleQuestionOther;
if (typeof window.toggleQuestionRadio !== 'function') window.toggleQuestionRadio = toggleQuestionRadio;
if (typeof window.loadApprovalProcessRun !== 'function') window.loadApprovalProcessRun = loadApprovalProcessRun;
// ─── Expose on window for HTML onclick handlers ────────────────
window.generateSessionId = generateSessionId;
window.setAgentSessionId = setAgentSessionId;
window.isCreativeModeLocked = isCreativeModeLocked;
window.isCanvasWidthLocked = isCanvasWidthLocked;
window.getCanvasWidthLockMessage = getCanvasWidthLockMessage;
window.getCanvasPanelMaximumWidth = getCanvasPanelMaximumWidth;
window.setCanvasPreviewDevice = setCanvasPreviewDevice;
window.setCreativeModeFromUI = setCreativeModeFromUI;
window.exitCreativeModeFromUI = exitCreativeModeFromUI;
window.applySessionCreativeMode = applySessionCreativeMode;
window.showToast = showToast;
window.bgtToast = bgtToast;
window.showConfirm = showConfirm;
window.restoreWorkspaceCheckpointFromDiff = restoreWorkspaceCheckpointFromDiff;
window.renderQueuedPromptsPanel = renderQueuedPromptsPanel;
window.toggleDesktopNewChatContextPopover = toggleDesktopNewChatContextPopover;
window.closeDesktopNewChatContextPopover = closeDesktopNewChatContextPopover;
window.removeQueuedPrompt = removeQueuedPrompt;
window.steerQueuedPrompt = steerQueuedPrompt;
window.clearQueuedPrompts = clearQueuedPrompts;
window.editQueuedPrompt = editQueuedPrompt;
window.updateQueuedPromptUI = updateQueuedPromptUI;
