wsEventBus.on('boot_greeting', (msg) => {
  if (msg?.automatedSession && typeof window.upsertAutomatedSession === 'function') {
    window.upsertAutomatedSession(msg.automatedSession, { markUnread: true });
    showToast('Startup update available in a new chat');
    return;
  }
  // Backward-compatible fallback for older payloads without automatedSession.
  if (msg?.sessionId && msg?.text && typeof window.upsertAutomatedSession === 'function') {
    window.upsertAutomatedSession({
      id: msg.sessionId,
      title: msg.title || '🌅 Startup',
      history: [{ role: 'assistant', content: msg.text }],
      createdAt: Date.now(),
      automated: true,
    }, { markUnread: true });
    showToast('Startup update available in a new chat');
    return;
  }

  const bootSess = (window.chatSessions || []).find(s => s.id === window.activeChatSessionId);
  if (bootSess && (!bootSess.history || bootSess.history.length === 0)) {
    bootSess.history = [{ role: 'assistant', content: msg.text }];
    bootSess.updatedAt = Date.now();
    saveChatSessions();
    syncActiveChat();
    renderChatMessages();
  }
});

wsEventBus.on('brain_thought_done', () => {
  refreshEmptyChatBrainCards();
});

// Manual and automatic settling both change visibility only. Keep the local
// sidebar projection in sync without navigating away from an open chat.
wsEventBus.on('session_state_changed', (msg = {}) => {
  const session = msg?.session;
  if (!session?.id) return;
  mergeServerSessionSummaries([session]);
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
});

wsEventBus.on('auto_settle_run', (summary = {}) => {
  if (summary?.dryRun === true || summary?.reason !== 'scheduled') return;
  const settled = Number(summary?.settled || 0);
  if (settled <= 0 || typeof showToast !== 'function') return;
  showToast('Chats auto-settled', `${settled} untouched chat${settled === 1 ? '' : 's'} moved to Settled Chats. You can reopen them there.`, 'info', 6500);
});

wsEventBus.on('main_chat_goal_updated', async (msg) => {
  const sid = String(msg?.sessionId || '').trim();
  if (!sid) return;
  const event = String(msg?.event || '');
  let sess = window.chatSessions.find(s => s.id === sid);
  if (!sess) {
    sess = createEmptyChatSession(sid);
    window.chatSessions.unshift(sess);
  }
  sess.mainChatGoal = msg.goal || null;
  sess.updatedAt = Date.now();
  if (sid === window.activeChatSessionId) {
    if (['runner_started', 'launch_accepted', 'turn_preparing', 'turn_started'].includes(event)) {
      window._sessionThinking[sid] = true;
      getSessionStreamState(sid).turnStartedAt = Date.now();
      syncActiveSessionRunState();
      if (typeof window.setButtonState === 'function') window.setButtonState(true);
      syncAssistantWorkTimer();
    }
    renderMainGoalStrip();
    if (['runner_stopped', 'runner_idle', 'runtime_failure', 'action:pause', 'action:clear', 'action:done'].includes(event)) {
      delete window._sessionThinking[sid];
      if (window._sessionAbortControllers) delete window._sessionAbortControllers[sid];
      syncActiveSessionRunState();
      if (typeof window.setButtonState === 'function') window.setButtonState(false);
      syncAssistantWorkTimer();
    }
    if (['judged', 'summarized', 'runner_idle', 'runner_stopped', 'runtime_failure'].includes(event)) {
      sess._needsServerLoad = true;
      await _loadSessionFromServer(sid);
      syncActiveChat();
    }
  } else {
    const becameUnread = !sess.unread;
    sess.unread = true;
    if (becameUnread) window.scheduleSessionListRefresh?.();
  }
  saveChatSessions();
});

wsEventBus.on('session_notification', async (msg) => {
  if (!msg) return;
  const appendToPreviousSession = async () => {
    const prevId = String(msg.previousSessionId || '').trim();
    const text = String(msg.text || '');
    if (!prevId || !text) return null;
    window.chatSessions = Array.isArray(window.chatSessions) ? window.chatSessions : [];
    let prev = window.chatSessions.find((s) => s.id === prevId);
    if (!prev) {
      prev = {
        id: prevId,
        title: msg.title || 'Restarted chat',
        history: [],
        processLog: [],
        createdAt: Date.now(),
        updatedAt: Date.now(),
        automated: false,
        source: String(msg.source || 'hot_restart'),
        unread: true,
      };
      window.chatSessions.unshift(prev);
    }
    if (['hot_restart', 'dev_apply'].includes(String(msg.source || ''))) {
      clearLiveTurnStateForSession(prevId);
      prev._needsServerLoad = true;
      await _loadSessionFromServer(prevId, { force: true });
      prev = window.chatSessions.find((s) => s.id === prevId) || prev;
      prev.history = reconcileChatHistoryAfterMerge(prev.history || []);
      clearLiveTurnStateForSession(prevId);
      await restorePendingInlineApprovalsForSession(prevId);
      await restorePendingInlineQuestionsForSession(prevId);
      prev = window.chatSessions.find((s) => s.id === prevId) || prev;
    }
    prev.history = Array.isArray(prev.history) ? prev.history : [];
    const packet = buildRestartProcessPacketMessage(prev);
    if (packet) {
      prev.history.push(packet);
    }
    const last = prev.history.length > 0 ? prev.history[prev.history.length - 1] : null;
    const alreadyHasText = prev.history.some((entry) => (
      String(entry?.role || '') === 'assistant'
      && String(entry?.content || '') === text
    ));
    if (!alreadyHasText && (!last || String(last.role || '') !== 'assistant' || String(last.content || '') !== text)) {
      prev.history.push({ role: 'assistant', content: text });
    }
    prev.updatedAt = Date.now();
    prev.unread = true;
    saveChatSessions();
    if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
    if (window.activeChatSessionId === prevId) renderChatMessages();
    return prev;
  };
  const ack = () => {
    if (msg.notificationId) {
      wsSend({ type: 'startup_notification_ack', notificationId: String(msg.notificationId), surface: 'web', sessionId: String(msg.previousSessionId || msg.sessionId || '') });
    }
  };
  if (String(msg.source || '') === 'hot_restart') {
    const targetSessionId = String(msg.previousSessionId || msg.sessionId || '').trim();
    if (targetSessionId.startsWith('mobile_') || targetSessionId === 'mobile_default') return;
    const restored = await appendToPreviousSession();
    if (restored?.id) {
      const activeBeforeRestartNotice = String(window.activeChatSessionId || '').trim();
      const viewingRecoveredThread = activeBeforeRestartNotice === restored.id;
      restored.unread = !viewingRecoveredThread;
      saveChatSessions();
      if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
      if (viewingRecoveredThread) {
        setAgentSessionId(restored.id);
        syncActiveChat();
        renderChatMessages();
      }
    }
    const restartText = String(msg.text || '').trim();
    const notificationKey = String(msg.notificationId || `${restored?.id || msg.previousSessionId || ''}:${restartText.length}:${restartText.slice(0, 120)}`);
    if (restartText && notificationKey !== voiceAgentRealtimeLastHotRestartSummaryKey) {
      requestVoiceAgentRealtimeFinalSummaryWithRetry(restartText, {
        key: notificationKey,
        sessionId: restored?.id || msg.previousSessionId || msg.sessionId,
      });
    }
    ack();
    return;
  }
  if (String(msg.source || '') === 'dev_apply') {
    const restored = await appendToPreviousSession();
    if (restored?.id) {
      const viewingAppliedThread = String(window.activeChatSessionId || '').trim() === restored.id;
      restored.unread = !viewingAppliedThread;
      saveChatSessions();
      if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
      if (viewingAppliedThread) renderChatMessages();
    }
    bgtToast('Coordinated dev changes applied', String(msg.text || 'The shared web UI is live.').slice(0, 180));
    ack();
    return;
  }
  if (msg.automatedSession && typeof window.upsertAutomatedSession === 'function') {
    window.upsertAutomatedSession(msg.automatedSession, { markUnread: true });
    await appendToPreviousSession();
    const title = msg.automatedSession.title || msg.title || 'Automated session';
    bgtToast('💬 New automated session', String(title).slice(0, 100));
    ack();
    return;
  }

  // Backward-compatible fallback for additive session_notification payload.
  if (msg.sessionId && msg.text && typeof window.upsertAutomatedSession === 'function') {
    window.upsertAutomatedSession({
      id: msg.sessionId,
      title: msg.title || 'Automated session',
      history: [{ role: 'assistant', content: msg.text }],
      createdAt: Date.now(),
      automated: true,
      source: String(msg.source || ''),
    }, { markUnread: true });
    await appendToPreviousSession();
    ack();
  }
});

wsEventBus.on('delivery_notification', (msg) => {
  if (!msg) return;
  const sid = String(msg.sessionId || window.activeChatSessionId || '').trim();
  const text = String(msg.text || msg.caption || '').trim();
  const imageDataUrl = String(msg.imageDataUrl || '').trim();
  const attachmentPath = String(msg.attachmentPath || '').trim();
  const fileName = String(msg.fileName || '').trim();
  const parts = [];
  if (text) parts.push(text);
  if (imageDataUrl) parts.push(`![${escHtml(String(msg.caption || 'Delivered image'))}](${imageDataUrl})`);
  else if (attachmentPath) parts.push(`Delivered file: ${fileName || attachmentPath}`);
  const content = parts.join('\n\n').trim();
  if (!content) return;
  let sess = (window.chatSessions || []).find((s) => s.id === sid);
  if (!sess) {
    sess = {
      id: sid || `delivery_${Date.now()}`,
      title: 'Delivered update',
      history: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      source: String(msg.target || 'delivery'),
      automated: true,
    };
    window.chatSessions = window.chatSessions || [];
    window.chatSessions.unshift(sess);
  }
  sess.history = Array.isArray(sess.history) ? sess.history : [];
  sess.history.push({
    role: 'assistant',
    content,
    timestamp: Number(msg.timestamp || Date.now()),
    channel: String(msg.target || 'web'),
    channelLabel: 'delivery',
  });
  sess.updatedAt = Date.now();
  if (sess.id !== window.activeChatSessionId) sess.unread = true;
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (sess.id === window.activeChatSessionId) renderChatMessages();
  if (typeof bgtToast === 'function') bgtToast('Delivered update', text || fileName || 'Screenshot delivered');
});

wsEventBus.on('vision_injected', (msg) => {
  if (!msg) return;
  const tool = String(msg.tool || '').trim();
  const sid = String(msg.sessionId || window.activeChatSessionId || '').trim();
  const preview = msg.preview && typeof msg.preview === 'object' ? msg.preview : {};
  const dataUrl = String(preview.dataUrl || msg.dataUrl || '').trim();
  if (!isRenderableLiveTraceImageSource(dataUrl)) return;
  const sourceValue = String(msg.source || '').toLowerCase();
  const source = sourceValue === 'browser' ? 'Browser' : sourceValue === 'media_analysis' ? 'Media analysis' : sourceValue === 'generated_image' ? 'Generated image' : 'Desktop';
  if (!/^voice_(?:browser|desktop)_screenshot$/i.test(tool)) {
    const streamState = getSessionStreamState(sid);
    const toolLabel = tool ? formatToolCallForLog(tool, {}, streamState).replace(/\.\.\.$/, '') : `${source} observation`;
    const text = String(msg.label || `Vision injected: ${toolLabel}`).trim();
    if (sourceValue === 'generated_image' && Array.isArray(streamState.liveTraceEntries)) {
      const incomingPreviewId = String(preview.previewId || '').trim();
      const incomingGenerationId = String(preview.generationId || '').trim();
      const incomingWorkspacePath = String(preview.workspacePath || '').trim();
      const incomingCacheKey = String(preview.cacheKey || '').trim();
      const priorIndex = streamState.liveTraceEntries.findIndex((entry) =>
        entry?.type === 'vision'
        && String(entry?.preview?.artifactKind || '') === 'generated_image_partial'
        && (
          (!!incomingPreviewId && String(entry?.preview?.previewId || '') === incomingPreviewId)
          || (!!incomingGenerationId && String(entry?.preview?.generationId || '') === incomingGenerationId)
          || (!incomingPreviewId && !incomingGenerationId && !!incomingWorkspacePath && String(entry?.preview?.workspacePath || '') === incomingWorkspacePath)
          || (!incomingPreviewId && !incomingGenerationId && !!incomingCacheKey && String(entry?.preview?.cacheKey || '') === incomingCacheKey)
        )
      );
      if (priorIndex >= 0) streamState.liveTraceEntries.splice(priorIndex, 1);
    }
    const last = Array.isArray(streamState.liveTraceEntries)
      ? streamState.liveTraceEntries[streamState.liveTraceEntries.length - 1]
      : null;
    const samePreview = last
      && last.type === 'vision'
      && String(last.text || '') === text
      && String(last?.preview?.dataUrl || '') === dataUrl;
    if (!samePreview) {
      appendLiveTraceToStreamState(streamState, 'vision', text);
      const added = streamState.liveTraceEntries[streamState.liveTraceEntries.length - 1];
      if (added) {
        added.preview = preview;
        added.previewTitle = String(msg.previewTitle || preview.title || `${source} preview`);
      }
    }
    if (sid === window.activeChatSessionId) {
      applyStreamStateToWindow(sid);
      renderChatMessages();
    }
    return;
  }
  const dimensions = preview.width && preview.height ? ` ${preview.width}x${preview.height}` : '';
  const content = `![${source} screenshot${dimensions}](${dataUrl})`;
  let sess = (window.chatSessions || []).find((s) => s.id === sid);
  if (!sess) {
    sess = {
      id: sid || `vision_${Date.now()}`,
      title: `${source} screenshot`,
      history: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      source: 'voice',
      automated: true,
    };
    window.chatSessions = window.chatSessions || [];
    window.chatSessions.unshift(sess);
  }
  sess.history = Array.isArray(sess.history) ? sess.history : [];
  sess.history.push({
    role: 'assistant',
    content,
    timestamp: Number(msg.timestamp || Date.now()),
    channel: 'voice',
    channelLabel: 'voice preview',
  });
  sess.updatedAt = Date.now();
  if (sess.id !== window.activeChatSessionId) sess.unread = true;
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  if (sess.id === window.activeChatSessionId) renderChatMessages();
});

function appendTelegramMessageToSession(sessionId, message) {
  const sid = String(sessionId || '').trim();
  if (!sid || !message || !message.role) return;
  const idx = (window.chatSessions || []).findIndex((s) => s.id === sid);
  if (idx < 0) return;
  const sess = window.chatSessions[idx];
  sess.history = Array.isArray(sess.history) ? sess.history : [];
  const next = {
    role: message.role === 'ai' ? 'assistant' : (message.role === 'assistant' ? 'assistant' : 'user'),
    content: String(message.content || ''),
    timestamp: Number(message.timestamp) || Date.now(),
    channel: 'telegram',
    channelLabel: 'telegram',
  };
  if (isSessionTitleCommandMessage(next)) return;
  const last = sess.history.length > 0 ? sess.history[sess.history.length - 1] : null;
  if (
    last
    && String(last.role || '') === String(next.role || '')
    && String(last.content || '') === String(next.content || '')
  ) {
    if (next.role === 'assistant') {
      delete window._sessionThinking[sid];
      sess.activeRun = false;
      sess.unread = true;
      window._sessionStreamState[sid] = makeEmptyStreamState();
      if (sid === window.activeChatSessionId) {
        syncActiveSessionRunState();
        applyStreamStateToWindow(sid);
        renderChatMessages();
      }
    }
    return;
  }
  sess.history.push(next);
  sess.updatedAt = Date.now();
  applyAutoSessionTitleOnce(sess, sess.history);
  if (next.role === 'assistant') {
    delete window._sessionThinking[sid];
    sess.activeRun = false;
    sess.unread = true;
    window._sessionStreamState[sid] = makeEmptyStreamState();
  }
  if (sid !== window.activeChatSessionId) sess.unread = true;
  if (sid === window.activeChatSessionId) {
    syncActiveSessionRunState();
    applyStreamStateToWindow(sid);
    renderChatMessages();
  }
}

function inferChannelFromSessionId(sessionId, fallback = '') {
  const sid = String(sessionId || '');
  const fb = String(fallback || '').trim().toLowerCase();
  if (fb) return fb;
  if (sid.startsWith('telegram_')) return 'telegram';
  if (sid.startsWith('mobile_')) return 'mobile';
  if (sid.startsWith('discord_')) return 'discord';
  if (sid.startsWith('whatsapp_')) return 'whatsapp';
  if (sid.startsWith('cli_')) return 'terminal';
  if (/^(task_|cron_|brain_|auto_)/i.test(sid)) return 'system';
  return 'web';
}

function ensureChannelChatSession(sessionId, options = {}) {
  const sid = String(sessionId || '').trim();
  if (!sid || isInternalChatSession({ id: sid })) return null;
  let sess = getChatSessionById(sid);
  const channel = inferChannelFromSessionId(sid, options.channel || options.source);
  if (!sess) {
    sess = {
      ...createEmptyChatSession(sid),
      title: options.title || (channel === 'web' ? 'New chat' : `${channel[0].toUpperCase()}${channel.slice(1)} chat`),
      source: channel !== 'web' ? channel : undefined,
      automated: channel !== 'web',
      unread: sid !== window.activeChatSessionId,
    };
    window.chatSessions = window.chatSessions || [];
    window.chatSessions.unshift(sess);
  }
  sess.history = Array.isArray(sess.history) ? sess.history : [];
  sess.processLog = Array.isArray(sess.processLog) ? sess.processLog : [];
  if (channel !== 'web') {
    sess.source = sess.source || channel;
    sess.automated = true;
  }
  return sess;
}

function inferCurrentTurnProcessStartIndex(sess, userContent = '') {
  const log = Array.isArray(sess?.processLog) ? sess.processLog : [];
  if (!log.length) return 0;
  const direct = String(userContent || '').replace(/\s+/g, ' ').trim();
  let fallbackUserText = direct;
  if (!fallbackUserText) {
    for (let i = (Array.isArray(sess?.history) ? sess.history.length : 0) - 1; i >= 0; i -= 1) {
      const msg = sess.history[i];
      if (String(msg?.role || '') === 'user') {
        fallbackUserText = String(msg?.content || '').replace(/\s+/g, ' ').trim();
        break;
      }
    }
  }
  if (fallbackUserText) {
    for (let i = log.length - 1; i >= 0; i -= 1) {
      const entry = log[i] || {};
      const entryText = String(entry.content || entry.text || '').replace(/\s+/g, ' ').trim();
      const entryType = String(entry.type || '').toLowerCase();
      if (entryType === 'user' && entryText === fallbackUserText) return i + 1;
    }
  }
  return 0;
}

function appendLiveTraceToStreamState(streamState, type, text, { append = false, extra = null } = {}) {
  const content = String(text || '');
  if (!content) return;
  if (isBareThinkingLiveTraceText(content)) return;
  if (!Array.isArray(streamState.liveTraceEntries)) streamState.liveTraceEntries = [];
  const normalizedType = String(type || 'info').toLowerCase();
  const isThoughtLike = isDesktopTraceThoughtType(normalizedType);
  const isUserVisibleThought = isThoughtLike && isDesktopUserVisibleReasoningTraceEntry({ type: normalizedType, extra });
  const last = streamState.liveTraceEntries[streamState.liveTraceEntries.length - 1];
  if (append && last && last.type === normalizedType
    && (!isThoughtLike || isDesktopUserVisibleReasoningTraceEntry(last) === isUserVisibleThought)) {
    last.text = `${last.text || ''}${content}`;
    if (extra && typeof extra === 'object') last.extra = { ...(last.extra || {}), ...extra };
    return;
  }
  const trimmed = content.trim();
  if (!trimmed) return;
  if (last && last.type === normalizedType
    && (!isThoughtLike || isDesktopUserVisibleReasoningTraceEntry(last) === isUserVisibleThought)
    && String(last.text || '').trim() === trimmed) return;
  streamState.liveTraceEntries.push({
    id: `trace_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    type: normalizedType,
    text: trimmed,
    ts: new Date().toLocaleTimeString(),
    ...(extra && typeof extra === 'object' ? { extra } : {}),
  });
}

function isDesktopProgressNarration(value) {
  const text = normalizeLiveTraceProseText(value).replace(/\s+/g, ' ').trim();
  return /^(?:Clarifying|Explaining|Confirming|Summarizing|Planning|Deciding|Inspecting|Preparing|Starting|Activating|Focusing|Prioritizing|Assessing|Attempting|Identifying|Verifying|Loading|Running|Capturing|Opening|Closing|Reading|Writing|Checking|Reviewing|Collecting|Invoking|Calling|Using|Searching|Coordinating|Waiting|Listing|Retrieving|Inferring|Implementing|Investigating|Exploring)\b/i.test(text);
}

function setDesktopLiveProgressNarration(streamState, text, appendTrace, { replace = false, visibility = 'summary' } = {}) {
  if (!streamState) return false;
  const incoming = String(text || '');
  if (!incoming) return false;
  if (!Array.isArray(streamState.liveTraceEntries)) streamState.liveTraceEntries = [];
  const existing = [...streamState.liveTraceEntries].reverse().find((entry) =>
    String(entry?.extra?.source || '').toLowerCase() === 'agent_progress'
  );
  if (!existing) {
    appendTrace('think', incoming, { extra: { visibility, source: 'agent_progress', reasoningKind: 'summary' } });
    return true;
  }
  const previous = String(existing.text || '').trim();
  const next = incoming.trim();
  if (!next) return false;
  // Providers send both snapshots and token deltas on this channel. Treat a
  // growing snapshot as replacement, otherwise append only when the previous
  // sentence can safely continue. That keeps one mutable progress slot instead
  // of leaving every transport packet behind in the tool timeline.
  const isSnapshot = next.length > previous.length && next.startsWith(previous);
  const canAppend = !replace
    && !isSnapshot
    && previous
    && !/[.!?:]\s*$/.test(previous)
    && (/^\s/.test(incoming) || /^[a-z0-9,'"‘’“”\-—.;:!?)}\]]/.test(next));
  const merged = canAppend
    ? dedupeDesktopTraceProseText(appendFinalResponseDelta(previous, incoming))
    : normalizeLiveTraceProseText(next);
  const latest = canAppend
    ? (merged.split(/\n\s*\n/).map((part) => part.trim()).filter(Boolean).pop() || merged)
    : merged;
  if (!latest) return false;
  const visibilityChanged = String(existing?.extra?.visibility || '') !== visibility;
  if (latest === String(existing.text || '').trim()) {
    if (visibilityChanged) existing.extra = { ...(existing.extra || {}), visibility, source: 'agent_progress', reasoningKind: 'summary' };
    return visibilityChanged;
  }
  existing.text = latest;
  existing.ts = new Date().toLocaleTimeString();
  existing.extra = { ...(existing.extra || {}), visibility, source: 'agent_progress', reasoningKind: 'summary' };
  return true;
}

function shouldAppendDesktopReasoningSummary(streamState, chunk) {
  const incoming = String(chunk || '');
  if (!streamState || !incoming) return false;
  const last = [...(Array.isArray(streamState.liveTraceEntries) ? streamState.liveTraceEntries : [])]
    .reverse()
    .find((entry) => String(entry?.extra?.source || '').toLowerCase() === 'reasoning_summary');
  if (!last) return false;
  const previous = String(last.text || '').trim();
  const next = incoming.trimStart();
  if (!previous || !next || /[.!?:]\s*$/.test(previous)) return false;
  return /^\s/.test(incoming) || /^[a-z0-9,.;:)}\]]/.test(next);
}

function appendDesktopReasoningSummary(streamState, chunk, appendTrace) {
  appendTrace('think', chunk, {
    append: shouldAppendDesktopReasoningSummary(streamState, chunk),
    extra: { visibility: 'user', source: 'reasoning_summary', reasoningKind: 'summary' },
  });
}

function applyToolActivityToStreamState(streamState, phase, payload = {}) {
  if (!streamState) return null;
  if (!Array.isArray(streamState.liveTraceEntries)) streamState.liveTraceEntries = [];
  return applyToolActivityEvent(streamState.liveTraceEntries, phase, payload);
}

function inspectStreamingVisualFences(text) {
  const source = String(text || '');
  const completed = [...source.matchAll(/```(chart|svg|html|mermaid)\s*\r?\n[\s\S]*?```/gi)]
    .map((match) => String(match[1] || '').toLowerCase());
  const openRe = /```(chart|svg|html|mermaid)\s*\r?\n/gi;
  let lastOpen = null;
  for (const match of source.matchAll(openRe)) lastOpen = match;
  let pending = null;
  if (lastOpen && Number.isFinite(lastOpen.index)) {
    const bodyStart = Number(lastOpen.index) + String(lastOpen[0] || '').length;
    if (source.indexOf('```', bodyStart) < 0) {
      pending = {
        renderer: String(lastOpen[1] || '').toLowerCase(),
        ordinal: completed.length,
      };
    }
  }
  return { completed, pending };
}

function syncStreamingVisualActivity(streamState, text, applyActivity, { finalize = false } = {}) {
  if (!streamState || typeof applyActivity !== 'function') return;
  const inspection = inspectStreamingVisualFences(text);
  const completeCount = inspection.completed.length;
  const active = streamState.visualGeneration;
  const finish = (generation) => {
    if (!generation) return;
    applyActivity('result', {
      action: 'present_visual',
      callId: generation.callId,
      args: { renderer: generation.renderer, ordinal: generation.ordinal },
      result: 'Rendered interactive visual.',
      ok: true,
      extra: { presentation: 'interactive_visual', renderer: generation.renderer },
    });
    streamState.visualCompletedCount = Math.max(Number(streamState.visualCompletedCount || 0), generation.ordinal + 1);
  };

  if (inspection.pending) {
    if (active && (active.ordinal !== inspection.pending.ordinal || active.renderer !== inspection.pending.renderer)) {
      if (completeCount > active.ordinal) finish(active);
      streamState.visualGeneration = null;
    }
    if (!streamState.visualGeneration) {
      const generation = {
        callId: `stream_visual_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        renderer: inspection.pending.renderer,
        ordinal: inspection.pending.ordinal,
      };
      applyActivity('call', {
        action: 'present_visual',
        callId: generation.callId,
        args: { renderer: generation.renderer, ordinal: generation.ordinal },
        extra: { presentation: 'interactive_visual', renderer: generation.renderer },
      });
      streamState.visualGeneration = generation;
    }
    return;
  }

  if (active && completeCount > active.ordinal) {
    finish(active);
    streamState.visualGeneration = null;
  }

  if (finalize) {
    let completedCount = Math.min(completeCount, Math.max(0, Number(streamState.visualCompletedCount || 0)));
    while (completedCount < completeCount) {
      const renderer = inspection.completed[completedCount] || 'interactive';
      const generation = {
        callId: `stream_visual_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        renderer,
        ordinal: completedCount,
      };
      applyActivity('call', {
        action: 'present_visual',
        callId: generation.callId,
        args: { renderer, ordinal: completedCount },
        extra: { presentation: 'interactive_visual', renderer },
      });
      finish(generation);
      completedCount += 1;
    }
    streamState.visualCompletedCount = completedCount;
  }
}

function desktopCommandActivityCollections(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return [];
  const collections = [];
  const add = (entries) => {
    if (Array.isArray(entries) && !collections.includes(entries)) collections.push(entries);
  };
  add(getSessionStreamState(sid)?.liveTraceEntries);
  const session = getChatSessionById(sid);
  for (const message of Array.isArray(session?.history) ? session.history : []) {
    add(message?.liveTraceEntries);
    add(message?.metadata?.liveTraceEntries);
  }
  return collections;
}

function handleDesktopInlineCommandProcessEvent(eventType, message = {}, attempt = 0) {
  const run = message.run && typeof message.run === 'object' ? message.run : {};
  const sessionId = String(run.sessionId || message.sessionId || '').trim();
  const runId = String(run.runId || message.runId || '').trim();
  if (!sessionId || !runId) return;
  if (eventType === 'process_run_exited') setToolActivityDisclosureState(`terminal:${runId}`, false);
  let applied = false;
  for (const entries of desktopCommandActivityCollections(sessionId)) {
    if (applyCommandProcessEvent(entries, eventType, message)) applied = true;
  }
  if (!applied && attempt < 12) {
    setTimeout(() => handleDesktopInlineCommandProcessEvent(eventType, message, attempt + 1), 40 + attempt * 20);
    return;
  }
  if (eventType === 'process_run_output') {
    appendCommandTerminalChunkToDom(runId, message.chunk, message.sequence || run.outputSeq);
    return;
  }
  if (applied && window.activeChatSessionId === sessionId) renderChatMessages();
}

['process_run_started', 'process_run_update', 'process_run_exited'].forEach((eventType) => {
  wsEventBus.on(eventType, (message = {}) => handleDesktopInlineCommandProcessEvent(eventType, message));
});
wsEventBus.on('process_run_output', (message = {}) => handleDesktopInlineCommandProcessEvent('process_run_output', message));

document.addEventListener('toggle', async (event) => {
  const terminal = event.target?.closest?.('.tool-command-terminal.is-complete');
  if (!terminal?.open || terminal.dataset.logLoaded === '1' || terminal.dataset.logLoading === '1') return;
  const runId = String(terminal.dataset.commandRunId || '').trim();
  if (!runId) return;
  terminal.dataset.logLoading = '1';
  try {
    const log = await api(`/api/processes/${encodeURIComponent(runId)}/log`);
    const output = terminal.querySelector('[data-command-terminal-output]');
    if (output) output.textContent = String(log?.combined || '(no output)');
    terminal.dataset.logLoaded = '1';
  } catch {
    const output = terminal.querySelector('[data-command-terminal-output]');
    if (output && /Open to load output/.test(output.textContent || '')) output.textContent = 'Could not load terminal output.';
  } finally {
    delete terminal.dataset.logLoading;
  }
}, true);

async function refreshSessionFromServer(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  const sess = getChatSessionById(sid);
  if (!sess) return;
  sess._needsServerLoad = true;
  await _loadSessionFromServer(sid, { force: true });
  if (sid === window.activeChatSessionId) syncActiveChat();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
}

function shouldProcessMainChatStreamEvent(msg = {}) {
  const sid = String(msg.sessionId || '').trim();
  const seq = Number(msg.seq);
  if (!sid || !Number.isFinite(seq)) return true;
  const key = String(msg.streamId || 'default');
  const map = window._mainChatStreamLastSeqBySession || (window._mainChatStreamLastSeqBySession = {});
  const prev = map[sid] && typeof map[sid] === 'object' ? map[sid] : {};
  const last = Number(prev[key] || -1);
  if (seq <= last) return false;
  prev[key] = seq;
  map[sid] = prev;
  if (key !== 'default') {
    const activeMap = window._mainChatStreamActiveIdBySession || (window._mainChatStreamActiveIdBySession = {});
    activeMap[sid] = key;
  }
  return true;
}

function resetMainChatStreamCursor(sessionId, streamId = '') {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  const key = String(streamId || '').trim();
  const map = window._mainChatStreamLastSeqBySession || (window._mainChatStreamLastSeqBySession = {});
  if (!key) {
    delete map[sid];
    delete window._mainChatStreamActiveIdBySession?.[sid];
    return;
  }
  if (map[sid] && typeof map[sid] === 'object') delete map[sid][key];
  if (window._mainChatStreamActiveIdBySession?.[sid] === key) delete window._mainChatStreamActiveIdBySession[sid];
}

function getMainChatStreamLastSeq(sessionId, streamId = 'default') {
  const sid = String(sessionId || '').trim();
  if (!sid) return 0;
  const key = String(streamId || 'default');
  const map = window._mainChatStreamLastSeqBySession || {};
  const prev = map[sid] && typeof map[sid] === 'object' ? map[sid] : {};
  const activeStreamId = String(window._mainChatStreamActiveIdBySession?.[sid] || '').trim();
  const resolvedKey = key === 'default' && activeStreamId ? activeStreamId : key;
  if (resolvedKey === 'default') {
    const max = Object.values(prev).reduce((best, item) => {
      const n = Number(item || 0);
      return Number.isFinite(n) && n > best ? n : best;
    }, 0);
    return max;
  }
  const value = Number(prev[resolvedKey] || 0);
  return Number.isFinite(value) && value > 0 ? value : 0;
}

const MAIN_CHAT_STREAM_CATCHUP_INTERVAL_MS = 3200;
const MAIN_CHAT_STREAM_TOOL_RESULT_SUMMARY_MAX = 420;

function _isMainChatStreamCatchupSessionVisible(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return false;
  if (sid !== String(window.activeChatSessionId || '').trim()) return false;
  // Mobile PWA/WebView often reports document.hidden while the user is still in chat;
  // keep HTTP catch-up alive for the active session on the mobile shell.
  if (typeof document !== 'undefined' && document.body?.classList?.contains('pm-mobile-active')) return true;
  return typeof document === 'undefined' || document.hidden !== true;
}

function summarizeToolResultForBackgroundSession(value, action = '') {
  const summaryMax = MAIN_CHAT_STREAM_TOOL_RESULT_SUMMARY_MAX;
  const normalizedAction = String(action || '').trim();
  const raw = String(value || '').trim();
  if (!raw) return '[tool result empty]';
  if (raw.length <= summaryMax) return raw;
  const actionPrefix = normalizedAction ? `[${normalizedAction}] ` : '';
  return `${actionPrefix}${raw.slice(0, summaryMax)}… (${raw.length - summaryMax} chars truncated in background stream)`;
}

function applyMainChatStreamFrame(sessionId, frame, options = {}) {
  if (!frame || typeof frame !== 'object') return;
  handleMainChatStreamEvent({
    sessionId,
    streamId: frame.streamId,
    seq: frame.seq,
    event: frame.type || frame.event,
    at: frame.at,
    data: frame.data || {},
  }, options);
}

async function catchUpMainChatStream(sessionId, options = {}) {
  const sid = String(sessionId || '').trim();
  if (!sid) return null;
  if (!_isMainChatStreamCatchupSessionVisible(sid)) return null;
  try {
    if (options.fullRefresh === true) {
      await _loadSessionFromServer(sid, {
        force: true,
        historyLimit: 300,
        processLimit: 500,
        recovery: true,
        fullProcess: true,
      });
    }
    const rememberedRun = readDesktopActiveChatRun(sid);
    const knownStreamId = String(
      options.streamId
        || rememberedRun?.streamId
        || window._mainChatStreamActiveIdBySession?.[sid]
        || '',
    ).trim();
    const explicitAfter = Number(options.after);
    let after = Number.isFinite(explicitAfter)
      ? Math.max(0, Math.floor(explicitAfter))
      : knownStreamId
        ? Math.max(getMainChatStreamLastSeq(sid, knownStreamId), Number(rememberedRun?.lastSeq || 0) || 0)
        : (options.recovery === true ? 0 : getMainChatStreamLastSeq(sid));
    let data = await fetchJsonWithTimeout(`/api/mobile/chat/stream/${encodeURIComponent(sid)}?after=${encodeURIComponent(String(after))}`, 4000);
    if (!data) return null;

    let streamId = String(data?.stream?.streamId || data?.events?.[0]?.streamId || '').trim();
    const firstSeq = Number(data?.stream?.firstSeq || 0) || 0;
    const streamChanged = !!knownStreamId && !!streamId && streamId !== knownStreamId;
    const retentionGap = after > 0 && firstSeq > after + 1;
    if ((streamChanged || retentionGap) && after > 0) {
      resetMainChatStreamCursor(sid, streamId || knownStreamId);
      after = 0;
      data = await fetchJsonWithTimeout(`/api/mobile/chat/stream/${encodeURIComponent(sid)}?after=0`, 4000);
      if (!data) return null;
      streamId = String(data?.stream?.streamId || data?.events?.[0]?.streamId || streamId || '').trim();
    }
    if (streamId) {
      window._mainChatStreamActiveIdBySession[sid] = streamId;
      if (after === 0 && (options.recovery === true || streamChanged || retentionGap)) {
        resetMainChatStreamCursor(sid, streamId);
        window._mainChatStreamActiveIdBySession[sid] = streamId;
      }
    }

    const sess = getChatSessionById(sid);
    if (data.active === true) {
      if (sess) sess.activeRun = true;
      window._sessionThinking[sid] = true;
      const streamState = getSessionStreamState(sid) || resetSessionStreamState(sid);
      streamState.currentTurnStartIndex = Number.isInteger(streamState.currentTurnStartIndex) && streamState.currentTurnStartIndex >= 0
        ? streamState.currentTurnStartIndex
        : inferCurrentTurnProcessStartIndex(sess);
      streamState.turnStartedAt = Number(streamState.turnStartedAt || getSessionLastMessageAt(sess) || Date.now());
      rememberDesktopActiveChatRun(sid, {
        streamId: streamId || rememberedRun?.streamId || '',
        runtimeId: String(data?.run?.id || data?.run?.runtimeId || rememberedRun?.runtimeId || '').trim(),
        clientRequestId: String(data?.run?.clientRequestId || rememberedRun?.clientRequestId || '').trim(),
        disconnected: false,
      });
    }

    const events = Array.isArray(data?.events) ? data.events : [];
    events.forEach((frame) => applyMainChatStreamFrame(sid, frame, { recovery: options.recovery === true }));
    const lastSeq = Number(data?.stream?.lastSeq || 0) || 0;
    if (streamId && lastSeq > 0) {
      rememberDesktopActiveChatRun(sid, { streamId, lastSeq });
    }

    if (data?.active && _isMainChatStreamCatchupSessionVisible(sid)) scheduleMainChatStreamCatchup(sid);
    if (data && data.active === false && (options.recovery === true || options.fullRefresh === true || events.some((frame) => ['done', 'error'].includes(String(frame?.type || frame?.event || ''))))) {
      if (sess?.activeRun === true || window._sessionThinking?.[sid] || readDesktopActiveChatRun(sid)) {
        clearLiveTurnStateForSession(sid);
      } else {
        clearDesktopActiveChatRun(sid);
      }
    }
    return data;
  } catch {
    return null;
  }
}

function scheduleMainChatStreamCatchup(sessionId) {
  const sid = String(sessionId || '').trim();
  if (!sid) return;
  if (!_isMainChatStreamCatchupSessionVisible(sid)) return;
  const timers = window._mainChatStreamCatchupTimers || (window._mainChatStreamCatchupTimers = {});
  if (timers[sid]) return;
  timers[sid] = setTimeout(async () => {
    delete timers[sid];
    if (!_isMainChatStreamCatchupSessionVisible(sid)) return;
    const data = await catchUpMainChatStream(sid);
    if (data?.active && _isMainChatStreamCatchupSessionVisible(sid)) scheduleMainChatStreamCatchup(sid);
  }, MAIN_CHAT_STREAM_CATCHUP_INTERVAL_MS);
}

async function recoverDesktopMainChatSession(sessionId, options = {}) {
  const sid = String(sessionId || '').trim();
  if (!sid || _isMobileShellActive() || !_isMainChatStreamCatchupSessionVisible(sid)) return null;
  const inFlight = window._desktopMainChatRecoveryInFlight || (window._desktopMainChatRecoveryInFlight = {});
  if (inFlight[sid]) return inFlight[sid];
  const promise = catchUpMainChatStream(sid, {
    ...options,
    recovery: true,
  });
  inFlight[sid] = promise;
  try {
    return await promise;
  } finally {
    if (inFlight[sid] === promise) delete inFlight[sid];
  }
}

function scheduleDesktopMainChatRecovery(sessionId, options = {}) {
  const sid = String(sessionId || '').trim();
  if (!sid || _isMobileShellActive() || !_isMainChatStreamCatchupSessionVisible(sid)) return;
  const timers = window._desktopMainChatRecoveryTimers || (window._desktopMainChatRecoveryTimers = {});
  const pending = window._desktopMainChatRecoveryPending || (window._desktopMainChatRecoveryPending = {});
  pending[sid] = { ...(pending[sid] || {}), ...options };
  const delayMs = Math.max(0, Math.min(5000, Number(options.delayMs ?? 220) || 0));
  if (timers[sid]) {
    if (options.force !== true) return;
    clearTimeout(timers[sid]);
    delete timers[sid];
  }
  timers[sid] = setTimeout(async () => {
    delete timers[sid];
    const nextOptions = pending[sid] || {};
    delete pending[sid];
    const data = await recoverDesktopMainChatSession(sid, nextOptions).catch(() => null);
    if (data?.active && _isMainChatStreamCatchupSessionVisible(sid)) scheduleDesktopMainChatRecovery(sid, { recovery: true, delayMs: MAIN_CHAT_STREAM_CATCHUP_INTERVAL_MS });
  }, delayMs);
}

function scheduleDesktopMainChatRecoveryOnResume(options = {}) {
  if (_isMobileShellActive()) return;
  const sid = String(window.activeChatSessionId || '').trim();
  if (!sid) return;
  scheduleDesktopMainChatRecovery(sid, {
    recovery: true,
    fullRefresh: options.fullRefresh !== false,
    force: options.force === true,
    delayMs: options.delayMs ?? 140,
  });
}

if (typeof window !== 'undefined') {
  window.addEventListener('pagehide', () => {
    if (_isMobileShellActive()) return;
    const sid = String(window.activeChatSessionId || '').trim();
    if (!sid || !window._sessionThinking?.[sid]) return;
    window._desktopPageLifecycleDisconnectedSessions[sid] = true;
    rememberDesktopActiveChatRun(sid, { disconnected: true, forcePersist: true });
  });
  window.addEventListener('pageshow', () => scheduleDesktopMainChatRecoveryOnResume({ force: true }));
  window.addEventListener('focus', () => scheduleDesktopMainChatRecoveryOnResume());
  window.addEventListener('online', () => scheduleDesktopMainChatRecoveryOnResume({ force: true }));
  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', () => {
      if (!document.hidden) scheduleDesktopMainChatRecoveryOnResume({ force: true });
    });
  }
}

// ─── Cross-channel live update helpers ────────────────────────────────────────

async function _wsReconnectCatchUp() {
  // Refresh session list from server to pick up sessions from other channels
  try {
    const data = await fetchJsonWithTimeout('/api/sessions', 2500);
    if (data) {
      const svr = Array.isArray(data.sessions) ? data.sessions : [];
      if (svr.length > 0) {
        mergeServerSessionSummaries(svr);
        if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
      }
    }
  } catch {}
  // Catch up on stream events for the active session that arrived while disconnected
  if (window.activeChatSessionId) {
    if (_isMobileShellActive()) {
      try {
        await _loadSessionFromServer(window.activeChatSessionId, { force: true });
        syncActiveChat();
      } catch {}
      catchUpMainChatStream(window.activeChatSessionId).catch(() => {});
    } else {
      recoverDesktopMainChatSession(window.activeChatSessionId, { recovery: true, fullRefresh: true, force: true }).catch(() => {});
    }
  }
}

function _isDesktopIdle() {
  if (window.isThinking) return false;
  if (window._sessionAbortControllers?.[window.activeChatSessionId]) return false;
  const input = document.getElementById('chat-input');
  if (input && String(input.value || '').trim().length > 0) return false;
  return true;
}

function _isExternalChannel(sid) {
  return ['telegram', 'mobile', 'discord', 'whatsapp', 'terminal'].includes(inferChannelFromSessionId(sid));
}

function _isMobileShellActive() {
  return document.body?.classList?.contains('pm-mobile-active') === true;
}

function _showChannelActivityToast(sid, channelLabel, preview, options = {}) {
  if (_isMobileShellActive()) return;
  const state = ['live', 'complete', 'failed'].includes(String(options.state || 'live'))
    ? String(options.state || 'live')
    : 'live';
  const title = String(options.title || (state === 'live'
    ? `Live on ${channelLabel}`
    : state === 'failed'
      ? `${channelLabel} needs attention`
      : `${channelLabel} completed`));
  const existingForSession = [...document.querySelectorAll('.__channel-activity-toast')]
    .find((node) => String(node.getAttribute('data-channel-sid') || '') === String(sid || ''));
  existingForSession?.remove();
  const toast = document.createElement('div');
  let autoDismissTimer = null;
  const dismissToast = () => {
    if (autoDismissTimer) {
      clearTimeout(autoDismissTimer);
      autoDismissTimer = null;
    }
    if (!toast.isConnected) return;
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => toast.remove(), 300);
  };
  toast.className = `__sc-toast __sc-toast--activity-${state} __channel-activity-toast`;
  const existing = document.querySelectorAll('.__sc-toast');
  const offset = 24 + [...existing].reduce((sum, t) => sum + t.offsetHeight + 8, 0);
  toast.style.cssText = `position:fixed;bottom:${offset}px;right:24px;z-index:99999;`;
  toast.setAttribute('data-channel-sid', sid);
  toast.innerHTML = `
    <span class="__sc-toast-icon" aria-hidden="true">${state === 'live' ? '◌' : state === 'failed' ? '!' : '✓'}</span>
    <div class="__sc-toast-copy">
      <div class="__sc-toast-title">${escHtml(title)}</div>
      ${preview ? `<div class="__sc-toast-body">${escHtml(String(preview).slice(0, 180))}</div>` : ''}
      <button class="__sc-toast-action __channel-switch-btn" type="button">${state === 'live' ? 'View live' : 'Open update'} →</button>
    </div>
    <button class="__sc-toast-close" type="button" aria-label="Dismiss">&times;</button>
  `;
  toast.querySelector('.__channel-switch-btn').addEventListener('click', () => {
    _switchToChannelSession(sid);
    dismissToast();
  });
  toast.querySelector('.__sc-toast-close')?.addEventListener('click', dismissToast);
  document.body.appendChild(toast);
  autoDismissTimer = setTimeout(dismissToast, state === 'failed' ? 16000 : 12000);
}

function _switchToChannelSession(sid) {
  const sess = getChatSessionById(sid);
  if (!sess) return;
  window.activeChatSessionId = sid;
  setAgentSessionId(sid);
  saveChatSessions();
  syncActiveChat();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  renderChatMessages();
  if (chatResourcesState.open) loadChatResources({ sessionId: sid });
  recoverDesktopMainChatSession(sid, { recovery: true, fullRefresh: false }).catch(() => {});
}
window._switchToChannelSession = _switchToChannelSession;

function handleMainChatStreamEvent(msg = {}, options = {}) {
  const sid = String(msg.sessionId || '').trim();
  if (!sid) return;
  const activeBeforeStreamEvent = window.activeChatSessionId;
  // Locally-started desktop turns are already handled by the /api/chat SSE reader.
  // The websocket bridge is for other live surfaces: Telegram, mobile, CLI, and
  // any channel turn this desktop tab is observing rather than owning.
  const clientRequestId = String(msg?.data?.clientRequestId || msg?.clientRequestId || '').trim();
  const isRecoveryReplay = options.recovery === true;
  if (!isRecoveryReplay && (isLocalMainChatRequest(sid, clientRequestId) || window._sessionAbortControllers?.[sid])) return;
  if (!shouldProcessMainChatStreamEvent(msg)) return;
  const evt = { type: String(msg.event || ''), ...(msg.data || {}) };
  const sess = ensureChannelChatSession(sid, { source: evt?.message?.channel || evt?.origin?.channel });
  if (!sess) return;
  if (evt.type !== 'done' && evt.type !== 'error') sess.activeRun = true;
  const streamState = getSessionStreamState(sid) || resetSessionStreamState(sid);
  const isViewing = sid === window.activeChatSessionId;
  const renderIfViewing = () => {
    if (!isViewing) return;
    applyStreamStateToWindow(sid);
    syncActiveSessionRunState();
    renderProgressPanel();
    renderStreamingChatUpdate(sid);
  };
  const moveVisibleAnswerTextIntoWorkflowTrace = () => {
    const text = String(streamState.streamingAIText || '').trim();
    if (!text) return;
    const appendTrace = (type, content, options) => appendLiveTraceToStreamState(streamState, type, content, options);
    if (isDesktopProgressNarration(text)) {
      setDesktopLiveProgressNarration(streamState, text, appendTrace);
    } else {
      appendTrace(streamState.toolActivityStarted ? 'think' : 'preamble', text, {
        extra: { visibility: 'user', source: 'reasoning_summary' },
      });
    }
    streamState.streamingAIText = '';
    streamState.finalResponseStarted = false;
  };
  const movePreToolAnswerTextIntoPreamble = moveVisibleAnswerTextIntoWorkflowTrace;
  const shouldRouteTokenToLiveTrace = () => {
    return false;
  };

  if (evt.type === 'session_title') {
    applyServerSessionTitle(sid, evt.title);
    renderIfViewing();
  } else if (evt.type === 'user_message') {
    const raw = evt.message && typeof evt.message === 'object' ? evt.message : {};
    const content = String(raw.content || evt.content || '').trim();
    const channelLabel = raw.channelLabel || raw.channel || inferChannelFromSessionId(sid);
    const isInternalWatchUserMessage = String(channelLabel || '').toLowerCase() === 'internal_watch'
      || /^\[Internal watch\b/i.test(content);
    if (content && !isInternalWatchUserMessage) {
      const next = {
        role: 'user',
        content,
        timestamp: Number(raw.timestamp || Date.now()),
        channel: inferChannelFromSessionId(sid, raw.channel),
        channelLabel,
        origin: raw.origin && typeof raw.origin === 'object' ? raw.origin : undefined,
        attachmentPreviews: Array.isArray(raw.attachmentPreviews)
          ? raw.attachmentPreviews.map(sanitizeAttachmentPreviewForDurableStorage)
          : undefined,
      };
      const last = sess.history[sess.history.length - 1];
      let appended = false;
      if (!last || String(last.role || '') !== 'user' || String(last.content || '') !== content) {
        sess.history.push(next);
        appended = true;
      }
      const origin = next.origin && typeof next.origin === 'object' ? next.origin : null;
      if (origin?.channel) {
        sess.lastOrigin = {
          channel: String(origin.channel),
          surface: String(origin.surface || '').trim() || undefined,
          device: String(origin.device || '').trim() || undefined,
          label: String(origin.label || '').trim() || undefined,
        };
      }
      applyAutoSessionTitleOnce(sess, sess.history);
      if (appended) addSessionProcessEntry(sid, 'user', content, { actor: next.channelLabel || next.channel || 'Channel' });
    }
    window._sessionThinking[sid] = true;
    streamState.currentTurnStartIndex = inferCurrentTurnProcessStartIndex(sess, content);
    streamState.turnStartedAt = Number(streamState.turnStartedAt || Date.now());
    if (!isViewing && _isExternalChannel(sid) && !_isMobileShellActive()) {
      const chLabel = sess.source || inferChannelFromSessionId(sid);
      const capturedContent = content;
      const toastMessage = capturedContent ? capturedContent.slice(0, 80) : 'New activity.';
      if (_isDesktopIdle() && !isViewing) {
        _showChannelActivityToast(sid, chLabel, toastMessage);
      } else {
        _showChannelActivityToast(sid, chLabel, content);
      }
    }
    renderIfViewing();
  } else if (evt.type === 'final_response_start') {
    beginFinalResponse(streamState);
    _settlePendingChatSteerPresentation(sid, streamState);
    scheduleStreamingRenderFor(sid, renderIfViewing);
  } else if (evt.type === 'token') {
    const chunk = String(evt.text || '');
    if (chunk) {
      window._sessionThinking[sid] = true;
      streamState.turnStartedAt = Number(streamState.turnStartedAt || Date.now());
      beginFinalResponse(streamState);
      _settlePendingChatSteerPresentation(sid, streamState);
      streamState.streamingAIText = appendFinalResponseDelta(streamState.streamingAIText, chunk);
      syncStreamingVisualActivity(streamState, streamState.streamingAIText, (phase, payload) =>
        applyToolActivityToStreamState(streamState, phase, payload)
      );
      scheduleStreamingRenderFor(sid, renderIfViewing);
    }
  } else if (evt.type === 'agent_mode') {
    streamState.agentExecutionMode = String(evt.mode || streamState.agentExecutionMode || '').trim();
    if (streamState.agentExecutionMode === 'execute') movePreToolAnswerTextIntoPreamble();
    if (evt.mode) addSessionProcessEntry(sid, 'info', `Agent mode: ${evt.mode}${evt.turnKind ? ` (${evt.turnKind})` : ''}`);
    renderIfViewing();
  } else if (evt.type === 'reasoning_summary_delta') {
    const chunk = String(evt.text || evt.summary || '');
    if (chunk) {
      window._sessionThinking[sid] = true;
      const appendTrace = (type, text, options) => appendLiveTraceToStreamState(streamState, type, text, options);
      // reasoning_summary is already an explicit user-safe progress channel.\n              // Treat every transport delta as part of the single replaceable status slot;\n              // classifying individual chunks leaks markdown/token boundaries into the UI.\n              setDesktopLiveProgressNarration(streamState, chunk, appendTrace);
      scheduleStreamingRenderFor(sid, renderIfViewing);
    }
  } else if (evt.type === 'thinking_delta') {
    const chunk = String(evt.thinking || evt.text || '');
    if (chunk) {
      window._sessionThinking[sid] = true;
      streamState.turnStartedAt = Number(streamState.turnStartedAt || Date.now());
      streamState.streamingThinkingText = (streamState.streamingThinkingText || '') + chunk;
      if (String(evt.source || '').toLowerCase() === 'reasoning_summary') {
        const appendTrace = (type, text, options) => appendLiveTraceToStreamState(streamState, type, text, options);
        // reasoning_summary is already an explicit user-safe progress channel.\n              // Treat every transport delta as part of the single replaceable status slot;\n              // classifying individual chunks leaks markdown/token boundaries into the UI.\n              setDesktopLiveProgressNarration(streamState, chunk, appendTrace);
      }
      scheduleStreamingRenderFor(sid, renderIfViewing);
    }
  } else if (evt.type === 'thinking' || evt.type === 'agent_thought') {
    const text = String(evt.thinking || evt.text || '').trim();
    const visibility = chatProgressVisibility(evt);
    if (text && visibility !== 'private') {
      setDesktopLiveProgressNarration(
        streamState,
        text,
        (type, content, options) => appendLiveTraceToStreamState(streamState, type, content, options),
        { replace: true, visibility },
      );
      renderIfViewing();
    }
  } else if (evt.type === 'model_stream_event') {
    const modelEvent = evt.event && typeof evt.event === 'object' ? evt.event : {};
    const modelType = String(modelEvent.type || '').trim();
    if (modelType === 'tool_call_start' || modelType === 'tool_call_done') {
      movePreToolAnswerTextIntoPreamble();
      streamState.toolActivityStarted = true;
      applyToolActivityToStreamState(streamState, modelType === 'tool_call_start' ? 'prepare' : 'prepared', {
        ...modelEvent,
        action: modelEvent.name,
      });
      renderIfViewing();
    }
  } else if (evt.type === 'ui_preflight' || evt.type === 'info') {
    const text = String(evt.message || '').trim();
    if (text) {
      streamState.currentPreflightStatus = text;
      streamState.currentProgressLines = Array.isArray(streamState.currentProgressLines) ? streamState.currentProgressLines : [];
      const last = streamState.currentProgressLines[streamState.currentProgressLines.length - 1];
      if (last !== text) streamState.currentProgressLines.push(text);
      if (streamState.currentProgressLines.length > 8) streamState.currentProgressLines = streamState.currentProgressLines.slice(-8);
      addSessionProcessEntry(sid, 'info', text, evt.actor ? { actor: evt.actor } : undefined);
      renderIfViewing();
    }
  } else if (evt.type === 'tool_call') {
    const action = String(evt.action || '').trim();
    if (action) {
      movePreToolAnswerTextIntoPreamble();
      streamState.toolActivityStarted = true;
      const args = evt.args && typeof evt.args === 'object' ? evt.args : {};
      const text = formatToolCallForLog(action, args, streamState);
      addSessionProcessEntry(sid, action.startsWith('skill_') ? 'skill' : 'tool', text, { action, args, ...args, ...(evt.actor ? { actor: evt.actor } : {}) });
      applyToolActivityToStreamState(streamState, 'call', evt);
      renderIfViewing();
    }
  } else if (evt.type === 'tool_result') {
    movePreToolAnswerTextIntoPreamble();
    streamState.toolActivityStarted = true;
    const action = String(evt.action || '').trim();
    const resultText = String(evt.result || '');
    const isBackgroundSession = sid !== window.activeChatSessionId;
    const safeResultText = isBackgroundSession
      ? summarizeToolResultForBackgroundSession(resultText, action)
      : resultText;
    const ok = evt.ok !== false && evt.success !== false && !evt.error;
    const text = action ? formatToolResultForLog(action, safeResultText, ok, streamState, evt.args || {}) : safeResultText;
    addSessionProcessEntry(sid, ok ? 'result' : 'error', text, { action, args: evt.args || {}, error: !ok, durationMs: evt.durationMs ?? evt.elapsedMs, ...(evt.actor ? { actor: evt.actor } : {}) });
    applyToolActivityToStreamState(streamState, 'result', evt);
    renderIfViewing();
  } else if (evt.type === 'tool_progress') {
    movePreToolAnswerTextIntoPreamble();
    streamState.toolActivityStarted = true;
    const action = String(evt.action || evt.name || '').trim();
    const message = String(evt.message || evt.progress || evt.status || '').trim();
    const ratio = Number.isFinite(Number(evt.ratio)) ? ` ${Math.round(Number(evt.ratio) * 100)}%` : '';
    const text = [action ? formatToolCallForLog(action, {}, streamState).replace(/\.\.\.$/, '') : 'Tool progress', message || ratio.trim()]
      .filter(Boolean)
      .join(': ');
    addSessionProcessEntry(sid, 'info', text, evt.actor ? { actor: evt.actor } : undefined);
    applyToolActivityToStreamState(streamState, 'progress', evt);
    renderIfViewing();
  } else if (evt.type === 'progress_state') {
    streamState.runtimeProgressState = normalizeDeclaredRuntimeProgressState({
      source: String(evt.source || 'none'),
      activeIndex: Number(evt.activeIndex || -1),
      items: Array.isArray(evt.items) ? evt.items.map((item, idx) => ({
        id: String(item.id || `p${idx + 1}`),
        text: String(item.text || '').slice(0, 120),
        status: String(item.status || 'pending'),
      })) : [],
    });
    sess.progressState = streamState.runtimeProgressState;
    renderIfViewing();
  } else if (evt.type === 'done') {
    _settlePendingChatSteerPresentation(sid, streamState);
    const reply = String(evt.reply || '');
    const content = reconcileFinalResponse(streamState.streamingAIText, reply);
    syncStreamingVisualActivity(streamState, content || streamState.streamingAIText, (phase, payload) =>
      applyToolActivityToStreamState(streamState, phase, payload),
    { finalize: true });
    if (content) {
      const workEndedAt = Number(evt.workEndedAt || 0) || Date.now();
      const workStartedAt = Number(evt.workStartedAt || streamState.turnStartedAt || 0) || workEndedAt;
      const last = sess.history[sess.history.length - 1];
      if (!last || !isAssistantLikeMessage(last) || String(last.content || '') !== content) {
        let lastUserTimestamp = 0;
        for (let i = sess.history.length - 1; i >= 0; i--) {
          if (String(sess.history[i]?.role || '') === 'user') {
            lastUserTimestamp = Number(sess.history[i]?.timestamp || 0) || 0;
            break;
          }
        }
        sess.history.push({
          role: 'ai',
          content,
          thinking: evt.thinking || streamState.streamingThinkingText || undefined,
          timestamp: lastUserTimestamp > 0 ? lastUserTimestamp + 1 : Date.now(),
          workStartedAt,
          workEndedAt,
          workDurationMs: Number.isFinite(Number(evt.workDurationMs))
            ? Math.max(0, Number(evt.workDurationMs))
            : Math.max(0, workEndedAt - workStartedAt),
          channel: inferChannelFromSessionId(sid),
          channelLabel: inferChannelFromSessionId(sid),
          artifacts: Array.isArray(evt.artifacts) && evt.artifacts.length ? evt.artifacts : undefined,
          generatedImages: Array.isArray(evt.generatedImages) && evt.generatedImages.length ? evt.generatedImages : undefined,
          generatedVideos: Array.isArray(evt.generatedVideos) && evt.generatedVideos.length ? evt.generatedVideos : undefined,
          canvasFiles: Array.isArray(evt.canvasFiles) && evt.canvasFiles.length ? evt.canvasFiles : undefined,
          fileChanges: evt.fileChanges || undefined,
          productCarousel: evt.productCarousel || undefined,
          richArtifacts: Array.isArray(evt.richArtifacts) && evt.richArtifacts.length ? evt.richArtifacts : undefined,
          goalCompletionReport: evt.goalCompletionReport || undefined,
          processEntries: mergeLiveTraceProcessEntries(streamState.liveTraceEntries, sess.processLog.slice(Number(streamState.currentTurnStartIndex || 0))),
        });
      }
      applyAutoSessionTitleOnce(sess, sess.history);
    }
    delete window._sessionThinking[sid];
    sess.activeRun = false;
    const desktopRun = readDesktopActiveChatRun(sid);
    if (!desktopRun?.clientRequestId || !clientRequestId || desktopRun.clientRequestId === clientRequestId) {
      clearDesktopActiveChatRun(sid);
    }
    window._sessionStreamState[sid] = makeEmptyStreamState();
    sess.unread = true;
    if (!isViewing && !_isMobileShellActive()) {
      _showChannelActivityToast(sid, sess.source || inferChannelFromSessionId(sid), content || 'Prometheus finished the response.', {
        state: 'complete',
        title: 'Response ready',
      });
    }
    setTimeout(() => refreshSessionFromServer(sid).catch(() => {}), 900);
    flushStreamingRenderFor(sid, renderIfViewing);
  } else if (evt.type === 'final') {
    const text = String(evt.text || evt.reply || '');
    if (text) {
      beginFinalResponse(streamState);
      _settlePendingChatSteerPresentation(sid, streamState);
      streamState.streamingAIText = reconcileFinalResponse(streamState.streamingAIText, text);
      syncStreamingVisualActivity(streamState, streamState.streamingAIText, (phase, payload) =>
        applyToolActivityToStreamState(streamState, phase, payload),
      { finalize: true });
      scheduleStreamingRenderFor(sid, renderIfViewing);
    }
  } else if (evt.type === 'error') {
    const text = String(evt.message || 'Unknown error').trim();
    addSessionProcessEntry(sid, 'error', text);
    delete window._sessionThinking[sid];
    sess.activeRun = false;
    const desktopRun = readDesktopActiveChatRun(sid);
    if (!desktopRun?.clientRequestId || !clientRequestId || desktopRun.clientRequestId === clientRequestId) {
      clearDesktopActiveChatRun(sid);
    }
    sess.unread = true;
    if (!isViewing && !_isMobileShellActive()) {
      _showChannelActivityToast(sid, sess.source || inferChannelFromSessionId(sid), text, {
        state: 'failed',
        title: 'Response needs attention',
      });
    }
    flushStreamingRenderFor(sid, renderIfViewing);
  }

  sess.updatedAt = Date.now();
  sess.lastMessageAt = getSessionLastMessageAt(sess);
  if (sid !== window.activeChatSessionId) sess.unread = true;
  window.chatSessions.sort((a, b) => getSessionLastMessageAt(b) - getSessionLastMessageAt(a));
  saveChatSessions();
  if (typeof window.renderSessionsList === 'function') window.renderSessionsList();
  refreshVisibleChannelsList();
  restoreActiveSessionIfStreamStoleFocus(activeBeforeStreamEvent, sid);
}

